INSERT INTO question VALUES('chem-5-3-19','chem','written',118,18,NULL,'Write a balanced equation for the reaction of ethene with steam and state the catalyst and reaction type.','C₂H₄(g) + H₂O(g) → CH₃CH₂OH(g); phosphoric acid (H₃PO₄) catalyst; addition reaction.','States are optional for the equation mark; the catalyst and reaction type must be given.',0,NULL,NULL,0,1,1.5,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
