INSERT INTO question VALUES('con-3','gcse-bio','written',470,2,NULL,'Give one advantage and one disadvantage of hormonal contraception compared with barrier methods.','Advantage: more effective; doesn''t interrupt sex. Disadvantage: no STI protection; possible side effects; must remember to take pill daily.','',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
