INSERT INTO question VALUES('cpa-3','gcse-bio','mcq',498,2,NULL,'Why use a water bath at a fixed temperature?',NULL,'Temperature affects enzyme activity, so must be kept constant.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('cpa-4','gcse-bio','written',498,3,NULL,'Describe how to time when starch is fully digested.','Put iodine drops on a spotting tile; every 10–30 s take a drop of the mixture and add to iodine; record when the iodine no longer turns blue-black.','',0,NULL,NULL,0,2,2.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
