INSERT INTO question VALUES('cpb-3','gcse-bio','mcq',502,2,NULL,'Area of a circular clear zone with radius 5 mm (π = 3.14)?',NULL,'πr² = 3.14 × 25 = 78.5 mm².',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('cpb-4','gcse-bio','written',502,3,NULL,'Give two aseptic techniques used when culturing bacteria.','Sterilise the inoculating loop in a flame; tape the lid (not fully sealed); flame the neck of bottles; open lids minimally; sterilise equipment in an autoclave.','',0,NULL,NULL,0,2,2.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('cpc-1','gcse-bio','mcq',501,0,NULL,'Energy per gram of food is calculated by:',NULL,'Divide energy transferred (J) by the mass of food burned (g).',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('cpc-2','gcse-bio','mcq',501,1,NULL,'To make the result more accurate you could:',NULL,'Less heat lost to the surroundings means a more accurate value.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
