INSERT INTO question VALUES('ene-1','gcse-bio','mcq',488,0,NULL,'Approximately what percentage of energy is passed to the next trophic level?',NULL,'About 10%. Most is lost through respiration, movement, heat, and undigested waste.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
