INSERT INTO question VALUES('ene-3','gcse-bio','mcq',488,2,NULL,'A producer stores 20 000 kJ and the primary consumer stores 2 000 kJ. Efficiency?',NULL,'2000 ÷ 20000 × 100 = 10%.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('ene-4','gcse-bio','written',488,3,NULL,'Give two reasons why energy is lost between trophic levels.','Respiration releases energy used for movement/heat; not all of the organism is eaten (bones, roots); some is egested as faeces; urea excreted.','',0,NULL,NULL,0,2,2.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
