INSERT INTO question VALUES('general-1-1-6','general','mcq',34,5,NULL,'A histogram of the number of hours worked per week by casual employees has a long tail extending to the right. The distribution is:',NULL,'A long tail to the right (towards higher values) indicates positive skew.',0,NULL,NULL,0,1,1.5,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
