INSERT INTO question VALUES('general-1-1-9','general','mcq',34,8,NULL,'A data value plotted at 2.5 on a log₁₀ scale is closest to:',NULL,'10^2.5 = 316.2..., so the actual value is approximately 316.',0,NULL,NULL,0,1,1.5,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
