INSERT INTO question VALUES('hea-4','gcse-bio','written',448,3,NULL,'Explain why HIV can make a person more likely to catch other diseases.','HIV attacks white blood cells (T cells), weakening the immune system, so other pathogens are not destroyed as effectively.','',0,NULL,NULL,0,2,2.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('hev-1','gcse-bio','mcq',442,0,NULL,'Which hominid fossil, about 3.2 million years old, is known as ''Lucy''?',NULL,'Lucy is an Australopithecus afarensis fossil. She walked upright.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
