INSERT INTO question VALUES('kft-3','gcse-bio','written',477,2,NULL,'Compare dialysis and transplants as treatments for kidney failure.','Dialysis: available, but time-consuming (several sessions a week), restricts diet and costs a lot over time. Transplant: long-term cure and freedom, but shortage of donors, surgery risks and lifelong immunosuppressants.','',0,NULL,NULL,0,2,2.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
