INSERT INTO question VALUES('methods-x1','methods','multi',NULL,NULL,0,'A cubic curve and a probability density function',NULL,NULL,0,'active',NULL,0,14,20.0,NULL,'Original question in the style of VCAA Exam 2, Section B','original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
