INSERT INTO question VALUES('ncd-3','gcse-bio','mcq',458,2,NULL,'BMI is calculated as:',NULL,'BMI = mass ÷ height². Waist:hip ratio is another obesity measure.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('ncd-4','gcse-bio','written',458,3,NULL,'Calculate the BMI of a person with mass 72 kg and height 1.80 m.','72 ÷ 1.80² = 72 ÷ 3.24 = 22.2','',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('neu-1','gcse-bio','mcq',424,0,NULL,'Which part of a neurone is insulating and speeds up impulses?',NULL,'The fatty myelin sheath insulates the axon so impulses jump between gaps and travel faster.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
