INSERT INTO question VALUES('neu-4','gcse-bio','written',424,3,NULL,'Describe the function of dendrites and of the axon.','Dendrites receive impulses from other neurones; the axon carries impulses away from the cell body over long distances.','',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
