INSERT INTO question VALUES('nit-2','gcse-bio','mcq',494,1,NULL,'Nitrifying bacteria convert:',NULL,'They oxidise ammonium compounds to nitrites then nitrates.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('nit-3','gcse-bio','mcq',494,2,NULL,'Denitrifying bacteria are most active in:',NULL,'They convert nitrates back into nitrogen gas in low-oxygen conditions.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('nit-4','gcse-bio','written',494,3,NULL,'Why do farmers rotate crops including legumes?','Legumes have nitrogen-fixing bacteria in root nodules, adding nitrates to the soil, so less fertiliser is needed for the next crop.','',0,NULL,NULL,0,2,2.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('osm-1','gcse-bio','mcq',419,0,NULL,'Osmosis is the movement of water across a partially permeable membrane from:',NULL,'Water moves from a dilute solution (high water concentration) to a more concentrated solution.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('osm-2','gcse-bio','mcq',419,1,NULL,'A potato cylinder goes from 2.0 g to 2.5 g after soaking. What is the percentage change in mass?',NULL,'Change = 0.5 g. 0.5 ÷ 2.0 × 100 = +25%.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('osm-3','gcse-bio','written',419,2,NULL,'Explain what happens to a plant cell placed in pure water.','Water enters by osmosis because the cell contents are more concentrated. The vacuole swells and pushes against the cell wall, so the cell becomes turgid. The cell wall stops it bursting.','',0,NULL,NULL,0,2,2.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('pad-1','gcse-bio','mcq',466,0,NULL,'Which adaptation helps cacti reduce water loss?',NULL,'Spines reduce surface area for transpiration.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
