INSERT INTO question VALUES('pdd-4','gcse-bio','written',451,3,NULL,'Describe two ways scientists can identify a plant disease.','Observe symptoms; compare with a reference/gardening manual; send samples to a lab; use monoclonal antibody testing kits; analyse DNA of the pathogen; check distribution of affected plants.','',0,NULL,NULL,0,2,2.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
