INSERT INTO question VALUES('vce-bio12-st-c1','vce-bio12','mcq',305,26,NULL,'Which correctly matches each cell with its potency?',NULL,'Totipotent cells can form a whole organism (including the placenta); pluripotent cells can form any body cell; multipotent cells form a few related types.',0,NULL,NULL,1,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('vce-bio12-th-c1','vce-bio12','mcq',310,26,NULL,'A person walks into a very cold room. Which response would NOT occur?',NULL,'In the cold, skin arterioles constrict (vasoconstriction) to reduce heat loss. Vasodilation happens when the body is too hot.',0,NULL,NULL,1,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
