INSERT INTO question VALUES('vce-psych12-se-c1','vce-psych12','mcq',351,23,NULL,'What is the difference between random sampling and random allocation?',NULL,'Random sampling helps representativeness (generalisation); random allocation spreads participant variables evenly between groups.',0,NULL,NULL,1,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('vce-psych12-sf-c1','vce-psych12','mcq',330,39,NULL,'Damage to Wernicke''s area (usually in the left temporal lobe) would most likely cause:',NULL,'Wernicke''s area is linked to language comprehension. Broca''s area (frontal lobe) is linked to speech production; the cerebellum to coordination.',0,NULL,NULL,1,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('vce-psych12-sm-c1','vce-psych12','mcq',350,35,NULL,'A study finds that adolescents who use social media more report lower mood. Researchers cannot conclude that social media causes low mood because:',NULL,'Only a controlled experiment, where the IV is manipulated and other variables controlled, supports cause-and-effect conclusions.',0,NULL,NULL,1,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
