INSERT INTO question VALUES('vce-psych12-sv-c1','vce-psych12','mcq',345,37,NULL,'Which order correctly describes the stages of visual sensation and perception?',NULL,'Sensation: light is received, converted (transduced) by rods and cones, and transmitted along the optic nerve. Perception: the brain selects, organises and interprets.',0,NULL,NULL,1,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
