INSERT INTO question VALUES('wat-1','gcse-bio','mcq',493,0,NULL,'Which process changes water vapour into liquid water in clouds?',NULL,'Water vapour cools and condenses.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('wat-2','gcse-bio','mcq',493,1,NULL,'Potable water is:',NULL,'It has low levels of dissolved substances and microbes.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('wat-3','gcse-bio','mcq',493,2,NULL,'Desalination produces fresh water by:',NULL,'Used in areas with little fresh water but expensive in energy.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('wat-4','gcse-bio','written',493,3,NULL,'Explain why desalination is not used widely.','It needs large amounts of energy, making it expensive; produces salty waste that can harm marine life.','',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('xyl-1','gcse-bio','mcq',462,0,NULL,'Xylem vessels transport:',NULL,'Xylem carries water and minerals from roots up to leaves.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('xyl-2','gcse-bio','mcq',462,1,NULL,'Which feature describes xylem?',NULL,'Xylem cells are dead, hollow tubes strengthened by lignin.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('xyl-3','gcse-bio','mcq',462,2,NULL,'How do root hair cells take up mineral ions?',NULL,'Minerals are often at lower concentration in the soil, so active transport is needed.',0,NULL,NULL,0,1,1.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
INSERT INTO question VALUES('xyl-4','gcse-bio','written',462,3,NULL,'Explain how root hair cells are adapted for absorbing water.','Long hair-like extension gives a large surface area; thin cell wall gives short diffusion distance; many mitochondria for active transport of minerals.','',0,NULL,NULL,0,2,2.0,NULL,NULL,'original','unknown',NULL,NULL,NULL,'Imported from index.html (written for this site; some questions were drafted with AI help and then reviewed).','2026-11-18T08:22:45','2026-11-18T08:23:12');
