INSERT INTO rubric_criterion VALUES(1433,'int-4',NULL,0,'Organisms in a community depend on each other for food, shelter, pollination, seed dispersal etc.',1,1);
INSERT INTO rubric_criterion VALUES(1434,'int-4',NULL,1,'A change in one population affects others.',1,1);
INSERT INTO rubric_criterion VALUES(1440,'g17-int-6',NULL,0,'Organisms depend on others for food, shelter, pollination or seed dispersal; e.g.',1,1);
INSERT INTO rubric_criterion VALUES(1441,'g17-int-6',NULL,1,'bees need nectar from flowers and flowers need bees for pollination;',1,1);
INSERT INTO rubric_criterion VALUES(1442,'g17-int-6',NULL,2,'a change in one population affects others.',1,1);
