INSERT INTO rubric_criterion VALUES(1447,'g17-int-8',NULL,1,'the insect population decreases;',1,1);
INSERT INTO rubric_criterion VALUES(1448,'g17-int-8',NULL,2,'birds have less food so bird numbers decrease or birds move away;',1,1);
INSERT INTO rubric_criterion VALUES(1449,'g17-int-8',NULL,3,'interdependence in the food web.',1,1);
INSERT INTO rubric_criterion VALUES(1454,'qua-4',NULL,0,'Use more quadrats / larger sample size; place randomly (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(1455,'qua-4',NULL,1,'random number generator); repeat and calculate a mean.',1,1);
INSERT INTO rubric_criterion VALUES(1461,'g18-quad-6',NULL,0,'Mean per quadrat = 45 ÷ 10 = 4.5;',1,1);
INSERT INTO rubric_criterion VALUES(1462,'g18-quad-6',NULL,1,'per m² = 4.5;',1,1);
INSERT INTO rubric_criterion VALUES(1463,'g18-quad-6',NULL,2,'population = 4.5 × 600 = 2700 buttercups.',1,1);
