INSERT INTO rubric_criterion VALUES(1466,'g18-quad-7',NULL,2,'repeat with several transects and calculate means for each distance;',1,1);
INSERT INTO rubric_criterion VALUES(1467,'g18-quad-7',NULL,3,'use the same size quadrat.',1,1);
INSERT INTO rubric_criterion VALUES(1468,'g18-quad-8',NULL,0,'A larger sample is more likely to be representative of the whole area;',1,1);
INSERT INTO rubric_criterion VALUES(1469,'g18-quad-8',NULL,1,'reduces the effect of anomalies/chance (unusually dense or sparse patches) on the mean.',1,1);
INSERT INTO rubric_criterion VALUES(1470,'gcse-bio-sampling-with-quadrats-c1',NULL,0,'2800 daisies',2,1);
INSERT INTO rubric_criterion VALUES(1474,'ene-4',NULL,0,'Respiration releases energy used for movement/heat; not all of the organism is eaten (bones, roots);',1,1);
INSERT INTO rubric_criterion VALUES(1475,'ene-4',NULL,1,'some is egested as faeces; urea excreted.',1,1);
INSERT INTO rubric_criterion VALUES(1481,'g18-ene-6',NULL,0,'120 ÷ 1500 × 100;',1,1);
INSERT INTO rubric_criterion VALUES(1482,'g18-ene-6',NULL,1,'= 8%.',1,1);
INSERT INTO rubric_criterion VALUES(1483,'g18-ene-7',NULL,0,'Biomass is lost between trophic levels;',1,1);
INSERT INTO rubric_criterion VALUES(1484,'g18-ene-7',NULL,1,'because energy is lost as heat from respiration, in waste and undigested material;',1,1);
INSERT INTO rubric_criterion VALUES(1485,'g18-ene-7',NULL,2,'so less biomass can be supported at each higher level.',1,1);
