INSERT INTO rubric_criterion VALUES(1487,'g18-ene-8',NULL,1,'control pests and disease; feed high-energy food.',1,1);
INSERT INTO rubric_criterion VALUES(1488,'gcse-bio-energy-transfer-and-biomass-pyramids-c1',NULL,0,'6%;',1,1);
INSERT INTO rubric_criterion VALUES(1489,'gcse-bio-energy-transfer-and-biomass-pyramids-c1',NULL,1,'energy is lost in respiration (as heat), in egested material and in parts not eaten.',1,1);
INSERT INTO rubric_criterion VALUES(1493,'hib-4',NULL,0,'Fertilisers wash into water; algae grow rapidly and block light; plants below die;',1,1);
INSERT INTO rubric_criterion VALUES(1494,'hib-4',NULL,1,'bacteria decompose dead material and use up oxygen through respiration; fish suffocate.',1,1);
INSERT INTO rubric_criterion VALUES(1500,'g18-hib-6',NULL,0,'Fewer trees to absorb CO₂ in photosynthesis;',1,1);
INSERT INTO rubric_criterion VALUES(1501,'g18-hib-6',NULL,1,'burning of trees releases CO₂;',1,1);
INSERT INTO rubric_criterion VALUES(1502,'g18-hib-6',NULL,2,'decomposition of the felled wood by microorganisms releases CO₂ through respiration.',1,1);
INSERT INTO rubric_criterion VALUES(1503,'g18-hib-7',NULL,0,'Fertiliser run-off: eutrophication, killing aquatic life;',1,1);
INSERT INTO rubric_criterion VALUES(1504,'g18-hib-7',NULL,1,'smoke/sulfur dioxide from burning fuels: acid rain damaging trees;',1,1);
INSERT INTO rubric_criterion VALUES(1505,'g18-hib-7',NULL,2,'waste/chemicals in water or on land: poisoning organisms;',1,1);
INSERT INTO rubric_criterion VALUES(1506,'g18-hib-7',NULL,3,'plastics: harm to wildlife.',1,1);
INSERT INTO rubric_criterion VALUES(1507,'g18-hib-8',NULL,0,'More land is needed for housing, farming and quarrying; this destroys habitats;',1,1);
INSERT INTO rubric_criterion VALUES(1508,'g18-hib-8',NULL,1,'more waste and pollution is produced;',1,1);
INSERT INTO rubric_criterion VALUES(1509,'g18-hib-8',NULL,2,'more resources are used and more carbon dioxide released.',1,1);
INSERT INTO rubric_criterion VALUES(1513,'cbd-3',NULL,0,'Stable ecosystems; protects food sources; potential new medicines;',1,1);
INSERT INTO rubric_criterion VALUES(1514,'cbd-3',NULL,1,'ecotourism; cultural/aesthetic value; protects pollinators.',1,1);
INSERT INTO rubric_criterion VALUES(1520,'g18-con-6',NULL,0,'Species depend on each other so loss of one affects food webs; stable ecosystems provide food/materials/pollination;',1,1);
INSERT INTO rubric_criterion VALUES(1521,'g18-con-6',NULL,1,'potential source of new medicines and crops;',1,1);
INSERT INTO rubric_criterion VALUES(1522,'g18-con-6',NULL,2,'ecotourism and aesthetic value.',1,1);
INSERT INTO rubric_criterion VALUES(1523,'g18-con-7',NULL,0,'Captive breeding programmes and release; protected nature reserves/national parks; legal protection/ban on hunting or trade;',1,1);
INSERT INTO rubric_criterion VALUES(1524,'g18-con-7',NULL,1,'seed banks; replanting hedgerows or habitats; setting fishing quotas.',1,1);
INSERT INTO rubric_criterion VALUES(1525,'g18-con-8',NULL,0,'Land would be taken out of food production so reducing income; conservation measures cost money and time;',1,1);
INSERT INTO rubric_criterion VALUES(1526,'g18-con-8',NULL,1,'some protected animals may damage crops or livestock.',1,1);
INSERT INTO rubric_criterion VALUES(1530,'fsc-3',NULL,0,'GM crops with higher yield or pest/drought resistance; crops with added nutrients;',1,1);
INSERT INTO rubric_criterion VALUES(1531,'fsc-3',NULL,1,'mycoprotein grown in fermenters; biological control of pests.',1,1);
INSERT INTO rubric_criterion VALUES(1537,'g19-food-6',NULL,0,'Any three from: rising birth rate / growing population; changing diets in developing countries increasing demand for meat;',1,1);
INSERT INTO rubric_criterion VALUES(1538,'g19-food-6',NULL,1,'new pests and pathogens affecting farming; environmental changes such as drought or flooding affecting yields;',1,1);
INSERT INTO rubric_criterion VALUES(1539,'g19-food-6',NULL,2,'cost of agricultural inputs (fertiliser, pesticide); conflicts affecting food availability.',1,1);
INSERT INTO rubric_criterion VALUES(1540,'g19-food-7',NULL,0,'Fishing quotas limit the number or mass of fish that can be caught; nets with larger mesh sizes let young fish escape;',1,1);
INSERT INTO rubric_criterion VALUES(1541,'g19-food-7',NULL,1,'so enough fish survive to breed and replace those caught;',1,1);
INSERT INTO rubric_criterion VALUES(1542,'g19-food-7',NULL,2,'fishing banned in breeding areas or at breeding times.',1,1);
INSERT INTO rubric_criterion VALUES(1543,'g19-food-8',NULL,0,'Genes can be transferred into crops to give resistance to pests or disease; or tolerance of drought/herbicides;',1,1);
INSERT INTO rubric_criterion VALUES(1544,'g19-food-8',NULL,1,'or higher yield / added nutrients;',1,1);
INSERT INTO rubric_criterion VALUES(1545,'g19-food-8',NULL,2,'so less of the crop is lost and more food is produced per hectare.',1,1);
INSERT INTO rubric_criterion VALUES(1550,'crb-4',NULL,0,'The animal eats the plant; carbon compounds become part of the animal''s biomass;',1,1);
INSERT INTO rubric_criterion VALUES(1551,'crb-4',NULL,1,'the animal respires releasing CO₂; when it dies decomposers respire, releasing more CO₂.',1,1);
INSERT INTO rubric_criterion VALUES(1557,'g19-carb-6',NULL,0,'Decomposers (bacteria and fungi) feed on the dead leaf;',1,1);
INSERT INTO rubric_criterion VALUES(1558,'g19-carb-6',NULL,1,'they break down carbon compounds and respire;',1,1);
INSERT INTO rubric_criterion VALUES(1559,'g19-carb-6',NULL,2,'releasing carbon dioxide into the atmosphere.',1,1);
INSERT INTO rubric_criterion VALUES(1560,'g19-carb-7',NULL,0,'Carbon is removed from the air by photosynthesis and returned by respiration, combustion and decay;',1,1);
INSERT INTO rubric_criterion VALUES(1561,'g19-carb-7',NULL,1,'so the overall amount of CO₂ stays roughly constant when these are in balance.',1,1);
INSERT INTO rubric_criterion VALUES(1562,'g19-carb-8',NULL,0,'Burning fossil fuels releases carbon locked away for millions of years as CO₂;',1,1);
INSERT INTO rubric_criterion VALUES(1563,'g19-carb-8',NULL,1,'deforestation reduces photosynthesis;',1,1);
INSERT INTO rubric_criterion VALUES(1564,'g19-carb-8',NULL,2,'so more CO₂ is released than removed, and atmospheric CO₂ rises.',1,1);
INSERT INTO rubric_criterion VALUES(1569,'wat-4',NULL,0,'It needs large amounts of energy, making it expensive; produces salty waste that can harm marine life.',1,1);
INSERT INTO rubric_criterion VALUES(1575,'g19-wat-6',NULL,0,'Choose a suitable source of fresh water;',1,1);
INSERT INTO rubric_criterion VALUES(1576,'g19-wat-6',NULL,1,'pass it through filter beds to remove solid particles;',1,1);
INSERT INTO rubric_criterion VALUES(1577,'g19-wat-6',NULL,2,'sterilise using chlorine (or ozone or ultraviolet light) to kill microbes.',1,1);
INSERT INTO rubric_criterion VALUES(1578,'g19-wat-7',NULL,0,'It may contain dissolved gases, dust or pollutants and microorganisms;',1,1);
INSERT INTO rubric_criterion VALUES(1579,'g19-wat-7',NULL,1,'potable water must have safe levels of dissolved substances and microbes.',1,1);
INSERT INTO rubric_criterion VALUES(1580,'g19-wat-8',NULL,0,'Fewer trees means less transpiration;',1,1);
INSERT INTO rubric_criterion VALUES(1581,'g19-wat-8',NULL,1,'so less water vapour enters the air and less rainfall may occur;',1,1);
INSERT INTO rubric_criterion VALUES(1582,'g19-wat-8',NULL,2,'more water runs off the soil, which may increase erosion/flooding.',1,1);
INSERT INTO rubric_criterion VALUES(1587,'nit-4',NULL,0,'Legumes have nitrogen-fixing bacteria in root nodules, adding nitrates to the soil, so less fertiliser is needed for the next crop.',2,1);
INSERT INTO rubric_criterion VALUES(1593,'g19-nit-6',NULL,0,'Decomposers break down the protein / urea into ammonia;',1,1);
INSERT INTO rubric_criterion VALUES(1594,'g19-nit-6',NULL,1,'nitrifying bacteria convert ammonia into nitrates;',1,1);
INSERT INTO rubric_criterion VALUES(1595,'g19-nit-6',NULL,2,'plant roots absorb nitrates from the soil;',1,1);
INSERT INTO rubric_criterion VALUES(1596,'g19-nit-6',NULL,3,'plants combine nitrates with glucose to make amino acids and then proteins.',1,1);
INSERT INTO rubric_criterion VALUES(1597,'g19-nit-7',NULL,0,'Nitrogen-fixing bacteria in the soil or in root nodules; lightning (high temperatures cause nitrogen to react with oxygen, forming nitrogen oxides that dissolve in rain);',1,1);
INSERT INTO rubric_criterion VALUES(1598,'g19-nit-7',NULL,1,'also the Haber process to make fertilisers.',1,1);
INSERT INTO rubric_criterion VALUES(1599,'g19-nit-8',NULL,0,'Excess nitrates are washed into the lake (leaching/runoff); causing algal bloom;',1,1);
INSERT INTO rubric_criterion VALUES(1600,'g19-nit-8',NULL,1,'which blocks light so plants die;',1,1);
INSERT INTO rubric_criterion VALUES(1601,'g19-nit-8',NULL,2,'decomposers respire using up oxygen, so fish die (eutrophication).',1,1);
INSERT INTO rubric_criterion VALUES(1606,'dec-4',NULL,0,'Turning adds oxygen so decomposers can respire aerobically, speeding up decomposition.',1,1);
INSERT INTO rubric_criterion VALUES(1612,'g20-dec-6',NULL,0,'Higher temperature in summer;',1,1);
INSERT INTO rubric_criterion VALUES(1613,'g20-dec-6',NULL,1,'increases enzyme activity / rate of respiration and reproduction of decomposers;',1,1);
INSERT INTO rubric_criterion VALUES(1614,'g20-dec-6',NULL,2,'so dead material is broken down faster (enzymes work at a lower rate when cold).',1,1);
INSERT INTO rubric_criterion VALUES(1615,'g20-dec-7',NULL,0,'Decomposers break down dead leaves and animals;',1,1);
INSERT INTO rubric_criterion VALUES(1616,'g20-dec-7',NULL,1,'respire and release carbon dioxide into the air for photosynthesis;',1,1);
INSERT INTO rubric_criterion VALUES(1617,'g20-dec-7',NULL,2,'release minerals/nitrates into the soil which plants absorb for growth.',1,1);
INSERT INTO rubric_criterion VALUES(1618,'g20-dec-8',NULL,0,'25 °C fastest, then 5 °C, then 60 °C slowest (or 60 °C may be near zero); at 25 °C bacteria are near optimum so reproduce and respire quickly;',1,1);
INSERT INTO rubric_criterion VALUES(1619,'g20-dec-8',NULL,1,'at 5 °C enzyme activity is slow;',1,1);
INSERT INTO rubric_criterion VALUES(1620,'g20-dec-8',NULL,2,'at 60 °C bacterial enzymes denature / bacteria are killed.',1,1);
INSERT INTO rubric_criterion VALUES(1621,'gcse-bio-decomposition-c1',NULL,0,'0.5 g/day;',1,1);
INSERT INTO rubric_criterion VALUES(1622,'gcse-bio-decomposition-c1',NULL,1,'warmer temperatures (up to the decomposers'' optimum), more water and more oxygen.',1,1);
INSERT INTO rubric_criterion VALUES(1626,'ind-4',NULL,0,'Advantages: cheap; shows long-term effects. Disadvantages: less precise; doesn''t identify the exact pollutant or its concentration.',1,1);
INSERT INTO rubric_criterion VALUES(1632,'g20-ind-6',NULL,0,'Stonefly larvae need high oxygen levels;',1,1);
INSERT INTO rubric_criterion VALUES(1633,'g20-ind-6',NULL,1,'sewage causes bacterial growth that uses up oxygen downstream;',1,1);
INSERT INTO rubric_criterion VALUES(1634,'g20-ind-6',NULL,2,'so stoneflies cannot survive downstream (indicating pollution).',1,1);
INSERT INTO rubric_criterion VALUES(1635,'g20-ind-7',NULL,0,'Organisms are exposed to conditions over a long time / reflect average pollution over weeks or months;',1,1);
INSERT INTO rubric_criterion VALUES(1636,'g20-ind-7',NULL,1,'a chemical test only shows the level at the moment of sampling and pollution may be intermittent.',1,1);
INSERT INTO rubric_criterion VALUES(1637,'g20-ind-8',NULL,0,'Use a quadrat on tree trunks at each site; record the types of lichen present (crusty, leafy, bushy) and percentage cover;',1,1);
INSERT INTO rubric_criterion VALUES(1638,'g20-ind-8',NULL,1,'more leafy/bushy lichens means cleaner air;',1,1);
INSERT INTO rubric_criterion VALUES(1639,'g20-ind-8',NULL,2,'repeat on several trees and compare means.',1,1);
INSERT INTO rubric_criterion VALUES(1644,'cpm-4',NULL,0,'Peel a thin layer of epidermis; place on a slide in a drop of water/iodine;',1,1);
INSERT INTO rubric_criterion VALUES(1645,'cpm-4',NULL,1,'lower a coverslip at an angle to avoid air bubbles; view under the microscope.',1,1);
INSERT INTO rubric_criterion VALUES(1651,'g20-cpm-6',NULL,0,'Place slide on the stage and clip it; select the lowest power objective;',1,1);
INSERT INTO rubric_criterion VALUES(1652,'g20-cpm-6',NULL,1,'use the coarse focus to move the stage/lens until the image is roughly clear (viewing from the side first to avoid contact);',1,1);
INSERT INTO rubric_criterion VALUES(1653,'g20-cpm-6',NULL,2,'use the fine focus to sharpen;',1,1);
INSERT INTO rubric_criterion VALUES(1654,'g20-cpm-6',NULL,3,'change to higher power if needed and use fine focus only.',1,1);
INSERT INTO rubric_criterion VALUES(1655,'g20-cpm-7',NULL,0,'Real size = image size ÷ magnification; 45 mm = 45 000 µm;',1,1);
INSERT INTO rubric_criterion VALUES(1656,'g20-cpm-7',NULL,1,'45 000 ÷ 300 = 150 µm.',1,1);
INSERT INTO rubric_criterion VALUES(1657,'g20-cpm-8',NULL,0,'Light must pass through the specimen;',1,1);
INSERT INTO rubric_criterion VALUES(1658,'g20-cpm-8',NULL,1,'if it is too thick, light cannot pass through / layers overlap, so the image is dark or unclear.',1,1);
INSERT INTO rubric_criterion VALUES(1663,'cpa-4',NULL,0,'Put iodine drops on a spotting tile; every 10–30 s take a drop of the mixture and add to iodine;',1,1);
INSERT INTO rubric_criterion VALUES(1664,'cpa-4',NULL,1,'record when the iodine no longer turns blue-black.',1,1);
INSERT INTO rubric_criterion VALUES(1670,'g20-cpa-6',NULL,0,'Add starch solution and buffer of a set pH to a tube in a water bath at constant temperature; add amylase and start the timer;',1,1);
INSERT INTO rubric_criterion VALUES(1671,'g20-cpa-6',NULL,1,'every 30 s remove a drop and add to iodine on a spotting tile;',1,1);
INSERT INTO rubric_criterion VALUES(1672,'g20-cpa-6',NULL,2,'record time when iodine stays orange-brown;',1,1);
INSERT INTO rubric_criterion VALUES(1673,'g20-cpa-6',NULL,3,'repeat at other pH values.',1,1);
INSERT INTO rubric_criterion VALUES(1674,'g20-cpa-7',NULL,0,'Temperature, volume/concentration of amylase or starch;',1,1);
INSERT INTO rubric_criterion VALUES(1675,'g20-cpa-7',NULL,1,'these also affect the rate of reaction so would affect results / make the test unfair.',1,1);
INSERT INTO rubric_criterion VALUES(1676,'g20-cpa-8',NULL,0,'Extreme pH disrupts the bonds holding the enzyme''s shape;',1,1);
INSERT INTO rubric_criterion VALUES(1677,'g20-cpa-8',NULL,1,'the active site changes shape / enzyme denatures;',1,1);
INSERT INTO rubric_criterion VALUES(1678,'g20-cpa-8',NULL,2,'the substrate (starch) can no longer fit so fewer reactions occur.',1,1);
INSERT INTO rubric_criterion VALUES(1683,'cpo-4',NULL,0,'The sucrose solution is more concentrated than the cell sap, so water leaves the cells by osmosis.',1,1);
INSERT INTO rubric_criterion VALUES(1689,'g21-pot-6',NULL,0,'Find where the line of best fit crosses the x-axis / 0% change in mass;',1,1);
INSERT INTO rubric_criterion VALUES(1690,'g21-pot-6',NULL,1,'read the sucrose concentration at that point, which equals the concentration of the cell sap because there is no net movement of water.',1,1);
INSERT INTO rubric_criterion VALUES(1691,'g21-pot-7',NULL,0,'Any three from: volume of solution; temperature; time left in solution;',1,1);
INSERT INTO rubric_criterion VALUES(1692,'g21-pot-7',NULL,1,'size / surface area / diameter of potato cylinders; type / same potato;',1,1);
INSERT INTO rubric_criterion VALUES(1693,'g21-pot-7',NULL,2,'method of blotting; same number of cylinders per beaker.',1,1);
INSERT INTO rubric_criterion VALUES(1694,'g21-pot-8',NULL,0,'Use several cylinders (e.g. three) in each concentration / repeat the experiment;',1,1);
INSERT INTO rubric_criterion VALUES(1695,'g21-pot-8',NULL,1,'calculate a mean percentage change for each concentration; identify and ignore anomalies.',1,1);
INSERT INTO rubric_criterion VALUES(1699,'cpf-3',NULL,0,'Wear eye protection; keep ethanol away from flames;',1,1);
INSERT INTO rubric_criterion VALUES(1700,'cpf-3',NULL,1,'use a water bath not a direct flame to heat Benedict''s.',1,1);
INSERT INTO rubric_criterion VALUES(1706,'g21-food-6',NULL,0,'Add Benedict''s reagent to the sample in a test tube;',1,1);
INSERT INTO rubric_criterion VALUES(1707,'g21-food-6',NULL,1,'heat in a water bath (about 80 °C / hot water);',1,1);
INSERT INTO rubric_criterion VALUES(1708,'g21-food-6',NULL,2,'for a few minutes;',1,1);
INSERT INTO rubric_criterion VALUES(1709,'g21-food-6',NULL,3,'positive result is colour change from blue to green / yellow / orange / brick red.',1,1);
INSERT INTO rubric_criterion VALUES(1710,'g21-food-7',NULL,0,'Starch;',1,1);
INSERT INTO rubric_criterion VALUES(1711,'g21-food-7',NULL,1,'and protein.',1,1);
INSERT INTO rubric_criterion VALUES(1712,'g21-food-8',NULL,0,'A water bath heats more gently / evenly so the liquid does not spit out;',1,1);
INSERT INTO rubric_criterion VALUES(1713,'g21-food-8',NULL,1,'ethanol is flammable so must be kept away from naked flames.',1,1);
INSERT INTO rubric_criterion VALUES(1717,'cpc-3',NULL,0,'Energy = 25 × 4.2 × 12 = 1260 J. 1260 ÷ 0.5 = 2520 J/g.',1,1);
INSERT INTO rubric_criterion VALUES(1723,'g21-cal-6',NULL,0,'Energy = 30 × 4.2 × 40 = 5040 J;',1,1);
INSERT INTO rubric_criterion VALUES(1724,'g21-cal-6',NULL,1,'5040 ÷ 0.8 = 6300 J/g (6.3 kJ/g).',2,1);
INSERT INTO rubric_criterion VALUES(1725,'g21-cal-7',NULL,0,'Any two from: volume / mass of water; starting temperature of water; distance between the food and the tube;',1,1);
INSERT INTO rubric_criterion VALUES(1726,'g21-cal-7',NULL,1,'mass of food; same apparatus / same type of tube.',1,1);
INSERT INTO rubric_criterion VALUES(1727,'g21-cal-8',NULL,0,'Repeat the experiment for each food and calculate a mean;',1,1);
INSERT INTO rubric_criterion VALUES(1728,'g21-cal-8',NULL,1,'ignore anomalous results / check repeats are close together.',1,1);
INSERT INTO rubric_criterion VALUES(1729,'gcse-bio-cp-calorimetry-c1',NULL,0,'Insulate the tube (or use a lid) to reduce heat loss; place the burning food closer to the tube;',1,1);
INSERT INTO rubric_criterion VALUES(1730,'gcse-bio-cp-calorimetry-c1',NULL,1,'make sure the food burns completely, relighting if needed; stir the water.',1,1);
INSERT INTO rubric_criterion VALUES(1734,'cpb-4',NULL,0,'Sterilise the inoculating loop in a flame; tape the lid (not fully sealed); flame the neck of bottles;',1,1);
INSERT INTO rubric_criterion VALUES(1735,'cpb-4',NULL,1,'open lids minimally; sterilise equipment in an autoclave.',1,1);
INSERT INTO rubric_criterion VALUES(1741,'g21-abx-6',NULL,0,'Sterilise the loop by passing it through a flame; let it cool;',1,1);
INSERT INTO rubric_criterion VALUES(1742,'g21-abx-6',NULL,1,'remove lid only slightly / minimally and spread bacteria on the agar;',1,1);
INSERT INTO rubric_criterion VALUES(1743,'g21-abx-6',NULL,2,'replace lid and tape it.',1,1);
INSERT INTO rubric_criterion VALUES(1744,'g21-abx-7',NULL,0,'A is more effective;',1,1);
INSERT INTO rubric_criterion VALUES(1745,'g21-abx-7',NULL,1,'because it has a larger clear zone / killed more bacteria;',1,1);
INSERT INTO rubric_criterion VALUES(1746,'g21-abx-7',NULL,2,'area = 3.14 × 7² = 153.9 mm² (about 154 mm²).',1,1);
INSERT INTO rubric_criterion VALUES(1747,'g21-abx-8',NULL,0,'37 °C is body temperature; it would encourage growth of human pathogens;',1,1);
INSERT INTO rubric_criterion VALUES(1748,'g21-abx-8',NULL,1,'25 °C reduces the risk of harmful pathogens growing.',1,1);
INSERT INTO rubric_criterion VALUES(1749,'gcse-bio-cp-antibiotics-and-bacterial-growth-c1',NULL,0,'About 154 mm²',1,1);
