INSERT INTO rubric_criterion VALUES(1760,'g22-lip-6',NULL,0,'Place a piece of pondweed in a beaker of water with sodium hydrogencarbonate (CO₂ source), connected to a gas syringe (or inverted funnel and syringe); place a lamp at a measured distance from the beaker;',1,1);
INSERT INTO rubric_criterion VALUES(1761,'g22-lip-6',NULL,1,'leave to adjust then record the volume of oxygen collected in a set time (e.g. 2 minutes);',1,1);
INSERT INTO rubric_criterion VALUES(1762,'g22-lip-6',NULL,2,'repeat at different distances, keeping temperature (e.g. use a water bath / heat shield) and pondweed the same;',1,1);
