INSERT INTO rubric_criterion VALUES(1772,'cpr-4',NULL,0,'Handle carefully; don''t leave them too long; avoid contact with soda lime; return them to their habitat afterwards.',1,1);
INSERT INTO rubric_criterion VALUES(1778,'g22-rrs-6',NULL,0,'The control shows whether changes in gas volume / liquid movement are due to the living organisms;',1,1);
