INSERT INTO rubric_criterion VALUES(1781,'g22-rrs-7',NULL,1,'but the soda lime can still absorb the CO₂ produced from the air around them.',1,1);
INSERT INTO rubric_criterion VALUES(1782,'g22-rrs-8',NULL,0,'The liquid would move faster / greater distance per minute at 25 °C;',1,1);
INSERT INTO rubric_criterion VALUES(1783,'g22-rrs-8',NULL,1,'because respiration is controlled by enzymes and a higher temperature gives more kinetic energy and more frequent collisions, so respiration rate increases and oxygen is used up more quickly.',2,1);
