INSERT INTO rubric_criterion VALUES(2881,'general-2-1-20',NULL,0,'Correlation only measures how strongly two variables are linearly associated; the association may be due to a third (lurking) variable, a confounding variable or coincidence.',1,1);
INSERT INTO rubric_criterion VALUES(2882,'general-2-1-20',NULL,1,'For example, ice-cream sales and drownings are correlated because both increase in hot weather.',1,1);
