INSERT INTO rubric_criterion VALUES(2884,'general-2-1-22',NULL,0,'Common response (both variables respond to a third variable), confounding (the effect of another variable cannot be separated from the explanatory variable) and coincidence.',3,1);
INSERT INTO rubric_criterion VALUES(2885,'general-2-1-23',NULL,0,'Pearson''s r only measures the strength of a linear association.',1,1);
INSERT INTO rubric_criterion VALUES(2886,'general-2-1-23',NULL,1,'For a curved pattern r may be close to zero even though there is a strong non-linear relationship, so it would be misleading.',1,1);
