INSERT INTO rubric_criterion VALUES(2943,'general-2-3-22',NULL,0,'If a linear model is appropriate, the residuals are randomly scattered above and below zero with no clear pattern.',1,1);
INSERT INTO rubric_criterion VALUES(2944,'general-2-3-22',NULL,1,'A clear pattern, such as a curve (U shape or inverted U), suggests the relationship is non-linear.',1,1);
