INSERT INTO rubric_criterion VALUES(3557,'general-7-4-22',NULL,1,'−0.4 1.6], so S0 = [980 − 180; −280 + 480] = [800; 200].',1,1);
INSERT INTO rubric_criterion VALUES(3558,'general-7-4-23',NULL,0,'Each step (after fish move between ponds), 30 fish are removed from pond 1 (e.g. harvested) and 10 fish are added to pond 2 (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(3559,'general-7-4-23',NULL,1,'restocked).',1,1);
INSERT INTO rubric_criterion VALUES(3560,'general-7-4-24',NULL,0,'510 members.',1,1);
INSERT INTO rubric_criterion VALUES(3561,'general-7-4-24',NULL,1,'G keeps the total at 500 (its columns sum to 1) and B adds 10 new members.',1,1);
INSERT INTO rubric_criterion VALUES(3562,'general-7-4-25',NULL,0,'1350 (1000 + 5 × 70).',2,1);
INSERT INTO rubric_criterion VALUES(3582,'general-8-1-19',NULL,0,'6 edges.',2,1);
INSERT INTO rubric_criterion VALUES(3583,'general-8-1-20',NULL,0,'K4 has four vertices of odd degree.',1,1);
INSERT INTO rubric_criterion VALUES(3584,'general-8-1-20',NULL,1,'An Euler trail requires zero or exactly two odd-degree vertices, so none exists.',1,1);
INSERT INTO rubric_criterion VALUES(3585,'general-8-1-21',NULL,0,'For example A–B–C–D–A–C (or its reverse, C–D–A–B–C–A, etc.).',3,1);
INSERT INTO rubric_criterion VALUES(3586,'general-8-1-22',NULL,0,'Yes.',1,1);
INSERT INTO rubric_criterion VALUES(3587,'general-8-1-22',NULL,1,'K5 is connected and every vertex has degree 4, which is even, so an Euler circuit exists.',1,1);
INSERT INTO rubric_criterion VALUES(3588,'general-8-1-23',NULL,0,'7 vertices.',1,1);
INSERT INTO rubric_criterion VALUES(3589,'general-8-1-24',NULL,0,'A–B–C–D–E–A (or A–E–D–C–B–A).',2,1);
INSERT INTO rubric_criterion VALUES(3590,'general-8-1-25',NULL,0,'An Euler circuit uses every edge exactly once and returns to the start;',1,1);
INSERT INTO rubric_criterion VALUES(3591,'general-8-1-25',NULL,1,'a Hamiltonian cycle visits every vertex exactly once and returns to the start.',1,1);
INSERT INTO rubric_criterion VALUES(3611,'general-8-2-19',NULL,0,'5 edges.',2,1);
INSERT INTO rubric_criterion VALUES(3612,'general-8-2-20',NULL,0,'13',1,1);
INSERT INTO rubric_criterion VALUES(3613,'general-8-2-21',NULL,0,'A–B–C–D–E, length 7.',2,1);
INSERT INTO rubric_criterion VALUES(3614,'general-8-2-22',NULL,0,'An MST minimises the total weight needed to connect all vertices, not the distance between a specific pair;',1,1);
INSERT INTO rubric_criterion VALUES(3615,'general-8-2-22',NULL,1,'the shortest route between two vertices may use an edge that is not in the MST.',1,1);
INSERT INTO rubric_criterion VALUES(3616,'general-8-2-23',NULL,0,'14 edges, because a tree with n vertices always has n − 1 edges.',2,1);
INSERT INTO rubric_criterion VALUES(3617,'general-8-2-24',NULL,0,'21 vertices.',1,1);
INSERT INTO rubric_criterion VALUES(3618,'general-8-2-25',NULL,0,'J–L–K–M–N, length 11.',1,1);
INSERT INTO rubric_criterion VALUES(3638,'general-8-3-19',NULL,0,'9',1,1);
INSERT INTO rubric_criterion VALUES(3639,'general-8-3-20',NULL,0,'Flow along that edge travels back towards the source, so it cannot add to the flow crossing from the source side to the sink side.',2,1);
INSERT INTO rubric_criterion VALUES(3640,'general-8-3-21',NULL,0,'P–2, Q–1, R–3 for a total of $125.',1,1);
INSERT INTO rubric_criterion VALUES(3641,'general-8-3-22',NULL,0,'0, 5, 2',1,1);
INSERT INTO rubric_criterion VALUES(3642,'general-8-3-23',NULL,0,'A–3, B–2, C–1, total 25 points.',2,1);
INSERT INTO rubric_criterion VALUES(3643,'general-8-3-24',NULL,0,'Every vertex in one group is paired with exactly one distinct vertex in the other group, so everyone is allocated exactly one task.',2,1);
INSERT INTO rubric_criterion VALUES(3644,'general-8-3-25',NULL,0,'25',1,1);
INSERT INTO rubric_criterion VALUES(3664,'general-8-4-19',NULL,0,'11 weeks; critical path A–C–D–E.',1,1);
INSERT INTO rubric_criterion VALUES(3665,'general-8-4-20',NULL,0,'1 week.',1,1);
INSERT INTO rubric_criterion VALUES(3666,'general-8-4-21',NULL,0,'A non-critical activity is not on the longest path, so the critical path length (which sets the completion time) is unchanged.',2,1);
INSERT INTO rubric_criterion VALUES(3667,'general-8-4-22',NULL,0,'Week 9.',1,1);
INSERT INTO rubric_criterion VALUES(3668,'general-8-4-23',NULL,0,'10 weeks; the critical path becomes A–B–E.',1,1);
INSERT INTO rubric_criterion VALUES(3669,'general-8-4-24',NULL,0,'A dummy activity has zero duration and is drawn (usually dashed) to show a precedence relationship that cannot otherwise be represented correctly, or to keep two activities from sharing the same start and end vertices.',2,1);
INSERT INTO rubric_criterion VALUES(3670,'general-8-4-25',NULL,0,'1 day.',1,1);
INSERT INTO rubric_criterion VALUES(3671,'general-8-4-c1',NULL,0,'12 days; float of C is 2 days',1,1);
INSERT INTO rubric_criterion VALUES(3675,'specialist-1-1-4',NULL,0,'Converse: ''If a triangle is isosceles, then it is equilateral'', which is false (e.g. sides 5, 5, 8).',1,1);
INSERT INTO rubric_criterion VALUES(3676,'specialist-1-1-4',NULL,1,'Contrapositive: ''If a triangle is not isosceles, then it is not equilateral'', which is true.',1,1);
INSERT INTO rubric_criterion VALUES(3680,'specialist-1-1-8',NULL,0,'Take a = 3, b = 4: √(9 + 16) = 5, but a + b = 7, and 5 ≠ 7.',2,1);
INSERT INTO rubric_criterion VALUES(3684,'specialist-1-1-12',NULL,0,'Take n = 3: 2³ = 8 and 3² = 9, and 8 < 9, so the statement is false.',1,1);
INSERT INTO rubric_criterion VALUES(3685,'specialist-1-1-12',NULL,1,'(n = 2 or n = 4 also work, since equality holds there.)',2,1);
INSERT INTO rubric_criterion VALUES(3689,'specialist-1-1-16',NULL,0,'Negation: ''∀x ∈ R, x² + 1 ≠ 0''.',1,1);
INSERT INTO rubric_criterion VALUES(3690,'specialist-1-1-16',NULL,1,'The negation is true, because x² ≥ 0 gives x² + 1 ≥ 1 > 0 for every real x.',1,1);
INSERT INTO rubric_criterion VALUES(3694,'specialist-1-1-20',NULL,0,'False. Counterexample: a = −3, b = 1. Here a < b, but a² = 9 > 1 = b².',1,1);
INSERT INTO rubric_criterion VALUES(3698,'specialist-1-1-24',NULL,0,'The first is true: for any x, take y = x + 1.',1,1);
INSERT INTO rubric_criterion VALUES(3699,'specialist-1-1-24',NULL,1,'The second is false: it says some y is greater than every real number, but taking x = y gives x < y false.',1,1);
INSERT INTO rubric_criterion VALUES(3700,'specialist-1-1-25',NULL,0,'√2 and −√2 are both irrational, but √2 + (−√2) = 0, which is rational.',2,1);
INSERT INTO rubric_criterion VALUES(3705,'specialist-1-2-4',NULL,0,'Let the integers be 2a and 2b, where a, b ∈ Z.',1,1);
INSERT INTO rubric_criterion VALUES(3706,'specialist-1-2-4',NULL,1,'Then 2a + 2b = 2(a + b), and a + b is an integer, so the sum is even.',2,1);
INSERT INTO rubric_criterion VALUES(3710,'specialist-1-2-8',NULL,0,'n² + n = n(n + 1). Of the consecutive integers n and n + 1, one is even, so the product is even.',1,1);
INSERT INTO rubric_criterion VALUES(3711,'specialist-1-2-8',NULL,1,'(Or by cases: if n = 2k then n² + n = 2(2k² + k);',1,1);
INSERT INTO rubric_criterion VALUES(3712,'specialist-1-2-8',NULL,2,'if n = 2k + 1 then n² + n = 2(2k² + 3k + 1).)',1,1);
INSERT INTO rubric_criterion VALUES(3716,'specialist-1-2-12',NULL,0,'Since a | b and a | c, b = ak and c = am for some integers k, m.',1,1);
INSERT INTO rubric_criterion VALUES(3717,'specialist-1-2-12',NULL,1,'Then b + c = a(k + m), and k + m is an integer, so a | (b + c).',2,1);
INSERT INTO rubric_criterion VALUES(3721,'specialist-1-2-16',NULL,0,'Let n = 2k + 1. Then n² − 1 = 4k² + 4k = 4k(k + 1).',1,1);
INSERT INTO rubric_criterion VALUES(3722,'specialist-1-2-16',NULL,1,'k(k + 1) is a product of consecutive integers, so it is even: k(k + 1) = 2m.',1,1);
INSERT INTO rubric_criterion VALUES(3723,'specialist-1-2-16',NULL,2,'Hence n² − 1 = 8m.',1,1);
INSERT INTO rubric_criterion VALUES(3727,'specialist-1-2-20',NULL,0,'Let the integers be 2a + 1 and 2b + 1.',1,1);
INSERT INTO rubric_criterion VALUES(3728,'specialist-1-2-20',NULL,1,'Their product is 4ab + 2a + 2b + 1 = 2(2ab + a + b) + 1, which has the form 2m + 1 with m an integer, so it is odd.',2,1);
INSERT INTO rubric_criterion VALUES(3732,'specialist-1-2-24',NULL,0,'Complete the square: x² − 6x + 10 = (x − 3)² + 1.',1,1);
INSERT INTO rubric_criterion VALUES(3733,'specialist-1-2-24',NULL,1,'Since (x − 3)² ≥ 0, the expression is at least 1, so it is greater than 0 for all real x.',2,1);
INSERT INTO rubric_criterion VALUES(3734,'specialist-1-2-25',NULL,0,'n³ − n = (n − 1)n(n + 1), a product of three consecutive integers.',1,1);
INSERT INTO rubric_criterion VALUES(3735,'specialist-1-2-25',NULL,1,'One of them is a multiple of 2 and one is a multiple of 3.',1,1);
INSERT INTO rubric_criterion VALUES(3736,'specialist-1-2-25',NULL,2,'Since 2 and 3 are coprime, 6 divides the product.',1,1);
INSERT INTO rubric_criterion VALUES(3737,'specialist-1-2-c1',NULL,0,'\(n^3 - n = (n - 1)n(n + 1)\), a product of three consecutive integers, so it contains a multiple of 2 and a multiple of 3, and is therefore divisible by 6.',3,1);
INSERT INTO rubric_criterion VALUES(3741,'specialist-1-3-4',NULL,0,'Assume √3 = p/q with p, q integers, q ≠ 0, in lowest terms. Then p² = 3q², so 3 | p² and, since 3 is prime, 3 | p.',1,1);
INSERT INTO rubric_criterion VALUES(3742,'specialist-1-3-4',NULL,1,'Write p = 3k: 9k² = 3q² gives q² = 3k², so 3 | q.',1,1);
INSERT INTO rubric_criterion VALUES(3743,'specialist-1-3-4',NULL,2,'Then 3 divides both p and q, which contradicts lowest terms.',1,1);
INSERT INTO rubric_criterion VALUES(3744,'specialist-1-3-4',NULL,3,'Hence √3 is irrational.',1,1);
INSERT INTO rubric_criterion VALUES(3748,'specialist-1-3-8',NULL,0,'Contrapositive: if n is even, then n² is even. Let n = 2k.',1,1);
INSERT INTO rubric_criterion VALUES(3749,'specialist-1-3-8',NULL,1,'Then n² = 4k² = 2(2k²), which is even.',1,1);
INSERT INTO rubric_criterion VALUES(3750,'specialist-1-3-8',NULL,2,'Since the contrapositive is true, the original statement is true.',1,1);
INSERT INTO rubric_criterion VALUES(3754,'specialist-1-3-12',NULL,0,'Assume r is the smallest positive rational.',1,1);
INSERT INTO rubric_criterion VALUES(3755,'specialist-1-3-12',NULL,1,'Then r/2 is rational (a ratio of integers), positive, and r/2 < r.',1,1);
INSERT INTO rubric_criterion VALUES(3756,'specialist-1-3-12',NULL,2,'This contradicts r being the smallest, so no smallest positive rational exists.',1,1);
INSERT INTO rubric_criterion VALUES(3760,'specialist-1-3-16',NULL,0,'Suppose 1/x is rational: 1/x = p/q with p, q integers and q ≠ 0. Since 1/x ≠ 0, p ≠ 0.',1,1);
INSERT INTO rubric_criterion VALUES(3761,'specialist-1-3-16',NULL,1,'Then x = q/p is rational, which contradicts x being irrational.',1,1);
INSERT INTO rubric_criterion VALUES(3762,'specialist-1-3-16',NULL,2,'So 1/x is irrational.',1,1);
INSERT INTO rubric_criterion VALUES(3766,'specialist-1-3-20',NULL,0,'Since log₂(5) > 0, assume log₂(5) = p/q with p, q positive integers. Then 2^(p/q) = 5, so 2ᵖ = 5^q.',1,1);
INSERT INTO rubric_criterion VALUES(3767,'specialist-1-3-20',NULL,1,'The left side is even (p ≥ 1) and the right side is odd, a contradiction.',1,1);
INSERT INTO rubric_criterion VALUES(3768,'specialist-1-3-20',NULL,2,'Hence log₂(5) is irrational.',1,1);
INSERT INTO rubric_criterion VALUES(3772,'specialist-1-3-24',NULL,0,'Contrapositive: if a and b are both odd, then ab is odd. Let a = 2m + 1 and b = 2n + 1.',1,1);
INSERT INTO rubric_criterion VALUES(3773,'specialist-1-3-24',NULL,1,'Then ab = 4mn + 2m + 2n + 1 = 2(2mn + m + n) + 1, which is odd.',1,1);
INSERT INTO rubric_criterion VALUES(3774,'specialist-1-3-24',NULL,2,'Hence the original statement holds.',1,1);
INSERT INTO rubric_criterion VALUES(3775,'specialist-1-3-25',NULL,0,'Assume such x and y exist. Then (x − y)(x + y) = 1.',1,1);
INSERT INTO rubric_criterion VALUES(3776,'specialist-1-3-25',NULL,1,'Since x + y ≥ 2 is a positive integer, the product of the integers x − y and x + y cannot be 1 (it would need x + y = 1).',1,1);
INSERT INTO rubric_criterion VALUES(3777,'specialist-1-3-25',NULL,2,'This is a contradiction.',1,1);
INSERT INTO rubric_criterion VALUES(3778,'specialist-1-3-c1',NULL,0,'Suppose \(\log_2 3 = \frac{p}{q}\) with \(p, q\) positive integers.',1,1);
INSERT INTO rubric_criterion VALUES(3779,'specialist-1-3-c1',NULL,1,'Then \(2^{p/q} = 3\), so \(2^p = 3^q\).',1,1);
INSERT INTO rubric_criterion VALUES(3780,'specialist-1-3-c1',NULL,2,'The left side is even and the right side is odd, a contradiction, so \(\log_2 3\) is irrational.',1,1);
INSERT INTO rubric_criterion VALUES(3784,'specialist-1-4-4',NULL,0,'Base: n = 1, LHS = 1 = 1(2)/2. Assume 1 + … + k = k(k + 1)/2.',1,1);
INSERT INTO rubric_criterion VALUES(3785,'specialist-1-4-4',NULL,1,'Then 1 + … + k + (k + 1) = k(k + 1)/2 + (k + 1) = (k + 1)(k + 2)/2, which is the formula for n = k + 1.',1,1);
INSERT INTO rubric_criterion VALUES(3786,'specialist-1-4-4',NULL,2,'By induction, the result holds for all n ∈ N.',1,1);
INSERT INTO rubric_criterion VALUES(3790,'specialist-1-4-8',NULL,0,'Base: 5¹ − 1 = 4. Assume 5ᵏ − 1 = 4m.',1,1);
INSERT INTO rubric_criterion VALUES(3791,'specialist-1-4-8',NULL,1,'Then 5^(k+1) − 1 = 5·5ᵏ − 1 = 5(4m + 1) − 1 = 20m + 4 = 4(5m + 1), which is divisible by 4.',1,1);
INSERT INTO rubric_criterion VALUES(3792,'specialist-1-4-8',NULL,2,'Hence true for all n ∈ N.',1,1);
INSERT INTO rubric_criterion VALUES(3796,'specialist-1-4-12',NULL,0,'Base: n = 1 gives 1 = 1. Assume the sum to k is k²(k + 1)²/4.',1,1);
INSERT INTO rubric_criterion VALUES(3797,'specialist-1-4-12',NULL,1,'Then adding (k + 1)³ gives (k + 1)²[k² + 4(k + 1)]/4 = (k + 1)²(k + 2)²/4 = ((k + 1)(k + 2)/2)².',1,1);
INSERT INTO rubric_criterion VALUES(3798,'specialist-1-4-12',NULL,2,'Hence true for all n.',1,1);
INSERT INTO rubric_criterion VALUES(3802,'specialist-1-4-16',NULL,0,'Base: n = 2 gives 9 > 5. Assume 3ᵏ > 2k + 1 for some k ≥ 2.',1,1);
INSERT INTO rubric_criterion VALUES(3803,'specialist-1-4-16',NULL,1,'Then 3^(k+1) = 3·3ᵏ > 3(2k + 1) = 6k + 3 = (2k + 3) + 4k > 2k + 3 = 2(k + 1) + 1, since 4k > 0.',1,1);
INSERT INTO rubric_criterion VALUES(3804,'specialist-1-4-16',NULL,2,'Hence true for all n ≥ 2.',1,1);
INSERT INTO rubric_criterion VALUES(3808,'specialist-1-4-20',NULL,0,'Base: 6 + 4 = 10 = 5 × 2. Assume 6ᵏ + 4 = 5m.',1,1);
INSERT INTO rubric_criterion VALUES(3809,'specialist-1-4-20',NULL,1,'Then 6^(k+1) + 4 = 6(6ᵏ + 4) − 20 = 30m − 20 = 5(6m − 4), which is divisible by 5.',1,1);
INSERT INTO rubric_criterion VALUES(3810,'specialist-1-4-20',NULL,2,'Hence true for all n ∈ N.',1,1);
INSERT INTO rubric_criterion VALUES(3814,'specialist-1-4-24',NULL,0,'Base: 2·3⁰ − 1 = 1 = a₁. Assume a_k = 2·3^(k−1) − 1.',1,1);
INSERT INTO rubric_criterion VALUES(3815,'specialist-1-4-24',NULL,1,'Then a_(k+1) = 3(2·3^(k−1) − 1) + 2 = 2·3ᵏ − 3 + 2 = 2·3ᵏ − 1, which is the formula for n = k + 1.',1,1);
INSERT INTO rubric_criterion VALUES(3816,'specialist-1-4-24',NULL,2,'Hence true for all n ∈ N.',1,1);
INSERT INTO rubric_criterion VALUES(3817,'specialist-1-4-25',NULL,0,'Base: 1 + 2 = 3. Assume k³ + 2k = 3m.',1,1);
INSERT INTO rubric_criterion VALUES(3818,'specialist-1-4-25',NULL,1,'Then (k + 1)³ + 2(k + 1) = k³ + 3k² + 3k + 1 + 2k + 2 = (k³ + 2k) + 3(k² + k + 1) = 3(m + k² + k + 1), which is divisible by 3.',1,1);
INSERT INTO rubric_criterion VALUES(3819,'specialist-1-4-25',NULL,2,'Hence true for all n ∈ N.',1,1);
INSERT INTO rubric_criterion VALUES(3820,'specialist-1-4-c1',NULL,0,'Base: \(5^1 - 1 = 4\).',1,1);
INSERT INTO rubric_criterion VALUES(3821,'specialist-1-4-c1',NULL,1,'Step: if \(5^k - 1 = 4m\), then \(5^{k+1} - 1 = 5 \cdot 5^k - 1 = 5(4m + 1) - 1 = 20m + 4 = 4(5m + 1)\).',1,1);
INSERT INTO rubric_criterion VALUES(3822,'specialist-1-4-c1',NULL,2,'So the statement holds for all \(n \in \mathbb{N}\).',1,1);
INSERT INTO rubric_criterion VALUES(3826,'specialist-2-1-4',NULL,0,'z = 3√2 cis(3π/4)',2,1);
INSERT INTO rubric_criterion VALUES(3830,'specialist-2-1-8',NULL,0,'a = 1, b = 3',2,1);
INSERT INTO rubric_criterion VALUES(3834,'specialist-2-1-12',NULL,0,'z/z̄ = −3/5 + (4/5)i',2,1);
INSERT INTO rubric_criterion VALUES(3838,'specialist-2-1-16',NULL,0,'±(3 − 2i)',2,1);
INSERT INTO rubric_criterion VALUES(3842,'specialist-2-1-20',NULL,0,'−2√3 − 2i',1,1);
INSERT INTO rubric_criterion VALUES(3846,'specialist-2-1-24',NULL,0,'z²w = 4cis(7π/12)',2,1);
INSERT INTO rubric_criterion VALUES(3847,'specialist-2-1-25',NULL,0,'z = −2i',2,1);
INSERT INTO rubric_criterion VALUES(3852,'specialist-2-2-4',NULL,0,'z = −2, 1 + √3 i, 1 − √3 i',2,1);
INSERT INTO rubric_criterion VALUES(3856,'specialist-2-2-8',NULL,0,'z = √3 − i, 1 + √3 i, −√3 + i, −1 − √3 i',2,1);
INSERT INTO rubric_criterion VALUES(3860,'specialist-2-2-12',NULL,0,'−512 + 512√3 i',2,1);
INSERT INTO rubric_criterion VALUES(3864,'specialist-2-2-16',NULL,0,'cos(4θ) = 8cos⁴θ − 8cos²θ + 1',2,1);
INSERT INTO rubric_criterion VALUES(3868,'specialist-2-2-20',NULL,0,'z = 1 + √3 i or z = −1 − √3 i',2,1);
INSERT INTO rubric_criterion VALUES(3872,'specialist-2-2-24',NULL,0,'−2',1,1);
INSERT INTO rubric_criterion VALUES(3873,'specialist-2-2-25',NULL,0,'n = 8, giving (1 − i)⁸ = 16',2,1);
INSERT INTO rubric_criterion VALUES(3874,'specialist-2-2-c1',NULL,0,'\(z = \pm\sqrt{2} \pm \sqrt{2}\,i\) (all four sign combinations)',3,1);
INSERT INTO rubric_criterion VALUES(3878,'specialist-2-3-4',NULL,0,'z = −1 ± 2i',2,1);
INSERT INTO rubric_criterion VALUES(3882,'specialist-2-3-8',NULL,0,'z = 1 + 2i and z = −1',2,1);
INSERT INTO rubric_criterion VALUES(3886,'specialist-2-3-12',NULL,0,'z = 1 + 2i or z = −1 + 2i',2,1);
INSERT INTO rubric_criterion VALUES(3890,'specialist-2-3-16',NULL,0,'(z − 2)(z + 2)(z − 2i)(z + 2i)',2,1);
INSERT INTO rubric_criterion VALUES(3894,'specialist-2-3-20',NULL,0,'a = 0, b = 1, third root z = −2',2,1);
INSERT INTO rubric_criterion VALUES(3898,'specialist-2-3-24',NULL,0,'z = i or z = −3i',2,1);
INSERT INTO rubric_criterion VALUES(3899,'specialist-2-3-25',NULL,0,'z = 2, 3i, −3i',2,1);
INSERT INTO rubric_criterion VALUES(3900,'specialist-2-3-c1',NULL,0,'\(a = -2\), \(b = 4\);',1,1);
INSERT INTO rubric_criterion VALUES(3901,'specialist-2-3-c1',NULL,1,'the other roots are \(1 - i\) and \(-2\)',2,1);
INSERT INTO rubric_criterion VALUES(3905,'specialist-2-4-4',NULL,0,'y = −x',2,1);
INSERT INTO rubric_criterion VALUES(3909,'specialist-2-4-8',NULL,0,'(x + 2)² + y² = 4: a circle with centre −2 and radius 2',2,1);
INSERT INTO rubric_criterion VALUES(3913,'specialist-2-4-12',NULL,0,'A closed annulus centred at the origin with inner radius 1 and outer radius 3;',1,1);
INSERT INTO rubric_criterion VALUES(3914,'specialist-2-4-12',NULL,1,'area = 8π.',2,1);
INSERT INTO rubric_criterion VALUES(3918,'specialist-2-4-16',NULL,0,'z = −1 + √3 i',2,1);
INSERT INTO rubric_criterion VALUES(3922,'specialist-2-4-20',NULL,0,'6',2,1);
INSERT INTO rubric_criterion VALUES(3926,'specialist-2-4-24',NULL,0,'xy = 4 (a rectangular hyperbola)',1,1);
INSERT INTO rubric_criterion VALUES(3927,'specialist-2-4-25',NULL,0,'z = 0 and z = 2 + 2i',2,1);
INSERT INTO rubric_criterion VALUES(3930,'specialist-3-1-2',NULL,0,'x² − 4x + 7 = (x − 2)² + 3, so y = x − 2 + 3/(x − 2).',1,1);
INSERT INTO rubric_criterion VALUES(3931,'specialist-3-1-2',NULL,1,'Vertical asymptote x = 2;',1,1);
INSERT INTO rubric_criterion VALUES(3932,'specialist-3-1-2',NULL,2,'oblique asymptote y = x − 2.',1,1);
INSERT INTO rubric_criterion VALUES(3934,'specialist-3-1-4',NULL,0,'dy/dx = (1 − x²)/(x² + 1)² = 0 at x = ±1.',1,1);
INSERT INTO rubric_criterion VALUES(3935,'specialist-3-1-4',NULL,1,'Local maximum (1, 1/2) and local minimum (−1, −1/2).',2,1);
INSERT INTO rubric_criterion VALUES(3939,'specialist-3-1-8',NULL,0,'y = 3 + 2/(x + 1).',1,1);
INSERT INTO rubric_criterion VALUES(3940,'specialist-3-1-8',NULL,1,'Asymptotes: x = −1 and y = 3.',1,1);
INSERT INTO rubric_criterion VALUES(3944,'specialist-3-1-12',NULL,0,'k = 3',2,1);
INSERT INTO rubric_criterion VALUES(3948,'specialist-3-1-16',NULL,0,'x = 2 or x = 1/2',2,1);
INSERT INTO rubric_criterion VALUES(3952,'specialist-3-1-20',NULL,0,'y = 1 + 2/(x² − 1). Vertical asymptotes x = 1 and x = −1;',1,1);
INSERT INTO rubric_criterion VALUES(3953,'specialist-3-1-20',NULL,1,'horizontal asymptote y = 1; y-intercept (0, −1).',1,1);
INSERT INTO rubric_criterion VALUES(3957,'specialist-3-1-24',NULL,0,'Stationary point: 2x + 8/x² = 0 gives x³ = −4, so x = −∛4 and y = 3∛16 (≈ (−1.59, 7.56)).',1,1);
INSERT INTO rubric_criterion VALUES(3958,'specialist-3-1-24',NULL,1,'x-intercept: x³ = 8, so (2, 0).',2,1);
INSERT INTO rubric_criterion VALUES(3962,'specialist-3-2-2',NULL,0,'LHS = 1/cos²x + 1/sin²x = (sin²x + cos²x)/(sin²x cos²x) = 1/(sin²x cos²x) = sec²x cosec²x = RHS.',3,1);
INSERT INTO rubric_criterion VALUES(3964,'specialist-3-2-4',NULL,0,'x = 7π/6 or x = 11π/6',2,1);
INSERT INTO rubric_criterion VALUES(3968,'specialist-3-2-8',NULL,0,'sec x = −√5/2 and cosec x = √5.',2,1);
INSERT INTO rubric_criterion VALUES(3972,'specialist-3-2-12',NULL,0,'x = 0, π/3, 5π/3, 2π',2,1);
INSERT INTO rubric_criterion VALUES(3976,'specialist-3-2-16',NULL,0,'Local minimum (0, 1), local maximum (π, −1);',1,1);
INSERT INTO rubric_criterion VALUES(3977,'specialist-3-2-16',NULL,1,'asymptote x = π/2.',1,1);
INSERT INTO rubric_criterion VALUES(3981,'specialist-3-2-20',NULL,0,'tan x',2,1);
INSERT INTO rubric_criterion VALUES(3985,'specialist-3-2-24',NULL,0,'a = 3, b = 2',2,1);
INSERT INTO rubric_criterion VALUES(3987,'specialist-3-2-c1',NULL,0,'\(x = 0\) or \(x = \frac{\pi}{4}\)',2,1);
INSERT INTO rubric_criterion VALUES(3989,'specialist-3-3-2',NULL,0,'7/9',2,1);
INSERT INTO rubric_criterion VALUES(3991,'specialist-3-3-4',NULL,0,'Domain [0, 2];',1,1);
INSERT INTO rubric_criterion VALUES(3992,'specialist-3-3-4',NULL,1,'range [0, 2π].',1,1);
INSERT INTO rubric_criterion VALUES(3996,'specialist-3-3-8',NULL,0,'x = √3/6 (= 1/(2√3))',2,1);
INSERT INTO rubric_criterion VALUES(4000,'specialist-3-3-12',NULL,0,'Let θ = tan⁻¹x, θ ∈ (−π/2, π/2), so cos θ > 0 and sec θ = √(1 + x²).',1,1);
INSERT INTO rubric_criterion VALUES(4001,'specialist-3-3-12',NULL,1,'Then sin θ = tan θ cos θ = x/√(1 + x²).',1,1);
INSERT INTO rubric_criterion VALUES(4005,'specialist-3-3-16',NULL,0,'tan(sum) = (2 + 3)/(1 − 2×3) = −1.',1,1);
INSERT INTO rubric_criterion VALUES(4006,'specialist-3-3-16',NULL,1,'Both angles lie in (π/4, π/2), so the sum lies in (π/2, π);',1,1);
INSERT INTO rubric_criterion VALUES(4007,'specialist-3-3-16',NULL,2,'hence tan⁻¹2 + tan⁻¹3 = 3π/4.',1,1);
INSERT INTO rubric_criterion VALUES(4011,'specialist-3-3-20',NULL,0,'π/3.',1,1);
INSERT INTO rubric_criterion VALUES(4012,'specialist-3-3-20',NULL,1,'sin(2π/3) = √3/2, and sin⁻¹ returns a value in [−π/2, π/2];',1,1);
INSERT INTO rubric_criterion VALUES(4013,'specialist-3-3-20',NULL,2,'2π/3 is outside this range.',1,1);
INSERT INTO rubric_criterion VALUES(4017,'specialist-3-3-24',NULL,0,'Domain [−√2, √2];',1,1);
INSERT INTO rubric_criterion VALUES(4018,'specialist-3-3-24',NULL,1,'range [−π/2, π/2].',1,1);
INSERT INTO rubric_criterion VALUES(4022,'specialist-3-4-2',NULL,0,'LHS = (sin A cos B + cos A sin B) + (sin A cos B − cos A sin B) = 2 sin A cos B = RHS.',2,1);
INSERT INTO rubric_criterion VALUES(4024,'specialist-3-4-4',NULL,0,'x = 0, 2π/3, 4π/3, 2π',2,1);
INSERT INTO rubric_criterion VALUES(4028,'specialist-3-4-8',NULL,0,'x = 0, π/3, π, 5π/3, 2π',2,1);
INSERT INTO rubric_criterion VALUES(4032,'specialist-3-4-12',NULL,0,'cos(π/8) = √(2 + √2)/2',2,1);
INSERT INTO rubric_criterion VALUES(4036,'specialist-3-4-16',NULL,0,'56/65',2,1);
INSERT INTO rubric_criterion VALUES(4040,'specialist-3-4-20',NULL,0,'LHS = 2 sin x cos x/(1 + 2cos²x − 1) = 2 sin x cos x/(2cos²x) = sin x/cos x = tan x = RHS.',2,1);
INSERT INTO rubric_criterion VALUES(4044,'specialist-3-4-24',NULL,0,'cos(2x + x) = cos 2x cos x − sin 2x sin x = (2cos²x − 1)cos x − 2 sin²x cos x = 2cos³x − cos x − 2(1 − cos²x)cos x = 4cos³x − 3cos x.',3,1);
INSERT INTO rubric_criterion VALUES(4050,'specialist-4-1-4',NULL,0,'(2/9)(x³ − 1)^(3/2) + c',3,1);
INSERT INTO rubric_criterion VALUES(4054,'specialist-4-1-8',NULL,0,'½log_e(2)',2,1);
INSERT INTO rubric_criterion VALUES(4058,'specialist-4-1-12',NULL,0,'(2/5)(x + 1)^(5/2) − (2/3)(x + 1)^(3/2) + c',3,1);
INSERT INTO rubric_criterion VALUES(4062,'specialist-4-1-16',NULL,0,'e − 1',2,1);
INSERT INTO rubric_criterion VALUES(4066,'specialist-4-1-20',NULL,0,'−cos(x) + ⅓cos³(x) + c',2,1);
INSERT INTO rubric_criterion VALUES(4070,'specialist-4-1-24',NULL,0,'x/2 + ¼sin(2x) + c',2,1);
INSERT INTO rubric_criterion VALUES(4071,'specialist-4-1-25',NULL,0,'2log_e(3/2)',2,1);
INSERT INTO rubric_criterion VALUES(4072,'specialist-4-1-c1',NULL,0,'\(\dfrac{2}{5}(x - 1)^{5/2} + \dfrac{2}{3}(x - 1)^{3/2} + c\)',3,1);
INSERT INTO rubric_criterion VALUES(4076,'specialist-4-2-4',NULL,0,'4/(5(x + 1)) + (9 − 4x)/(5(x² + 4))',3,1);
INSERT INTO rubric_criterion VALUES(4080,'specialist-4-2-8',NULL,0,'(4/5)log_e|x + 1| − (2/5)log_e(x² + 4) + (9/10)tan⁻¹(x/2) + c',3,1);
INSERT INTO rubric_criterion VALUES(4084,'specialist-4-2-12',NULL,0,'log_e(9/2)',2,1);
INSERT INTO rubric_criterion VALUES(4088,'specialist-4-2-16',NULL,0,'x + ½log_e|(x − 1)/(x + 1)| + c',2,1);
INSERT INTO rubric_criterion VALUES(4092,'specialist-4-2-20',NULL,0,'2log_e(3/2) (equivalently log_e(9/4))',2,1);
INSERT INTO rubric_criterion VALUES(4096,'specialist-4-2-24',NULL,0,'3log_e|x − 1| − 2/(x − 1) + c',2,1);
INSERT INTO rubric_criterion VALUES(4097,'specialist-4-2-25',NULL,0,'log_e(N/(1 − N)) + c',3,1);
INSERT INTO rubric_criterion VALUES(4102,'specialist-4-3-4',NULL,0,'π/(4√3) = √3π/12',2,1);
INSERT INTO rubric_criterion VALUES(4106,'specialist-4-3-8',NULL,0,'log_e(x² + 1) + 3tan⁻¹(x) + c',2,1);
INSERT INTO rubric_criterion VALUES(4110,'specialist-4-3-12',NULL,0,'½tan⁻¹((x − 3)/2) + c',2,1);
INSERT INTO rubric_criterion VALUES(4114,'specialist-4-3-16',NULL,0,'π/4',1,1);
INSERT INTO rubric_criterion VALUES(4118,'specialist-4-3-20',NULL,0,'−√(1 − x²) + 2sin⁻¹(x) + c',2,1);
INSERT INTO rubric_criterion VALUES(4122,'specialist-4-3-24',NULL,0,'π/2 − 1',2,1);
INSERT INTO rubric_criterion VALUES(4123,'specialist-4-3-25',NULL,0,'π/8',1,1);
INSERT INTO rubric_criterion VALUES(4128,'specialist-4-4-4',NULL,0,'π²/2',1,1);
INSERT INTO rubric_criterion VALUES(4132,'specialist-4-4-8',NULL,0,'14/3',1,1);
INSERT INTO rubric_criterion VALUES(4136,'specialist-4-4-12',NULL,0,'13π/3',2,1);
INSERT INTO rubric_criterion VALUES(4140,'specialist-4-4-16',NULL,0,'64π/15',2,1);
INSERT INTO rubric_criterion VALUES(4144,'specialist-4-4-20',NULL,0,'162π cm³ ≈ 508.9 cm³',1,1);
INSERT INTO rubric_criterion VALUES(4148,'specialist-4-4-24',NULL,0,'log_e(√2 + 1)',1,1);
INSERT INTO rubric_criterion VALUES(4149,'specialist-4-4-25',NULL,0,'(π/27)(10√10 − 1)',2,1);
INSERT INTO rubric_criterion VALUES(4150,'specialist-4-4-c1',NULL,0,'\(\frac{14}{3}\)',1,1);
INSERT INTO rubric_criterion VALUES(4169,'specialist-5-1-19',NULL,0,'∫ y^(−2) dy = ∫ x dx gives −1/y = x²/2 + c.',1,1);
INSERT INTO rubric_criterion VALUES(4170,'specialist-5-1-19',NULL,1,'y(0) = 1 gives c = −1, so y = 2/(2 − x²), valid for −√2 < x < √2.',2,1);
INSERT INTO rubric_criterion VALUES(4171,'specialist-5-1-20',NULL,0,'dy/dx = 6e^(2x).',1,1);
INSERT INTO rubric_criterion VALUES(4172,'specialist-5-1-20',NULL,1,'Also 2y + 2 = 2(3e^(2x) − 1) + 2 = 6e^(2x).',1,1);
INSERT INTO rubric_criterion VALUES(4173,'specialist-5-1-20',NULL,2,'Since both sides are equal, y = 3e^(2x) − 1 is a solution.',1,1);
INSERT INTO rubric_criterion VALUES(4174,'specialist-5-1-21',NULL,0,'∫ 1/(1 + y) dy = ∫ 1/x dx gives log_e|1 + y| = log_e(x) + c, so 1 + y = Ax.',1,1);
INSERT INTO rubric_criterion VALUES(4175,'specialist-5-1-21',NULL,1,'y(1) = 1 gives A = 2, so y = 2x − 1.',2,1);
INSERT INTO rubric_criterion VALUES(4176,'specialist-5-1-22',NULL,0,'N = 500e^(kt) with e^(2k) = 3, so k = log_e(3)/2 and N = 500 × 3^(t/2).',1,1);
INSERT INTO rubric_criterion VALUES(4177,'specialist-5-1-22',NULL,1,'For 10 000: 3^(t/2) = 20, so t = 2 log_e(20)/log_e(3) ≈ 5.45 hours.',1,1);
INSERT INTO rubric_criterion VALUES(4178,'specialist-5-1-23',NULL,0,'∫ y^(−1/2) dy = ∫ 4x dx gives 2√y = 2x² + c.',1,1);
INSERT INTO rubric_criterion VALUES(4179,'specialist-5-1-23',NULL,1,'y(0) = 1 gives c = 2, so √y = x² + 1 and y = (x² + 1)².',1,1);
INSERT INTO rubric_criterion VALUES(4180,'specialist-5-1-24',NULL,0,'∫ 1/(y − 1) dy = ∫ 2x dx gives log_e|y − 1| = x² + c, so y − 1 = Ae^(x²).',1,1);
INSERT INTO rubric_criterion VALUES(4181,'specialist-5-1-24',NULL,1,'y(0) = 4 gives A = 3, so y = 1 + 3e^(x²).',2,1);
INSERT INTO rubric_criterion VALUES(4182,'specialist-5-1-25',NULL,0,'e^y dy = x dx gives e^y = x²/2 + c.',1,1);
INSERT INTO rubric_criterion VALUES(4183,'specialist-5-1-25',NULL,1,'y(0) = 0 gives c = 1, so y = log_e(x²/2 + 1).',1,1);
INSERT INTO rubric_criterion VALUES(4184,'specialist-5-1-c1',NULL,0,'\(y = 2e^{x^2/2}\)',2,1);
INSERT INTO rubric_criterion VALUES(4203,'specialist-5-2-19',NULL,0,'Using partial fractions, (1/P + 1/(1000 − P)) dP = 0.5 dt, so log_e(P/(1000 − P)) = 0.5t + c.',1,1);
INSERT INTO rubric_criterion VALUES(4204,'specialist-5-2-19',NULL,1,'With P(0) = 100, P/(1000 − P) = (1/9)e^(0.5t), giving P = 1000/(1 + 9e^(−0.5t)).',2,1);
INSERT INTO rubric_criterion VALUES(4205,'specialist-5-2-20',NULL,0,'1 + 9e^(−0.5t) = 10/9, so 9e^(−0.5t) = 1/9 and e^(−0.5t) = 1/81.',1,1);
INSERT INTO rubric_criterion VALUES(4206,'specialist-5-2-20',NULL,1,'Thus t = 2 log_e(81) = 8 log_e(3) ≈ 8.79.',2,1);
INSERT INTO rubric_criterion VALUES(4207,'specialist-5-2-21',NULL,0,'Let f(P) = rP − rP²/K.',1,1);
INSERT INTO rubric_criterion VALUES(4208,'specialist-5-2-21',NULL,1,'f′(P) = r − 2rP/K = 0 gives P = K/2.',1,1);
INSERT INTO rubric_criterion VALUES(4209,'specialist-5-2-21',NULL,2,'f″(P) = −2r/K < 0, so this is a maximum, with maximum rate rK/4.',1,1);
INSERT INTO rubric_criterion VALUES(4210,'specialist-5-2-22',NULL,0,'r = 0.0001 × 10 000 = 1, K = 10 000, A = 9990/10 = 999, so N = 10 000/(1 + 999e^(−t)).',1,1);
INSERT INTO rubric_criterion VALUES(4211,'specialist-5-2-22',NULL,1,'N = 5000 when 999e^(−t) = 1, so t = log_e(999) ≈ 6.91 days.',1,1);
INSERT INTO rubric_criterion VALUES(4212,'specialist-5-2-23',NULL,0,'2P − 0.01P² = 2P(1 − P/200), so r = 2, K = 200.',1,1);
INSERT INTO rubric_criterion VALUES(4213,'specialist-5-2-23',NULL,1,'A = (200 − 50)/50 = 3, giving P = 200/(1 + 3e^(−2t)).',1,1);
INSERT INTO rubric_criterion VALUES(4214,'specialist-5-2-24',NULL,0,'r is the intrinsic (per-capita) growth rate when the population is small and resources are unlimited.',1,1);
INSERT INTO rubric_criterion VALUES(4215,'specialist-5-2-24',NULL,1,'K is the carrying capacity: the maximum population the environment can sustain long-term, where births and deaths balance.',1,1);
INSERT INTO rubric_criterion VALUES(4216,'specialist-5-2-25',NULL,0,'A = 800/200 = 4.',1,1);
INSERT INTO rubric_criterion VALUES(4217,'specialist-5-2-25',NULL,1,'400 = 1000/(1 + 4e^(−3r)) gives 1 + 4e^(−3r) = 2.5, so e^(−3r) = 3/8 and r = (1/3)log_e(8/3) ≈ 0.327.',1,1);
INSERT INTO rubric_criterion VALUES(4237,'specialist-5-3-19',NULL,0,'y₁ = 1 + 0.1(0 + 1) = 1.1; y₂ = 1.1 + 0.1(0.01 + 1.1) = 1.211;',1,1);
INSERT INTO rubric_criterion VALUES(4238,'specialist-5-3-19',NULL,1,'y₃ = 1.211 + 0.1(0.04 + 1.211) = 1.3361.',1,1);
INSERT INTO rubric_criterion VALUES(4239,'specialist-5-3-19',NULL,2,'So y(0.3) ≈ 1.3361.',1,1);
INSERT INTO rubric_criterion VALUES(4240,'specialist-5-3-20',NULL,0,'Underestimate.',1,1);
INSERT INTO rubric_criterion VALUES(4241,'specialist-5-3-20',NULL,1,'The exact solution y = e^x has d²y/dx² = e^x > 0, so it is concave up and the tangent-line steps lie below the curve.',2,1);
INSERT INTO rubric_criterion VALUES(4242,'specialist-5-3-21',NULL,0,'Segments are horizontal along y = 0 and y = 3 (equilibrium solutions). Gradients are positive for 0 < y < 3 and negative for y > 3 and y < 0.',1,1);
INSERT INTO rubric_criterion VALUES(4243,'specialist-5-3-21',NULL,1,'Slopes depend only on y, so they are identical along any horizontal line;',1,1);
INSERT INTO rubric_criterion VALUES(4244,'specialist-5-3-21',NULL,2,'y = 3 is stable and y = 0 unstable.',1,1);
INSERT INTO rubric_criterion VALUES(4245,'specialist-5-3-22',NULL,0,'y₁ = 0 + 0.5(1) = 0.5;',1,1);
INSERT INTO rubric_criterion VALUES(4246,'specialist-5-3-22',NULL,1,'y₂ = 0.5 + 0.5(1/1.25) = 0.9.',1,1);
INSERT INTO rubric_criterion VALUES(4247,'specialist-5-3-22',NULL,2,'Exact y(1) = tan⁻¹(1) = π/4 ≈ 0.785, so Euler overestimates by about 0.115.',1,1);
INSERT INTO rubric_criterion VALUES(4248,'specialist-5-3-23',NULL,0,'At (3, 2): 3/2 = 1.5.',1,1);
INSERT INTO rubric_criterion VALUES(4249,'specialist-5-3-23',NULL,1,'At (−3, 2): −3/2 = −1.5.',1,1);
INSERT INTO rubric_criterion VALUES(4250,'specialist-5-3-23',NULL,2,'Gradients at (x, y) and (−x, y) are negatives, so the slope field is symmetric (a reflection) about the y-axis.',1,1);
INSERT INTO rubric_criterion VALUES(4251,'specialist-5-3-24',NULL,0,'Each step multiplies by 1 + 0.25 × 2 = 1.5, so y(1) ≈ 1.5⁴ = 5.0625.',1,1);
INSERT INTO rubric_criterion VALUES(4252,'specialist-5-3-24',NULL,1,'Exact value e² ≈ 7.389, so the error ≈ 2.33, about 31.5% of the exact value.',2,1);
INSERT INTO rubric_criterion VALUES(4253,'specialist-5-3-25',NULL,0,'y₁ = 2 + 0.5 log_e(1) = 2;',1,1);
INSERT INTO rubric_criterion VALUES(4254,'specialist-5-3-25',NULL,1,'y₂ = 2 + 0.5 log_e(1.5) ≈ 2 + 0.2027 = 2.20.',1,1);
INSERT INTO rubric_criterion VALUES(4255,'specialist-5-3-c1',NULL,0,'\(y(0.2) \approx 1.22\)',3,1);
INSERT INTO rubric_criterion VALUES(4274,'specialist-5-4-19',NULL,0,'dQ/dt = 2 − 8Q/400 = 2 − Q/50. Solving with Q(0) = 0 gives Q = 100(1 − e^(−t/50)).',1,1);
INSERT INTO rubric_criterion VALUES(4275,'specialist-5-4-19',NULL,1,'Q(50) = 100(1 − e^(−1)) ≈ 63.2 kg.',1,1);
INSERT INTO rubric_criterion VALUES(4276,'specialist-5-4-20',NULL,0,'V = 100 − 2t, so dQ/dt = −5Q/(100 − 2t). Separating: log_e Q = (5/2)log_e(100 − 2t) + c.',1,1);
INSERT INTO rubric_criterion VALUES(4277,'specialist-5-4-20',NULL,1,'With Q(0) = 10, Q = 10((100 − 2t)/100)^(5/2).',1,1);
INSERT INTO rubric_criterion VALUES(4278,'specialist-5-4-21',NULL,0,'1 − e^(−t/50) = 0.75 gives e^(−t/50) = 0.25, so t = 50 log_e(4) = 100 log_e(2) ≈ 69.3 minutes.',2,1);
INSERT INTO rubric_criterion VALUES(4279,'specialist-5-4-22',NULL,0,'dA/dt = 10 − 0.25A. Solving gives A = 40(1 − e^(−0.25t)). As t → ∞, A → 40 mg.',1,1);
INSERT INTO rubric_criterion VALUES(4280,'specialist-5-4-23',NULL,0,'The solution is perfectly (instantaneously) mixed, so the concentration is uniform at Q/V.',1,1);
INSERT INTO rubric_criterion VALUES(4281,'specialist-5-4-23',NULL,1,'The flow rates and inflow concentration are constant, and salt is neither created nor destroyed in the tank.',1,1);
INSERT INTO rubric_criterion VALUES(4282,'specialist-5-4-24',NULL,0,'T = 20 + 160e^(−kt). 80 = 160e^(−10k) gives k = log_e(2)/10 ≈ 0.0693.',1,1);
INSERT INTO rubric_criterion VALUES(4283,'specialist-5-4-24',NULL,1,'For 30°C: e^(−kt) = 1/16, so t = 4 × 10 = 40 minutes.',1,1);
INSERT INTO rubric_criterion VALUES(4284,'specialist-5-4-25',NULL,0,'Equilibrium is A = 500 000, so A = 500 000 + (400 000 − 500 000)e^(0.04t) = 500 000 − 100 000e^(0.04t).',1,1);
INSERT INTO rubric_criterion VALUES(4285,'specialist-5-4-25',NULL,1,'A = 0 when e^(0.04t) = 5, so t = 25 log_e(5) ≈ 40.2 years.',1,1);
INSERT INTO rubric_criterion VALUES(4286,'specialist-5-4-c1',NULL,0,'\(Q = 20 - 10e^{-t/20}\)',1,1);
INSERT INTO rubric_criterion VALUES(4305,'specialist-6-1-19',NULL,0,'a = v dv/dx = e^(−x) × (−e^(−x)) = −e^(−2x) m/s².',1,1);
INSERT INTO rubric_criterion VALUES(4306,'specialist-6-1-20',NULL,0,'½v² = x³ + c, and v = 2 at x = 0 gives c = 2, so v² = 2x³ + 4.',1,1);
INSERT INTO rubric_criterion VALUES(4307,'specialist-6-1-20',NULL,1,'At x = 2, v² = 20 and v = 2√5 ≈ 4.47 m/s.',1,1);
INSERT INTO rubric_criterion VALUES(4308,'specialist-6-1-21',NULL,0,'44.1 = ½(9.8)t² gives t² = 9, so t = 3 s.',1,1);
INSERT INTO rubric_criterion VALUES(4309,'specialist-6-1-21',NULL,1,'Then v = 9.8 × 3 = 29.4 m/s.',1,1);
INSERT INTO rubric_criterion VALUES(4310,'specialist-6-1-22',NULL,0,'v = 6e^(−2t), so x = ∫v dt = 3(1 − e^(−2t)). As t → ∞, x → 3 m.',1,1);
INSERT INTO rubric_criterion VALUES(4311,'specialist-6-1-23',NULL,0,'x = 4t − t³/3. It changes direction at t = 2, where x = 16/3.',1,1);
INSERT INTO rubric_criterion VALUES(4312,'specialist-6-1-23',NULL,1,'Then x(3) = 3. Distance = 16/3 + (16/3 − 3) = 23/3 ≈ 7.67 m.',1,1);
INSERT INTO rubric_criterion VALUES(4313,'specialist-6-1-24',NULL,0,'v² = u² + 2as: 900 = 100 + 800a, so a = 1 m/s². t = (30 − 10)/1 = 20 s.',1,1);
INSERT INTO rubric_criterion VALUES(4314,'specialist-6-1-25',NULL,0,'v = 3t² − 6t and a = 6t − 6.',1,1);
INSERT INTO rubric_criterion VALUES(4315,'specialist-6-1-25',NULL,1,'a = 0 at t = 1 s, where v = 3 − 6 = −3 m/s (speed 3 m/s in the negative direction).',2,1);
INSERT INTO rubric_criterion VALUES(4316,'specialist-6-1-c1',NULL,0,'\(v^2 = 36 - 4x^2\); greatest distance 3 m',1,1);
INSERT INTO rubric_criterion VALUES(4335,'specialist-6-2-19',NULL,0,'Terminal velocity: 40v = 800, so v = 20 m/s.',1,1);
INSERT INTO rubric_criterion VALUES(4336,'specialist-6-2-19',NULL,1,'At v = 10: a = (800 − 400)/400 = 1 m/s².',1,1);
INSERT INTO rubric_criterion VALUES(4337,'specialist-6-2-20',NULL,0,'a = (6 − 2)g/8 = 4.9 m/s², so v = 4.9 × 1.5 = 7.35 m/s.',2,1);
INSERT INTO rubric_criterion VALUES(4338,'specialist-6-2-21',NULL,0,'9000 − 800(9.8) = 800a gives 1160 = 800a, so a = 1.45 m/s² upward.',1,1);
INSERT INTO rubric_criterion VALUES(4339,'specialist-6-2-22',NULL,0,'2 dv/dt = 4 − 2v, so dv/dt = 2 − v.',1,1);
INSERT INTO rubric_criterion VALUES(4340,'specialist-6-2-22',NULL,1,'Solving gives v = 2(1 − e^(−t)), and v → 2 m/s.',1,1);
INSERT INTO rubric_criterion VALUES(4341,'specialist-6-2-23',NULL,0,'R = 2i + 6j N, so a = i + 3j m/s². |a| = √10 ≈ 3.16 m/s².',1,1);
INSERT INTO rubric_criterion VALUES(4342,'specialist-6-2-24',NULL,0,'a = 27/9 = 3 m/s². D − 600 = 1200 × 3, so D = 4200 N.',1,1);
INSERT INTO rubric_criterion VALUES(4343,'specialist-6-2-25',NULL,0,'For the person, mg − R = ma. In free fall a = g, so R = m(g − g) = 0.',1,1);
INSERT INTO rubric_criterion VALUES(4344,'specialist-6-2-25',NULL,1,'With no normal reaction from the floor, they feel weightless, even though their weight mg is unchanged.',1,1);
INSERT INTO rubric_criterion VALUES(4345,'specialist-6-2-c1',NULL,0,'\(a = 1.96\) m/s²; \(T = 23.52\) N',1,1);
