INSERT INTO rubric_criterion VALUES(4583,'specialist-8-2-21',NULL,0,'The CLT says that for a sufficiently large sample size, the distribution of X̄ is approximately normal with mean μ and standard deviation σ/√n, whatever the population''s shape.',2,1);
INSERT INTO rubric_criterion VALUES(4584,'specialist-8-2-22',NULL,0,'1.8/√n < 0.2 gives √n > 9, so n > 81. The smallest sample size is n = 82.',1,1);
