INSERT INTO rubric_criterion VALUES(4610,'specialist-8-3-19',NULL,1,'Interval ≈ (6.90, 7.50) hours.',1,1);
INSERT INTO rubric_criterion VALUES(4611,'specialist-8-3-20',NULL,0,'If the sampling were repeated many times and an interval constructed each time, about 95% of those intervals would contain the true population mean.',1,1);
INSERT INTO rubric_criterion VALUES(4612,'specialist-8-3-20',NULL,1,'(12.4, 15.6) is one such interval, giving a plausible range for μ.',1,1);
INSERT INTO rubric_criterion VALUES(4613,'specialist-8-3-21',NULL,0,'n ≥ (2.576 × 4/0.5)² = 20.608² ≈ 424.7, so n = 425.',2,1);
INSERT INTO rubric_criterion VALUES(4614,'specialist-8-3-22',NULL,0,'μ is a fixed (unknown) constant and the interval is now fixed, so μ either is or is not in it.',1,1);
INSERT INTO rubric_criterion VALUES(4615,'specialist-8-3-22',NULL,1,'The 95% describes the proportion of intervals that would capture μ in repeated sampling.',2,1);
INSERT INTO rubric_criterion VALUES(4616,'specialist-8-3-23',NULL,0,'x̄ = (12.4 + 15.6)/2 = 14.',1,1);
INSERT INTO rubric_criterion VALUES(4617,'specialist-8-3-23',NULL,1,'Margin 1.6 = 1.96σ/10, so σ = 16/1.96 ≈ 8.16.',1,1);
INSERT INTO rubric_criterion VALUES(4618,'specialist-8-3-24',NULL,0,'500 g is outside the interval, so it is not a plausible value for μ at the 99% level.',1,1);
INSERT INTO rubric_criterion VALUES(4619,'specialist-8-3-24',NULL,1,'There is evidence (at the 1% level of significance) that the mean mass is less than 500 g.',2,1);
INSERT INTO rubric_criterion VALUES(4620,'specialist-8-3-25',NULL,0,'Width depends on the confidence level (z-value), the population standard deviation σ and the sample size n.',1,1);
