INSERT INTO rubric_criterion VALUES(4643,'specialist-8-4-19',NULL,2,'Since 0.0228 < 0.05, reject H₀: there is evidence the mean temperature is less than 65 °C.',1,1);
INSERT INTO rubric_criterion VALUES(4644,'specialist-8-4-20',NULL,0,'z = 3/1.5 = 2, so p = 2Pr(Z ≥ 2) ≈ 0.0455.',1,1);
