INSERT INTO rubric_criterion VALUES(4646,'specialist-8-4-21',NULL,0,'The p-value is the probability of obtaining a sample statistic at least as extreme as the one observed, assuming the null hypothesis is true.',1,1);
INSERT INTO rubric_criterion VALUES(4647,'specialist-8-4-22',NULL,0,'Type I: concluding the mean life is less than 30 hours when it actually is 30 hours.',1,1);
INSERT INTO rubric_criterion VALUES(4648,'specialist-8-4-22',NULL,1,'Type II: concluding there is no evidence against the claim (mean 30 hours) when the mean life is actually less than 30 hours.',1,1);
INSERT INTO rubric_criterion VALUES(4649,'specialist-8-4-23',NULL,0,'Standard error = 8/8 = 1. Reject H₀ if x̄ < 60 − 1.645 × 1, i.e.',1,1);
INSERT INTO rubric_criterion VALUES(4650,'specialist-8-4-23',NULL,1,'x̄ < 58.355 (approximately 58.36).',1,1);
INSERT INTO rubric_criterion VALUES(4651,'specialist-8-4-24',NULL,0,'H₀: μ = μ₀ is rejected in a two-tailed test at the 5% level exactly when μ₀ lies outside the 95% confidence interval (using the same σ and sample).',2,1);
INSERT INTO rubric_criterion VALUES(4652,'specialist-8-4-25',NULL,0,'Critical value: x̄ > 50 + 1.645 × 2 = 53.29.',1,1);
INSERT INTO rubric_criterion VALUES(4653,'specialist-8-4-25',NULL,1,'Pr(Type II) = Pr(X̄ < 53.29 | μ = 55) = Pr(Z < (53.29 − 55)/2) = Pr(Z < −0.855) ≈ 0.20.',2,1);
INSERT INTO rubric_criterion VALUES(4658,'chem-1-1-4',NULL,0,'Fossil fuels are burnt to power farm machinery, make fertilisers, transport the crop and heat the distillation process, so the total CO₂ released exceeds the CO₂ absorbed by the crop during photosynthesis.',2,1);
INSERT INTO rubric_criterion VALUES(4662,'chem-1-1-8',NULL,0,'Fatty acid methyl esters (biodiesel) and glycerol;',1,1);
INSERT INTO rubric_criterion VALUES(4663,'chem-1-1-8',NULL,1,'the methyl esters are the biodiesel fuel.',1,1);
INSERT INTO rubric_criterion VALUES(4667,'chem-1-1-12',NULL,0,'Biodiesel contains ester functional groups whose oxygen atoms can accept hydrogen bonds from water molecules, so it attracts and absorbs water.',1,1);
INSERT INTO rubric_criterion VALUES(4668,'chem-1-1-12',NULL,1,'Petrodiesel consists of non-polar hydrocarbons that cannot hydrogen bond with water.',1,1);
INSERT INTO rubric_criterion VALUES(4672,'chem-1-1-16',NULL,0,'Advantage: ethanol is renewable and can lower net greenhouse emissions (it also burns more cleanly). Disadvantage: ethanol releases less energy per gram than petrol, so fuel consumption increases (or it absorbs water, or crops compete with food).',1,1);
INSERT INTO rubric_criterion VALUES(4676,'chem-1-1-20',NULL,0,'A renewable fuel can be replaced by natural processes within a relatively short (human) timescale, e.g. biogas from a Gippsland dairy farm.',1,1);
INSERT INTO rubric_criterion VALUES(4677,'chem-1-1-20',NULL,1,'A non-renewable fuel is used faster than it can be replaced, taking millions of years to form, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(4678,'chem-1-1-20',NULL,2,'Latrobe Valley brown coal.',1,1);
INSERT INTO rubric_criterion VALUES(4682,'chem-1-1-24',NULL,0,'The gas is biogas, mainly methane, produced by anaerobic bacteria digesting manure.',1,1);
INSERT INTO rubric_criterion VALUES(4683,'chem-1-1-24',NULL,1,'The manure is continuously replaced by the cows'' feed, which is regrown each season, so the fuel source is replenished within a short timescale.',1,1);
INSERT INTO rubric_criterion VALUES(4684,'chem-1-1-25',NULL,0,'Ethanol has a polar O–H group that forms hydrogen bonds with water molecules, so it is miscible.',1,1);
INSERT INTO rubric_criterion VALUES(4685,'chem-1-1-25',NULL,1,'Octane is non-polar and has only dispersion forces, which cannot compete with the hydrogen bonding between water molecules, so it does not dissolve.',2,1);
INSERT INTO rubric_criterion VALUES(4691,'chem34a1-ffb-6',NULL,0,'C₆H₁₂O₆(aq) → 2C₂H₅OH(aq) + 2CO₂(g);',1,1);
INSERT INTO rubric_criterion VALUES(4692,'chem34a1-ffb-6',NULL,1,'the reaction is catalysed by enzymes in yeast (anaerobic conditions).',1,1);
INSERT INTO rubric_criterion VALUES(4693,'chem34a1-ffb-7',NULL,0,'The CO₂ released when a biofuel burns was absorbed from the atmosphere by the plants during photosynthesis, so in theory there is no net increase in atmospheric CO₂; however, fossil fuels are used in farming, fertiliser production, harvesting, transport and processing (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(4694,'chem34a1-ffb-7',NULL,1,'distillation), so there is a net release of CO₂;',1,1);
INSERT INTO rubric_criterion VALUES(4695,'chem34a1-ffb-7',NULL,2,'land clearing for crops can also release CO₂.',1,1);
INSERT INTO rubric_criterion VALUES(4696,'chem34a1-ffb-8',NULL,0,'They formed from the remains of ancient plants and marine organisms buried and subjected to heat and pressure over millions of years;',1,1);
INSERT INTO rubric_criterion VALUES(4697,'chem34a1-ffb-8',NULL,1,'they are used far faster than they are formed, so supplies cannot be replenished on a human timescale.',1,1);
INSERT INTO rubric_criterion VALUES(4702,'chem-1-2-4',NULL,0,'C₂H₅OH(l) + 3O₂(g) → 2CO₂(g) + 3H₂O(l)   ΔH = −1364 kJ mol⁻¹',1,1);
INSERT INTO rubric_criterion VALUES(4706,'chem-1-2-8',NULL,0,'2H₂(g) + O₂(g) → 2H₂O(l)   ΔH = −572 kJ mol⁻¹',2,1);
INSERT INTO rubric_criterion VALUES(4710,'chem-1-2-12',NULL,0,'ΔH = H(products) − H(reactants).',1,1);
INSERT INTO rubric_criterion VALUES(4711,'chem-1-2-12',NULL,1,'In an exothermic reaction energy is released to the surroundings, so the products have less enthalpy than the reactants and ΔH is negative.',1,1);
INSERT INTO rubric_criterion VALUES(4715,'chem-1-2-16',NULL,0,'ΔH = +4440 kJ mol⁻¹',2,1);
INSERT INTO rubric_criterion VALUES(4719,'chem-1-2-20',NULL,0,'With limited oxygen, incomplete combustion occurs. Products include carbon monoxide, carbon (soot) and water, along with less carbon dioxide;',1,1);
INSERT INTO rubric_criterion VALUES(4720,'chem-1-2-20',NULL,1,'less energy is released per mole of fuel.',1,1);
INSERT INTO rubric_criterion VALUES(4724,'chem-1-2-24',NULL,0,'ΔH = −890 + 2(+44) = −802 kJ mol⁻¹',2,1);
INSERT INTO rubric_criterion VALUES(4725,'chem-1-2-25',NULL,0,'C₅H₁₂(l) + 8O₂(g) → 5CO₂(g) + 6H₂O(l); the mole ratio CO₂ : C₅H₁₂ is 5 : 1.',1,1);
INSERT INTO rubric_criterion VALUES(4731,'chem34a1-cte-6',NULL,0,'2C₄H₁₀(g) + 13O₂(g) → 8CO₂(g) + 10H₂O(l) ΔH = −5748 kJ mol⁻¹ (or C₄H₁₀(g) + 13/2 O₂(g) → 4CO₂(g) + 5H₂O(l) ΔH = −2874 kJ mol⁻¹); correct formulas, balancing and states;',1,1);
INSERT INTO rubric_criterion VALUES(4732,'chem34a1-cte-6',NULL,1,'ΔH sign and value consistent with the coefficients.',1,1);
INSERT INTO rubric_criterion VALUES(4733,'chem34a1-cte-7',NULL,0,'n(CH₃OH) = 80.0 ÷ 32.0 = 2.50 mol;',1,1);
INSERT INTO rubric_criterion VALUES(4734,'chem34a1-cte-7',NULL,1,'energy = 2.50 × 726 = 1815 kJ ≈ 1.82 × 10³ kJ released.',1,1);
INSERT INTO rubric_criterion VALUES(4735,'chem34a1-cte-8',NULL,0,'At SLC (25 °C, 100 kPa) water is a liquid, so the standard value refers to liquid water;',1,1);
INSERT INTO rubric_criterion VALUES(4736,'chem34a1-cte-8',NULL,1,'if water were formed as a gas, less energy would be released because energy is absorbed when water vaporises, so |ΔH| would be smaller (less negative).',1,1);
INSERT INTO rubric_criterion VALUES(4741,'chem-1-3-4',NULL,0,'2220 / 44.0 = 50.5 kJ g⁻¹',2,1);
INSERT INTO rubric_criterion VALUES(4745,'chem-1-3-8',NULL,0,'n(C₂H₅OH) = 1000 / 1364 = 0.733 mol; n(CO₂) = 2 × 0.733 = 1.47 mol;',1,1);
INSERT INTO rubric_criterion VALUES(4746,'chem-1-3-8',NULL,1,'m = 1.47 × 44.0 = 64.5 g',1,1);
INSERT INTO rubric_criterion VALUES(4750,'chem-1-3-12',NULL,0,'n = 10 000 / 890 = 11.2 mol;',1,1);
INSERT INTO rubric_criterion VALUES(4751,'chem-1-3-12',NULL,1,'V = 11.2 × 24.8 = 279 L',1,1);
INSERT INTO rubric_criterion VALUES(4755,'chem-1-3-16',NULL,0,'n = 9000 / 44.0 = 205 mol;',1,1);
INSERT INTO rubric_criterion VALUES(4756,'chem-1-3-16',NULL,1,'energy = 205 × 2220 = 4.5 × 10⁵ kJ = 4.5 × 10² MJ (about 454 MJ)',2,1);
INSERT INTO rubric_criterion VALUES(4760,'chem-1-3-20',NULL,0,'Energy from 1.00 g octane = (1.00 / 114.0) × 5464 = 47.9 kJ;',1,1);
INSERT INTO rubric_criterion VALUES(4761,'chem-1-3-20',NULL,1,'ethanol releases 1364 / 46.0 = 29.7 kJ g⁻¹, so mass = 47.9 / 29.7 = 1.62 g',1,1);
INSERT INTO rubric_criterion VALUES(4765,'chem-1-3-24',NULL,0,'n = 1000 / 286 = 3.50 mol;',1,1);
INSERT INTO rubric_criterion VALUES(4766,'chem-1-3-24',NULL,1,'m = 3.50 × 2.0 = 6.99 g (about 7.0 g)',1,1);
INSERT INTO rubric_criterion VALUES(4767,'chem-1-3-25',NULL,0,'Vehicles carry fuel by mass (and volume), so the energy per gram tells how much energy is available for a given mass of fuel carried.',1,1);
INSERT INTO rubric_criterion VALUES(4768,'chem-1-3-25',NULL,1,'Molar values ignore that molecules of different fuels have very different masses.',1,1);
INSERT INTO rubric_criterion VALUES(4774,'chem34a1-eep-6',NULL,0,'Axes: enthalpy (vertical) against reaction progress (horizontal); reactants CH₄(g) + 2O₂(g) on a higher level, products CO₂(g) + 2H₂O(l) 890 kJ mol⁻¹ lower, with a hump between labelled transition state;',1,1);
INSERT INTO rubric_criterion VALUES(4775,'chem34a1-eep-6',NULL,1,'Ea arrow from reactants to top of hump (250 kJ mol⁻¹) and ΔH arrow from reactants down to products;',1,1);
INSERT INTO rubric_criterion VALUES(4776,'chem34a1-eep-6',NULL,2,'Ea(reverse) = 250 + 890 = 1140 kJ mol⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(4777,'chem34a1-eep-7',NULL,0,'The reaction has a high activation energy, so at room temperature very few collisions between CH₄ and O₂ have enough energy to break the reactant bonds;',1,1);
INSERT INTO rubric_criterion VALUES(4778,'chem34a1-eep-7',NULL,1,'a spark or flame provides enough energy to overcome Ea, after which the energy released sustains the reaction.',1,1);
INSERT INTO rubric_criterion VALUES(4779,'chem34a1-eep-8',NULL,0,'Energy absorbed breaking bonds = 2(436) + 498 = 1370 kJ;',1,1);
INSERT INTO rubric_criterion VALUES(4780,'chem34a1-eep-8',NULL,1,'energy released forming bonds = 4 × 463 = 1852 kJ;',1,1);
INSERT INTO rubric_criterion VALUES(4781,'chem34a1-eep-8',NULL,2,'ΔH = 1370 − 1852 = −482 kJ mol⁻¹ (exothermic).',1,1);
INSERT INTO rubric_criterion VALUES(4787,'chem34a1-gse-6',NULL,0,'n(C₃H₈) = 450 ÷ 44.0 = 10.2 mol;',1,1);
INSERT INTO rubric_criterion VALUES(4788,'chem34a1-gse-6',NULL,1,'(a) energy = 10.2 × 2220 = 2.27 × 10⁴ kJ;',1,1);
INSERT INTO rubric_criterion VALUES(4789,'chem34a1-gse-6',NULL,2,'(b) n(CO₂) = 3 × 10.2 = 30.7 mol, V = 30.7 × 24.8 = 761 L (7.61 × 10² L).',1,1);
INSERT INTO rubric_criterion VALUES(4790,'chem34a1-gse-7',NULL,0,'n(CH₄) = 5.00 ÷ 24.8 = 0.202 mol;',1,1);
INSERT INTO rubric_criterion VALUES(4791,'chem34a1-gse-7',NULL,1,'energy released = 0.202 × 890 = 179 kJ;',1,1);
INSERT INTO rubric_criterion VALUES(4792,'chem34a1-gse-7',NULL,2,'energy transferred = 0.650 × 179 = 117 kJ.',1,1);
INSERT INTO rubric_criterion VALUES(4793,'chem34a1-gse-8',NULL,0,'H₂: (1 ÷ 24.8) × 286 = 11.5 kJ L⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(4794,'chem34a1-gse-8',NULL,1,'CH₄: (1 ÷ 24.8) × 890 = 35.9 kJ L⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(4795,'chem34a1-gse-8',NULL,2,'hydrogen releases about one-third the energy per litre, so it must be compressed to high pressure or liquefied at very low temperature to store useful amounts, which costs energy and needs strong tanks.',1,1);
INSERT INTO rubric_criterion VALUES(4796,'chem-1-3-c1',NULL,0,'359 kJ',2,1);
INSERT INTO rubric_criterion VALUES(4800,'chem-1-4-4',NULL,0,'E = VIt = 5.00 × 3.00 × 120 = 1800 J;',1,1);
INSERT INTO rubric_criterion VALUES(4801,'chem-1-4-4',NULL,1,'CF = 1800 / 0.750 = 2.40 × 10³ J °C⁻¹ (2.40 kJ °C⁻¹)',1,1);
INSERT INTO rubric_criterion VALUES(4805,'chem-1-4-8',NULL,0,'q = 4.25 × 6.80 = 28.9 kJ; n = 1.15 / 46.0 = 0.0250 mol;',1,1);
INSERT INTO rubric_criterion VALUES(4806,'chem-1-4-8',NULL,1,'ΔH = −28.9 / 0.0250 = −1.16 × 10³ kJ mol⁻¹',1,1);
INSERT INTO rubric_criterion VALUES(4810,'chem-1-4-12',NULL,0,'q = mcΔT accounts only for energy absorbed by the water, whereas the calibration factor includes the energy absorbed by the container, stirrer, thermometer and any other parts of the calorimeter, as well as typical heat losses under the same conditions.',3,1);
INSERT INTO rubric_criterion VALUES(4814,'chem-1-4-16',NULL,0,'Heat lost to the surroundings and the metal can, and incomplete combustion (soot on the can). Both mean less energy reaches the water, so the calculated heat of combustion is lower than the true value.',1,1);
INSERT INTO rubric_criterion VALUES(4815,'chem-1-4-16',NULL,1,'Evaporation of ethanol from the wick before weighing would also make the calculated value too low.',1,1);
INSERT INTO rubric_criterion VALUES(4819,'chem-1-4-20',NULL,0,'q = 100 × 4.18 × 6.70 = 2.80 × 10³ J = 2.80 kJ;',1,1);
INSERT INTO rubric_criterion VALUES(4820,'chem-1-4-20',NULL,1,'n(H₂O) = 0.0500 mol;',1,1);
INSERT INTO rubric_criterion VALUES(4821,'chem-1-4-20',NULL,2,'ΔH = −2.80 / 0.0500 = −56.0 kJ mol⁻¹',1,1);
INSERT INTO rubric_criterion VALUES(4825,'chem-1-4-24',NULL,0,'Energy released = (0.200 / 16.0) × 890 = 11.1 kJ; absorbed = 0.700 × 11.1 = 7.79 kJ;',1,1);
INSERT INTO rubric_criterion VALUES(4826,'chem-1-4-24',NULL,1,'ΔT = 7790 / (300 × 4.18) = 6.21 °C',1,1);
INSERT INTO rubric_criterion VALUES(4827,'chem-1-4-25',NULL,0,'The lid reduces heat loss (or gain) to the surroundings by convection and evaporation.',1,1);
INSERT INTO rubric_criterion VALUES(4828,'chem-1-4-25',NULL,1,'The stirrer ensures the solution has a uniform temperature so the thermometer reads the true temperature change.',1,1);
INSERT INTO rubric_criterion VALUES(4834,'chem34a1-cal-6',NULL,0,'Energy released = 420 × 13.6 = 5712 J = 5.71 kJ;',1,1);
INSERT INTO rubric_criterion VALUES(4835,'chem34a1-cal-6',NULL,1,'n(H₂O) = n(H⁺) = 0.1000 L × 1.00 M = 0.100 mol;',1,1);
INSERT INTO rubric_criterion VALUES(4836,'chem34a1-cal-6',NULL,2,'ΔH = −5.71 ÷ 0.100 = −57.1 kJ mol⁻¹ (negative sign because exothermic).',1,1);
INSERT INTO rubric_criterion VALUES(4837,'chem34a1-cal-7',NULL,0,'The calibration factor is the energy needed to raise the temperature of the calorimeter and its contents by 1 °C;',1,1);
INSERT INTO rubric_criterion VALUES(4838,'chem34a1-cal-7',NULL,1,'changing the volume of water changes the total heat capacity, so the old calibration factor no longer applies.',1,1);
INSERT INTO rubric_criterion VALUES(4839,'chem34a1-cal-8',NULL,0,'Extrapolate the cooling section of the graph back to the time the reaction (or heating) began and take ΔT as the difference between this extrapolated temperature and the initial temperature;',1,1);
INSERT INTO rubric_criterion VALUES(4840,'chem34a1-cal-8',NULL,1,'this corrects for heat lost to the surroundings while the temperature was rising.',1,1);
INSERT INTO rubric_criterion VALUES(4841,'chem-1-4-c1',NULL,0,'−961 kJ/mol;',1,1);
INSERT INTO rubric_criterion VALUES(4842,'chem-1-4-c1',NULL,1,'heat is lost to the surroundings and the container, and combustion may be incomplete.',2,1);
INSERT INTO rubric_criterion VALUES(4846,'chem-3-1-4',NULL,0,'The 2 M acid has more H⁺ ions per unit volume, so collisions between H⁺ and the CaCO₃ surface occur more frequently.',1,1);
INSERT INTO rubric_criterion VALUES(4847,'chem-3-1-4',NULL,1,'With more collisions per second, there are more successful collisions per second (the proportion of successful collisions is unchanged), so the rate is greater.',2,1);
INSERT INTO rubric_criterion VALUES(4851,'chem-3-1-8',NULL,0,'At higher temperature particles have greater average kinetic energy, so collisions are slightly more frequent.',1,1);
INSERT INTO rubric_criterion VALUES(4852,'chem-3-1-8',NULL,1,'More importantly, a much larger proportion of collisions now have energy equal to or greater than the activation energy, so the number of successful collisions per second increases greatly.',2,1);
INSERT INTO rubric_criterion VALUES(4856,'chem-3-1-12',NULL,0,'Ea(reverse) = Ea(forward) + |ΔH| = 185 + 92 = 277 kJ mol⁻¹.',2,1);
INSERT INTO rubric_criterion VALUES(4860,'chem-3-1-16',NULL,0,'n(CaCO₃) = 1.00 ÷ 100.1 = 9.99 × 10⁻³ mol = n(CO₂).',1,1);
INSERT INTO rubric_criterion VALUES(4861,'chem-3-1-16',NULL,1,'Average rate = 9.99 × 10⁻³ ÷ 120 = 8.33 × 10⁻⁵ mol s⁻¹.',2,1);
INSERT INTO rubric_criterion VALUES(4865,'chem-3-1-20',NULL,0,'1) Collect the hydrogen gas in a gas syringe (or inverted measuring cylinder) and record its volume at regular time intervals.',1,1);
INSERT INTO rubric_criterion VALUES(4866,'chem-3-1-20',NULL,1,'2) Measure the pH (or conductivity) of the solution over time as H⁺ is consumed, or time how long the magnesium takes to disappear completely.',2,1);
INSERT INTO rubric_criterion VALUES(4870,'chem-3-1-24',NULL,0,'Initially reactant concentrations are highest, so collision frequency and rate are greatest (steep slope).',1,1);
INSERT INTO rubric_criterion VALUES(4871,'chem-3-1-24',NULL,1,'As magnesium and acid are used up, collisions become less frequent and the rate falls (flatter slope).',1,1);
INSERT INTO rubric_criterion VALUES(4872,'chem-3-1-24',NULL,2,'The line becomes horizontal when the limiting reactant is fully consumed and no more gas is produced.',1,1);
INSERT INTO rubric_criterion VALUES(4873,'chem-3-1-25',NULL,0,'Heating does not change the activation energy.',1,1);
INSERT INTO rubric_criterion VALUES(4874,'chem-3-1-25',NULL,1,'It increases the average kinetic energy of particles, so collisions are more frequent and a greater proportion of collisions have energy equal to or greater than the (unchanged) activation energy.',1,1);
INSERT INTO rubric_criterion VALUES(4880,'chem34a1-ctr-6',NULL,0,'Coal dust has a much larger surface area exposed to oxygen than a lump of the same mass;',1,1);
INSERT INTO rubric_criterion VALUES(4881,'chem34a1-ctr-6',NULL,1,'this greatly increases the frequency of collisions between carbon and O₂ molecules, so the reaction rate is so high that energy is released almost instantly, producing an explosion.',1,1);
INSERT INTO rubric_criterion VALUES(4882,'chem34a1-ctr-7',NULL,0,'Experiment 2 has a steeper initial gradient (faster rate) because the higher HCl concentration increases collision frequency;',1,1);
INSERT INTO rubric_criterion VALUES(4883,'chem34a1-ctr-7',NULL,1,'it levels off sooner;',1,1);
INSERT INTO rubric_criterion VALUES(4884,'chem34a1-ctr-7',NULL,2,'it reaches the same final volume of H₂ because magnesium is the limiting reactant and the same amount is used in both.',1,1);
INSERT INTO rubric_criterion VALUES(4885,'chem34a1-ctr-8',NULL,0,'Spoilage involves chemical (enzyme-catalysed and microbial) reactions;',1,1);
INSERT INTO rubric_criterion VALUES(4886,'chem34a1-ctr-8',NULL,1,'at lower temperature particles have less kinetic energy, so fewer collisions have energy ≥ activation energy and collisions are less frequent, so the rate of spoilage reactions decreases.',1,1);
INSERT INTO rubric_criterion VALUES(4891,'chem-3-2-4',NULL,0,'The curve becomes flatter and broader, the peak shifts to a higher kinetic energy and is lower, and the total area stays the same.',1,1);
INSERT INTO rubric_criterion VALUES(4892,'chem-3-2-4',NULL,1,'A greater area now lies beyond the activation energy, so more particles have energy ≥ Ea;',1,1);
INSERT INTO rubric_criterion VALUES(4893,'chem-3-2-4',NULL,2,'more collisions are successful per second and the rate increases.',1,1);
INSERT INTO rubric_criterion VALUES(4897,'chem-3-2-8',NULL,0,'The catalyst provides an alternative pathway with a lower activation energy.',1,1);
INSERT INTO rubric_criterion VALUES(4898,'chem-3-2-8',NULL,1,'The distribution curve itself is unchanged, but the Ea line moves to lower energy, so a larger proportion of particles have energy ≥ Ea and the frequency of successful collisions increases.',2,1);
INSERT INTO rubric_criterion VALUES(4902,'chem-3-2-12',NULL,0,'A homogeneous catalyst is in the same phase as the reactants, e.g. concentrated H₂SO₄ in the esterification of ethanoic acid and ethanol.',1,1);
INSERT INTO rubric_criterion VALUES(4903,'chem-3-2-12',NULL,1,'A heterogeneous catalyst is in a different phase from the reactants, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(4904,'chem-3-2-12',NULL,2,'solid iron catalysing the gaseous Haber process (or Pt/Pd/Rh in a catalytic converter).',1,1);
INSERT INTO rubric_criterion VALUES(4908,'chem-3-2-16',NULL,0,'A catalyst lowers the activation energy of both the forward and reverse reactions by the same amount, so both rates increase equally.',1,1);
INSERT INTO rubric_criterion VALUES(4909,'chem-3-2-16',NULL,1,'Equilibrium is reached sooner, but the equilibrium position and the value of K are unchanged, so the yield is the same.',2,1);
INSERT INTO rubric_criterion VALUES(4913,'chem-3-2-20',NULL,0,'The poison binds strongly to the active sites on the metal catalyst surface and is not released.',1,1);
INSERT INTO rubric_criterion VALUES(4914,'chem-3-2-20',NULL,1,'This blocks reactant molecules from adsorbing, so the catalyst''s effectiveness decreases permanently.',1,1);
INSERT INTO rubric_criterion VALUES(4918,'chem-3-2-24',NULL,0,'Ea(reverse, catalysed) = 140 + 196 = 336 kJ mol⁻¹.',2,1);
INSERT INTO rubric_criterion VALUES(4919,'chem-3-2-25',NULL,0,'Very few particles have zero (or near-zero) kinetic energy, so the curve begins at the origin.',1,1);
INSERT INTO rubric_criterion VALUES(4920,'chem-3-2-25',NULL,1,'A small number of particles have very high energies, and there is no fixed maximum energy, so the curve tails off towards the axis without reaching it.',2,1);
INSERT INTO rubric_criterion VALUES(4926,'chem34a1-mbc-6',NULL,0,'Axes: number of particles (vertical) against kinetic energy (horizontal); curve starts at origin, rises to a peak and has a long tail that approaches but never reaches zero;',1,1);
INSERT INTO rubric_criterion VALUES(4927,'chem34a1-mbc-6',NULL,1,'the T₂ curve is lower and broader with its peak shifted to the right, with the same area;',1,1);
INSERT INTO rubric_criterion VALUES(4928,'chem34a1-mbc-6',NULL,2,'with Ea marked, the area to the right of Ea is much larger at T₂, so a greater proportion of collisions are successful and the rate increases.',1,1);
INSERT INTO rubric_criterion VALUES(4929,'chem34a1-mbc-7',NULL,0,'A catalyst lowers the activation energy, so the Ea line moves to the left and the area under the curve beyond Ea increases, meaning more particles can react;',1,1);
INSERT INTO rubric_criterion VALUES(4930,'chem34a1-mbc-7',NULL,1,'the curve depends only on temperature (the energy distribution of the particles), which a catalyst does not change.',1,1);
INSERT INTO rubric_criterion VALUES(4931,'chem34a1-mbc-8',NULL,0,'MnO₂ is a catalyst that provides an alternative pathway with lower activation energy, so more collisions are successful and O₂ is produced rapidly (bubbling);',1,1);
INSERT INTO rubric_criterion VALUES(4932,'chem34a1-mbc-8',NULL,1,'because it is regenerated at the end of the reaction, its mass is unchanged;',1,1);
INSERT INTO rubric_criterion VALUES(4933,'chem34a1-mbc-8',NULL,2,'it is a heterogeneous catalyst (solid catalyst with aqueous reactant).',1,1);
INSERT INTO rubric_criterion VALUES(4938,'chem-3-3-4',NULL,0,'Kc = [NO₂]² / ([NO]²[O₂]); units M⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(4942,'chem-3-3-8',NULL,0,'Initial [H₂] = [I₂] = 0.100 M.',1,1);
INSERT INTO rubric_criterion VALUES(4943,'chem-3-3-8',NULL,1,'(2x)² ÷ (0.100 − x)² = 64.0, so 2x ÷ (0.100 − x) = 8.00, giving 10x = 0.800 and x = 0.0800.',1,1);
INSERT INTO rubric_criterion VALUES(4944,'chem-3-3-8',NULL,2,'[HI] = 2x = 0.160 M.',1,1);
INSERT INTO rubric_criterion VALUES(4948,'chem-3-3-12',NULL,0,'Q = (0.50)² ÷ ((0.10)² × 0.050) = 0.25 ÷ 0.00050 = 500 M⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(4949,'chem-3-3-12',NULL,1,'Q > Kc, so the mixture is not at equilibrium and the net reaction proceeds in the reverse direction (forming more SO₂ and O₂).',2,1);
INSERT INTO rubric_criterion VALUES(4953,'chem-3-3-16',NULL,0,'Adding reactant makes Q smaller than K, so the forward reaction is temporarily favoured. Concentrations then adjust until the ratio of products to reactants again equals K.',1,1);
INSERT INTO rubric_criterion VALUES(4954,'chem-3-3-16',NULL,1,'K depends only on temperature, which has not changed.',1,1);
INSERT INTO rubric_criterion VALUES(4958,'chem-3-3-20',NULL,0,'Reversing gives 1/2.0 = 0.50 M;',1,1);
INSERT INTO rubric_criterion VALUES(4959,'chem-3-3-20',NULL,1,'doubling the coefficients squares this: (0.50)² = 0.25 M².',1,1);
INSERT INTO rubric_criterion VALUES(4963,'chem-3-3-24',NULL,0,'In a closed system, the forward and reverse reactions continue to occur at equal rates, so there is no net change in the concentrations of reactants and products, even though particles are still reacting.',2,1);
INSERT INTO rubric_criterion VALUES(4964,'chem-3-3-25',NULL,0,'NO₂ reacted = 2 × 0.200 = 0.400 mol, so 0.400 mol NO₂ remains.',1,1);
INSERT INTO rubric_criterion VALUES(4965,'chem-3-3-25',NULL,1,'[NO₂] = 0.200 M and [N₂O₄] = 0.100 M.',1,1);
INSERT INTO rubric_criterion VALUES(4966,'chem-3-3-25',NULL,2,'Kc = 0.100 ÷ (0.200)² = 2.50 M⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(4972,'chem34a2-eq-6',NULL,0,'n(H₂) reacted = n(I₂) reacted = 0.780/2 = 0.390 mol, so 0.110 mol of each remains;',1,1);
INSERT INTO rubric_criterion VALUES(4973,'chem34a2-eq-6',NULL,1,'equilibrium concentrations: [H₂] = [I₂] = 0.110/2.00 = 0.0550 M, [HI] = 0.780/2.00 = 0.390 M;',1,1);
INSERT INTO rubric_criterion VALUES(4974,'chem34a2-eq-6',NULL,2,'K = [HI]²/([H₂][I₂]) = 0.390²/(0.0550 × 0.0550) = 50.3 (no units, as the mole totals on each side are equal).',1,1);
INSERT INTO rubric_criterion VALUES(4975,'chem34a2-eq-7',NULL,0,'Q = [N₂O₄]/[NO₂]² = 0.50/(0.20)² = 12.5 M⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(4976,'chem34a2-eq-7',NULL,1,'Q > K (12.5 > 6.0), so the system is not at equilibrium;',1,1);
INSERT INTO rubric_criterion VALUES(4977,'chem34a2-eq-7',NULL,2,'net reverse reaction occurs, so [NO₂] increases (and [N₂O₄] decreases) until Q = K.',1,1);
INSERT INTO rubric_criterion VALUES(4978,'chem34a2-eq-8',NULL,0,'In a closed system the forward and reverse reactions continue to occur at equal rates, so the concentrations of reactants and products stay constant (no net change), even though particles are still reacting;',1,1);
INSERT INTO rubric_criterion VALUES(4979,'chem34a2-eq-8',NULL,1,'only a change in temperature changes the value of K.',1,1);
INSERT INTO rubric_criterion VALUES(4980,'chem-3-3-c1',NULL,0,'K ≈ 0.051 M',2,1);
INSERT INTO rubric_criterion VALUES(4984,'chem-3-4-4',NULL,0,'Increasing pressure (by decreasing volume) increases the concentration of all gases.',1,1);
INSERT INTO rubric_criterion VALUES(4985,'chem-3-4-4',NULL,1,'The system partially opposes this by shifting to the side with fewer gas particles;',1,1);
INSERT INTO rubric_criterion VALUES(4986,'chem-3-4-4',NULL,2,'there are 4 mol of gas on the left and 2 mol on the right, so the equilibrium shifts right, increasing the yield of ammonia.',1,1);
INSERT INTO rubric_criterion VALUES(4990,'chem-3-4-8',NULL,0,'Because the reaction is exothermic, lower temperatures give a higher equilibrium yield.',1,1);
INSERT INTO rubric_criterion VALUES(4991,'chem-3-4-8',NULL,1,'However, at low temperatures the rate is too slow to be economical.',1,1);
INSERT INTO rubric_criterion VALUES(4992,'chem-3-4-8',NULL,2,'About 450 °C (with an iron catalyst) is a compromise that gives an acceptable yield at a fast enough rate.',1,1);
INSERT INTO rubric_criterion VALUES(4996,'chem-3-4-12',NULL,0,'The colour immediately becomes darker because [NO₂] increases when the volume decreases.',1,1);
INSERT INTO rubric_criterion VALUES(4997,'chem-3-4-12',NULL,1,'The system then shifts right, towards fewer gas particles, converting some NO₂ to N₂O₄, so the colour lightens.',1,1);
INSERT INTO rubric_criterion VALUES(4998,'chem-3-4-12',NULL,2,'The final colour is still darker than the original because [NO₂] is only partially restored.',1,1);
INSERT INTO rubric_criterion VALUES(5002,'chem-3-4-16',NULL,0,'Kc increases and the yield of hydrogen increases.',1,1);
INSERT INTO rubric_criterion VALUES(5003,'chem-3-4-16',NULL,1,'The forward reaction is endothermic, so increasing temperature favours the forward direction to partially absorb the added heat, increasing the product concentrations relative to reactants.',1,1);
INSERT INTO rubric_criterion VALUES(5007,'chem-3-4-20',NULL,0,'A catalyst speeds up the forward and reverse reactions equally, so the equilibrium position and yield are unchanged.',1,1);
INSERT INTO rubric_criterion VALUES(5008,'chem-3-4-20',NULL,1,'However, equilibrium is reached much faster, and a reasonable rate can be achieved at a lower temperature, where the equilibrium yield is higher, saving time and energy costs.',2,1);
INSERT INTO rubric_criterion VALUES(5012,'chem-3-4-24',NULL,0,'1) Use an excess of ethanol (or ethanoic acid): increasing a reactant concentration shifts the equilibrium right.',1,1);
INSERT INTO rubric_criterion VALUES(5013,'chem-3-4-24',NULL,1,'2) Remove a product as it forms, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(5014,'chem-3-4-24',NULL,2,'by distilling off the ester or using concentrated H₂SO₄ to absorb water: lowering product concentration shifts the equilibrium right.',1,1);
INSERT INTO rubric_criterion VALUES(5015,'chem-3-4-25',NULL,0,'[O₂] is higher than originally (but lower than immediately after the addition); [SO₂] is lower;',1,1);
INSERT INTO rubric_criterion VALUES(5016,'chem-3-4-25',NULL,1,'[SO₃] is higher; Kc is unchanged because the temperature is constant.',1,1);
INSERT INTO rubric_criterion VALUES(5022,'chem34a2-lc-6',NULL,0,'Decreasing volume increases the concentrations of all gases (increases pressure); by Le Chatelier''s principle the system partially opposes this by shifting to the side with fewer gas particles, i.e.',1,1);
INSERT INTO rubric_criterion VALUES(5023,'chem34a2-lc-6',NULL,1,'forward (3 mol → 1 mol); so the yield of methanol increases;',1,1);
INSERT INTO rubric_criterion VALUES(5024,'chem34a2-lc-6',NULL,2,'K is unchanged because temperature is constant.',1,1);
INSERT INTO rubric_criterion VALUES(5025,'chem34a2-lc-7',NULL,0,'Dilution halves every concentration, so Q = [FeSCN²⁺]/([Fe³⁺][SCN⁻]) becomes (½)/(½ × ½) = 2 × the original value, i.e. Q > K;',1,1);
INSERT INTO rubric_criterion VALUES(5026,'chem34a2-lc-7',NULL,1,'the net reverse reaction occurs (towards the side with more particles in solution) until Q = K;',1,1);
INSERT INTO rubric_criterion VALUES(5027,'chem34a2-lc-7',NULL,2,'the solution becomes paler red, both due to dilution and to some FeSCN²⁺ converting back to Fe³⁺ and SCN⁻.',1,1);
INSERT INTO rubric_criterion VALUES(5028,'chem34a2-lc-8',NULL,0,'There is no sudden vertical jump in any concentration at the moment of change;',1,1);
INSERT INTO rubric_criterion VALUES(5029,'chem34a2-lc-8',NULL,1,'[NH₃] gradually decreases while [N₂] and [H₂] gradually increase (the changes in N₂ : H₂ : NH₃ are in the ratio 1 : 3 : 2) until new constant (horizontal) values are reached;',1,1);
INSERT INTO rubric_criterion VALUES(5030,'chem34a2-lc-8',NULL,2,'K decreases because the reverse (endothermic) reaction is favoured at higher temperature.',1,1);
INSERT INTO rubric_criterion VALUES(5036,'chem34a2-ind-6',NULL,0,'Lower temperature would favour a higher equilibrium yield (exothermic forward reaction) but the rate would be too slow, so a moderate temperature with a catalyst gives an acceptable rate;',1,1);
INSERT INTO rubric_criterion VALUES(5037,'chem34a2-ind-6',NULL,1,'high pressure increases both rate (more frequent collisions) and yield (shift to fewer gas particles, 3 mol → 1 mol);',1,1);
INSERT INTO rubric_criterion VALUES(5038,'chem34a2-ind-6',NULL,2,'pressure is not raised further because of the energy cost of compression and the cost and safety risk of stronger equipment.',1,1);
INSERT INTO rubric_criterion VALUES(5039,'chem34a2-ind-7',NULL,0,'n(N₂) = 10.0 × 10⁶ g / 28.0 g mol⁻¹ = 3.57 × 10⁵ mol;',1,1);
INSERT INTO rubric_criterion VALUES(5040,'chem34a2-ind-7',NULL,1,'n(NH₃) theoretical = 2 × 3.57 × 10⁵ = 7.14 × 10⁵ mol, mass = 7.14 × 10⁵ × 17.0 = 1.21 × 10⁷ g (12.1 t);',1,1);
INSERT INTO rubric_criterion VALUES(5041,'chem34a2-ind-7',NULL,2,'percentage yield = 2.50/12.1 × 100 = 20.6%.',1,1);
INSERT INTO rubric_criterion VALUES(5042,'chem34a2-ind-8',NULL,0,'A catalyst lowers the activation energy, so an acceptable rate can be reached at a lower temperature; this means less energy (often from fossil fuels) is needed for heating, reducing costs and CO₂ emissions;',1,1);
INSERT INTO rubric_criterion VALUES(5043,'chem34a2-ind-8',NULL,1,'a catalyst is also not consumed, so it can be reused.',1,1);
INSERT INTO rubric_criterion VALUES(5048,'chem-4-1-4',NULL,0,'Anode: 2Br⁻(l) → Br₂(g) + 2e⁻. Cathode: K⁺(l) + e⁻ → K(l).',1,1);
INSERT INTO rubric_criterion VALUES(5052,'chem-4-1-8',NULL,0,'Water is a stronger oxidant than Na⁺ (E° −0.83 V compared with −2.71 V), so water is reduced at the cathode to H₂ and OH⁻ instead of Na⁺ being reduced to Na.',2,1);
INSERT INTO rubric_criterion VALUES(5056,'chem-4-1-12',NULL,0,'2H₂O(l) → 2H₂(g) + O₂(g)',1,1);
INSERT INTO rubric_criterion VALUES(5060,'chem-4-1-16',NULL,0,'2Ni²⁺(aq) + 2H₂O(l) → 2Ni(s) + O₂(g) + 4H⁺(aq)',1,1);
INSERT INTO rubric_criterion VALUES(5064,'chem-4-1-20',NULL,0,'0.54 − (−0.83) = 1.37 V',2,1);
INSERT INTO rubric_criterion VALUES(5068,'chem-4-1-24',NULL,0,'The reaction in an electrolytic cell is non-spontaneous (the strongest oxidant present lies below the strongest reductant in the electrochemical series), so electrical energy must be supplied to force electrons from the anode to the cathode.',2,1);
INSERT INTO rubric_criterion VALUES(5069,'chem-4-1-25',NULL,0,'They are inert: they conduct electricity but do not react themselves, so the products depend only on the species in the electrolyte.',2,1);
INSERT INTO rubric_criterion VALUES(5075,'chem34a2-ely-6',NULL,0,'Cathode: 2H₂O(l) + 2e⁻ → H₂(g) + 2OH⁻(aq) (water, −0.83 V, is a stronger oxidant than K⁺, −2.93 V);',1,1);
INSERT INTO rubric_criterion VALUES(5076,'chem34a2-ely-6',NULL,1,'anode: 2I⁻(aq) → I₂(aq) + 2e⁻ (I⁻ is a stronger reductant than H₂O, since I₂/I⁻ at +0.54 V is below O₂/H₂O at +1.23 V);',1,1);
INSERT INTO rubric_criterion VALUES(5077,'chem34a2-ely-6',NULL,2,'overall: 2I⁻(aq) + 2H₂O(l) → I₂(aq) + H₂(g) + 2OH⁻(aq);',1,1);
INSERT INTO rubric_criterion VALUES(5078,'chem34a2-ely-6',NULL,3,'observations: bubbles of colourless gas at the cathode (pH rises there), brown/yellow colour forming around the anode.',1,1);
INSERT INTO rubric_criterion VALUES(5079,'chem34a2-ely-7',NULL,0,'In aqueous solution water is a much stronger oxidant than Na⁺ (E° −0.83 V vs −2.71 V), so water would be reduced to H₂ at the cathode instead of Na⁺; in addition, any sodium formed would react vigorously with water;',1,1);
INSERT INTO rubric_criterion VALUES(5080,'chem34a2-ely-7',NULL,1,'in molten NaCl there is no water, so Na⁺ is the only species that can be reduced.',1,1);
INSERT INTO rubric_criterion VALUES(5081,'chem34a2-ely-8',NULL,0,'The spoon is the cathode, connected to the negative terminal; a silver anode is connected to the positive terminal, with AgNO₃(aq) (a solution of Ag⁺) as the electrolyte;',1,1);
INSERT INTO rubric_criterion VALUES(5082,'chem34a2-ely-8',NULL,1,'cathode: Ag⁺(aq) + e⁻ → Ag(s);',1,1);
INSERT INTO rubric_criterion VALUES(5083,'chem34a2-ely-8',NULL,2,'anode: Ag(s) → Ag⁺(aq) + e⁻, which replaces the Ag⁺ removed so [Ag⁺] stays constant.',1,1);
INSERT INTO rubric_criterion VALUES(5088,'chem-4-2-4',NULL,0,'Q = 1.50 × 2700 = 4050 C; n(e⁻) = 4050/96 500 = 0.04197 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5089,'chem-4-2-4',NULL,1,'n(Ni) = 0.02098 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5090,'chem-4-2-4',NULL,2,'m = 0.02098 × 58.7 = 1.23 g.',1,1);
INSERT INTO rubric_criterion VALUES(5094,'chem-4-2-8',NULL,0,'n(Ag) = 5.00/107.9 = 0.04634 mol = n(e⁻);',1,1);
INSERT INTO rubric_criterion VALUES(5095,'chem-4-2-8',NULL,1,'Q = 0.04634 × 96 500 = 4472 C;',1,1);
INSERT INTO rubric_criterion VALUES(5096,'chem-4-2-8',NULL,2,'t = 4472/0.750 = 5963 s = 99.4 min.',1,1);
INSERT INTO rubric_criterion VALUES(5100,'chem-4-2-12',NULL,0,'Q = 3.00 × 1200 = 3600 C; n(e⁻) = 0.03731 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5101,'chem-4-2-12',NULL,1,'n(O₂) = 0.03731/4 = 0.009326 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5102,'chem-4-2-12',NULL,2,'V = 0.009326 × 24.8 = 0.231 L.',1,1);
INSERT INTO rubric_criterion VALUES(5106,'chem-4-2-16',NULL,0,'Q = 150 000 × 86 400 = 1.296 × 10¹⁰ C; n(e⁻) = 1.343 × 10⁵ mol;',1,1);
INSERT INTO rubric_criterion VALUES(5107,'chem-4-2-16',NULL,1,'n(Al) = 4.48 × 10⁴ mol;',1,1);
INSERT INTO rubric_criterion VALUES(5108,'chem-4-2-16',NULL,2,'m = 4.48 × 10⁴ × 27.0 = 1.21 × 10⁶ g = 1.21 t.',1,1);
INSERT INTO rubric_criterion VALUES(5112,'chem-4-2-20',NULL,0,'For the same quantity of charge, the amount (mol) of substance produced is inversely proportional to the charge on the ion. E.g. 1 mol of electrons deposits 1 mol Ag from Ag⁺ but only 0.5 mol Cu from Cu²⁺.',1,1);
INSERT INTO rubric_criterion VALUES(5116,'chem-4-2-24',NULL,0,'n(e⁻) = 1930/96 500 = 0.0200 mol; n(Sn) = 1.187/118.7 = 0.0100 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5117,'chem-4-2-24',NULL,1,'ratio 2:1, so the ion is Sn²⁺.',1,1);
INSERT INTO rubric_criterion VALUES(5118,'chem-4-2-25',NULL,0,'n(Ag) = 1.079/107.9 = 0.0100 mol = n(e⁻);',1,1);
INSERT INTO rubric_criterion VALUES(5119,'chem-4-2-25',NULL,1,'n(Cu) = 0.00500 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5120,'chem-4-2-25',NULL,2,'m(Cu) = 0.00500 × 63.5 = 0.318 g.',1,1);
INSERT INTO rubric_criterion VALUES(5126,'chem34a2-far-6',NULL,0,'Q = It = 3.50 × (45.0 × 60) = 9.45 × 10³ C; n(e⁻) = 9450/96 500 = 0.0979 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5127,'chem34a2-far-6',NULL,1,'n(Cr) = 0.0979/3 = 0.0326 mol (Cr³⁺ + 3e⁻ → Cr);',1,1);
INSERT INTO rubric_criterion VALUES(5128,'chem34a2-far-6',NULL,2,'m(Cr) = 0.0326 × 52.0 = 1.70 g.',1,1);
INSERT INTO rubric_criterion VALUES(5129,'chem34a2-far-7',NULL,0,'Q = 0.500 × 1930 = 965 C; n(e⁻) = 965/96 500 = 0.0100 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5130,'chem34a2-far-7',NULL,1,'n(Ni) = 0.300/58.7 = 0.00511 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5131,'chem34a2-far-7',NULL,2,'ratio n(e⁻) : n(Ni) = 0.0100/0.00511 ≈ 2, so the ion is Ni²⁺.',1,1);
INSERT INTO rubric_criterion VALUES(5132,'chem34a2-far-8',NULL,0,'Q = 5.00 × (2.00 × 3600) = 3.60 × 10⁴ C; n(e⁻) = 36 000/96 500 = 0.373 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5133,'chem34a2-far-8',NULL,1,'2Cl⁻ → Cl₂ + 2e⁻ so n(Cl₂) = 0.373/2 = 0.187 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5134,'chem34a2-far-8',NULL,2,'V = 0.187 × 24.8 = 4.63 L.',1,1);
INSERT INTO rubric_criterion VALUES(5135,'chem-4-2-c1',NULL,0,'About 19.9 minutes (1.19 × 10³ s)',3,1);
INSERT INTO rubric_criterion VALUES(5139,'chem-4-3-4',NULL,0,'Pb(s) + PbO₂(s) + 4H⁺(aq) + 2SO₄²⁻(aq) → 2PbSO₄(s) + 2H₂O(l)',1,1);
INSERT INTO rubric_criterion VALUES(5143,'chem-4-3-8',NULL,0,'PbSO₄ is insoluble and stays attached to the electrodes, so when current is reversed it can be oxidised back to PbO₂ at one electrode and reduced back to Pb at the other.',2,1);
INSERT INTO rubric_criterion VALUES(5147,'chem-4-3-12',NULL,0,'Li⁺ + C₆ + e⁻ → LiC₆',1,1);
INSERT INTO rubric_criterion VALUES(5151,'chem-4-3-16',NULL,0,'The recharge reaction is non-spontaneous, so the applied voltage must exceed the cell''s EMF to push electrons in the reverse direction and also overcome internal resistance.',2,1);
INSERT INTO rubric_criterion VALUES(5155,'chem-4-3-20',NULL,0,'The polarity of each electrode stays the same (negative stays negative), but the labels swap: the negative electrode is the anode on discharge and the cathode on recharge, and the positive electrode is the cathode on discharge and the anode on recharge.',3,1);
INSERT INTO rubric_criterion VALUES(5159,'chem-4-3-24',NULL,0,'Six cells of about 2 V each are connected in series, so their voltages add to about 12 V.',2,1);
INSERT INTO rubric_criterion VALUES(5160,'chem-4-3-25',NULL,0,'Advantage: high energy density and low mass give a long driving range and many recharge cycles. Disadvantage: risk of thermal runaway/fire, high cost, or environmental impacts of mining lithium and cobalt.',1,1);
INSERT INTO rubric_criterion VALUES(5166,'chem34a2-bat-6',NULL,0,'(a) C₆(s) + Li⁺ + e⁻ → LiC₆(s);',1,1);
INSERT INTO rubric_criterion VALUES(5167,'chem34a2-bat-6',NULL,1,'(b) the negative terminal of the charger;',1,1);
INSERT INTO rubric_criterion VALUES(5168,'chem34a2-bat-6',NULL,2,'during recharge reduction occurs at the graphite electrode (it is the cathode), so it must be supplied with electrons from the negative terminal (it remains the negative electrode of the cell).',1,1);
INSERT INTO rubric_criterion VALUES(5169,'chem34a2-bat-7',NULL,0,'2PbSO₄(s) + 2H₂O(l) → Pb(s) + PbO₂(s) + 4H⁺(aq) + 2SO₄²⁻(aq);',1,1);
INSERT INTO rubric_criterion VALUES(5170,'chem34a2-bat-7',NULL,1,'PbSO₄ at the positive electrode is oxidised (Pb from +2 to +4 in PbO₂);',1,1);
INSERT INTO rubric_criterion VALUES(5171,'chem34a2-bat-7',NULL,2,'PbSO₄ at the negative electrode is reduced (Pb from +2 to 0).',1,1);
INSERT INTO rubric_criterion VALUES(5172,'chem34a2-bat-8',NULL,0,'Lithium is a very strong reductant (Li⁺/Li E° = −3.04 V) and would react with water to produce H₂ gas, and water would be reduced/oxidised in preference at the high cell voltage;',1,1);
INSERT INTO rubric_criterion VALUES(5173,'chem34a2-bat-8',NULL,1,'safety concern: the organic electrolyte is flammable, so overcharging, damage or overheating can lead to thermal runaway and fire.',1,1);
INSERT INTO rubric_criterion VALUES(5178,'chem-4-4-4',NULL,0,'The spoon is the cathode (negative terminal) and a nickel bar is the anode (positive terminal), both in NiSO₄(aq), connected to a DC supply. Cathode: Ni²⁺ + 2e⁻ → Ni;',1,1);
INSERT INTO rubric_criterion VALUES(5179,'chem-4-4-4',NULL,1,'anode: Ni → Ni²⁺ + 2e⁻.',1,1);
INSERT INTO rubric_criterion VALUES(5183,'chem-4-4-8',NULL,0,'Q = 0.200 × 900 = 180 C; n(e⁻) = 180/96 500 = 1.865 × 10⁻³ mol = n(Au);',1,1);
INSERT INTO rubric_criterion VALUES(5184,'chem-4-4-8',NULL,1,'m = 1.865 × 10⁻³ × 197.0 = 0.367 g.',1,1);
INSERT INTO rubric_criterion VALUES(5188,'chem-4-4-12',NULL,0,'Galvanic: chemical → electrical energy, anode negative. Electrolytic: electrical → chemical energy, anode positive.',1,1);
INSERT INTO rubric_criterion VALUES(5192,'chem-4-4-16',NULL,0,'Only Cu²⁺, the strongest oxidant present, is reduced at the cathode;',1,1);
INSERT INTO rubric_criterion VALUES(5193,'chem-4-4-16',NULL,1,'more reactive impurities such as Zn and Fe remain in solution as ions, and less reactive Ag and Au fall as sludge.',1,1);
INSERT INTO rubric_criterion VALUES(5197,'chem-4-4-20',NULL,0,'Water rather than copper would be oxidised at the anode, producing O₂ and H⁺, so Cu²⁺ would not be replenished;',1,1);
INSERT INTO rubric_criterion VALUES(5198,'chem-4-4-20',NULL,1,'its concentration would fall and the solution would become acidic, slowing and changing plating.',1,1);
INSERT INTO rubric_criterion VALUES(5202,'chem-4-4-24',NULL,0,'Q = 3600 C; n(Ag) = 3600/96 500 = 0.03731 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5203,'chem-4-4-24',NULL,1,'m = 4.03 g; V = 4.03/10.5 = 0.3834 cm³;',1,1);
INSERT INTO rubric_criterion VALUES(5204,'chem-4-4-24',NULL,2,'thickness = 0.3834/50.0 = 7.67 × 10⁻³ cm = 76.7 µm.',1,1);
INSERT INTO rubric_criterion VALUES(5205,'chem-4-4-25',NULL,0,'Galvanic cathode is positive; electrolytic cathode is negative.',1,1);
INSERT INTO rubric_criterion VALUES(5206,'chem-4-4-25',NULL,1,'In a galvanic cell electrons are consumed spontaneously at the cathode leaving it relatively positive; in an electrolytic cell the power supply pushes electrons onto the cathode, making it negative.',1,1);
INSERT INTO rubric_criterion VALUES(5226,'chem-5-1-19',NULL,0,'Pentan-1-ol.',1,1);
INSERT INTO rubric_criterion VALUES(5227,'chem-5-1-20',NULL,0,'CH₃CH₂CH(CH₃)CH₂CH₃',3,1);
INSERT INTO rubric_criterion VALUES(5228,'chem-5-1-21',NULL,0,'The chain should be numbered from the end nearer the branch to give the lowest locant, so the correct name is 2-methylbutane.',2,1);
INSERT INTO rubric_criterion VALUES(5229,'chem-5-1-22',NULL,0,'Methyl methanoate.',1,1);
INSERT INTO rubric_criterion VALUES(5230,'chem-5-1-23',NULL,0,'Hydroxyl (–OH) and carboxyl (–COOH) groups;',1,1);
INSERT INTO rubric_criterion VALUES(5231,'chem-5-1-23',NULL,1,'IUPAC name 2-hydroxypropanoic acid.',1,1);
INSERT INTO rubric_criterion VALUES(5232,'chem-5-1-24',NULL,0,'C₇H₁₆O (C₇H₁₅OH).',1,1);
INSERT INTO rubric_criterion VALUES(5233,'chem-5-1-25',NULL,0,'Ethanol molecules form hydrogen bonds between their –OH groups as well as dispersion forces, whereas propane has only weak dispersion forces;',1,1);
INSERT INTO rubric_criterion VALUES(5234,'chem-5-1-25',NULL,1,'more energy is needed to separate ethanol molecules.',1,1);
INSERT INTO rubric_criterion VALUES(5240,'chem34a2-nom-6',NULL,0,'(a) CH₃CH₂CH(CH₃)CH₂COOH (carbon 1 is the carboxyl carbon, methyl on carbon 3);',1,1);
INSERT INTO rubric_criterion VALUES(5241,'chem34a2-nom-6',NULL,1,'(b) CH₂ClCHClCH₃.',1,1);
INSERT INTO rubric_criterion VALUES(5242,'chem34a2-nom-7',NULL,0,'The name does not use the longest carbon chain: an ethyl group on carbon 2 of butane extends the main chain to 5 carbons;',1,1);
INSERT INTO rubric_criterion VALUES(5243,'chem34a2-nom-7',NULL,1,'drawing it as CH₃CH(CH₂CH₃)CH₂CH₃ shows the longest chain is 5 carbons with a methyl on carbon 3, so the correct name is 3-methylpentane.',1,1);
INSERT INTO rubric_criterion VALUES(5244,'chem34a2-nom-8',NULL,0,'Propyl butanoate;',1,1);
INSERT INTO rubric_criterion VALUES(5245,'chem34a2-nom-8',NULL,1,'CH₃CH₂CH₂COOCH₂CH₂CH₃.',1,1);
INSERT INTO rubric_criterion VALUES(5265,'chem-5-2-19',NULL,0,'Pentane, 2-methylbutane and 2,2-dimethylpropane.',3,1);
INSERT INTO rubric_criterion VALUES(5266,'chem-5-2-20',NULL,0,'Methyl ethanoate (CH₃COOCH₃) and ethyl methanoate (HCOOCH₂CH₃).',2,1);
INSERT INTO rubric_criterion VALUES(5267,'chem-5-2-21',NULL,0,'Pentane is an unbranched chain, so its molecules have a larger surface area of contact and stronger dispersion forces;',1,1);
INSERT INTO rubric_criterion VALUES(5268,'chem-5-2-21',NULL,1,'the compact, branched 2,2-dimethylpropane has weaker dispersion forces.',1,1);
INSERT INTO rubric_criterion VALUES(5269,'chem-5-2-22',NULL,0,'CH₃CH₂CH₂OH, propan-1-ol;',1,1);
INSERT INTO rubric_criterion VALUES(5270,'chem-5-2-22',NULL,1,'CH₃CH(OH)CH₃, propan-2-ol.',1,1);
INSERT INTO rubric_criterion VALUES(5271,'chem-5-2-23',NULL,0,'They have different molecular formulas: but-1-ene is C₄H₈ and butane is C₄H₁₀.',1,1);
INSERT INTO rubric_criterion VALUES(5272,'chem-5-2-24',NULL,0,'3-Chloropentane.',1,1);
INSERT INTO rubric_criterion VALUES(5273,'chem-5-2-25',NULL,0,'Butan-2-one (butanone), CH₃COCH₂CH₃.',1,1);
INSERT INTO rubric_criterion VALUES(5279,'chem34a2-iso-6',NULL,0,'There is no rotation about a carbon–carbon double bond, so groups attached to the double-bond carbons are fixed in position;',1,1);
INSERT INTO rubric_criterion VALUES(5280,'chem34a2-iso-6',NULL,1,'in but-2-ene each double-bond carbon has two different groups (H and CH₃), so the CH₃ groups can be on the same side (cis) or opposite sides (trans);',1,1);
INSERT INTO rubric_criterion VALUES(5281,'chem34a2-iso-6',NULL,2,'in propene one double-bond carbon has two identical H atoms, so swapping them gives the same molecule and no cis–trans isomers exist.',1,1);
INSERT INTO rubric_criterion VALUES(5282,'chem34a2-iso-7',NULL,0,'Butan-1-ol, butan-2-ol, 2-methylpropan-1-ol and 2-methylpropan-2-ol;',1,1);
INSERT INTO rubric_criterion VALUES(5283,'chem34a2-iso-7',NULL,1,'butan-2-ol is chiral because carbon 2 is bonded to four different groups (H, OH, CH₃, C₂H₅).',2,1);
INSERT INTO rubric_criterion VALUES(5284,'chem34a2-iso-8',NULL,0,'Biological receptors and enzymes are themselves chiral, so only one enantiomer may fit the active site and produce the desired effect;',1,1);
INSERT INTO rubric_criterion VALUES(5285,'chem34a2-iso-8',NULL,1,'the other enantiomer may be inactive (wasting material) or cause harmful side effects, as in the case of thalidomide.',1,1);
INSERT INTO rubric_criterion VALUES(5305,'chem-5-3-19',NULL,0,'C₂H₄(g) + H₂O(g) → CH₃CH₂OH(g); phosphoric acid (H₃PO₄) catalyst; addition reaction.',1,1);
INSERT INTO rubric_criterion VALUES(5306,'chem-5-3-20',NULL,0,'CH₃CH₂CH₂Br + NaOH → CH₃CH₂CH₂OH + NaBr (or CH₃CH₂CH₂Br + OH⁻ → CH₃CH₂CH₂OH + Br⁻).',2,1);
INSERT INTO rubric_criterion VALUES(5307,'chem-5-3-21',NULL,0,'Alkenes are unsaturated, containing a C=C double bond that can open to bond to added atoms;',1,1);
INSERT INTO rubric_criterion VALUES(5308,'chem-5-3-21',NULL,1,'alkanes are saturated with only single bonds, so they can only undergo substitution.',1,1);
INSERT INTO rubric_criterion VALUES(5309,'chem-5-3-22',NULL,0,'Distilling the ethanal off as it forms (limited oxidant) stops further oxidation, giving ethanal;',1,1);
INSERT INTO rubric_criterion VALUES(5310,'chem-5-3-22',NULL,1,'heating under reflux with excess oxidant oxidises it fully to ethanoic acid.',1,1);
INSERT INTO rubric_criterion VALUES(5311,'chem-5-3-23',NULL,0,'100%, because it is an addition reaction in which all reactant atoms end up in the single desired product.',2,1);
INSERT INTO rubric_criterion VALUES(5312,'chem-5-3-24',NULL,0,'Atom economy = 46.0 ÷ (64.5 + 40.0) × 100 = 46.0 ÷ 104.5 × 100 ≈ 44.0%.',2,1);
INSERT INTO rubric_criterion VALUES(5313,'chem-5-3-25',NULL,0,'Add bromine water: hexene rapidly decolourises it (orange/brown to colourless) by addition across the C=C;',1,1);
INSERT INTO rubric_criterion VALUES(5314,'chem-5-3-25',NULL,1,'hexane does not decolourise it quickly.',1,1);
INSERT INTO rubric_criterion VALUES(5320,'chem34a2-rxn-6',NULL,0,'CH₃COOH(l) + CH₃OH(l) ⇌ CH₃COOCH₃(l) + H₂O(l);',1,1);
INSERT INTO rubric_criterion VALUES(5321,'chem34a2-rxn-6',NULL,1,'product is methyl ethanoate;',1,1);
INSERT INTO rubric_criterion VALUES(5322,'chem34a2-rxn-6',NULL,2,'conditions: a few drops of concentrated H₂SO₄ as a catalyst and heating under reflux.',1,1);
INSERT INTO rubric_criterion VALUES(5323,'chem34a2-rxn-7',NULL,0,'CH₃CH₂Cl + NH₃ → CH₃CH₂NH₂ + HCl;',1,1);
INSERT INTO rubric_criterion VALUES(5324,'chem34a2-rxn-7',NULL,1,'the product is ethanamine;',1,1);
INSERT INTO rubric_criterion VALUES(5325,'chem34a2-rxn-7',NULL,2,'this is a substitution reaction (the Cl atom is replaced by –NH₂).',1,1);
INSERT INTO rubric_criterion VALUES(5326,'chem34a2-rxn-8',NULL,0,'Propene decolourises the orange/brown bromine water quickly;',1,1);
INSERT INTO rubric_criterion VALUES(5327,'chem34a2-rxn-8',NULL,1,'Br₂ adds across the C=C double bond: CH₂=CHCH₃ + Br₂ → CH₂BrCHBrCH₃ (1,2-dibromopropane);',1,1);
INSERT INTO rubric_criterion VALUES(5328,'chem34a2-rxn-8',NULL,2,'propane is saturated and does not react (without UV light), so the orange colour remains.',1,1);
INSERT INTO rubric_criterion VALUES(5348,'chem-5-4-19',NULL,0,'1) Ethene + steam with H₃PO₄ catalyst → ethanol. 2) Oxidise some ethanol with acidified K₂Cr₂O₇ (or KMnO₄) under reflux → ethanoic acid.',1,1);
INSERT INTO rubric_criterion VALUES(5349,'chem-5-4-19',NULL,1,'3) React ethanol with ethanoic acid using concentrated H₂SO₄ catalyst → ethyl ethanoate + water.',1,1);
INSERT INTO rubric_criterion VALUES(5350,'chem-5-4-20',NULL,0,'CH₃COOH + CH₃OH ⇌ CH₃COOCH₃ + H₂O (concentrated H₂SO₄ catalyst).',1,1);
INSERT INTO rubric_criterion VALUES(5351,'chem-5-4-21',NULL,0,'n(ethanol) = 23.0 ÷ 46.0 = 0.500 mol; theoretical mass = 0.500 × 88.0 = 44.0 g;',1,1);
INSERT INTO rubric_criterion VALUES(5352,'chem-5-4-21',NULL,1,'actual = 0.650 × 44.0 = 28.6 g.',1,1);
INSERT INTO rubric_criterion VALUES(5353,'chem-5-4-22',NULL,0,'Ethyl propanoate; hydrolysis gives propanoic acid and ethanol.',1,1);
INSERT INTO rubric_criterion VALUES(5354,'chem-5-4-23',NULL,0,'1) Heat with NaOH(aq) (substitution) → ethanol.',1,1);
INSERT INTO rubric_criterion VALUES(5355,'chem-5-4-23',NULL,1,'2) Heat under reflux with acidified K₂Cr₂O₇ or KMnO₄ (oxidation) → ethanoic acid.',1,1);
INSERT INTO rubric_criterion VALUES(5356,'chem-5-4-24',NULL,0,'Ethyl methanoate, HCOOCH₂CH₃.',1,1);
INSERT INTO rubric_criterion VALUES(5357,'chem-5-4-25',NULL,0,'Overall yield = 0.90 × 0.80 × 0.75 × 100 = 54%.',2,1);
INSERT INTO rubric_criterion VALUES(5363,'chem34a2-syn-6',NULL,0,'n(CH₃COOH) = 12.0/60.0 = 0.200 mol;',1,1);
INSERT INTO rubric_criterion VALUES(5364,'chem34a2-syn-6',NULL,1,'1 : 1 ratio, so theoretical n(CH₃COOCH₂CH₃) = 0.200 mol, mass = 0.200 × 88.0 = 17.6 g;',1,1);
INSERT INTO rubric_criterion VALUES(5365,'chem34a2-syn-6',NULL,2,'percentage yield = 11.0/17.6 × 100 = 62.5%.',1,1);
INSERT INTO rubric_criterion VALUES(5366,'chem34a2-syn-7',NULL,0,'Step 1: ethene + steam with H₃PO₄ catalyst (about 300 °C) → ethanol;',1,1);
INSERT INTO rubric_criterion VALUES(5367,'chem34a2-syn-7',NULL,1,'step 2: oxidise part of the ethanol with acidified K₂Cr₂O₇ (or KMnO₄), heated, → ethanoic acid;',1,1);
INSERT INTO rubric_criterion VALUES(5368,'chem34a2-syn-7',NULL,2,'step 3: react ethanoic acid with the remaining ethanol, heated under reflux with concentrated H₂SO₄ as a catalyst → ethyl ethanoate + water.',1,1);
INSERT INTO rubric_criterion VALUES(5369,'chem34a2-syn-8',NULL,0,'Molar masses: CH₃COOH 60.0, C₂H₅OH 46.0, ester 88.0 g mol⁻¹; atom economy = 88.0/(60.0 + 46.0) × 100 = 83.0%;',1,1);
INSERT INTO rubric_criterion VALUES(5370,'chem34a2-syn-8',NULL,1,'yield could be increased by using an excess of one reactant (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(5371,'chem34a2-syn-8',NULL,2,'ethanol) or by removing the ester or water as it forms, shifting the equilibrium to the right.',1,1);
INSERT INTO rubric_criterion VALUES(5372,'chem-5-4-c1',NULL,0,'14.4 g',1,1);
INSERT INTO rubric_criterion VALUES(5391,'chem-6-1-19',NULL,0,'The molecular ion is unstable and fragments readily before it reaches the detector, so very few intact molecular ions are detected.',2,1);
INSERT INTO rubric_criterion VALUES(5392,'chem-6-1-20',NULL,0,'m/z = 3(12) + 7(1) = 43.',1,1);
INSERT INTO rubric_criterion VALUES(5393,'chem-6-1-20',NULL,1,'It would be expected in the spectrum of butane (or propan-1-ol, 1-chloropropane, etc.).',2,1);
INSERT INTO rubric_criterion VALUES(5394,'chem-6-1-21',NULL,0,'C₂H₅⁺ (CH₃CH₂⁺). [CH₃CH₂CH₃]⁺ → CH₃CH₂⁺ + CH₃•',1,1);
INSERT INTO rubric_criterion VALUES(5395,'chem-6-1-22',NULL,0,'m/z 64 and 66 in about a 3:1 ratio, because chlorine occurs naturally as ³⁵Cl (about 75%) and ³⁷Cl (about 25%).',2,1);
INSERT INTO rubric_criterion VALUES(5396,'chem-6-1-23',NULL,0,'The ion is CHO⁺ (m/z 29), formed when the molecular ion (m/z 44) loses a methyl radical, CH₃• (mass 15).',1,1);
INSERT INTO rubric_criterion VALUES(5397,'chem-6-1-24',NULL,0,'m/z 57: CH₃CH₂CO⁺ (loss of CH₃•, 72 − 15). m/z 43: CH₃CO⁺ (loss of C₂H₅•, 72 − 29).',1,1);
INSERT INTO rubric_criterion VALUES(5398,'chem-6-1-25',NULL,0,'The sample is vaporised and ionised (an electron is knocked off to form positive ions, some of which fragment).',1,1);
INSERT INTO rubric_criterion VALUES(5399,'chem-6-1-25',NULL,1,'The ions are accelerated, then deflected by a magnetic field according to their mass-to-charge ratio, and detected;',1,1);
INSERT INTO rubric_criterion VALUES(5400,'chem-6-1-25',NULL,2,'the detector records relative abundance against m/z.',1,1);
INSERT INTO rubric_criterion VALUES(5406,'chem34a3-ms-6',NULL,0,'The molecular ion is the whole molecule with one electron removed (charge 1+), so its m/z equals its mass, which is the relative molecular mass (the lost electron has negligible mass);',1,1);
INSERT INTO rubric_criterion VALUES(5407,'chem34a3-ms-6',NULL,1,'the molecular ion may be unstable and fragment almost completely before reaching the detector, so the M⁺ peak is small or missing.',1,1);
INSERT INTO rubric_criterion VALUES(5408,'chem34a3-ms-7',NULL,0,'(a) Peaks at m/z = 108 (CH₃CH₂⁷⁹Br⁺) and m/z = 110 (CH₃CH₂⁸¹Br⁺);',1,1);
INSERT INTO rubric_criterion VALUES(5409,'chem34a3-ms-7',NULL,1,'approximately equal heights (1 : 1) because the two isotopes are about equally abundant;',1,1);
INSERT INTO rubric_criterion VALUES(5410,'chem34a3-ms-7',NULL,2,'(b) m/z = 29 is CH₃CH₂⁺ (C₂H₅⁺), formed by loss of a Br atom from the molecular ion.',1,1);
INSERT INTO rubric_criterion VALUES(5411,'chem34a3-ms-8',NULL,0,'Propanone, CH₃COCH₃ (M = 58); the base peak at 43 is CH₃CO⁺ formed by loss of a CH₃ group (58 − 15 = 43);',1,1);
INSERT INTO rubric_criterion VALUES(5412,'chem34a3-ms-8',NULL,1,'the peak at 15 is CH₃⁺;',1,1);
INSERT INTO rubric_criterion VALUES(5413,'chem34a3-ms-8',NULL,2,'the absence of a peak at 29 (C₂H₅⁺ or CHO⁺) argues against propanal, CH₃CH₂CHO, which has the same molar mass.',1,1);
INSERT INTO rubric_criterion VALUES(5433,'chem-6-2-19',NULL,0,'Carboxylic acid molecules form strong hydrogen bonds with each other (often as dimers).',1,1);
INSERT INTO rubric_criterion VALUES(5434,'chem-6-2-19',NULL,1,'This gives a range of O–H bond strengths, so the O–H absorbs over a wide range of wavenumbers (about 2500–3000 cm⁻¹).',1,1);
INSERT INTO rubric_criterion VALUES(5435,'chem-6-2-20',NULL,0,'Butan-1-ol shows a broad O–H absorption at about 3200–3600 cm⁻¹ and no C=O peak.',1,1);
INSERT INTO rubric_criterion VALUES(5436,'chem-6-2-20',NULL,1,'Butanal shows a strong, sharp C=O absorption at about 1700 cm⁻¹ and no broad O–H band.',1,1);
INSERT INTO rubric_criterion VALUES(5437,'chem-6-2-21',NULL,0,'Although the molecule has no overall dipole, its asymmetric stretching and bending vibrations create a temporary change in dipole moment, so those vibrations absorb IR radiation.',2,1);
INSERT INTO rubric_criterion VALUES(5438,'chem-6-2-22',NULL,0,'The region below about 1500 cm⁻¹ contains complex absorptions from bending and skeletal vibrations that are unique to each compound.',1,1);
INSERT INTO rubric_criterion VALUES(5439,'chem-6-2-22',NULL,1,'Matching a sample''s fingerprint region to a reference spectrum confirms its identity.',1,1);
INSERT INTO rubric_criterion VALUES(5440,'chem-6-2-23',NULL,0,'Propanone forms.',1,1);
INSERT INTO rubric_criterion VALUES(5441,'chem-6-2-23',NULL,1,'A strong C=O absorption appears at about 1700 cm⁻¹ and the broad alcohol O–H absorption at 3200–3600 cm⁻¹ disappears.',1,1);
INSERT INTO rubric_criterion VALUES(5442,'chem-6-2-24',NULL,0,'IR mainly identifies the functional groups present; it does not give the molecular mass, the number of carbon atoms or how the carbon skeleton is arranged, so isomers can be hard to tell apart.',1,1);
INSERT INTO rubric_criterion VALUES(5443,'chem-6-2-25',NULL,0,'Vibrational energy levels are quantised.',1,1);
INSERT INTO rubric_criterion VALUES(5444,'chem-6-2-25',NULL,1,'A bond absorbs only photons whose energy exactly matches the gap between its vibrational levels, and that gap depends on bond strength and the masses of the atoms.',1,1);
INSERT INTO rubric_criterion VALUES(5450,'chem34a3-ir-6',NULL,0,'Propan-1-ol: broad O–H (alcohol) absorption around 3200–3600 cm⁻¹ and no C=O absorption;',1,1);
INSERT INTO rubric_criterion VALUES(5451,'chem34a3-ir-6',NULL,1,'propanal: strong C=O absorption around 1700–1740 cm⁻¹ and no broad O–H band;',1,1);
INSERT INTO rubric_criterion VALUES(5452,'chem34a3-ir-6',NULL,2,'propanoic acid: both a C=O absorption near 1700 cm⁻¹ and a very broad O–H (acid) absorption from about 2500–3300 cm⁻¹ overlapping the C–H region.',1,1);
INSERT INTO rubric_criterion VALUES(5453,'chem34a3-ir-7',NULL,0,'Alcohol molecules are hydrogen bonded to each other in the liquid;',1,1);
INSERT INTO rubric_criterion VALUES(5454,'chem34a3-ir-7',NULL,1,'the strength of these hydrogen bonds varies between molecules, so O–H bonds vibrate over a range of frequencies (wavenumbers), producing a broad absorption band.',1,1);
INSERT INTO rubric_criterion VALUES(5455,'chem34a3-ir-8',NULL,0,'The student is correct: the ester has no O–H group, so a pure sample shows no broad O–H absorption (a band there would indicate unreacted ethanol, ethanoic acid or water);',1,1);
INSERT INTO rubric_criterion VALUES(5456,'chem34a3-ir-8',NULL,1,'a strong C=O absorption around 1735–1750 cm⁻¹ should be present (C–O and C–H absorptions are also acceptable).',1,1);
INSERT INTO rubric_criterion VALUES(5476,'chem-6-3-19',NULL,0,'Two signals: the CH₃ signal is a triplet (area 3) and the CH₂ signal is a quartet (area 2), with the CH₂ at the higher chemical shift because it is next to Cl.',2,1);
INSERT INTO rubric_criterion VALUES(5477,'chem-6-3-20',NULL,0,'Any two of: it gives one strong signal because all 12 H (and 4 C) are equivalent; its signal sits away from most organic signals (defined as 0 ppm);',1,1);
INSERT INTO rubric_criterion VALUES(5478,'chem-6-3-20',NULL,1,'it is chemically inert; it is volatile, so it is easily removed;',1,1);
INSERT INTO rubric_criterion VALUES(5479,'chem-6-3-20',NULL,2,'it is non-toxic.',1,1);
INSERT INTO rubric_criterion VALUES(5480,'chem-6-3-21',NULL,0,'Four peaks.',1,1);
INSERT INTO rubric_criterion VALUES(5481,'chem-6-3-21',NULL,1,'Each of the four carbon atoms is in a different chemical environment because the molecule has no symmetry that makes any two carbons equivalent.',2,1);
INSERT INTO rubric_criterion VALUES(5482,'chem-6-3-22',NULL,0,'An ethyl group (–CH₂CH₃).',1,1);
INSERT INTO rubric_criterion VALUES(5483,'chem-6-3-22',NULL,1,'The CH₃ is split into a triplet by the 2 neighbouring CH₂ hydrogens, and the CH₂ is split into a quartet by the 3 neighbouring CH₃ hydrogens.',1,1);
INSERT INTO rubric_criterion VALUES(5484,'chem-6-3-23',NULL,0,'Propanone, CH₃COCH₃.',1,1);
INSERT INTO rubric_criterion VALUES(5485,'chem-6-3-23',NULL,1,'All six hydrogens are equivalent (two identical CH₃ groups on either side of the C=O) and have no non-equivalent neighbouring hydrogens, so they give one singlet.',1,1);
INSERT INTO rubric_criterion VALUES(5486,'chem-6-3-24',NULL,0,'Propan-2-ol, CH₃CH(OH)CH₃.',1,1);
INSERT INTO rubric_criterion VALUES(5487,'chem-6-3-24',NULL,1,'¹H NMR: a doublet (6H) for the two equivalent CH₃ groups, a septet (1H) for the CH, and a singlet (1H) for the OH.',1,1);
INSERT INTO rubric_criterion VALUES(5488,'chem-6-3-25',NULL,0,'The area under each signal is proportional to the number of hydrogen atoms in that environment.',1,1);
INSERT INTO rubric_criterion VALUES(5489,'chem-6-3-25',NULL,1,'The area ratio therefore shows how many H are in each environment, for example 3 : 2 suggests CH₃ and CH₂ groups.',1,1);
INSERT INTO rubric_criterion VALUES(5495,'chem34a3-nmr-6',NULL,0,'Three signals (three H environments); CH₃: triplet (split by 2 H on CH₂), relative area 3, about 1.2 ppm;',1,1);
INSERT INTO rubric_criterion VALUES(5496,'chem34a3-nmr-6',NULL,1,'CH₂: quartet (split by 3 H on CH₃), relative area 2, about 3.6 ppm (shifted downfield by the O);',1,1);
INSERT INTO rubric_criterion VALUES(5497,'chem34a3-nmr-6',NULL,2,'OH: singlet, relative area 1, variable shift (about 2–5 ppm).',1,1);
INSERT INTO rubric_criterion VALUES(5498,'chem34a3-nmr-7',NULL,0,'Ethyl ethanoate has a CH₃ singlet near 2.0 ppm (CH₃ next to C=O), whereas methyl propanoate has a CH₃ singlet near 3.7 ppm (CH₃ bonded to O); in ethyl ethanoate the CH₂ quartet is near 4.1 ppm (CH₂ bonded to O), whereas in methyl propanoate the CH₂ quartet is near 2.3 ppm (CH₂ next to C=O).',1,1);
INSERT INTO rubric_criterion VALUES(5499,'chem34a3-nmr-7',NULL,1,'Both show a triplet/quartet/singlet pattern with areas 3 : 2 : 3, so chemical shift is the key difference.',1,1);
INSERT INTO rubric_criterion VALUES(5500,'chem34a3-nmr-8',NULL,0,'Propan-2-ol, CH₃CH(OH)CH₃;',1,1);
INSERT INTO rubric_criterion VALUES(5501,'chem34a3-nmr-8',NULL,1,'two ¹³C peaks show two carbon environments (the two equivalent CH₃ carbons and the CH carbon), whereas propan-1-ol would give three;',1,1);
INSERT INTO rubric_criterion VALUES(5502,'chem34a3-nmr-8',NULL,2,'the doublet with area 6 arises from 6 equivalent CH₃ hydrogens split by the single H on the adjacent CH carbon (n + 1 = 2).',1,1);
INSERT INTO rubric_criterion VALUES(5522,'chem-6-4-19',NULL,0,'c = (4200 ÷ 3000) × 20.0 = 28.0 mg/L',2,1);
INSERT INTO rubric_criterion VALUES(5523,'chem-6-4-20',NULL,0,'n(NaOH) = 0.1000 × 0.02150 = 2.150 × 10⁻³ mol = n(CH₃COOH). Diluted c = 2.150 × 10⁻³ ÷ 0.02500 = 0.0860 M;',1,1);
INSERT INTO rubric_criterion VALUES(5524,'chem-6-4-20',NULL,1,'original c = 0.0860 × 10 = 0.860 M.',1,1);
INSERT INTO rubric_criterion VALUES(5525,'chem-6-4-20',NULL,2,'Mass in 100 mL = 0.0860 mol × 60.05 = 5.16 g, so 5.16% (w/v).',1,1);
INSERT INTO rubric_criterion VALUES(5526,'chem-6-4-21',NULL,0,'Solid NaOH is hygroscopic (it absorbs water from the air) and reacts with atmospheric CO₂.',1,1);
INSERT INTO rubric_criterion VALUES(5527,'chem-6-4-21',NULL,1,'Its mass therefore does not reflect the true amount of NaOH, so a solution of accurately known concentration cannot be made by weighing it.',1,1);
INSERT INTO rubric_criterion VALUES(5528,'chem-6-4-22',NULL,0,'Each compound has a different balance of attraction to the stationary phase and solubility in the mobile phase (for example, due to differences in polarity).',1,1);
INSERT INTO rubric_criterion VALUES(5529,'chem-6-4-22',NULL,1,'The compound more strongly adsorbed to the stationary phase moves more slowly and has a longer retention time.',2,1);
INSERT INTO rubric_criterion VALUES(5530,'chem-6-4-23',NULL,0,'The water left in the pipette dilutes the aliquot, so it contains fewer moles of analyte.',1,1);
INSERT INTO rubric_criterion VALUES(5531,'chem-6-4-23',NULL,1,'The titre is smaller, and the calculated concentration is lower than the true value.',1,1);
INSERT INTO rubric_criterion VALUES(5532,'chem-6-4-24',NULL,0,'n(MnO₄⁻) = 0.0150 × 0.01240 = 1.86 × 10⁻⁴ mol;',1,1);
INSERT INTO rubric_criterion VALUES(5533,'chem-6-4-24',NULL,1,'n(Fe²⁺) = 5 × 1.86 × 10⁻⁴ = 9.30 × 10⁻⁴ mol;',1,1);
INSERT INTO rubric_criterion VALUES(5534,'chem-6-4-24',NULL,2,'m = 9.30 × 10⁻⁴ × 55.85 = 0.0519 g = 51.9 mg.',1,1);
INSERT INTO rubric_criterion VALUES(5535,'chem-6-4-25',NULL,0,'Small particles give the stationary phase a very large surface area, which improves separation and resolution.',1,1);
INSERT INTO rubric_criterion VALUES(5536,'chem-6-4-25',NULL,1,'They also pack tightly and resist flow, so high pressure is needed to push the mobile phase through the column at a useful rate.',1,1);
INSERT INTO rubric_criterion VALUES(5542,'chem34a3-chr-6',NULL,0,'(a) Retention time is used for qualitative identification: a component is identified by comparing its retention time with that of a known standard run under identical conditions (same column, mobile phase, flow rate, temperature);',1,1);
INSERT INTO rubric_criterion VALUES(5543,'chem34a3-chr-6',NULL,1,'(b) peak area is proportional to the amount/concentration of the component;',1,1);
INSERT INTO rubric_criterion VALUES(5544,'chem34a3-chr-6',NULL,2,'it is used quantitatively by comparing with a calibration curve made from standards of known concentration.',1,1);
INSERT INTO rubric_criterion VALUES(5545,'chem34a3-chr-7',NULL,0,'Different compounds can have the same (or very similar) retention time under a given set of conditions, so a match is not proof of identity;',1,1);
INSERT INTO rubric_criterion VALUES(5546,'chem34a3-chr-7',NULL,1,'confirmation could be obtained by spiking the sample with the standard and checking that only the single peak increases (no new peak), by repeating with a different column or mobile phase, or by coupling HPLC to a mass spectrometer.',1,1);
INSERT INTO rubric_criterion VALUES(5547,'chem34a3-chr-8',NULL,0,'Concentration in original drink = 12.4 × (50.0 ÷ 10.0) = 62.0 mg L⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(5548,'chem34a3-chr-8',NULL,1,'mass in 0.600 L = 62.0 × 0.600 = 37.2 mg.',1,1);
INSERT INTO rubric_criterion VALUES(5554,'chem34a3-vol-6',NULL,0,'n(I₂) = 0.0250 × 0.02270 = 5.675 × 10⁻⁴ mol = n(vitamin C) in 20.00 mL;',1,1);
INSERT INTO rubric_criterion VALUES(5555,'chem34a3-vol-6',NULL,1,'n in 100.0 mL = 5.675 × 10⁻⁴ × (100.0 ÷ 20.00) = 2.838 × 10⁻³ mol;',1,1);
INSERT INTO rubric_criterion VALUES(5556,'chem34a3-vol-6',NULL,2,'m = 2.838 × 10⁻³ × 176.0 = 0.499 g (3 significant figures, limited by 0.0250 mol L⁻¹).',1,1);
INSERT INTO rubric_criterion VALUES(5557,'chem34a3-vol-7',NULL,0,'Concordant titres are titres that agree closely with each other, typically within 0.10 mL;',1,1);
INSERT INTO rubric_criterion VALUES(5558,'chem34a3-vol-7',NULL,1,'averaging only concordant titres excludes the rough/trial titre and any outliers, which reduces the effect of random errors and improves the precision (and reliability) of the result.',1,1);
INSERT INTO rubric_criterion VALUES(5559,'chem34a3-vol-8',NULL,0,'n(NaOH) = 0.115 × 0.02465 = 2.835 × 10⁻³ mol = n(acid) (1 : 1 for a monoprotic acid);',1,1);
INSERT INTO rubric_criterion VALUES(5560,'chem34a3-vol-8',NULL,1,'M = 0.250 ÷ 2.835 × 10⁻³ = 88.2 g mol⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(5561,'chem34a3-vol-8',NULL,2,'this matches butanoic acid, CH₃CH₂CH₂COOH (88.0 g mol⁻¹).',1,1);
INSERT INTO rubric_criterion VALUES(5562,'chem-6-4-c1',NULL,0,'0.860 M',3,1);
INSERT INTO rubric_criterion VALUES(5581,'chem-7-1-19',NULL,0,'H₂NCH₂CONHCH(CH₃)COOH (water is also produced).',1,1);
INSERT INTO rubric_criterion VALUES(5582,'chem-7-1-20',NULL,0,'The extra kinetic energy disrupts the hydrogen bonds, ionic interactions and dispersion forces that maintain the secondary and tertiary structure, so the protein unfolds (denatures).',1,1);
INSERT INTO rubric_criterion VALUES(5583,'chem-7-1-20',NULL,1,'Its specific 3D shape (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(5584,'chem-7-1-20',NULL,2,'active site) is lost, so it can no longer function, even though the peptide bonds remain.',1,1);
INSERT INTO rubric_criterion VALUES(5585,'chem-7-1-21',NULL,0,'Secondary structure is the local folding of the backbone into α-helices or β-pleated sheets, held by hydrogen bonds between backbone C=O and N–H groups.',1,1);
INSERT INTO rubric_criterion VALUES(5586,'chem-7-1-21',NULL,1,'Tertiary structure is the overall 3D folding of the whole chain, held by interactions between side chains (hydrogen bonds, ionic interactions, dispersion forces and covalent disulfide bridges).',2,1);
INSERT INTO rubric_criterion VALUES(5587,'chem-7-1-22',NULL,0,'C₃H₇NO₂ (alanine).',1,1);
INSERT INTO rubric_criterion VALUES(5588,'chem-7-1-23',NULL,0,'Many individual plant proteins are low in one or more essential amino acids (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(5589,'chem-7-1-23',NULL,1,'grains are low in lysine, legumes in methionine).',1,1);
INSERT INTO rubric_criterion VALUES(5590,'chem-7-1-23',NULL,2,'Combining complementary proteins ensures all essential amino acids, which the body cannot synthesise, are obtained in sufficient amounts.',1,1);
INSERT INTO rubric_criterion VALUES(5591,'chem-7-1-24',NULL,0,'Lowering the pH protonates –COO⁻ side chains to –COOH, changing the charges on R groups.',1,1);
INSERT INTO rubric_criterion VALUES(5592,'chem-7-1-24',NULL,1,'This disrupts the ionic interactions and hydrogen bonds that hold the tertiary structure, so the proteins unfold and clump together (coagulate).',1,1);
INSERT INTO rubric_criterion VALUES(5593,'chem-7-1-25',NULL,0,'900 g',2,1);
INSERT INTO rubric_criterion VALUES(5599,'chem34a3-prot-6',NULL,0,'Changing the pH alters the concentration of H⁺, which changes the charges on acidic and basic R groups (e.g. –COOH/–COO⁻ and –NH₂/–NH₃⁺) in the enzyme;',1,1);
INSERT INTO rubric_criterion VALUES(5600,'chem34a3-prot-6',NULL,1,'this disrupts ionic interactions and hydrogen bonds that maintain the tertiary structure, changing the shape of the active site; the substrate can no longer bind as effectively (and charged groups involved in catalysis may be altered), so activity decreases;',1,1);
INSERT INTO rubric_criterion VALUES(5601,'chem34a3-prot-6',NULL,2,'large changes cause denaturation.',1,1);
INSERT INTO rubric_criterion VALUES(5602,'chem34a3-prot-7',NULL,0,'A coenzyme is a non-protein organic molecule that binds to an enzyme (often at or near the active site) and is required for the enzyme to catalyse its reaction, frequently by carrying electrons, atoms or groups;',1,1);
INSERT INTO rubric_criterion VALUES(5603,'chem34a3-prot-7',NULL,1,'without enough of the vitamin, the coenzyme cannot be made, so the enzymes that depend on it are less active and those reactions proceed more slowly.',1,1);
INSERT INTO rubric_criterion VALUES(5604,'chem34a3-prot-8',NULL,0,'H₂NCH₂CONHCH(CH₃)COOH, i.e. glycine is at the N-terminal end: the –COOH of glycine and the –NH₂ of alanine join to form –CO–NH–;',1,1);
INSERT INTO rubric_criterion VALUES(5605,'chem34a3-prot-8',NULL,1,'it is a condensation reaction releasing one H₂O molecule;',1,1);
INSERT INTO rubric_criterion VALUES(5606,'chem34a3-prot-8',NULL,2,'the bond formed is a peptide (amide) bond.',1,1);
INSERT INTO rubric_criterion VALUES(5626,'chem-7-2-19',NULL,0,'Glucose is a small molecule with five –OH groups that form many hydrogen bonds with water.',1,1);
INSERT INTO rubric_criterion VALUES(5627,'chem-7-2-19',NULL,1,'A triglyceride is a large molecule dominated by long non-polar hydrocarbon chains that can only form dispersion forces, so it cannot form enough attractions with water to dissolve.',2,1);
INSERT INTO rubric_criterion VALUES(5628,'chem-7-2-20',NULL,0,'(a) Glucose. (b) Glycerol and three fatty acids.',1,1);
INSERT INTO rubric_criterion VALUES(5629,'chem-7-2-21',NULL,0,'The cis C=C double bonds in unsaturated chains create kinks, so the molecules cannot pack closely.',1,1);
INSERT INTO rubric_criterion VALUES(5630,'chem-7-2-21',NULL,1,'This weakens the dispersion forces between molecules, so less energy is needed to separate them and the melting point is lower.',1,1);
INSERT INTO rubric_criterion VALUES(5631,'chem-7-2-22',NULL,0,'36.0 g',2,1);
INSERT INTO rubric_criterion VALUES(5632,'chem-7-2-23',NULL,0,'Antioxidants are preferentially oxidised (they react with oxygen or free radicals more readily than the C=C bonds in the unsaturated fats), so the oils in the nuts are protected from oxidation and rancid-smelling breakdown products form more slowly.',2,1);
INSERT INTO rubric_criterion VALUES(5633,'chem-7-2-24',NULL,0,'Both are polymers of α-glucose.',1,1);
INSERT INTO rubric_criterion VALUES(5634,'chem-7-2-24',NULL,1,'Amylose is unbranched (α-1,4 links only), while amylopectin is branched (α-1,4 and α-1,6 links).',1,1);
INSERT INTO rubric_criterion VALUES(5635,'chem-7-2-24',NULL,2,'Foods high in amylose have a lower GI because the unbranched chains coil tightly and are hydrolysed more slowly.',1,1);
INSERT INTO rubric_criterion VALUES(5636,'chem-7-2-25',NULL,0,'3 C=C double bonds; polyunsaturated.',1,1);
INSERT INTO rubric_criterion VALUES(5642,'chem34a3-carb-6',NULL,0,'Glycogen is more highly branched than starch (amylopectin), with α(1→6) branch points occurring more frequently;',1,1);
INSERT INTO rubric_criterion VALUES(5643,'chem34a3-carb-6',NULL,1,'the many branch ends provide many sites where enzymes can hydrolyse glucose units at the same time, allowing rapid release of glucose when needed.',1,1);
INSERT INTO rubric_criterion VALUES(5644,'chem34a3-carb-7',NULL,0,'Because aspartame is about 200 times sweeter, only a tiny mass is needed to achieve the same sweetness;',1,1);
INSERT INTO rubric_criterion VALUES(5645,'chem34a3-carb-7',NULL,1,'although it releases a similar amount of energy per gram to sucrose (it is a dipeptide derivative, around 17 kJ g⁻¹), the very small mass contributes negligible energy to the drink.',1,1);
INSERT INTO rubric_criterion VALUES(5646,'chem34a3-carb-8',NULL,0,'Amylose is unbranched and coils tightly into a helix, so it has fewer exposed chain ends for amylase enzymes to act on and is hydrolysed more slowly; glucose is therefore released into the bloodstream more slowly, giving a smaller, slower rise in blood glucose (lower GI);',1,1);
INSERT INTO rubric_criterion VALUES(5647,'chem34a3-carb-8',NULL,1,'a benefit is better blood-glucose control (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(5648,'chem34a3-carb-8',NULL,2,'for people with diabetes) or feeling full for longer / more sustained energy release.',1,1);
INSERT INTO rubric_criterion VALUES(5654,'chem34a3-fat-6',NULL,0,'An omega-3 fatty acid is an unsaturated fatty acid whose first carbon–carbon double bond is located at the third carbon counting from the methyl (omega) end of the chain; it is essential because the human body cannot synthesise it (cannot insert a double bond at that position), so it must be obtained from food (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(5655,'chem34a3-fat-6',NULL,1,'fish, flaxseed).',1,1);
INSERT INTO rubric_criterion VALUES(5656,'chem34a3-fat-7',NULL,0,'Oxidative rancidity occurs when oxygen reacts at carbon–carbon double bonds, breaking the chains into smaller, unpleasant-smelling aldehydes, ketones and acids; polyunsaturated oils have more C=C bonds, so they oxidise more readily than saturated fats;',1,1);
INSERT INTO rubric_criterion VALUES(5657,'chem34a3-fat-7',NULL,1,'manufacturers add antioxidants (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(5658,'chem34a3-fat-7',NULL,2,'vitamin E/tocopherols), store in airtight, opaque or nitrogen-flushed containers, or refrigerate to slow oxidation.',1,1);
INSERT INTO rubric_criterion VALUES(5659,'chem34a3-fat-8',NULL,0,'Vitamin C''s many –OH groups form hydrogen bonds with water, making it water-soluble;',1,1);
INSERT INTO rubric_criterion VALUES(5660,'chem34a3-fat-8',NULL,1,'vitamin A is largely non-polar, so it interacts by dispersion forces with fats and is fat-soluble rather than water-soluble;',1,1);
INSERT INTO rubric_criterion VALUES(5661,'chem34a3-fat-8',NULL,2,'consequence: vitamin C is not stored and excess is excreted, so it must be consumed regularly, whereas vitamin A is stored in body fat/liver and excessive intake can accumulate to toxic levels.',1,1);
INSERT INTO rubric_criterion VALUES(5681,'chem-7-3-19',NULL,0,'Amylase''s active site has a shape and chemical environment complementary to the α-glycosidic links in starch.',1,1);
INSERT INTO rubric_criterion VALUES(5682,'chem-7-3-19',NULL,1,'Cellulose has β-glycosidic links, giving a different 3D shape that does not fit the active site, so amylase cannot bind and hydrolyse it.',1,1);
INSERT INTO rubric_criterion VALUES(5683,'chem-7-3-20',NULL,0,'From 20 °C to 37 °C, particles have more kinetic energy, so enzyme–substrate collisions are more frequent and energetic, increasing rate.',1,1);
INSERT INTO rubric_criterion VALUES(5684,'chem-7-3-20',NULL,1,'Above about 45 °C the hydrogen bonds and other interactions holding the tertiary structure break, so the enzyme denatures, the active site changes shape and activity falls.',2,1);
INSERT INTO rubric_criterion VALUES(5685,'chem-7-3-21',NULL,0,'A cofactor is a non-protein component needed for enzyme activity; inorganic cofactors are metal ions such as Mg²⁺ or Zn²⁺.',1,1);
INSERT INTO rubric_criterion VALUES(5686,'chem-7-3-21',NULL,1,'A coenzyme is an organic cofactor, often derived from a vitamin, such as NAD⁺ (from niacin, vitamin B3).',1,1);
INSERT INTO rubric_criterion VALUES(5687,'chem-7-3-22',NULL,0,'Vitamin C is water-soluble, so excess dissolves in blood and is excreted in urine.',1,1);
INSERT INTO rubric_criterion VALUES(5688,'chem-7-3-22',NULL,1,'Vitamins A and D are fat-soluble, so excess is stored in the liver and fatty tissue and can accumulate to toxic levels.',1,1);
INSERT INTO rubric_criterion VALUES(5689,'chem-7-3-23',NULL,0,'The statement is incorrect. Denaturation disrupts the secondary and tertiary (and quaternary) structure by breaking weak interactions, but the covalent peptide bonds of the primary structure are not broken.',1,1);
INSERT INTO rubric_criterion VALUES(5690,'chem-7-3-23',NULL,1,'Breaking the protein into amino acids would require hydrolysis.',1,1);
INSERT INTO rubric_criterion VALUES(5691,'chem-7-3-24',NULL,0,'Vitamin D is mostly non-polar, so it forms dispersion forces with the non-polar hydrocarbon chains of triglycerides in fat tissue.',1,1);
INSERT INTO rubric_criterion VALUES(5692,'chem-7-3-24',NULL,1,'It cannot form enough hydrogen bonds with water to dissolve in blood plasma, so it dissolves in and is stored in fat.',2,1);
INSERT INTO rubric_criterion VALUES(5693,'chem-7-3-25',NULL,0,'Bromelain in fresh pineapple catalyses hydrolysis of peptide bonds in gelatine, breaking it into smaller peptides that cannot form a gel.',1,1);
INSERT INTO rubric_criterion VALUES(5694,'chem-7-3-25',NULL,1,'Heating during canning denatures bromelain, so its active site is lost and it can no longer hydrolyse the gelatine.',1,1);
INSERT INTO rubric_criterion VALUES(5714,'chem-7-4-19',NULL,0,'9.41 kJ g⁻¹',2,1);
INSERT INTO rubric_criterion VALUES(5715,'chem-7-4-20',NULL,0,'3.60 kJ g⁻¹',2,1);
INSERT INTO rubric_criterion VALUES(5716,'chem-7-4-21',NULL,0,'Heat is lost to the surroundings (air, the can and the clamp), and the food may burn incompletely, leaving soot or unburnt residue, so the water absorbs less energy than the food contains.',1,1);
INSERT INTO rubric_criterion VALUES(5717,'chem-7-4-21',NULL,1,'Improvements include using a bomb calorimeter or insulating/shielding the apparatus and calibrating it electrically.',2,1);
INSERT INTO rubric_criterion VALUES(5718,'chem-7-4-22',NULL,0,'In the small intestine, bile emulsifies the fat and the enzyme lipase (from the pancreas) catalyses hydrolysis of the three ester bonds.',1,1);
INSERT INTO rubric_criterion VALUES(5719,'chem-7-4-22',NULL,1,'The products are glycerol and fatty acids (often absorbed as monoglycerides and fatty acids).',1,1);
INSERT INTO rubric_criterion VALUES(5720,'chem-7-4-23',NULL,0,'Fat releases about 37 kJ g⁻¹ compared with about 16 kJ g⁻¹ for carbohydrate, because it is less oxidised.',1,1);
INSERT INTO rubric_criterion VALUES(5721,'chem-7-4-23',NULL,1,'Fat is also stored without water (it is non-polar), whereas glycogen is stored hydrated, so fat stores far more energy per unit mass.',2,1);
INSERT INTO rubric_criterion VALUES(5722,'chem-7-4-24',NULL,0,'326 kJ',2,1);
INSERT INTO rubric_criterion VALUES(5723,'chem-7-4-25',NULL,0,'Humans lack the enzyme cellulase needed to hydrolyse the β-glycosidic links in cellulose, so it cannot be broken down into glucose and absorbed.',1,1);
INSERT INTO rubric_criterion VALUES(5724,'chem-7-4-25',NULL,1,'It passes through the digestive tract largely unchanged, though it aids digestive health.',1,1);
INSERT INTO rubric_criterion VALUES(5730,'chem34a3-en-6',NULL,0,'Energy released = 2.50 × 6.40 = 16.0 kJ;',1,1);
INSERT INTO rubric_criterion VALUES(5731,'chem34a3-en-6',NULL,1,'energy content = 16.0 ÷ 1.20 = 13.3 kJ g⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(5732,'chem34a3-en-7',NULL,0,'q = 200 × 4.18 × 15.0 = 12 540 J = 12.54 kJ; n(ethanol) = 0.850 ÷ 46.0 = 1.848 × 10⁻² mol;',1,1);
INSERT INTO rubric_criterion VALUES(5733,'chem34a3-en-7',NULL,1,'ΔH = −12.54 ÷ 1.848 × 10⁻² = −679 kJ mol⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(5734,'chem34a3-en-7',NULL,2,'much less negative than −1364 kJ mol⁻¹ because heat is lost to the surroundings/container (and combustion may be incomplete), so not all the energy released is absorbed by the water.',1,1);
INSERT INTO rubric_criterion VALUES(5735,'chem34a3-en-8',NULL,0,'Fats consist mostly of long hydrocarbon chains with many C–H bonds and very little oxygen, so they are in a much less oxidised (more reduced) state than carbohydrates, which already contain many C–O/O–H groups;',1,1);
INSERT INTO rubric_criterion VALUES(5736,'chem34a3-en-8',NULL,1,'oxidising fats to CO₂ and H₂O therefore forms many more strong C=O and O–H bonds per gram, releasing more energy (about 37 kJ g⁻¹ versus 16 kJ g⁻¹).',1,1);
INSERT INTO rubric_criterion VALUES(5737,'chem-7-4-c1',NULL,0,'396 kJ',2,1);
INSERT INTO rubric_criterion VALUES(5741,'chem-8-1-4',NULL,0,'Preventing waste avoids the need for extra treatment processes, which themselves use energy, materials and money and can still produce hazardous residues.',1,1);
INSERT INTO rubric_criterion VALUES(5742,'chem-8-1-4',NULL,1,'It also removes the risk of waste escaping into the environment.',1,1);
INSERT INTO rubric_criterion VALUES(5746,'chem-8-1-8',NULL,0,'Catalysis: the enzyme speeds up the reaction without being consumed, reducing waste.',1,1);
INSERT INTO rubric_criterion VALUES(5747,'chem-8-1-8',NULL,1,'Design for energy efficiency: the reaction proceeds at low temperature and atmospheric pressure, so less energy is needed.',1,1);
INSERT INTO rubric_criterion VALUES(5748,'chem-8-1-8',NULL,2,'(Use of renewable feedstocks also accepted if a plant sugar is the substrate.)',1,1);
INSERT INTO rubric_criterion VALUES(5752,'chem-8-1-12',NULL,0,'Advantage: it is non-toxic and non-flammable and can be removed simply by releasing pressure, leaving no solvent residue. Disadvantage: high pressures are needed, requiring energy and specialised equipment (and CO₂ is a greenhouse gas if released).',1,1);
INSERT INTO rubric_criterion VALUES(5756,'chem-8-1-16',NULL,0,'A renewable feedstock can be replaced by natural processes within a human timescale, e.g. sugar cane or vegetable oils.',1,1);
INSERT INTO rubric_criterion VALUES(5757,'chem-8-1-16',NULL,1,'A non-renewable feedstock is used faster than it forms, e.g. crude oil or natural gas.',1,1);
INSERT INTO rubric_criterion VALUES(5761,'chem-8-1-20',NULL,0,'Continuous monitoring during a reaction detects changes such as rising temperature or formation of unwanted by-products as they occur, so operators can adjust conditions immediately.',1,1);
INSERT INTO rubric_criterion VALUES(5762,'chem-8-1-20',NULL,1,'This prevents large amounts of hazardous waste forming or being released.',1,1);
INSERT INTO rubric_criterion VALUES(5766,'chem-8-1-24',NULL,0,'Replace the solvent with a safer one such as water or supercritical CO₂ (safer solvents), and minimise the quantity stored by generating or ordering it as needed (inherently safer chemistry for accident prevention).',2,1);
INSERT INTO rubric_criterion VALUES(5767,'chem-8-1-25',NULL,0,'Steam reforming uses a non-renewable fossil fuel feedstock, needs high temperatures (often from burning fossil fuels) and produces carbon monoxide/carbon dioxide.',1,1);
INSERT INTO rubric_criterion VALUES(5768,'chem-8-1-25',NULL,1,'Solar-powered electrolysis uses a renewable energy source and water, and produces only oxygen as a by-product.',2,1);
INSERT INTO rubric_criterion VALUES(5773,'chem-8-2-4',NULL,0,'AE = 50.5 ÷ (16.0 + 71.0) × 100 = 50.5 ÷ 87.0 × 100 = 58.0%',2,1);
INSERT INTO rubric_criterion VALUES(5777,'chem-8-2-8',NULL,0,'With anhydride: 180.0 ÷ 240.0 × 100 = 75.0%.',1,1);
INSERT INTO rubric_criterion VALUES(5778,'chem-8-2-8',NULL,1,'With ethanoic acid: 180.0 ÷ 198.0 × 100 = 90.9%.',1,1);
INSERT INTO rubric_criterion VALUES(5779,'chem-8-2-8',NULL,2,'The ethanoic acid route has the higher atom economy.',1,1);
INSERT INTO rubric_criterion VALUES(5783,'chem-8-2-12',NULL,0,'Atom economy is calculated only from the balanced equation and molar masses, assuming complete reaction, so it shows the maximum fraction of reactant atoms that can end up in the product.',1,1);
INSERT INTO rubric_criterion VALUES(5784,'chem-8-2-12',NULL,1,'Percentage yield compares the mass of product actually obtained with the theoretical maximum, so it requires experimental data.',2,1);
INSERT INTO rubric_criterion VALUES(5788,'chem-8-2-16',NULL,0,'If CO₂ is also a useful product, its mass is included in the numerator, so the effective atom economy rises from 51.1% (ethanol only) to 100%, because all the mass of the reactant ends up in useful products.',2,1);
INSERT INTO rubric_criterion VALUES(5792,'chem-8-2-20',NULL,0,'AE = 28.0 ÷ 30.0 × 100 = 93.3%',2,1);
INSERT INTO rubric_criterion VALUES(5796,'chem-8-2-24',NULL,0,'In addition polymerisation all monomer atoms are incorporated into the polymer, giving 100% atom economy.',1,1);
INSERT INTO rubric_criterion VALUES(5797,'chem-8-2-24',NULL,1,'In condensation polymerisation a small molecule such as water is eliminated each time a link forms, so some reactant mass is lost as by-product and atom economy is less than 100%.',2,1);
INSERT INTO rubric_criterion VALUES(5798,'chem-8-2-25',NULL,0,'AE = (2 × 40.0) ÷ (2 × 58.5 + 2 × 18.0) × 100 = 80.0 ÷ 153.0 × 100 = 52.3%',2,1);
INSERT INTO rubric_criterion VALUES(5799,'chem-8-2-c1',NULL,0,'51.1% for fermentation;',1,1);
INSERT INTO rubric_criterion VALUES(5800,'chem-8-2-c1',NULL,1,'100% for hydration',1,1);
INSERT INTO rubric_criterion VALUES(5804,'chem-8-3-4',NULL,0,'Overall yield = 0.85 × 0.60 × 100 = 51%.',1,1);
INSERT INTO rubric_criterion VALUES(5805,'chem-8-3-4',NULL,1,'Fewer steps means less product lost overall, fewer reagents and solvents used and less waste and energy consumed.',1,1);
INSERT INTO rubric_criterion VALUES(5809,'chem-8-3-8',NULL,0,'Any two of: the reaction reaches equilibrium and does not go to completion; side reactions form unwanted products; product is lost during separation and purification (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(5810,'chem-8-3-8',NULL,1,'filtration, distillation); reactants are impure.',1,1);
INSERT INTO rubric_criterion VALUES(5814,'chem-8-3-12',NULL,0,'High atom economy means the reaction itself produces little by-product, while high yield means most of the possible product is actually obtained.',1,1);
INSERT INTO rubric_criterion VALUES(5815,'chem-8-3-12',NULL,1,'Improving both minimises wasted raw materials and waste disposal, lowering cost and environmental impact.',1,1);
INSERT INTO rubric_criterion VALUES(5819,'chem-8-3-16',NULL,0,'Theoretical ester = 0.250 × 88.0 = 22.0 g.',1,1);
INSERT INTO rubric_criterion VALUES(5820,'chem-8-3-16',NULL,1,'Yield = 15.4 ÷ 22.0 × 100 = 70.0%.',1,1);
INSERT INTO rubric_criterion VALUES(5824,'chem-8-3-20',NULL,0,'Only about 15% conversion occurs in a single pass because the reaction reaches equilibrium.',1,1);
INSERT INTO rubric_criterion VALUES(5825,'chem-8-3-20',NULL,1,'Recycling the unreacted gases back to the reactor means they eventually react, giving an overall yield of about 98% and reducing waste of feedstock.',1,1);
INSERT INTO rubric_criterion VALUES(5829,'chem-8-3-24',NULL,0,'Theoretical aspirin needed = 5.00 ÷ 0.700 = 7.14 g = 0.0397 mol.',1,1);
INSERT INTO rubric_criterion VALUES(5830,'chem-8-3-24',NULL,1,'Mass of salicylic acid = 0.0397 × 138.0 = 5.48 g.',1,1);
INSERT INTO rubric_criterion VALUES(5831,'chem-8-3-25',NULL,0,'Mass cannot be created, so the mass of pure product cannot exceed the theoretical maximum from the limiting reactant. A yield over 100% means the product contains extra mass, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(5832,'chem-8-3-25',NULL,1,'residual water/solvent from incomplete drying or impurities.',1,1);
INSERT INTO rubric_criterion VALUES(5833,'chem-8-3-c1',NULL,0,'80.0%',2,1);
INSERT INTO rubric_criterion VALUES(5837,'chem-8-4-4',NULL,0,'A linear economy follows a take–make–use–dispose model in which resources are extracted, made into products and discarded as waste.',1,1);
INSERT INTO rubric_criterion VALUES(5838,'chem-8-4-4',NULL,1,'A circular economy designs out waste and keeps materials in use for as long as possible through reuse, repair and recycling, with materials recovered at the end of a product''s life.',2,1);
INSERT INTO rubric_criterion VALUES(5842,'chem-8-4-8',NULL,0,'Advantage: it is made from a renewable feedstock and is close to carbon neutral, since the CO₂ released on combustion was absorbed during plant growth. Disadvantage: growing sugar cane uses land, water and fertiliser that may compete with food crops, and processing (e.g. distillation) requires energy.',1,1);
INSERT INTO rubric_criterion VALUES(5846,'chem-8-4-12',NULL,0,'Thermosetting polymers have strong covalent cross-links between chains, so they do not soften or melt when heated and cannot be remoulded; they decompose instead.',1,1);
INSERT INTO rubric_criterion VALUES(5847,'chem-8-4-12',NULL,1,'Thermoplastics have only weak intermolecular forces between chains and can be melted and reshaped.',1,1);
INSERT INTO rubric_criterion VALUES(5851,'chem-8-4-16',NULL,0,'The by-products, which would otherwise be waste, become inputs for other industries.',1,1);
INSERT INTO rubric_criterion VALUES(5852,'chem-8-4-16',NULL,1,'This keeps materials in use, reduces waste going to landfill or the atmosphere, and reduces the need for new raw materials (industrial symbiosis).',1,1);
INSERT INTO rubric_criterion VALUES(5856,'chem-8-4-20',NULL,0,'An LCA assesses the environmental impacts, such as energy use, raw materials, emissions and waste, at every stage of a product''s life: raw material extraction, manufacture, transport, use and end-of-life disposal or recycling.',1,1);
INSERT INTO rubric_criterion VALUES(5857,'chem-8-4-20',NULL,1,'It allows products or processes to be compared and identifies the stages where impacts can be reduced.',2,1);
INSERT INTO rubric_criterion VALUES(5861,'chem-8-4-24',NULL,0,'Currently hydrogen is mostly produced from natural gas by steam reforming, a non-renewable feedstock that releases CO₂.',1,1);
INSERT INTO rubric_criterion VALUES(5862,'chem-8-4-24',NULL,1,'Electrolysis of water using solar or wind electricity uses renewable energy and water, producing only O₂ as a by-product, so greenhouse gas emissions and fossil-fuel use are greatly reduced.',2,1);
INSERT INTO rubric_criterion VALUES(5863,'chem-8-4-25',NULL,0,'Reducing avoids using materials and creating waste in the first place, and reusing keeps a product in use without reprocessing.',1,1);
INSERT INTO rubric_criterion VALUES(5864,'chem-8-4-25',NULL,1,'Recycling still requires energy, collection and processing, and often loses some material quality, so it has a greater environmental impact than reducing or reusing.',2,1);
INSERT INTO rubric_criterion VALUES(5869,'physics-1-1-4',NULL,0,'F = GMm/R² = 6.67×10⁻¹¹ × 6.42×10²³ × 2.0 / (3.39×10⁶)² ≈ 7.5 N.',2,1);
INSERT INTO rubric_criterion VALUES(5873,'physics-1-1-8',NULL,0,'The forces are equal in size, but a = F/m.',1,1);
INSERT INTO rubric_criterion VALUES(5874,'physics-1-1-8',NULL,1,'Earth''s mass is about 10²⁴ times larger than the ball''s, so Earth''s acceleration is far too small to notice, while the ball accelerates at about 9.8 m s⁻².',1,1);
INSERT INTO rubric_criterion VALUES(5878,'physics-1-1-12',NULL,0,'F = GMm/r² = 6.67×10⁻¹¹ × 1.90×10²⁷ × 8.93×10²² / (4.22×10⁸)² ≈ 6.4 × 10²² N.',2,1);
INSERT INTO rubric_criterion VALUES(5882,'physics-1-1-16',NULL,0,'G is very small (6.67 × 10⁻¹¹), so the gravitational force between everyday objects is tiny.',1,1);
INSERT INTO rubric_criterion VALUES(5883,'physics-1-1-16',NULL,1,'We feel a large force from Earth only because its mass is enormous (about 6 × 10²⁴ kg).',1,1);
INSERT INTO rubric_criterion VALUES(5887,'physics-1-1-20',NULL,0,'The claim is incorrect.',1,1);
INSERT INTO rubric_criterion VALUES(5888,'physics-1-1-20',NULL,1,'The forces are a Newton''s third law pair, and F = GMm/r² uses both masses symmetrically, so the forces are equal in size and opposite in direction.',1,1);
INSERT INTO rubric_criterion VALUES(5889,'physics-1-1-20',NULL,2,'Earth''s larger mass means it accelerates less, not that it pulls harder.',1,1);
INSERT INTO rubric_criterion VALUES(5893,'physics-1-1-24',NULL,0,'The radius increases by a factor of 4.2×10⁷/7.0×10⁶ = 6, so the force decreases by a factor of 6² = 36.',2,1);
INSERT INTO rubric_criterion VALUES(5894,'physics-1-1-25',NULL,0,'r = √(Gm₁m₂/F) = √(6.67×10⁻¹¹ × 2500 / 1.0×10⁻⁸) = √16.7 ≈ 4.1 m.',2,1);
INSERT INTO rubric_criterion VALUES(5899,'physics-1-2-4',NULL,0,'g = GM/R² = 6.67×10⁻¹¹ × 1.90×10²⁷ / (6.99×10⁷)² ≈ 25.9 N kg⁻¹.',2,1);
INSERT INTO rubric_criterion VALUES(5903,'physics-1-2-8',NULL,0,'Mass is the amount of matter in an object (kg) and stays the same everywhere.',1,1);
INSERT INTO rubric_criterion VALUES(5904,'physics-1-2-8',NULL,1,'Weight is the gravitational force on it, W = mg (N), so it depends on g.',1,1);
INSERT INTO rubric_criterion VALUES(5905,'physics-1-2-8',NULL,2,'A 90 kg astronaut has a mass of 90 kg on both Earth and the Moon, but weighs about 882 N on Earth and about 146 N on the Moon (g ≈ 1.62 N kg⁻¹).',1,1);
INSERT INTO rubric_criterion VALUES(5909,'physics-1-2-12',NULL,0,'g ∝ M/R² = 4/2² = 1, so g_X = 9.8 N kg⁻¹, the same as Earth.',2,1);
INSERT INTO rubric_criterion VALUES(5913,'physics-1-2-16',NULL,0,'The force on a test mass m at distance r is F = GMm/r².',1,1);
INSERT INTO rubric_criterion VALUES(5914,'physics-1-2-16',NULL,1,'Field strength is force per unit mass, g = F/m = (GMm/r²)/m = GM/r².',1,1);
INSERT INTO rubric_criterion VALUES(5918,'physics-1-2-20',NULL,0,'M = gR²/G = 3.7 × (3.39×10⁶)² / 6.67×10⁻¹¹ ≈ 6.4 × 10²³ kg.',2,1);
INSERT INTO rubric_criterion VALUES(5922,'physics-1-2-24',NULL,0,'Earth is slightly flattened (an oblate spheroid), so the poles are closer to Earth''s centre than the equator. Because g ∝ 1/r², g is larger at the poles.',1,1);
INSERT INTO rubric_criterion VALUES(5923,'physics-1-2-24',NULL,1,'(Earth''s rotation also reduces the effective g at the equator.)',1,1);
INSERT INTO rubric_criterion VALUES(5924,'physics-1-2-25',NULL,0,'g_Earth = GM_E/r² = 3.98×10¹⁴ / (3.0×10⁸)² ≈ 4.42×10⁻³ N kg⁻¹ towards Earth.',1,1);
INSERT INTO rubric_criterion VALUES(5925,'physics-1-2-25',NULL,1,'g_Moon = GM_M/r² = 4.90×10¹² / (8.4×10⁷)² ≈ 6.95×10⁻⁴ N kg⁻¹ towards the Moon.',1,1);
INSERT INTO rubric_criterion VALUES(5926,'physics-1-2-25',NULL,2,'Net ≈ 3.7×10⁻³ N kg⁻¹ towards Earth.',1,1);
INSERT INTO rubric_criterion VALUES(5931,'physics-1-3-4',NULL,0,'GMm/r² = mv²/r and v = 2πr/T.',1,1);
INSERT INTO rubric_criterion VALUES(5932,'physics-1-3-4',NULL,1,'Substituting: GM/r² = 4π²r/T², which rearranges to T² = 4π²r³/(GM).',1,1);
INSERT INTO rubric_criterion VALUES(5936,'physics-1-3-8',NULL,0,'T = 6000 s.',1,1);
INSERT INTO rubric_criterion VALUES(5937,'physics-1-3-8',NULL,1,'r = ∛(GMT²/4π²) = ∛(3.98×10¹⁴ × 6000² / 4π²) ≈ 7.13×10⁶ m.',1,1);
INSERT INTO rubric_criterion VALUES(5938,'physics-1-3-8',NULL,2,'Altitude = 7.13×10⁶ − 6.37×10⁶ ≈ 7.6×10⁵ m (about 760 km).',1,1);
INSERT INTO rubric_criterion VALUES(5942,'physics-1-3-12',NULL,0,'A geostationary satellite stays above the same point on the equator because its 24-hour period matches Earth''s rotation.',1,1);
INSERT INTO rubric_criterion VALUES(5943,'physics-1-3-12',NULL,1,'Ground dishes can stay pointed at one fixed spot without tracking, giving continuous coverage of a large region.',1,1);
INSERT INTO rubric_criterion VALUES(5947,'physics-1-3-16',NULL,0,'T_M/T_E = (r_M/r_E)^(3/2) = (2.28/1.50)^(3/2) = 1.52^1.5 ≈ 1.87, so T_Mars ≈ 1.87 years.',3,1);
INSERT INTO rubric_criterion VALUES(5951,'physics-1-3-20',NULL,0,'T = 27.3 × 86400 = 2.36×10⁶ s.',1,1);
INSERT INTO rubric_criterion VALUES(5952,'physics-1-3-20',NULL,1,'v = 2πr/T = 2π × 3.84×10⁸ / 2.36×10⁶ ≈ 1.02×10³ m s⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(5956,'physics-1-3-24',NULL,0,'M = 4π²r³/(GT²) = 4π² × (1.50×10¹¹)³ / (6.67×10⁻¹¹ × (3.16×10⁷)²) ≈ 2.0×10³⁰ kg.',2,1);
INSERT INTO rubric_criterion VALUES(5957,'physics-1-3-25',NULL,0,'Drag removes mechanical energy, so the satellite drops to a smaller orbital radius.',1,1);
INSERT INTO rubric_criterion VALUES(5958,'physics-1-3-25',NULL,1,'Because v = √(GM/r), its speed actually increases as it spirals inwards: gravity does positive work as it falls, adding more kinetic energy than drag removes.',1,1);
INSERT INTO rubric_criterion VALUES(5959,'physics-1-3-c1',NULL,0,'v ≈ 7.5 × 10³ m/s;',1,1);
INSERT INTO rubric_criterion VALUES(5960,'physics-1-3-c1',NULL,1,'T ≈ 97 minutes',1,1);
INSERT INTO rubric_criterion VALUES(5964,'physics-1-4-4',NULL,0,'Find the area under the F–r graph between the two radii, for example by counting squares or using trapezia, and multiply by the scale of one square.',1,1);
INSERT INTO rubric_criterion VALUES(5965,'physics-1-4-4',NULL,1,'This area is the work done against gravity, which equals the increase in the satellite''s gravitational potential energy.',2,1);
INSERT INTO rubric_criterion VALUES(5969,'physics-1-4-8',NULL,0,'Area ≈ ½(8.13 + 6.22) × 1.0×10⁶ = 7.18×10⁶ J kg⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(5970,'physics-1-4-8',NULL,1,'Energy ≈ 250 × 7.18×10⁶ ≈ 1.8×10⁹ J.',2,1);
INSERT INTO rubric_criterion VALUES(5974,'physics-1-4-12',NULL,0,'Too high.',1,1);
INSERT INTO rubric_criterion VALUES(5975,'physics-1-4-12',NULL,1,'g decreases with altitude (to about 8.7 N kg⁻¹ at 400 km), so the true average g over the climb is less than 9.8 N kg⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(5976,'physics-1-4-12',NULL,2,'Using 9.8 N kg⁻¹ throughout overestimates the area under the g–r graph.',1,1);
INSERT INTO rubric_criterion VALUES(5980,'physics-1-4-16',NULL,0,'Average g ≈ (9.8 + 8.69)/2 = 9.245 N kg⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(5981,'physics-1-4-16',NULL,1,'ΔU ≈ m × g_avg × Δh = 450 × 9.245 × 4.0×10⁵ ≈ 1.7×10⁹ J.',1,1);
INSERT INTO rubric_criterion VALUES(5985,'physics-1-4-20',NULL,0,'One square = 100 × 1.0×10⁵ = 1.0×10⁷ J.',1,1);
INSERT INTO rubric_criterion VALUES(5986,'physics-1-4-20',NULL,1,'ΔU = 35 × 1.0×10⁷ = 3.5×10⁸ J.',1,1);
INSERT INTO rubric_criterion VALUES(5990,'physics-1-4-24',NULL,0,'mgh = ½mv², so v = √(2gh) = √(2 × 9.8 × 285) ≈ 75 m s⁻¹.',2,1);
INSERT INTO rubric_criterion VALUES(5991,'physics-1-4-25',NULL,0,'Gravity pulls the satellite towards Earth, so moving it outwards means work must be done against the gravitational force (the force and the displacement are opposite).',1,1);
INSERT INTO rubric_criterion VALUES(5992,'physics-1-4-25',NULL,1,'This work is stored as an increase in gravitational potential energy, equal to the area under the F–r graph.',2,1);
INSERT INTO rubric_criterion VALUES(6012,'physics-2-1-19',NULL,0,'F = k e²/r² = 8.99 × 10⁹ × (1.6 × 10⁻¹⁹)²/(5.3 × 10⁻¹¹)² ≈ 8.2 × 10⁻⁸ N, attractive.',2,1);
INSERT INTO rubric_criterion VALUES(6013,'physics-2-1-20',NULL,0,'Field lines radiate outwards from each charge and curve away from the region between them, so no lines connect the two charges.',1,1);
INSERT INTO rubric_criterion VALUES(6014,'physics-2-1-20',NULL,1,'At the midpoint there is a neutral point where the field is zero.',1,1);
INSERT INTO rubric_criterion VALUES(6015,'physics-2-1-20',NULL,2,'Lines never cross and are densest close to each charge.',1,1);
INSERT INTO rubric_criterion VALUES(6016,'physics-2-1-21',NULL,0,'The uniform field exerts a constant vertical force (qE), so the electron has constant vertical acceleration, while its horizontal velocity is unchanged because there is no horizontal force.',1,1);
INSERT INTO rubric_criterion VALUES(6017,'physics-2-1-21',NULL,1,'Constant velocity in one direction combined with constant acceleration in the perpendicular direction produces a parabola, like a projectile.',2,1);
INSERT INTO rubric_criterion VALUES(6018,'physics-2-1-22',NULL,0,'V = Ed = 4.0 × 10⁵ × 5.0 × 10⁻³ = 2.0 × 10³ V (2000 V).',1,1);
INSERT INTO rubric_criterion VALUES(6019,'physics-2-1-23',NULL,0,'q = F/E = 2.4 × 10⁻³/8.0 × 10³ = 3.0 × 10⁻⁷ C (0.30 μC).',2,1);
INSERT INTO rubric_criterion VALUES(6020,'physics-2-1-24',NULL,0,'Fₑ/F_g = ke²/(Gm²) = (8.99 × 10⁹ × (1.6 × 10⁻¹⁹)²)/(6.67 × 10⁻¹¹ × (1.67 × 10⁻²⁷)²) ≈ 1.2 × 10³⁶.',1,1);
INSERT INTO rubric_criterion VALUES(6021,'physics-2-1-24',NULL,1,'The electric force is vastly larger, so gravity is negligible between subatomic particles.',2,1);
INSERT INTO rubric_criterion VALUES(6022,'physics-2-1-25',NULL,0,'Each charge is 0.10 m away: E = kq/r² = 8.99 × 10⁹ × 3.0 × 10⁻⁹/0.010 ≈ 2.7 × 10³ N C⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(6023,'physics-2-1-25',NULL,1,'Both fields point towards the negative charge, so E_total ≈ 5.4 × 10³ N C⁻¹ directed towards the −3.0 nC charge.',2,1);
INSERT INTO rubric_criterion VALUES(6043,'physics-2-2-19',NULL,0,'The field forms concentric circles around the wire in planes perpendicular to the current, getting weaker with distance from the wire.',1,1);
INSERT INTO rubric_criterion VALUES(6044,'physics-2-2-19',NULL,1,'Its direction is found with the right-hand grip rule: point the right thumb in the direction of conventional current and the fingers curl in the direction of the field.',2,1);
INSERT INTO rubric_criterion VALUES(6045,'physics-2-2-20',NULL,0,'Inside, the fields from every loop point in the same direction along the axis and add together, giving a strong, nearly uniform field.',1,1);
INSERT INTO rubric_criterion VALUES(6046,'physics-2-2-20',NULL,1,'Outside, the field lines spread out over a much larger region (and contributions from opposite sides of loops partly cancel), so the field is much weaker.',2,1);
INSERT INTO rubric_criterion VALUES(6047,'physics-2-2-21',NULL,0,'1. Magnetic field lines form closed loops, while electric field lines start on positive charges and end on negative charges. 2.',1,1);
INSERT INTO rubric_criterion VALUES(6048,'physics-2-2-21',NULL,1,'The magnetic force on a moving charge is perpendicular to the field lines, whereas the electric force on a charge is along the field lines. (Also: magnetic fields exert no force on stationary charges.)',1,1);
INSERT INTO rubric_criterion VALUES(6049,'physics-2-2-22',NULL,0,'The field forms circles around the wire that run clockwise as seen by the viewer.',1,1);
INSERT INTO rubric_criterion VALUES(6050,'physics-2-2-22',NULL,1,'With the right thumb pointing into the page, the fingers curl clockwise.',1,1);
INSERT INTO rubric_criterion VALUES(6051,'physics-2-2-23',NULL,0,'The field from each wire at the midpoint has the same magnitude, and because the currents are opposite, the right-hand grip rule shows both fields point in the same direction.',1,1);
INSERT INTO rubric_criterion VALUES(6052,'physics-2-2-23',NULL,1,'They add, so the field is twice that of one wire, directed perpendicular to the plane containing the wires.',2,1);
INSERT INTO rubric_criterion VALUES(6053,'physics-2-2-24',NULL,0,'B ∝ I, so B = 4.0 × (5.0/2.0) = 10 mT (1.0 × 10⁻² T).',1,1);
INSERT INTO rubric_criterion VALUES(6054,'physics-2-2-25',NULL,0,'Reversing the direction of the current reverses the field, swapping the north and south poles.',1,1);
INSERT INTO rubric_criterion VALUES(6055,'physics-2-2-25',NULL,1,'A soft iron core is easily magnetised, which greatly strengthens and concentrates the field, and it loses its magnetism quickly when the current is switched off.',2,1);
INSERT INTO rubric_criterion VALUES(6075,'physics-2-3-19',NULL,0,'The magnetic force qvB is always perpendicular to the velocity, so it provides the centripetal force: qvB = mv²/r.',1,1);
INSERT INTO rubric_criterion VALUES(6076,'physics-2-3-19',NULL,1,'Rearranging gives r = mv/(qB).',1,1);
INSERT INTO rubric_criterion VALUES(6077,'physics-2-3-20',NULL,0,'B = mv/(qr) = (9.1 × 10⁻³¹ × 4.0 × 10⁶)/(1.6 × 10⁻¹⁹ × 0.050) ≈ 4.6 × 10⁻⁴ T.',1,1);
INSERT INTO rubric_criterion VALUES(6078,'physics-2-3-21',NULL,0,'The magnetic force is always perpendicular to the particle''s velocity, so it has no component along the direction of motion and does no work.',1,1);
INSERT INTO rubric_criterion VALUES(6079,'physics-2-3-21',NULL,1,'With no work done the kinetic energy, and therefore the speed, is constant;',1,1);
INSERT INTO rubric_criterion VALUES(6080,'physics-2-3-21',NULL,2,'only the direction changes.',1,1);
INSERT INTO rubric_criterion VALUES(6081,'physics-2-3-22',NULL,0,'F = nIlB = 20 × 1.5 × 0.050 × 0.30 = 0.45 N.',2,1);
INSERT INTO rubric_criterion VALUES(6082,'physics-2-3-23',NULL,0,'The brushes make a sliding electrical contact between the external DC supply and the rotating coil.',1,1);
INSERT INTO rubric_criterion VALUES(6083,'physics-2-3-23',NULL,1,'The split-ring commutator reverses the direction of current in the coil every half rotation (when the coil plane is perpendicular to the field), so the forces on each side always produce torque in the same rotational direction and the motor keeps turning.',2,1);
INSERT INTO rubric_criterion VALUES(6084,'physics-2-3-24',NULL,0,'IlB = mg, so I = mg/(lB) = (6.0 × 10⁻³ × 9.8)/(0.20 × 0.50) ≈ 0.59 A.',1,1);
INSERT INTO rubric_criterion VALUES(6085,'physics-2-3-25',NULL,0,'South.',1,1);
INSERT INTO rubric_criterion VALUES(6086,'physics-2-3-25',NULL,1,'Using F = qv × B (or the right-hand slap rule) with velocity east and field up, the force on a positive charge points south.',1,1);
INSERT INTO rubric_criterion VALUES(6087,'physics-2-3-c1',NULL,0,'2.3 × 10⁻³ m (2.3 mm)',2,1);
INSERT INTO rubric_criterion VALUES(6106,'physics-2-4-19',NULL,0,'Electron gun: produces electrons by thermionic emission and accelerates them with an electric field. Linac: uses electric fields to accelerate the electrons to near light speed in a straight line.',1,1);
INSERT INTO rubric_criterion VALUES(6107,'physics-2-4-19',NULL,1,'Booster ring: further increases their energy as bending magnets'' field increases to keep them on the circular path.',1,1);
INSERT INTO rubric_criterion VALUES(6108,'physics-2-4-19',NULL,2,'Storage ring: bending magnets keep the electrons circulating for hours, producing synchrotron light, while RF cavities replace lost energy.',1,1);
INSERT INTO rubric_criterion VALUES(6109,'physics-2-4-19',NULL,3,'Beamlines: channel the synchrotron light to experimental stations.',1,1);
INSERT INTO rubric_criterion VALUES(6110,'physics-2-4-20',NULL,0,'In the bending magnets the electrons change direction, so they are accelerating;',1,1);
INSERT INTO rubric_criterion VALUES(6111,'physics-2-4-20',NULL,1,'accelerating charges emit electromagnetic radiation.',1,1);
INSERT INTO rubric_criterion VALUES(6112,'physics-2-4-20',NULL,2,'This radiation carries energy away, so RF cavities must keep supplying energy, otherwise the electrons would lose energy and their orbit would not be maintained.',1,1);
INSERT INTO rubric_criterion VALUES(6113,'physics-2-4-21',NULL,0,'½mv² = qV, so v = √(2qV/m) = √(2 × 1.6 × 10⁻¹⁹ × 3.0 × 10³/9.1 × 10⁻³¹) ≈ 3.2 × 10⁷ m s⁻¹.',2,1);
INSERT INTO rubric_criterion VALUES(6114,'physics-2-4-22',NULL,0,'r = mv/(qB) = (9.1 × 10⁻³¹ × 3.2 × 10⁷)/(1.6 × 10⁻¹⁹ × 5.0 × 10⁻³) ≈ 3.6 × 10⁻² m (about 3.6 cm).',2,1);
INSERT INTO rubric_criterion VALUES(6115,'physics-2-4-23',NULL,0,'r = mv/(qB) with q, v and B equal, so r ∝ m.',1,1);
INSERT INTO rubric_criterion VALUES(6116,'physics-2-4-23',NULL,1,'Ratio = 14/12 ≈ 1.17.',1,1);
INSERT INTO rubric_criterion VALUES(6117,'physics-2-4-24',NULL,0,'Any gas molecules in the tube would collide with the electrons, scattering them out of the beam and causing them to lose energy.',1,1);
INSERT INTO rubric_criterion VALUES(6118,'physics-2-4-24',NULL,1,'A high vacuum lets the beam travel long distances (for hours in a storage ring) without these collisions.',2,1);
INSERT INTO rubric_criterion VALUES(6119,'physics-2-4-25',NULL,0,'E = V/d = 200/0.040 = 5.0 × 10³ V m⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(6120,'physics-2-4-25',NULL,1,'F = qE = 8.0 × 10⁻¹⁶ N;',1,1);
INSERT INTO rubric_criterion VALUES(6121,'physics-2-4-25',NULL,2,'a = F/m = 8.0 × 10⁻¹⁶/9.1 × 10⁻³¹ ≈ 8.8 × 10¹⁴ m s⁻², towards the positive plate.',1,1);
INSERT INTO rubric_criterion VALUES(6122,'physics-2-4-c1',NULL,0,'8.0 × 10⁻¹⁶ J;',1,1);
INSERT INTO rubric_criterion VALUES(6123,'physics-2-4-c1',NULL,1,'4.2 × 10⁷ m/s',2,1);
INSERT INTO rubric_criterion VALUES(6142,'physics-3-1-19',NULL,0,'N = mg − T sin 30° = 392 − 75 = 317 N (about 3.2 × 10² N).',3,1);
INSERT INTO rubric_criterion VALUES(6143,'physics-3-1-20',NULL,0,'The third-law pair forces act on different objects, so they do not cancel.',1,1);
INSERT INTO rubric_criterion VALUES(6144,'physics-3-1-20',NULL,1,'The cart accelerates because the horse''s forward pull on it is larger than the friction on the cart.',1,1);
INSERT INTO rubric_criterion VALUES(6145,'physics-3-1-20',NULL,2,'The horse accelerates because the ground''s forward friction on its hooves is larger than the cart''s backward pull.',1,1);
INSERT INTO rubric_criterion VALUES(6146,'physics-3-1-21',NULL,0,'Slowing while moving down means the acceleration is upwards: N = m(g + a) = 65 × (9.8 + 1.2) = 715 N.',3,1);
INSERT INTO rubric_criterion VALUES(6147,'physics-3-1-22',NULL,0,'Down-slope weight component = 4.0 × 9.8 × sin 35° ≈ 22.5 N.',1,1);
INSERT INTO rubric_criterion VALUES(6148,'physics-3-1-22',NULL,1,'Net force = 22.5 − 10 = 12.5 N, so a = 12.5/4.0 ≈ 3.1 m/s² down the slope.',2,1);
INSERT INTO rubric_criterion VALUES(6149,'physics-3-1-23',NULL,0,'a = (5.0 − 3.0) × 9.8 / 8.0 = 2.45 m/s².',1,1);
INSERT INTO rubric_criterion VALUES(6150,'physics-3-1-23',NULL,1,'T = 3.0 × (9.8 + 2.45) ≈ 36.8 N.',2,1);
INSERT INTO rubric_criterion VALUES(6151,'physics-3-1-24',NULL,0,'The claim is wrong. After release, the only force on the ball is gravity, acting downwards.',1,1);
INSERT INTO rubric_criterion VALUES(6152,'physics-3-1-24',NULL,1,'The ball keeps rising because of its inertia (its initial upward velocity), and the downward net force slows it at 9.8 m/s².',1,1);
INSERT INTO rubric_criterion VALUES(6153,'physics-3-1-25',NULL,0,'Net force = 1500 − 300 = 1200 N, so a = 1200/500 = 2.4 m/s².',2,1);
INSERT INTO rubric_criterion VALUES(6173,'physics-3-2-19',NULL,0,'Range = v² sin 2θ/g = 900 × sin 80°/9.8 ≈ 90 m.',1,1);
INSERT INTO rubric_criterion VALUES(6174,'physics-3-2-19',NULL,1,'(Equivalently: t = 2 × 19.3/9.8 ≈ 3.94 s, and 23.0 × 3.94 ≈ 90 m.)',2,1);
INSERT INTO rubric_criterion VALUES(6175,'physics-3-2-20',NULL,0,'uy = 30 sin 40° ≈ 19.3 m/s;',1,1);
INSERT INTO rubric_criterion VALUES(6176,'physics-3-2-20',NULL,1,'h = uy²/(2g) = 19.3²/19.6 ≈ 19 m.',1,1);
INSERT INTO rubric_criterion VALUES(6177,'physics-3-2-21',NULL,0,'t = √(2 × 45/9.8) ≈ 3.0 s;',1,1);
INSERT INTO rubric_criterion VALUES(6178,'physics-3-2-21',NULL,1,'horizontal distance = 12 × 3.03 ≈ 36 m.',1,1);
INSERT INTO rubric_criterion VALUES(6179,'physics-3-2-22',NULL,0,'Ignoring air resistance, the only force is gravity, which acts vertically.',1,1);
INSERT INTO rubric_criterion VALUES(6180,'physics-3-2-22',NULL,1,'So there is no horizontal acceleration (constant horizontal velocity), while the vertical motion has constant acceleration g.',1,1);
INSERT INTO rubric_criterion VALUES(6181,'physics-3-2-22',NULL,2,'Perpendicular vectors do not affect each other, and the two components are linked only by time.',1,1);
INSERT INTO rubric_criterion VALUES(6182,'physics-3-2-23',NULL,0,'vx = 18 cos 35° ≈ 14.7 m/s, so t = 20/14.7 ≈ 1.36 s.',1,1);
INSERT INTO rubric_criterion VALUES(6183,'physics-3-2-23',NULL,1,'y = (18 sin 35°)(1.36) − 4.9(1.36)² ≈ 14.0 − 9.0 ≈ 5.0 m.',1,1);
INSERT INTO rubric_criterion VALUES(6184,'physics-3-2-23',NULL,2,'Since 5.0 m > 2.4 m, it passes over the crossbar.',1,1);
INSERT INTO rubric_criterion VALUES(6185,'physics-3-2-24',NULL,0,'vy² = 2gh = 2 × 9.8 × 45 = 882, so vy ≈ 29.7 m/s.',1,1);
INSERT INTO rubric_criterion VALUES(6186,'physics-3-2-24',NULL,1,'v = √(12² + 882) = √1026 ≈ 32 m/s.',1,1);
INSERT INTO rubric_criterion VALUES(6187,'physics-3-2-25',NULL,0,'t = √(2 × 500/9.8) ≈ 10.1 s, so the horizontal distance = 60 × 10.1 ≈ 606 m (about 610 m).',1,1);
INSERT INTO rubric_criterion VALUES(6188,'physics-3-2-25',NULL,1,'The plane is directly above the package when it lands, because both have the same horizontal velocity.',2,1);
INSERT INTO rubric_criterion VALUES(6189,'physics-3-2-c1',NULL,0,'2.0 s;',1,1);
INSERT INTO rubric_criterion VALUES(6190,'physics-3-2-c1',NULL,1,'30 m',1,1);
INSERT INTO rubric_criterion VALUES(6209,'physics-3-3-19',NULL,0,'Vertically: N cos θ = mg. Horizontally (towards the centre): N sin θ = mv²/r.',1,1);
INSERT INTO rubric_criterion VALUES(6210,'physics-3-3-19',NULL,1,'Dividing the second equation by the first gives tan θ = v²/(rg).',1,1);
INSERT INTO rubric_criterion VALUES(6211,'physics-3-3-20',NULL,0,'108 km/h = 30 m/s.',1,1);
INSERT INTO rubric_criterion VALUES(6212,'physics-3-3-20',NULL,1,'tan θ = 30²/(200 × 9.8) = 900/1960 ≈ 0.459, so θ ≈ 25°.',1,1);
INSERT INTO rubric_criterion VALUES(6213,'physics-3-3-21',NULL,0,'v = √(gr) = √(9.8 × 0.90) ≈ 3.0 m/s.',1,1);
INSERT INTO rubric_criterion VALUES(6214,'physics-3-3-21',NULL,1,'At this speed gravity alone provides exactly the centripetal force needed, so the water needs no push from the bucket base;',1,1);
INSERT INTO rubric_criterion VALUES(6215,'physics-3-3-21',NULL,2,'any slower and gravity would pull it out of the circular path.',1,1);
INSERT INTO rubric_criterion VALUES(6216,'physics-3-3-22',NULL,0,'N − mg = mv²/r, so N = 60 × (9.8 + 400/12) = 60 × 43.1 ≈ 2.6 × 10³ N (about 4.4 times their weight).',3,1);
INSERT INTO rubric_criterion VALUES(6217,'physics-3-3-23',NULL,0,'mv²/r = F, so v = √(Fr/m) = √(7000 × 40/1400) = √200 ≈ 14 m/s (about 51 km/h).',2,1);
INSERT INTO rubric_criterion VALUES(6218,'physics-3-3-24',NULL,0,'The passengers'' inertia tends to keep them moving in a straight line (Newton''s first law). The car turns inwards beneath them until the door or seat pushes them inwards, providing the centripetal force.',1,1);
INSERT INTO rubric_criterion VALUES(6219,'physics-3-3-24',NULL,1,'No outward force acts;',1,1);
INSERT INTO rubric_criterion VALUES(6220,'physics-3-3-24',NULL,2,'the sensation comes from the inward push of the car.',1,1);
INSERT INTO rubric_criterion VALUES(6221,'physics-3-3-25',NULL,0,'F = mv²/r = 1500 × 625/100 = 9375 N (about 9.4 × 10³ N), directed horizontally towards the centre of the curve.',1,1);
INSERT INTO rubric_criterion VALUES(6222,'physics-3-3-c1',NULL,0,'About 39°',1,1);
INSERT INTO rubric_criterion VALUES(6241,'physics-3-4-19',NULL,0,'30 000 = 3000v + 1000 × 12, so v = 6.0 m/s forward. KE before = ½ × 3000 × 10² = 150 000 J;',1,1);
INSERT INTO rubric_criterion VALUES(6242,'physics-3-4-19',NULL,1,'KE after = ½ × 3000 × 6² + ½ × 1000 × 12² = 54 000 + 72 000 = 126 000 J.',1,1);
INSERT INTO rubric_criterion VALUES(6243,'physics-3-4-19',NULL,2,'KE is not conserved, so the collision is inelastic.',1,1);
INSERT INTO rubric_criterion VALUES(6244,'physics-3-4-20',NULL,0,'Crumple zones deform progressively, increasing the time over which the car (and its occupants) come to rest.',1,1);
INSERT INTO rubric_criterion VALUES(6245,'physics-3-4-20',NULL,1,'The change in momentum is the same, so by F = Δp/Δt a longer stopping time means a smaller average force.',1,1);
INSERT INTO rubric_criterion VALUES(6246,'physics-3-4-20',NULL,2,'They also absorb kinetic energy through deformation.',1,1);
INSERT INTO rubric_criterion VALUES(6247,'physics-3-4-21',NULL,0,'Es = ½ × 400 × 0.10² = 2.0 J.',1,1);
INSERT INTO rubric_criterion VALUES(6248,'physics-3-4-21',NULL,1,'½ × 0.050 × v² = 2.0, so v = √80 ≈ 8.9 m/s.',1,1);
INSERT INTO rubric_criterion VALUES(6249,'physics-3-4-22',NULL,0,'KE = ½ × 1500 × 20² = 300 000 J.',1,1);
INSERT INTO rubric_criterion VALUES(6250,'physics-3-4-22',NULL,1,'The work done by the brakes, F × 40, equals this KE, so F = 300 000/40 = 7500 N.',1,1);
INSERT INTO rubric_criterion VALUES(6251,'physics-3-4-23',NULL,0,'Impulse = Δp = 0.45 × 25 = 11.25 ≈ 11 N s.',1,1);
INSERT INTO rubric_criterion VALUES(6252,'physics-3-4-23',NULL,1,'Average force = 11.25/0.010 ≈ 1.1 × 10³ N.',1,1);
INSERT INTO rubric_criterion VALUES(6253,'physics-3-4-24',NULL,0,'Impact speed = √(2 × 9.8 × 1.25) ≈ 4.95 m/s downwards;',1,1);
INSERT INTO rubric_criterion VALUES(6254,'physics-3-4-24',NULL,1,'rebound speed = √(2 × 9.8 × 0.80) ≈ 3.96 m/s upwards.',1,1);
INSERT INTO rubric_criterion VALUES(6255,'physics-3-4-24',NULL,2,'Impulse = 2.0 × (3.96 + 4.95) ≈ 17.8 N s upwards.',1,1);
INSERT INTO rubric_criterion VALUES(6256,'physics-3-4-25',NULL,0,'Drop in height = 18 m.',1,1);
INSERT INTO rubric_criterion VALUES(6257,'physics-3-4-25',NULL,1,'½v² = gΔh, so v = √(2 × 9.8 × 18) = √352.8 ≈ 18.8 m/s.',1,1);
INSERT INTO rubric_criterion VALUES(6277,'physics-4-1-19',NULL,0,'1. The laws of physics are the same in all inertial frames of reference. 2.',1,1);
INSERT INTO rubric_criterion VALUES(6278,'physics-4-1-19',NULL,1,'The speed of light in a vacuum is the same (c) for all observers, regardless of the motion of the source or observer.',1,1);
INSERT INTO rubric_criterion VALUES(6279,'physics-4-1-20',NULL,0,'The ship moving at constant velocity is an inertial frame.',1,1);
INSERT INTO rubric_criterion VALUES(6280,'physics-4-1-20',NULL,1,'Since the laws of physics are the same in all inertial frames, any experiment below deck gives exactly the same result as on land, so there is no way to detect the ship''s uniform motion.',2,1);
INSERT INTO rubric_criterion VALUES(6281,'physics-4-1-21',NULL,0,'The experiment detected no change in the speed of light with Earth''s motion, so there was no evidence for an aether.',1,1);
INSERT INTO rubric_criterion VALUES(6282,'physics-4-1-21',NULL,1,'This supported the idea that light travels at the same speed c in all directions and for all observers, which became Einstein''s second postulate.',2,1);
INSERT INTO rubric_criterion VALUES(6283,'physics-4-1-22',NULL,0,'Light from each event travels at c in every frame.',1,1);
INSERT INTO rubric_criterion VALUES(6284,'physics-4-1-22',NULL,1,'An observer moving towards one event meets its light sooner, and because they must also measure both light signals at speed c over equal distances in their own frame, they conclude that the events occurred at different times.',1,1);
INSERT INTO rubric_criterion VALUES(6285,'physics-4-1-22',NULL,2,'So simultaneity depends on the frame.',1,1);
INSERT INTO rubric_criterion VALUES(6286,'physics-4-1-23',NULL,0,'An inertial frame is not accelerating (at rest or moving at constant velocity), e.g. a tram travelling at constant speed along a straight track.',1,1);
INSERT INTO rubric_criterion VALUES(6287,'physics-4-1-23',NULL,1,'A non-inertial frame is accelerating, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(6288,'physics-4-1-23',NULL,2,'a car braking or a car turning a corner.',1,1);
INSERT INTO rubric_criterion VALUES(6289,'physics-4-1-24',NULL,0,'c (3.0 × 10⁸ m/s).',1,1);
INSERT INTO rubric_criterion VALUES(6290,'physics-4-1-24',NULL,1,'By Einstein''s second postulate, the speed of light in a vacuum is the same for all observers, regardless of the motion of the source.',1,1);
INSERT INTO rubric_criterion VALUES(6291,'physics-4-1-25',NULL,0,'Time intervals are not absolute in special relativity; they depend on the observer''s frame of reference.',1,1);
INSERT INTO rubric_criterion VALUES(6292,'physics-4-1-25',NULL,1,'Each observer''s measurement is correct in their own inertial frame, and no frame is preferred, so both measurements are valid.',1,1);
INSERT INTO rubric_criterion VALUES(6312,'physics-4-2-19',NULL,0,'γ = 1/√(1 − 0.90²) = 1/√0.19 = 1/0.436 = 2.29',2,1);
INSERT INTO rubric_criterion VALUES(6313,'physics-4-2-20',NULL,0,'γ = 1/√(1 − 0.49) = 1/√0.51 = 1.40.',1,1);
INSERT INTO rubric_criterion VALUES(6314,'physics-4-2-20',NULL,1,'Δt₀ = Δt/γ = 20.0/1.40 = 14.3 years.',1,1);
INSERT INTO rubric_criterion VALUES(6315,'physics-4-2-21',NULL,0,'γ = 9.0/1.8 = 5.0.',1,1);
INSERT INTO rubric_criterion VALUES(6316,'physics-4-2-21',NULL,1,'1 − v²/c² = 1/25 = 0.04, so v = √0.96 c = 0.98c (about 2.94 × 10⁸ m/s).',2,1);
INSERT INTO rubric_criterion VALUES(6317,'physics-4-2-22',NULL,0,'To an outside observer the light in the moving clock follows a longer, diagonal path between the mirrors.',1,1);
INSERT INTO rubric_criterion VALUES(6318,'physics-4-2-22',NULL,1,'Because the speed of light is the same',1,1);
INSERT INTO rubric_criterion VALUES(6319,'physics-4-2-22',NULL,2,'(c) for all observers, the longer path takes more time, so each tick of the moving clock takes longer: it runs slow.',1,1);
INSERT INTO rubric_criterion VALUES(6320,'physics-4-2-23',NULL,0,'γ = 2, so 1 − v²/c² = 0.25 and v = √0.75 c = 0.866c = 2.6 × 10⁸ m/s.',2,1);
INSERT INTO rubric_criterion VALUES(6321,'physics-4-2-24',NULL,0,'For v = 30 m/s, v/c = 1 × 10⁻⁷, so v²/c² = 1 × 10⁻¹⁴ and γ ≈ 1 + 5 × 10⁻¹⁵. The difference from 1 is far too small to notice;',1,1);
INSERT INTO rubric_criterion VALUES(6322,'physics-4-2-24',NULL,1,'time dilation only becomes significant at speeds close to c.',1,1);
INSERT INTO rubric_criterion VALUES(6323,'physics-4-2-25',NULL,0,'γ = 1.67, so Δt = γΔt₀ = 1.67 × 30 = 50 minutes.',2,1);
INSERT INTO rubric_criterion VALUES(6343,'physics-4-3-19',NULL,0,'γ = 1/√0.19 = 2.29.',1,1);
INSERT INTO rubric_criterion VALUES(6344,'physics-4-3-19',NULL,1,'L = L₀/γ = 120/2.29 = 52 m.',1,1);
INSERT INTO rubric_criterion VALUES(6345,'physics-4-3-20',NULL,0,'No. She is at rest relative to her spacecraft, so she measures its proper length.',1,1);
INSERT INTO rubric_criterion VALUES(6346,'physics-4-3-20',NULL,1,'Length contraction is only observed for objects moving relative to the observer.',1,1);
INSERT INTO rubric_criterion VALUES(6347,'physics-4-3-21',NULL,0,'γ = 1/√(1 − 0.9604) = 1/√0.0396 = 5.03.',1,1);
INSERT INTO rubric_criterion VALUES(6348,'physics-4-3-21',NULL,1,'Dilated lifetime = 5.03 × 2.2 μs = 11.1 μs.',1,1);
INSERT INTO rubric_criterion VALUES(6349,'physics-4-3-21',NULL,2,'d = 0.98 × 3.0 × 10⁸ × 11.1 × 10⁻⁶ = 3.3 × 10³ m (3.3 km).',1,1);
INSERT INTO rubric_criterion VALUES(6350,'physics-4-3-22',NULL,0,'L = L₀/γ = 12/5.03 = 2.4 km.',1,1);
INSERT INTO rubric_criterion VALUES(6351,'physics-4-3-23',NULL,0,'In Earth''s frame, the muons'' lifetimes are time dilated, so they live long enough to travel through the atmosphere.',1,1);
INSERT INTO rubric_criterion VALUES(6352,'physics-4-3-23',NULL,1,'In the muons'' frame, their lifetime is normal but the atmosphere is length contracted, so the distance is short enough to cover.',1,1);
INSERT INTO rubric_criterion VALUES(6353,'physics-4-3-23',NULL,2,'Both frames predict the same observed result: many muons reach the ground.',1,1);
INSERT INTO rubric_criterion VALUES(6354,'physics-4-3-24',NULL,0,'L/L₀ = 4.8/8.0 = 0.60 = 1/γ, so 1 − v²/c² = 0.36 and v = 0.80c (2.4 × 10⁸ m/s).',2,1);
INSERT INTO rubric_criterion VALUES(6355,'physics-4-3-25',NULL,0,'The astronaut on the spacecraft measures the spacecraft''s proper length, because the spacecraft is at rest in her frame.',1,1);
INSERT INTO rubric_criterion VALUES(6356,'physics-4-3-25',NULL,1,'An observer on Earth measures the proper Earth–Moon distance, because Earth and the Moon are (approximately) at rest in that frame.',2,1);
INSERT INTO rubric_criterion VALUES(6357,'physics-4-3-c1',NULL,0,'About 6.6 km',3,1);
INSERT INTO rubric_criterion VALUES(6376,'physics-4-4-19',NULL,0,'E = Pt = 2.2 × 10⁹ × 86 400 = 1.9 × 10¹⁴ J.',1,1);
INSERT INTO rubric_criterion VALUES(6377,'physics-4-4-19',NULL,1,'m = E/c² = 1.9 × 10¹⁴/9.0 × 10¹⁶ = 2.1 × 10⁻³ kg (about 2.1 g).',2,1);
INSERT INTO rubric_criterion VALUES(6378,'physics-4-4-20',NULL,0,'mc² = 8.19 × 10⁻¹⁴ J and γ = 1.67. Total energy E = γmc² = 1.67 × 8.19 × 10⁻¹⁴ = 1.37 × 10⁻¹³ J.',1,1);
INSERT INTO rubric_criterion VALUES(6379,'physics-4-4-20',NULL,1,'Ek = E − mc² = 5.5 × 10⁻¹⁴ J.',1,1);
INSERT INTO rubric_criterion VALUES(6380,'physics-4-4-21',NULL,0,'Ek = (γ − 1)mc², and γ = 1/√(1 − v²/c²) approaches infinity as v approaches c.',1,1);
INSERT INTO rubric_criterion VALUES(6381,'physics-4-4-21',NULL,1,'So an infinite amount of energy would be needed to reach c, which is impossible.',1,1);
INSERT INTO rubric_criterion VALUES(6382,'physics-4-4-22',NULL,0,'When v is much less than c, γ ≈ 1 + ½v²/c². Then (γ − 1)mc² ≈ ½(v²/c²)mc² = ½mv².',1,1);
INSERT INTO rubric_criterion VALUES(6383,'physics-4-4-22',NULL,1,'So the two formulas agree at low speeds, and differ only near c.',1,1);
INSERT INTO rubric_criterion VALUES(6384,'physics-4-4-23',NULL,0,'Ek = (γ − 1)mc² = mc², so γ = 2.',1,1);
INSERT INTO rubric_criterion VALUES(6385,'physics-4-4-23',NULL,1,'1 − v²/c² = 0.25, so v = √0.75 c = 0.866c (2.6 × 10⁸ m/s).',1,1);
INSERT INTO rubric_criterion VALUES(6386,'physics-4-4-24',NULL,0,'The total mass of the helium nucleus (and other products) is less than the total mass of the hydrogen nuclei that fused.',1,1);
INSERT INTO rubric_criterion VALUES(6387,'physics-4-4-24',NULL,1,'This mass difference Δm is converted into energy according to E = Δmc², released mainly as kinetic energy of particles and as radiation.',2,1);
INSERT INTO rubric_criterion VALUES(6388,'physics-4-4-25',NULL,0,'γ = 3, so 1 − v²/c² = 1/9 and v = √(8/9) c = 0.943c = 2.83 × 10⁸ m/s.',2,1);
INSERT INTO rubric_criterion VALUES(6393,'physics-5-1-4',NULL,0,'Magnetic flux is a measure of the total magnetic field passing through an area.',1,1);
INSERT INTO rubric_criterion VALUES(6394,'physics-5-1-4',NULL,1,'Φ = B⊥A, where B⊥ is the component of the magnetic field perpendicular to the area A;',1,1);
INSERT INTO rubric_criterion VALUES(6395,'physics-5-1-4',NULL,2,'it is measured in webers (Wb).',1,1);
INSERT INTO rubric_criterion VALUES(6399,'physics-5-1-8',NULL,0,'A = π(0.050)² = 7.85 × 10⁻³ m², so Φ = 0.60 × 7.85 × 10⁻³ ≈ 4.7 × 10⁻³ Wb.',2,1);
INSERT INTO rubric_criterion VALUES(6403,'physics-5-1-12',NULL,0,'ΔΦ = 0.50 × 4.0 × 10⁻³ = 2.0 × 10⁻³ Wb per turn;',1,1);
INSERT INTO rubric_criterion VALUES(6404,'physics-5-1-12',NULL,1,'ε = NΔΦ/Δt = 150 × 2.0 × 10⁻³ / 0.080 ≈ 3.8 V (3.75 V).',2,1);
INSERT INTO rubric_criterion VALUES(6408,'physics-5-1-16',NULL,0,'The flux through the loop is BA and both B and A stay constant while the loop is fully inside the field, so the flux does not change.',1,1);
INSERT INTO rubric_criterion VALUES(6409,'physics-5-1-16',NULL,1,'With ΔΦ/Δt = 0, Faraday''s law gives zero emf and therefore no current.',1,1);
INSERT INTO rubric_criterion VALUES(6413,'physics-5-1-20',NULL,0,'Any three of: move the magnet faster (increase the rate of change of flux); use a stronger magnet;',1,1);
INSERT INTO rubric_criterion VALUES(6414,'physics-5-1-20',NULL,1,'increase the number of turns on the coil;',1,1);
INSERT INTO rubric_criterion VALUES(6415,'physics-5-1-20',NULL,2,'increase the cross-sectional area of the coil (or use an iron core to increase the flux).',1,1);
INSERT INTO rubric_criterion VALUES(6419,'physics-5-1-24',NULL,0,'ΔΦ = (0.50 − 0.10) × 0.025 = 0.010 Wb per turn;',1,1);
INSERT INTO rubric_criterion VALUES(6420,'physics-5-1-24',NULL,1,'ε = 80 × 0.010 / 0.20 = 4.0 V;',1,1);
INSERT INTO rubric_criterion VALUES(6421,'physics-5-1-24',NULL,2,'I = ε/R = 4.0 / 4.0 = 1.0 A.',1,1);
INSERT INTO rubric_criterion VALUES(6422,'physics-5-1-25',NULL,0,'Magnetic flux density B is the strength of the magnetic field at a point, measured in tesla.',1,1);
INSERT INTO rubric_criterion VALUES(6423,'physics-5-1-25',NULL,1,'Magnetic flux Φ is the amount of field passing through a given area, Φ = B⊥A, measured in webers.',1,1);
INSERT INTO rubric_criterion VALUES(6424,'physics-5-1-c1',NULL,0,'5.0 V',2,1);
INSERT INTO rubric_criterion VALUES(6428,'physics-5-2-4',NULL,0,'The direction of an induced current (or emf) is such that the magnetic field it produces opposes the change in magnetic flux that caused it.',1,1);
INSERT INTO rubric_criterion VALUES(6432,'physics-5-2-8',NULL,0,'If the induced current attracted the magnet, the magnet would speed up and more current would be produced with no work input, creating energy from nothing.',1,1);
INSERT INTO rubric_criterion VALUES(6433,'physics-5-2-8',NULL,1,'Because the induced current opposes the motion, work must be done to push the magnet in, and this work is converted into electrical energy.',2,1);
INSERT INTO rubric_criterion VALUES(6437,'physics-5-2-12',NULL,0,'As the magnet falls, the changing flux induces eddy currents in the pipe whose fields oppose its motion (Lenz''s law), producing an upward force.',1,1);
INSERT INTO rubric_criterion VALUES(6438,'physics-5-2-12',NULL,1,'This force increases with speed, so the magnet speeds up until the upward magnetic force equals its weight;',1,1);
INSERT INTO rubric_criterion VALUES(6439,'physics-5-2-12',NULL,2,'the net force is then zero and it falls at constant (terminal) velocity.',1,1);
INSERT INTO rubric_criterion VALUES(6443,'physics-5-2-16',NULL,0,'Anticlockwise viewed from above. The upward flux decreases, so the induced current produces an upward field inside the loop to oppose the decrease;',1,1);
INSERT INTO rubric_criterion VALUES(6444,'physics-5-2-16',NULL,1,'by the right-hand grip rule this needs an anticlockwise current viewed from above.',1,1);
INSERT INTO rubric_criterion VALUES(6448,'physics-5-2-20',NULL,0,'When the switch is closed the current, and therefore the flux through the ring, increases rapidly, inducing a current in the ring whose field opposes the solenoid''s field, so the ring is repelled.',1,1);
INSERT INTO rubric_criterion VALUES(6449,'physics-5-2-20',NULL,1,'Once the current is steady the flux is constant, so no emf or current is induced and there is no repulsion.',2,1);
INSERT INTO rubric_criterion VALUES(6453,'physics-5-2-24',NULL,0,'When braking, the wheels turn the motor''s coil in its magnetic field, inducing a current that charges the battery.',1,1);
INSERT INTO rubric_criterion VALUES(6454,'physics-5-2-24',NULL,1,'By Lenz''s law, the induced current produces a force (torque) that opposes the rotation, slowing the car while converting kinetic energy into electrical energy.',2,1);
INSERT INTO rubric_criterion VALUES(6455,'physics-5-2-25',NULL,0,'Anticlockwise as viewed from the magnet.',1,1);
INSERT INTO rubric_criterion VALUES(6456,'physics-5-2-25',NULL,1,'The near end of the coil must become a north pole to oppose the approaching north pole, and a current that appears anticlockwise when viewed from an end makes that end a north pole.',1,1);
INSERT INTO rubric_criterion VALUES(6461,'physics-5-3-4',NULL,0,'The emf depends on the rate of change of flux, not the flux itself.',1,1);
INSERT INTO rubric_criterion VALUES(6462,'physics-5-3-4',NULL,1,'When the plane is parallel to the field, the flux is passing through zero and changing at its fastest rate (the steepest part of the flux–time graph), so the emf is maximum.',2,1);
INSERT INTO rubric_criterion VALUES(6466,'physics-5-3-8',NULL,0,'V_peak = √2 × 230 ≈ 325 V.',1,1);
INSERT INTO rubric_criterion VALUES(6467,'physics-5-3-8',NULL,1,'Period T = 1/f = 1/50 = 0.020 s (20 ms).',1,1);
INSERT INTO rubric_criterion VALUES(6471,'physics-5-3-12',NULL,0,'Both are halved.',1,1);
INSERT INTO rubric_criterion VALUES(6472,'physics-5-3-12',NULL,1,'The flux changes half as quickly, so the peak emf halves, and the coil completes half as many rotations per second, so the frequency halves.',1,1);
INSERT INTO rubric_criterion VALUES(6476,'physics-5-3-16',NULL,0,'I_RMS = P/V_RMS = 2400/230 ≈ 10.4 A.',1,1);
INSERT INTO rubric_criterion VALUES(6477,'physics-5-3-16',NULL,1,'R = V_RMS²/P = 230²/2400 ≈ 22.0 Ω.',1,1);
INSERT INTO rubric_criterion VALUES(6481,'physics-5-3-20',NULL,0,'Slip rings keep each end of the coil connected to the same external terminal, so the output current reverses every half turn (AC).',1,1);
INSERT INTO rubric_criterion VALUES(6482,'physics-5-3-20',NULL,1,'A split-ring commutator swaps the connections every half turn, so the output always has the same polarity (varying DC).',2,1);
INSERT INTO rubric_criterion VALUES(6486,'physics-5-3-24',NULL,0,'After half a turn the flux reverses, so ΔΦ = 2BA = 2 × 0.20 × 0.030 = 0.012 Wb per turn.',1,1);
INSERT INTO rubric_criterion VALUES(6487,'physics-5-3-24',NULL,1,'ε = NΔΦ/Δt = 50 × 0.012 / 0.010 = 60 V.',1,1);
INSERT INTO rubric_criterion VALUES(6488,'physics-5-3-25',NULL,0,'The RMS value gives the equivalent DC value that delivers the same average power to a resistor, so power can be calculated directly with P = V_RMS I_RMS.',1,1);
INSERT INTO rubric_criterion VALUES(6489,'physics-5-3-25',NULL,1,'Peak values would overstate the average power, since the voltage is only at its peak for an instant.',2,1);
INSERT INTO rubric_criterion VALUES(6494,'physics-5-4-4',NULL,0,'An alternating current in the primary coil produces a changing magnetic flux in the iron core.',1,1);
INSERT INTO rubric_criterion VALUES(6495,'physics-5-4-4',NULL,1,'The core carries this changing flux through the secondary coil, and by Faraday''s law the changing flux induces an alternating emf in the secondary.',1,1);
INSERT INTO rubric_criterion VALUES(6499,'physics-5-4-8',NULL,0,'N_s = N_p × V_s/V_p = 1800 × 11/66 = 300 turns.',2,1);
INSERT INTO rubric_criterion VALUES(6503,'physics-5-4-12',NULL,0,'For a given power, P = VI, so a higher voltage means a smaller current.',1,1);
INSERT INTO rubric_criterion VALUES(6504,'physics-5-4-12',NULL,1,'The power lost as heat in the lines is P_loss = I²R, so reducing the current greatly reduces losses (halving the current reduces losses by a factor of 4).',2,1);
INSERT INTO rubric_criterion VALUES(6508,'physics-5-4-16',NULL,0,'(a) I = 100 000/415 ≈ 241 A, P_loss = 241² × 0.50 ≈ 2.9 × 10⁴ W (29 kW).',1,1);
INSERT INTO rubric_criterion VALUES(6509,'physics-5-4-16',NULL,1,'(b) I = 100 000/11 000 ≈ 9.09 A, P_loss = 9.09² × 0.50 ≈ 41 W.',2,1);
INSERT INTO rubric_criterion VALUES(6513,'physics-5-4-20',NULL,0,'The changing flux induces eddy currents in the iron core, which waste energy as heat.',1,1);
INSERT INTO rubric_criterion VALUES(6514,'physics-5-4-20',NULL,1,'Laminations (thin sheets insulated from each other) break up the paths for these currents, reducing eddy currents and so reducing energy loss.',1,1);
INSERT INTO rubric_criterion VALUES(6518,'physics-5-4-24',NULL,0,'Power = 24 × 4.0 = 96 W, so I_p = 96/240 = 0.40 A.',1,1);
INSERT INTO rubric_criterion VALUES(6519,'physics-5-4-24',NULL,1,'The turns ratio N_p : N_s = 240 : 24 = 10 : 1.',1,1);
INSERT INTO rubric_criterion VALUES(6520,'physics-5-4-25',NULL,0,'I = 20 000/240 ≈ 83.3 A.',1,1);
INSERT INTO rubric_criterion VALUES(6521,'physics-5-4-25',NULL,1,'Voltage drop = IR = 83.3 × 0.20 ≈ 16.7 V.',1,1);
INSERT INTO rubric_criterion VALUES(6522,'physics-5-4-25',NULL,2,'Power loss = I²R = 83.3² × 0.20 ≈ 1.4 × 10³ W (1.4 kW).',1,1);
INSERT INTO rubric_criterion VALUES(6523,'physics-5-4-c1',NULL,0,'About 1.0 MW at 22 kV and 10 kW at 220 kV: 100 times less',1,1);
INSERT INTO rubric_criterion VALUES(6542,'physics-6-1-19',NULL,0,'An EM wave consists of oscillating electric and magnetic fields.',1,1);
INSERT INTO rubric_criterion VALUES(6543,'physics-6-1-19',NULL,1,'A changing electric field produces a changing magnetic field, and a changing magnetic field produces a changing electric field, so the wave regenerates itself and propagates through empty space without any particles needing to vibrate.',2,1);
INSERT INTO rubric_criterion VALUES(6544,'physics-6-1-20',NULL,0,'λ = v/f = (2.25 × 10^8)/(4.6 × 10^14) ≈ 4.9 × 10^-7 m (about 490 nm).',3,1);
INSERT INTO rubric_criterion VALUES(6545,'physics-6-1-21',NULL,0,'λ = c/f = (3.0 × 10^8)/(2.6 × 10^9) ≈ 0.12 m (11.5 cm).',2,1);
INSERT INTO rubric_criterion VALUES(6546,'physics-6-1-22',NULL,0,'In a transverse wave the oscillation is perpendicular to the direction of energy transfer (e.g. light or any EM wave, waves on a string).',1,1);
INSERT INTO rubric_criterion VALUES(6547,'physics-6-1-22',NULL,1,'In a longitudinal wave the oscillation is parallel to the direction of energy transfer (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(6548,'physics-6-1-22',NULL,2,'sound in air).',1,1);
INSERT INTO rubric_criterion VALUES(6549,'physics-6-1-23',NULL,0,'Maxwell unified electricity and magnetism in a set of equations that predicted self-sustaining electromagnetic waves.',1,1);
INSERT INTO rubric_criterion VALUES(6550,'physics-6-1-23',NULL,1,'The predicted speed, 1/√(μ₀ε₀) ≈ 3.0 × 10^8 m s⁻¹, matched the measured speed of light, so he concluded that light is an electromagnetic wave.',2,1);
INSERT INTO rubric_criterion VALUES(6551,'physics-6-1-24',NULL,0,'The speed decreases, the frequency stays the same, and the wavelength decreases (since λ = v/f).',1,1);
INSERT INTO rubric_criterion VALUES(6552,'physics-6-1-25',NULL,0,'Number = (1.0 × 10^-3)/(500 × 10^-9) = 2.0 × 10^3, i.e.',1,1);
INSERT INTO rubric_criterion VALUES(6553,'physics-6-1-25',NULL,1,'2000 wavelengths.',1,1);
INSERT INTO rubric_criterion VALUES(6573,'physics-6-2-19',NULL,0,'Light from the two coherent slits travels different distances to each point on the screen.',1,1);
INSERT INTO rubric_criterion VALUES(6574,'physics-6-2-19',NULL,1,'Where the path difference is a whole number of wavelengths (nλ) the waves arrive in phase and interfere constructively, giving a bright fringe.',1,1);
INSERT INTO rubric_criterion VALUES(6575,'physics-6-2-19',NULL,2,'Where the path difference is (n − ½)λ the waves arrive half a cycle out of phase and interfere destructively, giving a dark fringe.',1,1);
INSERT INTO rubric_criterion VALUES(6576,'physics-6-2-20',NULL,0,'d = λL/Δx = (532 × 10^-9 × 3.0)/(4.0 × 10^-3) ≈ 4.0 × 10^-4 m = 0.40 mm.',2,1);
INSERT INTO rubric_criterion VALUES(6577,'physics-6-2-21',NULL,0,'Path difference = ½λ = 320 nm (3.2 × 10^-7 m).',1,1);
INSERT INTO rubric_criterion VALUES(6578,'physics-6-2-22',NULL,0,'The two-source interference fringes disappear.',1,1);
INSERT INTO rubric_criterion VALUES(6579,'physics-6-2-22',NULL,1,'Only the single-slit diffraction pattern remains: a broad central bright band with much fainter side bands, and the overall intensity is lower.',1,1);
INSERT INTO rubric_criterion VALUES(6580,'physics-6-2-23',NULL,0,'Δx = 25 mm ÷ 10 = 2.5 mm.',1,1);
INSERT INTO rubric_criterion VALUES(6581,'physics-6-2-23',NULL,1,'λ = Δx d / L = (2.5 × 10^-3 × 0.20 × 10^-3)/1.0 = 5.0 × 10^-7 m = 500 nm.',1,1);
INSERT INTO rubric_criterion VALUES(6582,'physics-6-2-24',NULL,0,'The central fringe is white because all wavelengths have zero path difference there.',1,1);
INSERT INTO rubric_criterion VALUES(6583,'physics-6-2-24',NULL,1,'Either side are coloured fringes, with violet/blue on the inner edge and red on the outer edge, because Δx = λL/d is larger for longer wavelengths.',1,1);
INSERT INTO rubric_criterion VALUES(6584,'physics-6-2-24',NULL,2,'Further out the colours overlap and the pattern washes out.',1,1);
INSERT INTO rubric_criterion VALUES(6585,'physics-6-2-25',NULL,0,'Newton''s particle model predicted just two bright bands behind the two slits.',1,1);
INSERT INTO rubric_criterion VALUES(6586,'physics-6-2-25',NULL,1,'Young observed many alternating bright and dark fringes, including darkness where light from both slits overlapped.',1,1);
INSERT INTO rubric_criterion VALUES(6587,'physics-6-2-25',NULL,2,'Adding light to light to produce darkness can only be explained by wave interference.',1,1);
INSERT INTO rubric_criterion VALUES(6588,'physics-6-2-c1',NULL,0,'4.0 mm;',1,1);
INSERT INTO rubric_criterion VALUES(6589,'physics-6-2-c1',NULL,1,'it decreases',1,1);
INSERT INTO rubric_criterion VALUES(6608,'physics-6-3-19',NULL,0,'Diffraction depends on the ratio λ/w. It is significant when λ/w is about 1 or greater, and becomes negligible when λ/w is much less than 1. Increasing λ or decreasing w increases diffraction.',1,1);
INSERT INTO rubric_criterion VALUES(6609,'physics-6-3-20',NULL,0,'λ = c/f = (3.0 × 10^8)/(2.4 × 10^9) = 0.125 m.',1,1);
INSERT INTO rubric_criterion VALUES(6610,'physics-6-3-20',NULL,1,'λ/w = 0.125/0.125 = 1.0, so the signal diffracts significantly and spreads widely beyond the gap.',2,1);
INSERT INTO rubric_criterion VALUES(6611,'physics-6-3-21',NULL,0,'Sound waves have wavelengths around 0.1–3 m, comparable to the doorway width, so λ/w is close to 1 and they diffract strongly around the edges.',1,1);
INSERT INTO rubric_criterion VALUES(6612,'physics-6-3-21',NULL,1,'Light has wavelengths around 400–700 nm, so λ/w is tiny and it hardly diffracts, travelling almost in straight lines.',2,1);
INSERT INTO rubric_criterion VALUES(6613,'physics-6-3-22',NULL,0,'The pattern is a wide, bright central band with fainter, narrower bands on either side.',1,1);
INSERT INTO rubric_criterion VALUES(6614,'physics-6-3-22',NULL,1,'As the slit narrows, λ/w increases, so the whole pattern spreads out: the central band becomes wider (and dimmer, because less light passes through).',1,1);
INSERT INTO rubric_criterion VALUES(6615,'physics-6-3-23',NULL,0,'Keep λ/w constant: w = 0.10 mm × (450/650) ≈ 0.069 mm (about 69 µm).',1,1);
INSERT INTO rubric_criterion VALUES(6616,'physics-6-3-24',NULL,0,'UV light has a shorter wavelength than visible light.',1,1);
INSERT INTO rubric_criterion VALUES(6617,'physics-6-3-24',NULL,1,'For tiny features of a given width, λ/w is smaller, so there is less diffraction and spreading of the light, allowing sharper, smaller features to be produced.',1,1);
INSERT INTO rubric_criterion VALUES(6618,'physics-6-3-25',NULL,0,'Newton''s particle model predicts that light travels in straight lines and casts sharp-edged shadows.',1,1);
INSERT INTO rubric_criterion VALUES(6619,'physics-6-3-25',NULL,1,'When light passes through a narrow gap it spreads into the geometric shadow and forms bright and dark bands, which is characteristic of waves and is explained by Huygens'' wavelets interfering.',2,1);
INSERT INTO rubric_criterion VALUES(6639,'physics-6-4-19',NULL,0,'Polarisation means restricting the oscillation to a single plane. This is only possible for transverse waves, where oscillations can occur in many directions perpendicular to the direction of travel.',1,1);
INSERT INTO rubric_criterion VALUES(6640,'physics-6-4-19',NULL,1,'In a longitudinal wave the oscillation is always along the direction of travel, so there is nothing to filter.',1,1);
INSERT INTO rubric_criterion VALUES(6641,'physics-6-4-19',NULL,2,'Because light can be polarised, it must be transverse.',1,1);
INSERT INTO rubric_criterion VALUES(6642,'physics-6-4-20',NULL,0,'Light reflecting off a horizontal surface such as a wet road is largely horizontally polarised.',1,1);
INSERT INTO rubric_criterion VALUES(6643,'physics-6-4-20',NULL,1,'The lenses have vertical transmission axes, so they block most of this horizontally polarised reflected light while still transmitting about half of the unpolarised light from other objects.',2,1);
INSERT INTO rubric_criterion VALUES(6644,'physics-6-4-21',NULL,0,'After the first filter: 60 W m⁻² (half). After the second, crossed filter: 0 W m⁻².',1,1);
INSERT INTO rubric_criterion VALUES(6645,'physics-6-4-22',NULL,0,'Look at the light through a single polarising filter and rotate the filter through 180°. If the brightness stays constant, the light is unpolarised.',1,1);
INSERT INTO rubric_criterion VALUES(6646,'physics-6-4-22',NULL,1,'If the brightness varies, dropping to (near) zero at one orientation, the light is plane-polarised.',1,1);
INSERT INTO rubric_criterion VALUES(6647,'physics-6-4-23',NULL,0,'In unpolarised light the electric field oscillates in all directions perpendicular to the direction of travel.',1,1);
INSERT INTO rubric_criterion VALUES(6648,'physics-6-4-23',NULL,1,'In plane-polarised light the electric field oscillates in only one plane.',1,1);
INSERT INTO rubric_criterion VALUES(6649,'physics-6-4-24',NULL,0,'Sound in air is a longitudinal wave: the air particles oscillate parallel to the direction of travel.',1,1);
INSERT INTO rubric_criterion VALUES(6650,'physics-6-4-24',NULL,1,'There is only one possible oscillation direction, so it cannot be restricted to a particular plane perpendicular to the motion.',1,1);
INSERT INTO rubric_criterion VALUES(6651,'physics-6-4-25',NULL,0,'Maxwell''s theory describes light as oscillating electric and magnetic fields perpendicular to the direction of travel, which is a transverse wave.',1,1);
INSERT INTO rubric_criterion VALUES(6652,'physics-6-4-25',NULL,1,'Polarisation filters can select one direction of the electric field oscillation, which is only possible for a transverse wave, so polarisation is consistent with Maxwell''s model.',2,1);
INSERT INTO rubric_criterion VALUES(6657,'physics-7-1-4',NULL,0,'Each red photon has energy hf less than the work function.',1,1);
INSERT INTO rubric_criterion VALUES(6658,'physics-7-1-4',NULL,1,'Electrons absorb one photon at a time, so increasing intensity only increases the number of photons, not the energy of each, and no electron gains enough energy to escape.',1,1);
INSERT INTO rubric_criterion VALUES(6662,'physics-7-1-8',NULL,0,'Photon energy = 1.24 × 10^-6/250 × 10^-9 = 4.96 eV.',1,1);
INSERT INTO rubric_criterion VALUES(6663,'physics-7-1-8',NULL,1,'Ek max = 4.96 − 4.3 ≈ 0.66 eV (about 1.1 × 10^-19 J).',2,1);
INSERT INTO rubric_criterion VALUES(6667,'physics-7-1-12',NULL,0,'Once the anode is positive enough, every photoelectron emitted from the cathode is collected.',1,1);
INSERT INTO rubric_criterion VALUES(6668,'physics-7-1-12',NULL,1,'Further increasing the voltage cannot increase the current because the rate of emission is fixed by the number of photons arriving per second.',1,1);
INSERT INTO rubric_criterion VALUES(6672,'physics-7-1-16',NULL,0,'h = Δ(eV₀)/Δf = 0.83 eV/2.0 × 10^14 Hz = 4.15 × 10^-15 eV s.',1,1);
INSERT INTO rubric_criterion VALUES(6673,'physics-7-1-16',NULL,1,'W = hf − eV₀ = (4.15 × 10^-15)(6.0 × 10^14) − 0.50 ≈ 2.0 eV.',2,1);
INSERT INTO rubric_criterion VALUES(6677,'physics-7-1-20',NULL,0,'The wave model predicts that with dim light, energy would spread over the surface and an electron would need time to accumulate enough to escape.',1,1);
INSERT INTO rubric_criterion VALUES(6678,'physics-7-1-20',NULL,1,'In fact electrons are emitted instantly, consistent with each electron absorbing a whole photon''s energy in one interaction.',2,1);
INSERT INTO rubric_criterion VALUES(6682,'physics-7-1-24',NULL,0,'A reverse voltage is applied so the anode is negative relative to the photoemissive cathode.',1,1);
INSERT INTO rubric_criterion VALUES(6683,'physics-7-1-24',NULL,1,'The voltage is increased until the photocurrent just falls to zero;',1,1);
INSERT INTO rubric_criterion VALUES(6684,'physics-7-1-24',NULL,2,'this voltage is the stopping voltage, where eV₀ equals the maximum kinetic energy of the photoelectrons.',1,1);
INSERT INTO rubric_criterion VALUES(6685,'physics-7-1-25',NULL,0,'E photon = hc/λ = (6.63 × 10^-34 × 3.00 × 10^8)/5.30 × 10^-7 = 3.75 × 10^-19 J.',1,1);
INSERT INTO rubric_criterion VALUES(6686,'physics-7-1-25',NULL,1,'N = 1.0/3.75 × 10^-19 ≈ 2.7 × 10^18 photons per second.',2,1);
INSERT INTO rubric_criterion VALUES(6687,'physics-7-1-c1',NULL,0,'0.80 eV;',1,1);
INSERT INTO rubric_criterion VALUES(6688,'physics-7-1-c1',NULL,1,'0.80 V',1,1);
INSERT INTO rubric_criterion VALUES(6692,'physics-7-2-4',NULL,0,'Ek = 54 × 1.60 × 10^-19 = 8.64 × 10^-18 J;',1,1);
INSERT INTO rubric_criterion VALUES(6693,'physics-7-2-4',NULL,1,'p = √(2mEk) = √(2 × 9.11 × 10^-31 × 8.64 × 10^-18) = 3.97 × 10^-24 kg m s^-1;',1,1);
INSERT INTO rubric_criterion VALUES(6694,'physics-7-2-4',NULL,2,'λ = h/p = 1.67 × 10^-10 m (0.167 nm).',1,1);
INSERT INTO rubric_criterion VALUES(6698,'physics-7-2-8',NULL,0,'A diffraction pattern of bright and dark rings forms because electron waves scattered by regularly spaced atoms interfere constructively and destructively.',1,1);
INSERT INTO rubric_criterion VALUES(6699,'physics-7-2-8',NULL,1,'Interference and diffraction are wave properties, and the ring spacing matches the de Broglie wavelength λ = h/p.',1,1);
INSERT INTO rubric_criterion VALUES(6703,'physics-7-2-12',NULL,0,'Same pattern means same wavelength and hence the same momentum.',1,1);
INSERT INTO rubric_criterion VALUES(6704,'physics-7-2-12',NULL,1,'p = E/c = (8000 × 1.60 × 10^-19)/3.00 × 10^8 = 4.27 × 10^-24 kg m s^-1.',1,1);
INSERT INTO rubric_criterion VALUES(6705,'physics-7-2-12',NULL,2,'Electron Ek = p²/(2m) = 1.0 × 10^-17 J ≈ 62 eV.',1,1);
INSERT INTO rubric_criterion VALUES(6709,'physics-7-2-16',NULL,0,'Electrons accelerated through thousands of volts have de Broglie wavelengths far shorter than visible light (around 400–700 nm).',1,1);
INSERT INTO rubric_criterion VALUES(6710,'physics-7-2-16',NULL,1,'Less diffraction occurs for a given aperture or feature size, so finer detail can be resolved.',1,1);
INSERT INTO rubric_criterion VALUES(6714,'physics-7-2-20',NULL,0,'v = h/(mλ) = 6.63 × 10^-34/(1.67 × 10^-27 × 1.0 × 10^-10) ≈ 4.0 × 10^3 m s^-1.',2,1);
INSERT INTO rubric_criterion VALUES(6718,'physics-7-2-24',NULL,0,'A car''s momentum is very large, so its de Broglie wavelength λ = h/(mv) is extremely small (around 10^-38 m), far smaller than any gap or obstacle.',1,1);
INSERT INTO rubric_criterion VALUES(6719,'physics-7-2-24',NULL,1,'Diffraction is therefore negligible and no wave effects can be detected.',1,1);
INSERT INTO rubric_criterion VALUES(6720,'physics-7-2-25',NULL,0,'The de Broglie wavelength halves because λ = h/(mv).',1,1);
INSERT INTO rubric_criterion VALUES(6721,'physics-7-2-25',NULL,1,'Electrons diffract through smaller angles, so the rings become smaller and closer together (roughly half the radius for small angles).',1,1);
INSERT INTO rubric_criterion VALUES(6726,'physics-7-3-4',NULL,0,'ΔE = 13.6 − 1.51 = 12.09 eV.',1,1);
INSERT INTO rubric_criterion VALUES(6727,'physics-7-3-4',NULL,1,'f = ΔE/h = 12.09/4.14 × 10^-15 = 2.92 × 10^15 Hz.',1,1);
INSERT INTO rubric_criterion VALUES(6731,'physics-7-3-8',NULL,0,'Electrons in the atoms can only occupy specific, quantised energy levels.',1,1);
INSERT INTO rubric_criterion VALUES(6732,'physics-7-3-8',NULL,1,'When an electron drops from a higher level to a lower level it emits a photon with energy equal to the difference, E = hf, so only specific frequencies and wavelengths appear.',2,1);
INSERT INTO rubric_criterion VALUES(6736,'physics-7-3-12',NULL,0,'Atoms in the gas absorb only photons whose energies exactly match differences between their energy levels.',1,1);
INSERT INTO rubric_criterion VALUES(6737,'physics-7-3-12',NULL,1,'Those wavelengths are removed from the beam, and the re-emitted light goes in all directions, so dark lines appear on the continuous spectrum at those wavelengths.',2,1);
INSERT INTO rubric_criterion VALUES(6741,'physics-7-3-16',NULL,0,'E₃ → E₂: 2.5 eV; E₂ → E₁: 3.5 eV; E₃ → E₁: 6.0 eV.',1,1);
INSERT INTO rubric_criterion VALUES(6745,'physics-7-3-20',NULL,0,'A photon must be absorbed completely, so its energy must exactly equal a transition energy, and 11.0 eV matches none.',1,1);
INSERT INTO rubric_criterion VALUES(6746,'physics-7-3-20',NULL,1,'A colliding electron can transfer only part of its kinetic energy, so it can give 10.2 eV to raise the atom to n = 2 and keep 0.8 eV.',2,1);
INSERT INTO rubric_criterion VALUES(6750,'physics-7-3-24',NULL,0,'ΔE = 10.2 eV;',1,1);
INSERT INTO rubric_criterion VALUES(6751,'physics-7-3-24',NULL,1,'λ = 1.24 × 10^-6/10.2 = 1.22 × 10^-7 m (about 122 nm), which is ultraviolet.',1,1);
INSERT INTO rubric_criterion VALUES(6752,'physics-7-3-25',NULL,0,'An electron in an orbit behaves as a wave, and a stable orbit is one where a whole number of wavelengths fits around the circumference (nλ = 2πr), forming a standing wave.',1,1);
INSERT INTO rubric_criterion VALUES(6753,'physics-7-3-25',NULL,1,'Other orbits would cause destructive interference, so only certain orbits and energies are allowed.',2,1);
INSERT INTO rubric_criterion VALUES(6758,'physics-7-4-4',NULL,0,'Light shows both wave and particle behaviour, and which appears depends on the experiment.',1,1);
INSERT INTO rubric_criterion VALUES(6759,'physics-7-4-4',NULL,1,'Young''s double-slit interference pattern is evidence for the wave model;',1,1);
INSERT INTO rubric_criterion VALUES(6760,'physics-7-4-4',NULL,2,'the photoelectric effect, with its threshold frequency and instant emission, is evidence for the photon (particle) model.',1,1);
INSERT INTO rubric_criterion VALUES(6764,'physics-7-4-8',NULL,0,'Each photon is detected at a single point on the screen, showing particle behaviour.',1,1);
INSERT INTO rubric_criterion VALUES(6765,'physics-7-4-8',NULL,1,'As many photons accumulate, they form the interference pattern, showing that the probability of where each photon lands is governed by wave interference.',1,1);
INSERT INTO rubric_criterion VALUES(6769,'physics-7-4-12',NULL,0,'Δx = λL/d = (5.32 × 10^-7 × 1.5)/2.5 × 10^-4 = 3.2 × 10^-3 m (3.2 mm).',2,1);
INSERT INTO rubric_criterion VALUES(6773,'physics-7-4-16',NULL,0,'Newton''s model predicts two bright bands behind the slits, with brightness simply adding where streams overlap.',1,1);
INSERT INTO rubric_criterion VALUES(6774,'physics-7-4-16',NULL,1,'Young observed many alternating bright and dark bands, and the dark bands require destructive interference of waves, which particles cannot produce.',1,1);
INSERT INTO rubric_criterion VALUES(6778,'physics-7-4-20',NULL,0,'Each photon of a given frequency carries the same energy, E = hf.',1,1);
INSERT INTO rubric_criterion VALUES(6779,'physics-7-4-20',NULL,1,'A more intense beam contains more photons arriving each second, so the total energy delivered per second (the power) is greater, while the energy of each photon is unchanged.',2,1);
INSERT INTO rubric_criterion VALUES(6783,'physics-7-4-24',NULL,0,'Path difference/λ = 1.2 × 10^-6/4.8 × 10^-7 = 2.5, which is a half-integer number of wavelengths.',1,1);
INSERT INTO rubric_criterion VALUES(6784,'physics-7-4-24',NULL,1,'The waves arrive out of phase and interfere destructively, so P is on a dark band (the third dark band).',1,1);
INSERT INTO rubric_criterion VALUES(6785,'physics-7-4-25',NULL,0,'The photoelectric effect shows that light, usually treated as a wave, also behaves as particles (photons).',1,1);
INSERT INTO rubric_criterion VALUES(6786,'physics-7-4-25',NULL,1,'Electron diffraction shows that electrons, usually treated as particles, also behave as waves with λ = h/p.',1,1);
INSERT INTO rubric_criterion VALUES(6787,'physics-7-4-25',NULL,2,'Together they show both light and matter have dual natures.',1,1);
INSERT INTO rubric_criterion VALUES(6807,'physics-8-1-19',NULL,0,'Independent: number of turns in the coil. Dependent: peak induced EMF.',1,1);
INSERT INTO rubric_criterion VALUES(6808,'physics-8-1-19',NULL,1,'Controlled (any two): strength of the magnet, drop height, coil diameter/area, orientation of the magnet, type of wire.',1,1);
INSERT INTO rubric_criterion VALUES(6809,'physics-8-1-20',NULL,0,'If the angle of the incline increases, then the acceleration of the trolley will increase, because the component of the gravitational force down the slope (mg sin θ) increases.',2,1);
INSERT INTO rubric_criterion VALUES(6810,'physics-8-1-21',NULL,0,'Repeated measurements allow the effect of random errors to be reduced by averaging, help identify outliers and indicate the precision/repeatability of the data.',1,1);
INSERT INTO rubric_criterion VALUES(6811,'physics-8-1-21',NULL,1,'However, repeating does not reduce systematic errors.',1,1);
INSERT INTO rubric_criterion VALUES(6812,'physics-8-1-22',NULL,0,'Repeatability is the closeness of agreement of results when the same person repeats a measurement with the same method, equipment and conditions.',1,1);
INSERT INTO rubric_criterion VALUES(6813,'physics-8-1-22',NULL,1,'Reproducibility is the closeness of agreement when the measurement is repeated by different people, with different equipment or in different locations.',2,1);
INSERT INTO rubric_criterion VALUES(6814,'physics-8-1-23',NULL,0,'Any two: increase the distance to the wall so the time is longer; clap in rhythm with the echoes and time many (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(6815,'physics-8-1-23',NULL,1,'20) intervals, then divide; use microphones and a data logger instead of a hand-held stopwatch;',1,1);
INSERT INTO rubric_criterion VALUES(6816,'physics-8-1-23',NULL,2,'repeat and average.',1,1);
INSERT INTO rubric_criterion VALUES(6817,'physics-8-1-24',NULL,0,'A wide range with enough values allows the trend or relationship to be identified reliably, reveals any non-linearity, reduces the influence of any single uncertain point on the line of best fit and allows a meaningful gradient to be found.',3,1);
INSERT INTO rubric_criterion VALUES(6818,'physics-8-1-25',NULL,0,'A controlled variable is a variable that could affect the dependent variable and so is kept constant throughout the experiment.',1,1);
INSERT INTO rubric_criterion VALUES(6819,'physics-8-1-25',NULL,1,'If it is not controlled, changes in the dependent variable may be caused by it rather than the independent variable, so the conclusion is not valid.',2,1);
INSERT INTO rubric_criterion VALUES(6839,'physics-8-2-19',NULL,0,'Accuracy is how close a measurement is to the true value;',1,1);
INSERT INTO rubric_criterion VALUES(6840,'physics-8-2-19',NULL,1,'precision is how closely repeated measurements agree with each other.',1,1);
INSERT INTO rubric_criterion VALUES(6841,'physics-8-2-19',NULL,2,'For example, readings of g of 9.51, 9.52 and 9.53 m/s² are precise but not accurate, because they are clustered but well below 9.80 m/s².',1,1);
INSERT INTO rubric_criterion VALUES(6842,'physics-8-2-20',NULL,0,'Mean = 22.0 ÷ 5 = 4.4 cm. Half range = (4.6 − 4.2) ÷ 2 = 0.2 cm.',1,1);
INSERT INTO rubric_criterion VALUES(6843,'physics-8-2-20',NULL,1,'Extension = 4.4 ± 0.2 cm.',1,1);
INSERT INTO rubric_criterion VALUES(6844,'physics-8-2-21',NULL,0,'g = 4π² × 0.800 ÷ 1.80² = 9.75 m/s².',1,1);
INSERT INTO rubric_criterion VALUES(6845,'physics-8-2-21',NULL,1,'Percentage uncertainty = 0.625% + 2 × 1.11% ≈ 2.8%, so the uncertainty is about ±0.3 m/s².',1,1);
INSERT INTO rubric_criterion VALUES(6846,'physics-8-2-21',NULL,2,'g = 9.7 ± 0.3 m/s².',1,1);
INSERT INTO rubric_criterion VALUES(6847,'physics-8-2-22',NULL,0,'R = 6.0 ÷ 0.50 = 12 Ω. Percentage uncertainty = 1.7% + 4.0% = 5.7%, so ΔR ≈ 0.7 Ω.',1,1);
INSERT INTO rubric_criterion VALUES(6848,'physics-8-2-22',NULL,1,'R = 12.0 ± 0.7 Ω.',1,1);
INSERT INTO rubric_criterion VALUES(6849,'physics-8-2-23',NULL,0,'Volume = 2.00³ = 8.00 cm³ with 3 × 1% = 3% uncertainty.',1,1);
INSERT INTO rubric_criterion VALUES(6850,'physics-8-2-23',NULL,1,'Mass uncertainty = 0.46%.',1,1);
INSERT INTO rubric_criterion VALUES(6851,'physics-8-2-23',NULL,2,'Density = 21.6 ÷ 8.00 = 2.70 g/cm³ with about 3.5% uncertainty, so ρ = 2.70 ± 0.09 g/cm³.',1,1);
INSERT INTO rubric_criterion VALUES(6852,'physics-8-2-24',NULL,0,'Extra significant figures imply a higher precision than the measurements can support.',1,1);
INSERT INTO rubric_criterion VALUES(6853,'physics-8-2-24',NULL,1,'The result should be given to the same number of significant figures as the least precise data used.',1,1);
INSERT INTO rubric_criterion VALUES(6854,'physics-8-2-25',NULL,0,'One oscillation: 0.2 ÷ 1.5 × 100 ≈ 13%. Twenty oscillations take 30 s: 0.2 ÷ 30 × 100 ≈ 0.67%.',1,1);
INSERT INTO rubric_criterion VALUES(6855,'physics-8-2-25',NULL,1,'Timing 20 oscillations reduces the percentage uncertainty by a factor of 20.',1,1);
INSERT INTO rubric_criterion VALUES(6875,'physics-8-3-19',NULL,0,'Random errors cause unpredictable scatter of readings either side of the true value, e.g. variation in reaction time when using a stopwatch.',1,1);
INSERT INTO rubric_criterion VALUES(6876,'physics-8-3-19',NULL,1,'Systematic errors shift every reading in the same direction by a consistent amount, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(6877,'physics-8-3-19',NULL,2,'a balance with a zero error or a miscalibrated thermometer.',1,1);
INSERT INTO rubric_criterion VALUES(6878,'physics-8-3-20',NULL,0,'The accepted value lies outside the range 9.37 to 9.47 m/s², so random error alone cannot explain the difference and a systematic error is likely.',1,1);
INSERT INTO rubric_criterion VALUES(6879,'physics-8-3-20',NULL,1,'For example, measuring the length only to the top of the bob (making L too short) would make g consistently too low.',2,1);
INSERT INTO rubric_criterion VALUES(6880,'physics-8-3-21',NULL,0,'A systematic error affects every reading in the same direction by the same amount, so the mean is shifted by the same amount.',1,1);
INSERT INTO rubric_criterion VALUES(6881,'physics-8-3-21',NULL,1,'Averaging only reduces errors that vary randomly above and below the true value.',1,1);
INSERT INTO rubric_criterion VALUES(6882,'physics-8-3-22',NULL,0,'True diameter = 1.27 − 0.03 = 1.24 mm.',1,1);
INSERT INTO rubric_criterion VALUES(6883,'physics-8-3-23',NULL,0,'3.10 s is the outlier.',1,1);
INSERT INTO rubric_criterion VALUES(6884,'physics-8-3-23',NULL,1,'Mean of the remaining values = (2.31 + 2.28 + 2.35 + 2.30) ÷ 4 = 9.24 ÷ 4 = 2.31 s.',2,1);
INSERT INTO rubric_criterion VALUES(6885,'physics-8-3-24',NULL,0,'It is too vague.',1,1);
INSERT INTO rubric_criterion VALUES(6886,'physics-8-3-24',NULL,1,'Genuine mistakes (such as misreading a scale) should be avoided or the reading repeated, and are not part of the error analysis.',1,1);
INSERT INTO rubric_criterion VALUES(6887,'physics-8-3-24',NULL,2,'The report should instead identify specific random or systematic errors and their effect on the results.',1,1);
INSERT INTO rubric_criterion VALUES(6888,'physics-8-3-25',NULL,0,'This is a systematic error: friction always opposes motion, so the measured acceleration will be consistently less than g sin θ.',1,1);
INSERT INTO rubric_criterion VALUES(6889,'physics-8-3-25',NULL,1,'It could be reduced by friction-compensating the track (tilting it slightly until the trolley moves at constant velocity) or including friction in the model.',2,1);
INSERT INTO rubric_criterion VALUES(6909,'physics-8-4-19',NULL,0,'Square both sides: T² = (4π²/k)m.',1,1);
INSERT INTO rubric_criterion VALUES(6910,'physics-8-4-19',NULL,1,'Plot T² (y-axis) against m (x-axis);',1,1);
INSERT INTO rubric_criterion VALUES(6911,'physics-8-4-19',NULL,2,'the graph is a straight line through the origin with gradient 4π²/k, so k = 4π² ÷ gradient.',1,1);
INSERT INTO rubric_criterion VALUES(6912,'physics-8-4-20',NULL,0,'k = 4π² ÷ 0.20 = 39.5 ÷ 0.20 ≈ 2.0 × 10² N/m.',2,1);
INSERT INTO rubric_criterion VALUES(6913,'physics-8-4-21',NULL,0,'Measure I at several distances, then plot I against 1/r². If the graph is a straight line through the origin, then I ∝ 1/r² is supported;',1,1);
INSERT INTO rubric_criterion VALUES(6914,'physics-8-4-21',NULL,1,'the gradient gives the constant of proportionality.',1,1);
INSERT INTO rubric_criterion VALUES(6915,'physics-8-4-22',NULL,0,'Gradient = (5.2 + 4.6) ÷ 2 = 4.9, uncertainty = (5.2 − 4.6) ÷ 2 = 0.3.',1,1);
INSERT INTO rubric_criterion VALUES(6916,'physics-8-4-22',NULL,1,'Gradient = 4.9 ± 0.3.',1,1);
INSERT INTO rubric_criterion VALUES(6917,'physics-8-4-23',NULL,0,'φ = hf₀ = 4.14 × 10⁻¹⁵ × 5.5 × 10¹⁴ ≈ 2.3 eV.',2,1);
INSERT INTO rubric_criterion VALUES(6918,'physics-8-4-24',NULL,0,'A straight line makes the relationship easy to recognise and test, deviations from the model are easy to see, and the gradient and intercept can be used to find physical constants (such as g or k) using all the data rather than one point.',3,1);
INSERT INTO rubric_criterion VALUES(6919,'physics-8-4-25',NULL,0,'d = ½at², so the gradient = a/2.',1,1);
INSERT INTO rubric_criterion VALUES(6920,'physics-8-4-25',NULL,1,'a = 2 × 0.60 = 1.2 m/s².',1,1);
INSERT INTO rubric_criterion VALUES(6921,'physics-8-4-c1',NULL,0,'Plot T² against L;',1,1);
INSERT INTO rubric_criterion VALUES(6922,'physics-8-4-c1',NULL,1,'g = 4π²/gradient ≈ 9.80 m/s²',3,1);
INSERT INTO rubric_criterion VALUES(6928,'bio34a1-nas-6',NULL,0,'The two strands run in opposite directions;',1,1);
INSERT INTO rubric_criterion VALUES(6929,'bio34a1-nas-6',NULL,1,'one strand runs 5′ to 3′ while its complementary strand runs 3′ to 5′ (the 5′ phosphate end of one strand lies opposite the 3′ hydroxyl end of the other).',1,1);
INSERT INTO rubric_criterion VALUES(6930,'bio34a1-nas-7',NULL,0,'Complementary strand: 3′-TACGGCAA-5′ (equivalently written 5′-AACGGCAT-3′);',1,1);
INSERT INTO rubric_criterion VALUES(6931,'bio34a1-nas-7',NULL,1,'the strands are held together by hydrogen bonds between complementary bases.',1,1);
INSERT INTO rubric_criterion VALUES(6932,'bio34a1-nas-8',NULL,0,'Both are single-stranded RNA polymers made of ribonucleotides containing ribose and A, U, C, G;',1,1);
INSERT INTO rubric_criterion VALUES(6933,'bio34a1-nas-8',NULL,1,'mRNA is a linear molecule that carries a copy of the genetic instructions (codons) from the DNA to the ribosome;',1,1);
INSERT INTO rubric_criterion VALUES(6934,'bio34a1-nas-8',NULL,2,'tRNA folds into a cloverleaf shape held by internal base pairing, carries an anticodon at one end and a specific amino acid at the 3′ end, delivering amino acids to the ribosome during translation.',1,1);
INSERT INTO rubric_criterion VALUES(6941,'bio34a1-trp-6',NULL,0,'A 5′ methyl-guanine (methylated G) cap is added to the 5′ end, which protects the mRNA and helps ribosome attachment;',1,1);
INSERT INTO rubric_criterion VALUES(6942,'bio34a1-trp-6',NULL,1,'a poly-A tail is added to the 3′ end, which protects the mRNA from degradation and aids export;',1,1);
INSERT INTO rubric_criterion VALUES(6943,'bio34a1-trp-6',NULL,2,'introns are removed and exons are joined together by spliceosomes (splicing).',1,1);
INSERT INTO rubric_criterion VALUES(6944,'bio34a1-trp-7',NULL,0,'During splicing, different combinations of exons from the same pre-mRNA can be retained or removed;',1,1);
INSERT INTO rubric_criterion VALUES(6945,'bio34a1-trp-7',NULL,1,'this produces different mature mRNAs from one gene, each translated into a different polypeptide, so the number of proteins exceeds the number of genes.',1,1);
INSERT INTO rubric_criterion VALUES(6946,'bio34a1-trp-8',NULL,0,'Prokaryotes lack a membrane-bound nucleus, so ribosomes can access mRNA as soon as it is made (eukaryotes separate transcription in the nucleus from translation in the cytoplasm);',1,1);
INSERT INTO rubric_criterion VALUES(6947,'bio34a1-trp-8',NULL,1,'as a consequence, prokaryotic mRNA generally does not undergo splicing, capping and tailing, whereas eukaryotic pre-mRNA is processed in the nucleus before export.',1,1);
INSERT INTO rubric_criterion VALUES(6954,'bio34a1-tgc-6',NULL,0,'Each tRNA molecule binds (is charged with) a specific amino acid at its 3′ end;',1,1);
INSERT INTO rubric_criterion VALUES(6955,'bio34a1-tgc-6',NULL,1,'it carries this amino acid to the ribosome;',1,1);
INSERT INTO rubric_criterion VALUES(6956,'bio34a1-tgc-6',NULL,2,'its anticodon pairs complementarily with the matching mRNA codon, ensuring amino acids are added in the order specified by the mRNA.',1,1);
INSERT INTO rubric_criterion VALUES(6957,'bio34a1-tgc-7',NULL,0,'Met–Ala–Trp–Lys;',1,1);
INSERT INTO rubric_criterion VALUES(6958,'bio34a1-tgc-7',NULL,1,'UGA is a stop codon, which has no matching tRNA, so a release factor binds instead and translation terminates, releasing the polypeptide.',1,1);
INSERT INTO rubric_criterion VALUES(6959,'bio34a1-tgc-8',NULL,0,'The genetic code is universal;',1,1);
INSERT INTO rubric_criterion VALUES(6960,'bio34a1-tgc-8',NULL,1,'the same codons code for the same amino acids in almost all organisms, so bacterial ribosomes and tRNAs translate the jellyfish codons into the same amino acid sequence.',1,1);
INSERT INTO rubric_criterion VALUES(6967,'bio34a1-gro-6',NULL,0,'When tryptophan is low, no tryptophan binds to the repressor (coded by trpR), so the repressor stays inactive and cannot bind to the operator;',1,1);
INSERT INTO rubric_criterion VALUES(6968,'bio34a1-gro-6',NULL,1,'RNA polymerase can therefore bind to the promoter and transcribe the structural genes that code for the enzymes that synthesise tryptophan.',1,1);
INSERT INTO rubric_criterion VALUES(6969,'bio34a1-gro-7',NULL,0,'Making tryptophan-synthesis enzymes requires energy and resources (ATP, amino acids, nucleotides);',1,1);
INSERT INTO rubric_criterion VALUES(6970,'bio34a1-gro-7',NULL,1,'by switching off the operon when tryptophan is already available, the bacterium avoids wasting resources and can direct them to other processes such as growth and reproduction.',1,1);
INSERT INTO rubric_criterion VALUES(6971,'bio34a1-gro-8',NULL,0,'Transcription and translation are coupled in bacteria, so a ribosome begins translating the leader (trpL) sequence while it is being transcribed;',1,1);
INSERT INTO rubric_criterion VALUES(6972,'bio34a1-gro-8',NULL,1,'when tryptophan (and tRNA carrying tryptophan) is abundant, the ribosome moves quickly past the trp codons in region 1 and covers region 2;',1,1);
INSERT INTO rubric_criterion VALUES(6973,'bio34a1-gro-8',NULL,2,'this allows regions 3 and 4 to pair, forming a terminator hairpin loop that causes RNA polymerase to detach before the structural genes are transcribed.',1,1);
INSERT INTO rubric_criterion VALUES(6980,'bio34a1-psp-6',NULL,0,'A condensation reaction occurs between the carboxyl group of one amino acid and the amino group of the next;',1,1);
INSERT INTO rubric_criterion VALUES(6981,'bio34a1-psp-6',NULL,1,'a molecule of water is released and a covalent peptide bond (C–N) forms between them.',1,1);
INSERT INTO rubric_criterion VALUES(6982,'bio34a1-psp-7',NULL,0,'The change alters the primary structure of the polypeptide; this changes the interactions between R groups (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(6983,'bio34a1-psp-7',NULL,1,'hydrophobic interactions, ionic bonds) and therefore the way the polypeptide folds into its tertiary structure;',1,1);
INSERT INTO rubric_criterion VALUES(6984,'bio34a1-psp-7',NULL,2,'if the shape of the active site changes, the substrate may no longer be complementary, so enzyme activity is reduced or lost.',1,1);
INSERT INTO rubric_criterion VALUES(6985,'bio34a1-psp-8',NULL,0,'Different genes are switched on (expressed) or off in different cell types due to gene regulation;',1,1);
INSERT INTO rubric_criterion VALUES(6986,'bio34a1-psp-8',NULL,1,'in addition, alternative splicing and post-translational modification can differ between cells, so each cell type produces a different set of proteins.',1,1);
INSERT INTO rubric_criterion VALUES(6993,'bio34a1-sec-6',NULL,0,'Ribosomes attached to the rough ER translate the mRNA, and the growing polypeptide enters the ER lumen;',1,1);
INSERT INTO rubric_criterion VALUES(6994,'bio34a1-sec-6',NULL,1,'within the ER the polypeptide is folded and may be modified, then packaged into transport vesicles that carry it to the Golgi apparatus.',1,1);
INSERT INTO rubric_criterion VALUES(6995,'bio34a1-sec-7',NULL,0,'Extensive rough ER provides many ribosomes and space to synthesise and fold large amounts of protein for secretion;',1,1);
INSERT INTO rubric_criterion VALUES(6996,'bio34a1-sec-7',NULL,1,'many mitochondria supply ATP needed for protein synthesis and for vesicle transport and exocytosis.',1,1);
INSERT INTO rubric_criterion VALUES(6997,'bio34a1-sec-8',NULL,0,'The gene is transcribed into mRNA in the nucleus, which is processed and exported to the cytoplasm;',1,1);
INSERT INTO rubric_criterion VALUES(6998,'bio34a1-sec-8',NULL,1,'the mRNA is translated by ribosomes on the rough ER and the polypeptide enters the ER lumen where it folds, then travels in a transport vesicle to the Golgi apparatus;',1,1);
INSERT INTO rubric_criterion VALUES(6999,'bio34a1-sec-8',NULL,2,'the Golgi modifies and packages the protein into a secretory vesicle, which moves to and fuses with the plasma membrane, releasing the protein by exocytosis.',1,1);
INSERT INTO rubric_criterion VALUES(7006,'bio34a1-edm-6',NULL,0,'DNA polymerase synthesises a new DNA strand by adding free nucleotides one at a time, complementary to a template strand, to the 3′ end of a growing strand/primer;',1,1);
INSERT INTO rubric_criterion VALUES(7007,'bio34a1-edm-6',NULL,1,'DNA ligase joins two existing DNA fragments together by forming a phosphodiester bond between them, and does not use a template.',1,1);
INSERT INTO rubric_criterion VALUES(7008,'bio34a1-edm-7',NULL,0,'Restriction enzymes evolved as a defence against bacteriophages, cutting invading viral DNA at specific recognition sites;',1,1);
INSERT INTO rubric_criterion VALUES(7009,'bio34a1-edm-7',NULL,1,'the bacteria''s own DNA is protected because its recognition sites are chemically modified (methylated), so the enzyme cannot cut them.',1,1);
INSERT INTO rubric_criterion VALUES(7010,'bio34a1-edm-8',NULL,0,'Probability = (1/4)⁶ = 1/4096, so on average once every 4096 bp;',1,1);
INSERT INTO rubric_criterion VALUES(7011,'bio34a1-edm-8',NULL,1,'a four-base-pair site has a probability of (1/4)⁴ = 1/256, occurring once every 256 bp on average;',1,1);
INSERT INTO rubric_criterion VALUES(7012,'bio34a1-edm-8',NULL,2,'it therefore occurs more often, cutting the DNA at more sites and producing more, smaller fragments.',1,1);
INSERT INTO rubric_criterion VALUES(7019,'bio34a1-cas-6',NULL,0,'When a bacteriophage injects its DNA, Cas proteins (Cas1 and Cas2) cut out a short segment of the viral DNA;',1,1);
INSERT INTO rubric_criterion VALUES(7020,'bio34a1-cas-6',NULL,1,'this segment is inserted as a new spacer into the bacterium''s CRISPR array between repeat sequences;',1,1);
INSERT INTO rubric_criterion VALUES(7021,'bio34a1-cas-6',NULL,2,'on a later infection the array is transcribed into crRNA, which guides Cas9 to the matching viral DNA so it is cut and destroyed.',1,1);
INSERT INTO rubric_criterion VALUES(7022,'bio34a1-cas-7',NULL,0,'After Cas9 makes a double-stranded break at the target site, scientists supply a DNA template containing the desired sequence flanked by regions homologous to either side of the break;',1,1);
INSERT INTO rubric_criterion VALUES(7023,'bio34a1-cas-7',NULL,1,'the cell uses homology-directed repair to copy the template into the break, inserting the corrected sequence.',1,1);
INSERT INTO rubric_criterion VALUES(7024,'bio34a1-cas-8',NULL,0,'Advantage: it is cheaper, faster and more precise/easily targeted, since only the sgRNA sequence needs to be changed to target a new gene;',1,1);
INSERT INTO rubric_criterion VALUES(7025,'bio34a1-cas-8',NULL,1,'concern: off-target cuts could cause harmful mutations, and edits to embryos are heritable (germline) and passed on to future generations without their consent.',1,1);
INSERT INTO rubric_criterion VALUES(7032,'bio34a1-pcr-6',NULL,0,'Primers are short single-stranded DNA sequences complementary to the ends of the target region, providing a 3′ end from which DNA polymerase can begin adding nucleotides;',1,1);
INSERT INTO rubric_criterion VALUES(7033,'bio34a1-pcr-6',NULL,1,'two primers are needed because each binds to a different strand (forward and reverse) at opposite ends of the target, so both strands are copied and the region between them is amplified.',1,1);
INSERT INTO rubric_criterion VALUES(7034,'bio34a1-pcr-7',NULL,0,'PCR with primers flanking specific STR loci is used to amplify these regions from the small amounts of DNA in each sample;',1,1);
INSERT INTO rubric_criterion VALUES(7035,'bio34a1-pcr-7',NULL,1,'because individuals have different numbers of repeats, the amplified fragments differ in length;',1,1);
INSERT INTO rubric_criterion VALUES(7036,'bio34a1-pcr-7',NULL,2,'the fragments are separated by size using gel electrophoresis and the banding patterns of the crime scene sample and suspect are compared (matching bands at all loci indicate a match).',1,1);
INSERT INTO rubric_criterion VALUES(7037,'bio34a1-pcr-8',NULL,0,'Without a ladder of known fragment sizes, the sizes of the sample fragments cannot be determined (only their relative positions);',1,1);
INSERT INTO rubric_criterion VALUES(7038,'bio34a1-pcr-8',NULL,1,'a negative control (PCR reaction with no template DNA) should also be run to check that reagents are not contaminated with DNA.',1,1);
INSERT INTO rubric_criterion VALUES(7045,'bio34a1-rpt-6',NULL,0,'The gene of interest and the plasmid are cut with the same restriction enzyme to produce complementary sticky ends;',1,1);
INSERT INTO rubric_criterion VALUES(7046,'bio34a1-rpt-6',NULL,1,'the gene and plasmid are mixed so their sticky ends base pair by hydrogen bonding;',1,1);
INSERT INTO rubric_criterion VALUES(7047,'bio34a1-rpt-6',NULL,2,'DNA ligase is added to form phosphodiester bonds, sealing the gene into the plasmid to form a recombinant plasmid.',1,1);
INSERT INTO rubric_criterion VALUES(7048,'bio34a1-rpt-7',NULL,0,'Transformation is inefficient because plasmids must cross the cell membrane and wall, which only happens in a small fraction of cells even after heat shock or electroporation;',1,1);
INSERT INTO rubric_criterion VALUES(7049,'bio34a1-rpt-7',NULL,1,'a selectable marker such as an antibiotic-resistance gene on the plasmid allows only transformed bacteria to grow on agar containing that antibiotic.',1,1);
INSERT INTO rubric_criterion VALUES(7050,'bio34a1-rpt-8',NULL,0,'Any two: the gene was inserted in the reverse orientation relative to the promoter, so it is not transcribed correctly; the plasmid lacks a bacterial promoter or ribosome binding site upstream of the gene;',1,1);
INSERT INTO rubric_criterion VALUES(7051,'bio34a1-rpt-8',NULL,1,'the gene contains introns that bacteria cannot remove; the protein is degraded by bacterial proteases or requires post-translational modification the bacteria cannot perform.',1,1);
INSERT INTO rubric_criterion VALUES(7058,'bio34a1-gmo-6',NULL,0,'The gene of interest (with a marker gene) is inserted into the T-DNA region of a Ti plasmid, replacing the tumour-causing genes, using restriction enzymes and ligase; the recombinant plasmid is put into Agrobacterium, which is used to infect plant cells or tissue, transferring the T-DNA into the plant genome;',1,1);
INSERT INTO rubric_criterion VALUES(7059,'bio34a1-gmo-6',NULL,1,'transformed cells are selected (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(7060,'bio34a1-gmo-6',NULL,2,'on antibiotic or herbicide media) and grown by tissue culture into whole plants that carry the gene.',1,1);
INSERT INTO rubric_criterion VALUES(7061,'bio34a1-gmo-7',NULL,0,'Benefit: reduced use of broad-spectrum insecticide sprays, protecting non-target insects and reducing costs while increasing yield;',1,1);
INSERT INTO rubric_criterion VALUES(7062,'bio34a1-gmo-7',NULL,1,'risk: target pests may evolve resistance to the Bt toxin through natural selection (managed using refuge crops), or the transgene may spread to related wild plants by cross-pollination.',1,1);
INSERT INTO rubric_criterion VALUES(7063,'bio34a1-gmo-8',NULL,0,'For: GM crops can increase yields, resist pests or drought, or improve nutrition (e.g. Golden Rice), helping feed growing populations;',1,1);
INSERT INTO rubric_criterion VALUES(7064,'bio34a1-gmo-8',NULL,1,'against: patented GM seed may need to be bought each season, increasing costs and dependence of farmers on a few large companies, and some consumers and export markets reject GM products.',1,1);
INSERT INTO rubric_criterion VALUES(7071,'bio34a2-enz-6',NULL,0,'Enzymes are proteins whose tertiary structure is determined by the sequence of amino acids (primary structure);',1,1);
INSERT INTO rubric_criterion VALUES(7072,'bio34a2-enz-6',NULL,1,'folding produces an active site with a specific three-dimensional shape and chemical properties (charge, hydrophobicity);',1,1);
INSERT INTO rubric_criterion VALUES(7073,'bio34a2-enz-6',NULL,2,'only a substrate with a complementary shape and chemistry can bind to the active site to form an enzyme–substrate complex, so each enzyme is specific to one substrate/reaction.',1,1);
INSERT INTO rubric_criterion VALUES(7074,'bio34a2-enz-7',NULL,0,'Energy released from catabolic reactions such as cellular respiration is used to add an inorganic phosphate (Pi) to ADP, forming ATP; ATP diffuses to sites where energy is needed;',1,1);
INSERT INTO rubric_criterion VALUES(7075,'bio34a2-enz-7',NULL,1,'hydrolysis of ATP to ADP + Pi releases energy that drives anabolic or energy-requiring processes such as active transport, muscle contraction or protein synthesis;',1,1);
INSERT INTO rubric_criterion VALUES(7076,'bio34a2-enz-7',NULL,2,'ADP + Pi are then recycled back to respiration to be reloaded.',1,1);
INSERT INTO rubric_criterion VALUES(7077,'bio34a2-enz-8',NULL,0,'Unloaded coenzymes (NAD⁺) accept electrons and hydrogen ions released during glycolysis and the Krebs cycle, becoming loaded (NADH);',1,1);
INSERT INTO rubric_criterion VALUES(7078,'bio34a2-enz-8',NULL,1,'loaded NADH carries these electrons and protons to the electron transport chain on the inner mitochondrial membrane, where it is unloaded (returning to NAD⁺) and the energy is used to produce ATP.',1,1);
INSERT INTO rubric_criterion VALUES(7085,'bio34a2-inh-6',NULL,0,'An irreversible inhibitor forms strong (often covalent) bonds with the enzyme, permanently inactivating it;',1,1);
INSERT INTO rubric_criterion VALUES(7086,'bio34a2-inh-6',NULL,1,'a reversible inhibitor binds with weak bonds and can detach, so enzyme activity can be restored;',1,1);
INSERT INTO rubric_criterion VALUES(7087,'bio34a2-inh-6',NULL,2,'because the insect''s acetylcholinesterase is permanently inactivated, enzyme activity cannot recover (new enzyme must be synthesised), so nerve function fails and the insect dies.',1,1);
INSERT INTO rubric_criterion VALUES(7088,'bio34a2-inh-7',NULL,0,'At 10 °C the enzyme and substrate molecules have low kinetic energy, so there are fewer successful collisions between substrate and active site and fewer enzyme–substrate complexes form per unit time, giving low activity;',1,1);
INSERT INTO rubric_criterion VALUES(7089,'bio34a2-inh-7',NULL,1,'the enzyme is not denatured at 10 °C, so activity would increase if warmed;',1,1);
INSERT INTO rubric_criterion VALUES(7090,'bio34a2-inh-7',NULL,2,'at 60 °C heat disrupts the hydrogen bonds maintaining tertiary structure, so the enzyme denatures, the active site loses its shape and substrate can no longer bind, so activity is near zero.',1,1);
INSERT INTO rubric_criterion VALUES(7091,'bio34a2-inh-8',NULL,0,'The final product of a pathway binds to (often allosterically inhibits) an enzyme early in the pathway, reducing its activity when product levels are high;',1,1);
INSERT INTO rubric_criterion VALUES(7092,'bio34a2-inh-8',NULL,1,'this prevents over-production of the product and avoids wasting substrate and energy, with the pathway resuming when product levels fall.',1,1);
INSERT INTO rubric_criterion VALUES(7099,'bio34a2-ps-6',NULL,0,'Rubisco is the enzyme in the stroma that catalyses carbon fixation, combining CO₂ with a 5-carbon compound (RuBP) at the start of the Calvin cycle;',1,1);
INSERT INTO rubric_criterion VALUES(7100,'bio34a2-ps-6',NULL,1,'like other enzymes it has an optimum temperature;',1,1);
INSERT INTO rubric_criterion VALUES(7101,'bio34a2-ps-6',NULL,2,'below the optimum, fewer successful collisions occur so the rate is slower, and above the optimum the enzyme begins to denature (and binds O₂ more readily), reducing the rate of carbon fixation.',1,1);
INSERT INTO rubric_criterion VALUES(7102,'bio34a2-ps-7',NULL,0,'6CO₂ + 12H₂O → C₆H₁₂O₆ + 6O₂ + 6H₂O (in the presence of light and chlorophyll; 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ also accepted);',1,1);
INSERT INTO rubric_criterion VALUES(7103,'bio34a2-ps-7',NULL,1,'water is split in the light-dependent stage in the thylakoid membranes (grana);',1,1);
INSERT INTO rubric_criterion VALUES(7104,'bio34a2-ps-7',NULL,2,'carbon dioxide is fixed in the light-independent stage (Calvin cycle) in the stroma.',1,1);
INSERT INTO rubric_criterion VALUES(7105,'bio34a2-ps-8',NULL,0,'The light-dependent stage produces ATP and NADPH, which are required to power and reduce CO₂ in the light-independent stage;',1,1);
INSERT INTO rubric_criterion VALUES(7106,'bio34a2-ps-8',NULL,1,'the light-independent stage regenerates ADP + Pi and NADP⁺, which must return to the thylakoids for the light-dependent stage to continue, so neither stage can continue for long without the other.',1,1);
INSERT INTO rubric_criterion VALUES(7113,'bio34a2-c4-6',NULL,0,'In hot, dry conditions C3 plants close their stomata to reduce water loss by transpiration;',1,1);
INSERT INTO rubric_criterion VALUES(7114,'bio34a2-c4-6',NULL,1,'this prevents CO₂ from diffusing into the leaf while O₂ produced by the light-dependent stage builds up, so the ratio of O₂ to CO₂ around rubisco increases;',1,1);
INSERT INTO rubric_criterion VALUES(7115,'bio34a2-c4-6',NULL,2,'rubisco therefore binds O₂ more often (and its affinity for O₂ relative to CO₂ increases at higher temperatures), increasing photorespiration and reducing glucose production.',1,1);
INSERT INTO rubric_criterion VALUES(7116,'bio34a2-c4-7',NULL,0,'Similarity: both first fix CO₂ using PEP carboxylase (which does not bind O₂) into a 4-carbon compound, later releasing CO₂ to rubisco for the Calvin cycle;',1,1);
INSERT INTO rubric_criterion VALUES(7117,'bio34a2-c4-7',NULL,1,'difference: C4 plants separate the two steps spatially (mesophyll and bundle sheath cells) during the day, whereas CAM plants separate them in time (CO₂ fixed at night, Calvin cycle during the day) within the same cell.',1,1);
INSERT INTO rubric_criterion VALUES(7118,'bio34a2-c4-8',NULL,0,'Recommend the C4 crop;',1,1);
INSERT INTO rubric_criterion VALUES(7119,'bio34a2-c4-8',NULL,1,'in hot, sunny, dry conditions stomata may partially close, and a C3 crop would suffer high photorespiration, reducing yield;',1,1);
INSERT INTO rubric_criterion VALUES(7120,'bio34a2-c4-8',NULL,2,'the C4 crop concentrates CO₂ around rubisco in bundle sheath cells, so photorespiration is minimised and it can photosynthesise efficiently with stomata only partly open, giving higher yield and better water use efficiency.',1,1);
INSERT INTO rubric_criterion VALUES(7127,'bio34a2-cr-6',NULL,0,'Location: mitochondrial matrix;',1,1);
INSERT INTO rubric_criterion VALUES(7128,'bio34a2-cr-6',NULL,1,'inputs: acetyl CoA (derived from 2 pyruvate), NAD⁺, FAD, ADP + Pi;',1,1);
INSERT INTO rubric_criterion VALUES(7129,'bio34a2-cr-6',NULL,2,'outputs: CO₂ (released as waste), 2 ATP, loaded coenzymes NADH and FADH₂ (which carry electrons and H⁺ to the electron transport chain).',1,1);
INSERT INTO rubric_criterion VALUES(7130,'bio34a2-cr-7',NULL,0,'More mitochondria means more sites for the Krebs cycle and electron transport chain (more cristae surface area), so the rate of aerobic respiration increases;',1,1);
INSERT INTO rubric_criterion VALUES(7131,'bio34a2-cr-7',NULL,1,'more ATP can be produced aerobically to supply energy for muscle contraction during sustained exercise, reducing reliance on anaerobic respiration and lactate build-up.',1,1);
INSERT INTO rubric_criterion VALUES(7132,'bio34a2-cr-8',NULL,0,'The electron transport chain proteins and ATP synthase are embedded in the inner mitochondrial membrane;',1,1);
INSERT INTO rubric_criterion VALUES(7133,'bio34a2-cr-8',NULL,1,'folding into cristae greatly increases the surface area of this membrane, so more electron transport chains and ATP synthase enzymes are present and more ATP can be produced per mitochondrion.',1,1);
INSERT INTO rubric_criterion VALUES(7140,'bio34a2-an-6',NULL,0,'Yeast breaks down glucose by glycolysis in the cytosol into 2 pyruvate, producing 2 ATP and 2 NADH;',1,1);
INSERT INTO rubric_criterion VALUES(7141,'bio34a2-an-6',NULL,1,'in the absence of oxygen pyruvate is converted into ethanol and CO₂, which regenerates NAD⁺ so glycolysis can continue;',1,1);
INSERT INTO rubric_criterion VALUES(7142,'bio34a2-an-6',NULL,2,'advantage: it is a renewable fuel, and the CO₂ released when it burns was recently absorbed by the crop during photosynthesis, so net CO₂ emissions can be lower than for fossil fuels.',1,1);
INSERT INTO rubric_criterion VALUES(7143,'bio34a2-an-7',NULL,0,'Anaerobic respiration produces only 2 ATP per glucose, which cannot meet a high energy demand for long and rapidly uses up glucose;',1,1);
INSERT INTO rubric_criterion VALUES(7144,'bio34a2-an-7',NULL,1,'lactate (and associated H⁺) builds up in the muscle, lowering pH, which affects enzyme function and contributes to fatigue, so oxygen is needed to recover.',1,1);
INSERT INTO rubric_criterion VALUES(7145,'bio34a2-an-8',NULL,0,'Dough rises due to CO₂ released by yeast respiration (including fermentation);',1,1);
INSERT INTO rubric_criterion VALUES(7146,'bio34a2-an-8',NULL,1,'at 30 °C, closer to the optimum temperature of yeast enzymes, molecules have more kinetic energy and enzyme–substrate collisions are more frequent, so the rate of respiration and CO₂ production is faster than at 15 °C.',1,1);
INSERT INTO rubric_criterion VALUES(7147,'vce-bio34-an-c1',NULL,0,'Converting pyruvate to lactate regenerates NAD⁺ from NADH.',1,1);
INSERT INTO rubric_criterion VALUES(7148,'vce-bio34-an-c1',NULL,1,'Glycolysis needs NAD⁺, so it can continue and keep producing 2 ATP per glucose.',1,1);
INSERT INTO rubric_criterion VALUES(7154,'bio34a2-bt-6',NULL,0,'A guide RNA complementary to the target gene is designed and delivered with Cas9 into plant cells; Cas9 is guided to the target sequence (next to a PAM) and makes a double-stranded cut;',1,1);
INSERT INTO rubric_criterion VALUES(7155,'bio34a2-bt-6',NULL,1,'the cell repairs the break by non-homologous end joining, often introducing insertions/deletions that disable the gene; e.g.',1,1);
INSERT INTO rubric_criterion VALUES(7156,'bio34a2-bt-6',NULL,2,'knocking out a gene that makes the plant susceptible to a disease, or a gene that limits grain size/number, could increase yield.',1,1);
INSERT INTO rubric_criterion VALUES(7157,'bio34a2-bt-7',NULL,0,'Factor: photorespiration / the inefficiency of rubisco, which binds O₂ as well as CO₂; approach: gene editing (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(7158,'bio34a2-bt-7',NULL,1,'CRISPR-Cas9) or genetic modification to produce a rubisco with greater specificity for CO₂, or insert a CO₂-concentrating mechanism (e.g. C4 pathway genes);',1,1);
INSERT INTO rubric_criterion VALUES(7159,'bio34a2-bt-7',NULL,2,'this would increase the rate of carbon fixation in the Calvin cycle, producing more glucose for growth and increasing yield.',1,1);
INSERT INTO rubric_criterion VALUES(7160,'bio34a2-bt-8',NULL,0,'Advantage: it is renewable and the CO₂ released was recently absorbed during photosynthesis, so it can reduce net greenhouse gas emissions compared with fossil fuels;',1,1);
INSERT INTO rubric_criterion VALUES(7161,'bio34a2-bt-8',NULL,1,'disadvantage: growing sugarcane for fuel uses land, water and fertiliser that could be used for food production, and processing requires energy inputs that reduce the net benefit.',1,1);
INSERT INTO rubric_criterion VALUES(7168,'bio34a2-pb-6',NULL,0,'A pathogen is an agent that causes disease, e.g. the influenza virus or the bacterium Mycobacterium tuberculosis;',1,1);
INSERT INTO rubric_criterion VALUES(7169,'bio34a2-pb-6',NULL,1,'an antigen is a molecule (often a protein or glycoprotein) that is recognised by the immune system and can trigger an immune response, e.g. the haemagglutinin protein on the surface of the influenza virus.',1,1);
INSERT INTO rubric_criterion VALUES(7170,'bio34a2-pb-7',NULL,0,'Physical: thick bark or a waxy cuticle that blocks entry of fungal hyphae, and/or thick cellulose cell walls that are hard to penetrate;',1,1);
INSERT INTO rubric_criterion VALUES(7171,'bio34a2-pb-7',NULL,1,'chemical: production of antimicrobial/antifungal compounds such as essential oils, or enzymes such as chitinase that break down fungal cell walls (any two, with at least a correct description of each).',1,1);
INSERT INTO rubric_criterion VALUES(7172,'bio34a2-pb-8',NULL,0,'Gastric juice contains hydrochloric acid giving a pH of about 1.5–3.5;',1,1);
INSERT INTO rubric_criterion VALUES(7173,'bio34a2-pb-8',NULL,1,'this low pH denatures proteins (including enzymes) of many ingested microorganisms, killing them before they can reach and colonise the intestines.',1,1);
INSERT INTO rubric_criterion VALUES(7180,'bio34a2-inn-6',NULL,0,'The neutrophil is attracted to the infection site by chemical signals (chemotaxis) and recognises the pathogen (e.g. via receptors that bind pathogen surface molecules or complement/antibody);',1,1);
INSERT INTO rubric_criterion VALUES(7181,'bio34a2-inn-6',NULL,1,'it engulfs the pathogen by extending its membrane around it, forming a phagosome (endocytosis);',1,1);
INSERT INTO rubric_criterion VALUES(7182,'bio34a2-inn-6',NULL,2,'the phagosome fuses with a lysosome and hydrolytic enzymes digest the pathogen, with waste removed by exocytosis.',1,1);
INSERT INTO rubric_criterion VALUES(7183,'bio34a2-inn-7',NULL,0,'Damaged cells and mast cells release histamine and other chemicals;',1,1);
INSERT INTO rubric_criterion VALUES(7184,'bio34a2-inn-7',NULL,1,'histamine causes vasodilation, increasing blood flow (redness and heat), and increases capillary permeability so fluid leaks into tissue (swelling, pressing on nerves to cause pain);',1,1);
INSERT INTO rubric_criterion VALUES(7185,'bio34a2-inn-7',NULL,2,'increased permeability allows phagocytes (neutrophils, macrophages) and complement proteins to move into the tissue and destroy pathogens, with clotting factors helping to wall off the area.',1,1);
INSERT INTO rubric_criterion VALUES(7186,'bio34a2-inn-8',NULL,0,'Complement proteins can form a membrane attack complex that creates pores in the bacterial membrane, causing lysis; they can coat (opsonise) bacteria, making them easier for phagocytes to recognise and engulf;',1,1);
INSERT INTO rubric_criterion VALUES(7187,'bio34a2-inn-8',NULL,1,'they also act as chemical signals that attract phagocytes to the site (any two).',1,1);
INSERT INTO rubric_criterion VALUES(7194,'bio34a2-ap-6',NULL,0,'MHC I is found on all nucleated cells, whereas MHC II is found only on antigen-presenting cells (dendritic cells, macrophages, B cells); MHC I presents peptides from proteins made inside the cell (endogenous, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(7195,'bio34a2-ap-6',NULL,1,'viral proteins in an infected cell), which are recognised by cytotoxic T cells; MHC II presents peptides from material engulfed from outside the cell (exogenous, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(7196,'bio34a2-ap-6',NULL,2,'phagocytosed bacteria), which are recognised by T helper cells.',1,1);
INSERT INTO rubric_criterion VALUES(7197,'bio34a2-ap-7',NULL,0,'Cells of the donor organ carry MHC markers (self-markers) that differ from those of the recipient;',1,1);
INSERT INTO rubric_criterion VALUES(7198,'bio34a2-ap-7',NULL,1,'the recipient''s immune system recognises the donor MHC as non-self/foreign (antigens), activating T cells (and antibodies) that attack and destroy the transplanted tissue.',1,1);
INSERT INTO rubric_criterion VALUES(7199,'bio34a2-ap-8',NULL,0,'Bacteria and/or antigen-presenting cells such as dendritic cells that have engulfed the bacteria travel in lymph through lymphatic vessels;',1,1);
INSERT INTO rubric_criterion VALUES(7200,'bio34a2-ap-8',NULL,1,'they reach a nearby lymph node, where the dendritic cell presents antigen on MHC II to T helper cells, and B cells encounter antigen;',1,1);
INSERT INTO rubric_criterion VALUES(7201,'bio34a2-ap-8',NULL,2,'lymphocytes with complementary receptors are selected and undergo clonal expansion in the node, after which effector cells and antibodies leave via lymph and blood to the site of infection.',1,1);
INSERT INTO rubric_criterion VALUES(7208,'bio34a2-hum-6',NULL,0,'A naive B cell with B cell receptors (membrane-bound antibodies) complementary to the antigen binds it (clonal selection) and presents antigen fragments on MHC II;',1,1);
INSERT INTO rubric_criterion VALUES(7209,'bio34a2-hum-6',NULL,1,'a T helper cell that has been activated against the same antigen binds the B cell and releases cytokines;',1,1);
INSERT INTO rubric_criterion VALUES(7210,'bio34a2-hum-6',NULL,2,'the B cell is stimulated to undergo clonal expansion (rapid mitosis), producing many identical cells;',1,1);
INSERT INTO rubric_criterion VALUES(7211,'bio34a2-hum-6',NULL,3,'these differentiate into plasma cells, which secrete large quantities of specific antibodies, and memory B cells, which persist and provide a faster secondary response.',1,1);
INSERT INTO rubric_criterion VALUES(7212,'bio34a2-hum-7',NULL,0,'Agglutination: each antibody has (at least) two binding sites, so antibodies bind several bacteria at once, clumping them together so they cannot spread and are more easily engulfed by phagocytes;',1,1);
INSERT INTO rubric_criterion VALUES(7213,'bio34a2-hum-7',NULL,1,'opsonisation: antibodies coat the bacteria and phagocytes recognise the constant region of bound antibodies, which increases the rate of phagocytosis.',1,1);
INSERT INTO rubric_criterion VALUES(7214,'bio34a2-hum-8',NULL,0,'Antibodies are specific: the variable region of each antibody has a shape complementary to one specific antigen (epitope);',1,1);
INSERT INTO rubric_criterion VALUES(7215,'bio34a2-hum-8',NULL,1,'antigens on the chickenpox virus have a different shape from measles antigens, so measles antibodies cannot bind to them, and no memory cells specific for chickenpox exist.',1,1);
INSERT INTO rubric_criterion VALUES(7222,'bio34a3-cmi-6',NULL,0,'Dendritic cell presents viral antigen on MHC II to a helper T cell with a complementary T cell receptor (and antigen on MHC I to a naive cytotoxic T cell with a complementary receptor);',1,1);
INSERT INTO rubric_criterion VALUES(7223,'bio34a3-cmi-6',NULL,1,'the activated helper T cell releases cytokines/interleukins;',1,1);
INSERT INTO rubric_criterion VALUES(7224,'bio34a3-cmi-6',NULL,2,'cytokines stimulate clonal selection and clonal expansion of the specific cytotoxic T cells (and production of memory T cells);',1,1);
INSERT INTO rubric_criterion VALUES(7225,'bio34a3-cmi-6',NULL,3,'cytotoxic T cells leave the lymph node, travel to the infection site, bind infected cells displaying the antigen on MHC I and release perforin and granzymes, causing apoptosis.',1,1);
INSERT INTO rubric_criterion VALUES(7226,'bio34a3-cmi-7',NULL,0,'Antibodies are found in body fluids (plasma, lymph) and can only bind antigens/pathogens outside cells, so they cannot reach viruses replicating inside cells;',1,1);
INSERT INTO rubric_criterion VALUES(7227,'bio34a3-cmi-7',NULL,1,'cytotoxic T cells recognise viral antigen displayed on MHC I of infected cells and destroy the whole infected cell, removing the site of viral replication.',1,1);
INSERT INTO rubric_criterion VALUES(7228,'bio34a3-cmi-8',NULL,0,'Donor cells display MHC markers that differ from the recipient''s (non-self);',1,1);
INSERT INTO rubric_criterion VALUES(7229,'bio34a3-cmi-8',NULL,1,'recipient cytotoxic T cells (activated with help from helper T cells) would recognise these as foreign and destroy the transplanted tissue, causing rejection;',1,1);
INSERT INTO rubric_criterion VALUES(7230,'bio34a3-cmi-8',NULL,2,'suppressing T cells reduces rejection but increases the risk of infections (or certain cancers) because the recipient''s adaptive immune response is weakened.',1,1);
INSERT INTO rubric_criterion VALUES(7231,'vce-bio34-cm-c1',NULL,0,'The infected cell presents viral antigen on MHC I. A cytotoxic T cell with a complementary receptor binds it and releases perforin and granzymes, triggering apoptosis.',1,1);
INSERT INTO rubric_criterion VALUES(7232,'vce-bio34-cm-c1',NULL,1,'Antibodies act only outside cells, and viruses replicating inside cells are hidden from them.',1,1);
INSERT INTO rubric_criterion VALUES(7238,'bio34a3-tiv-6',NULL,0,'Active immunity: the individual''s own immune system is exposed to an antigen and produces antibodies (via plasma cells) and memory cells; protection is long-lasting because of memory cells (but takes time to develop);',1,1);
INSERT INTO rubric_criterion VALUES(7239,'bio34a3-tiv-6',NULL,1,'passive immunity: antibodies made by another organism are received, giving immediate protection;',1,1);
INSERT INTO rubric_criterion VALUES(7240,'bio34a3-tiv-6',NULL,2,'it is short-lived because no memory cells are made and the antibodies are degraded.',1,1);
INSERT INTO rubric_criterion VALUES(7241,'bio34a3-tiv-7',NULL,0,'The first dose triggered a primary response: naive B cells had to undergo clonal selection and expansion, so there was a lag and a small peak;',1,1);
INSERT INTO rubric_criterion VALUES(7242,'bio34a3-tiv-7',NULL,1,'memory B cells (and memory helper T cells) were produced during the primary response;',1,1);
INSERT INTO rubric_criterion VALUES(7243,'bio34a3-tiv-7',NULL,2,'at the booster, these memory cells recognised the antigen and rapidly differentiated into many plasma cells, producing a faster and much larger secondary response.',1,1);
INSERT INTO rubric_criterion VALUES(7244,'bio34a3-tiv-8',NULL,0,'If fewer people are immune than the threshold, an infected person is likely to contact enough susceptible people that each case leads to more than one new case;',1,1);
INSERT INTO rubric_criterion VALUES(7245,'bio34a3-tiv-8',NULL,1,'the pathogen can then spread through clusters of susceptible (unvaccinated or non-responding) individuals, causing an outbreak.',1,1);
INSERT INTO rubric_criterion VALUES(7252,'bio34a3-edi-6',NULL,0,'Factor 1: international travel/globalisation; infected people (including asymptomatic carriers) moved between countries before detection, seeding new outbreaks;',1,1);
INSERT INTO rubric_criterion VALUES(7253,'bio34a3-edi-6',NULL,1,'factor 2: high population density/urbanisation or a lack of prior immunity in the population;',1,1);
INSERT INTO rubric_criterion VALUES(7254,'bio34a3-edi-6',NULL,2,'crowded conditions increase contact rates for airborne/droplet spread, and with no existing immunity (novel virus) almost everyone was susceptible.',1,1);
INSERT INTO rubric_criterion VALUES(7255,'bio34a3-edi-6',NULL,3,'(Accept also asymptomatic transmission, long incubation period.)',1,1);
INSERT INTO rubric_criterion VALUES(7256,'bio34a3-edi-7',NULL,0,'The monoclonal antibody is specific/complementary to the antigen (e.g. HER2) on the cancer cell, so it binds only cancer cells and not healthy cells;',1,1);
INSERT INTO rubric_criterion VALUES(7257,'bio34a3-edi-7',NULL,1,'binding may block the receptor and stop signals that stimulate uncontrolled division; it can also tag the cell for destruction by immune cells (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(7258,'bio34a3-edi-7',NULL,2,'NK cells/phagocytes), or carry an attached drug/radioactive substance directly to the cancer cell.',1,1);
INSERT INTO rubric_criterion VALUES(7259,'bio34a3-edi-8',NULL,0,'A pathogen that normally infects animals (reservoir host) is transmitted to humans through close contact, e.g. habitat destruction, wildlife trade or farming;',1,1);
INSERT INTO rubric_criterion VALUES(7260,'bio34a3-edi-8',NULL,1,'mutation(s) may allow the pathogen to bind human cells and spread from human to human, and because humans have no prior immunity it can spread rapidly.',1,1);
INSERT INTO rubric_criterion VALUES(7267,'bio34a3-mgd-6',NULL,0,'Founder effect: a small group of individuals leaves a population to colonise a new area, so the new population''s gene pool reflects only the founders'' alleles; bottleneck effect: a large population is drastically reduced in size by a chance event (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(7268,'bio34a3-mgd-6',NULL,1,'bushfire, disease), and survivors carry only a subset of alleles;',1,1);
INSERT INTO rubric_criterion VALUES(7269,'bio34a3-mgd-6',NULL,2,'similarity: both are forms of genetic drift that reduce genetic diversity and can change allele frequencies by chance.',1,1);
INSERT INTO rubric_criterion VALUES(7270,'bio34a3-mgd-7',NULL,0,'Genetic drift (a bottleneck effect);',1,1);
INSERT INTO rubric_criterion VALUES(7271,'bio34a3-mgd-7',NULL,1,'because the deaths were random rather than related to phenotype, the 20 survivors happened by chance to carry fewer B alleles, so the allele frequency changed without selection.',1,1);
INSERT INTO rubric_criterion VALUES(7272,'bio34a3-mgd-8',NULL,0,'A somatic mutation occurs in a body cell and is not passed to offspring, so it cannot change the population''s gene pool;',1,1);
INSERT INTO rubric_criterion VALUES(7273,'bio34a3-mgd-8',NULL,1,'a germline mutation occurs in cells that produce gametes and can be inherited, introducing a new allele into the gene pool on which evolutionary mechanisms can act.',1,1);
INSERT INTO rubric_criterion VALUES(7280,'bio34a3-nss-6',NULL,0,'Variation: snails in the population vary in shell thickness due to different alleles (arising from mutation);',1,1);
INSERT INTO rubric_criterion VALUES(7281,'bio34a3-nss-6',NULL,1,'selection pressure: crabs crush and eat thin-shelled snails more easily;',1,1);
INSERT INTO rubric_criterion VALUES(7282,'bio34a3-nss-6',NULL,2,'selective advantage: thick-shelled snails are more likely to survive and reproduce;',1,1);
INSERT INTO rubric_criterion VALUES(7283,'bio34a3-nss-6',NULL,3,'inheritance: they pass the thick-shell alleles to offspring, so over many generations the frequency of the thick-shell allele/phenotype increases in the population.',1,1);
INSERT INTO rubric_criterion VALUES(7284,'bio34a3-nss-7',NULL,0,'Humans apply a strong, consistent and deliberate selection pressure, allowing only individuals with the desired trait to breed each generation;',1,1);
INSERT INTO rubric_criterion VALUES(7285,'bio34a3-nss-7',NULL,1,'in natural selection, pressures vary and individuals without the advantageous trait still often reproduce, so allele frequencies change more slowly.',1,1);
INSERT INTO rubric_criterion VALUES(7286,'bio34a3-nss-8',NULL,0,'Genetic diversity decreases because only a few sheep with particular alleles are used for breeding (and inbreeding increases);',1,1);
INSERT INTO rubric_criterion VALUES(7287,'bio34a3-nss-8',NULL,1,'consequence: the flock has a reduced ability to adapt to environmental change/disease, or recessive harmful conditions become more common due to increased homozygosity.',1,1);
INSERT INTO rubric_criterion VALUES(7294,'bio34a3-aar-6',NULL,0,'Variation: some bacteria possess a resistance allele/gene that arose by random mutation or was acquired by plasmid transfer;',1,1);
INSERT INTO rubric_criterion VALUES(7295,'bio34a3-aar-6',NULL,1,'selection pressure: methicillin use kills susceptible bacteria;',1,1);
INSERT INTO rubric_criterion VALUES(7296,'bio34a3-aar-6',NULL,2,'resistant bacteria survive and reproduce rapidly by binary fission, passing on the resistance gene (and may share it by conjugation);',1,1);
INSERT INTO rubric_criterion VALUES(7297,'bio34a3-aar-6',NULL,3,'over many generations the frequency of resistant bacteria increases until most of the population is resistant.',1,1);
INSERT INTO rubric_criterion VALUES(7298,'bio34a3-aar-7',NULL,0,'For a virus to survive, it would need resistance mutations to all three drugs at once, which is extremely unlikely;',1,1);
INSERT INTO rubric_criterion VALUES(7299,'bio34a3-aar-7',NULL,1,'so combination therapy reduces the chance that resistant variants survive and are selected, slowing the evolution of resistance.',1,1);
INSERT INTO rubric_criterion VALUES(7300,'bio34a3-aar-8',NULL,0,'Bacteria have very short generation times (can divide every 20–30 minutes) and huge population sizes, so mutations arise frequently and selection acts over many generations quickly;',1,1);
INSERT INTO rubric_criterion VALUES(7301,'bio34a3-aar-8',NULL,1,'humans have long generation times and fewer offspring, so changes in allele frequency take much longer.',1,1);
INSERT INTO rubric_criterion VALUES(7302,'vce-bio34-ar-c1',NULL,0,'Random mutations already give a few bacteria some resistance. The antibiotic kills susceptible bacteria, so resistant ones survive and reproduce, passing on the allele (natural selection).',1,1);
INSERT INTO rubric_criterion VALUES(7303,'vce-bio34-ar-c1',NULL,1,'Stopping early leaves the more resistant survivors to multiply.',1,1);
INSERT INTO rubric_criterion VALUES(7309,'bio34a3-spe-6',NULL,0,'Rising sea level created a geographical barrier, so gene flow between island and mainland populations stopped; the island population faced different selection pressures (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(7310,'bio34a3-spe-6',NULL,1,'climate, food, predators) and natural selection favoured different alleles;',1,1);
INSERT INTO rubric_criterion VALUES(7311,'bio34a3-spe-6',NULL,2,'random mutations and genetic drift (small island population) further changed allele frequencies;',1,1);
INSERT INTO rubric_criterion VALUES(7312,'bio34a3-spe-6',NULL,3,'over many generations the gene pools diverged so much that the populations would be reproductively isolated (unable to produce fertile offspring) if reunited, meaning a new species had formed (allopatric speciation).',1,1);
INSERT INTO rubric_criterion VALUES(7313,'bio34a3-spe-7',NULL,0,'Allopatric speciation occurs when populations are separated by a geographical barrier that prevents gene flow; sympatric speciation occurs within the same geographical area, where reproductive isolation arises without a physical barrier (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(7314,'bio34a3-spe-7',NULL,1,'by polyploidy, behavioural or temporal isolation).',1,1);
INSERT INTO rubric_criterion VALUES(7315,'bio34a3-spe-8',NULL,0,'Observe (or allow) the two populations to interbreed under natural conditions; if they do not mate or their offspring are not viable/fertile (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(7316,'bio34a3-spe-8',NULL,1,'test whether hybrid offspring can produce their own offspring), they are reproductively isolated and are separate species; if fertile offspring are produced, speciation has not occurred.',1,1);
INSERT INTO rubric_criterion VALUES(7323,'bio34a3-frd-6',NULL,0,'Fossilisation requires rare conditions (rapid burial, low oxygen), so most organisms decompose or are scavenged without forming fossils; soft-bodied organisms rarely fossilise;',1,1);
INSERT INTO rubric_criterion VALUES(7324,'bio34a3-frd-6',NULL,1,'and many fossils are destroyed by erosion or geological activity, or have not yet been discovered. (Any two.)',1,1);
INSERT INTO rubric_criterion VALUES(7325,'bio34a3-frd-7',NULL,0,'The volcanic ash layers were dated by absolute (radiometric) dating, e.g. potassium-argon dating, which measures the ratio of a parent isotope to its stable daughter product and uses the known half-life;',1,1);
INSERT INTO rubric_criterion VALUES(7326,'bio34a3-frd-7',NULL,1,'sedimentary rock itself cannot easily be dated this way;',1,1);
INSERT INTO rubric_criterion VALUES(7327,'bio34a3-frd-7',NULL,2,'by superposition, the fossil is younger than the lower layer and older than the upper layer, so it is between 3.2 and 3.6 million years old.',1,1);
INSERT INTO rubric_criterion VALUES(7328,'bio34a3-frd-8',NULL,0,'An index fossil is from a species that was widespread geographically but existed for a relatively short period of time;',1,1);
INSERT INTO rubric_criterion VALUES(7329,'bio34a3-frd-8',NULL,1,'if the same index fossil is found in rock layers at both sites, the layers can be inferred to be of similar age (relative dating/correlation).',1,1);
INSERT INTO rubric_criterion VALUES(7336,'bio34a3-erp-6',NULL,0,'Vestigial structures are reduced structures that have little or no function in the organism but were functional in its ancestors;',1,1);
INSERT INTO rubric_criterion VALUES(7337,'bio34a3-erp-6',NULL,1,'example: the human coccyx (tailbone), or pelvic bones in whales/pythons;',1,1);
INSERT INTO rubric_criterion VALUES(7338,'bio34a3-erp-6',NULL,2,'they provide evidence that the species shares a common ancestor with organisms in which the structure is functional, having been retained from that ancestor but reduced through evolution as it lost its selective advantage.',1,1);
INSERT INTO rubric_criterion VALUES(7339,'bio34a3-erp-7',NULL,0,'P and Q are most closely related (2 differences) and share the most recent common ancestor;',1,1);
INSERT INTO rubric_criterion VALUES(7340,'bio34a3-erp-7',NULL,1,'R and S are more closely related to each other (4 differences) than to P or Q, forming a second group;',1,1);
INSERT INTO rubric_criterion VALUES(7341,'bio34a3-erp-7',NULL,2,'the two groups (P+Q and R+S) diverged from an earlier common ancestor, at the base of the tree.',1,1);
INSERT INTO rubric_criterion VALUES(7342,'bio34a3-erp-8',NULL,0,'The number of DNA (or amino acid) differences between two species is counted; dividing by the known mutation rate (calibrated using fossils of known age) estimates the time since they shared a common ancestor;',1,1);
INSERT INTO rubric_criterion VALUES(7343,'bio34a3-erp-8',NULL,1,'limitation: mutation rates can vary between genes, species and over time (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(7344,'bio34a3-erp-8',NULL,2,'due to generation time or selection), so estimates may be inaccurate.',1,1);
INSERT INTO rubric_criterion VALUES(7351,'bio34a3-hev-6',NULL,0,'Valgus angle: the femurs angle inwards towards the knees, placing the feet under the body''s centre of gravity for balance when walking;',1,1);
INSERT INTO rubric_criterion VALUES(7352,'bio34a3-hev-6',NULL,1,'short, broad, bowl-shaped pelvis: supports the internal organs and provides attachment for muscles that stabilise the body on one leg during walking;',1,1);
INSERT INTO rubric_criterion VALUES(7353,'bio34a3-hev-6',NULL,2,'(also accept S-shaped spine, which positions the centre of gravity over the hips and absorbs shock;',1,1);
INSERT INTO rubric_criterion VALUES(7354,'bio34a3-hev-6',NULL,3,'or arched foot and non-opposable big toe in line with other toes, which act as a lever and absorb shock).',1,1);
INSERT INTO rubric_criterion VALUES(7355,'bio34a3-hev-7',NULL,0,'mtDNA is inherited only through the maternal line and does not recombine, so changes accumulate only by mutation at a relatively constant rate;',1,1);
INSERT INTO rubric_criterion VALUES(7356,'bio34a3-hev-7',NULL,1,'African populations show the greatest mtDNA diversity, indicating they are the oldest (more time to accumulate mutations);',1,1);
INSERT INTO rubric_criterion VALUES(7357,'bio34a3-hev-7',NULL,2,'non-African populations carry a subset of African lineages, and molecular clock estimates trace all modern mtDNA to a common female ancestor in Africa, supporting a recent African origin and later migration.',1,1);
INSERT INTO rubric_criterion VALUES(7358,'bio34a3-hev-8',NULL,0,'Scientific models are based on available evidence, and the fossil record is incomplete;',1,1);
INSERT INTO rubric_criterion VALUES(7359,'bio34a3-hev-8',NULL,1,'a new species with an unexpected combination of features (small brain and body, yet recent age and tool use) shows that several hominin species co-existed and that the human family tree is more branched than previously thought, so models must be revised.',1,1);
INSERT INTO rubric_criterion VALUES(7366,'chem12a1-ast-6',NULL,0,'Isotopes are atoms of the same element (same number of protons/atomic number) with different numbers of neutrons (different mass numbers);',1,1);
INSERT INTO rubric_criterion VALUES(7367,'chem12a1-ast-6',NULL,1,'both isotopes have 6 electrons with the same configuration (2,4), and chemical reactions depend on electrons, so they react identically.',1,1);
INSERT INTO rubric_criterion VALUES(7368,'chem12a1-ast-7',NULL,0,'Ar = (10.0 × 19.9 + 11.0 × 80.1) ÷ 100;',1,1);
INSERT INTO rubric_criterion VALUES(7369,'chem12a1-ast-7',NULL,1,'= (199 + 881.1) ÷ 100 = 10.8.',1,1);
INSERT INTO rubric_criterion VALUES(7370,'chem12a1-ast-8',NULL,0,'16 protons means the element is sulfur;',1,1);
INSERT INTO rubric_criterion VALUES(7371,'chem12a1-ast-8',NULL,1,'mass number = 16 + 18 = 34, symbol ³⁴S²⁻ (³⁴₁₆S²⁻);',1,1);
INSERT INTO rubric_criterion VALUES(7372,'chem12a1-ast-8',NULL,2,'there are 2 more electrons than protons, so the charge is 2−.',1,1);
INSERT INTO rubric_criterion VALUES(7388,'chem12a1-ast-24',NULL,0,'Thomson''s model had positive charge spread evenly through the whole atom with electrons embedded in it [1];',1,1);
INSERT INTO rubric_criterion VALUES(7389,'chem12a1-ast-24',NULL,1,'Rutherford''s model placed all the positive charge and almost all the mass in a tiny, dense nucleus at the centre [1];',1,1);
INSERT INTO rubric_criterion VALUES(7390,'chem12a1-ast-24',NULL,2,'the electrons are outside the nucleus, so the atom is mostly empty space [1].',1,1);
INSERT INTO rubric_criterion VALUES(7391,'chem12a1-ast-25',NULL,0,'Ar = (20.0 × 90.5 + 21.0 × 0.3 + 22.0 × 9.2) ÷ 100 = (1810 + 6.3 + 202.4) ÷ 100 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7392,'chem12a1-ast-25',NULL,1,'= 20.2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(7393,'chem12a1-ast-26',NULL,0,'Al atom: 2,8,3 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7394,'chem12a1-ast-26',NULL,1,'Al³⁺ ion: 2,8 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7395,'chem12a1-ast-26',NULL,2,'the atom loses its three outer-shell electrons to form the 3+ ion, so the third shell is no longer occupied [1].',1,1);
INSERT INTO rubric_criterion VALUES(7396,'chem12a1-ast-27',NULL,0,'Protons = 30 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7397,'chem12a1-ast-27',NULL,1,'neutrons = 65 − 30 = 35 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7398,'chem12a1-ast-27',NULL,2,'electrons = 30 − 2 = 28 because the 2+ charge means two electrons have been lost [1].',1,1);
INSERT INTO rubric_criterion VALUES(7399,'chem12a1-ast-28',NULL,0,'Let the fraction of ⁷Li be x: 7.0x + 6.0(1 − x) = 6.94 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7400,'chem12a1-ast-28',NULL,1,'x = 0.94, so ⁷Li is 94% [1];',1,1);
INSERT INTO rubric_criterion VALUES(7401,'chem12a1-ast-28',NULL,2,'⁶Li is therefore 6% [1].',1,1);
INSERT INTO rubric_criterion VALUES(7402,'chem12a1-ast-29',NULL,0,'The horizontal axis shows mass-to-charge ratio (mass of each isotope for singly charged ions) and each peak represents one isotope [1];',1,1);
INSERT INTO rubric_criterion VALUES(7403,'chem12a1-ast-29',NULL,1,'the height of each peak gives the relative abundance of that isotope [1];',1,1);
INSERT INTO rubric_criterion VALUES(7404,'chem12a1-ast-29',NULL,2,'the relative atomic mass is the weighted average of the isotopic masses using these abundances [1].',1,1);
INSERT INTO rubric_criterion VALUES(7405,'chem12a1-ast-30',NULL,0,'Electrons are in fixed shells (energy levels) at set distances from the nucleus, each with a specific energy [1];',1,1);
INSERT INTO rubric_criterion VALUES(7406,'chem12a1-ast-30',NULL,1,'electrons can move between energy levels only by absorbing or emitting specific amounts of energy [1].',1,1);
INSERT INTO rubric_criterion VALUES(7407,'chem12a1-ast-31',NULL,0,'X and Y are isotopes because they have the same number of protons (12) but different numbers of neutrons [1];',1,1);
INSERT INTO rubric_criterion VALUES(7408,'chem12a1-ast-31',NULL,1,'the element is magnesium, so X is ²⁴Mg [1] and Y is ²⁶Mg [1].',2,1);
INSERT INTO rubric_criterion VALUES(7409,'chem12a1-ast-32',NULL,0,'The ion has 20 − 2 = 18 electrons [1];',1,1);
INSERT INTO rubric_criterion VALUES(7410,'chem12a1-ast-32',NULL,1,'configuration 2,8,8 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7411,'chem12a1-ast-32',NULL,2,'the same configuration as argon [1].',1,1);
INSERT INTO rubric_criterion VALUES(7419,'chem12a1-ec-6',NULL,0,'S: 1s² 2s² 2p⁶ 3s² 3p⁴;',1,1);
INSERT INTO rubric_criterion VALUES(7420,'chem12a1-ec-6',NULL,1,'S²⁻: 1s² 2s² 2p⁶ 3s² 3p⁶ (two electrons added to 3p, same configuration as argon).',1,1);
INSERT INTO rubric_criterion VALUES(7421,'chem12a1-ec-7',NULL,0,'Subshells fill in order of increasing energy, and the 4s subshell is lower in energy than 3d, so it fills first;',1,1);
INSERT INTO rubric_criterion VALUES(7422,'chem12a1-ec-7',NULL,1,'each orbital holds a maximum of two electrons, which have opposite spins.',1,1);
INSERT INTO rubric_criterion VALUES(7423,'chem12a1-ec-8',NULL,0,'Heat energy promotes (excites) electrons to higher energy levels;',1,1);
INSERT INTO rubric_criterion VALUES(7424,'chem12a1-ec-8',NULL,1,'when the electrons return to lower energy levels they release the energy difference as light (photons) of specific energies/wavelengths, giving discrete lines;',1,1);
INSERT INTO rubric_criterion VALUES(7425,'chem12a1-ec-8',NULL,2,'each element has a unique set of energy levels (different nuclear charge and electron arrangement), so the energy differences, and therefore the line pattern, are unique to that element.',1,1);
INSERT INTO rubric_criterion VALUES(7442,'chem12a1-ec-25',NULL,0,'Al: 1s² 2s² 2p⁶ 3s² 3p¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(7443,'chem12a1-ec-25',NULL,1,'Al³⁺: 1s² 2s² 2p⁶ [1].',1,1);
INSERT INTO rubric_criterion VALUES(7444,'chem12a1-ec-25',NULL,2,'Al³⁺ has the same configuration as neon [1].',1,1);
INSERT INTO rubric_criterion VALUES(7445,'chem12a1-ec-26',NULL,0,'A subshell is a group of orbitals of the same type (s, p, d, f) within a shell, with the same energy [1].',1,1);
INSERT INTO rubric_criterion VALUES(7446,'chem12a1-ec-26',NULL,1,'An orbital is a region of space where an electron is likely to be found, holding a maximum of two electrons [1].',1,1);
INSERT INTO rubric_criterion VALUES(7447,'chem12a1-ec-26',NULL,2,'A d subshell contains 5 orbitals [1].',1,1);
INSERT INTO rubric_criterion VALUES(7448,'chem12a1-ec-27',NULL,0,'V: [Ar] 3d³ 4s² [1].',1,1);
INSERT INTO rubric_criterion VALUES(7449,'chem12a1-ec-27',NULL,1,'V³⁺: [Ar] 3d² (the 4s electrons are removed first, then one 3d electron) [1].',1,1);
INSERT INTO rubric_criterion VALUES(7450,'chem12a1-ec-28',NULL,0,'Calcium (1s² … 4s²) has its last electron enter the 4s subshell, so it is an s-block element [1].',1,1);
INSERT INTO rubric_criterion VALUES(7451,'chem12a1-ec-28',NULL,1,'Scandium ([Ar] 3d¹ 4s²) has its last electron enter the 3d subshell, so it is a d-block element [1].',1,1);
INSERT INTO rubric_criterion VALUES(7452,'chem12a1-ec-29',NULL,0,'Co²⁺: [Ar] 3d⁷ [1]. There are 3 unpaired electrons (3d⁷ gives two paired and three unpaired in five orbitals) [1].',1,1);
INSERT INTO rubric_criterion VALUES(7453,'chem12a1-ec-29',NULL,1,'Cobalt is [Ar] 3d⁷ 4s²;',1,1);
INSERT INTO rubric_criterion VALUES(7454,'chem12a1-ec-29',NULL,2,'the two 4s electrons are removed first when the ion forms [1].',1,1);
INSERT INTO rubric_criterion VALUES(7457,'chem12a1-ec-32',NULL,0,'Br: 1s² 2s² 2p⁶ 3s² 3p⁶ 3d¹⁰ 4s² 4p⁵ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7458,'chem12a1-ec-32',NULL,1,'Br⁻: 1s² 2s² 2p⁶ 3s² 3p⁶ 3d¹⁰ 4s² 4p⁶ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7459,'chem12a1-ec-32',NULL,2,'Br⁻ has the same configuration as krypton [1].',1,1);
INSERT INTO rubric_criterion VALUES(7466,'chem12a1-pt-6',NULL,0,'Both ions have the same number of electrons in the same shells (isoelectronic);',1,1);
INSERT INTO rubric_criterion VALUES(7467,'chem12a1-pt-6',NULL,1,'Na⁺ has 11 protons compared with 9 in F⁻, so its greater nuclear charge pulls the electrons closer, giving a smaller radius.',1,1);
INSERT INTO rubric_criterion VALUES(7468,'chem12a1-pt-7',NULL,0,'First ionisation energy decreases down the group;',1,1);
INSERT INTO rubric_criterion VALUES(7469,'chem12a1-pt-7',NULL,1,'core charge stays constant at +1, but the number of occupied shells increases, so the valence electron is further from the nucleus;',1,1);
INSERT INTO rubric_criterion VALUES(7470,'chem12a1-pt-7',NULL,2,'the weaker attraction (with more shielding) means less energy is needed to remove it.',1,1);
INSERT INTO rubric_criterion VALUES(7471,'chem12a1-pt-8',NULL,0,'Electronegativity increases across period 3 from Na to Cl;',1,1);
INSERT INTO rubric_criterion VALUES(7472,'chem12a1-pt-8',NULL,1,'core charge increases and atomic radius decreases with the same number of shells, so the nucleus attracts bonding electrons more strongly.',1,1);
INSERT INTO rubric_criterion VALUES(7488,'chem12a1-pt-24',NULL,0,'Core charge is the net positive charge experienced by valence electrons: number of protons minus number of inner-shell (non-valence) electrons [1];',1,1);
INSERT INTO rubric_criterion VALUES(7489,'chem12a1-pt-24',NULL,1,'aluminium has 13 protons and 10 inner-shell electrons, so core charge = +3 [1].',1,1);
INSERT INTO rubric_criterion VALUES(7490,'chem12a1-pt-25',NULL,0,'Both atoms have a core charge of +2 and two valence electrons [1];',1,1);
INSERT INTO rubric_criterion VALUES(7491,'chem12a1-pt-25',NULL,1,'calcium has four occupied shells compared with three for magnesium, so its valence electrons are further from the nucleus [1];',1,1);
INSERT INTO rubric_criterion VALUES(7492,'chem12a1-pt-25',NULL,2,'they are less strongly attracted, so they are lost more easily, making calcium more reactive [1].',1,1);
INSERT INTO rubric_criterion VALUES(7493,'chem12a1-pt-26',NULL,0,'Atomic radius decreases from sodium to silicon across the period [1];',1,1);
INSERT INTO rubric_criterion VALUES(7494,'chem12a1-pt-26',NULL,1,'the number of occupied shells stays the same (three) while core charge increases from +1 to +4 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7495,'chem12a1-pt-26',NULL,2,'the increasing attraction pulls the valence electrons closer to the nucleus [1].',1,1);
INSERT INTO rubric_criterion VALUES(7499,'chem12a1-pt-30',NULL,0,'The very large increase between the third and fourth ionisation energies shows that the fourth electron is removed from an inner shell [1];',1,1);
INSERT INTO rubric_criterion VALUES(7500,'chem12a1-pt-30',NULL,1,'so the atom has three valence electrons and is in group 13 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7501,'chem12a1-pt-30',NULL,2,'in period 3 this is aluminium [1].',1,1);
INSERT INTO rubric_criterion VALUES(7502,'chem12a1-pt-31',NULL,0,'Chlorine has the higher first ionisation energy [1];',1,1);
INSERT INTO rubric_criterion VALUES(7503,'chem12a1-pt-31',NULL,1,'both have three occupied shells but chlorine''s core charge is +7 compared with +1, so its valence electrons are held much more strongly [1].',1,1);
INSERT INTO rubric_criterion VALUES(7510,'chem12a1-mb-6',NULL,0,'Magnesium contributes two delocalised electrons per atom and forms Mg²⁺ ions, while sodium contributes one and forms Na⁺;',1,1);
INSERT INTO rubric_criterion VALUES(7511,'chem12a1-mb-6',NULL,1,'the higher cation charge and greater density of delocalised electrons give stronger electrostatic attraction in magnesium, so more energy is needed to disrupt the lattice.',1,1);
INSERT INTO rubric_criterion VALUES(7512,'chem12a1-mb-7',NULL,0,'The small carbon atoms occupy spaces (interstices) between the iron ions in the lattice;',1,1);
INSERT INTO rubric_criterion VALUES(7513,'chem12a1-mb-7',NULL,1,'this distorts the lattice and makes it harder for layers of iron ions to slide past each other, so the alloy is harder and less malleable.',1,1);
INSERT INTO rubric_criterion VALUES(7514,'chem12a1-mb-8',NULL,0,'Quenching (rapid cooling) produces very small crystals, giving a hard but brittle metal;',1,1);
INSERT INTO rubric_criterion VALUES(7515,'chem12a1-mb-8',NULL,1,'tempering involves reheating the quenched metal to a moderate temperature and cooling it, which allows partial rearrangement of the crystals;',1,1);
INSERT INTO rubric_criterion VALUES(7516,'chem12a1-mb-8',NULL,2,'tempered steel keeps much of its hardness but is tougher and less brittle.',1,1);
INSERT INTO rubric_criterion VALUES(7533,'chem12a1-mb-25',NULL,0,'n(Al) = 2.70 / 27.0 = 0.100 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7534,'chem12a1-mb-25',NULL,1,'each Al atom contributes 3 delocalised electrons, so n(e⁻) = 0.300 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7535,'chem12a1-mb-25',NULL,2,'number = 0.300 × 6.02 × 10²³ = 1.81 × 10²³ electrons [1].',1,1);
INSERT INTO rubric_criterion VALUES(7540,'chem12a1-mb-30',NULL,0,'A metal is a lattice of positive ions (cations) surrounded by a sea of delocalised valence electrons [1];',1,1);
INSERT INTO rubric_criterion VALUES(7541,'chem12a1-mb-30',NULL,1,'the bonding is the electrostatic attraction between the cations and the delocalised electrons [1].',1,1);
INSERT INTO rubric_criterion VALUES(7542,'chem12a1-mb-31',NULL,0,'The copper and silver atoms differ in size from gold atoms and disrupt the regular arrangement of the lattice [1];',1,1);
INSERT INTO rubric_criterion VALUES(7543,'chem12a1-mb-31',NULL,1,'this makes it harder for layers of atoms to slide over each other, so the alloy is harder [1].',1,1);
INSERT INTO rubric_criterion VALUES(7550,'chem12a1-ib-6',NULL,0,'Formula Ca₃N₂;',1,1);
INSERT INTO rubric_criterion VALUES(7551,'chem12a1-ib-6',NULL,1,'each Ca atom loses 2 electrons to form Ca²⁺ and each N atom gains 3 electrons to form N³⁻;',1,1);
INSERT INTO rubric_criterion VALUES(7552,'chem12a1-ib-6',NULL,2,'three Ca atoms transfer a total of 6 electrons to two N atoms, so the charges balance (3 × +2 = 2 × 3).',1,1);
INSERT INTO rubric_criterion VALUES(7553,'chem12a1-ib-7',NULL,0,'(a) iron(III) oxide;',1,1);
INSERT INTO rubric_criterion VALUES(7554,'chem12a1-ib-7',NULL,1,'(b) ammonium nitrate;',1,1);
INSERT INTO rubric_criterion VALUES(7555,'chem12a1-ib-7',NULL,2,'(c) potassium dichromate.',1,1);
INSERT INTO rubric_criterion VALUES(7556,'chem12a1-ib-8',NULL,0,'Ionic bonding; high melting point: strong electrostatic attraction between oppositely charged ions throughout the lattice needs a lot of energy to overcome;',1,1);
INSERT INTO rubric_criterion VALUES(7557,'chem12a1-ib-8',NULL,1,'conductivity: ions are fixed in the solid but free to move in solution, so only the solution conducts;',1,1);
INSERT INTO rubric_criterion VALUES(7558,'chem12a1-ib-8',NULL,2,'brittleness: displacing layers aligns like charges, which repel (any two explanations).',1,1);
INSERT INTO rubric_criterion VALUES(7571,'chem12a1-ib-21',NULL,0,'(a) Na₂S [1];',1,1);
INSERT INTO rubric_criterion VALUES(7572,'chem12a1-ib-21',NULL,1,'(b) Mg(NO₃)₂ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7573,'chem12a1-ib-21',NULL,2,'(c) Fe(OH)₃ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7574,'chem12a1-ib-21',NULL,3,'(d) (NH₄)₂CO₃ [1].',1,1);
INSERT INTO rubric_criterion VALUES(7575,'chem12a1-ib-22',NULL,0,'Water is a polar molecule with partial positive and partial negative ends [1];',1,1);
INSERT INTO rubric_criterion VALUES(7576,'chem12a1-ib-22',NULL,1,'the partial negative oxygen ends are attracted to Na⁺ and the partial positive hydrogen ends are attracted to Cl⁻ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7577,'chem12a1-ib-22',NULL,2,'the energy released by these ion–water attractions is enough to overcome the ionic bonds in the lattice, so the ions separate and become surrounded by water molecules [1].',1,1);
INSERT INTO rubric_criterion VALUES(7578,'chem12a1-ib-23',NULL,0,'Al atom: 2,8,3 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7579,'chem12a1-ib-23',NULL,1,'Al³⁺ ion: 2,8 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7580,'chem12a1-ib-23',NULL,2,'Al loses its three valence electrons to achieve a stable noble gas configuration (same as neon), leaving 13 protons and 10 electrons, so the charge is 3+ [1].',1,1);
INSERT INTO rubric_criterion VALUES(7581,'chem12a1-ib-24',NULL,0,'A continuous three-dimensional array of alternating positive and negative ions [1];',1,1);
INSERT INTO rubric_criterion VALUES(7582,'chem12a1-ib-24',NULL,1,'held in fixed positions by strong electrostatic attraction between oppositely charged ions (no discrete molecules) [1].',1,1);
INSERT INTO rubric_criterion VALUES(7583,'chem12a1-ib-25',NULL,0,'Mg (2,8,2) loses two electrons to form Mg²⁺ (2,8) [1];',1,1);
INSERT INTO rubric_criterion VALUES(7584,'chem12a1-ib-25',NULL,1,'each Cl atom (2,8,7) gains one electron to form Cl⁻ (2,8,8), so two Cl atoms are needed [1];',1,1);
INSERT INTO rubric_criterion VALUES(7585,'chem12a1-ib-25',NULL,2,'the oppositely charged ions attract by electrostatic forces to form a lattice with formula MgCl₂ [1].',1,1);
INSERT INTO rubric_criterion VALUES(7591,'chem12a1-ib-31',NULL,0,'MgO contains Mg²⁺ and O²⁻ ions, whereas NaCl contains Na⁺ and Cl⁻ ions [1];',1,1);
INSERT INTO rubric_criterion VALUES(7592,'chem12a1-ib-31',NULL,1,'the ions in MgO have greater charges and are smaller, so the electrostatic attraction in the lattice is stronger [1];',1,1);
INSERT INTO rubric_criterion VALUES(7593,'chem12a1-ib-31',NULL,2,'more energy is therefore needed to break the lattice [1].',1,1);
INSERT INTO rubric_criterion VALUES(7594,'chem12a1-ib-32',NULL,0,'n(Na₂CO₃) = 5.30 ÷ 106.0 = 0.0500 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7595,'chem12a1-ib-32',NULL,1,'each formula unit has three ions (2Na⁺ + CO₃²⁻), so n(ions) = 0.150 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7596,'chem12a1-ib-32',NULL,2,'number of ions = 0.150 × 6.02 × 10²³ = 9.03 × 10²² [1].',1,1);
INSERT INTO rubric_criterion VALUES(7597,'chem12a1-ib-33',NULL,0,'CaS [1];',1,1);
INSERT INTO rubric_criterion VALUES(7598,'chem12a1-ib-33',NULL,1,'Ca²⁺ and S²⁻ both have the configuration 1s² 2s² 2p⁶ 3s² 3p⁶ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7599,'chem12a1-ib-33',NULL,2,'they are isoelectronic with each other and with the noble gas argon [1].',1,1);
INSERT INTO rubric_criterion VALUES(7606,'chem12a1-nr-6',NULL,0,'(a) Ca(s) + 2H₂O(l) → Ca(OH)₂(aq) + H₂(g);',1,1);
INSERT INTO rubric_criterion VALUES(7607,'chem12a1-nr-6',NULL,1,'(b) 2Mg(s) + O₂(g) → 2MgO(s).',1,1);
INSERT INTO rubric_criterion VALUES(7608,'chem12a1-nr-7',NULL,0,'Order of reactivity: A > B > C;',1,1);
INSERT INTO rubric_criterion VALUES(7609,'chem12a1-nr-7',NULL,1,'A could be magnesium (reacts rapidly with dilute acid);',1,1);
INSERT INTO rubric_criterion VALUES(7610,'chem12a1-nr-7',NULL,2,'B could be iron (reacts slowly), and C could be copper (does not react with dilute HCl).',1,1);
INSERT INTO rubric_criterion VALUES(7611,'chem12a1-nr-8',NULL,0,'Nanoparticles have a much larger surface area to volume ratio, so a larger proportion of silver atoms are exposed at the surface;',1,1);
INSERT INTO rubric_criterion VALUES(7612,'chem12a1-nr-8',NULL,1,'this allows more contact with and greater release of silver ions to bacteria, so a small mass is very effective;',1,1);
INSERT INTO rubric_criterion VALUES(7613,'chem12a1-nr-8',NULL,2,'concern: nanoparticles may penetrate cells or tissue, accumulate in the body or the environment, or harm beneficial organisms, and their long-term health effects are not fully known.',1,1);
INSERT INTO rubric_criterion VALUES(7628,'chem12a1-nr-23',NULL,0,'Ratio for a cube = 6 ÷ side length, so for 10 nm: 6 ÷ 10 = 0.60 nm⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7629,'chem12a1-nr-23',NULL,1,'1.0 cm = 1.0 × 10⁷ nm, so ratio = 6 ÷ (1.0 × 10⁷) = 6.0 × 10⁻⁷ nm⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7630,'chem12a1-nr-23',NULL,2,'the 10 nm cube''s ratio is 10⁶ (one million) times larger [1].',1,1);
INSERT INTO rubric_criterion VALUES(7636,'chem12a1-nr-29',NULL,0,'A reddish-brown deposit (copper) forms on the nail [1];',1,1);
INSERT INTO rubric_criterion VALUES(7637,'chem12a1-nr-29',NULL,1,'the blue colour of the solution fades (towards pale green) [1];',1,1);
INSERT INTO rubric_criterion VALUES(7638,'chem12a1-nr-29',NULL,2,'Fe(s) + Cu²⁺(aq) → Fe²⁺(aq) + Cu(s) [1].',1,1);
INSERT INTO rubric_criterion VALUES(7639,'chem12a1-nr-30',NULL,0,'Benefit: the nanoparticles are antibacterial, which reduces odour (or the growth of bacteria) in the fabric [1];',1,1);
INSERT INTO rubric_criterion VALUES(7640,'chem12a1-nr-30',NULL,1,'risk: nanoparticles washed out of the clothing may enter waterways and harm aquatic organisms (or may be absorbed through skin with unknown effects) [1].',1,1);
INSERT INTO rubric_criterion VALUES(7647,'chem12a1-lc-6',NULL,0,'Carbon is the central atom;',1,1);
INSERT INTO rubric_criterion VALUES(7648,'chem12a1-lc-6',NULL,1,'C forms a double bond to O and single bonds to each of the two H atoms;',1,1);
INSERT INTO rubric_criterion VALUES(7649,'chem12a1-lc-6',NULL,2,'O has two lone pairs while C and H have none (C and O have octets, H has 2 electrons).',1,1);
INSERT INTO rubric_criterion VALUES(7650,'chem12a1-lc-7',NULL,0,'Valence electrons: 5 + 3 × 7 = 26;',1,1);
INSERT INTO rubric_criterion VALUES(7651,'chem12a1-lc-7',NULL,1,'3 bonding pairs (three P–Cl single bonds);',1,1);
INSERT INTO rubric_criterion VALUES(7652,'chem12a1-lc-7',NULL,2,'lone pairs: 1 on P + 3 on each Cl = 10 lone pairs (26 − 6 = 20 electrons).',1,1);
INSERT INTO rubric_criterion VALUES(7653,'chem12a1-lc-8',NULL,0,'Melting only requires overcoming weak intermolecular (dispersion) forces between molecules, not the strong covalent bonds within them, so little energy is needed;',1,1);
INSERT INTO rubric_criterion VALUES(7654,'chem12a1-lc-8',NULL,1,'the molecules are neutral and all electrons are localised in bonds or lone pairs, so there are no free charged particles to carry a current.',1,1);
INSERT INTO rubric_criterion VALUES(7671,'chem12a1-lc-25',NULL,0,'A bonding pair is a pair of electrons shared between two atoms, forming a covalent bond [1].',1,1);
INSERT INTO rubric_criterion VALUES(7672,'chem12a1-lc-25',NULL,1,'A lone pair is a pair of valence electrons that belongs to one atom only and is not involved in bonding [1].',1,1);
INSERT INTO rubric_criterion VALUES(7673,'chem12a1-lc-26',NULL,0,'N₂ contains a triple bond (three shared pairs) whereas O₂ contains a double bond (two shared pairs) [1].',1,1);
INSERT INTO rubric_criterion VALUES(7674,'chem12a1-lc-26',NULL,1,'More shared pairs mean a greater electrostatic attraction between the shared electrons and the two nuclei [1].',1,1);
INSERT INTO rubric_criterion VALUES(7675,'chem12a1-lc-26',NULL,2,'This makes the N≡N bond shorter and stronger, so more energy is needed to break it [1].',1,1);
INSERT INTO rubric_criterion VALUES(7676,'chem12a1-lc-27',NULL,0,'Total valence electrons = 4 + 2 × 6 = 16 [1].',1,1);
INSERT INTO rubric_criterion VALUES(7677,'chem12a1-lc-27',NULL,1,'Carbon is the central atom and forms a double bond to each sulfur atom (S=C=S) [1].',1,1);
INSERT INTO rubric_criterion VALUES(7678,'chem12a1-lc-27',NULL,2,'Each S atom has two lone pairs and C has none, so all atoms have an octet [1].',1,1);
INSERT INTO rubric_criterion VALUES(7679,'chem12a1-lc-28',NULL,0,'Oxygen (6 valence electrons) shares one electron with each of two hydrogen atoms, forming two single bonds, and has two lone pairs, giving it 8 electrons (an octet) [1].',1,1);
INSERT INTO rubric_criterion VALUES(7680,'chem12a1-lc-28',NULL,1,'Each hydrogen shares one pair, giving it 2 electrons in its valence shell, the same as helium [1].',1,1);
INSERT INTO rubric_criterion VALUES(7681,'chem12a1-lc-29',NULL,0,'Non-metal atoms have high and similar attractions for electrons, so neither atom can remove electrons completely from the other [1].',1,1);
INSERT INTO rubric_criterion VALUES(7682,'chem12a1-lc-29',NULL,1,'Instead they share electrons, so that each atom attains a stable noble-gas electron configuration [1].',1,1);
INSERT INTO rubric_criterion VALUES(7683,'chem12a1-lc-30',NULL,0,'In CH₄, the central C has 4 bonding pairs and 0 lone pairs [1].',1,1);
INSERT INTO rubric_criterion VALUES(7684,'chem12a1-lc-30',NULL,1,'In NH₃, the central N has 3 bonding pairs and 1 lone pair [1].',1,1);
INSERT INTO rubric_criterion VALUES(7685,'chem12a1-lc-30',NULL,2,'In H₂O, the central O has 2 bonding pairs and 2 lone pairs, so the central atom has an octet (4 pairs in total) in each molecule [1].',1,1);
INSERT INTO rubric_criterion VALUES(7686,'chem12a1-lc-31',NULL,0,'Total valence electrons = 2 × 4 + 6 × 1 + 6 = 20 [1].',1,1);
INSERT INTO rubric_criterion VALUES(7687,'chem12a1-lc-31',NULL,1,'All bonds are single bonds: C–C, C–O, O–H and five C–H bonds [1].',1,1);
INSERT INTO rubric_criterion VALUES(7688,'chem12a1-lc-31',NULL,2,'This gives 8 bonding pairs (16 electrons) [1].',1,1);
INSERT INTO rubric_criterion VALUES(7689,'chem12a1-lc-31',NULL,3,'The remaining 4 electrons form 2 lone pairs, both on the oxygen atom, and no other atom has lone pairs [1].',1,1);
INSERT INTO rubric_criterion VALUES(7696,'chem12a1-vs-6',NULL,0,'The O atom has four electron pairs (two bonding, two lone pairs) which repel each other and arrange themselves tetrahedrally to be as far apart as possible;',1,1);
INSERT INTO rubric_criterion VALUES(7697,'chem12a1-vs-6',NULL,1,'the shape is described by the atoms only, so the two H atoms and O form a V (bent) shape with an angle of about 104.5°.',1,1);
INSERT INTO rubric_criterion VALUES(7698,'chem12a1-vs-7',NULL,0,'(a) HCN: linear, 180° (two regions of electron density around C, no lone pairs);',1,1);
INSERT INTO rubric_criterion VALUES(7699,'chem12a1-vs-7',NULL,1,'(b) SiCl₄: tetrahedral, 109.5° (four bonding pairs, no lone pairs on Si).',1,1);
INSERT INTO rubric_criterion VALUES(7700,'chem12a1-vs-8',NULL,0,'Both central atoms have four electron pairs arranged tetrahedrally;',1,1);
INSERT INTO rubric_criterion VALUES(7701,'chem12a1-vs-8',NULL,1,'N in ammonia has one lone pair, which repels more strongly than bonding pairs, pushing the N–H bonds closer together and reducing the angle, while methane has four bonding pairs and no lone pairs.',1,1);
INSERT INTO rubric_criterion VALUES(7717,'chem12a1-vs-24',NULL,0,'In CO₂ the carbon atom has two regions of electron density and no lone pairs [1];',1,1);
INSERT INTO rubric_criterion VALUES(7718,'chem12a1-vs-24',NULL,1,'these are furthest apart at 180°, so the molecule is linear [1];',1,1);
INSERT INTO rubric_criterion VALUES(7719,'chem12a1-vs-24',NULL,2,'in SO₂ the sulfur atom has three regions including one lone pair, so the two bonded atoms are not opposite each other and the shape is V-shaped [1].',1,1);
INSERT INTO rubric_criterion VALUES(7720,'chem12a1-vs-25',NULL,0,'Both central atoms have four electron pairs arranged tetrahedrally [1];',1,1);
INSERT INTO rubric_criterion VALUES(7721,'chem12a1-vs-25',NULL,1,'water has two lone pairs but ammonia has only one [1];',1,1);
INSERT INTO rubric_criterion VALUES(7722,'chem12a1-vs-25',NULL,2,'the extra lone pair repels the bonding pairs more strongly, squeezing the angle further below 109.5° in water [1].',1,1);
INSERT INTO rubric_criterion VALUES(7723,'chem12a1-vs-26',NULL,0,'The arrangement of electron pairs includes both bonding and lone pairs; in NH₃ the four pairs are arranged tetrahedrally [1];',1,1);
INSERT INTO rubric_criterion VALUES(7724,'chem12a1-vs-26',NULL,1,'the shape describes only the positions of the atoms, so with one lone pair the NH₃ molecule is trigonal pyramidal [1].',1,1);
INSERT INTO rubric_criterion VALUES(7729,'chem12a1-vs-31',NULL,0,'BF₃ is trigonal planar, with three bonding pairs and no lone pairs around B [1];',1,1);
INSERT INTO rubric_criterion VALUES(7730,'chem12a1-vs-31',NULL,1,'NF₃ is trigonal pyramidal, as N has three bonding pairs and one lone pair, so four electron pairs are arranged tetrahedrally [1];',1,1);
INSERT INTO rubric_criterion VALUES(7731,'chem12a1-vs-31',NULL,2,'the lone pair repels the bonding pairs more strongly, pushing the F atoms closer together so the F–N–F angle is less than 109.5° [1].',1,1);
INSERT INTO rubric_criterion VALUES(7738,'chem12a1-ep-6',NULL,0,'Cl is more electronegative than C, so each C–Cl bond is polar (Cδ+–Clδ−);',1,1);
INSERT INTO rubric_criterion VALUES(7739,'chem12a1-ep-6',NULL,1,'the molecule is tetrahedral and symmetrical, so the four equal bond dipoles cancel and there is no overall dipole.',1,1);
INSERT INTO rubric_criterion VALUES(7740,'chem12a1-ep-7',NULL,0,'O is more electronegative than H, so the shared electrons in each O–H bond are pulled towards O, making each bond polar;',1,1);
INSERT INTO rubric_criterion VALUES(7741,'chem12a1-ep-7',NULL,1,'O carries a partial negative charge (δ−) and each H a partial positive charge (δ+);',1,1);
INSERT INTO rubric_criterion VALUES(7742,'chem12a1-ep-7',NULL,2,'the molecule is V-shaped (asymmetrical), so the bond dipoles do not cancel and there is a net dipole.',1,1);
INSERT INTO rubric_criterion VALUES(7743,'chem12a1-ep-8',NULL,0,'H–Br < H–Cl < H–F;',1,1);
INSERT INTO rubric_criterion VALUES(7744,'chem12a1-ep-8',NULL,1,'electronegativity decreases down group 17 because the valence shell is further from the nucleus (more shells, same core charge), so the halogen''s attraction for the shared electrons, and therefore the electronegativity difference with H, decreases from F to Br.',1,1);
INSERT INTO rubric_criterion VALUES(7759,'chem12a1-ep-23',NULL,0,'N is more electronegative than H, so each N–H bond is polar with Nδ− and Hδ+ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7760,'chem12a1-ep-23',NULL,1,'the molecule is trigonal pyramidal because of the lone pair on N, so it is asymmetrical [1];',1,1);
INSERT INTO rubric_criterion VALUES(7761,'chem12a1-ep-23',NULL,2,'the bond dipoles therefore do not cancel and the molecule has a net dipole [1].',1,1);
INSERT INTO rubric_criterion VALUES(7762,'chem12a1-ep-24',NULL,0,'The three C–Cl bonds are strongly polar, whereas the C–H bond is almost non-polar [1];',1,1);
INSERT INTO rubric_criterion VALUES(7763,'chem12a1-ep-24',NULL,1,'the four bonds are not identical, so the molecule is not symmetrical in its charge distribution [1];',1,1);
INSERT INTO rubric_criterion VALUES(7764,'chem12a1-ep-24',NULL,2,'the bond dipoles do not cancel, so there is a net dipole [1].',1,1);
INSERT INTO rubric_criterion VALUES(7765,'chem12a1-ep-25',NULL,0,'Na–Cl: 3.2 − 0.9 = 2.3, ionic [1];',1,1);
INSERT INTO rubric_criterion VALUES(7766,'chem12a1-ep-25',NULL,1,'H–Cl: 3.2 − 2.2 = 1.0, polar covalent [1];',1,1);
INSERT INTO rubric_criterion VALUES(7767,'chem12a1-ep-25',NULL,2,'Cl–Cl: 0, non-polar covalent [1].',1,1);
INSERT INTO rubric_criterion VALUES(7768,'chem12a1-ep-26',NULL,0,'S is slightly more electronegative than H, so each S–H bond is slightly polar with Sδ− and Hδ+ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7769,'chem12a1-ep-26',NULL,1,'H₂S is bent because of the two lone pairs on S, so it is asymmetrical [1];',1,1);
INSERT INTO rubric_criterion VALUES(7770,'chem12a1-ep-26',NULL,2,'the bond dipoles do not cancel, so H₂S is weakly polar [1].',1,1);
INSERT INTO rubric_criterion VALUES(7771,'chem12a1-ep-27',NULL,0,'Polarity depends on the shape as well as the bonds, and in a symmetrical molecule such as CO₂ the equal bond dipoles cancel [1];',1,1);
INSERT INTO rubric_criterion VALUES(7772,'chem12a1-ep-27',NULL,1,'a diatomic molecule has only one bond, so there is nothing to cancel its dipole [1];',1,1);
INSERT INTO rubric_criterion VALUES(7773,'chem12a1-ep-27',NULL,2,'hence a diatomic molecule such as HCl with a polar bond has a net dipole and is polar [1].',1,1);
INSERT INTO rubric_criterion VALUES(7777,'chem12a1-ep-31',NULL,0,'(a) The differences are C–H 0.4, C–O 0.8 and O–H 1.2, so the order of increasing polarity is C–H < C–O < O–H [1];',1,1);
INSERT INTO rubric_criterion VALUES(7778,'chem12a1-ep-31',NULL,1,'(b) oxygen is more electronegative, so it carries the partial negative charge and carbon the partial positive charge, Cδ+–Oδ− [1].',1,1);
INSERT INTO rubric_criterion VALUES(7779,'chem12a1-ep-32',NULL,0,'Both molecules contain polar S–O bonds, with S the less electronegative atom [1];',1,1);
INSERT INTO rubric_criterion VALUES(7780,'chem12a1-ep-32',NULL,1,'SO₃ is trigonal planar and symmetrical, so the bond dipoles cancel and there is no net dipole [1];',1,1);
INSERT INTO rubric_criterion VALUES(7781,'chem12a1-ep-32',NULL,2,'SO₂ is V-shaped because S has a lone pair, so the bond dipoles do not cancel and the molecule has a net dipole [1].',1,1);
INSERT INTO rubric_criterion VALUES(7788,'chem12a1-im-6',NULL,0,'In ice, each water molecule forms hydrogen bonds to four neighbours in a fixed, open hexagonal lattice;',1,1);
INSERT INTO rubric_criterion VALUES(7789,'chem12a1-im-6',NULL,1,'this arrangement holds molecules further apart than in the liquid;',1,1);
INSERT INTO rubric_criterion VALUES(7790,'chem12a1-im-6',NULL,2,'when ice melts some hydrogen bonds break and molecules pack more closely, so the same mass occupies a smaller volume in the liquid (ice has a lower density and floats).',1,1);
INSERT INTO rubric_criterion VALUES(7791,'chem12a1-im-7',NULL,0,'(a) HF molecules form hydrogen bonds (H bonded to highly electronegative F), which are much stronger than the intermolecular forces in the other hydrogen halides;',1,1);
INSERT INTO rubric_criterion VALUES(7792,'chem12a1-im-7',NULL,1,'(b) HCl, HBr and HI cannot hydrogen bond;',1,1);
INSERT INTO rubric_criterion VALUES(7793,'chem12a1-im-7',NULL,2,'from HCl to HI the number of electrons increases, so dispersion forces become stronger, outweighing the decrease in dipole–dipole attraction as bond polarity falls.',1,1);
INSERT INTO rubric_criterion VALUES(7794,'chem12a1-im-8',NULL,0,'(a) CH₄: dispersion forces only (non-polar);',1,1);
INSERT INTO rubric_criterion VALUES(7795,'chem12a1-im-8',NULL,1,'(b) HCl: dispersion and dipole–dipole forces;',1,1);
INSERT INTO rubric_criterion VALUES(7796,'chem12a1-im-8',NULL,2,'(c) NH₃: dispersion, dipole–dipole and hydrogen bonding.',1,1);
INSERT INTO rubric_criterion VALUES(7811,'chem12a1-im-23',NULL,0,'A hydrogen bond is an attractive intermolecular force between a hydrogen atom covalently bonded to a highly electronegative atom (N, O or F) in one molecule and a lone pair on a N, O or F atom of a neighbouring molecule [1];',1,1);
INSERT INTO rubric_criterion VALUES(7812,'chem12a1-im-23',NULL,1,'the molecule must therefore contain H bonded directly to N, O or F and the other atom must have a lone pair [1].',1,1);
INSERT INTO rubric_criterion VALUES(7813,'chem12a1-im-24',NULL,0,'These are non-polar molecules, so only dispersion forces act between them [1];',1,1);
INSERT INTO rubric_criterion VALUES(7814,'chem12a1-im-24',NULL,1,'the number of electrons and the molecular size increase from methane to butane [1];',1,1);
INSERT INTO rubric_criterion VALUES(7815,'chem12a1-im-24',NULL,2,'stronger dispersion forces mean more energy is needed to separate the molecules, so the boiling point rises [1].',1,1);
INSERT INTO rubric_criterion VALUES(7816,'chem12a1-im-25',NULL,0,'Both have similar numbers of electrons, so their dispersion forces are of similar strength [1];',1,1);
INSERT INTO rubric_criterion VALUES(7817,'chem12a1-im-25',NULL,1,'ethanol has an H atom bonded directly to O, so its molecules form hydrogen bonds [1];',1,1);
INSERT INTO rubric_criterion VALUES(7818,'chem12a1-im-25',NULL,2,'hydrogen bonds are stronger than the dispersion forces alone in propane, so more energy is needed to boil ethanol [1].',1,1);
INSERT INTO rubric_criterion VALUES(7819,'chem12a1-im-26',NULL,0,'Intramolecular forces (covalent bonds) act within a molecule, whereas intermolecular forces act between separate molecules [1];',1,1);
INSERT INTO rubric_criterion VALUES(7820,'chem12a1-im-26',NULL,1,'when water boils only intermolecular forces (hydrogen bonds and dispersion forces) are overcome, and the O–H covalent bonds stay intact [1].',1,1);
INSERT INTO rubric_criterion VALUES(7821,'chem12a1-im-27',NULL,0,'Each water molecule has two H atoms and two lone pairs, so it can form up to four hydrogen bonds [1];',1,1);
INSERT INTO rubric_criterion VALUES(7822,'chem12a1-im-27',NULL,1,'HF has only one H atom per molecule and NH₃ has only one lone pair, so each can form fewer hydrogen bonds per molecule [1];',1,1);
INSERT INTO rubric_criterion VALUES(7823,'chem12a1-im-27',NULL,2,'more extensive hydrogen bonding in water requires more energy to overcome, giving the highest boiling point [1].',1,1);
INSERT INTO rubric_criterion VALUES(7824,'chem12a1-im-28',NULL,0,'Both are non-polar, so only dispersion forces act between molecules [1];',1,1);
INSERT INTO rubric_criterion VALUES(7825,'chem12a1-im-28',NULL,1,'I₂ has many more electrons and is larger than F₂, so its dispersion forces are much stronger, which holds the molecules in a solid at room temperature [1].',1,1);
INSERT INTO rubric_criterion VALUES(7828,'chem12a1-im-31',NULL,0,'(a) Subliming CO₂ overcomes only the weak dispersion forces between molecules [1];',1,1);
INSERT INTO rubric_criterion VALUES(7829,'chem12a1-im-31',NULL,1,'(b) evaporating ethanol overcomes hydrogen bonds (as well as dipole–dipole and dispersion forces) between molecules [1];',1,1);
INSERT INTO rubric_criterion VALUES(7830,'chem12a1-im-31',NULL,2,'no covalent bonds within the molecules are broken in either process [1].',1,1);
INSERT INTO rubric_criterion VALUES(7831,'chem12a1-im-32',NULL,0,'The two molecules have similar molar masses, so their dispersion forces are of similar strength, but propan-1-ol has an O–H group and forms hydrogen bonds between its molecules whereas propanone has only dipole–dipole and dispersion forces [1];',1,1);
INSERT INTO rubric_criterion VALUES(7832,'chem12a1-im-32',NULL,1,'the hydrogen bonds are stronger, so more energy is needed to separate the molecules of propan-1-ol, giving it the higher boiling point [1].',1,1);
INSERT INTO rubric_criterion VALUES(7839,'chem12a1-cl-6',NULL,0,'In diamond each C is covalently bonded to four others in a rigid 3D tetrahedral network, so it is very hard, and all valence electrons are localised in bonds so it cannot conduct;',1,1);
INSERT INTO rubric_criterion VALUES(7840,'chem12a1-cl-6',NULL,1,'in graphite each C bonds to three others in layers held together by weak dispersion forces, so layers slide and it is soft;',1,1);
INSERT INTO rubric_criterion VALUES(7841,'chem12a1-cl-6',NULL,2,'the fourth electron of each C is delocalised within the layers, so graphite conducts.',1,1);
INSERT INTO rubric_criterion VALUES(7842,'chem12a1-cl-7',NULL,0,'SiO₂ is a covalent network lattice, so melting requires breaking many strong covalent Si–O bonds throughout the structure;',1,1);
INSERT INTO rubric_criterion VALUES(7843,'chem12a1-cl-7',NULL,1,'CO₂ consists of discrete non-polar molecules, so only weak dispersion forces between molecules must be overcome.',1,1);
INSERT INTO rubric_criterion VALUES(7844,'chem12a1-cl-8',NULL,0,'Use: e.g. reinforcing lightweight sports equipment or composite materials, or as tiny electrical conductors in electronics;',1,1);
INSERT INTO rubric_criterion VALUES(7845,'chem12a1-cl-8',NULL,1,'property and explanation: very high tensile strength because of the strong covalent bonds in the continuous hexagonal carbon network, or electrical conductivity because of the delocalised electrons in the graphene structure.',1,1);
INSERT INTO rubric_criterion VALUES(7860,'chem12a1-cl-23',NULL,0,'Both are covalent network lattices, with atoms joined by strong covalent bonds in a continuous three-dimensional arrangement [1];',1,1);
INSERT INTO rubric_criterion VALUES(7861,'chem12a1-cl-23',NULL,1,'in diamond each C bonds to four C atoms, while in SiO₂ each Si bonds to four O and each O to two Si [1];',1,1);
INSERT INTO rubric_criterion VALUES(7862,'chem12a1-cl-23',NULL,2,'shared properties include very high melting point and hardness, and being non-conductors of electricity [1].',1,1);
INSERT INTO rubric_criterion VALUES(7863,'chem12a1-cl-24',NULL,0,'C₆₀ is a discrete spherical molecule of 60 carbon atoms arranged in hexagons and pentagons, with each carbon bonded to three others [1];',1,1);
INSERT INTO rubric_criterion VALUES(7864,'chem12a1-cl-24',NULL,1,'in the solid, separate C₆₀ molecules are held together only by weak dispersion forces [1];',1,1);
INSERT INTO rubric_criterion VALUES(7865,'chem12a1-cl-24',NULL,2,'these are easily overcome, whereas diamond is a rigid network of strong covalent bonds throughout [1].',1,1);
INSERT INTO rubric_criterion VALUES(7866,'chem12a1-cl-25',NULL,0,'Each carbon atom in graphene forms three covalent bonds with neighbouring carbons, leaving one valence electron that is not used in bonding [1];',1,1);
INSERT INTO rubric_criterion VALUES(7867,'chem12a1-cl-25',NULL,1,'this electron is delocalised across the sheet and is free to move when a voltage is applied, carrying charge [1].',1,1);
INSERT INTO rubric_criterion VALUES(7868,'chem12a1-cl-26',NULL,0,'Drill bits use hardness of diamond [1];',1,1);
INSERT INTO rubric_criterion VALUES(7869,'chem12a1-cl-26',NULL,1,'because each C is covalently bonded to four others in a rigid three-dimensional tetrahedral lattice [1];',1,1);
INSERT INTO rubric_criterion VALUES(7870,'chem12a1-cl-26',NULL,2,'electrodes use the electrical conductivity of graphite [1];',1,1);
INSERT INTO rubric_criterion VALUES(7871,'chem12a1-cl-26',NULL,3,'because each C bonds to only three others, leaving one delocalised electron per atom that can move through the layers [1].',1,1);
INSERT INTO rubric_criterion VALUES(7872,'chem12a1-cl-27',NULL,0,'The error is that diamond is not held together by dispersion forces between molecules, as it contains no discrete molecules [1];',1,1);
INSERT INTO rubric_criterion VALUES(7873,'chem12a1-cl-27',NULL,1,'it is a covalent network lattice and melting requires breaking many strong covalent bonds between carbon atoms [1].',1,1);
INSERT INTO rubric_criterion VALUES(7877,'chem12a1-cl-31',NULL,0,'Each carbon atom has one delocalised electron that is free to move across the sheet, so graphene conducts electricity [1];',1,1);
INSERT INTO rubric_criterion VALUES(7878,'chem12a1-cl-31',NULL,1,'the strong covalent bonds in the one-atom-thick hexagonal sheet make it strong yet flexible [1].',1,1);
INSERT INTO rubric_criterion VALUES(7879,'chem12a1-cl-32',NULL,0,'In graphite each carbon atom has one delocalised electron that is free to move along the layers and carry charge [1];',1,1);
INSERT INTO rubric_criterion VALUES(7880,'chem12a1-cl-32',NULL,1,'in silicon dioxide all valence electrons are held in localised covalent bonds, so there are no mobile charge carriers [1].',1,1);
INSERT INTO rubric_criterion VALUES(7887,'chem12a2-rm-6',NULL,0,'Ar = (24 × 78.99 + 25 × 10.00 + 26 × 11.01) ÷ 100;',1,1);
INSERT INTO rubric_criterion VALUES(7888,'chem12a2-rm-6',NULL,1,'= (1895.76 + 250.0 + 286.26) ÷ 100 = 24.32 (no units, as it is a relative value).',1,1);
INSERT INTO rubric_criterion VALUES(7889,'chem12a2-rm-7',NULL,0,'Relative isotopic mass is the mass of one atom of a particular isotope relative to one-twelfth of the mass of a ¹²C atom;',1,1);
INSERT INTO rubric_criterion VALUES(7890,'chem12a2-rm-7',NULL,1,'relative atomic mass is the weighted mean of the relative isotopic masses of all naturally occurring isotopes of the element, taking their abundances into account;',1,1);
INSERT INTO rubric_criterion VALUES(7891,'chem12a2-rm-7',NULL,2,'because most elements are a mixture of isotopes, the weighted mean lies between the isotopic masses and is usually not a whole number.',1,1);
INSERT INTO rubric_criterion VALUES(7892,'chem12a2-rm-8',NULL,0,'Ar = (63 × 69.2 + 65 × 30.8) ÷ 100;',1,1);
INSERT INTO rubric_criterion VALUES(7893,'chem12a2-rm-8',NULL,1,'= (4359.6 + 2002.0) ÷ 100 = 63.6;',1,1);
INSERT INTO rubric_criterion VALUES(7894,'chem12a2-rm-8',NULL,2,'X is copper (Ar = 63.5 in the data book), the closest match.',1,1);
INSERT INTO rubric_criterion VALUES(7909,'chem12a2-rm-23',NULL,0,'Ar = (79 × 50.7 + 81 × 49.3) ÷ 100 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7910,'chem12a2-rm-23',NULL,1,'= (4005.3 + 3993.3) ÷ 100 = 79.99 [1].',1,1);
INSERT INTO rubric_criterion VALUES(7911,'chem12a2-rm-24',NULL,0,'The sample is vaporised [1];',1,1);
INSERT INTO rubric_criterion VALUES(7912,'chem12a2-rm-24',NULL,1,'atoms are ionised (by electron bombardment) to form positive ions [1];',1,1);
INSERT INTO rubric_criterion VALUES(7913,'chem12a2-rm-24',NULL,2,'the ions are accelerated and deflected by a magnetic (or electric) field, with lighter ions deflected more than heavier ones of the same charge [1];',1,1);
INSERT INTO rubric_criterion VALUES(7914,'chem12a2-rm-24',NULL,3,'a detector records the ions at each m/z value, with peak height giving relative abundance [1].',1,1);
INSERT INTO rubric_criterion VALUES(7915,'chem12a2-rm-25',NULL,0,'Let x be the fraction of ⁴¹K: 39(1 − x) + 41x = 39.10 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7916,'chem12a2-rm-25',NULL,1,'39 + 2x = 39.10, so x = 0.05 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7917,'chem12a2-rm-25',NULL,2,'⁴¹K = 5% and ³⁹K = 95% [1].',1,1);
INSERT INTO rubric_criterion VALUES(7918,'chem12a2-rm-26',NULL,0,'The horizontal axis shows the mass-to-charge ratio (m/z) of the ions [1];',1,1);
INSERT INTO rubric_criterion VALUES(7919,'chem12a2-rm-26',NULL,1,'for a ⁶³Cu⁺ ion, m/z = 63 [1].',1,1);
INSERT INTO rubric_criterion VALUES(7920,'chem12a2-rm-27',NULL,0,'Ar = (20 × 90.5 + 21 × 0.3 + 22 × 9.2) ÷ 100 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7921,'chem12a2-rm-27',NULL,1,'= (1810 + 6.3 + 202.4) ÷ 100 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7922,'chem12a2-rm-27',NULL,2,'= 20.19 [1].',1,1);
INSERT INTO rubric_criterion VALUES(7923,'chem12a2-rm-28',NULL,0,'Both are isotopes of chlorine with 17 protons and 17 electrons [1];',1,1);
INSERT INTO rubric_criterion VALUES(7924,'chem12a2-rm-28',NULL,1,'they differ in neutron number (18 and 20), so their masses differ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7925,'chem12a2-rm-28',NULL,2,'chemical properties depend on the electron configuration, which is the same for both [1].',1,1);
INSERT INTO rubric_criterion VALUES(7928,'chem12a2-rm-31',NULL,0,'Let the abundance of ¹⁸⁴Q be x%: 185.2 = (184x + 186(100 − x)) ÷ 100 [1];',1,1);
INSERT INTO rubric_criterion VALUES(7929,'chem12a2-rm-31',NULL,1,'18 520 = 18 600 − 2x, so x = 40.0, giving ¹⁸⁴Q 40.0% and ¹⁸⁶Q 60.0% [1].',1,1);
INSERT INTO rubric_criterion VALUES(7930,'chem12a2-rm-32',NULL,0,'Only charged particles can be accelerated, deflected by the magnetic field and detected, so the atoms must be ionised [1];',1,1);
INSERT INTO rubric_criterion VALUES(7931,'chem12a2-rm-32',NULL,1,'a vacuum prevents the ions colliding with air particles, which would deflect them or neutralise them before they reach the detector [1].',1,1);
INSERT INTO rubric_criterion VALUES(7932,'vce-chem12-rm-c1',NULL,0,'10.8',2,1);
INSERT INTO rubric_criterion VALUES(7938,'chem12a2-mol-6',NULL,0,'M(C₆H₁₂O₆) = 6(12.0) + 12(1.0) + 6(16.0) = 180.0 g mol⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(7939,'chem12a2-mol-6',NULL,1,'n = 9.00 ÷ 180.0 = 0.0500 mol;',1,1);
INSERT INTO rubric_criterion VALUES(7940,'chem12a2-mol-6',NULL,2,'N = 0.0500 × 6.02 × 10²³ = 3.01 × 10²² molecules.',1,1);
INSERT INTO rubric_criterion VALUES(7941,'chem12a2-mol-7',NULL,0,'n(H) = 1.20 × 10²⁴ ÷ 6.02 × 10²³ = 1.99 mol;',1,1);
INSERT INTO rubric_criterion VALUES(7942,'chem12a2-mol-7',NULL,1,'each ethanol molecule has 6 H atoms, so n(C₂H₅OH) = 1.99 ÷ 6 = 0.332 mol;',1,1);
INSERT INTO rubric_criterion VALUES(7943,'chem12a2-mol-7',NULL,2,'M(C₂H₅OH) = 46.0 g mol⁻¹, so m = 0.332 × 46.0 = 15.3 g.',1,1);
INSERT INTO rubric_criterion VALUES(7944,'chem12a2-mol-8',NULL,0,'One mole is the amount of substance containing 6.02 × 10²³ (Avogadro''s number of) specified particles;',1,1);
INSERT INTO rubric_criterion VALUES(7945,'chem12a2-mol-8',NULL,1,'both samples contain the same number of atoms, but each magnesium atom on average has about twice the mass of a carbon atom, so the molar mass (numerically equal to Ar in grams) is larger for magnesium.',1,1);
INSERT INTO rubric_criterion VALUES(7960,'chem12a2-mol-23',NULL,0,'M((NH₄)₂SO₄) = 2(14.0) + 8(1.0) + 32.1 + 4(16.0) = 132.1 g mol⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7961,'chem12a2-mol-23',NULL,1,'m = n × M = 0.350 × 132.1 = 46.2 g [1].',1,1);
INSERT INTO rubric_criterion VALUES(7962,'chem12a2-mol-24',NULL,0,'M(CH₄) = 12.0 + 4(1.0) = 16.0 g mol⁻¹, so n = 5.00 ÷ 16.0 = 0.313 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7963,'chem12a2-mol-24',NULL,1,'each molecule contains 5 atoms, so n(atoms) = 5 × 0.3125 = 1.56 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7964,'chem12a2-mol-24',NULL,2,'N = 1.56 × 6.02 × 10²³ = 9.41 × 10²³ atoms [1].',1,1);
INSERT INTO rubric_criterion VALUES(7965,'chem12a2-mol-25',NULL,0,'Relative molecular mass is the mass of a molecule relative to 1/12 of a carbon-12 atom, so it is a ratio with no units [1];',1,1);
INSERT INTO rubric_criterion VALUES(7966,'chem12a2-mol-25',NULL,1,'molar mass is the mass of one mole of the substance, in g mol⁻¹, and is numerically equal to the relative molecular mass [1].',1,1);
INSERT INTO rubric_criterion VALUES(7967,'chem12a2-mol-26',NULL,0,'Each formula unit contains 6 O atoms, so n(Cu(NO₃)₂) = 0.600 ÷ 6 = 0.100 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7968,'chem12a2-mol-26',NULL,1,'M = 63.5 + 2(14.0) + 6(16.0) = 187.5 g mol⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7969,'chem12a2-mol-26',NULL,2,'m = 0.100 × 187.5 = 18.8 g [1].',1,1);
INSERT INTO rubric_criterion VALUES(7970,'chem12a2-mol-27',NULL,0,'n(H₂O) = 10.0 ÷ 18.0 = 0.556 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7971,'chem12a2-mol-27',NULL,1,'N(H₂O) = 0.556 × 6.02 × 10²³ = 3.34 × 10²³ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7972,'chem12a2-mol-27',NULL,2,'n(CO₂) = 10.0 ÷ 44.0 = 0.227 mol, so N(CO₂) = 0.227 × 6.02 × 10²³ = 1.37 × 10²³ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7973,'chem12a2-mol-27',NULL,3,'the water sample contains more molecules because its molar mass is smaller [1].',1,1);
INSERT INTO rubric_criterion VALUES(7974,'chem12a2-mol-28',NULL,0,'n = 3.01 × 10²² ÷ 6.02 × 10²³ = 0.0500 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7975,'chem12a2-mol-28',NULL,1,'M = m ÷ n = 3.20 ÷ 0.0500 = 64.0 g mol⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(7976,'chem12a2-mol-28',NULL,2,'this matches SO₂ (64.1 g mol⁻¹), not O₂ (32.0) or N₂ (28.0) [1].',1,1);
INSERT INTO rubric_criterion VALUES(7977,'chem12a2-mol-29',NULL,0,'n(Al) = 1000 ÷ 27.0 = 37.0 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7978,'chem12a2-mol-29',NULL,1,'N = 37.0 × 6.02 × 10²³ = 2.23 × 10²⁵ atoms [1].',1,1);
INSERT INTO rubric_criterion VALUES(7979,'chem12a2-mol-30',NULL,0,'M(NaCl) = 23.0 + 35.5 = 58.5 g mol⁻¹, so n = 2.34 ÷ 58.5 = 0.0400 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7980,'chem12a2-mol-30',NULL,1,'each formula unit gives 2 ions (Na⁺ and Cl⁻), so n(ions) = 0.0800 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7981,'chem12a2-mol-30',NULL,2,'N = 0.0800 × 6.02 × 10²³ = 4.82 × 10²² ions [1].',1,1);
INSERT INTO rubric_criterion VALUES(7982,'chem12a2-mol-31',NULL,0,'M(Na₂CO₃·10H₂O) = 106.0 + 10(18.0) = 286.0 g mol⁻¹, so n = 2.86 ÷ 286.0 = 0.0100 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7983,'chem12a2-mol-31',NULL,1,'n(H₂O) = 10 × 0.0100 = 0.100 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(7984,'chem12a2-mol-31',NULL,2,'m(H₂O) = 0.100 × 18.0 = 1.80 g [1];',1,1);
INSERT INTO rubric_criterion VALUES(7985,'chem12a2-mol-31',NULL,3,'n(H) = 2 × 0.100 = 0.200 mol, so N = 0.200 × 6.02 × 10²³ = 1.20 × 10²³ atoms [1].',1,1);
INSERT INTO rubric_criterion VALUES(7987,'vce-chem12-mo-c1',NULL,0,'1.8 × 10²⁴ atoms',2,1);
INSERT INTO rubric_criterion VALUES(7993,'chem12a2-emp-6',NULL,0,'In 100 g: n(C) = 85.6 ÷ 12.0 = 7.13 mol and n(H) = 14.4 ÷ 1.0 = 14.4 mol;',1,1);
INSERT INTO rubric_criterion VALUES(7994,'chem12a2-emp-6',NULL,1,'ratio 7.13 : 14.4 = 1 : 2.02 ≈ 1 : 2, so the empirical formula is CH₂ (M = 14.0 g mol⁻¹);',1,1);
INSERT INTO rubric_criterion VALUES(7995,'chem12a2-emp-6',NULL,2,'56.0 ÷ 14.0 = 4, so the molecular formula is C₄H₈.',1,1);
INSERT INTO rubric_criterion VALUES(7996,'chem12a2-emp-7',NULL,0,'m(H₂O) lost = 2.50 − 1.60 = 0.90 g, so n(H₂O) = 0.90 ÷ 18.0 = 0.050 mol;',1,1);
INSERT INTO rubric_criterion VALUES(7997,'chem12a2-emp-7',NULL,1,'M(CuSO₄) = 63.5 + 32.1 + 64.0 = 159.6 g mol⁻¹, so n(CuSO₄) = 1.60 ÷ 159.6 = 0.0100 mol;',1,1);
INSERT INTO rubric_criterion VALUES(7998,'chem12a2-emp-7',NULL,2,'ratio H₂O : CuSO₄ = 0.050 : 0.0100 = 5, so x = 5 (CuSO₄·5H₂O).',1,1);
INSERT INTO rubric_criterion VALUES(7999,'chem12a2-emp-8',NULL,0,'M(Fe₂O₃) = 2(55.8) + 3(16.0) = 159.6 g mol⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(8000,'chem12a2-emp-8',NULL,1,'%Fe = 111.6 ÷ 159.6 × 100 = 69.9%;',1,1);
INSERT INTO rubric_criterion VALUES(8001,'chem12a2-emp-8',NULL,2,'m(Fe₂O₃) = 0.800 × 500 = 400 kg, so m(Fe) = 0.699 × 400 = 280 kg (2.80 × 10² kg).',1,1);
INSERT INTO rubric_criterion VALUES(8016,'chem12a2-emp-23',NULL,0,'M(Al₂(SO₄)₃) = 2(27.0) + 3(32.1) + 12(16.0) = 342.3 g mol⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8017,'chem12a2-emp-23',NULL,1,'%O = 192.0 ÷ 342.3 × 100 = 56.1% [1].',1,1);
INSERT INTO rubric_criterion VALUES(8018,'chem12a2-emp-24',NULL,0,'n(Pb) = 2.07 ÷ 207 = 0.0100 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8019,'chem12a2-emp-24',NULL,1,'n(O) = 0.320 ÷ 16.0 = 0.0200 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8020,'chem12a2-emp-24',NULL,2,'ratio Pb : O = 1 : 2, so the empirical formula is PbO₂ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8021,'chem12a2-emp-25',NULL,0,'n(C) = n(CO₂) = 2.20 ÷ 44.0 = 0.0500 mol, so m(C) = 0.600 g [1];',1,1);
INSERT INTO rubric_criterion VALUES(8022,'chem12a2-emp-25',NULL,1,'n(H) = 2 × 1.35 ÷ 18.0 = 0.150 mol, so m(H) = 0.150 g [1];',1,1);
INSERT INTO rubric_criterion VALUES(8023,'chem12a2-emp-25',NULL,2,'m(O) = 1.15 − 0.600 − 0.150 = 0.400 g, so n(O) = 0.400 ÷ 16.0 = 0.0250 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8024,'chem12a2-emp-25',NULL,3,'ratio C : H : O = 0.0500 : 0.150 : 0.0250 = 2 : 6 : 1, so the empirical formula is C₂H₆O [1].',1,1);
INSERT INTO rubric_criterion VALUES(8025,'chem12a2-emp-26',NULL,0,'In 100 g: m(H₂O) = 62.9 g and m(Na₂CO₃) = 37.1 g; n(H₂O) = 62.9 ÷ 18.0 = 3.49 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8026,'chem12a2-emp-26',NULL,1,'M(Na₂CO₃) = 106.0 g mol⁻¹, so n(Na₂CO₃) = 37.1 ÷ 106.0 = 0.350 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8027,'chem12a2-emp-26',NULL,2,'ratio H₂O : Na₂CO₃ = 3.49 ÷ 0.350 ≈ 10, so x = 10 [1].',1,1);
INSERT INTO rubric_criterion VALUES(8028,'chem12a2-emp-27',NULL,0,'M(C₃H₄O₃) = 3(12.0) + 4(1.0) + 3(16.0) = 88.0 g mol⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8029,'chem12a2-emp-27',NULL,1,'176 ÷ 88.0 = 2, so the molecular formula is C₆H₈O₆ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8030,'chem12a2-emp-28',NULL,0,'(a) Cleaning removes the layer of magnesium oxide already on the ribbon, so the initial mass is that of magnesium only and the mass of oxygen gained is not underestimated [1];',1,1);
INSERT INTO rubric_criterion VALUES(8031,'chem12a2-emp-28',NULL,1,'(b) constant mass shows that the reaction is complete and no more oxygen is being gained, so the mass of oxygen combined is accurate [1].',1,1);
INSERT INTO rubric_criterion VALUES(8032,'chem12a2-emp-29',NULL,0,'%Fe = 1.40 ÷ 2.20 × 100 = 63.6% [1];',1,1);
INSERT INTO rubric_criterion VALUES(8033,'chem12a2-emp-29',NULL,1,'m(S) = 2.20 − 1.40 = 0.80 g, so n(Fe) = 1.40 ÷ 55.8 = 0.0251 mol and n(S) = 0.80 ÷ 32.1 = 0.0249 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8034,'chem12a2-emp-29',NULL,2,'ratio Fe : S = 1 : 1, so the empirical formula is FeS [1].',1,1);
INSERT INTO rubric_criterion VALUES(8035,'chem12a2-emp-30',NULL,0,'In 100 g: n(C) = 49.0 ÷ 12.0 = 4.08 mol, n(H) = 2.7 ÷ 1.0 = 2.7 mol, n(Cl) = 48.3 ÷ 35.5 = 1.36 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8036,'chem12a2-emp-30',NULL,1,'dividing by 1.36 gives C : H : Cl = 3 : 2 : 1, so the empirical formula is C₃H₂Cl [1];',1,1);
INSERT INTO rubric_criterion VALUES(8037,'chem12a2-emp-30',NULL,2,'M(C₃H₂Cl) = 36.0 + 2.0 + 35.5 = 73.5 g mol⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8038,'chem12a2-emp-30',NULL,3,'147 ÷ 73.5 = 2, so the molecular formula is C₆H₄Cl₂ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8039,'chem12a2-emp-31',NULL,0,'Mass of chlorine = 6.67 − 1.35 = 5.32 g [1];',1,1);
INSERT INTO rubric_criterion VALUES(8040,'chem12a2-emp-31',NULL,1,'n(Al) = 1.35 ÷ 27.0 = 0.0500 mol and n(Cl) = 5.32 ÷ 35.5 = 0.150 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8041,'chem12a2-emp-31',NULL,2,'ratio Al : Cl = 1 : 3, so the empirical formula is AlCl₃ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8042,'vce-chem12-pc-c1',NULL,0,'Empirical formula CH₂O;',1,1);
INSERT INTO rubric_criterion VALUES(8043,'vce-chem12-pc-c1',NULL,1,'molecular formula C₆H₁₂O₆',2,1);
INSERT INTO rubric_criterion VALUES(8049,'chem12a2-hc-6',NULL,0,'(a) pentane;',1,1);
INSERT INTO rubric_criterion VALUES(8050,'chem12a2-hc-6',NULL,1,'(b) but-1-yne;',1,1);
INSERT INTO rubric_criterion VALUES(8051,'chem12a2-hc-6',NULL,2,'(c) 2-methylpropane (methylpropane is also accepted).',1,1);
INSERT INTO rubric_criterion VALUES(8052,'chem12a2-hc-7',NULL,0,'Both are non-polar, so the only intermolecular forces are dispersion forces, and both have the same number of electrons;',1,1);
INSERT INTO rubric_criterion VALUES(8053,'chem12a2-hc-7',NULL,1,'pentane is a linear (unbranched) molecule, so its molecules have a larger surface area of contact and can approach more closely;',1,1);
INSERT INTO rubric_criterion VALUES(8054,'chem12a2-hc-7',NULL,2,'this gives stronger dispersion forces in pentane, needing more energy to separate the molecules, hence a higher boiling point than the compact, spherical 2,2-dimethylpropane.',1,1);
INSERT INTO rubric_criterion VALUES(8055,'chem12a2-hc-8',NULL,0,'(a) C₃H₈(g) + 5O₂(g) → 3CO₂(g) + 4H₂O(l);',1,1);
INSERT INTO rubric_criterion VALUES(8056,'chem12a2-hc-8',NULL,1,'(b) the chain should be numbered from the end that gives the branch the lowest locant;',1,1);
INSERT INTO rubric_criterion VALUES(8057,'chem12a2-hc-8',NULL,2,'the correct name is 2-methylbutane.',1,1);
INSERT INTO rubric_criterion VALUES(8071,'chem12a2-hc-22',NULL,0,'Saturated hydrocarbons contain only single C–C bonds, e.g. propane [1];',1,1);
INSERT INTO rubric_criterion VALUES(8072,'chem12a2-hc-22',NULL,1,'unsaturated hydrocarbons contain at least one C=C or C≡C bond, e.g. ethene [1].',1,1);
INSERT INTO rubric_criterion VALUES(8073,'chem12a2-hc-23',NULL,0,'Alkanes CₙH₂ₙ₊₂ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8074,'chem12a2-hc-23',NULL,1,'alkenes CₙH₂ₙ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8075,'chem12a2-hc-23',NULL,2,'alkynes CₙH₂ₙ₋₂ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8076,'chem12a2-hc-24',NULL,0,'(a) but-1-ene [1];',1,1);
INSERT INTO rubric_criterion VALUES(8077,'chem12a2-hc-24',NULL,1,'(b) 2-methylpentane [1];',1,1);
INSERT INTO rubric_criterion VALUES(8078,'chem12a2-hc-24',NULL,2,'(c) but-2-yne [1].',1,1);
INSERT INTO rubric_criterion VALUES(8079,'chem12a2-hc-25',NULL,0,'(a) CH₃C(CH₃)=CHCH₃ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8080,'chem12a2-hc-25',NULL,1,'(b) HC≡CCH(CH₃)CH₂CH₃ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8081,'chem12a2-hc-26',NULL,0,'Hexane is non-polar and has only weak dispersion forces between its molecules [1];',1,1);
INSERT INTO rubric_criterion VALUES(8082,'chem12a2-hc-26',NULL,1,'water molecules are held by strong hydrogen bonds [1];',1,1);
INSERT INTO rubric_criterion VALUES(8083,'chem12a2-hc-26',NULL,2,'the forces that hexane could form with water are much weaker than the hydrogen bonds that would be broken, so hexane does not dissolve [1].',1,1);
INSERT INTO rubric_criterion VALUES(8084,'chem12a2-hc-27',NULL,0,'n(C₃H₈) = 11.0 ÷ 44.0 = 0.250 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8085,'chem12a2-hc-27',NULL,1,'n(CO₂) = 3 × 0.250 = 0.750 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8086,'chem12a2-hc-27',NULL,2,'m(CO₂) = 0.750 × 44.0 = 33.0 g [1].',1,1);
INSERT INTO rubric_criterion VALUES(8087,'chem12a2-hc-28',NULL,0,'Add bromine water (a few drops, shaking) to a sample of each [1];',1,1);
INSERT INTO rubric_criterion VALUES(8088,'chem12a2-hc-28',NULL,1,'but-1-ene decolourises the orange-brown bromine water quickly because it is unsaturated [1];',1,1);
INSERT INTO rubric_criterion VALUES(8089,'chem12a2-hc-28',NULL,2,'butane causes no colour change in the dark because it is saturated [1].',1,1);
INSERT INTO rubric_criterion VALUES(8092,'chem12a2-hc-31',NULL,0,'n(C₂H₆) = 5.00 ÷ 30.0 = 0.167 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8093,'chem12a2-hc-31',NULL,1,'n(CO₂) = 2 × 0.167 = 0.333 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8094,'chem12a2-hc-31',NULL,2,'V(CO₂) = 0.333 × 24.8 = 8.27 L [1].',1,1);
INSERT INTO rubric_criterion VALUES(8101,'chem12a2-fg-6',NULL,0,'Ethanol has a polar –OH group with H bonded to highly electronegative O;',1,1);
INSERT INTO rubric_criterion VALUES(8102,'chem12a2-fg-6',NULL,1,'it can form hydrogen bonds with water molecules, which release enough energy to compensate for breaking hydrogen bonds between water molecules, so ethanol mixes with water;',1,1);
INSERT INTO rubric_criterion VALUES(8103,'chem12a2-fg-6',NULL,2,'ethane is non-polar with only dispersion forces, so it cannot form hydrogen bonds with water and would disrupt the water hydrogen-bond network without compensating attractions, so it does not dissolve.',1,1);
INSERT INTO rubric_criterion VALUES(8104,'chem12a2-fg-7',NULL,0,'Fifth member has n = 5: pentan-1-ol, C₅H₁₁OH (C₅H₁₂O);',1,1);
INSERT INTO rubric_criterion VALUES(8105,'chem12a2-fg-7',NULL,1,'M = 5(12.0) + 12(1.0) + 16.0 = 88.0 g mol⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(8106,'chem12a2-fg-8',NULL,0,'(a) carboxyl group, propanoic acid;',1,1);
INSERT INTO rubric_criterion VALUES(8107,'chem12a2-fg-8',NULL,1,'(b) bromo (halo) group, 2-bromopropane;',1,1);
INSERT INTO rubric_criterion VALUES(8108,'chem12a2-fg-8',NULL,2,'(c) carbon–carbon double bond, propene (prop-1-ene).',1,1);
INSERT INTO rubric_criterion VALUES(8120,'chem12a2-fg-20',NULL,0,'CH₃CH₂CH₂Cl is 1-chloropropane [1];',1,1);
INSERT INTO rubric_criterion VALUES(8121,'chem12a2-fg-20',NULL,1,'CH₃CHClCH₃ is 2-chloropropane [1].',1,1);
INSERT INTO rubric_criterion VALUES(8122,'chem12a2-fg-21',NULL,0,'General formula CₙH₂ₙ₊₂, so 2n + 2 = 22 and n = 10, giving C₁₀H₂₂ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8123,'chem12a2-fg-21',NULL,1,'the name is decane [1].',1,1);
INSERT INTO rubric_criterion VALUES(8124,'chem12a2-fg-22',NULL,0,'Alkanes contain only C–C single bonds whereas alkenes contain a C=C double bond [1];',1,1);
INSERT INTO rubric_criterion VALUES(8125,'chem12a2-fg-22',NULL,1,'hex-1-ene decolourises the orange/brown bromine water [1];',1,1);
INSERT INTO rubric_criterion VALUES(8126,'chem12a2-fg-22',NULL,2,'hexane does not react so the bromine water stays orange/brown [1].',1,1);
INSERT INTO rubric_criterion VALUES(8127,'chem12a2-fg-23',NULL,0,'Both are non-polar, so the only intermolecular forces are dispersion forces [1];',1,1);
INSERT INTO rubric_criterion VALUES(8128,'chem12a2-fg-23',NULL,1,'butane has more electrons (larger molecules), so stronger dispersion forces that require more energy to overcome [1].',1,1);
INSERT INTO rubric_criterion VALUES(8129,'chem12a2-fg-24',NULL,0,'Hydroxyl group, –OH [1];',1,1);
INSERT INTO rubric_criterion VALUES(8130,'chem12a2-fg-24',NULL,1,'carboxyl group, –COOH [1].',1,1);
INSERT INTO rubric_criterion VALUES(8131,'chem12a2-fg-25',NULL,0,'Molecular formula is C₄H₉Cl [1];',1,1);
INSERT INTO rubric_criterion VALUES(8132,'chem12a2-fg-25',NULL,1,'M = 4(12.0) + 9(1.0) + 35.5 = 92.5 g mol⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8133,'chem12a2-fg-25',NULL,2,'%Cl = 35.5 ÷ 92.5 × 100 = 38.4% [1].',1,1);
INSERT INTO rubric_criterion VALUES(8134,'chem12a2-fg-26',NULL,0,'Ester group, –COO– [1];',1,1);
INSERT INTO rubric_criterion VALUES(8135,'chem12a2-fg-26',NULL,1,'carboxylic acid is propanoic acid [1];',1,1);
INSERT INTO rubric_criterion VALUES(8136,'chem12a2-fg-26',NULL,2,'alkanol is methanol [1].',1,1);
INSERT INTO rubric_criterion VALUES(8137,'chem12a2-fg-27',NULL,0,'The –OH group forms hydrogen bonds with water, so methanol, with a small non-polar part, mixes with water [1];',1,1);
INSERT INTO rubric_criterion VALUES(8138,'chem12a2-fg-27',NULL,1,'decan-1-ol has a long non-polar hydrocarbon chain that forms only dispersion forces with water [1];',1,1);
INSERT INTO rubric_criterion VALUES(8139,'chem12a2-fg-27',NULL,2,'the energy released by hydrogen bonding is not enough to disrupt the hydrogen bonds between water molecules, so decan-1-ol is insoluble [1].',1,1);
INSERT INTO rubric_criterion VALUES(8142,'chem12a2-fg-30',NULL,0,'(a) 2-chlorobutane, a haloalkane (chloro group, –Cl) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8143,'chem12a2-fg-30',NULL,1,'(b) pentan-3-ol, an alkanol (hydroxyl group, –OH) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8144,'chem12a2-fg-31',NULL,0,'Methylamine has an N–H group, so its molecules form hydrogen bonds with each other, whereas ethane molecules are held together only by weak dispersion forces [1];',1,1);
INSERT INTO rubric_criterion VALUES(8145,'chem12a2-fg-31',NULL,1,'more energy is needed to overcome the hydrogen bonds, so methylamine has the higher boiling point [1].',1,1);
INSERT INTO rubric_criterion VALUES(8152,'chem12a2-ap-6',NULL,0,'Monomer is tetrafluoroethene, CF₂=CF₂;',1,1);
INSERT INTO rubric_criterion VALUES(8153,'chem12a2-ap-6',NULL,1,'repeating unit is –CF₂–CF₂–;',1,1);
INSERT INTO rubric_criterion VALUES(8154,'chem12a2-ap-6',NULL,2,'the C=C double bond of each monomer breaks and monomers join end to end with no other product (no small molecule such as water is lost), so it is addition polymerisation.',1,1);
INSERT INTO rubric_criterion VALUES(8155,'chem12a2-ap-7',NULL,0,'Longer chains have more electrons and greater contact area between chains, so the dispersion forces between chains are stronger in total;',1,1);
INSERT INTO rubric_criterion VALUES(8156,'chem12a2-ap-7',NULL,1,'more energy is needed for the chains to slide past each other, so the polymer softens at a higher temperature.',1,1);
INSERT INTO rubric_criterion VALUES(8157,'chem12a2-ap-8',NULL,0,'n CH₂=CH(C₆H₅) → –[CH₂–CH(C₆H₅)]ₙ–; the repeating unit shows the double bond opened and a benzene ring (phenyl group) on every second carbon;',1,1);
INSERT INTO rubric_criterion VALUES(8158,'chem12a2-ap-8',NULL,1,'e.g.',1,1);
INSERT INTO rubric_criterion VALUES(8159,'chem12a2-ap-8',NULL,2,'it is rigid/brittle at room temperature because the bulky phenyl groups restrict chain movement (or it is a thermoplastic that softens on heating because there are no cross-links).',1,1);
INSERT INTO rubric_criterion VALUES(8173,'chem12a2-ap-22',NULL,0,'A monomer is a small molecule that can join with many others to form a polymer [1].',1,1);
INSERT INTO rubric_criterion VALUES(8174,'chem12a2-ap-22',NULL,1,'A polymer is a very large molecule made of many repeating units joined together [1].',1,1);
INSERT INTO rubric_criterion VALUES(8175,'chem12a2-ap-22',NULL,2,'Addition polymerisation requires a carbon–carbon double bond (C=C) in the monomer [1].',1,1);
INSERT INTO rubric_criterion VALUES(8176,'chem12a2-ap-23',NULL,0,'n CH₂=CH(CH₃) → –[CH₂–CH(CH₃)]ₙ– [1] with the double bond opened and a methyl group on every second carbon of the chain, with no other product formed [1].',2,1);
INSERT INTO rubric_criterion VALUES(8177,'chem12a2-ap-24',NULL,0,'Repeating unit is –CH₂–CHCl– (same formula as chloroethene, C₂H₃Cl) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8178,'chem12a2-ap-24',NULL,1,'M(C₂H₃Cl) = 2 × 12.0 + 3 × 1.0 + 35.5 = 62.5 g mol⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8179,'chem12a2-ap-24',NULL,2,'M(polymer) = 2500 × 62.5 = 1.56 × 10⁵ g mol⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8180,'chem12a2-ap-25',NULL,0,'(a) No atoms are lost in addition polymerisation, so mass of polyethene = 5.60 kg [1].',1,1);
INSERT INTO rubric_criterion VALUES(8181,'chem12a2-ap-25',NULL,1,'(b) n(C₂H₄) = 5600 ÷ 28.0 = 200 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8182,'chem12a2-ap-25',NULL,2,'each chain uses 4.00 × 10³ monomer units, so n(chains) = 200 ÷ 4.00 × 10³ [1] = 0.0500 mol [1].',2,1);
INSERT INTO rubric_criterion VALUES(8187,'chem12a2-ap-30',NULL,0,'The section is –CH₂–CHCl–CH₂–CHCl–CH₂–CHCl– (three –CH₂–CHCl– units joined end to end) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8188,'chem12a2-ap-30',NULL,1,'during polymerisation one bond of the C=C in each monomer breaks [1];',1,1);
INSERT INTO rubric_criterion VALUES(8189,'chem12a2-ap-30',NULL,2,'the freed electrons form new single bonds to neighbouring monomers, so the backbone contains only C–C single bonds [1].',1,1);
INSERT INTO rubric_criterion VALUES(8190,'chem12a2-ap-31',NULL,0,'Number of repeating units = 1.25 × 10⁵ ÷ 62.5 = 2.00 × 10³ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8191,'chem12a2-ap-31',NULL,1,'each unit contributes two backbone carbon atoms, so 2 × 2.00 × 10³ = 4.00 × 10³ carbon atoms [1].',1,1);
INSERT INTO rubric_criterion VALUES(8198,'chem12a2-tt-6',NULL,0,'In a linear economy, fossil fuels are extracted to make PET, bottles are used once and then sent to landfill or become litter (take–make–dispose); in a circular economy, bottles are designed for recovery, collected (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(8199,'chem12a2-tt-6',NULL,1,'through container deposit schemes) and mechanically or chemically recycled into new bottles;',1,1);
INSERT INTO rubric_criterion VALUES(8200,'chem12a2-tt-6',NULL,2,'this reduces demand for new raw materials, energy use and waste, keeping the material in use for longer.',1,1);
INSERT INTO rubric_criterion VALUES(8201,'chem12a2-tt-7',NULL,0,'The resin chains are joined by covalent cross-links forming a rigid three-dimensional network;',1,1);
INSERT INTO rubric_criterion VALUES(8202,'chem12a2-tt-7',NULL,1,'heating gives the chains energy, but the strong covalent cross-links prevent them from sliding past one another, so the material does not soften or melt;',1,1);
INSERT INTO rubric_criterion VALUES(8203,'chem12a2-tt-7',NULL,2,'only at very high temperatures do covalent bonds break, causing decomposition (charring) rather than melting.',1,1);
INSERT INTO rubric_criterion VALUES(8204,'chem12a2-tt-8',NULL,0,'Bio-based means the carbon comes from a renewable biological feedstock (sugarcane);',1,1);
INSERT INTO rubric_criterion VALUES(8205,'chem12a2-tt-8',NULL,1,'however, bio-PE is chemically identical to fossil-derived polyethene, so microorganisms cannot readily break it down and it is not biodegradable;',1,1);
INSERT INTO rubric_criterion VALUES(8206,'chem12a2-tt-8',NULL,2,'an advantage is that it reduces use of finite fossil fuels, and the CO₂ absorbed by the sugarcane during growth can offset some of the emissions (and it can be recycled with ordinary PE).',1,1);
INSERT INTO rubric_criterion VALUES(8221,'chem12a2-tt-23',NULL,0,'Polyethene is a thermoplastic whose chains are held together only by weak dispersion forces [1];',1,1);
INSERT INTO rubric_criterion VALUES(8222,'chem12a2-tt-23',NULL,1,'heating overcomes these forces so the chains can slide and the material can be melted and remoulded [1];',1,1);
INSERT INTO rubric_criterion VALUES(8223,'chem12a2-tt-23',NULL,2,'vulcanised rubber has covalent sulfur cross-links between chains, which hold the chains in place, so it cannot melt and decomposes when heated strongly [1].',1,1);
INSERT INTO rubric_criterion VALUES(8224,'chem12a2-tt-24',NULL,0,'Mechanical recycling involves sorting, cleaning, shredding and melting the PET so that it can be reshaped into new products without changing the polymer chemically [1]; chemical recycling breaks the polymer into monomers or small molecules (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(8225,'chem12a2-tt-24',NULL,1,'by hydrolysis) which are purified and repolymerised [1];',1,1);
INSERT INTO rubric_criterion VALUES(8226,'chem12a2-tt-24',NULL,2,'chemical recycling can give material equal in quality to new PET, whereas mechanical recycling often gives a lower-quality product because chains shorten and contaminants build up [1].',1,1);
INSERT INTO rubric_criterion VALUES(8227,'chem12a2-tt-25',NULL,0,'Order: reducing consumption, then recycling, then landfill [1];',1,1);
INSERT INTO rubric_criterion VALUES(8228,'chem12a2-tt-25',NULL,1,'reducing consumption is best because less material and energy is used and no waste is created [1];',1,1);
INSERT INTO rubric_criterion VALUES(8229,'chem12a2-tt-25',NULL,2,'recycling keeps materials in use and saves raw materials, whereas landfill loses the material permanently and uses land [1].',1,1);
INSERT INTO rubric_criterion VALUES(8230,'chem12a2-tt-26',NULL,0,'Mass of PET in waste = 0.65 × 12.0 [1] = 7.80 t [1];',1,1);
INSERT INTO rubric_criterion VALUES(8231,'chem12a2-tt-26',NULL,1,'mass recovered = 0.70 × 7.80 = 5.46 t [1].',2,1);
INSERT INTO rubric_criterion VALUES(8232,'chem12a2-tt-27',NULL,0,'Make the tubs from a thermoplastic such as polypropene or PET instead [1];',1,1);
INSERT INTO rubric_criterion VALUES(8233,'chem12a2-tt-27',NULL,1,'a thermoplastic can be melted and remoulded because it has no covalent cross-links, so it can be mechanically recycled [1].',1,1);
INSERT INTO rubric_criterion VALUES(8234,'chem12a2-tt-28',NULL,0,'Landfill is cool and has little oxygen and moisture, so conditions are unsuitable for the microorganisms that degrade PLA, which needs the high temperatures and moisture of industrial composting [1];',1,1);
INSERT INTO rubric_criterion VALUES(8235,'chem12a2-tt-28',NULL,1,'composting allows PLA to break down into carbon dioxide, water and biomass, which can be returned to soil rather than being buried [1].',1,1);
INSERT INTO rubric_criterion VALUES(8236,'chem12a2-tt-29',NULL,0,'Downcycling is recycling a material into a product of lower quality or value than the original [1];',1,1);
INSERT INTO rubric_criterion VALUES(8237,'chem12a2-tt-29',NULL,1,'during melting and reprocessing, polymer chains can shorten and impurities or mixed polymers contaminate the plastic [1];',1,1);
INSERT INTO rubric_criterion VALUES(8238,'chem12a2-tt-29',NULL,2,'this reduces strength and clarity, so the material is used for less demanding products such as park benches rather than new food-grade bottles [1].',1,1);
INSERT INTO rubric_criterion VALUES(8239,'chem12a2-tt-30',NULL,0,'Benefit: the refund encourages people to return bottles, increasing collection rates and reducing litter and landfill [1];',1,1);
INSERT INTO rubric_criterion VALUES(8240,'chem12a2-tt-30',NULL,1,'benefit: returned bottles form a clean, single-type stream that is easier to recycle into food-grade material, reducing demand for new fossil-fuel-based PET [1];',1,1);
INSERT INTO rubric_criterion VALUES(8241,'chem12a2-tt-30',NULL,2,'limitation: it covers only certain containers and relies on consumer participation, and collection and transport cost energy and money [1];',1,1);
INSERT INTO rubric_criterion VALUES(8242,'chem12a2-tt-30',NULL,3,'overall it keeps materials in use for longer but should be combined with reduction and reuse strategies [1].',1,1);
INSERT INTO rubric_criterion VALUES(8250,'chem12a2-wat-6',NULL,0,'Water has a high specific heat capacity;',1,1);
INSERT INTO rubric_criterion VALUES(8251,'chem12a2-wat-6',NULL,1,'this is because energy is used to disrupt the extensive hydrogen bonding between water molecules, so a large amount of energy is needed to change its temperature;',1,1);
INSERT INTO rubric_criterion VALUES(8252,'chem12a2-wat-6',NULL,2,'large bodies of water such as Port Phillip Bay therefore absorb heat during the day and release it at night with only small temperature changes, moderating the air temperature of nearby land.',1,1);
INSERT INTO rubric_criterion VALUES(8253,'chem12a2-wat-7',NULL,0,'A hydrogen bond is an attraction between a hydrogen atom bonded to a highly electronegative atom (O) in one molecule and a lone pair on an O atom of a neighbouring molecule;',1,1);
INSERT INTO rubric_criterion VALUES(8254,'chem12a2-wat-7',NULL,1,'the large electronegativity difference makes H strongly δ+ and O strongly δ−;',1,1);
INSERT INTO rubric_criterion VALUES(8255,'chem12a2-wat-7',NULL,2,'each water molecule has two H atoms (each can bond to another molecule) and two lone pairs on O (each can accept a hydrogen bond), giving up to four hydrogen bonds.',1,1);
INSERT INTO rubric_criterion VALUES(8256,'chem12a2-wat-8',NULL,0,'ΔT = q ÷ (mc) = 15 000 ÷ (200 × 4.18) = 17.9 °C;',1,1);
INSERT INTO rubric_criterion VALUES(8257,'chem12a2-wat-8',NULL,1,'final temperature = 18.0 + 17.9 = 35.9 °C.',1,1);
INSERT INTO rubric_criterion VALUES(8272,'chem12a2-wat-23',NULL,0,'Water molecules at the surface are attracted inwards and sideways by hydrogen bonds to neighbouring molecules, producing high surface tension [1];',1,1);
INSERT INTO rubric_criterion VALUES(8273,'chem12a2-wat-23',NULL,1,'this forms a skin that can support the small mass of the insect without the surface breaking [1].',1,1);
INSERT INTO rubric_criterion VALUES(8274,'chem12a2-wat-24',NULL,0,'Nitrogen is small and highly electronegative, so the N–H bonds are very polar and NH₃ molecules form hydrogen bonds between them [1];',1,1);
INSERT INTO rubric_criterion VALUES(8275,'chem12a2-wat-24',NULL,1,'phosphorus is larger and less electronegative, so PH₃ cannot form hydrogen bonds and is held only by weaker dispersion forces and weak dipole–dipole attractions [1];',1,1);
INSERT INTO rubric_criterion VALUES(8276,'chem12a2-wat-24',NULL,2,'hydrogen bonds are stronger, so more energy is needed to separate NH₃ molecules, giving ammonia the higher boiling point despite its smaller molar mass [1].',1,1);
INSERT INTO rubric_criterion VALUES(8277,'chem12a2-wat-25',NULL,0,'Heating: q = mcΔT = 500 × 4.18 × 85.0 = 1.78 × 10⁵ J [1];',1,1);
INSERT INTO rubric_criterion VALUES(8278,'chem12a2-wat-25',NULL,1,'= 178 kJ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8279,'chem12a2-wat-25',NULL,2,'n(H₂O) = 500 ÷ 18.0 = 27.8 mol, vaporisation energy = 27.8 × 40.7 = 1.13 × 10³ kJ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8280,'chem12a2-wat-25',NULL,3,'total = 178 + 1130 = 1.31 × 10³ kJ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8281,'chem12a2-wat-26',NULL,0,'q = mcΔT = 1500 × 4.18 × 78.0 [1] = 4.89 × 10⁵ J [1];',1,1);
INSERT INTO rubric_criterion VALUES(8282,'chem12a2-wat-26',NULL,1,'time = 4.89 × 10⁵ ÷ 2000 = 245 s (about 4.1 minutes) [1].',2,1);
INSERT INTO rubric_criterion VALUES(8283,'chem12a2-wat-27',NULL,0,'In ice, hydrogen bonds hold the molecules in a rigid, open lattice with more space between molecules than in liquid water [1];',1,1);
INSERT INTO rubric_criterion VALUES(8284,'chem12a2-wat-27',NULL,1,'so ice has a lower density than liquid water and floats at the surface [1];',1,1);
INSERT INTO rubric_criterion VALUES(8285,'chem12a2-wat-27',NULL,2,'the floating layer of ice insulates the water below, so it remains liquid and aquatic life can survive [1].',1,1);
INSERT INTO rubric_criterion VALUES(8286,'chem12a2-wat-28',NULL,0,'Oxygen is much more electronegative than hydrogen, so each O–H bond is polar with O partially negative (δ−) and H partially positive (δ+) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8287,'chem12a2-wat-28',NULL,1,'the molecule is bent (about 104.5°) because of the two lone pairs on oxygen [1];',1,1);
INSERT INTO rubric_criterion VALUES(8288,'chem12a2-wat-28',NULL,2,'because of the bent shape, the bond dipoles do not cancel, so the molecule has a net dipole [1].',1,1);
INSERT INTO rubric_criterion VALUES(8289,'chem12a2-wat-29',NULL,0,'Covalent O–H bonds are strong bonds within a molecule formed by sharing of electrons, whereas hydrogen bonds are much weaker intermolecular attractions between δ+ H and a lone pair on O of a neighbouring molecule [1];',1,1);
INSERT INTO rubric_criterion VALUES(8290,'chem12a2-wat-29',NULL,1,'when water evaporates only the hydrogen bonds between molecules are broken, and the covalent bonds remain intact [1].',1,1);
INSERT INTO rubric_criterion VALUES(8291,'chem12a2-wat-30',NULL,0,'Energy lost by the hot water equals energy gained by the cold water [1];',1,1);
INSERT INTO rubric_criterion VALUES(8292,'chem12a2-wat-30',NULL,1,'100 × 4.18 × (80.0 − T) = 200 × 4.18 × (T − 20.0) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8293,'chem12a2-wat-30',NULL,2,'8000 − 100T = 200T − 4000, so T = 40.0 °C [1].',1,1);
INSERT INTO rubric_criterion VALUES(8294,'chem12a2-wat-31',NULL,0,'Methanol has a polar O–H group that can form hydrogen bonds with water molecules [1];',1,1);
INSERT INTO rubric_criterion VALUES(8295,'chem12a2-wat-31',NULL,1,'the new methanol–water hydrogen bonds are comparable in strength to those broken in water and in methanol, so the two mix [1];',1,1);
INSERT INTO rubric_criterion VALUES(8296,'chem12a2-wat-31',NULL,2,'pentane is non-polar and can form only weak dispersion forces with water, which cannot compensate for the hydrogen bonds that would be broken between water molecules, so it does not mix [1].',1,1);
INSERT INTO rubric_criterion VALUES(8303,'chem12a2-sol-6',NULL,0,'Water molecules are polar;',1,1);
INSERT INTO rubric_criterion VALUES(8304,'chem12a2-sol-6',NULL,1,'the δ− oxygen ends are attracted to Na⁺ ions and the δ+ hydrogen ends to Cl⁻ ions at the surface of the lattice (ion–dipole attractions);',1,1);
INSERT INTO rubric_criterion VALUES(8305,'chem12a2-sol-6',NULL,2,'these attractions are strong enough to overcome the ionic bonding, so ions are pulled from the lattice and become surrounded by water molecules (hydrated), dispersing through the solution as Na⁺(aq) and Cl⁻(aq).',1,1);
INSERT INTO rubric_criterion VALUES(8306,'chem12a2-sol-7',NULL,0,'Cu²⁺(aq) + 2OH⁻(aq) → Cu(OH)₂(s);',1,1);
INSERT INTO rubric_criterion VALUES(8307,'chem12a2-sol-7',NULL,1,'a pale blue precipitate forms (and the blue colour of the solution fades);',1,1);
INSERT INTO rubric_criterion VALUES(8308,'chem12a2-sol-7',NULL,2,'the spectator ions are Na⁺ and SO₄²⁻.',1,1);
INSERT INTO rubric_criterion VALUES(8309,'chem12a2-sol-8',NULL,0,'The ion is Ba²⁺;',1,1);
INSERT INTO rubric_criterion VALUES(8310,'chem12a2-sol-8',NULL,1,'barium sulfate is insoluble, so Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s) explains the white precipitate;',1,1);
INSERT INTO rubric_criterion VALUES(8311,'chem12a2-sol-8',NULL,2,'if Ag⁺ were present, adding chloride would have formed a white precipitate of AgCl, but none formed (BaCl₂ is soluble).',1,1);
INSERT INTO rubric_criterion VALUES(8325,'chem12a2-sol-22',NULL,0,'Ca²⁺(aq) + CO₃²⁻(aq) → CaCO₃(s) [1] A white precipitate forms [1] The spectator ions are Na⁺ and Cl⁻ [1]',3,1);
INSERT INTO rubric_criterion VALUES(8326,'chem12a2-sol-23',NULL,0,'n(AgNO₃) = 0.0250 × 0.200 = 0.00500 mol [1] Ag⁺ : AgCl = 1 : 1, so n(AgCl) = 0.00500 mol [1] m(AgCl) = 0.00500 × 143.4 = 0.717 g [1]',3,1);
INSERT INTO rubric_criterion VALUES(8327,'chem12a2-sol-24',NULL,0,'Add barium nitrate solution to a sample of each solution [1] The one that forms a white precipitate is sodium sulfate, because Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s) [1] Add silver nitrate solution to samples of the other two solutions [1] The one that forms a white precipitate (AgCl) is sodium chloride and the one with no precipitate is sodium nitrate [1]',4,1);
INSERT INTO rubric_criterion VALUES(8328,'chem12a2-sol-25',NULL,0,'For an ionic compound to dissolve, the energy released by ion–dipole attractions between the ions and water molecules must be enough to overcome the attractions between ions in the lattice [1] In AgCl the attractions between the Ag⁺ and Cl⁻ ions in the lattice are stronger than the ion–dipole attractions with water, so it stays solid, whereas for NaCl the ion–dipole attractions are sufficient so it dissolves [1]',2,1);
INSERT INTO rubric_criterion VALUES(8329,'chem12a2-sol-26',NULL,0,'Mass dissolved at 60 °C = 46 × 2.5 = 115 g [1] Mass that can stay dissolved at 20 °C = 34 × 2.5 = 85 g [1] Mass crystallising = 115 − 85 = 30 g [1]',3,1);
INSERT INTO rubric_criterion VALUES(8330,'chem12a2-sol-27',NULL,0,'Add sodium carbonate solution so that carbonate ions react with lead(II) ions: Pb²⁺(aq) + CO₃²⁻(aq) → PbCO₃(s) [1] Lead(II) carbonate is insoluble so the lead is removed from solution as a precipitate, while the Na⁺ ions remain in solution as spectator ions [1] The precipitate is separated from the water by filtration [1]',3,1);
INSERT INTO rubric_criterion VALUES(8331,'chem12a2-sol-28',NULL,0,'Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s) [1] Ba²⁺ and SO₄²⁻ are each 0.00500 mol, so they react completely with none in excess [1] n(Na⁺) = 2 × 0.00500 = 0.0100 mol and n(Cl⁻) = 2 × 0.00500 = 0.0100 mol, in a total volume of 0.100 L [1] [Na⁺] = [Cl⁻] = 0.0100 ÷ 0.100 = 0.100 mol L⁻¹ [1]',4,1);
INSERT INTO rubric_criterion VALUES(8332,'chem12a2-sol-29',NULL,0,'Al(NO₃)₃(aq) + 3KOH(aq) → Al(OH)₃(s) + 3KNO₃(aq) [1] Ionic form: Al³⁺(aq) + 3NO₃⁻(aq) + 3K⁺(aq) + 3OH⁻(aq) → Al(OH)₃(s) + 3K⁺(aq) + 3NO₃⁻(aq) [1] Cancelling spectator ions K⁺ and NO₃⁻ gives Al³⁺(aq) + 3OH⁻(aq) → Al(OH)₃(s) [1]',3,1);
INSERT INTO rubric_criterion VALUES(8340,'chem12a2-bl-6',NULL,0,'(a) HCO₃⁻(aq) + OH⁻(aq) → CO₃²⁻(aq) + H₂O(l);',1,1);
INSERT INTO rubric_criterion VALUES(8341,'chem12a2-bl-6',NULL,1,'(b) HCO₃⁻(aq) + H₃O⁺(aq) → H₂CO₃(aq) + H₂O(l) (or → CO₂(g) + 2H₂O(l));',1,1);
INSERT INTO rubric_criterion VALUES(8342,'chem12a2-bl-6',NULL,2,'an amphiprotic species can act as either a proton donor (acid) or a proton acceptor (base) depending on what it reacts with.',1,1);
INSERT INTO rubric_criterion VALUES(8343,'chem12a2-bl-7',NULL,0,'CH₃COOH / CH₃COO⁻ (acid / conjugate base);',1,1);
INSERT INTO rubric_criterion VALUES(8344,'chem12a2-bl-7',NULL,1,'H₃O⁺ / H₂O (conjugate acid / base).',1,1);
INSERT INTO rubric_criterion VALUES(8345,'chem12a2-bl-8',NULL,0,'(a) MgCO₃(s) + 2HCl(aq) → MgCl₂(aq) + H₂O(l) + CO₂(g);',1,1);
INSERT INTO rubric_criterion VALUES(8346,'chem12a2-bl-8',NULL,1,'(b) Zn(s) + 2HCl(aq) → ZnCl₂(aq) + H₂(g);',1,1);
INSERT INTO rubric_criterion VALUES(8347,'chem12a2-bl-8',NULL,2,'in both, bubbles of gas (effervescence) are seen and the solid dissolves.',1,1);
INSERT INTO rubric_criterion VALUES(8362,'chem12a2-bl-23',NULL,0,'A Brønsted–Lowry base is a proton (H⁺) acceptor [1].',1,1);
INSERT INTO rubric_criterion VALUES(8363,'chem12a2-bl-23',NULL,1,'CO₃²⁻(aq) + H₂O(l) ⇌ HCO₃⁻(aq) + OH⁻(aq) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8364,'chem12a2-bl-23',NULL,2,'The conjugate acid formed is HCO₃⁻ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8365,'chem12a2-bl-24',NULL,0,'HNO₃(aq) + H₂O(l) → H₃O⁺(aq) + NO₃⁻(aq) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8366,'chem12a2-bl-24',NULL,1,'It is a strong acid because it ionises (donates protons to water) essentially completely, so the equation has a single arrow [1].',1,1);
INSERT INTO rubric_criterion VALUES(8367,'chem12a2-bl-25',NULL,0,'CH₃COOH(aq) + H₂O(l) ⇌ CH₃COO⁻(aq) + H₃O⁺(aq) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8368,'chem12a2-bl-25',NULL,1,'Only a small fraction of molecules ionise, so the reaction does not go to completion and an equilibrium with mostly unionised CH₃COOH is established [1].',1,1);
INSERT INTO rubric_criterion VALUES(8369,'chem12a2-bl-26',NULL,0,'(a) H₂SO₄(aq) + 2NaOH(aq) → Na₂SO₄(aq) + 2H₂O(l) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8370,'chem12a2-bl-26',NULL,1,'(b) H₂SO₄(aq) + CuO(s) → CuSO₄(aq) + H₂O(l) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8371,'chem12a2-bl-26',NULL,2,'the black solid dissolves and the solution turns blue [1].',1,1);
INSERT INTO rubric_criterion VALUES(8372,'chem12a2-bl-27',NULL,0,'2CH₃COOH(aq) + CO₃²⁻(aq) → 2CH₃COO⁻(aq) + H₂O(l) + CO₂(g) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8373,'chem12a2-bl-27',NULL,1,'CH₃COOH is the proton donor (acid) and CO₃²⁻ is the proton acceptor (base) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8374,'chem12a2-bl-28',NULL,0,'H₂SO₄(aq) + H₂O(l) → HSO₄⁻(aq) + H₃O⁺(aq) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8375,'chem12a2-bl-28',NULL,1,'HSO₄⁻(aq) + H₂O(l) ⇌ SO₄²⁻(aq) + H₃O⁺(aq) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8376,'chem12a2-bl-29',NULL,0,'HCl(aq) + NaOH(aq) → NaCl(aq) + H₂O(l) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8377,'chem12a2-bl-29',NULL,1,'n(NaOH) = 0.100 × 0.0185 = 1.85 × 10⁻³ mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8378,'chem12a2-bl-29',NULL,2,'n(HCl) = 1.85 × 10⁻³ mol (1:1 ratio) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8379,'chem12a2-bl-29',NULL,3,'c(HCl) = 1.85 × 10⁻³ ÷ 0.0250 = 0.0740 M [1].',1,1);
INSERT INTO rubric_criterion VALUES(8380,'chem12a2-bl-30',NULL,0,'2H₂O(l) ⇌ H₃O⁺(aq) + OH⁻(aq) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8381,'chem12a2-bl-30',NULL,1,'one water molecule donates a proton (acts as an acid) while the other accepts it (acts as a base) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8382,'chem12a2-bl-31',NULL,0,'HCl is a strong acid and ionises completely, giving a high concentration of ions [1];',1,1);
INSERT INTO rubric_criterion VALUES(8383,'chem12a2-bl-31',NULL,1,'ethanoic acid is weak and only partly ionises, so fewer mobile ions are present to carry charge [1].',1,1);
INSERT INTO rubric_criterion VALUES(8391,'chem12a2-ph-6',NULL,0,'Strength describes the extent to which an acid ionises (donates protons) in water: a strong acid such as HCl ionises completely, while a weak acid such as CH₃COOH ionises only partially; concentration describes the amount of acid dissolved per litre of solution (mol L⁻¹);',1,1);
INSERT INTO rubric_criterion VALUES(8392,'chem12a2-ph-6',NULL,1,'so an acid can be strong but dilute (e.g. 0.001 mol L⁻¹ HCl) or weak but concentrated (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(8393,'chem12a2-ph-6',NULL,2,'10 mol L⁻¹ CH₃COOH).',1,1);
INSERT INTO rubric_criterion VALUES(8394,'chem12a2-ph-7',NULL,0,'n(HCl) = 0.100 × 0.0200 = 2.00 × 10⁻³ mol and n(NaOH) = 0.100 × 0.0150 = 1.50 × 10⁻³ mol, so H₃O⁺ is in excess by 5.0 × 10⁻⁴ mol;',1,1);
INSERT INTO rubric_criterion VALUES(8395,'chem12a2-ph-7',NULL,1,'total volume = 35.0 mL, so [H₃O⁺] = 5.0 × 10⁻⁴ ÷ 0.0350 = 1.43 × 10⁻² mol L⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(8396,'chem12a2-ph-7',NULL,2,'pH = −log₁₀(1.43 × 10⁻²) = 1.85.',1,1);
INSERT INTO rubric_criterion VALUES(8397,'chem12a2-ph-8',NULL,0,'[OH⁻] = 0.025 mol L⁻¹, so [H₃O⁺] = 1.0 × 10⁻¹⁴ ÷ 0.025 = 4.0 × 10⁻¹³ mol L⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(8398,'chem12a2-ph-8',NULL,1,'pH = −log₁₀(4.0 × 10⁻¹³) = 12.40 (12.4).',1,1);
INSERT INTO rubric_criterion VALUES(8413,'chem12a2-ph-23',NULL,0,'A strong acid is one that ionises (donates protons to water) completely in aqueous solution [1];',1,1);
INSERT INTO rubric_criterion VALUES(8414,'chem12a2-ph-23',NULL,1,'HNO₃ + H₂O → H₃O⁺ + NO₃⁻ (single forward arrow) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8415,'chem12a2-ph-24',NULL,0,'n(HCl) = 0.50 × 0.0100 = 5.0 × 10⁻³ mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8416,'chem12a2-ph-24',NULL,1,'c = 5.0 × 10⁻³ ÷ 0.250 = 0.020 mol L⁻¹, so [H₃O⁺] = 0.020 mol L⁻¹ as HCl is strong [1];',1,1);
INSERT INTO rubric_criterion VALUES(8417,'chem12a2-ph-24',NULL,2,'pH = −log₁₀(0.020) = 1.70 [1].',1,1);
INSERT INTO rubric_criterion VALUES(8418,'chem12a2-ph-25',NULL,0,'[H₃O⁺] = 10⁻ᵖᴴ = 10⁻³·⁴⁰ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8419,'chem12a2-ph-25',NULL,1,'= 4.0 × 10⁻⁴ mol L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8420,'chem12a2-ph-26',NULL,0,'CH₃COOH + H₂O ⇌ CH₃COO⁻ + H₃O⁺ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8421,'chem12a2-ph-26',NULL,1,'the reversible arrow shows ionisation is incomplete, with the equilibrium lying well to the left [1];',1,1);
INSERT INTO rubric_criterion VALUES(8422,'chem12a2-ph-26',NULL,2,'so most ethanoic acid remains as molecules and [H₃O⁺] is much lower than the acid concentration [1].',1,1);
INSERT INTO rubric_criterion VALUES(8423,'chem12a2-ph-27',NULL,0,'n(NaOH) = 2.50 × 10⁻³ mol and n(HCl) = 2.00 × 10⁻³ mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8424,'chem12a2-ph-27',NULL,1,'OH⁻ is in excess by 5.0 × 10⁻⁴ mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8425,'chem12a2-ph-27',NULL,2,'total volume = 45.0 mL, so [OH⁻] = 5.0 × 10⁻⁴ ÷ 0.0450 = 1.11 × 10⁻² mol L⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8426,'chem12a2-ph-27',NULL,3,'[H₃O⁺] = 1.0 × 10⁻¹⁴ ÷ 1.11 × 10⁻² = 9.0 × 10⁻¹³ mol L⁻¹, pH = 12.05 [1].',1,1);
INSERT INTO rubric_criterion VALUES(8427,'chem12a2-ph-28',NULL,0,'[H₃O⁺] = 10⁻²·⁷⁸ = 1.66 × 10⁻³ mol L⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8428,'chem12a2-ph-28',NULL,1,'fraction ionised = 1.66 × 10⁻³ ÷ 0.15 = 0.0111 [1];',1,1);
INSERT INTO rubric_criterion VALUES(8429,'chem12a2-ph-28',NULL,2,'so about 1.1% ionised, confirming it is a weak acid [1].',1,1);
INSERT INTO rubric_criterion VALUES(8430,'chem12a2-ph-29',NULL,0,'n(HNO₃) = 1.26 ÷ 63.0 = 0.0200 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8431,'chem12a2-ph-29',NULL,1,'c = 0.0200 ÷ 0.250 = 0.0800 mol L⁻¹, so [H₃O⁺] = 0.0800 mol L⁻¹ as HNO₃ is strong [1];',1,1);
INSERT INTO rubric_criterion VALUES(8432,'chem12a2-ph-29',NULL,2,'pH = −log₁₀(0.0800) = 1.10 [1].',1,1);
INSERT INTO rubric_criterion VALUES(8433,'vce-chem12-ph-c1',NULL,0,'pH = 12.0',2,1);
INSERT INTO rubric_criterion VALUES(8439,'chem12a3-rr-6',NULL,0,'Oxidation: Al(s) → Al³⁺(aq) + 3e⁻;',1,1);
INSERT INTO rubric_criterion VALUES(8440,'chem12a3-rr-6',NULL,1,'Reduction: Cu²⁺(aq) + 2e⁻ → Cu(s);',1,1);
INSERT INTO rubric_criterion VALUES(8441,'chem12a3-rr-6',NULL,2,'Overall (electrons balanced at 6): 2Al(s) + 3Cu²⁺(aq) → 2Al³⁺(aq) + 3Cu(s).',1,1);
INSERT INTO rubric_criterion VALUES(8442,'chem12a3-rr-7',NULL,0,'Reduction: MnO₄⁻(aq) + 8H⁺(aq) + 5e⁻ → Mn²⁺(aq) + 4H₂O(l);',1,1);
INSERT INTO rubric_criterion VALUES(8443,'chem12a3-rr-7',NULL,1,'Oxidation: Fe²⁺(aq) → Fe³⁺(aq) + e⁻;',1,1);
INSERT INTO rubric_criterion VALUES(8444,'chem12a3-rr-7',NULL,2,'Multiply the oxidation by 5 so electrons cancel;',1,1);
INSERT INTO rubric_criterion VALUES(8445,'chem12a3-rr-7',NULL,3,'Overall: MnO₄⁻(aq) + 8H⁺(aq) + 5Fe²⁺(aq) → Mn²⁺(aq) + 5Fe³⁺(aq) + 4H₂O(l).',1,1);
INSERT INTO rubric_criterion VALUES(8446,'chem12a3-rr-8',NULL,0,'Cl in Cl₂ has oxidation number 0; in Cl⁻ it is −1, so some chlorine is reduced;',1,1);
INSERT INTO rubric_criterion VALUES(8447,'chem12a3-rr-8',NULL,1,'in OCl⁻ it is +1, so some chlorine is oxidised;',1,1);
INSERT INTO rubric_criterion VALUES(8448,'chem12a3-rr-8',NULL,2,'the same species is both oxidised and reduced (disproportionation), and H, O and Na oxidation numbers do not change.',1,1);
INSERT INTO rubric_criterion VALUES(8464,'chem12a3-rr-24',NULL,0,'H₂S: S = −2 as each H is +1 [1].',1,1);
INSERT INTO rubric_criterion VALUES(8465,'chem12a3-rr-24',NULL,1,'S₈: S = 0 as it is an uncombined element [1].',1,1);
INSERT INTO rubric_criterion VALUES(8466,'chem12a3-rr-24',NULL,2,'SO₂: S = +4 as each O is −2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(8467,'chem12a3-rr-24',NULL,3,'SO₄²⁻: S = +6 since S + 4(−2) = −2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(8468,'chem12a3-rr-25',NULL,0,'Oxidation: SO₂(g) + 2H₂O(l) → SO₄²⁻(aq) + 4H⁺(aq) + 2e⁻ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8469,'chem12a3-rr-25',NULL,1,'Reduction: MnO₄⁻(aq) + 8H⁺(aq) + 5e⁻ → Mn²⁺(aq) + 4H₂O(l) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8470,'chem12a3-rr-25',NULL,2,'Multiply oxidation by 5 and reduction by 2 so 10 electrons cancel [1].',1,1);
INSERT INTO rubric_criterion VALUES(8471,'chem12a3-rr-25',NULL,3,'Overall: 5SO₂(g) + 2MnO₄⁻(aq) + 2H₂O(l) → 5SO₄²⁻(aq) + 2Mn²⁺(aq) + 4H⁺(aq) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8472,'chem12a3-rr-26',NULL,0,'Oxidation: Mg(s) → Mg²⁺(aq) + 2e⁻ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8473,'chem12a3-rr-26',NULL,1,'Reduction: 2H⁺(aq) + 2e⁻ → H₂(g) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8474,'chem12a3-rr-26',NULL,2,'Overall: Mg(s) + 2H⁺(aq) → Mg²⁺(aq) + H₂(g) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8475,'chem12a3-rr-26',NULL,3,'Mg is the species oxidised (0 to +2) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8476,'chem12a3-rr-27',NULL,0,'Fe changes from +3 to 0, so it is reduced [1].',1,1);
INSERT INTO rubric_criterion VALUES(8477,'chem12a3-rr-27',NULL,1,'Al changes from 0 to +3, so it is oxidised [1].',1,1);
INSERT INTO rubric_criterion VALUES(8478,'chem12a3-rr-27',NULL,2,'Oxidising agent is Fe₂O₃ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8479,'chem12a3-rr-27',NULL,3,'Reducing agent is Al [1].',1,1);
INSERT INTO rubric_criterion VALUES(8480,'chem12a3-rr-28',NULL,0,'In the zinc reaction Zn changes from 0 to +2 and H changes from +1 to 0, so oxidation numbers change and it is redox [1].',1,1);
INSERT INTO rubric_criterion VALUES(8481,'chem12a3-rr-28',NULL,1,'In the NaOH and HCl reaction every element keeps its oxidation number (Na +1, O −2, H +1, Cl −1), so it is not redox [1].',1,1);
INSERT INTO rubric_criterion VALUES(8482,'chem12a3-rr-29',NULL,0,'n(Mg) = 0.486 ÷ 24.3 = 0.0200 mol [1].',1,1);
INSERT INTO rubric_criterion VALUES(8483,'chem12a3-rr-29',NULL,1,'The mole ratio Mg : Cu is 1 : 1, so n(Cu) = 0.0200 mol [1].',1,1);
INSERT INTO rubric_criterion VALUES(8484,'chem12a3-rr-29',NULL,2,'m(Cu) = 0.0200 × 63.5 = 1.27 g [1].',1,1);
INSERT INTO rubric_criterion VALUES(8485,'chem12a3-rr-30',NULL,0,'Electrons lost in oxidation cannot exist freely in solution, so they must be gained by another species in reduction [1].',1,1);
INSERT INTO rubric_criterion VALUES(8486,'chem12a3-rr-30',NULL,1,'The number of electrons lost by the reducing agent equals the number gained by the oxidising agent [1].',1,1);
INSERT INTO rubric_criterion VALUES(8487,'chem12a3-rr-31',NULL,0,'Reduction: H₂O₂(aq) + 2H⁺(aq) + 2e⁻ → 2H₂O(l) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8488,'chem12a3-rr-31',NULL,1,'oxidation: Fe²⁺(aq) → Fe³⁺(aq) + e⁻ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8489,'chem12a3-rr-31',NULL,2,'overall (oxidation half-equation × 2): H₂O₂(aq) + 2Fe²⁺(aq) + 2H⁺(aq) → 2Fe³⁺(aq) + 2H₂O(l) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8496,'chem12a3-rs-6',NULL,0,'A reaction occurs;',1,1);
INSERT INTO rubric_criterion VALUES(8497,'chem12a3-rs-6',NULL,1,'Pb²⁺(aq) (E° = −0.13 V) is a stronger oxidising agent than Zn²⁺(aq) (E° = −0.76 V), so Zn(s) is a stronger reductant than Pb(s) and can reduce Pb²⁺;',1,1);
INSERT INTO rubric_criterion VALUES(8498,'chem12a3-rs-6',NULL,2,'Zn(s) + Pb²⁺(aq) → Zn²⁺(aq) + Pb(s) (grey crystals of lead form as zinc dissolves).',1,1);
INSERT INTO rubric_criterion VALUES(8499,'chem12a3-rs-7',NULL,0,'Iron is a stronger reducing agent than copper (Fe²⁺/Fe is below Cu²⁺/Cu in the electrochemical series), so iron is oxidised and the container corrodes while copper metal deposits;',1,1);
INSERT INTO rubric_criterion VALUES(8500,'chem12a3-rs-7',NULL,1,'Fe(s) + Cu²⁺(aq) → Fe²⁺(aq) + Cu(s).',1,1);
INSERT INTO rubric_criterion VALUES(8501,'chem12a3-rs-8',NULL,0,'(a) A > C > B > D, since each metal displaces only those below it;',1,1);
INSERT INTO rubric_criterion VALUES(8502,'chem12a3-rs-8',NULL,1,'(b) D²⁺ is the strongest oxidising agent;',1,1);
INSERT INTO rubric_criterion VALUES(8503,'chem12a3-rs-8',NULL,2,'because D is the weakest reductant, its ion most readily gains electrons (every other metal can reduce D²⁺).',1,1);
INSERT INTO rubric_criterion VALUES(8515,'chem12a3-rs-20',NULL,0,'A reddish-brown solid (copper) deposits on the magnesium [1];',1,1);
INSERT INTO rubric_criterion VALUES(8516,'chem12a3-rs-20',NULL,1,'the blue colour of the solution fades [1];',1,1);
INSERT INTO rubric_criterion VALUES(8517,'chem12a3-rs-20',NULL,2,'Mg(s) + Cu²⁺(aq) → Mg²⁺(aq) + Cu(s) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8518,'chem12a3-rs-21',NULL,0,'Place a strip of each metal into a solution of each of the other metals'' nitrates (or a systematic set of pairs) and observe for deposits of metal [1];',1,1);
INSERT INTO rubric_criterion VALUES(8519,'chem12a3-rs-21',NULL,1,'a reaction (metal deposit on the strip) shows the strip is more reactive than the metal in solution [1];',1,1);
INSERT INTO rubric_criterion VALUES(8520,'chem12a3-rs-21',NULL,2,'zinc displaces all three others, silver displaces none [1];',1,1);
INSERT INTO rubric_criterion VALUES(8521,'chem12a3-rs-21',NULL,3,'order from most to least reactive: Zn > Pb > Cu > Ag [1].',1,1);
INSERT INTO rubric_criterion VALUES(8522,'chem12a3-rs-22',NULL,0,'Oxidation: Al(s) → Al³⁺(aq) + 3e⁻ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8523,'chem12a3-rs-22',NULL,1,'reduction: Cu²⁺(aq) + 2e⁻ → Cu(s) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8524,'chem12a3-rs-22',NULL,2,'overall: 2Al(s) + 3Cu²⁺(aq) → 2Al³⁺(aq) + 3Cu(s) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8525,'chem12a3-rs-23',NULL,0,'n(Zn) = 3.27 ÷ 65.4 = 0.0500 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8526,'chem12a3-rs-23',NULL,1,'Zn + Cu²⁺ → Zn²⁺ + Cu, so n(Cu) = n(Zn) = 0.0500 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8527,'chem12a3-rs-23',NULL,2,'m(Cu) = 0.0500 × 63.5 = 3.18 g [1].',1,1);
INSERT INTO rubric_criterion VALUES(8528,'chem12a3-rs-24',NULL,0,'Zinc lies below hydrogen in the reactivity series, so Zn is a stronger reducing agent than H₂ and can reduce H⁺ to H₂ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8529,'chem12a3-rs-24',NULL,1,'copper lies above hydrogen, so it is a weaker reducing agent than H₂ and cannot reduce H⁺ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8530,'chem12a3-rs-25',NULL,0,'Iron is a weaker reducing agent than magnesium (Fe²⁺/Fe lies above Mg²⁺/Mg in the electrochemical series) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8531,'chem12a3-rs-25',NULL,1,'so Fe(s) cannot transfer electrons to Mg²⁺ and no displacement occurs [1].',1,1);
INSERT INTO rubric_criterion VALUES(8532,'chem12a3-rs-26',NULL,0,'A reaction in which a more reactive metal transfers electrons to the ion of a less reactive metal, so the more reactive metal is oxidised and the ion is reduced to the metal [1]; e.g.',1,1);
INSERT INTO rubric_criterion VALUES(8533,'chem12a3-rs-26',NULL,1,'Mg(s) + 2Ag⁺(aq) → Mg²⁺(aq) + 2Ag(s) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8542,'chem12a3-cd-6',NULL,0,'V₁ = c₂V₂ ÷ c₁ = 0.250 × 2.00 ÷ 10.0 = 0.0500 L = 50.0 mL of stock;',1,1);
INSERT INTO rubric_criterion VALUES(8543,'chem12a3-cd-6',NULL,1,'measure 50.0 mL accurately (pipette/burette), transfer to a 2.00 L volumetric flask and make up to the mark with deionised water, then mix.',1,1);
INSERT INTO rubric_criterion VALUES(8544,'chem12a3-cd-7',NULL,0,'(a) 0.48 mg ÷ 0.200 L = 2.4 mg L⁻¹ = 2.4 ppm;',1,1);
INSERT INTO rubric_criterion VALUES(8545,'chem12a3-cd-7',NULL,1,'(b) M(NO₃⁻) = 14.0 + 3 × 16.0 = 62.0 g mol⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(8546,'chem12a3-cd-7',NULL,2,'c = 2.4 × 10⁻³ g L⁻¹ ÷ 62.0 g mol⁻¹ = 3.9 × 10⁻⁵ mol L⁻¹ (2 significant figures).',1,1);
INSERT INTO rubric_criterion VALUES(8547,'chem12a3-cd-8',NULL,0,'First dilution: 0.500 × 10.0 ÷ 100.0 = 0.0500 mol L⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(8548,'chem12a3-cd-8',NULL,1,'second dilution: 0.0500 × 5.00 ÷ 50.0 = 0.00500 mol L⁻¹ (5.00 × 10⁻³ mol L⁻¹);',1,1);
INSERT INTO rubric_criterion VALUES(8549,'chem12a3-cd-8',NULL,2,'n(Cu²⁺) = 0.00500 × 0.0500 L = 2.50 × 10⁻⁴ mol (equal to the moles in the 5.00 mL aliquot).',1,1);
INSERT INTO rubric_criterion VALUES(8565,'chem12a3-cd-24',NULL,0,'n(KCl) = c × V = 0.100 × 0.5000 = 0.0500 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8566,'chem12a3-cd-24',NULL,1,'m = n × M = 0.0500 × 74.6 = 3.73 g [1].',1,1);
INSERT INTO rubric_criterion VALUES(8567,'chem12a3-cd-25',NULL,0,'Mass concentration = 2.50 × 10⁻⁴ mol L⁻¹ × 35.5 g mol⁻¹ = 8.875 × 10⁻³ g L⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8568,'chem12a3-cd-25',NULL,1,'= 8.88 mg L⁻¹ = 8.88 ppm (assuming density 1.00 g mL⁻¹) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8569,'chem12a3-cd-26',NULL,0,'Na₃PO₄(s) → 3Na⁺(aq) + PO₄³⁻(aq) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8570,'chem12a3-cd-26',NULL,1,'[Na⁺] = 3 × 0.250 = 0.750 mol L⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8571,'chem12a3-cd-26',NULL,2,'[PO₄³⁻] = 0.250 mol L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8572,'chem12a3-cd-27',NULL,0,'n(HNO₃) = 0.600 × 0.0200 = 0.0120 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8573,'chem12a3-cd-27',NULL,1,'final volume = 20.0 + 30.0 = 50.0 mL [1];',1,1);
INSERT INTO rubric_criterion VALUES(8574,'chem12a3-cd-27',NULL,2,'c = 0.0120 ÷ 0.0500 = 0.240 mol L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8575,'chem12a3-cd-28',NULL,0,'A volumetric flask is calibrated to hold one precise volume when filled to its mark, whereas a beaker''s graduations are only approximate [1];',1,1);
INSERT INTO rubric_criterion VALUES(8576,'chem12a3-cd-28',NULL,1,'the solute is first dissolved in less water and then made up to the mark so that the total final volume of solution (not the volume of water added) is accurately known, giving an accurate concentration [1].',1,1);
INSERT INTO rubric_criterion VALUES(8577,'chem12a3-cd-29',NULL,0,'Use c₁V₁ = c₂V₂ (concentration in ppm is directly proportional to the amount of solute per volume) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8578,'chem12a3-cd-29',NULL,1,'V₁ = 25.0 × 100.0 ÷ 1000 = 2.50 mL [1];',1,1);
INSERT INTO rubric_criterion VALUES(8579,'chem12a3-cd-29',NULL,2,'pipette 2.50 mL of stock into a 100.0 mL volumetric flask, then add deionised water to the mark and mix by inverting [1].',1,1);
INSERT INTO rubric_criterion VALUES(8580,'chem12a3-cd-30',NULL,0,'c(MgCl₂) = 0.400 × 50.0 ÷ 200.0 = 0.100 mol L⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8581,'chem12a3-cd-30',NULL,1,'[Mg²⁺] = 0.100 mol L⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8582,'chem12a3-cd-30',NULL,2,'[Cl⁻] = 2 × 0.100 = 0.200 mol L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8584,'vce-chem12-cd-c1',NULL,0,'0.100 M;',1,1);
INSERT INTO rubric_criterion VALUES(8585,'vce-chem12-cd-c1',NULL,1,'20 ppm',1,1);
INSERT INTO rubric_criterion VALUES(8591,'chem12a3-sl-6',NULL,0,'n(Ag⁺) = 0.200 × 0.0500 = 0.0100 mol; n(Cl⁻) = 0.150 × 0.0300 = 0.00450 mol;',1,1);
INSERT INTO rubric_criterion VALUES(8592,'chem12a3-sl-6',NULL,1,'the ratio is 1:1, so Cl⁻ (NaCl) is limiting;',1,1);
INSERT INTO rubric_criterion VALUES(8593,'chem12a3-sl-6',NULL,2,'m(AgCl) = 0.00450 × 143.4 = 0.645 g;',1,1);
INSERT INTO rubric_criterion VALUES(8594,'chem12a3-sl-6',NULL,3,'excess Ag⁺ = 0.0100 − 0.00450 = 0.00550 mol.',1,1);
INSERT INTO rubric_criterion VALUES(8595,'chem12a3-sl-7',NULL,0,'n(CaCO₃) = 2.50 ÷ 100.1 = 0.0250 mol;',1,1);
INSERT INTO rubric_criterion VALUES(8596,'chem12a3-sl-7',NULL,1,'n(HCl) = 1.00 × 0.0400 = 0.0400 mol;',1,1);
INSERT INTO rubric_criterion VALUES(8597,'chem12a3-sl-7',NULL,2,'0.0250 mol CaCO₃ would need 0.0500 mol HCl, so HCl is limiting;',1,1);
INSERT INTO rubric_criterion VALUES(8598,'chem12a3-sl-7',NULL,3,'n(CO₂) = ½ × 0.0400 = 0.0200 mol, m = 0.0200 × 44.0 = 0.880 g.',1,1);
INSERT INTO rubric_criterion VALUES(8599,'chem12a3-sl-8',NULL,0,'Any two of: the reaction may not go to completion (e.g. it is reversible or too slow); side reactions form other products;',1,1);
INSERT INTO rubric_criterion VALUES(8600,'chem12a3-sl-8',NULL,1,'product is lost during transfer, filtration or washing; reactants are impure, so fewer moles are present than assumed.',1,1);
INSERT INTO rubric_criterion VALUES(8614,'chem12a3-sl-22',NULL,0,'The limiting reactant is the reactant that is completely consumed first [1];',1,1);
INSERT INTO rubric_criterion VALUES(8615,'chem12a3-sl-22',NULL,1,'once it is used up the reaction stops, so no more product can form regardless of how much of the other reactants (in excess) remains [1].',1,1);
INSERT INTO rubric_criterion VALUES(8616,'chem12a3-sl-23',NULL,0,'n(Al) = 5.40 ÷ 27.0 = 0.200 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8617,'chem12a3-sl-23',NULL,1,'n(Al₂O₃) = 2/4 × 0.200 = 0.100 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8618,'chem12a3-sl-23',NULL,2,'m(Al₂O₃) = 0.100 × 102.0 = 10.2 g [1].',1,1);
INSERT INTO rubric_criterion VALUES(8619,'chem12a3-sl-24',NULL,0,'n(Al) = 0.540 ÷ 27.0 = 0.0200 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8620,'chem12a3-sl-24',NULL,1,'n(HCl) = 1.00 × 0.0500 = 0.0500 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8621,'chem12a3-sl-24',NULL,2,'0.0200 mol Al needs 0.0600 mol HCl, so HCl is limiting [1];',1,1);
INSERT INTO rubric_criterion VALUES(8622,'chem12a3-sl-24',NULL,3,'n(H₂) = 3/6 × 0.0500 = 0.0250 mol, V = 0.0250 × 24.8 = 0.620 L [1].',1,1);
INSERT INTO rubric_criterion VALUES(8623,'chem12a3-sl-25',NULL,0,'n(CuSO₄) = 0.500 × 0.0200 = 0.0100 mol, so n(Cu(OH)₂) = 0.0100 mol (1:1) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8624,'chem12a3-sl-25',NULL,1,'theoretical mass = 0.0100 × 97.5 = 0.975 g [1];',1,1);
INSERT INTO rubric_criterion VALUES(8625,'chem12a3-sl-25',NULL,2,'percentage yield = 0.850 ÷ 0.975 × 100 = 87.2 % [1].',1,1);
INSERT INTO rubric_criterion VALUES(8626,'chem12a3-sl-26',NULL,0,'The limiting reactant depends on the amounts in mol available compared with the mole ratio in the balanced equation, not on mass [1];',1,1);
INSERT INTO rubric_criterion VALUES(8627,'chem12a3-sl-26',NULL,1,'substances have different molar masses and coefficients, so each mass must be converted to moles and compared with the stoichiometric ratio [1].',1,1);
INSERT INTO rubric_criterion VALUES(8628,'chem12a3-sl-27',NULL,0,'n(C₂H₅OH) = 2.30 ÷ 46.0 = 0.0500 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8629,'chem12a3-sl-27',NULL,1,'n(O₂) = 3 × 0.0500 = 0.150 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8630,'chem12a3-sl-27',NULL,2,'V(O₂) = 0.150 × 24.8 = 3.72 L [1].',1,1);
INSERT INTO rubric_criterion VALUES(8631,'chem12a3-sl-28',NULL,0,'n(Pb²⁺) = 0.400 × 0.0250 = 0.0100 mol; n(I⁻) = 0.600 × 0.0250 = 0.0150 mol;',1,1);
INSERT INTO rubric_criterion VALUES(8632,'chem12a3-sl-28',NULL,1,'0.0100 mol Pb²⁺ needs 0.0200 mol I⁻, so I⁻ (KI) is limiting [1]; n(PbI₂) = ½ × 0.0150 = 0.00750 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8633,'chem12a3-sl-28',NULL,2,'m = 0.00750 × 461.0 = 3.46 g [1];',1,1);
INSERT INTO rubric_criterion VALUES(8634,'chem12a3-sl-28',NULL,3,'Pb²⁺ remaining = 0.0100 − 0.00750 = 0.00250 mol in 0.0500 L, so c = 0.0500 mol L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8635,'chem12a3-sl-29',NULL,0,'Theoretical mass of CaO = 5.61 ÷ 0.800 = 7.01 g, so n(CaO) = 7.01 ÷ 56.1 = 0.125 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8636,'chem12a3-sl-29',NULL,1,'n(CaCO₃) = 0.125 mol (1:1) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8637,'chem12a3-sl-29',NULL,2,'m(CaCO₃) = 0.125 × 100.1 = 12.5 g [1].',1,1);
INSERT INTO rubric_criterion VALUES(8638,'chem12a3-sl-30',NULL,0,'n(Na) = 4.60 ÷ 23.0 = 0.200 mol, which needs only 0.100 mol Cl₂ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8639,'chem12a3-sl-30',NULL,1,'Cl₂ (0.150 mol) is in excess, so Na is the limiting reactant [1];',1,1);
INSERT INTO rubric_criterion VALUES(8640,'chem12a3-sl-30',NULL,2,'n(NaCl) = 0.200 mol, m = 0.200 × 58.5 = 11.7 g [1].',1,1);
INSERT INTO rubric_criterion VALUES(8641,'chem12a3-sl-31',NULL,0,'CaCO₃(s) → CaO(s) + CO₂(g) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8642,'chem12a3-sl-31',NULL,1,'n(CaCO₃) = 5.00 ÷ 100.1 = 0.04995 mol, so theoretical m(CaO) = 0.04995 × 56.1 = 2.80 g [1];',1,1);
INSERT INTO rubric_criterion VALUES(8643,'chem12a3-sl-31',NULL,2,'percentage yield = 2.05 ÷ 2.80 × 100 = 73.2% [1].',1,1);
INSERT INTO rubric_criterion VALUES(8644,'vce-chem12-sl-c1',NULL,0,'Oxygen is limiting; 72.0 g of water',1,1);
INSERT INTO rubric_criterion VALUES(8650,'chem12a3-gl-6',NULL,0,'n(CO₂) = V ÷ Vm = 3.10 ÷ 24.8 = 0.125 mol;',1,1);
INSERT INTO rubric_criterion VALUES(8651,'chem12a3-gl-6',NULL,1,'m = 0.125 × 44.0 = 5.50 g.',1,1);
INSERT INTO rubric_criterion VALUES(8652,'chem12a3-gl-7',NULL,0,'T = 298 K;',1,1);
INSERT INTO rubric_criterion VALUES(8653,'chem12a3-gl-7',NULL,1,'n(N₂) = PV ÷ RT = (120 × 60.0) ÷ (8.31 × 298) = 2.91 mol;',1,1);
INSERT INTO rubric_criterion VALUES(8654,'chem12a3-gl-7',NULL,2,'n(NaN₃) = 2/3 × 2.91 = 1.94 mol;',1,1);
INSERT INTO rubric_criterion VALUES(8655,'chem12a3-gl-7',NULL,3,'M(NaN₃) = 23.0 + 3 × 14.0 = 65.0 g mol⁻¹, so m = 1.94 × 65.0 = 126 g.',1,1);
INSERT INTO rubric_criterion VALUES(8656,'chem12a3-gl-8',NULL,0,'Heating increases the average kinetic energy of the gas particles, so they move faster;',1,1);
INSERT INTO rubric_criterion VALUES(8657,'chem12a3-gl-8',NULL,1,'they collide with the container walls more often and with greater force;',1,1);
INSERT INTO rubric_criterion VALUES(8658,'chem12a3-gl-8',NULL,2,'because the volume is fixed, the force per unit area of wall (pressure) increases.',1,1);
INSERT INTO rubric_criterion VALUES(8672,'chem12a3-gl-22',NULL,0,'n(CH₄) = m ÷ M = 8.00 ÷ 16.0 = 0.500 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8673,'chem12a3-gl-22',NULL,1,'V = n × Vm = 0.500 × 24.8 = 12.4 L [1].',1,1);
INSERT INTO rubric_criterion VALUES(8674,'chem12a3-gl-23',NULL,0,'Boyle''s law: P₁V₁ = P₂V₂ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8675,'chem12a3-gl-23',NULL,1,'P₂ = 150 × 3.0 ÷ 1.2 = 375 kPa [1].',1,1);
INSERT INTO rubric_criterion VALUES(8676,'chem12a3-gl-24',NULL,0,'Temperatures in kelvin: T₁ = 288 K and T₂ = 318 K [1];',1,1);
INSERT INTO rubric_criterion VALUES(8677,'chem12a3-gl-24',NULL,1,'V₂ = 250 × 318 ÷ 288 = 276 mL [1].',1,1);
INSERT INTO rubric_criterion VALUES(8678,'chem12a3-gl-25',NULL,0,'Convert to kelvin: T₁ = 300 K, T₂ = 400 K [1];',1,1);
INSERT INTO rubric_criterion VALUES(8679,'chem12a3-gl-25',NULL,1,'combined gas law: P₁V₁ ÷ T₁ = P₂V₂ ÷ T₂ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8680,'chem12a3-gl-25',NULL,2,'V₂ = 2.50 × (200 ÷ 100) × (400 ÷ 300) = 6.67 L [1].',1,1);
INSERT INTO rubric_criterion VALUES(8681,'chem12a3-gl-26',NULL,0,'n(H₂) = 2.48 ÷ 24.8 = 0.100 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8682,'chem12a3-gl-26',NULL,1,'n(Mg) = n(H₂) = 0.100 mol, from the 1 : 1 ratio [1];',1,1);
INSERT INTO rubric_criterion VALUES(8683,'chem12a3-gl-26',NULL,2,'m(Mg) = 0.100 × 24.3 = 2.43 g [1].',1,1);
INSERT INTO rubric_criterion VALUES(8684,'chem12a3-gl-27',NULL,0,'T = 300 K; n = PV ÷ RT = (100 × 1.00) ÷ (8.31 × 300) = 0.0401 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8685,'chem12a3-gl-27',NULL,1,'M = m ÷ n [1];',1,1);
INSERT INTO rubric_criterion VALUES(8686,'chem12a3-gl-27',NULL,2,'M = 1.50 ÷ 0.0401 = 37.4 g mol⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8687,'chem12a3-gl-28',NULL,0,'With a smaller volume, the gas particles strike the container walls more frequently, as they have less distance to travel between collisions [1];',1,1);
INSERT INTO rubric_criterion VALUES(8688,'chem12a3-gl-28',NULL,1,'the average kinetic energy is unchanged (constant temperature), so the greater collision rate per unit area increases the pressure [1].',1,1);
INSERT INTO rubric_criterion VALUES(8689,'chem12a3-gl-29',NULL,0,'Gas particles are very far apart, so the volume of the gas is mostly empty space and the size of individual particles is negligible [1];',1,1);
INSERT INTO rubric_criterion VALUES(8690,'chem12a3-gl-29',NULL,1,'the volume of a gas therefore depends only on the number of particles (at fixed T and P), not on their identity (Avogadro''s hypothesis) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8691,'chem12a3-gl-30',NULL,0,'At the same T and P, gas volumes are in the same ratio as the coefficients, so C₃H₈ : O₂ : CO₂ = 1 : 5 : 3 [1];',1,1);
INSERT INTO rubric_criterion VALUES(8692,'chem12a3-gl-30',NULL,1,'V(O₂) = 5 × 4.0 = 20 L [1];',1,1);
INSERT INTO rubric_criterion VALUES(8693,'chem12a3-gl-30',NULL,2,'V(CO₂) = 3 × 4.0 = 12 L [1].',1,1);
INSERT INTO rubric_criterion VALUES(8694,'chem12a3-gl-31',NULL,0,'T = 27 + 273 = 300 K [1];',1,1);
INSERT INTO rubric_criterion VALUES(8695,'chem12a3-gl-31',NULL,1,'P = nRT ÷ V = (0.0500 × 8.31 × 300) ÷ 1.50 = 83.1 kPa [1].',1,1);
INSERT INTO rubric_criterion VALUES(8696,'vce-chem12-gl-c1',NULL,0,'0.120 mol',2,1);
INSERT INTO rubric_criterion VALUES(8702,'chem12a3-vt-6',NULL,0,'n(NaOH) = 0.1050 × 0.01685 = 1.769 × 10⁻³ mol = n(CH₃COOH) in the aliquot (1:1);',1,1);
INSERT INTO rubric_criterion VALUES(8703,'chem12a3-vt-6',NULL,1,'c(diluted) = 1.769 × 10⁻³ ÷ 0.02000 = 0.08846 mol L⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(8704,'chem12a3-vt-6',NULL,2,'c(original) = 0.08846 × 10 (dilution factor 250.0/25.00) = 0.885 mol L⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(8705,'chem12a3-vt-6',NULL,3,'0.885 × 60.0 = 53.1 g L⁻¹ = 5.31 % (m/v).',1,1);
INSERT INTO rubric_criterion VALUES(8706,'chem12a3-vt-7',NULL,0,'Phenolphthalein;',1,1);
INSERT INTO rubric_criterion VALUES(8707,'chem12a3-vt-7',NULL,1,'at equivalence the solution contains ethanoate ions, a weak base, so the equivalence point pH is above 7 (about 8–9);',1,1);
INSERT INTO rubric_criterion VALUES(8708,'chem12a3-vt-7',NULL,2,'the indicator must change colour within the steep pH change at equivalence, which phenolphthalein does, whereas methyl orange would change colour well before equivalence, giving a titre that is too small.',1,1);
INSERT INTO rubric_criterion VALUES(8709,'chem12a3-vt-8',NULL,0,'Any three: high purity; known, stable chemical formula;',1,1);
INSERT INTO rubric_criterion VALUES(8710,'chem12a3-vt-8',NULL,1,'does not absorb water or react with air (not hygroscopic or deliquescent); high molar mass to reduce weighing error;',1,1);
INSERT INTO rubric_criterion VALUES(8711,'chem12a3-vt-8',NULL,2,'readily soluble; NaOH is unsuitable because it absorbs water from the air and reacts with atmospheric CO₂ (forming Na₂CO₃), so its mass does not reliably match the amount of NaOH.',1,1);
INSERT INTO rubric_criterion VALUES(8726,'chem12a3-vt-23',NULL,0,'Burette is rinsed with a small amount of the titrant (standard solution) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8727,'chem12a3-vt-23',NULL,1,'pipette is rinsed with a small amount of the analyte solution it will measure [1];',1,1);
INSERT INTO rubric_criterion VALUES(8728,'chem12a3-vt-23',NULL,2,'conical flask is rinsed with deionised water only, because the water does not change the moles of analyte in the aliquot, whereas rinsing with analyte would add extra moles and make the titre too large [1].',1,1);
INSERT INTO rubric_criterion VALUES(8729,'chem12a3-vt-24',NULL,0,'The rough titre gives an approximate end point so that later titrations can add titrant dropwise near the end point for accuracy [1];',1,1);
INSERT INTO rubric_criterion VALUES(8730,'chem12a3-vt-24',NULL,1,'concordant titres (within 0.10 mL) show that the results are reproducible and that random errors are small, so the mean is reliable [1].',1,1);
INSERT INTO rubric_criterion VALUES(8731,'chem12a3-vt-25',NULL,0,'Accuracy is how close the result is to the true value [1];',1,1);
INSERT INTO rubric_criterion VALUES(8732,'chem12a3-vt-25',NULL,1,'precision is how close repeated measurements (titres) are to each other [1];',1,1);
INSERT INTO rubric_criterion VALUES(8733,'chem12a3-vt-25',NULL,2,'a systematic error, such as a burette not rinsed with titrant or a consistently misread meniscus, shifts all titres the same way so they are concordant (precise) but the result is wrong (inaccurate) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8734,'chem12a3-vt-26',NULL,0,'n(HCl) = 0.0950 × 0.02130 = 2.0235 × 10⁻³ mol = n(NH₃) in the aliquot (1:1) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8735,'chem12a3-vt-26',NULL,1,'c(diluted) = 2.0235 × 10⁻³ ÷ 0.02500 = 0.0809 mol L⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8736,'chem12a3-vt-26',NULL,2,'c(original) = 0.08094 × 50 (dilution factor 500.0/10.00) = 4.05 mol L⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8737,'chem12a3-vt-26',NULL,3,'4.047 × 17.0 = 68.8 g L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8738,'chem12a3-vt-27',NULL,0,'The equivalence point of a strong acid with a strong base is at pH 7, which lies within the range of bromothymol blue [1];',1,1);
INSERT INTO rubric_criterion VALUES(8739,'chem12a3-vt-27',NULL,1,'the pH changes very steeply (from about 3 to 11) near equivalence, so a drop of titrant moves the pH through the whole range of the indicator [1];',1,1);
INSERT INTO rubric_criterion VALUES(8740,'chem12a3-vt-27',NULL,2,'therefore several indicators (such as phenolphthalein or methyl orange) give a nearly identical titre, whereas a weak acid has a smaller, higher-pH steep region so only some indicators are suitable [1].',1,1);
INSERT INTO rubric_criterion VALUES(8741,'chem12a3-vt-28',NULL,0,'n(H₂C₂O₄·2H₂O) = 0.6300 ÷ 126.0 = 5.000 × 10⁻³ mol, so c = 5.000 × 10⁻³ ÷ 0.1000 = 0.0500 mol L⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8742,'chem12a3-vt-28',NULL,1,'n(H₂C₂O₄) in aliquot = 0.0500 × 0.02000 = 1.000 × 10⁻³ mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8743,'chem12a3-vt-28',NULL,2,'n(NaOH) = 2 × 1.000 × 10⁻³ = 2.000 × 10⁻³ mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8744,'chem12a3-vt-28',NULL,3,'c(NaOH) = 2.000 × 10⁻³ ÷ 0.01940 = 0.103 mol L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8745,'chem12a3-vt-29',NULL,0,'Accurately weigh the required mass of the primary standard (for example by difference) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8746,'chem12a3-vt-29',NULL,1,'dissolve it in a beaker with deionised water, then transfer the solution to the volumetric flask, rinsing the beaker and funnel into the flask [1];',1,1);
INSERT INTO rubric_criterion VALUES(8747,'chem12a3-vt-29',NULL,2,'add deionised water until the bottom of the meniscus sits on the calibration mark at eye level [1];',1,1);
INSERT INTO rubric_criterion VALUES(8748,'chem12a3-vt-29',NULL,3,'stopper and invert the flask several times to mix thoroughly [1].',1,1);
INSERT INTO rubric_criterion VALUES(8749,'vce-chem12-va-c1',NULL,0,'0.0460 M',2,1);
INSERT INTO rubric_criterion VALUES(8755,'chem12a3-ga-6',NULL,0,'m(H₂O) = 2.50 − 1.60 = 0.90 g, n(H₂O) = 0.90 ÷ 18.0 = 0.050 mol;',1,1);
INSERT INTO rubric_criterion VALUES(8756,'chem12a3-ga-6',NULL,1,'n(CuSO₄) = 1.60 ÷ 159.6 = 0.0100 mol;',1,1);
INSERT INTO rubric_criterion VALUES(8757,'chem12a3-ga-6',NULL,2,'ratio H₂O : CuSO₄ = 0.050 ÷ 0.0100 ≈ 5, so x = 5 (CuSO₄·5H₂O).',1,1);
INSERT INTO rubric_criterion VALUES(8758,'chem12a3-ga-7',NULL,0,'n(BaSO₄) = 0.0583 ÷ 233.4 = 2.50 × 10⁻⁴ mol;',1,1);
INSERT INTO rubric_criterion VALUES(8759,'chem12a3-ga-7',NULL,1,'n(SO₄²⁻) = 2.50 × 10⁻⁴ mol (1:1);',1,1);
INSERT INTO rubric_criterion VALUES(8760,'chem12a3-ga-7',NULL,2,'m(SO₄²⁻) = 2.50 × 10⁻⁴ × 96.1 = 0.0240 g = 24.0 mg;',1,1);
INSERT INTO rubric_criterion VALUES(8761,'chem12a3-ga-7',NULL,3,'concentration = 24.0 mg ÷ 0.2000 L = 1.20 × 10² mg L⁻¹ = 120 ppm.',1,1);
INSERT INTO rubric_criterion VALUES(8762,'chem12a3-ga-8',NULL,0,'Any two with effect: the precipitate is not dried to constant mass, so the mass is too high and the result is overestimated; fine precipitate passes through the filter paper, or some precipitate stays dissolved, so the mass is too low and the result is underestimated;',1,1);
INSERT INTO rubric_criterion VALUES(8763,'chem12a3-ga-8',NULL,1,'soluble impurities are not washed off or are co-precipitated, so the result is too high;',1,1);
INSERT INTO rubric_criterion VALUES(8764,'chem12a3-ga-8',NULL,2,'not enough precipitating agent is added, so precipitation is incomplete and the result is too low.',1,1);
INSERT INTO rubric_criterion VALUES(8778,'chem12a3-ga-22',NULL,0,'Washing removes soluble impurities (such as excess precipitating reagent or spectator ions) that are stuck to the surface of the precipitate [1];',1,1);
INSERT INTO rubric_criterion VALUES(8779,'chem12a3-ga-22',NULL,1,'if left, these would dry onto the precipitate, adding mass and making the calculated amount of analyte too high [1].',1,1);
INSERT INTO rubric_criterion VALUES(8780,'chem12a3-ga-23',NULL,0,'Accurately weigh the sample and dissolve it in distilled water [1];',1,1);
INSERT INTO rubric_criterion VALUES(8781,'chem12a3-ga-23',NULL,1,'add excess silver nitrate solution so that all chloride ions precipitate as AgCl [1];',1,1);
INSERT INTO rubric_criterion VALUES(8782,'chem12a3-ga-23',NULL,2,'filter the mixture and wash the precipitate with distilled water [1];',1,1);
INSERT INTO rubric_criterion VALUES(8783,'chem12a3-ga-23',NULL,3,'dry the precipitate to constant mass, weigh it and use the mole ratio n(Cl⁻) = n(AgCl) to calculate the percentage of chloride [1].',1,1);
INSERT INTO rubric_criterion VALUES(8784,'chem12a3-ga-24',NULL,0,'n(AgCl) = 2.868 ÷ 143.4 = 0.02000 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8785,'chem12a3-ga-24',NULL,1,'n(NaCl) = n(AgCl) = 0.02000 mol (1:1 ratio) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8786,'chem12a3-ga-24',NULL,2,'m(NaCl) = 0.02000 × 58.5 = 1.170 g [1];',1,1);
INSERT INTO rubric_criterion VALUES(8787,'chem12a3-ga-24',NULL,3,'% NaCl = 1.170 ÷ 1.250 × 100 = 93.6 % [1].',1,1);
INSERT INTO rubric_criterion VALUES(8788,'chem12a3-ga-25',NULL,0,'n(CaCO₃) = 0.350 ÷ 100.1 = 3.50 × 10⁻³ mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8789,'chem12a3-ga-25',NULL,1,'n(Ca²⁺) = n(CaCO₃) = 3.50 × 10⁻³ mol (1:1) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8790,'chem12a3-ga-25',NULL,2,'c(Ca²⁺) = 3.50 × 10⁻³ ÷ 0.0250 = 0.140 mol L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8791,'chem12a3-ga-26',NULL,0,'m(H₂O) = 4.92 − 2.40 = 2.52 g, so n(H₂O) = 2.52 ÷ 18.0 = 0.140 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8792,'chem12a3-ga-26',NULL,1,'n(MgSO₄) = 2.40 ÷ 120.4 = 0.0199 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8793,'chem12a3-ga-26',NULL,2,'ratio H₂O : MgSO₄ = 0.140 ÷ 0.0199 ≈ 7, so x = 7 (MgSO₄·7H₂O) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8794,'chem12a3-ga-27',NULL,0,'Not all of the analyte ions are precipitated, because the precipitating agent is the limiting reactant [1];',1,1);
INSERT INTO rubric_criterion VALUES(8795,'chem12a3-ga-27',NULL,1,'the mass of precipitate is lower than it should be, so the calculated mass of analyte is too low [1].',1,1);
INSERT INTO rubric_criterion VALUES(8796,'chem12a3-ga-28',NULL,0,'The mass is still decreasing, so the precipitate has not reached constant mass and still contains water [1];',1,1);
INSERT INTO rubric_criterion VALUES(8797,'chem12a3-ga-28',NULL,1,'the student should reheat the precipitate and cool it in a desiccator to prevent water being reabsorbed [1];',1,1);
INSERT INTO rubric_criterion VALUES(8798,'chem12a3-ga-28',NULL,2,'then reweigh, repeating until two successive masses agree [1].',1,1);
INSERT INTO rubric_criterion VALUES(8799,'chem12a3-ga-29',NULL,0,'It must be very insoluble, so that almost none is lost in the filtrate or during washing [1];',1,1);
INSERT INTO rubric_criterion VALUES(8800,'chem12a3-ga-29',NULL,1,'it must have a known formula (composition), so that the amount of analyte can be calculated from its mass [1].',1,1);
INSERT INTO rubric_criterion VALUES(8801,'chem12a3-ga-30',NULL,0,'n(AgCl) = 0.0287 ÷ 143.4 = 2.00 × 10⁻⁴ mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8802,'chem12a3-ga-30',NULL,1,'n(Cl⁻) = n(AgCl) = 2.00 × 10⁻⁴ mol (1:1) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8803,'chem12a3-ga-30',NULL,2,'m(Cl⁻) = 2.00 × 10⁻⁴ × 35.5 = 7.10 × 10⁻³ g = 7.10 mg [1];',1,1);
INSERT INTO rubric_criterion VALUES(8804,'chem12a3-ga-30',NULL,3,'concentration = 7.10 mg ÷ 0.2500 L = 28.4 mg L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8806,'vce-chem12-ga-c1',NULL,0,'1.42 g/L',3,1);
INSERT INTO rubric_criterion VALUES(8812,'chem12a3-cu-6',NULL,0,'The calibration is linear with slope 0.11 ÷ 2.0 = 0.055 per mg L⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(8813,'chem12a3-cu-6',NULL,1,'diluted sample c = 0.15 ÷ 0.055 = 2.7 mg L⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(8814,'chem12a3-cu-6',NULL,2,'dilution factor 50.0 ÷ 5.0 = 10, so original = 27 mg L⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(8815,'chem12a3-cu-7',NULL,0,'At λmax the absorbance changes most for a given change in concentration, giving the greatest sensitivity and the lowest detection limit;',1,1);
INSERT INTO rubric_criterion VALUES(8816,'chem12a3-cu-7',NULL,1,'the absorption peak is flattest there, so small shifts in wavelength have little effect on readings, which improves precision (it may also reduce interference from other species).',1,1);
INSERT INTO rubric_criterion VALUES(8817,'chem12a3-cu-8',NULL,0,'Absorbance depends on the instrument, wavelength, cuvette path length and the analyte, so the relationship between absorbance and concentration must be found under the same conditions;',1,1);
INSERT INTO rubric_criterion VALUES(8818,'chem12a3-cu-8',NULL,1,'the curve converts sample absorbance into concentration;',1,1);
INSERT INTO rubric_criterion VALUES(8819,'chem12a3-cu-8',NULL,2,'the relationship is only known to be linear over the range measured, and at high concentrations it may stop being linear, so extrapolating beyond the standards is unreliable.',1,1);
INSERT INTO rubric_criterion VALUES(8833,'chem12a3-cu-22',NULL,0,'Use c₁V₁ = c₂V₂: V₁ = 20 × 100.0 ÷ 100 = 20 mL of stock required [1].',1,1);
INSERT INTO rubric_criterion VALUES(8834,'chem12a3-cu-22',NULL,1,'Measure 20.0 mL of the stock accurately using a pipette (or burette) and transfer it to a 100.0 mL volumetric flask [1].',1,1);
INSERT INTO rubric_criterion VALUES(8835,'chem12a3-cu-22',NULL,2,'Add deionised water up to the mark, stopper and invert several times to mix thoroughly [1].',1,1);
INSERT INTO rubric_criterion VALUES(8836,'chem12a3-cu-23',NULL,0,'The calibration is linear through the origin with a slope of 0.24 per mmol L⁻¹ (0.12 ÷ 0.50) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8837,'chem12a3-cu-23',NULL,1,'c = 0.30 ÷ 0.24 = 1.25 mmol L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8838,'chem12a3-cu-23',NULL,2,'n = 1.25 × 10⁻³ mol L⁻¹ × 0.0250 L = 3.1 × 10⁻⁵ mol [1].',1,1);
INSERT INTO rubric_criterion VALUES(8839,'chem12a3-cu-24',NULL,0,'The reagent reacts with the analyte to form a coloured species that absorbs in the visible region, so absorbance can be measured [1].',1,1);
INSERT INTO rubric_criterion VALUES(8840,'chem12a3-cu-24',NULL,1,'The reagent is added in excess/fixed amounts so that all the analyte reacts and the colour intensity (absorbance) is proportional to the analyte concentration [1].',1,1);
INSERT INTO rubric_criterion VALUES(8841,'chem12a3-cu-25',NULL,0,'The absorbance is no longer proportional to concentration at high concentrations, so the calibration is unreliable beyond the linear range and concentrations cannot be read accurately [1].',1,1);
INSERT INTO rubric_criterion VALUES(8842,'chem12a3-cu-25',NULL,1,'The sample should be diluted by a known factor so that its absorbance falls within the linear range, then the dilution factor is applied to the result [1].',1,1);
INSERT INTO rubric_criterion VALUES(8843,'chem12a3-cu-26',NULL,0,'Concentration of diluted solution = 0.48 ÷ 0.040 = 12 mg L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8844,'chem12a3-cu-26',NULL,1,'Dilution factor = 100.0 ÷ 1.00 = 100, so the 250.0 mL solution is 1200 mg L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(8845,'chem12a3-cu-26',NULL,2,'Mass of Cu = 1200 mg L⁻¹ × 0.2500 L = 300 mg [1].',1,1);
INSERT INTO rubric_criterion VALUES(8846,'chem12a3-cu-26',NULL,3,'% Cu = 300 ÷ 500 × 100 = 60% [1].',1,1);
INSERT INTO rubric_criterion VALUES(8847,'chem12a3-cu-27',NULL,0,'Rinse the cuvette with a small amount of the solution to be measured, and avoid air bubbles in the light path [1]. Wipe the clear faces clean and handle only by the frosted sides;',1,1);
INSERT INTO rubric_criterion VALUES(8848,'chem12a3-cu-27',NULL,1,'place the cuvette in the same orientation each time [1].',1,1);
INSERT INTO rubric_criterion VALUES(8849,'chem12a3-cu-28',NULL,0,'White light contains all visible wavelengths, and the solution absorbs light of some wavelengths (mainly green, around 530 nm) as electrons are promoted to higher energy levels [1].',1,1);
INSERT INTO rubric_criterion VALUES(8850,'chem12a3-cu-28',NULL,1,'The remaining wavelengths (red and blue/violet) are transmitted [1].',1,1);
INSERT INTO rubric_criterion VALUES(8851,'chem12a3-cu-28',NULL,2,'The transmitted light combines to give the complementary colour, so the solution appears purple [1].',1,1);
INSERT INTO rubric_criterion VALUES(8852,'chem12a3-cu-29',NULL,0,'Absorbance is directly proportional to the concentration of the absorbing species [1].',1,1);
INSERT INTO rubric_criterion VALUES(8853,'chem12a3-cu-29',NULL,1,'Absorbance is also directly proportional to the path length of the cuvette [1].',1,1);
INSERT INTO rubric_criterion VALUES(8854,'chem12a3-cu-30',NULL,0,'Prepare standard solutions of known Cu²⁺ concentration and measure their absorbance at the wavelength of maximum absorbance [1];',1,1);
INSERT INTO rubric_criterion VALUES(8855,'chem12a3-cu-30',NULL,1,'plot absorbance against concentration to give a straight-line calibration curve [1];',1,1);
INSERT INTO rubric_criterion VALUES(8856,'chem12a3-cu-30',NULL,2,'measure the absorbance of the sample (diluting if it is out of range) and read its concentration from the curve, allowing for any dilution [1].',1,1);
INSERT INTO rubric_criterion VALUES(8857,'vce-chem12-uv-c1',NULL,0,'45 mg/L',2,1);
INSERT INTO rubric_criterion VALUES(8863,'chem12a3-go-6',NULL,0,'CO₂(g) ⇌ CO₂(aq);',1,1);
INSERT INTO rubric_criterion VALUES(8864,'chem12a3-go-6',NULL,1,'CO₂(aq) + H₂O(l) ⇌ H₂CO₃(aq);',1,1);
INSERT INTO rubric_criterion VALUES(8865,'chem12a3-go-6',NULL,2,'H₂CO₃(aq) + H₂O(l) ⇌ HCO₃⁻(aq) + H₃O⁺(aq), and the rise in [H₃O⁺] lowers the pH (some HCO₃⁻ also ionises further to CO₃²⁻ and H₃O⁺).',1,1);
INSERT INTO rubric_criterion VALUES(8866,'chem12a3-go-7',NULL,0,'Shells form by Ca²⁺(aq) + CO₃²⁻(aq) → CaCO₃(s), which needs a good supply of carbonate ions;',1,1);
INSERT INTO rubric_criterion VALUES(8867,'chem12a3-go-7',NULL,1,'extra H₃O⁺ from dissolved CO₂ converts carbonate to hydrogencarbonate (H₃O⁺(aq) + CO₃²⁻(aq) → HCO₃⁻(aq) + H₂O(l)), so less CO₃²⁻ is available and shell building costs organisms more energy;',1,1);
INSERT INTO rubric_criterion VALUES(8868,'chem12a3-go-7',NULL,2,'at lower pH existing shells can dissolve: CaCO₃(s) + H₃O⁺(aq) → Ca²⁺(aq) + HCO₃⁻(aq) + H₂O(l).',1,1);
INSERT INTO rubric_criterion VALUES(8869,'chem12a3-go-8',NULL,0,'The natural greenhouse effect is warming from naturally occurring greenhouse gases that keeps Earth''s average temperature about 33 °C warmer than it would be otherwise;',1,1);
INSERT INTO rubric_criterion VALUES(8870,'chem12a3-go-8',NULL,1,'the enhanced greenhouse effect is the additional warming caused by human activities (fossil fuel combustion, land clearing, agriculture) raising greenhouse gas concentrations;',1,1);
INSERT INTO rubric_criterion VALUES(8871,'chem12a3-go-8',NULL,2,'methane absorbs infrared radiation far more effectively per molecule than CO₂ (a global warming potential of roughly 25–30 times CO₂ over 100 years), so emissions from livestock, landfill and gas leaks have a large effect.',1,1);
INSERT INTO rubric_criterion VALUES(8885,'chem12a3-go-22',NULL,0,'[H₃O⁺] = 10⁻ᵖᴴ, so initial [H₃O⁺] = 10⁻⁸·² = 6.3 × 10⁻⁹ M [1];',1,1);
INSERT INTO rubric_criterion VALUES(8886,'chem12a3-go-22',NULL,1,'final [H₃O⁺] = 10⁻⁷·⁹ = 1.3 × 10⁻⁸ M [1];',1,1);
INSERT INTO rubric_criterion VALUES(8887,'chem12a3-go-22',NULL,2,'the ratio is 10⁰·³ ≈ 2.0, so [H₃O⁺] doubles [1].',1,1);
INSERT INTO rubric_criterion VALUES(8888,'chem12a3-go-23',NULL,0,'CO₂: burning fossil fuels (or land clearing) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8889,'chem12a3-go-23',NULL,1,'CH₄: livestock digestion, landfill or rice paddies (or gas leaks) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8890,'chem12a3-go-23',NULL,2,'N₂O: use of nitrogen-based fertilisers (or some industrial processes) [1].',1,1);
INSERT INTO rubric_criterion VALUES(8891,'chem12a3-go-24',NULL,0,'C₃H₈(g) + 5O₂(g) → 3CO₂(g) + 4H₂O(l) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8892,'chem12a3-go-24',NULL,1,'n(C₃H₈) = 5.00 ÷ 44.0 = 0.114 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8893,'chem12a3-go-24',NULL,2,'n(CO₂) = 3 × 0.1136 = 0.341 mol [1];',1,1);
INSERT INTO rubric_criterion VALUES(8894,'chem12a3-go-24',NULL,3,'V(CO₂) = 0.341 × 24.8 = 8.45 L [1].',1,1);
INSERT INTO rubric_criterion VALUES(8898,'chem12a3-go-28',NULL,0,'The dissolving of CO₂ is exothermic: CO₂(g) ⇌ CO₂(aq), ΔH < 0 [1];',1,1);
INSERT INTO rubric_criterion VALUES(8899,'chem12a3-go-28',NULL,1,'a rise in temperature favours the endothermic (reverse) reaction, so the equilibrium shifts left and less CO₂ stays dissolved [1];',1,1);
INSERT INTO rubric_criterion VALUES(8900,'chem12a3-go-28',NULL,2,'less CO₂ is absorbed by the oceans, so more remains in the atmosphere, strengthening the enhanced greenhouse effect [1].',1,1);
INSERT INTO rubric_criterion VALUES(8901,'chem12a3-go-29',NULL,0,'CO₂-e from methane = 150 × 28 = 4200 t [1];',1,1);
INSERT INTO rubric_criterion VALUES(8902,'chem12a3-go-29',NULL,1,'CO₂-e from nitrous oxide = 4.0 × 265 = 1060 t [1];',1,1);
INSERT INTO rubric_criterion VALUES(8903,'chem12a3-go-29',NULL,2,'total = 4200 + 1060 = 5260 t (5.3 × 10³ t) CO₂-equivalent [1].',1,1);
INSERT INTO rubric_criterion VALUES(8904,'chem12a3-go-30',NULL,0,'C(s) + O₂(g) → CO₂(g) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8905,'chem12a3-go-30',NULL,1,'n(C) = 1.00 × 10⁶ ÷ 12.0 = 8.33 × 10⁴ mol = n(CO₂) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8906,'chem12a3-go-30',NULL,2,'m(CO₂) = 8.33 × 10⁴ × 44.0 = 3.67 × 10⁶ g (3.67 × 10³ kg) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8907,'chem12a3-go-30',NULL,3,'V(CO₂) = 8.33 × 10⁴ × 24.8 = 2.07 × 10⁶ L [1].',1,1);
INSERT INTO rubric_criterion VALUES(8914,'bio12a1-ct-6',NULL,0,'Cells exchange materials (nutrients, O₂, wastes) across their plasma membrane; small cells have a high SA:V ratio so the membrane area can supply the volume quickly enough / diffusion distances to the centre stay short;',1,1);
INSERT INTO rubric_criterion VALUES(8915,'bio12a1-ct-6',NULL,1,'large cells would have too little membrane relative to volume and could not meet metabolic demands.',1,1);
INSERT INTO rubric_criterion VALUES(8916,'bio12a1-ct-7',NULL,0,'X: SA = 6 × 16 = 96 µm², V = 64 µm³, SA:V = 1.5:1;',1,1);
INSERT INTO rubric_criterion VALUES(8917,'bio12a1-ct-7',NULL,1,'Y: SA = 6 × 64 = 384 µm², V = 512 µm³, SA:V = 0.75:1;',1,1);
INSERT INTO rubric_criterion VALUES(8918,'bio12a1-ct-7',NULL,2,'cell X is more efficient because it has the higher SA:V ratio (twice that of Y).',1,1);
INSERT INTO rubric_criterion VALUES(8919,'bio12a1-ct-8',NULL,0,'Microscopes allowed cells to be observed for the first time (e.g. Hooke''s cork cells, van Leeuwenhoek''s microorganisms);',1,1);
INSERT INTO rubric_criterion VALUES(8920,'bio12a1-ct-8',NULL,1,'repeated observation of cells in all plant and animal tissues, and of cells dividing, provided the evidence that all organisms are made of cells and that cells come from pre-existing cells.',1,1);
INSERT INTO rubric_criterion VALUES(8936,'bio12a1-ct-24',NULL,0,'Surface area = 2(2 × 3 + 3 × 5 + 2 × 5) = 2(6 + 15 + 10) = 62 µm² [1];',1,1);
INSERT INTO rubric_criterion VALUES(8937,'bio12a1-ct-24',NULL,1,'volume = 2 × 3 × 5 = 30 µm³ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8938,'bio12a1-ct-24',NULL,2,'SA:V = 62 ÷ 30 ≈ 2.1:1 [1]',1,1);
INSERT INTO rubric_criterion VALUES(8939,'bio12a1-ct-25',NULL,0,'The claim is incorrect [1];',1,1);
INSERT INTO rubric_criterion VALUES(8940,'bio12a1-ct-25',NULL,1,'the large cell has more total membrane but a lower SA:V, so less membrane is available per unit of cytoplasm to exchange materials [1]',1,1);
INSERT INTO rubric_criterion VALUES(8941,'bio12a1-ct-26',NULL,0,'Magnification is how many times larger the image appears than the specimen [1];',1,1);
INSERT INTO rubric_criterion VALUES(8942,'bio12a1-ct-26',NULL,1,'resolution is the smallest distance between two points that can still be seen as separate points [1]',1,1);
INSERT INTO rubric_criterion VALUES(8943,'bio12a1-ct-27',NULL,0,'Actual length = 60 mm ÷ 1500 = 0.04 mm [1];',1,1);
INSERT INTO rubric_criterion VALUES(8944,'bio12a1-ct-27',NULL,1,'0.04 mm × 1000 = 40 µm [1]',1,1);
INSERT INTO rubric_criterion VALUES(8945,'bio12a1-ct-28',NULL,0,'Stated that all cells arise only from pre-existing cells, by cell division [1];',1,1);
INSERT INTO rubric_criterion VALUES(8946,'bio12a1-ct-28',NULL,1,'this completed cell theory by explaining how new cells, and therefore growth and repair, are produced [1]',1,1);
INSERT INTO rubric_criterion VALUES(8947,'bio12a1-ct-29',NULL,0,'As side length increases, the SA:V ratio decreases, so the two are inversely proportional [1];',1,1);
INSERT INTO rubric_criterion VALUES(8948,'bio12a1-ct-29',NULL,1,'for a cube, SA:V = 6 ÷ side length [1];',1,1);
INSERT INTO rubric_criterion VALUES(8949,'bio12a1-ct-29',NULL,2,'surface area increases with the square of the side length while volume increases with the cube, so volume increases faster [1]',1,1);
INSERT INTO rubric_criterion VALUES(8956,'bio12a1-pe-6',NULL,0,'Any two: eukaryotes have a membrane-bound nucleus while prokaryotes have a nucleoid region; eukaryotes have membrane-bound organelles (e.g. mitochondria, ER) while prokaryotes do not;',1,1);
INSERT INTO rubric_criterion VALUES(8957,'bio12a1-pe-6',NULL,1,'prokaryotic DNA is circular while eukaryotic DNA is linear; prokaryotes have smaller (70S) ribosomes; prokaryotes are generally much smaller.',1,1);
INSERT INTO rubric_criterion VALUES(8958,'bio12a1-pe-7',NULL,0,'A plant (eukaryotic, photosynthetic) cell; the nucleus and mitochondria show it is eukaryotic, and the chloroplasts and cell wall together indicate a plant cell (animal cells lack both;',1,1);
INSERT INTO rubric_criterion VALUES(8959,'bio12a1-pe-7',NULL,1,'fungi lack chloroplasts).',1,1);
INSERT INTO rubric_criterion VALUES(8960,'bio12a1-pe-8',NULL,0,'Organelles separate incompatible reactions and keep enzymes and substrates concentrated in specific compartments (e.g. hydrolytic enzymes in lysosomes);',1,1);
INSERT INTO rubric_criterion VALUES(8961,'bio12a1-pe-8',NULL,1,'this increases the efficiency of metabolism and allows eukaryotic cells to be larger and more complex than prokaryotes.',1,1);
INSERT INTO rubric_criterion VALUES(8977,'bio12a1-pe-24',NULL,0,'Site of protein synthesis (translation) [1]',1,1);
INSERT INTO rubric_criterion VALUES(8978,'bio12a1-pe-25',NULL,0,'The vacuole takes up water, creating turgor (internal) pressure [1];',1,1);
INSERT INTO rubric_criterion VALUES(8979,'bio12a1-pe-25',NULL,1,'this pushes the plasma membrane against the cellulose cell wall, which resists expansion and keeps the cell firm [1].',1,1);
INSERT INTO rubric_criterion VALUES(8980,'bio12a1-pe-26',NULL,0,'Image size = 10 mm = 10 000 µm [1];',1,1);
INSERT INTO rubric_criterion VALUES(8981,'bio12a1-pe-26',NULL,1,'magnification = image size ÷ actual size = 10 000 ÷ 2 = ×5000 [1].',1,1);
INSERT INTO rubric_criterion VALUES(8982,'bio12a1-pe-27',NULL,0,'Controls the movement of substances into and out of the cell (selectively permeable) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8983,'bio12a1-pe-27',NULL,1,'separates the cell''s contents from its external environment [1].',1,1);
INSERT INTO rubric_criterion VALUES(8984,'bio12a1-pe-28',NULL,0,'Surface area = 6 × 3² = 54 µm² and volume = 3³ = 27 µm³ [1];',1,1);
INSERT INTO rubric_criterion VALUES(8985,'bio12a1-pe-28',NULL,1,'ratio = 54 ÷ 27 = 2:1 [1];',1,1);
INSERT INTO rubric_criterion VALUES(8986,'bio12a1-pe-28',NULL,2,'a larger ratio gives more membrane per unit volume, so exchange of substances with the environment is more efficient [1].',1,1);
INSERT INTO rubric_criterion VALUES(8987,'bio12a1-pe-29',NULL,0,'Total magnification = 10 × 40 = ×400 [1];',1,1);
INSERT INTO rubric_criterion VALUES(8988,'bio12a1-pe-29',NULL,1,'image size = 8 mm = 8000 µm [1];',1,1);
INSERT INTO rubric_criterion VALUES(8989,'bio12a1-pe-29',NULL,2,'actual size = 8000 ÷ 400 = 20 µm [1].',1,1);
INSERT INTO rubric_criterion VALUES(8990,'bio12a1-pe-30',NULL,0,'DNA: bacterium in a nucleoid (not membrane-bound), liver cell in a membrane-bound nucleus [1]; ribosomes: bacterium 70S, liver cell 80S [1];',1,1);
INSERT INTO rubric_criterion VALUES(8991,'bio12a1-pe-30',NULL,1,'membrane-bound organelles: absent in the bacterium, present in the liver cell (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(8992,'bio12a1-pe-30',NULL,2,'mitochondria, endoplasmic reticulum, Golgi apparatus) [1];',1,1);
INSERT INTO rubric_criterion VALUES(8993,'bio12a1-pe-30',NULL,3,'size: bacterium typically 0.1–5 µm, liver cell typically 10–100 µm [1].',1,1);
INSERT INTO rubric_criterion VALUES(8994,'bio12a1-pe-31',NULL,0,'Binary fission replicates the single circular chromosome and the cell divides, so each daughter receives identical DNA [1];',1,1);
INSERT INTO rubric_criterion VALUES(8995,'bio12a1-pe-31',NULL,1,'variation arises from mutations and from the transfer of plasmids between bacteria [1].',1,1);
INSERT INTO rubric_criterion VALUES(8996,'bio12a1-pe-32',NULL,0,'Plasmids carry genes for antibiotic resistance [1];',1,1);
INSERT INTO rubric_criterion VALUES(8997,'bio12a1-pe-32',NULL,1,'plasmids can be transferred from resistant to non-resistant bacteria [1];',1,1);
INSERT INTO rubric_criterion VALUES(8998,'bio12a1-pe-32',NULL,2,'bacteria that have received the plasmid survive treatment, reproduce and increase the proportion of resistant bacteria in the population [1].',1,1);
INSERT INTO rubric_criterion VALUES(9005,'bio12a1-or-6',NULL,0,'Double membrane-bound organelle;',1,1);
INSERT INTO rubric_criterion VALUES(9006,'bio12a1-or-6',NULL,1,'contains stacks of thylakoid membranes (grana) containing chlorophyll, surrounded by fluid stroma;',1,1);
INSERT INTO rubric_criterion VALUES(9007,'bio12a1-or-6',NULL,2,'site of photosynthesis, converting light energy into chemical energy in glucose (light-dependent reactions on thylakoids, light-independent reactions in stroma).',1,1);
INSERT INTO rubric_criterion VALUES(9008,'bio12a1-or-7',NULL,0,'Flight muscle contracts repeatedly and has a very high energy demand;',1,1);
INSERT INTO rubric_criterion VALUES(9009,'bio12a1-or-7',NULL,1,'mitochondria carry out aerobic respiration producing ATP, so more mitochondria supply the large amounts of ATP needed for contraction, whereas skin cells require far less.',1,1);
INSERT INTO rubric_criterion VALUES(9010,'bio12a1-or-8',NULL,0,'The nucleus contains the DNA (chromosomes) holding the genetic instructions;',1,1);
INSERT INTO rubric_criterion VALUES(9011,'bio12a1-or-8',NULL,1,'genes are transcribed into mRNA which leaves through nuclear pores to ribosomes, so the nucleus controls which proteins (including enzymes) are made and hence cell activities.',1,1);
INSERT INTO rubric_criterion VALUES(9024,'bio12a1-or-21',NULL,0,'Site of protein synthesis (translation of mRNA into a polypeptide) [1]',1,1);
INSERT INTO rubric_criterion VALUES(9025,'bio12a1-or-22',NULL,0,'Production of ribosomal subunits, including synthesis of ribosomal RNA [1]',1,1);
INSERT INTO rubric_criterion VALUES(9026,'bio12a1-or-23',NULL,0,'Lack of a nucleus leaves more space for haemoglobin, so more oxygen can be carried per cell [1];',1,1);
INSERT INTO rubric_criterion VALUES(9027,'bio12a1-or-23',NULL,1,'without mitochondria the cell does not use oxygen for its own respiration, so more oxygen is delivered to the tissues [1]',1,1);
INSERT INTO rubric_criterion VALUES(9028,'bio12a1-or-24',NULL,0,'The cell wall is rigid and strong, made of cellulose [1];',1,1);
INSERT INTO rubric_criterion VALUES(9029,'bio12a1-or-24',NULL,1,'it resists the outward pressure (turgor pressure) generated by the vacuole and cytoplasm, so the cell does not burst [1]',1,1);
INSERT INTO rubric_criterion VALUES(9030,'bio12a1-or-25',NULL,0,'Membrane-bound sacs (vesicles) containing hydrolytic (digestive) enzymes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9031,'bio12a1-or-25',NULL,1,'the enzymes break down materials taken into the cell, such as food particles [1];',1,1);
INSERT INTO rubric_criterion VALUES(9032,'bio12a1-or-25',NULL,2,'they also digest worn-out organelles so their components can be recycled [1]',1,1);
INSERT INTO rubric_criterion VALUES(9033,'bio12a1-or-26',NULL,0,'Double membrane: a smooth outer membrane and an inner membrane [1];',1,1);
INSERT INTO rubric_criterion VALUES(9034,'bio12a1-or-26',NULL,1,'the inner membrane is folded into cristae [1];',1,1);
INSERT INTO rubric_criterion VALUES(9035,'bio12a1-or-26',NULL,2,'a fluid matrix containing enzymes, mitochondrial DNA and ribosomes [1]',1,1);
INSERT INTO rubric_criterion VALUES(9036,'bio12a1-or-27',NULL,0,'mRNA is made in the nucleus by transcription of DNA [1];',1,1);
INSERT INTO rubric_criterion VALUES(9037,'bio12a1-or-27',NULL,1,'mRNA cannot pass through the nuclear pores into the cytoplasm [1];',1,1);
INSERT INTO rubric_criterion VALUES(9038,'bio12a1-or-27',NULL,2,'ribosomes in the cytoplasm cannot receive the mRNA template for translation [1];',1,1);
INSERT INTO rubric_criterion VALUES(9039,'bio12a1-or-27',NULL,3,'so fewer proteins (including enzymes) are made, disrupting cell activities [1]',1,1);
INSERT INTO rubric_criterion VALUES(9040,'bio12a1-or-28',NULL,0,'Both have a double outer membrane [1];',1,1);
INSERT INTO rubric_criterion VALUES(9041,'bio12a1-or-28',NULL,1,'the chloroplast has thylakoids stacked in grana containing chlorophyll and a stroma, while the mitochondrion has cristae and a matrix [1];',1,1);
INSERT INTO rubric_criterion VALUES(9042,'bio12a1-or-28',NULL,2,'the chloroplast carries out photosynthesis, converting light energy into chemical energy in glucose [1];',1,1);
INSERT INTO rubric_criterion VALUES(9043,'bio12a1-or-28',NULL,3,'the mitochondrion carries out aerobic respiration, releasing energy from glucose to make ATP [1]',1,1);
INSERT INTO rubric_criterion VALUES(9044,'bio12a1-or-29',NULL,0,'The claim is incorrect [1];',1,1);
INSERT INTO rubric_criterion VALUES(9045,'bio12a1-or-29',NULL,1,'prokaryotic cells such as bacteria have no nucleus, and their DNA lies in a nucleoid region in the cytoplasm [1]',1,1);
INSERT INTO rubric_criterion VALUES(9052,'bio12a1-pm-6',NULL,0,'A phospholipid bilayer with hydrophilic heads facing outward and hydrophobic tails inward;',1,1);
INSERT INTO rubric_criterion VALUES(9053,'bio12a1-pm-6',NULL,1,'proteins (integral/transmembrane and peripheral) are embedded in or attached to the bilayer in a mosaic pattern, with cholesterol and glycoproteins/glycolipids present;',1,1);
INSERT INTO rubric_criterion VALUES(9054,'bio12a1-pm-6',NULL,2,'components can move laterally, so the membrane is fluid.',1,1);
INSERT INTO rubric_criterion VALUES(9055,'bio12a1-pm-7',NULL,0,'O₂ is small and non-polar so it dissolves in and passes through the hydrophobic core of the bilayer;',1,1);
INSERT INTO rubric_criterion VALUES(9056,'bio12a1-pm-7',NULL,1,'Na⁺ is charged and is repelled by the hydrophobic tails, so it needs channel or carrier proteins to cross.',1,1);
INSERT INTO rubric_criterion VALUES(9057,'bio12a1-pm-8',NULL,0,'Any two: transport (channel or carrier proteins); receptors for signalling molecules such as hormones; enzymes;',1,1);
INSERT INTO rubric_criterion VALUES(9058,'bio12a1-pm-8',NULL,1,'cell recognition (glycoproteins); attachment/adhesion to other cells or the cytoskeleton.',1,1);
INSERT INTO rubric_criterion VALUES(9073,'bio12a1-pm-23',NULL,0,'Peptide hormones are polar and charged, so they cannot pass through the hydrophobic core of the bilayer [1];',1,1);
INSERT INTO rubric_criterion VALUES(9074,'bio12a1-pm-23',NULL,1,'they bind to a specific receptor protein on the outer surface of the membrane [1];',1,1);
INSERT INTO rubric_criterion VALUES(9075,'bio12a1-pm-23',NULL,2,'the binding causes a change in the receptor that triggers a response inside the cell, such as a second messenger [1].',1,1);
INSERT INTO rubric_criterion VALUES(9076,'bio12a1-pm-24',NULL,0,'The product of one enzyme is passed directly to the next enzyme in the sequence [1];',1,1);
INSERT INTO rubric_criterion VALUES(9077,'bio12a1-pm-24',NULL,1,'this reduces the time for intermediates to diffuse away, so the pathway runs faster [1].',1,1);
INSERT INTO rubric_criterion VALUES(9078,'bio12a1-pm-25',NULL,0,'Hydrophobic tails exposed at the edges of the tear are unfavourable in water [1];',1,1);
INSERT INTO rubric_criterion VALUES(9079,'bio12a1-pm-25',NULL,1,'the phospholipids rearrange so the tails are shielded and the heads face the water, closing the gap [1].',1,1);
INSERT INTO rubric_criterion VALUES(9080,'bio12a1-pm-26',NULL,0,'3 200 : 12 800 = 1 : 4 [1];',1,1);
INSERT INTO rubric_criterion VALUES(9081,'bio12a1-pm-26',NULL,1,'both values are divided by 3 200 (12 800 ÷ 3 200 = 4) [1].',1,1);
INSERT INTO rubric_criterion VALUES(9082,'bio12a1-pm-27',NULL,0,'20 × 0.15 nm = 3.0 nm [1];',1,1);
INSERT INTO rubric_criterion VALUES(9083,'bio12a1-pm-27',NULL,1,'this equals the thickness of the hydrophobic core, so the helix can just span the bilayer [1].',1,1);
INSERT INTO rubric_criterion VALUES(9084,'bio12a1-pm-28',NULL,0,'The high temperature damages the membranes, disrupting their structure and denaturing their proteins [1];',1,1);
INSERT INTO rubric_criterion VALUES(9085,'bio12a1-pm-28',NULL,1,'the membranes lose their selective permeability [1];',1,1);
INSERT INTO rubric_criterion VALUES(9086,'bio12a1-pm-28',NULL,2,'the red betalain pigment stored in the cells diffuses out into the water [1].',1,1);
INSERT INTO rubric_criterion VALUES(9093,'bio12a1-pt-6',NULL,0,'The net movement of water molecules across a selectively (partially) permeable membrane;',1,1);
INSERT INTO rubric_criterion VALUES(9094,'bio12a1-pt-6',NULL,1,'from a region of lower solute concentration (higher free water concentration) to a region of higher solute concentration.',1,1);
INSERT INTO rubric_criterion VALUES(9095,'bio12a1-pt-7',NULL,0,'Cl⁻ ions normally diffuse out through CFTR channels into the mucus (facilitated diffusion);',1,1);
INSERT INTO rubric_criterion VALUES(9096,'bio12a1-pt-7',NULL,1,'without this, solute concentration outside the cell stays low;',1,1);
INSERT INTO rubric_criterion VALUES(9097,'bio12a1-pt-7',NULL,2,'so less water follows by osmosis into the mucus, leaving it dehydrated, thick and sticky.',1,1);
INSERT INTO rubric_criterion VALUES(9098,'bio12a1-pt-8',NULL,0,'Glucose is a relatively large, polar molecule that cannot pass through the hydrophobic core of the phospholipid bilayer;',1,1);
INSERT INTO rubric_criterion VALUES(9099,'bio12a1-pt-8',NULL,1,'it needs specific carrier (GLUT) proteins to move down its concentration gradient.',1,1);
INSERT INTO rubric_criterion VALUES(9114,'bio12a1-pt-23',NULL,0,'The net movement of particles from a region of higher concentration to a region of lower concentration [1];',1,1);
INSERT INTO rubric_criterion VALUES(9115,'bio12a1-pt-23',NULL,1,'down a concentration gradient, without the input of energy (ATP) [1].',1,1);
INSERT INTO rubric_criterion VALUES(9116,'bio12a1-pt-24',NULL,0,'Heat denatures the membrane proteins and disrupts the phospholipid bilayer, making the membrane more permeable [1];',1,1);
INSERT INTO rubric_criterion VALUES(9117,'bio12a1-pt-24',NULL,1,'so the pigment molecules can diffuse out of the cell down their concentration gradient [1].',1,1);
INSERT INTO rubric_criterion VALUES(9118,'bio12a1-pt-25',NULL,0,'Similarity: both are passive and require no ATP [1];',1,1);
INSERT INTO rubric_criterion VALUES(9119,'bio12a1-pt-25',NULL,1,'both move substances down a concentration gradient [1].',1,1);
INSERT INTO rubric_criterion VALUES(9120,'bio12a1-pt-25',NULL,2,'Difference: simple diffusion needs no membrane protein, whereas facilitated diffusion requires channel or carrier proteins [1];',1,1);
INSERT INTO rubric_criterion VALUES(9121,'bio12a1-pt-25',NULL,3,'facilitated diffusion can become saturated when all carriers are occupied, whereas the rate of simple diffusion rises in proportion to the gradient [1].',1,1);
INSERT INTO rubric_criterion VALUES(9122,'bio12a1-pt-26',NULL,0,'Iodine molecules are small enough to pass through the pores of the dialysis tubing, moving down their concentration gradient into the bag [1];',1,1);
INSERT INTO rubric_criterion VALUES(9123,'bio12a1-pt-26',NULL,1,'the iodine reacts with starch to form a blue-black colour [1];',1,1);
INSERT INTO rubric_criterion VALUES(9124,'bio12a1-pt-26',NULL,2,'starch molecules are too large to pass through the pores and remain in the bag [1].',1,1);
INSERT INTO rubric_criterion VALUES(9125,'bio12a1-pt-27',NULL,0,'Aquaporins are channel proteins embedded in the membrane [1];',1,1);
INSERT INTO rubric_criterion VALUES(9126,'bio12a1-pt-27',NULL,1,'they allow water molecules to cross the membrane rapidly by facilitated diffusion, down the water concentration gradient [1].',1,1);
INSERT INTO rubric_criterion VALUES(9127,'bio12a1-pt-28',NULL,0,'Saline is isotonic to the cytoplasm of the red blood cells [1];',1,1);
INSERT INTO rubric_criterion VALUES(9128,'bio12a1-pt-28',NULL,1,'so water moves in and out at equal rates, with no net water movement [1].',1,1);
INSERT INTO rubric_criterion VALUES(9129,'bio12a1-pt-28',NULL,2,'Distilled water is hypotonic to the cytoplasm (lower solute concentration) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9130,'bio12a1-pt-28',NULL,3,'so water moves into the cells by osmosis, causing them to swell and lyse (burst) [1].',1,1);
INSERT INTO rubric_criterion VALUES(9131,'bio12a1-pt-29',NULL,0,'The concentration gradient becomes smaller as particles spread out [1];',1,1);
INSERT INTO rubric_criterion VALUES(9132,'bio12a1-pt-29',NULL,1,'so there is a smaller difference between the rates of particles moving in each direction, reducing the net movement [1];',1,1);
INSERT INTO rubric_criterion VALUES(9133,'bio12a1-pt-29',NULL,2,'at equilibrium particles move in both directions at equal rates, so the net rate is zero [1].',1,1);
INSERT INTO rubric_criterion VALUES(9140,'bio12a1-at-6',NULL,0,'Similarity: both use specific membrane proteins;',1,1);
INSERT INTO rubric_criterion VALUES(9141,'bio12a1-at-6',NULL,1,'difference: active transport moves substances against their concentration gradient whereas facilitated diffusion moves them down the gradient;',1,1);
INSERT INTO rubric_criterion VALUES(9142,'bio12a1-at-6',NULL,2,'active transport requires energy from ATP whereas facilitated diffusion is passive.',1,1);
INSERT INTO rubric_criterion VALUES(9143,'bio12a1-at-7',NULL,0,'The plasma membrane folds inward (invaginates) around the material outside the cell; the membrane pinches off to form a vesicle that carries the material into the cytoplasm;',1,1);
INSERT INTO rubric_criterion VALUES(9144,'bio12a1-at-7',NULL,1,'it requires energy (ATP) and is a form of bulk transport.',1,1);
INSERT INTO rubric_criterion VALUES(9145,'bio12a1-at-8',NULL,0,'Active transport requires ATP to power protein pumps;',1,1);
INSERT INTO rubric_criterion VALUES(9146,'bio12a1-at-8',NULL,1,'mitochondria produce most ATP through aerobic respiration, so many mitochondria supply the energy needed for continuous active transport.',1,1);
INSERT INTO rubric_criterion VALUES(9158,'bio12a1-at-20',NULL,0,'Golgi apparatus [1].',1,1);
INSERT INTO rubric_criterion VALUES(9159,'bio12a1-at-21',NULL,0,'Endocytosis requires energy from ATP, whereas simple diffusion is passive [1];',1,1);
INSERT INTO rubric_criterion VALUES(9160,'bio12a1-at-21',NULL,1,'endocytosis moves material in bulk inside a membrane-bound vesicle, whereas diffusion moves individual small molecules directly across the membrane [1].',1,1);
INSERT INTO rubric_criterion VALUES(9161,'bio12a1-at-22',NULL,0,'The membrane must extend outwards to surround the bacterium [1];',1,1);
INSERT INTO rubric_criterion VALUES(9162,'bio12a1-at-22',NULL,1,'the flexible phospholipid bilayer and cytoskeleton allow the membrane to deform and enclose the bacterium in a vesicle [1].',1,1);
INSERT INTO rubric_criterion VALUES(9163,'bio12a1-at-23',NULL,0,'Three Na⁺ bind to the pump protein on the inside of the cell [1];',1,1);
INSERT INTO rubric_criterion VALUES(9164,'bio12a1-at-23',NULL,1,'ATP is hydrolysed, the phosphate attaches to the pump and it changes shape, releasing the Na⁺ outside [1];',1,1);
INSERT INTO rubric_criterion VALUES(9165,'bio12a1-at-23',NULL,2,'two K⁺ bind from outside, the phosphate is released and the pump returns to its original shape, releasing the K⁺ inside [1].',1,1);
INSERT INTO rubric_criterion VALUES(9166,'bio12a1-at-24',NULL,0,'The enzyme is synthesised on ribosomes attached to the rough endoplasmic reticulum [1];',1,1);
INSERT INTO rubric_criterion VALUES(9167,'bio12a1-at-24',NULL,1,'it is transported to the Golgi apparatus, where it is packaged into vesicles [1];',1,1);
INSERT INTO rubric_criterion VALUES(9168,'bio12a1-at-24',NULL,2,'the vesicles move to the plasma membrane, fuse with it and release the enzyme outside the cell by exocytosis [1].',1,1);
INSERT INTO rubric_criterion VALUES(9169,'bio12a1-at-25',NULL,0,'In endocytosis the membrane folds inwards around material outside the cell and pinches off a vesicle that carries it into the cytoplasm [1];',1,1);
INSERT INTO rubric_criterion VALUES(9170,'bio12a1-at-25',NULL,1,'in exocytosis a vesicle fuses with the plasma membrane and releases its contents outside [1];',1,1);
INSERT INTO rubric_criterion VALUES(9171,'bio12a1-at-25',NULL,2,'both processes require energy from ATP [1];',1,1);
INSERT INTO rubric_criterion VALUES(9172,'bio12a1-at-25',NULL,3,'the fluid phospholipid bilayer allows the membrane to deform and fuse with vesicle membranes [1].',1,1);
INSERT INTO rubric_criterion VALUES(9179,'bio12a1-bf-6',NULL,0,'The circular chromosome (and any plasmids) is replicated;',1,1);
INSERT INTO rubric_criterion VALUES(9180,'bio12a1-bf-6',NULL,1,'the cell elongates and the two chromosome copies move to opposite ends;',1,1);
INSERT INTO rubric_criterion VALUES(9181,'bio12a1-bf-6',NULL,2,'the plasma membrane pinches inward and a new cell wall (septum) forms, splitting the cell into two genetically identical daughter cells.',1,1);
INSERT INTO rubric_criterion VALUES(9182,'bio12a1-bf-7',NULL,0,'4 h = 8 generations;',1,1);
INSERT INTO rubric_criterion VALUES(9183,'bio12a1-bf-7',NULL,1,'10 × 2⁸ = 10 × 256 = 2560 cells;',1,1);
INSERT INTO rubric_criterion VALUES(9184,'bio12a1-bf-7',NULL,2,'growth slows because nutrients run out / wastes accumulate / space becomes limited.',1,1);
INSERT INTO rubric_criterion VALUES(9185,'bio12a1-bf-8',NULL,0,'Binary fission is a simple, rapid process with short generation times (e.g. ~20 min);',1,1);
INSERT INTO rubric_criterion VALUES(9186,'bio12a1-bf-8',NULL,1,'the number of cells doubles each generation, so the population grows exponentially and can reach very large numbers quickly.',1,1);
INSERT INTO rubric_criterion VALUES(9200,'bio12a1-bf-22',NULL,0,'The chromosome is replicated before division, so the parent has two copies of its DNA [1];',1,1);
INSERT INTO rubric_criterion VALUES(9201,'bio12a1-bf-22',NULL,1,'each daughter receives one complete copy, the same amount of DNA as the original parent cell [1].',1,1);
INSERT INTO rubric_criterion VALUES(9202,'bio12a1-bf-23',NULL,0,'8000 ÷ 250 = 32 = 2⁵, so 5 generations occurred [1];',1,1);
INSERT INTO rubric_criterion VALUES(9203,'bio12a1-bf-23',NULL,1,'3 hours = 180 minutes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9204,'bio12a1-bf-23',NULL,2,'generation time = 180 ÷ 5 = 36 minutes [1].',1,1);
INSERT INTO rubric_criterion VALUES(9205,'bio12a1-bf-24',NULL,0,'Some bacteria carry plasmids with genes for antibiotic resistance [1];',1,1);
INSERT INTO rubric_criterion VALUES(9206,'bio12a1-bf-24',NULL,1,'the plasmid can be transferred to other bacteria, spreading the resistance genes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9207,'bio12a1-bf-24',NULL,2,'the surviving resistant cells divide by binary fission, so the resistant population grows rapidly [1].',1,1);
INSERT INTO rubric_criterion VALUES(9208,'bio12a1-bf-25',NULL,0,'Similarity: the DNA is replicated before the cell divides [1];',1,1);
INSERT INTO rubric_criterion VALUES(9209,'bio12a1-bf-25',NULL,1,'similarity: both produce two genetically identical daughter cells [1];',1,1);
INSERT INTO rubric_criterion VALUES(9210,'bio12a1-bf-25',NULL,2,'difference: binary fission does not use a spindle of microtubules, whereas mitosis does [1];',1,1);
INSERT INTO rubric_criterion VALUES(9211,'bio12a1-bf-25',NULL,3,'difference: a prokaryote has one circular chromosome not enclosed in a nucleus, whereas a eukaryote has multiple linear chromosomes enclosed in a nucleus [1].',1,1);
INSERT INTO rubric_criterion VALUES(9212,'bio12a1-bf-26',NULL,0,'Each daughter cell must receive one complete copy of the chromosome [1];',1,1);
INSERT INTO rubric_criterion VALUES(9213,'bio12a1-bf-26',NULL,1,'separating before replication is complete would leave a cell with incomplete genetic information [1].',1,1);
INSERT INTO rubric_criterion VALUES(9220,'bio12a1-cc-6',NULL,0,'Prophase: chromosomes condense and become visible as two sister chromatids joined at a centromere;',1,1);
INSERT INTO rubric_criterion VALUES(9221,'bio12a1-cc-6',NULL,1,'the nuclear envelope breaks down and spindle fibres begin to form from the centrosomes;',1,1);
INSERT INTO rubric_criterion VALUES(9222,'bio12a1-cc-6',NULL,2,'metaphase: chromosomes line up along the equator (metaphase plate) with spindle fibres attached to each centromere.',1,1);
INSERT INTO rubric_criterion VALUES(9223,'bio12a1-cc-7',NULL,0,'Checkpoints are control points where the cell checks conditions before proceeding; G1 checks cell size, nutrients and DNA damage before replication, and G2 checks that DNA has been replicated completely and correctly before mitosis;',1,1);
INSERT INTO rubric_criterion VALUES(9224,'bio12a1-cc-7',NULL,1,'if problems are detected the cycle is halted for repair or apoptosis.',1,1);
INSERT INTO rubric_criterion VALUES(9225,'bio12a1-cc-8',NULL,0,'Mitosis produces genetically identical daughter cells;',1,1);
INSERT INTO rubric_criterion VALUES(9226,'bio12a1-cc-8',NULL,1,'this allows growth, repair/replacement of damaged or worn-out cells, and asexual reproduction, while keeping the chromosome number constant.',1,1);
INSERT INTO rubric_criterion VALUES(9240,'bio12a1-cc-22',NULL,0,'Cleavage furrow (formed by a contractile ring of actin filaments) [1]',1,1);
INSERT INTO rubric_criterion VALUES(9241,'bio12a1-cc-23',NULL,0,'The period of the cell cycle between divisions in which the cell grows, replicates its DNA and prepares for mitosis [1]',1,1);
INSERT INTO rubric_criterion VALUES(9242,'bio12a1-cc-24',NULL,0,'A chromosome consists of two sister chromatids joined at the centromere after S phase [1];',1,1);
INSERT INTO rubric_criterion VALUES(9243,'bio12a1-cc-24',NULL,1,'a chromatid is one of the two identical copies of DNA that make up a replicated chromosome [1]',1,1);
INSERT INTO rubric_criterion VALUES(9244,'bio12a1-cc-25',NULL,0,'Telophase: the chromosomes reach the poles and decondense [1];',1,1);
INSERT INTO rubric_criterion VALUES(9245,'bio12a1-cc-25',NULL,1,'a nuclear envelope reforms around each set of chromosomes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9246,'bio12a1-cc-25',NULL,2,'cytokinesis: a cleavage furrow forms and pinches the cytoplasm into two separate daughter cells [1]',1,1);
INSERT INTO rubric_criterion VALUES(9247,'bio12a1-cc-26',NULL,0,'G1: the cell grows and makes proteins and organelles [1];',1,1);
INSERT INTO rubric_criterion VALUES(9248,'bio12a1-cc-26',NULL,1,'S: DNA is replicated so that each chromosome has two sister chromatids [1];',1,1);
INSERT INTO rubric_criterion VALUES(9249,'bio12a1-cc-26',NULL,2,'G2: the cell continues to grow, checks the replicated DNA and makes proteins needed for division, such as tubulin for spindle fibres [1]',1,1);
INSERT INTO rubric_criterion VALUES(9250,'bio12a1-cc-27',NULL,0,'Mitosis produces two daughter cells, not four [1];',1,1);
INSERT INTO rubric_criterion VALUES(9251,'bio12a1-cc-27',NULL,1,'each daughter cell has the same (diploid) chromosome number as the parent, not half [1]',1,1);
INSERT INTO rubric_criterion VALUES(9252,'bio12a1-cc-28',NULL,0,'Embryonic cells divide rapidly to produce the cells needed for growth [1];',1,1);
INSERT INTO rubric_criterion VALUES(9253,'bio12a1-cc-28',NULL,1,'so a greater proportion of cells are in mitosis at any one time [1];',1,1);
INSERT INTO rubric_criterion VALUES(9254,'bio12a1-cc-28',NULL,2,'cells in mature liver tissue divide only rarely, so few are in mitosis [1];',1,1);
INSERT INTO rubric_criterion VALUES(9255,'bio12a1-cc-28',NULL,3,'the mitotic index is the proportion of cells in mitosis, so it is higher in the embryo [1]',1,1);
INSERT INTO rubric_criterion VALUES(9256,'bio12a1-cc-29',NULL,0,'Time in mitosis = 18 − (8 + 7 + 2) = 1 hour [1];',1,1);
INSERT INTO rubric_criterion VALUES(9257,'bio12a1-cc-29',NULL,1,'time in interphase = 8 + 7 + 2 = 17 hours [1];',1,1);
INSERT INTO rubric_criterion VALUES(9258,'bio12a1-cc-29',NULL,2,'17 ÷ 18 × 100 = 94.4% (about 94%) of the cycle [1]',1,1);
INSERT INTO rubric_criterion VALUES(9265,'bio12a1-ap-6',NULL,0,'The intrinsic pathway is triggered by signals from within the cell (e.g. DNA damage) causing mitochondria to release cytochrome c, which activates caspases;',1,1);
INSERT INTO rubric_criterion VALUES(9266,'bio12a1-ap-6',NULL,1,'the extrinsic pathway is triggered by external signal molecules (e.g. from immune cells) binding to death receptors on the plasma membrane, which activates caspases.',1,1);
INSERT INTO rubric_criterion VALUES(9267,'bio12a1-ap-7',NULL,0,'Proto-oncogenes code for proteins that promote normal cell division;',1,1);
INSERT INTO rubric_criterion VALUES(9268,'bio12a1-ap-7',NULL,1,'a mutation can convert it into an oncogene that is permanently ''switched on'' / overactive;',1,1);
INSERT INTO rubric_criterion VALUES(9269,'bio12a1-ap-7',NULL,2,'cells divide uncontrollably regardless of signals, forming a mass of cells (tumour).',1,1);
INSERT INTO rubric_criterion VALUES(9270,'bio12a1-ap-8',NULL,0,'Mitosis replaces cells while apoptosis removes old, damaged or unneeded cells; if apoptosis is too low, cells accumulate (e.g. cancer);',1,1);
INSERT INTO rubric_criterion VALUES(9271,'bio12a1-ap-8',NULL,1,'if too high, tissue is lost (e.g. degenerative disease), so balance maintains a constant, healthy cell number.',1,1);
INSERT INTO rubric_criterion VALUES(9285,'bio12a1-ap-22',NULL,0,'A benign tumour stays in one place and does not invade surrounding tissue [1];',1,1);
INSERT INTO rubric_criterion VALUES(9286,'bio12a1-ap-22',NULL,1,'a malignant tumour invades nearby tissue and can spread to other parts of the body, disrupting organ function [1].',1,1);
INSERT INTO rubric_criterion VALUES(9287,'bio12a1-ap-23',NULL,0,'The drugs damage DNA or block mitosis, killing cells that divide rapidly [1];',1,1);
INSERT INTO rubric_criterion VALUES(9288,'bio12a1-ap-23',NULL,1,'hair follicle cells and the cells lining the digestive tract also divide rapidly [1];',1,1);
INSERT INTO rubric_criterion VALUES(9289,'bio12a1-ap-23',NULL,2,'so these healthy cells are damaged too, causing side effects [1].',1,1);
INSERT INTO rubric_criterion VALUES(9290,'bio12a1-ap-24',NULL,0,'12 000 − 9 500 = 2 500 cells gained per day [1];',1,1);
INSERT INTO rubric_criterion VALUES(9291,'bio12a1-ap-24',NULL,1,'the tissue is growing, as its cell number is increasing [1].',1,1);
INSERT INTO rubric_criterion VALUES(9292,'bio12a1-ap-25',NULL,0,'Mitotic index = 21 ÷ 350 × 100 [1] = 6% [1].',2,1);
INSERT INTO rubric_criterion VALUES(9293,'bio12a1-ap-26',NULL,0,'UV radiation is absorbed by DNA, forming thymine dimers that distort the DNA [1];',1,1);
INSERT INTO rubric_criterion VALUES(9294,'bio12a1-ap-26',NULL,1,'if these are not repaired correctly, the DNA base sequence is changed (a mutation) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9295,'bio12a1-ap-26',NULL,2,'mutations in genes controlling the cell cycle or apoptosis can cause cells to divide uncontrollably and form a tumour [1].',1,1);
INSERT INTO rubric_criterion VALUES(9296,'bio12a1-ap-27',NULL,0,'Cells in a tumour continue to acquire mutations as they divide [1];',1,1);
INSERT INTO rubric_criterion VALUES(9297,'bio12a1-ap-27',NULL,1,'cells with mutations that increase division or help them escape apoptosis have a growth advantage and out-compete other cells [1];',1,1);
INSERT INTO rubric_criterion VALUES(9298,'bio12a1-ap-27',NULL,2,'this produces a more aggressive population that may spread to other tissues [1].',1,1);
INSERT INTO rubric_criterion VALUES(9299,'bio12a1-ap-28',NULL,0,'Normal cells receive a signal from neighbouring cells that halts division [1];',1,1);
INSERT INTO rubric_criterion VALUES(9300,'bio12a1-ap-28',NULL,1,'cancer cells do not respond to this signal, so they keep dividing and form a mass [1].',1,1);
INSERT INTO rubric_criterion VALUES(9301,'bio12a1-ap-29',NULL,0,'Without a working enzyme, DNA errors and damage are not corrected [1];',1,1);
INSERT INTO rubric_criterion VALUES(9302,'bio12a1-ap-29',NULL,1,'mutations then accumulate in genes controlling cell division, increasing the likelihood of cancer [1].',1,1);
INSERT INTO rubric_criterion VALUES(9303,'bio12a1-ap-30',NULL,0,'Cancer cells detach from the primary tumour and invade the surrounding tissue [1];',1,1);
INSERT INTO rubric_criterion VALUES(9304,'bio12a1-ap-30',NULL,1,'they enter the blood or lymphatic system [1];',1,1);
INSERT INTO rubric_criterion VALUES(9305,'bio12a1-ap-30',NULL,2,'they travel to a distant site, where they settle and divide to form a secondary tumour [1].',1,1);
INSERT INTO rubric_criterion VALUES(9312,'bio12a1-sc-6',NULL,0,'Advantage: they are pluripotent, so can potentially form any body cell type to treat many diseases (e.g. replace damaged nerve or heart cells);',1,1);
INSERT INTO rubric_criterion VALUES(9313,'bio12a1-sc-6',NULL,1,'concern: obtaining them destroys an embryo, which some people believe has the moral status of a person.',1,1);
INSERT INTO rubric_criterion VALUES(9314,'bio12a1-sc-7',NULL,0,'Function is to transport oxygen;',1,1);
INSERT INTO rubric_criterion VALUES(9315,'bio12a1-sc-7',NULL,1,'it lacks a nucleus and most organelles so there is more room for haemoglobin, and its biconcave disc shape gives a high SA:V for rapid diffusion of O₂ (and flexibility to pass through capillaries).',1,1);
INSERT INTO rubric_criterion VALUES(9316,'bio12a1-sc-8',NULL,0,'Specialised cells of a similar type form tissues (e.g. cardiac muscle cells form cardiac muscle tissue);',1,1);
INSERT INTO rubric_criterion VALUES(9317,'bio12a1-sc-8',NULL,1,'different tissues work together to form an organ (e.g. the heart contains muscle, nervous and connective tissue);',1,1);
INSERT INTO rubric_criterion VALUES(9318,'bio12a1-sc-8',NULL,2,'organs work together in an organ system (e.g. heart and blood vessels form the circulatory system).',1,1);
INSERT INTO rubric_criterion VALUES(9331,'bio12a1-sc-21',NULL,0,'Differentiation [1]',1,1);
INSERT INTO rubric_criterion VALUES(9332,'bio12a1-sc-22',NULL,0,'Collection is non-invasive, so the donor does not need surgery or experience pain [1].',1,1);
INSERT INTO rubric_criterion VALUES(9333,'bio12a1-sc-23',NULL,0,'Division of labour means each cell type can be structurally and functionally adapted to carry out one role efficiently [1];',1,1);
INSERT INTO rubric_criterion VALUES(9334,'bio12a1-sc-23',NULL,1,'cells can be grouped into tissues and organs that perform complex tasks no single cell could carry out [1].',1,1);
INSERT INTO rubric_criterion VALUES(9335,'bio12a1-sc-24',NULL,0,'Embryonic stem cells come from the early embryo, before cells have committed to a lineage, so they can form all body cell types (pluripotent) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9336,'bio12a1-sc-24',NULL,1,'adult stem cells are found in mature tissues and have become restricted to forming the cell types of that tissue (multipotent) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9337,'bio12a1-sc-24',NULL,2,'as development proceeds, the genes for other cell types are progressively switched off [1].',1,1);
INSERT INTO rubric_criterion VALUES(9338,'bio12a1-sc-25',NULL,0,'Stem cells at the base of intestinal crypts divide by mitosis to produce new daughter cells [1];',1,1);
INSERT INTO rubric_criterion VALUES(9339,'bio12a1-sc-25',NULL,1,'some daughter cells differentiate into specialised cells, such as absorptive cells, by switching on particular genes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9340,'bio12a1-sc-25',NULL,2,'older cells move up to the tip of the villus, where they are shed, so the lining is replaced about every few days [1].',1,1);
INSERT INTO rubric_criterion VALUES(9341,'bio12a1-sc-26',NULL,0,'Cells in the tissue are undifferentiated, stem-like cells that can still divide and form new tissues [1];',1,1);
INSERT INTO rubric_criterion VALUES(9342,'bio12a1-sc-26',NULL,1,'hormones in the growth medium stimulate them to divide, forming an undifferentiated mass called a callus [1];',1,1);
INSERT INTO rubric_criterion VALUES(9343,'bio12a1-sc-26',NULL,2,'cells in the callus then differentiate into roots and shoots, producing genetically identical plants (clones) [1].',1,1);
INSERT INTO rubric_criterion VALUES(9350,'bio12a1-pl-6',NULL,0,'Water enters root hair cells by osmosis because the cell sap has a lower water potential / higher solute concentration than the soil (minerals are actively transported in);',1,1);
INSERT INTO rubric_criterion VALUES(9351,'bio12a1-pl-6',NULL,1,'water moves across the cortex via the cell walls and cytoplasm;',1,1);
INSERT INTO rubric_criterion VALUES(9352,'bio12a1-pl-6',NULL,2,'at the endodermis the Casparian strip forces water through the cytoplasm before it enters the xylem.',1,1);
INSERT INTO rubric_criterion VALUES(9353,'bio12a1-pl-7',NULL,0,'When water loss exceeds uptake, the plant closes its stomata (guard cells lose turgor) to conserve water;',1,1);
INSERT INTO rubric_criterion VALUES(9354,'bio12a1-pl-7',NULL,1,'less water vapour can diffuse out of the leaf, so transpiration rate decreases.',1,1);
INSERT INTO rubric_criterion VALUES(9355,'bio12a1-pl-8',NULL,0,'Xylem consists of dead, hollow, lignified vessels while phloem consists of living sieve tube elements and companion cells;',1,1);
INSERT INTO rubric_criterion VALUES(9356,'bio12a1-pl-8',NULL,1,'xylem transports water and minerals while phloem transports sugars (sucrose) and other organic compounds;',1,1);
INSERT INTO rubric_criterion VALUES(9357,'bio12a1-pl-8',NULL,2,'xylem flow is upward only (from roots) while phloem transports sugars in both directions from sources to sinks.',1,1);
INSERT INTO rubric_criterion VALUES(9371,'bio12a1-pl-22',NULL,0,'Transpiration is the loss of water vapour from the aerial parts of a plant [1];',1,1);
INSERT INTO rubric_criterion VALUES(9372,'bio12a1-pl-22',NULL,1,'most of it occurs through the stomata in the leaves [1].',1,1);
INSERT INTO rubric_criterion VALUES(9373,'bio12a1-pl-23',NULL,0,'Xylem vessels lose their cytoplasm and nucleus at maturity, leaving hollow, lignified tubes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9374,'bio12a1-pl-23',NULL,1,'with no living contents to obstruct flow, water moves continuously through the vessels as a column [1].',1,1);
INSERT INTO rubric_criterion VALUES(9375,'bio12a1-pl-24',NULL,0,'Dry soil reduces the water available for uptake by the roots, so less water reaches the leaves [1];',1,1);
INSERT INTO rubric_criterion VALUES(9376,'bio12a1-pl-24',NULL,1,'stomata close to conserve water, reducing the entry of CO₂ into the leaf [1];',1,1);
INSERT INTO rubric_criterion VALUES(9377,'bio12a1-pl-24',NULL,2,'the lower CO₂ concentration in the leaf reduces the rate of photosynthesis [1].',1,1);
INSERT INTO rubric_criterion VALUES(9378,'bio12a1-pl-25',NULL,0,'The waxy cuticle is waterproof, so it reduces evaporation from the leaf epidermis [1];',1,1);
INSERT INTO rubric_criterion VALUES(9379,'bio12a1-pl-25',NULL,1,'most water loss therefore occurs through the stomata [1];',1,1);
INSERT INTO rubric_criterion VALUES(9380,'bio12a1-pl-25',NULL,2,'if the cuticle is damaged, water loss through the epidermis increases and the rate of transpiration rises [1].',1,1);
INSERT INTO rubric_criterion VALUES(9381,'bio12a1-pl-26',NULL,0,'Guard cells [1].',1,1);
INSERT INTO rubric_criterion VALUES(9382,'bio12a1-pl-27',NULL,0,'Mineral ions are often at a lower concentration in the soil than in root cells, so they must be moved against a concentration gradient [1];',1,1);
INSERT INTO rubric_criterion VALUES(9383,'bio12a1-pl-27',NULL,1,'this requires ATP from cellular respiration, as the process is active transport [1];',1,1);
INSERT INTO rubric_criterion VALUES(9384,'bio12a1-pl-27',NULL,2,'water moves down its water potential gradient by osmosis, which requires no energy input [1].',1,1);
INSERT INTO rubric_criterion VALUES(9385,'bio12a1-pl-28',NULL,0,'Advantage: the transpiration pull moves water and dissolved minerals up the xylem [1];',1,1);
INSERT INTO rubric_criterion VALUES(9386,'bio12a1-pl-28',NULL,1,'advantage: evaporation of water from the leaf cools the leaf [1];',1,1);
INSERT INTO rubric_criterion VALUES(9387,'bio12a1-pl-28',NULL,2,'disadvantage: water loss can cause wilting if uptake cannot keep pace [1];',1,1);
INSERT INTO rubric_criterion VALUES(9388,'bio12a1-pl-28',NULL,3,'disadvantage: stomata must be open for CO₂ uptake, so water is lost at the same time [1].',1,1);
INSERT INTO rubric_criterion VALUES(9389,'bio12a1-pl-29',NULL,0,'Small or needle-shaped leaves reduce the surface area available for transpiration [1];',1,1);
INSERT INTO rubric_criterion VALUES(9390,'bio12a1-pl-29',NULL,1,'sunken stomata in pits trap humid air around the pores, reducing water loss [1].',1,1);
INSERT INTO rubric_criterion VALUES(9391,'bio12a1-pl-30',NULL,0,'The cut shoot takes up water, so the movement of an air bubble along the capillary tube measures water uptake [1];',1,1);
INSERT INTO rubric_criterion VALUES(9392,'bio12a1-pl-30',NULL,1,'the distance moved by the bubble per unit time gives the rate [1];',1,1);
INSERT INTO rubric_criterion VALUES(9393,'bio12a1-pl-30',NULL,2,'assumption: water taken up equals water lost by transpiration, so water used in photosynthesis or growth is negligible [1].',1,1);
INSERT INTO rubric_criterion VALUES(9400,'bio12a2-dig-6',NULL,0,'Mechanical digestion physically breaks food into smaller pieces without changing its chemical make-up, e.g. chewing by teeth or churning in the stomach;',1,1);
INSERT INTO rubric_criterion VALUES(9401,'bio12a2-dig-6',NULL,1,'chemical digestion uses enzymes to break the bonds in large molecules to form smaller molecules, e.g. amylase hydrolysing starch to maltose or pepsin breaking proteins into polypeptides.',1,1);
INSERT INTO rubric_criterion VALUES(9402,'bio12a2-dig-7',NULL,0,'It is very long and folded, with villi and microvilli, giving a very large surface area for absorption;',1,1);
INSERT INTO rubric_criterion VALUES(9403,'bio12a2-dig-7',NULL,1,'the epithelium of each villus is only one cell thick, so the diffusion distance into the blood is short;',1,1);
INSERT INTO rubric_criterion VALUES(9404,'bio12a2-dig-7',NULL,2,'each villus has a dense capillary network (and a lacteal for lipids) that carries absorbed nutrients away, keeping a steep concentration gradient.',1,1);
INSERT INTO rubric_criterion VALUES(9405,'bio12a2-dig-8',NULL,0,'Flattened villi greatly reduce the surface area of the small intestine;',1,1);
INSERT INTO rubric_criterion VALUES(9406,'bio12a2-dig-8',NULL,1,'so the rate of absorption of nutrients such as glucose, amino acids, iron and vitamins decreases;',1,1);
INSERT INTO rubric_criterion VALUES(9407,'bio12a2-dig-8',NULL,2,'the person may show malnutrition, weight loss, fatigue or anaemia even though they eat enough (undigested or unabsorbed material may also cause diarrhoea).',1,1);
INSERT INTO rubric_criterion VALUES(9422,'bio12a2-dig-23',NULL,0,'Rhythmic, wave-like contractions of the smooth muscle in the wall of the alimentary canal that push food along the gut. [1]',1,1);
INSERT INTO rubric_criterion VALUES(9423,'bio12a2-dig-24',NULL,0,'Pancreatic lipase, trypsin and other pancreatic enzymes cannot reach the duodenum, so lipids and proteins are not hydrolysed into smaller molecules that can be absorbed [1];',1,1);
INSERT INTO rubric_criterion VALUES(9424,'bio12a2-dig-24',NULL,1,'undigested fats and proteins pass into the large intestine, causing malabsorption and possibly fatty faeces [1].',1,1);
INSERT INTO rubric_criterion VALUES(9425,'bio12a2-dig-25',NULL,0,'Contraction of the stomach''s smooth muscle in several directions churns the food and mixes it with gastric juice [1];',1,1);
INSERT INTO rubric_criterion VALUES(9426,'bio12a2-dig-25',NULL,1,'this breaks the food into smaller pieces, increasing the surface area available for enzymes such as pepsin to act on [1].',1,1);
INSERT INTO rubric_criterion VALUES(9427,'bio12a2-dig-26',NULL,0,'Early samples turn blue-black, showing that starch is still present [1];',1,1);
INSERT INTO rubric_criterion VALUES(9428,'bio12a2-dig-26',NULL,1,'later samples stay brown-orange, the colour of iodine alone, showing that no starch remains [1];',1,1);
INSERT INTO rubric_criterion VALUES(9429,'bio12a2-dig-26',NULL,2,'amylase has hydrolysed the starch into smaller sugars such as maltose, which do not give a blue-black colour with iodine [1].',1,1);
INSERT INTO rubric_criterion VALUES(9430,'bio12a2-dig-27',NULL,0,'The tongue pushes the bolus back into the pharynx and the swallowing reflex begins [1];',1,1);
INSERT INTO rubric_criterion VALUES(9431,'bio12a2-dig-27',NULL,1,'the epiglottis closes over the trachea so the bolus enters the oesophagus [1];',1,1);
INSERT INTO rubric_criterion VALUES(9432,'bio12a2-dig-27',NULL,2,'peristalsis moves the bolus down the oesophagus and the lower oesophageal sphincter relaxes to let it into the stomach [1].',1,1);
INSERT INTO rubric_criterion VALUES(9433,'bio12a2-dig-28',NULL,0,'Stomach: hydrochloric acid activates pepsinogen to pepsin [1];',1,1);
INSERT INTO rubric_criterion VALUES(9434,'bio12a2-dig-28',NULL,1,'pepsin hydrolyses proteins into polypeptides [1];',1,1);
INSERT INTO rubric_criterion VALUES(9435,'bio12a2-dig-28',NULL,2,'small intestine: trypsin from the pancreas hydrolyses polypeptides into smaller peptides [1];',1,1);
INSERT INTO rubric_criterion VALUES(9436,'bio12a2-dig-28',NULL,3,'peptidases on the microvilli hydrolyse these into amino acids, which are absorbed [1].',1,1);
INSERT INTO rubric_criterion VALUES(9437,'bio12a2-dig-29',NULL,0,'Rate = 6.0 g ÷ 4.0 min = 1.5 g min⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(9438,'bio12a2-dig-29',NULL,1,'increase the concentration of amylase in the mixture [1].',1,1);
INSERT INTO rubric_criterion VALUES(9439,'bio12a2-dig-30',NULL,0,'Active trypsin would digest the pancreas''s own tissue, causing self-digestion [1];',1,1);
INSERT INTO rubric_criterion VALUES(9440,'bio12a2-dig-30',NULL,1,'trypsinogen is converted to active trypsin only in the duodenum, by the enzyme enterokinase, so proteins are digested in the correct place [1].',1,1);
INSERT INTO rubric_criterion VALUES(9447,'bio12a2-endex-6',NULL,0,'Filtration: blood pressure forces water and small solutes (glucose, salts, urea) out of the glomerulus into the Bowman''s capsule;',1,1);
INSERT INTO rubric_criterion VALUES(9448,'bio12a2-endex-6',NULL,1,'reabsorption: useful substances such as glucose, amino acids, many ions and much of the water move from the tubule back into the blood;',1,1);
INSERT INTO rubric_criterion VALUES(9449,'bio12a2-endex-6',NULL,2,'secretion: extra wastes or ions such as H⁺, K⁺ and some drugs are actively moved from the blood into the tubule.',1,1);
INSERT INTO rubric_criterion VALUES(9450,'bio12a2-endex-7',NULL,0,'A hormone can only act on cells that have receptors complementary in shape to that hormone;',1,1);
INSERT INTO rubric_criterion VALUES(9451,'bio12a2-endex-7',NULL,1,'only these target cells bind the hormone and start a response, while other cells lack the receptor and are not affected.',1,1);
INSERT INTO rubric_criterion VALUES(9452,'bio12a2-endex-8',NULL,0,'The anterior pituitary secretes tropic hormones such as TSH, ACTH, FSH and LH; these stimulate other endocrine glands (thyroid, adrenal cortex, gonads) to release their own hormones, so it controls many glands;',1,1);
INSERT INTO rubric_criterion VALUES(9453,'bio12a2-endex-8',NULL,1,'however, the pituitary is itself controlled by releasing hormones from the hypothalamus (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(9454,'bio12a2-endex-8',NULL,2,'TRH), which links the nervous system to the endocrine system.',1,1);
INSERT INTO rubric_criterion VALUES(9469,'bio12a2-endex-23',NULL,0,'The posterior pituitary stores and releases ADH and oxytocin, which are made in the hypothalamus [1];',1,1);
INSERT INTO rubric_criterion VALUES(9470,'bio12a2-endex-23',NULL,1,'the anterior pituitary makes and secretes its own tropic hormones, whose release is controlled by releasing hormones from the hypothalamus [1].',1,1);
INSERT INTO rubric_criterion VALUES(9471,'bio12a2-endex-24',NULL,0,'Falling thyroxine removes inhibition of the hypothalamus, which releases TRH [1];',1,1);
INSERT INTO rubric_criterion VALUES(9472,'bio12a2-endex-24',NULL,1,'TRH stimulates the anterior pituitary to secrete TSH [1];',1,1);
INSERT INTO rubric_criterion VALUES(9473,'bio12a2-endex-24',NULL,2,'TSH stimulates the thyroid to secrete more thyroxine, which returns to normal and then inhibits TRH and TSH release [1].',1,1);
INSERT INTO rubric_criterion VALUES(9474,'bio12a2-endex-25',NULL,0,'Insulin is a protein, so it would be digested by enzymes in the stomach and small intestine and lose its function [1];',1,1);
INSERT INTO rubric_criterion VALUES(9475,'bio12a2-endex-25',NULL,1,'injection delivers intact insulin directly into the blood [1].',1,1);
INSERT INTO rubric_criterion VALUES(9476,'bio12a2-endex-26',NULL,0,'Lungs remove carbon dioxide (and water vapour) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9477,'bio12a2-endex-26',NULL,1,'skin removes water, salts and urea in sweat [1].',1,1);
INSERT INTO rubric_criterion VALUES(9478,'bio12a2-endex-27',NULL,0,'Urea is normally filtered at the glomerulus and removed from the body in urine [1];',1,1);
INSERT INTO rubric_criterion VALUES(9479,'bio12a2-endex-27',NULL,1,'when kidney function fails, urea is not filtered out or excreted, so it builds up in the blood [1].',1,1);
INSERT INTO rubric_criterion VALUES(9480,'bio12a2-endex-28',NULL,0,'Glycogenesis [1]',1,1);
INSERT INTO rubric_criterion VALUES(9481,'bio12a2-endex-29',NULL,0,'Drinking a large volume lowers the solute concentration of the blood [1];',1,1);
INSERT INTO rubric_criterion VALUES(9482,'bio12a2-endex-29',NULL,1,'less ADH is released from the posterior pituitary [1];',1,1);
INSERT INTO rubric_criterion VALUES(9483,'bio12a2-endex-29',NULL,2,'the collecting ducts become less permeable to water, so less water is reabsorbed and dilute urine is produced [1].',1,1);
INSERT INTO rubric_criterion VALUES(9484,'bio12a2-endex-30',NULL,0,'Alpha cells of the islets of Langerhans respond to the fall by secreting glucagon into the blood [1];',1,1);
INSERT INTO rubric_criterion VALUES(9485,'bio12a2-endex-30',NULL,1,'glucagon binds to receptors on liver cells and stimulates the breakdown of glycogen (glycogenolysis) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9486,'bio12a2-endex-30',NULL,2,'glucose is released into the blood, raising blood glucose towards normal [1];',1,1);
INSERT INTO rubric_criterion VALUES(9487,'bio12a2-endex-30',NULL,3,'the rising glucose reduces glucagon secretion, which is negative feedback [1].',1,1);
INSERT INTO rubric_criterion VALUES(9488,'bio12a2-endex-31',NULL,0,'Microvilli on the cell surface increase surface area for reabsorption of glucose, amino acids and ions [1];',1,1);
INSERT INTO rubric_criterion VALUES(9489,'bio12a2-endex-31',NULL,1,'many mitochondria supply the ATP needed for active transport [1].',1,1);
INSERT INTO rubric_criterion VALUES(9496,'bio12a2-srm-6',NULL,0,'In negative feedback, the response reduces or reverses the original stimulus, returning the variable towards its set point and maintaining homeostasis; in positive feedback, the response increases or amplifies the original stimulus, moving the variable further from its starting value until an end point is reached (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(9497,'bio12a2-srm-6',NULL,1,'childbirth, blood clotting).',1,1);
INSERT INTO rubric_criterion VALUES(9498,'bio12a2-srm-7',NULL,0,'Stimulus: high temperature of the pan on the skin; receptor: thermoreceptors/pain receptors in the skin of the hand; modulator: the spinal cord (a reflex arc through interneurons);',1,1);
INSERT INTO rubric_criterion VALUES(9499,'bio12a2-srm-7',NULL,1,'effector: skeletal muscles of the arm (e.g. biceps);',1,1);
INSERT INTO rubric_criterion VALUES(9500,'bio12a2-srm-7',NULL,2,'response: muscle contraction that moves the hand away from the pan. (3 marks for all five correct, 2 for four, 1 for two or three.)',1,1);
INSERT INTO rubric_criterion VALUES(9501,'bio12a2-srm-8',NULL,0,'Cell metabolism depends on enzymes, which have an optimum temperature and pH;',1,1);
INSERT INTO rubric_criterion VALUES(9502,'bio12a2-srm-8',NULL,1,'large changes alter the shape of the active site or denature the enzyme (or slow reactions a lot if too cold), so metabolic reactions could not continue at the rates cells need.',1,1);
INSERT INTO rubric_criterion VALUES(9516,'bio12a2-srm-22',NULL,0,'A change in the internal or external environment that is detected by a receptor. [1]',1,1);
INSERT INTO rubric_criterion VALUES(9517,'bio12a2-srm-23',NULL,0,'The modulator (control centre) receives information from the receptor and coordinates the response by signalling the effector. [1]',1,1);
INSERT INTO rubric_criterion VALUES(9518,'bio12a2-srm-24',NULL,0,'The narrow band of values, either side of the set point, within which a homeostatic variable is kept. [1]',1,1);
INSERT INTO rubric_criterion VALUES(9519,'bio12a2-srm-25',NULL,0,'The stimulus is a rise in body temperature, which is detected and triggers sweating. [1] Evaporation of sweat cools the body, reversing the original rise and returning temperature towards the set point.',1,1);
INSERT INTO rubric_criterion VALUES(9520,'bio12a2-srm-25',NULL,1,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(9521,'bio12a2-srm-26',NULL,0,'Stimulus: a rise in blood carbon dioxide concentration (fall in pH), detected by chemoreceptors. [1] Response: increased rate and depth of breathing, produced by the diaphragm and intercostal muscles, expels carbon dioxide and returns blood pH towards its set point.',1,1);
INSERT INTO rubric_criterion VALUES(9522,'bio12a2-srm-26',NULL,1,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(9523,'bio12a2-srm-27',NULL,0,'The modulator determines whether the variable has deviated from the set point. [1] This allows an appropriately sized and directed response to be sent to the effector to reverse the change.',1,1);
INSERT INTO rubric_criterion VALUES(9524,'bio12a2-srm-27',NULL,1,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(9525,'bio12a2-srm-28',NULL,0,'The response must reverse the stimulus quickly and strongly enough to counteract it. [1] If it is too slow or too weak, the variable keeps changing and can move outside the tolerance range, which may damage cells or disrupt function.',1,1);
INSERT INTO rubric_criterion VALUES(9526,'bio12a2-srm-28',NULL,1,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(9527,'bio12a2-srm-29',NULL,0,'Receptor: osmoreceptors that detect the increased solute concentration of the blood. [1] Modulator: the hypothalamus, which signals the posterior pituitary to release ADH into the blood.',1,1);
INSERT INTO rubric_criterion VALUES(9528,'bio12a2-srm-29',NULL,1,'[1] Effector: the kidney collecting ducts, which reabsorb more water, diluting the blood and reversing the change.',1,1);
INSERT INTO rubric_criterion VALUES(9529,'bio12a2-srm-29',NULL,2,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(9536,'bio12a2-thermo-6',NULL,0,'The hypothalamus releases TRH, which stimulates the anterior pituitary to release TSH;',1,1);
INSERT INTO rubric_criterion VALUES(9537,'bio12a2-thermo-6',NULL,1,'TSH stimulates the thyroid to secrete thyroxine, which increases the metabolic (cellular respiration) rate of body cells, releasing more heat.',1,1);
INSERT INTO rubric_criterion VALUES(9538,'bio12a2-thermo-7',NULL,0,'Exercise raises core temperature, which is detected and leads to vasodilation of arterioles supplying the skin;',1,1);
INSERT INTO rubric_criterion VALUES(9539,'bio12a2-thermo-7',NULL,1,'more warm blood flows close to the skin surface, making it look red and increasing heat loss by radiation.',1,1);
INSERT INTO rubric_criterion VALUES(9540,'bio12a2-thermo-8',NULL,0,'Stimulus: fall in skin and core temperature, detected by thermoreceptors in the skin and in the hypothalamus; the hypothalamus acts as modulator and sends nerve impulses to effectors;',1,1);
INSERT INTO rubric_criterion VALUES(9541,'bio12a2-thermo-8',NULL,1,'e.g. skeletal muscles shiver to produce heat, and smooth muscle in skin arterioles contracts (vasoconstriction) to reduce heat loss (also accept piloerection or a behavioural response such as putting on clothing or seeking shelter);',1,1);
INSERT INTO rubric_criterion VALUES(9542,'bio12a2-thermo-8',NULL,2,'this is negative feedback because the responses counteract the fall in temperature.',1,1);
INSERT INTO rubric_criterion VALUES(9555,'bio12a2-thermo-21',NULL,0,'As the lizard''s body temperature falls, enzyme-controlled reactions, including cellular respiration, slow down [1];',1,1);
INSERT INTO rubric_criterion VALUES(9556,'bio12a2-thermo-21',NULL,1,'less energy is released and nerve impulses and muscle contraction slow, so the lizard moves sluggishly [1].',1,1);
INSERT INTO rubric_criterion VALUES(9557,'bio12a2-thermo-22',NULL,0,'High temperature denatures enzymes and other proteins, so their shape and function are lost [1];',1,1);
INSERT INTO rubric_criterion VALUES(9558,'bio12a2-thermo-22',NULL,1,'metabolic reactions, including cellular respiration, cannot proceed normally, damaging cells and organs [1].',1,1);
INSERT INTO rubric_criterion VALUES(9559,'bio12a2-thermo-23',NULL,0,'Fat has a low thermal conductivity, so heat conducts slowly from the warm core through the fat towards the surrounding water [1];',1,1);
INSERT INTO rubric_criterion VALUES(9560,'bio12a2-thermo-23',NULL,1,'fat tissue has relatively few blood vessels, so less blood flows to the outer layer and less heat is carried to the skin surface [1].',1,1);
INSERT INTO rubric_criterion VALUES(9561,'bio12a2-thermo-24',NULL,0,'Surface area = 6 × 2² = 24 cm² [1];',1,1);
INSERT INTO rubric_criterion VALUES(9562,'bio12a2-thermo-24',NULL,1,'volume = 2³ = 8 cm³, so the ratio is 24 : 8 = 3 : 1 (3 cm⁻¹) [1].',1,1);
INSERT INTO rubric_criterion VALUES(9563,'bio12a2-thermo-25',NULL,0,'Water evaporates from the moist surfaces of the tongue and respiratory tract [1];',1,1);
INSERT INTO rubric_criterion VALUES(9564,'bio12a2-thermo-25',NULL,1,'the evaporation removes heat energy from the blood and body, cooling the dog [1].',1,1);
INSERT INTO rubric_criterion VALUES(9565,'bio12a2-thermo-26',NULL,0,'Light-coloured fur or skin reflects solar radiation [1];',1,1);
INSERT INTO rubric_criterion VALUES(9566,'bio12a2-thermo-26',NULL,1,'nocturnal activity avoids the hottest part of the day [1];',1,1);
INSERT INTO rubric_criterion VALUES(9567,'bio12a2-thermo-26',NULL,2,'burrowing into cooler soil or shade reduces heat gained from the environment [1].',1,1);
INSERT INTO rubric_criterion VALUES(9574,'bio12a2-bgr-6',NULL,0,'The fall in blood glucose is detected by alpha cells (and beta cells) in the islets of Langerhans;',1,1);
INSERT INTO rubric_criterion VALUES(9575,'bio12a2-bgr-6',NULL,1,'alpha cells secrete more glucagon and beta cells secrete less insulin;',1,1);
INSERT INTO rubric_criterion VALUES(9576,'bio12a2-bgr-6',NULL,2,'glucagon causes liver cells to break glycogen down into glucose (glycogenolysis), which is released into the blood, so blood glucose rises back towards the set point and the stimulus is removed.',1,1);
INSERT INTO rubric_criterion VALUES(9577,'bio12a2-bgr-7',NULL,0,'When blood glucose is high, insulin causes liver cells to take up glucose and store it as glycogen (glycogenesis);',1,1);
INSERT INTO rubric_criterion VALUES(9578,'bio12a2-bgr-7',NULL,1,'when blood glucose is low, glucagon causes liver cells to break glycogen down and release glucose into the blood (glycogenolysis), so the liver acts as a glucose store that buffers changes.',1,1);
INSERT INTO rubric_criterion VALUES(9579,'bio12a2-bgr-8',NULL,0,'Adrenaline stimulates the breakdown of glycogen in the liver (and muscles), releasing glucose;',1,1);
INSERT INTO rubric_criterion VALUES(9580,'bio12a2-bgr-8',NULL,1,'the extra glucose supplies muscle and brain cells with more fuel for cellular respiration, giving more ATP for a fight-or-flight response.',1,1);
INSERT INTO rubric_criterion VALUES(9594,'bio12a2-bgr-22',NULL,0,'Glycogenesis is the conversion of glucose into glycogen for storage [1];',1,1);
INSERT INTO rubric_criterion VALUES(9595,'bio12a2-bgr-22',NULL,1,'glycogenolysis is the breakdown of glycogen into glucose [1].',1,1);
INSERT INTO rubric_criterion VALUES(9596,'bio12a2-bgr-23',NULL,0,'Contracting muscle cells take up glucose from the blood, lowering blood glucose [1];',1,1);
INSERT INTO rubric_criterion VALUES(9597,'bio12a2-bgr-23',NULL,1,'this improves the response of body cells to insulin and reduces the amount of insulin needed [1].',1,1);
INSERT INTO rubric_criterion VALUES(9598,'bio12a2-bgr-24',NULL,0,'Increase = 0.40 × 5.5 = 2.2 mmol L⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(9599,'bio12a2-bgr-24',NULL,1,'new concentration = 5.5 + 2.2 = 7.7 mmol L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(9600,'bio12a2-bgr-25',NULL,0,'Without insulin, body cells cannot take up glucose, so they break down stored fats and proteins for energy [1];',1,1);
INSERT INTO rubric_criterion VALUES(9601,'bio12a2-bgr-25',NULL,1,'blood glucose rises above the renal threshold, so glucose is excreted in the urine [1];',1,1);
INSERT INTO rubric_criterion VALUES(9602,'bio12a2-bgr-25',NULL,2,'the glucose draws water into the urine by osmosis, increasing urine output [1].',1,1);
INSERT INTO rubric_criterion VALUES(9603,'bio12a2-bgr-26',NULL,0,'Insulin is secreted by beta cells when blood glucose is high [1];',1,1);
INSERT INTO rubric_criterion VALUES(9604,'bio12a2-bgr-26',NULL,1,'glucagon is secreted by alpha cells when blood glucose is low [1];',1,1);
INSERT INTO rubric_criterion VALUES(9605,'bio12a2-bgr-26',NULL,2,'insulin promotes glucose uptake by cells and the conversion of glucose into glycogen [1];',1,1);
INSERT INTO rubric_criterion VALUES(9606,'bio12a2-bgr-26',NULL,3,'glucagon promotes the breakdown of liver glycogen into glucose, which is released into the blood [1].',1,1);
INSERT INTO rubric_criterion VALUES(9607,'bio12a2-bgr-27',NULL,0,'The islets of Langerhans secrete hormones directly into the blood, which is an endocrine function [1];',1,1);
INSERT INTO rubric_criterion VALUES(9608,'bio12a2-bgr-27',NULL,1,'acinar cells secrete digestive enzymes into ducts that carry them to the small intestine, which is an exocrine function [1].',1,1);
INSERT INTO rubric_criterion VALUES(9609,'bio12a2-bgr-28',NULL,0,'Cells, especially brain cells, need a constant supply of glucose for cellular respiration [1].',1,1);
INSERT INTO rubric_criterion VALUES(9610,'bio12a2-bgr-29',NULL,0,'Blood glucose can fall well below the set point [1];',1,1);
INSERT INTO rubric_criterion VALUES(9611,'bio12a2-bgr-29',NULL,1,'the brain depends on glucose for cellular respiration, so it is deprived of fuel, causing confusion and, in severe cases, unconsciousness [1];',1,1);
INSERT INTO rubric_criterion VALUES(9612,'bio12a2-bgr-29',NULL,2,'the body''s glucagon and adrenaline responses may not restore blood glucose quickly enough to prevent this [1].',1,1);
INSERT INTO rubric_criterion VALUES(9613,'bio12a2-bgr-30',NULL,0,'Glycogen is a large, insoluble molecule, so storing glucose as glycogen does not raise the solute concentration of the cytoplasm and does not draw water into the cell by osmosis [1];',1,1);
INSERT INTO rubric_criterion VALUES(9614,'bio12a2-bgr-30',NULL,1,'glycogen can be quickly broken down into glucose when the cell needs it [1].',1,1);
INSERT INTO rubric_criterion VALUES(9621,'bio12a2-wb-6',NULL,0,'Water loss in sweat raises the solute concentration of the blood, which is detected by osmoreceptors in the hypothalamus;',1,1);
INSERT INTO rubric_criterion VALUES(9622,'bio12a2-wb-6',NULL,1,'the hypothalamus causes more ADH to be released from the posterior pituitary (and thirst is stimulated);',1,1);
INSERT INTO rubric_criterion VALUES(9623,'bio12a2-wb-6',NULL,2,'ADH increases the permeability of the distal tubules and collecting ducts to water, so more water is reabsorbed into the blood and a small volume of concentrated urine is produced.',1,1);
INSERT INTO rubric_criterion VALUES(9624,'bio12a2-wb-7',NULL,0,'Very long loops of Henle (relative to kidney size); these build a very high solute concentration in the medulla, so a large amount of water moves by osmosis out of the collecting ducts and is reabsorbed, leaving a very small volume of highly concentrated urine.',1,1);
INSERT INTO rubric_criterion VALUES(9625,'bio12a2-wb-7',NULL,1,'(Also accept high ADH levels or highly permeable collecting ducts with matching explanation.)',1,1);
INSERT INTO rubric_criterion VALUES(9626,'bio12a2-wb-8',NULL,0,'Water lost by sweating raises blood solute concentration, so more ADH is released and more water is reabsorbed from the collecting ducts;',1,1);
INSERT INTO rubric_criterion VALUES(9627,'bio12a2-wb-8',NULL,1,'the same amount of urea and pigment is dissolved in a smaller volume of water, so the urine is more concentrated and darker.',1,1);
INSERT INTO rubric_criterion VALUES(9640,'bio12a2-wb-21',NULL,0,'Proximal convoluted tubule [1].',1,1);
INSERT INTO rubric_criterion VALUES(9641,'bio12a2-wb-22',NULL,0,'Blood pressure forces water and small solutes (such as glucose, urea and ions) out of the glomerular capillaries and into Bowman''s capsule [1];',1,1);
INSERT INTO rubric_criterion VALUES(9642,'bio12a2-wb-22',NULL,1,'blood cells and large molecules are too big to pass through the filtration membrane, so they remain in the blood [1].',1,1);
INSERT INTO rubric_criterion VALUES(9643,'bio12a2-wb-23',NULL,0,'The descending limb is permeable to water [1];',1,1);
INSERT INTO rubric_criterion VALUES(9644,'bio12a2-wb-23',NULL,1,'water moves out of the filtrate by osmosis into the more concentrated medulla, so the filtrate becomes more concentrated as it descends [1].',1,1);
INSERT INTO rubric_criterion VALUES(9645,'bio12a2-wb-24',NULL,0,'Blood flows past a semi-permeable (dialysis) membrane [1];',1,1);
INSERT INTO rubric_criterion VALUES(9646,'bio12a2-wb-24',NULL,1,'urea diffuses across the membrane from the blood, where its concentration is higher, into the dialysis fluid, where it is lower [1];',1,1);
INSERT INTO rubric_criterion VALUES(9647,'bio12a2-wb-24',NULL,2,'small waste molecules pass through the membrane while blood cells and large proteins are retained in the blood [1].',1,1);
INSERT INTO rubric_criterion VALUES(9648,'bio12a2-wb-25',NULL,0,'Sweat from the skin [1];',1,1);
INSERT INTO rubric_criterion VALUES(9649,'bio12a2-wb-25',NULL,1,'water vapour in exhaled air [1] (water lost in faeces is also accepted).',1,1);
INSERT INTO rubric_criterion VALUES(9650,'bio12a2-wb-26',NULL,0,'The total concentration of dissolved solute particles in a solution, measured in osmol L⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(9651,'bio12a2-wb-27',NULL,0,'Osmoreceptors in the hypothalamus detect the rise in blood osmolarity and stimulate the sensation of thirst [1];',1,1);
INSERT INTO rubric_criterion VALUES(9652,'bio12a2-wb-27',NULL,1,'the person drinks water, which dilutes the blood back towards normal [1].',1,1);
INSERT INTO rubric_criterion VALUES(9659,'bio12a2-mal-6',NULL,0,'Type 1 is an autoimmune disease in which beta cells are destroyed, so little or no insulin is made;',1,1);
INSERT INTO rubric_criterion VALUES(9660,'bio12a2-mal-6',NULL,1,'type 2 involves insulin resistance (cells respond poorly to insulin), sometimes with reduced insulin output later, and is linked to genetics, obesity and inactivity;',1,1);
INSERT INTO rubric_criterion VALUES(9661,'bio12a2-mal-6',NULL,2,'type 1 is managed with insulin injections or a pump, while type 2 is often first managed with diet, exercise and weight loss, then oral medication and sometimes insulin.',1,1);
INSERT INTO rubric_criterion VALUES(9662,'bio12a2-mal-7',NULL,0,'Without ADH, the distal tubules and collecting ducts stay poorly permeable to water, so little water is reabsorbed;',1,1);
INSERT INTO rubric_criterion VALUES(9663,'bio12a2-mal-7',NULL,1,'the person produces a very large volume of dilute urine;',1,1);
INSERT INTO rubric_criterion VALUES(9664,'bio12a2-mal-7',NULL,2,'as a result they lose water and become dehydrated, and blood solute concentration rises, which is detected by osmoreceptors, so they feel extreme thirst and drink large amounts.',1,1);
INSERT INTO rubric_criterion VALUES(9665,'bio12a2-mal-8',NULL,0,'Thyroxine normally inhibits the release of TRH from the hypothalamus and TSH from the anterior pituitary (negative feedback);',1,1);
INSERT INTO rubric_criterion VALUES(9666,'bio12a2-mal-8',NULL,1,'with low thyroxine, this inhibition is removed, so TSH levels stay high;',1,1);
INSERT INTO rubric_criterion VALUES(9667,'bio12a2-mal-8',NULL,2,'continuous TSH stimulation makes thyroid cells grow and divide, so the gland enlarges, yet it still cannot make thyroxine without iodine.',1,1);
INSERT INTO rubric_criterion VALUES(9678,'bio12a2-mal-19',NULL,0,'The pump delivers a small, continuous (basal) dose of insulin over 24 hours, similar to the steady insulin release of a healthy pancreas between meals [1];',1,1);
INSERT INTO rubric_criterion VALUES(9679,'bio12a2-mal-19',NULL,1,'it can also deliver extra bolus doses at mealtimes, so insulin is available as glucose enters the blood after eating [1];',1,1);
INSERT INTO rubric_criterion VALUES(9680,'bio12a2-mal-19',NULL,2,'the dose can be adjusted for activity and food, so blood glucose stays closer to the normal range and hyperglycaemia or hypoglycaemia is less likely [1].',1,1);
INSERT INTO rubric_criterion VALUES(9681,'bio12a2-mal-20',NULL,0,'Beta cells in the islets of Langerhans detect the rise and secrete insulin into the blood [1];',1,1);
INSERT INTO rubric_criterion VALUES(9682,'bio12a2-mal-20',NULL,1,'insulin causes liver and muscle cells to take up glucose and store it as glycogen, so blood glucose falls back towards normal [1];',1,1);
INSERT INTO rubric_criterion VALUES(9683,'bio12a2-mal-20',NULL,2,'in type 1 diabetes the beta cells have been destroyed by the immune system, so no insulin is released and glucose stays high in the blood [1].',1,1);
INSERT INTO rubric_criterion VALUES(9684,'bio12a2-mal-21',NULL,0,'The failed kidneys cannot excrete urea and other nitrogenous wastes, so these build up in the blood [1];',1,1);
INSERT INTO rubric_criterion VALUES(9685,'bio12a2-mal-21',NULL,1,'excess water and ions such as potassium also accumulate, which can cause swelling, high blood pressure and heart problems [1];',1,1);
INSERT INTO rubric_criterion VALUES(9686,'bio12a2-mal-21',NULL,2,'in haemodialysis, blood flows past a semi-permeable membrane and wastes diffuse into the dialysis fluid down their concentration gradient [1];',1,1);
INSERT INTO rubric_criterion VALUES(9687,'bio12a2-mal-21',NULL,3,'the dialysis fluid has suitable ion concentrations so useful ions are not lost, and excess water can be removed by applying pressure to the blood side [1].',1,1);
INSERT INTO rubric_criterion VALUES(9688,'bio12a2-mal-22',NULL,0,'Desmopressin binds to receptors on the cells of the distal tubule and collecting duct, increasing their permeability to water [1];',1,1);
INSERT INTO rubric_criterion VALUES(9689,'bio12a2-mal-22',NULL,1,'more water is reabsorbed by osmosis, so less urine is produced and it is more concentrated [1].',1,1);
INSERT INTO rubric_criterion VALUES(9690,'bio12a2-mal-23',NULL,0,'Sweating and the evaporation of sweat are the main cooling responses, so with sweating stopped much less heat is lost from the body [1];',1,1);
INSERT INTO rubric_criterion VALUES(9691,'bio12a2-mal-23',NULL,1,'heat is still produced by metabolism and gained from the environment, so body temperature keeps rising [1];',1,1);
INSERT INTO rubric_criterion VALUES(9692,'bio12a2-mal-23',NULL,2,'at this temperature enzymes and proteins begin to denature, disrupting metabolic reactions and damaging cells, especially in the brain [1];',1,1);
INSERT INTO rubric_criterion VALUES(9693,'bio12a2-mal-23',NULL,3,'the negative feedback responses have failed to return the body to its set point, so the condition becomes life-threatening without rapid cooling [1].',1,1);
INSERT INTO rubric_criterion VALUES(9694,'bio12a2-mal-24',NULL,0,'At 37 °C with a set point of 39 °C, the body detects its temperature as too low, so it shivers and constricts skin blood vessels to produce and conserve heat [1];',1,1);
INSERT INTO rubric_criterion VALUES(9695,'bio12a2-mal-24',NULL,1,'with the set point back at 37 °C and body temperature at 38.5 °C, the temperature is detected as too high, so the body sweats and dilates skin arterioles to lose heat [1];',1,1);
INSERT INTO rubric_criterion VALUES(9696,'bio12a2-mal-24',NULL,2,'in both cases the responses oppose the change and stop once body temperature returns to the set point [1].',1,1);
INSERT INTO rubric_criterion VALUES(9697,'bio12a2-mal-25',NULL,0,'Target cells respond poorly to insulin, so blood glucose stays high and the beta cells are stimulated to secrete more insulin [1];',1,1);
INSERT INTO rubric_criterion VALUES(9698,'bio12a2-mal-25',NULL,1,'over years the beta cells are overworked and can be damaged, so their insulin output falls [1];',1,1);
INSERT INTO rubric_criterion VALUES(9699,'bio12a2-mal-25',NULL,2,'with less insulin and continuing resistance, glucose uptake and storage decline, so blood glucose rises further and is harder to control [1].',1,1);
INSERT INTO rubric_criterion VALUES(9700,'bio12a2-mal-26',NULL,0,'The brain relies almost entirely on glucose as its energy source for cellular respiration [1];',1,1);
INSERT INTO rubric_criterion VALUES(9701,'bio12a2-mal-26',NULL,1,'low blood glucose reduces the glucose supplied to brain cells, so less ATP is produced and neurons cannot function normally, causing confusion [1];',1,1);
INSERT INTO rubric_criterion VALUES(9702,'bio12a2-mal-26',NULL,2,'the body responds by releasing adrenaline and glucagon, and the adrenaline causes shakiness [1].',1,1);
INSERT INTO rubric_criterion VALUES(9709,'bio12a2-gen-6',NULL,0,'Genome: the complete set of DNA (genetic material) of an organism;',1,1);
INSERT INTO rubric_criterion VALUES(9710,'bio12a2-gen-6',NULL,1,'gene: a section of DNA at a particular locus that carries the code for a functional product such as a protein;',1,1);
INSERT INTO rubric_criterion VALUES(9711,'bio12a2-gen-6',NULL,2,'allele: one of the different forms (variants) of a gene, with a slightly different base sequence, found at the same locus.',1,1);
INSERT INTO rubric_criterion VALUES(9712,'bio12a2-gen-7',NULL,0,'Prokaryotes usually have a single circular chromosome found free in the cytosol (nucleoid region), while eukaryotes have several linear chromosomes inside a nucleus;',1,1);
INSERT INTO rubric_criterion VALUES(9713,'bio12a2-gen-7',NULL,1,'prokaryotes often also carry small circular plasmids, whereas eukaryotes have DNA in mitochondria (and chloroplasts) and much more non-coding DNA wound around histone proteins.',1,1);
INSERT INTO rubric_criterion VALUES(9714,'bio12a2-gen-8',NULL,0,'The alleles have different base sequences, so they may code for a different amino acid sequence;',1,1);
INSERT INTO rubric_criterion VALUES(9715,'bio12a2-gen-8',NULL,1,'this changes the shape and function of the protein (or stops it being made or working), which changes the observable characteristic.',1,1);
INSERT INTO rubric_criterion VALUES(9728,'bio12a2-gen-21',NULL,0,'DNA (deoxyribonucleic acid) [1]',1,1);
INSERT INTO rubric_criterion VALUES(9729,'bio12a2-gen-22',NULL,0,'A variation in the DNA sequence in which a single base (nucleotide) differs at a specific position [1], and the variant is common enough to be found in a substantial proportion of a population [1].',2,1);
INSERT INTO rubric_criterion VALUES(9730,'bio12a2-gen-23',NULL,0,'Diploid genome = 2 × haploid genome [1];',1,1);
INSERT INTO rubric_criterion VALUES(9731,'bio12a2-gen-23',NULL,1,'2 × 3 × 10⁹ = 6 × 10⁹ base pairs [1].',1,1);
INSERT INTO rubric_criterion VALUES(9732,'bio12a2-gen-24',NULL,0,'Comparing sequences can identify genes or alleles linked to a trait or disease [1];',1,1);
INSERT INTO rubric_criterion VALUES(9733,'bio12a2-gen-24',NULL,1,'this can support diagnostic tests, treatments or the study of evolutionary relationships [1].',1,1);
INSERT INTO rubric_criterion VALUES(9734,'bio12a2-gen-25',NULL,0,'Dominance describes how an allele''s effect shows in a heterozygote, not how often the allele occurs [1];',1,1);
INSERT INTO rubric_criterion VALUES(9735,'bio12a2-gen-25',NULL,1,'allele frequency depends on factors such as mutation, selection and chance in a population [1].',1,1);
INSERT INTO rubric_criterion VALUES(9736,'bio12a2-gen-26',NULL,0,'Copies of allele A = 4 × 2 + 3 × 1 = 11 [1];',1,1);
INSERT INTO rubric_criterion VALUES(9737,'bio12a2-gen-26',NULL,1,'total alleles = 10 × 2 = 20 [1];',1,1);
INSERT INTO rubric_criterion VALUES(9738,'bio12a2-gen-26',NULL,2,'frequency of A = 11 ÷ 20 = 0.55 (55%) [1].',1,1);
INSERT INTO rubric_criterion VALUES(9739,'bio12a2-gen-27',NULL,0,'Having two identical alleles of a gene at a locus (for example AA or aa) [1].',1,1);
INSERT INTO rubric_criterion VALUES(9740,'bio12a2-gen-28',NULL,0,'Both cells developed by mitosis from the same fertilised egg, so each carries an identical copy of the DNA [1];',1,1);
INSERT INTO rubric_criterion VALUES(9741,'bio12a2-gen-28',NULL,1,'the cells express different sets of genes, producing different proteins that give each cell its structure and function [1].',1,1);
INSERT INTO rubric_criterion VALUES(9742,'bio12a2-gen-29',NULL,0,'Having a single set of chromosomes, so one allele of each gene in a cell [1].',1,1);
INSERT INTO rubric_criterion VALUES(9749,'bio12a2-chr-6',NULL,0,'At metaphase the chromosomes are fully condensed (supercoiled), so they are at their shortest and thickest and easiest to see and count;',1,1);
INSERT INTO rubric_criterion VALUES(9750,'bio12a2-chr-6',NULL,1,'each chromosome is made of two sister chromatids joined at the centromere, so their size, shape, centromere position and banding pattern can be compared to pair them.',1,1);
INSERT INTO rubric_criterion VALUES(9751,'bio12a2-chr-7',NULL,0,'Diploid number 2n = 78;',1,1);
INSERT INTO rubric_criterion VALUES(9752,'bio12a2-chr-7',NULL,1,'haploid number n = 39;',1,1);
INSERT INTO rubric_criterion VALUES(9753,'bio12a2-chr-7',NULL,2,'a sperm cell has 38 autosomes, because a gamete contains one chromosome from each of the 39 pairs, and one of these is a sex chromosome (X or Y), leaving 38 autosomes.',1,1);
INSERT INTO rubric_criterion VALUES(9754,'bio12a2-chr-8',NULL,0,'Nondisjunction occurred during meiosis in one parent;',1,1);
INSERT INTO rubric_criterion VALUES(9755,'bio12a2-chr-8',NULL,1,'the sex chromosomes (homologues in meiosis I, or sister chromatids in meiosis II) failed to separate, producing a gamete with no sex chromosome;',1,1);
INSERT INTO rubric_criterion VALUES(9756,'bio12a2-chr-8',NULL,2,'this gamete was fertilised by a normal gamete carrying one X, giving a zygote with 45 chromosomes and a single X.',1,1);
INSERT INTO rubric_criterion VALUES(9769,'bio12a2-chr-21',NULL,0,'47,XXX [1]',1,1);
INSERT INTO rubric_criterion VALUES(9770,'bio12a2-chr-22',NULL,0,'A karyotype is an image of the chromosomes from one cell, showing their number and structure [1];',1,1);
INSERT INTO rubric_criterion VALUES(9771,'bio12a2-chr-22',NULL,1,'a pedigree is a family diagram that traces the inheritance of a trait across generations [1].',1,1);
INSERT INTO rubric_criterion VALUES(9772,'bio12a2-chr-23',NULL,0,'The X and Y differ in size and carry different genes, so most of their length does not pair [1];',1,1);
INSERT INTO rubric_criterion VALUES(9773,'bio12a2-chr-23',NULL,1,'they share only a small pairing region at their tips, where they can pair and cross over in meiosis I [1].',1,1);
INSERT INTO rubric_criterion VALUES(9774,'bio12a2-chr-24',NULL,0,'Crossing over: non-sister chromatids of a homologous pair exchange segments in prophase I [1], so the chromatids carry new combinations of alleles [1];',1,1);
INSERT INTO rubric_criterion VALUES(9775,'bio12a2-chr-24',NULL,1,'independent assortment: during metaphase I each homologous pair lines up and orients at random [1], so each gamete receives a random mix of maternal and paternal chromosomes [1].',3,1);
INSERT INTO rubric_criterion VALUES(9776,'bio12a2-chr-25',NULL,0,'Diploid number 2n = 24 [1];',1,1);
INSERT INTO rubric_criterion VALUES(9777,'bio12a2-chr-25',NULL,1,'a triploid cell has 3n = 36 chromosomes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9778,'bio12a2-chr-25',NULL,2,'triploidy adds a complete extra haploid set so every chromosome appears three times, whereas trisomy involves an extra copy of only one chromosome [1].',1,1);
INSERT INTO rubric_criterion VALUES(9779,'bio12a2-chr-26',NULL,0,'Klinefelter (male): 47 chromosomes [1], sex chromosomes XXY [1];',1,1);
INSERT INTO rubric_criterion VALUES(9780,'bio12a2-chr-26',NULL,1,'Turner (female): 45 chromosomes [1], a single X chromosome with no second sex chromosome (45,X) [1].',3,1);
INSERT INTO rubric_criterion VALUES(9781,'bio12a2-chr-27',NULL,0,'Monosomy removes one copy of every gene on the chromosome, halving the expression of those genes and usually disrupting development so the embryo does not survive [1];',1,1);
INSERT INTO rubric_criterion VALUES(9782,'bio12a2-chr-27',NULL,1,'trisomy 21 adds one copy of one of the smallest autosomes, which has relatively few genes, so the extra dose is tolerated and the embryo can develop to birth [1];',1,1);
INSERT INTO rubric_criterion VALUES(9783,'bio12a2-chr-27',NULL,2,'the extra dose still causes Down syndrome features, such as intellectual disability [1].',1,1);
INSERT INTO rubric_criterion VALUES(9784,'bio12a2-chr-28',NULL,0,'Giemsa stain [1]',1,1);
INSERT INTO rubric_criterion VALUES(9785,'bio12a2-chr-29',NULL,0,'Female (XX) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9786,'bio12a2-chr-29',NULL,1,'46 chromosomes, so there is no change in the total number [1];',1,1);
INSERT INTO rubric_criterion VALUES(9787,'bio12a2-chr-29',NULL,2,'a translocation in which segments are exchanged between chromosomes 9 and 22 [1].',1,1);
INSERT INTO rubric_criterion VALUES(9794,'bio12a2-mei-6',NULL,0,'Mitosis involves one division and produces two daughter cells, while meiosis involves two divisions and produces four;',1,1);
INSERT INTO rubric_criterion VALUES(9795,'bio12a2-mei-6',NULL,1,'mitosis keeps the chromosome number the same (diploid to diploid), while meiosis halves it (diploid to haploid);',1,1);
INSERT INTO rubric_criterion VALUES(9796,'bio12a2-mei-6',NULL,2,'mitosis produces genetically identical cells for growth and repair, while meiosis produces genetically different gametes because of crossing over and independent assortment (homologues pair up only in meiosis).',1,1);
INSERT INTO rubric_criterion VALUES(9797,'bio12a2-mei-7',NULL,0,'During prophase I, non-sister chromatids of homologous chromosomes exchange equivalent segments of DNA at chiasmata;',1,1);
INSERT INTO rubric_criterion VALUES(9798,'bio12a2-mei-7',NULL,1,'this creates chromatids with new combinations of maternal and paternal alleles (recombinants), so each gamete gets a unique combination of alleles.',1,1);
INSERT INTO rubric_criterion VALUES(9799,'bio12a2-mei-8',NULL,0,'Crossing over in prophase I swaps segments between non-sister chromatids, making new allele combinations on each chromosome;',1,1);
INSERT INTO rubric_criterion VALUES(9800,'bio12a2-mei-8',NULL,1,'independent assortment of homologous pairs at metaphase I produces many different combinations of maternal and paternal chromosomes in each gamete;',1,1);
INSERT INTO rubric_criterion VALUES(9801,'bio12a2-mei-8',NULL,2,'random fertilisation means any one of the father''s genetically different sperm can fuse with any one of the mother''s genetically different eggs.',1,1);
INSERT INTO rubric_criterion VALUES(9814,'bio12a2-mei-21',NULL,0,'Homologous chromosomes are separated and move into different daughter cells [1];',1,1);
INSERT INTO rubric_criterion VALUES(9815,'bio12a2-mei-21',NULL,1,'each daughter cell therefore has half the chromosome number of the parent cell, so it is haploid [1].',1,1);
INSERT INTO rubric_criterion VALUES(9816,'bio12a2-mei-22',NULL,0,'Crossing over occurs in prophase I and exchanges segments between non-sister chromatids, creating chromosomes with mixed alleles [1];',1,1);
INSERT INTO rubric_criterion VALUES(9817,'bio12a2-mei-22',NULL,1,'independent assortment occurs at metaphase I when each homologous pair is oriented at random, so each gamete receives a random mix of whole maternal and paternal chromosomes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9818,'bio12a2-mei-22',NULL,2,'both occur in the same meiosis, so together they make each gamete genetically different from the others [1].',1,1);
INSERT INTO rubric_criterion VALUES(9819,'bio12a2-mei-23',NULL,0,'Sister chromatids are two copies of the same chromosome, made by DNA replication during S phase [1];',1,1);
INSERT INTO rubric_criterion VALUES(9820,'bio12a2-mei-23',NULL,1,'homologous chromosomes come from different parents, so they may carry different alleles of the same genes [1].',1,1);
INSERT INTO rubric_criterion VALUES(9821,'bio12a2-mei-24',NULL,0,'46 chromosomes in the replicated cell [1];',1,1);
INSERT INTO rubric_criterion VALUES(9822,'bio12a2-mei-24',NULL,1,'92 chromatids, since each chromosome has two chromatids [1];',1,1);
INSERT INTO rubric_criterion VALUES(9823,'bio12a2-mei-24',NULL,2,'23 chromosomes in each gamete, because gametes are haploid [1].',1,1);
INSERT INTO rubric_criterion VALUES(9824,'bio12a2-mei-25',NULL,0,'A mutation is a change in the base sequence of DNA, so it creates new alleles [1];',1,1);
INSERT INTO rubric_criterion VALUES(9825,'bio12a2-mei-25',NULL,1,'crossing over only rearranges existing alleles into new combinations on chromosomes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9826,'bio12a2-mei-25',NULL,2,'mutations are rare and random, whereas crossing over occurs regularly during prophase I of meiosis [1].',1,1);
INSERT INTO rubric_criterion VALUES(9827,'bio12a2-mei-26',NULL,0,'The centromere of each chromosome divides, so the two sister chromatids become separate chromosomes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9828,'bio12a2-mei-26',NULL,1,'spindle fibres attached to the centromeres pull each chromosome to opposite poles of the cell [1].',1,1);
INSERT INTO rubric_criterion VALUES(9829,'bio12a2-mei-27',NULL,0,'In prophase I, homologous chromosomes pair up (synapsis) to form bivalents, and crossing over may occur [1];',1,1);
INSERT INTO rubric_criterion VALUES(9830,'bio12a2-mei-27',NULL,1,'at metaphase I, bivalents line up at the equator with the two homologues of each pair facing opposite poles [1];',1,1);
INSERT INTO rubric_criterion VALUES(9831,'bio12a2-mei-27',NULL,2,'at anaphase I, homologous chromosomes are pulled to opposite poles while sister chromatids remain joined at their centromeres [1].',1,1);
INSERT INTO rubric_criterion VALUES(9832,'bio12a2-mei-28',NULL,0,'Crossing over and independent assortment occur only in meiosis, not in mitosis [1];',1,1);
INSERT INTO rubric_criterion VALUES(9833,'bio12a2-mei-28',NULL,1,'in mitosis homologous chromosomes do not pair and the daughter cells are genetically identical, so no new variation is produced [1].',1,1);
INSERT INTO rubric_criterion VALUES(9834,'bio12a2-mei-29',NULL,0,'n = 6, so independent assortment gives 2⁶ = 64 different gametes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9835,'bio12a2-mei-29',NULL,1,'64 different sperm types can each combine with 64 different egg types [1];',1,1);
INSERT INTO rubric_criterion VALUES(9836,'bio12a2-mei-29',NULL,2,'64 × 64 = 4096 possible zygotes [1].',1,1);
INSERT INTO rubric_criterion VALUES(9843,'bio12a2-gpe-6',NULL,0,'Continuous variation shows a range of values with no distinct categories, usually because the trait is polygenic and affected by environment, e.g. height or skin colour;',1,1);
INSERT INTO rubric_criterion VALUES(9844,'bio12a2-gpe-6',NULL,1,'discontinuous variation falls into a few distinct categories, usually controlled by one or a few genes, e.g. ABO blood group or attached versus free earlobes.',1,1);
INSERT INTO rubric_criterion VALUES(9845,'bio12a2-gpe-7',NULL,0,'The genotype (homozygous recessive) cannot be changed, so the enzyme is still non-functional;',1,1);
INSERT INTO rubric_criterion VALUES(9846,'bio12a2-gpe-7',NULL,1,'the environment (a diet low in phenylalanine) stops phenylalanine building up to harmful levels;',1,1);
INSERT INTO rubric_criterion VALUES(9847,'bio12a2-gpe-7',NULL,2,'so the phenotype depends on the interaction of genotype and environment, and the same genotype can produce a different phenotype under different conditions.',1,1);
INSERT INTO rubric_criterion VALUES(9848,'bio12a2-gpe-8',NULL,0,'Methyl groups can be added to DNA (or histones can be modified), which can switch genes off or reduce their expression without changing the base sequence;',1,1);
INSERT INTO rubric_criterion VALUES(9849,'bio12a2-gpe-8',NULL,1,'the twins experience different environments (diet, smoking, stress), which cause different methylation patterns, so different genes are expressed and their phenotypes diverge.',1,1);
INSERT INTO rubric_criterion VALUES(9863,'bio12a2-gpe-22',NULL,0,'The plants have the same genotype, so genes do not explain the difference [1];',1,1);
INSERT INTO rubric_criterion VALUES(9864,'bio12a2-gpe-22',NULL,1,'sunlight (the environment) acts on this genotype to produce a different phenotype [1].',1,1);
INSERT INTO rubric_criterion VALUES(9865,'bio12a2-gpe-23',NULL,0,'Other genes and environmental factors, such as diet, lifestyle or medical care, interact with the genotype [1];',1,1);
INSERT INTO rubric_criterion VALUES(9866,'bio12a2-gpe-23',NULL,1,'so the same genotype can produce different phenotypes [1].',1,1);
INSERT INTO rubric_criterion VALUES(9867,'bio12a2-gpe-24',NULL,0,'Sunlight (UV exposure) increases melanin production, so the skin darkens [1].',1,1);
INSERT INTO rubric_criterion VALUES(9868,'bio12a2-gpe-25',NULL,0,'Environmental factors such as diet, temperature or light act on the genotype during development [1];',1,1);
INSERT INTO rubric_criterion VALUES(9869,'bio12a2-gpe-25',NULL,1,'the genotype sets a range of possible phenotypes and the environment determines where in that range the organism falls [1].',1,1);
INSERT INTO rubric_criterion VALUES(9870,'bio12a2-gpe-26',NULL,0,'The claim is not valid [1];',1,1);
INSERT INTO rubric_criterion VALUES(9871,'bio12a2-gpe-26',NULL,1,'environmental differences, such as diet, illness or lifestyle, can produce different phenotypes from the same genotype [1];',1,1);
INSERT INTO rubric_criterion VALUES(9872,'bio12a2-gpe-26',NULL,2,'epigenetic changes or mutations that arise after the twins develop can also change gene expression [1].',1,1);
INSERT INTO rubric_criterion VALUES(9873,'bio12a2-gpe-27',NULL,0,'Partly incorrect: environmental factors change the phenotype without altering the DNA sequence in most cases [1];',1,1);
INSERT INTO rubric_criterion VALUES(9874,'bio12a2-gpe-27',NULL,1,'but environmental mutagens such as UV radiation or chemicals can cause mutations that do change the genotype [1].',1,1);
INSERT INTO rubric_criterion VALUES(9881,'bio12a3-mono-6',NULL,0,'(a) Parents Bb (black) and bb (brown); Bb produces B and b gametes, bb produces only b gametes;',1,1);
INSERT INTO rubric_criterion VALUES(9882,'bio12a3-mono-6',NULL,1,'(b) offspring genotypes 1 Bb : 1 bb;',1,1);
INSERT INTO rubric_criterion VALUES(9883,'bio12a3-mono-6',NULL,2,'phenotypes 1 black : 1 brown (50% each).',1,1);
INSERT INTO rubric_criterion VALUES(9884,'bio12a3-mono-7',NULL,0,'Fertilisation is random, so each offspring has an independent 3/4 probability of being round and real counts deviate by chance from the predicted ratio;',1,1);
INSERT INTO rubric_criterion VALUES(9885,'bio12a3-mono-7',NULL,1,'a larger sample (more offspring) or repeating the cross would make the results more reliable and closer to 3 : 1.',1,1);
INSERT INTO rubric_criterion VALUES(9886,'bio12a3-mono-8',NULL,0,'Genotype is the combination of alleles an organism has for a gene (e.g. Tt);',1,1);
INSERT INTO rubric_criterion VALUES(9887,'bio12a3-mono-8',NULL,1,'phenotype is the observable characteristic produced by the genotype interacting with the environment (e.g. tall);',1,1);
INSERT INTO rubric_criterion VALUES(9888,'bio12a3-mono-8',NULL,2,'homozygous means having two identical alleles for a gene (TT or tt); for example a TT plant and a Tt plant are both tall because T is dominant, so the same phenotype can come from different genotypes.',1,1);
INSERT INTO rubric_criterion VALUES(9903,'bio12a3-mono-23',NULL,0,'The homozygous recessive partner contributes only recessive alleles, so each offspring''s phenotype directly reflects the allele passed on by the unknown parent [1];',1,1);
INSERT INTO rubric_criterion VALUES(9904,'bio12a3-mono-23',NULL,1,'crossing with another dominant-phenotype individual can hide a recessive allele, because heterozygotes and homozygous dominant individuals look the same [1].',1,1);
INSERT INTO rubric_criterion VALUES(9905,'bio12a3-mono-24',NULL,0,'1 TT : 2 Tt : 1 tt [1].',1,1);
INSERT INTO rubric_criterion VALUES(9906,'bio12a3-mono-25',NULL,0,'Probability that one child is aa = 1/4 [1];',1,1);
INSERT INTO rubric_criterion VALUES(9907,'bio12a3-mono-25',NULL,1,'both children aa = 1/4 × 1/4 = 1/16 (6.25%) [1].',1,1);
INSERT INTO rubric_criterion VALUES(9908,'bio12a3-mono-26',NULL,0,'(a) rr; produces only r gametes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9909,'bio12a3-mono-26',NULL,1,'(b) RR gives all rough offspring (Rr) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9910,'bio12a3-mono-26',NULL,2,'Rr gives about 1 rough : 1 smooth offspring [1];',1,1);
INSERT INTO rubric_criterion VALUES(9911,'bio12a3-mono-26',NULL,3,'(c) each smooth offspring must have received r from the unknown parent, since the smooth parent contributes only r [1].',1,1);
INSERT INTO rubric_criterion VALUES(9912,'bio12a3-mono-27',NULL,0,'It has one copy of the recessive allele, which it can pass on to its offspring [1];',1,1);
INSERT INTO rubric_criterion VALUES(9913,'bio12a3-mono-27',NULL,1,'it shows the dominant phenotype because the dominant allele masks the recessive one [1].',1,1);
INSERT INTO rubric_criterion VALUES(9914,'bio12a3-mono-28',NULL,0,'(a) 1/2 (two of four squares are Pp) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9915,'bio12a3-mono-28',NULL,1,'(b) 3/4 (PP or Pp are unaffected) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9916,'bio12a3-mono-28',NULL,2,'(c) each conception is an independent event, so earlier children do not change the chance for later ones [1].',1,1);
INSERT INTO rubric_criterion VALUES(9917,'bio12a3-mono-29',NULL,0,'(a) Rr [1];',1,1);
INSERT INTO rubric_criterion VALUES(9918,'bio12a3-mono-29',NULL,1,'(b) 3 red : 1 white [1];',1,1);
INSERT INTO rubric_criterion VALUES(9919,'bio12a3-mono-29',NULL,2,'(c) homozygous for the trait, so it breeds true and produces offspring with the same phenotype for that trait when self-pollinated [1];',1,1);
INSERT INTO rubric_criterion VALUES(9920,'bio12a3-mono-29',NULL,3,'(d) the R allele is dominant, so the heterozygous Rr plants express red [1].',1,1);
INSERT INTO rubric_criterion VALUES(9921,'bio12a3-mono-30',NULL,0,'Bb [1];',1,1);
INSERT INTO rubric_criterion VALUES(9922,'bio12a3-mono-30',NULL,1,'the white offspring (bb) must have received a b allele from the black parent, so that parent carries b, and as it shows black it must be heterozygous [1].',1,1);
INSERT INTO rubric_criterion VALUES(9929,'bio12a3-dihy-6',NULL,0,'(a) BbRr produces BR, Br, bR and br gametes in equal proportions; bbrr produces only br gametes;',1,1);
INSERT INTO rubric_criterion VALUES(9930,'bio12a3-dihy-6',NULL,1,'(b) offspring 1 black rough (BbRr) : 1 black smooth (Bbrr) : 1 white rough (bbRr) : 1 white smooth (bbrr), i.e.',1,1);
INSERT INTO rubric_criterion VALUES(9931,'bio12a3-dihy-6',NULL,2,'1 : 1 : 1 : 1.',1,1);
INSERT INTO rubric_criterion VALUES(9932,'bio12a3-dihy-7',NULL,0,'Genes on different (non-homologous) chromosomes assort independently because the orientation of each homologous pair at metaphase I is random;',1,1);
INSERT INTO rubric_criterion VALUES(9933,'bio12a3-dihy-7',NULL,1,'this gives all allele combinations in gametes in equal proportions;',1,1);
INSERT INTO rubric_criterion VALUES(9934,'bio12a3-dihy-7',NULL,2,'linked genes are on the same chromosome and tend to be inherited together, so parental combinations of alleles are more common in gametes and new combinations only arise when crossing over occurs between the loci.',1,1);
INSERT INTO rubric_criterion VALUES(9935,'bio12a3-dihy-8',NULL,0,'The 1 : 1 : 1 : 1 ratio is consistent with independent assortment, so the genes are probably unlinked;',1,1);
INSERT INTO rubric_criterion VALUES(9936,'bio12a3-dihy-8',NULL,1,'however genes very far apart on the same chromosome can also recombine at close to 50%, so the result alone does not prove they are on different chromosomes.',1,1);
INSERT INTO rubric_criterion VALUES(9951,'bio12a3-dihy-23',NULL,0,'(a) Recombination frequency = 150 ÷ 1000 × 100 = 15% [1];',1,1);
INSERT INTO rubric_criterion VALUES(9952,'bio12a3-dihy-23',NULL,1,'(b) the genes are linked because recombinant phenotypes make up only 15% (less than 50%), so the parental phenotypes are far more common [1].',1,1);
INSERT INTO rubric_criterion VALUES(9953,'bio12a3-dihy-24',NULL,0,'Crossing over occurs in prophase I [1];',1,1);
INSERT INTO rubric_criterion VALUES(9954,'bio12a3-dihy-24',NULL,1,'homologous chromosomes pair and non-sister chromatids exchange equal segments at chiasmata [1];',1,1);
INSERT INTO rubric_criterion VALUES(9955,'bio12a3-dihy-24',NULL,2,'the chromatids then carry new combinations of alleles, so the gametes formed from them are recombinant [1].',1,1);
INSERT INTO rubric_criterion VALUES(9956,'bio12a3-dihy-25',NULL,0,'The percentage of offspring (or gametes) that show recombinant phenotypes (or genotypes), calculated as recombinant ÷ total × 100 [1].',1,1);
INSERT INTO rubric_criterion VALUES(9957,'bio12a3-dihy-26',NULL,0,'(a) TtRr produces TR, Tr, tR and tr in equal proportions [1];',1,1);
INSERT INTO rubric_criterion VALUES(9958,'bio12a3-dihy-26',NULL,1,'ttRr produces tR and tr in equal proportions [1];',1,1);
INSERT INTO rubric_criterion VALUES(9959,'bio12a3-dihy-26',NULL,2,'(b) tall red : tall white : dwarf red : dwarf white = 3 : 1 : 3 : 1 [1];',1,1);
INSERT INTO rubric_criterion VALUES(9960,'bio12a3-dihy-26',NULL,3,'(c) 1/2 × 1/4 = 1/8, so 1/8 × 320 = 40 tall white offspring [1].',1,1);
INSERT INTO rubric_criterion VALUES(9961,'bio12a3-dihy-27',NULL,0,'Independent assortment: random orientation of homologous pairs at metaphase I produces different combinations of maternal and paternal chromosomes in gametes [1];',1,1);
INSERT INTO rubric_criterion VALUES(9962,'bio12a3-dihy-27',NULL,1,'crossing over: exchange of segments between non-sister chromatids in prophase I produces new combinations of alleles on the same chromosome [1].',1,1);
INSERT INTO rubric_criterion VALUES(9963,'bio12a3-dihy-28',NULL,0,'(a) 35% of gametes are AB (70% parental, split equally) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9964,'bio12a3-dihy-28',NULL,1,'(b) 30% × 500 = 150 recombinant offspring [1];',1,1);
INSERT INTO rubric_criterion VALUES(9965,'bio12a3-dihy-28',NULL,2,'(c) ab gametes are 35%, so 35% × 500 = 175 ab/ab offspring [1].',1,1);
INSERT INTO rubric_criterion VALUES(9966,'bio12a3-dihy-29',NULL,0,'Probability of aa from Aa × Aa = 1/4 [1];',1,1);
INSERT INTO rubric_criterion VALUES(9967,'bio12a3-dihy-29',NULL,1,'probability of B_ from Bb × Bb = 3/4, so aaB_ = 1/4 × 3/4 = 3/16 [1].',1,1);
INSERT INTO rubric_criterion VALUES(9968,'bio12a3-dihy-30',NULL,0,'ABC, ABc, AbC and Abc, each 25% [1].',1,1);
INSERT INTO rubric_criterion VALUES(9975,'bio12a3-ped-6',NULL,0,'(a) Both parents are Ff;',1,1);
INSERT INTO rubric_criterion VALUES(9976,'bio12a3-ped-6',NULL,1,'(b) Ff × Ff gives 1 FF : 2 Ff : 1 ff, so the probability of a carrier (Ff) child is 1/2;',1,1);
INSERT INTO rubric_criterion VALUES(9977,'bio12a3-ped-6',NULL,2,'(c) the daughter is unaffected so she cannot be ff;',1,1);
INSERT INTO rubric_criterion VALUES(9978,'bio12a3-ped-6',NULL,3,'of the remaining unaffected outcomes (1 FF : 2 Ff) two out of three are carriers, so her probability is 2/3.',1,1);
INSERT INTO rubric_criterion VALUES(9979,'bio12a3-ped-7',NULL,0,'Autosomal dominant traits usually appear in every generation and every affected person has at least one affected parent, whereas recessive traits can skip generations;',1,1);
INSERT INTO rubric_criterion VALUES(9980,'bio12a3-ped-7',NULL,1,'two affected parents can have an unaffected child with a dominant trait, but two affected parents with a recessive trait (both homozygous recessive) will only have affected children.',1,1);
INSERT INTO rubric_criterion VALUES(9981,'bio12a3-ped-8',NULL,0,'Males have one X chromosome (XY), so a single recessive allele (XʰY) is enough to cause haemophilia;',1,1);
INSERT INTO rubric_criterion VALUES(9982,'bio12a3-ped-8',NULL,1,'females have two X chromosomes and need two copies of the recessive allele (XʰXʰ), which is much less likely;',1,1);
INSERT INTO rubric_criterion VALUES(9983,'bio12a3-ped-8',NULL,2,'a father passes his Y chromosome, not his X, to his sons, so sons get their X from their mother and cannot inherit the allele from their father.',1,1);
INSERT INTO rubric_criterion VALUES(9997,'bio12a3-ped-22',NULL,0,'A carrier is a person who is heterozygous for the recessive allele, so is unaffected but can pass the allele to their offspring [1].',1,1);
INSERT INTO rubric_criterion VALUES(9998,'bio12a3-ped-23',NULL,0,'The affected grandfather (XᵃY) passes Xᵃ to his daughter, who is an unaffected carrier (XᴬXᵃ) [1];',1,1);
INSERT INTO rubric_criterion VALUES(9999,'bio12a3-ped-23',NULL,1,'the dominant Xᴬ masks the recessive allele, so she does not show the trait and the generation is skipped [1];',1,1);
INSERT INTO rubric_criterion VALUES(10000,'bio12a3-ped-23',NULL,2,'her son receives Xᵃ with probability 1/2 and is affected, so the trait reappears in the next generation [1].',1,1);
INSERT INTO rubric_criterion VALUES(10001,'bio12a3-ped-24',NULL,0,'Sons: probability 0, because sons receive Y from their father and Xᵈ from their unaffected mother [1];',1,1);
INSERT INTO rubric_criterion VALUES(10002,'bio12a3-ped-24',NULL,1,'daughters: probability 1, because every daughter receives Xᴰ from her affected father [1];',1,1);
INSERT INTO rubric_criterion VALUES(10003,'bio12a3-ped-24',NULL,2,'daughters are affected even though they are heterozygous (XᴰXᵈ), because the allele is dominant [1].',1,1);
INSERT INTO rubric_criterion VALUES(10004,'bio12a3-ped-25',NULL,0,'(a) I-2 is Aa, because she must have given the recessive allele to the affected daughter II-2 [1];',1,1);
INSERT INTO rubric_criterion VALUES(10005,'bio12a3-ped-25',NULL,1,'II-1 is Aa, because he received a from his affected father and is unaffected [1];',1,1);
INSERT INTO rubric_criterion VALUES(10006,'bio12a3-ped-25',NULL,2,'(b) the probability is 1/4 (25%) [1], because Aa × Aa gives 1 AA : 2 Aa : 1 aa and only aa children are affected [1].',2,1);
INSERT INTO rubric_criterion VALUES(10007,'bio12a3-ped-26',NULL,0,'She needs two copies of the recessive allele, so she must receive Xᵃ from her father as well as from her mother [1];',1,1);
INSERT INTO rubric_criterion VALUES(10008,'bio12a3-ped-26',NULL,1,'a father has only one X chromosome, so he must carry Xᵃ and be affected (XᵃY) [1].',1,1);
INSERT INTO rubric_criterion VALUES(10009,'bio12a3-ped-27',NULL,0,'Related parents are more likely to carry the same recessive allele, inherited from a common ancestor [1];',1,1);
INSERT INTO rubric_criterion VALUES(10010,'bio12a3-ped-27',NULL,1,'so the child is more likely to inherit two copies of that allele and show the condition [1].',1,1);
INSERT INTO rubric_criterion VALUES(10011,'bio12a3-ped-28',NULL,0,'Yes, it rules out X-linked dominant inheritance [1];',1,1);
INSERT INTO rubric_criterion VALUES(10012,'bio12a3-ped-28',NULL,1,'an affected father with X-linked dominant inheritance passes the dominant allele to all his daughters, who would all be affected [1].',1,1);
INSERT INTO rubric_criterion VALUES(10019,'bio12a3-asex-6',NULL,0,'The circular chromosome is replicated and the two copies attach to the plasma membrane;',1,1);
INSERT INTO rubric_criterion VALUES(10020,'bio12a3-asex-6',NULL,1,'the cell elongates, separating the copies, and the membrane and cell wall pinch in across the middle to form two daughter cells;',1,1);
INSERT INTO rubric_criterion VALUES(10021,'bio12a3-asex-6',NULL,2,'each daughter receives an identical copy of the replicated DNA, so they are genetically identical unless a mutation occurred during replication.',1,1);
INSERT INTO rubric_criterion VALUES(10022,'bio12a3-asex-7',NULL,0,'Advantages: no mate is needed so isolated individuals can reproduce; reproduction is fast and energy-efficient, allowing rapid population growth;',1,1);
INSERT INTO rubric_criterion VALUES(10023,'bio12a3-asex-7',NULL,1,'(also accept: successful genotypes are passed on unchanged). Disadvantages: offspring have little genetic variation, so the population may not survive a change in the environment or a new disease;',1,1);
INSERT INTO rubric_criterion VALUES(10024,'bio12a3-asex-7',NULL,2,'harmful mutations can build up in the lineage;',1,1);
INSERT INTO rubric_criterion VALUES(10025,'bio12a3-asex-7',NULL,3,'offspring may compete closely with the parent for resources.',1,1);
INSERT INTO rubric_criterion VALUES(10026,'bio12a3-asex-8',NULL,0,'In spring and summer food is plentiful and conditions are stable, so asexual reproduction allows rapid population growth to exploit resources;',1,1);
INSERT INTO rubric_criterion VALUES(10027,'bio12a3-asex-8',NULL,1,'in autumn conditions change and become harsher, so sexual reproduction produces genetically diverse offspring (and overwintering eggs), increasing the chance some will survive the changed conditions.',1,1);
INSERT INTO rubric_criterion VALUES(10041,'bio12a3-asex-22',NULL,0,'A small piece of plant tissue (explant) is removed and placed on sterile nutrient medium containing plant hormones [1];',1,1);
INSERT INTO rubric_criterion VALUES(10042,'bio12a3-asex-22',NULL,1,'its cells divide by mitosis to form a mass of undifferentiated cells, which is then induced to form shoots and roots, producing plantlets [1];',1,1);
INSERT INTO rubric_criterion VALUES(10043,'bio12a3-asex-22',NULL,2,'the cells are produced by mitosis with no meiosis or fertilisation, so each plantlet has the same genotype as the parent plant [1].',1,1);
INSERT INTO rubric_criterion VALUES(10044,'bio12a3-asex-23',NULL,0,'A group of genetically identical individuals produced asexually from one parent, by mitosis [1].',1,1);
INSERT INTO rubric_criterion VALUES(10045,'bio12a3-asex-24',NULL,0,'Each eye contains a bud from which shoots grow, and the cells of the shoots are produced by mitosis from the parent''s own cells [1];',1,1);
INSERT INTO rubric_criterion VALUES(10046,'bio12a3-asex-24',NULL,1,'no meiosis or fertilisation is involved, so no new combination of alleles is formed [1];',1,1);
INSERT INTO rubric_criterion VALUES(10047,'bio12a3-asex-24',NULL,2,'the new plants have the same genotype as the parent tuber, so they keep its desirable traits [1].',1,1);
INSERT INTO rubric_criterion VALUES(10048,'bio12a3-asex-25',NULL,0,'Asexual reproduction involves no meiosis or fertilisation, so no new combinations of existing alleles are produced [1];',1,1);
INSERT INTO rubric_criterion VALUES(10049,'bio12a3-asex-25',NULL,1,'new alleles can arise only from mutations, which occur during DNA replication [1];',1,1);
INSERT INTO rubric_criterion VALUES(10050,'bio12a3-asex-25',NULL,2,'a beneficial mutation in one cell is passed to all of its clone offspring by mitosis [1];',1,1);
INSERT INTO rubric_criterion VALUES(10051,'bio12a3-asex-25',NULL,3,'if it improves survival or reproduction, natural selection causes the clone lineage carrying it to increase in frequency in the population [1].',1,1);
INSERT INTO rubric_criterion VALUES(10052,'bio12a3-asex-26',NULL,0,'Buds form at the leaf margin, and their cells divide by mitosis to produce a small plant with roots and shoots [1];',1,1);
INSERT INTO rubric_criterion VALUES(10053,'bio12a3-asex-26',NULL,1,'the plantlet develops from the parent''s own body cells, with no meiosis or fertilisation [1];',1,1);
INSERT INTO rubric_criterion VALUES(10054,'bio12a3-asex-26',NULL,2,'so it has the same genotype as the parent and is a clone [1].',1,1);
INSERT INTO rubric_criterion VALUES(10055,'bio12a3-asex-27',NULL,0,'Gemmae are formed by mitosis in the parent plant, so no meiosis or fertilisation is involved [1];',1,1);
INSERT INTO rubric_criterion VALUES(10056,'bio12a3-asex-27',NULL,1,'each gemma grows into a new plant that is genetically identical to the single parent [1].',1,1);
INSERT INTO rubric_criterion VALUES(10057,'bio12a3-asex-28',NULL,0,'Advantage: many genetically identical plants can be produced quickly from a small amount of tissue, keeping the desirable traits of the variety [1];',1,1);
INSERT INTO rubric_criterion VALUES(10058,'bio12a3-asex-28',NULL,1,'disadvantage: the plants have little genetic variation, so the whole group is at risk from a new disease or environmental change [1].',1,1);
INSERT INTO rubric_criterion VALUES(10059,'bio12a3-asex-29',NULL,0,'Asexual reproduction in plants in which a new plant grows from a non-reproductive part of the parent, such as a stem, root or leaf [1].',1,1);
INSERT INTO rubric_criterion VALUES(10060,'bio12a3-asex-30',NULL,0,'Cells in the fragment divide by mitosis and reorganise to form the body structures of a complete sponge [1];',1,1);
INSERT INTO rubric_criterion VALUES(10061,'bio12a3-asex-30',NULL,1,'the new sponge is genetically identical to the parent because no meiosis or fertilisation occurred [1].',1,1);
INSERT INTO rubric_criterion VALUES(10068,'bio12a3-sex-6',NULL,0,'Crossing over: during prophase I homologous chromosomes pair and non-sister chromatids exchange segments at chiasmata;',1,1);
INSERT INTO rubric_criterion VALUES(10069,'bio12a3-sex-6',NULL,1,'this produces recombinant chromatids with new combinations of alleles on the same chromosome.',1,1);
INSERT INTO rubric_criterion VALUES(10070,'bio12a3-sex-6',NULL,2,'Independent assortment: during metaphase I each homologous pair lines up at the equator in a random orientation independent of other pairs;',1,1);
INSERT INTO rubric_criterion VALUES(10071,'bio12a3-sex-6',NULL,3,'so maternal and paternal chromosomes are distributed to gametes in many different combinations (2ⁿ).',1,1);
INSERT INTO rubric_criterion VALUES(10072,'bio12a3-sex-7',NULL,0,'Genetic diversity means individuals carry different alleles, so some are more likely to have traits that let them survive a new selection pressure such as disease or climate change;',1,1);
INSERT INTO rubric_criterion VALUES(10073,'bio12a3-sex-7',NULL,1,'these individuals survive and reproduce so the population persists;',1,1);
INSERT INTO rubric_criterion VALUES(10074,'bio12a3-sex-7',NULL,2,'for example the Tasmanian devil has very low genetic diversity, which has made it highly vulnerable to devil facial tumour disease, which spreads between devils because their immune systems do not recognise the tumour cells as foreign.',1,1);
INSERT INTO rubric_criterion VALUES(10075,'bio12a3-sex-8',NULL,0,'In meiosis I homologous chromosomes separate, so the two cells produced are haploid (n) although each chromosome still has two chromatids;',1,1);
INSERT INTO rubric_criterion VALUES(10076,'bio12a3-sex-8',NULL,1,'in meiosis II sister chromatids separate, like mitosis;',1,1);
INSERT INTO rubric_criterion VALUES(10077,'bio12a3-sex-8',NULL,2,'this produces four haploid cells, each chromosome with a single chromatid, and the ploidy does not change in meiosis II.',1,1);
INSERT INTO rubric_criterion VALUES(10091,'bio12a3-sex-22',NULL,0,'A haploid sperm nucleus fuses with a haploid ovum nucleus to form a diploid zygote [1];',1,1);
INSERT INTO rubric_criterion VALUES(10092,'bio12a3-sex-22',NULL,1,'this restores the diploid chromosome number that meiosis halved, so each generation keeps the same number [1].',1,1);
INSERT INTO rubric_criterion VALUES(10093,'bio12a3-sex-23',NULL,0,'Meiosis II non-disjunction: sister chromatids of one chromosome fail to separate in anaphase II, so two of the four gametes are normal and two are abnormal, one with an extra chromosome and one missing a chromosome [1];',1,1);
INSERT INTO rubric_criterion VALUES(10094,'bio12a3-sex-23',NULL,1,'meiosis I non-disjunction: a homologous pair fails to separate in anaphase I, so all four gametes are abnormal, two with an extra chromosome and two missing one [1];',1,1);
INSERT INTO rubric_criterion VALUES(10095,'bio12a3-sex-23',NULL,2,'so meiosis II non-disjunction produces a mix of normal and abnormal gametes, whereas meiosis I non-disjunction makes every gamete abnormal [1].',1,1);
INSERT INTO rubric_criterion VALUES(10096,'bio12a3-sex-24',NULL,0,'Gametes are the cells that fuse to form a zygote, so a mutation in a gamete''s DNA can be passed on to the offspring [1];',1,1);
INSERT INTO rubric_criterion VALUES(10097,'bio12a3-sex-24',NULL,1,'mutations in body (somatic) cells are not inherited by offspring, so their effects are limited to that individual [1].',1,1);
INSERT INTO rubric_criterion VALUES(10098,'bio12a3-sex-25',NULL,0,'Mitosis has one division whereas meiosis has two divisions [1];',1,1);
INSERT INTO rubric_criterion VALUES(10099,'bio12a3-sex-25',NULL,1,'mitosis produces two daughter cells and meiosis produces four daughter cells [1];',1,1);
INSERT INTO rubric_criterion VALUES(10100,'bio12a3-sex-25',NULL,2,'mitosis daughter cells are diploid and meiosis daughter cells are haploid [1];',1,1);
INSERT INTO rubric_criterion VALUES(10101,'bio12a3-sex-25',NULL,3,'mitosis daughter cells are genetically identical to the parent cell, whereas meiosis daughter cells are genetically different from each other and from the parent [1].',1,1);
INSERT INTO rubric_criterion VALUES(10102,'bio12a3-sex-26',NULL,0,'Any gamete from one parent can fuse with any gamete from the other, so each zygote combines a random gamete from each parent [1];',1,1);
INSERT INTO rubric_criterion VALUES(10103,'bio12a3-sex-26',NULL,1,'each gamete carries a random mix of maternal and paternal chromosomes from independent assortment, so each parent produces 2ⁿ different gametes [1];',1,1);
INSERT INTO rubric_criterion VALUES(10104,'bio12a3-sex-26',NULL,2,'the number of possible zygotes is therefore (2ⁿ) × (2ⁿ), a very large number of different combinations [1].',1,1);
INSERT INTO rubric_criterion VALUES(10105,'bio12a3-sex-27',NULL,0,'Two sister chromatids, joined at the centromere [1].',1,1);
INSERT INTO rubric_criterion VALUES(10106,'bio12a3-sex-28',NULL,0,'Females have two X chromosomes (XX) and males have one X and one Y chromosome (XY) [1];',1,1);
INSERT INTO rubric_criterion VALUES(10107,'bio12a3-sex-28',NULL,1,'each ovum carries an X chromosome, and the sex of the offspring depends on whether the sperm that fertilises it carries an X (female) or a Y (male) [1].',1,1);
INSERT INTO rubric_criterion VALUES(10114,'bio12a3-clone-6',NULL,0,'A somatic (body) cell is taken from the cow to be cloned and its nucleus extracted;',1,1);
INSERT INTO rubric_criterion VALUES(10115,'bio12a3-clone-6',NULL,1,'an egg cell is taken from a donor cow and its nucleus removed (enucleated);',1,1);
INSERT INTO rubric_criterion VALUES(10116,'bio12a3-clone-6',NULL,2,'the donor nucleus is inserted into (or the somatic cell fused with) the enucleated egg and an electric pulse or chemicals stimulate it to divide;',1,1);
INSERT INTO rubric_criterion VALUES(10117,'bio12a3-clone-6',NULL,3,'the resulting embryo is grown in culture to an early embryo and implanted into the uterus of a surrogate cow, which gives birth to a calf genetically identical (in nuclear DNA) to the somatic cell donor.',1,1);
INSERT INTO rubric_criterion VALUES(10118,'bio12a3-clone-7',NULL,0,'Gene expression is affected by the environment and by random events in development (e.g. X-chromosome inactivation in female cats determines coat patches), so the same genotype can give a different phenotype;',1,1);
INSERT INTO rubric_criterion VALUES(10119,'bio12a3-clone-7',NULL,1,'the clone also has mitochondrial DNA from the egg donor and develops in a different uterine environment from the donor.',1,1);
INSERT INTO rubric_criterion VALUES(10120,'bio12a3-clone-8',NULL,0,'Benefit: animals or plants with desirable traits (e.g. high milk yield, disease resistance) can be copied exactly and quickly;',1,1);
INSERT INTO rubric_criterion VALUES(10121,'bio12a3-clone-8',NULL,1,'risk: herds or crops of clones have low genetic diversity, so a single disease or environmental change could devastate them (also accept low success rates and health problems in cloned animals, or ethical concerns about animal welfare).',1,1);
INSERT INTO rubric_criterion VALUES(10134,'bio12a3-clone-21',NULL,0,'Early embryo cells are undifferentiated and totipotent, so each can develop into any cell type [1];',1,1);
INSERT INTO rubric_criterion VALUES(10135,'bio12a3-clone-21',NULL,1,'each separated group of cells can therefore develop into a complete embryo [1].',1,1);
INSERT INTO rubric_criterion VALUES(10136,'bio12a3-clone-22',NULL,0,'Sterile conditions prevent contamination by bacteria or fungi [1];',1,1);
INSERT INTO rubric_criterion VALUES(10137,'bio12a3-clone-22',NULL,1,'contaminants would compete with the explant for nutrients or kill the plant tissue [1].',1,1);
INSERT INTO rubric_criterion VALUES(10138,'bio12a3-clone-23',NULL,0,'Collect DNA samples (e.g. from tissue or blood) from the clone and the donor [1];',1,1);
INSERT INTO rubric_criterion VALUES(10139,'bio12a3-clone-23',NULL,1,'compare DNA profiles or markers, such as microsatellites or sequence data, at several loci [1];',1,1);
INSERT INTO rubric_criterion VALUES(10140,'bio12a3-clone-23',NULL,2,'matching results at all loci indicate identical nuclear DNA [1].',1,1);
INSERT INTO rubric_criterion VALUES(10141,'bio12a3-clone-24',NULL,0,'Only the cells of an early, undifferentiated embryo can each form a whole organism, and the embryo has a limited number of cells [1];',1,1);
INSERT INTO rubric_criterion VALUES(10142,'bio12a3-clone-24',NULL,1,'splitting it into too many pieces leaves each piece with too few cells to develop successfully [1].',1,1);
INSERT INTO rubric_criterion VALUES(10143,'bio12a3-clone-25',NULL,0,'Micropropagation uses small pieces of plant tissue (explants, often meristem), whereas SCNT uses a body cell nucleus placed in an enucleated egg [1];',1,1);
INSERT INTO rubric_criterion VALUES(10144,'bio12a3-clone-25',NULL,1,'micropropagation grows explants on sterile nutrient media with hormones, whereas SCNT embryos are stimulated to divide and then implanted into a surrogate uterus [1];',1,1);
INSERT INTO rubric_criterion VALUES(10145,'bio12a3-clone-25',NULL,2,'both produce offspring genetically identical to the source of the nuclear DNA [1];',1,1);
INSERT INTO rubric_criterion VALUES(10146,'bio12a3-clone-25',NULL,3,'micropropagation involves no egg or sperm, whereas SCNT uses an egg but no sperm [1].',1,1);
INSERT INTO rubric_criterion VALUES(10147,'bio12a3-clone-26',NULL,0,'Many cloned embryos fail or die before or soon after birth, so many animals suffer [1];',1,1);
INSERT INTO rubric_criterion VALUES(10148,'bio12a3-clone-26',NULL,1,'surviving clones may have health problems such as abnormal organ development or shortened lifespan [1].',1,1);
INSERT INTO rubric_criterion VALUES(10149,'bio12a3-clone-27',NULL,0,'Working: 12 ÷ 250 × 100 [1];',1,1);
INSERT INTO rubric_criterion VALUES(10150,'bio12a3-clone-27',NULL,1,'answer: 4.8% of transferred embryos produced a live calf [1].',1,1);
INSERT INTO rubric_criterion VALUES(10151,'bio12a3-clone-28',NULL,0,'Clones are genetically identical in nuclear DNA, so the same mutation is copied into every clone [1];',1,1);
INSERT INTO rubric_criterion VALUES(10152,'bio12a3-clone-28',NULL,1,'if the mutation is harmful, all of the clones are affected, so the problem is repeated across the population [1].',1,1);
INSERT INTO rubric_criterion VALUES(10159,'bio12a3-adapt-6',NULL,0,'Structural adaptations are physical features of the body, e.g. the large ears of the bilby, which lose heat;',1,1);
INSERT INTO rubric_criterion VALUES(10160,'bio12a3-adapt-6',NULL,1,'physiological adaptations are internal functions or processes, e.g. the spinifex hopping mouse producing highly concentrated urine to conserve water;',1,1);
INSERT INTO rubric_criterion VALUES(10161,'bio12a3-adapt-6',NULL,2,'behavioural adaptations are actions an organism carries out, e.g. kangaroos licking their forearms so evaporation cools the blood in surface vessels.',1,1);
INSERT INTO rubric_criterion VALUES(10162,'bio12a3-adapt-7',NULL,0,'A thick waxy cuticle on leaves is waterproof, so less water evaporates through the leaf surface;',1,1);
INSERT INTO rubric_criterion VALUES(10163,'bio12a3-adapt-7',NULL,1,'sunken stomata or stomata in hair-lined pits trap a layer of humid air, which reduces the water vapour concentration gradient and slows transpiration (also accept: reduced leaf surface area/needle-like leaves lower the area for water loss;',1,1);
INSERT INTO rubric_criterion VALUES(10164,'bio12a3-adapt-7',NULL,2,'vertically hanging leaves, as in eucalypts, reduce heat absorbed in the midday sun;',1,1);
INSERT INTO rubric_criterion VALUES(10165,'bio12a3-adapt-7',NULL,3,'rolled leaves enclose stomata).',1,1);
INSERT INTO rubric_criterion VALUES(10166,'bio12a3-adapt-8',NULL,0,'Longer ears have a larger surface area with many blood vessels, which increases heat loss to the environment by radiation and convection;',1,1);
INSERT INTO rubric_criterion VALUES(10167,'bio12a3-adapt-8',NULL,1,'in hot climates rabbits with longer ears are more likely to avoid overheating, survive and reproduce, so the trait becomes more common, while in cooler regions shorter ears reduce heat loss.',1,1);
INSERT INTO rubric_criterion VALUES(10182,'bio12a3-adapt-23',NULL,0,'An action or behaviour carried out by an organism [1] that improves its chance of survival or reproduction, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10183,'bio12a3-adapt-23',NULL,1,'an echidna curling into a ball with its spines facing outwards when threatened [1].',1,1);
INSERT INTO rubric_criterion VALUES(10184,'bio12a3-adapt-24',NULL,0,'Structural [1].',1,1);
INSERT INTO rubric_criterion VALUES(10185,'bio12a3-adapt-25',NULL,0,'Pale colours reflect a greater proportion of incoming solar radiation [1];',1,1);
INSERT INTO rubric_criterion VALUES(10186,'bio12a3-adapt-25',NULL,1,'less radiant energy is absorbed by the skin [1];',1,1);
INSERT INTO rubric_criterion VALUES(10187,'bio12a3-adapt-25',NULL,2,'so less heat is gained from the environment, and less evaporative cooling and water loss is needed [1].',1,1);
INSERT INTO rubric_criterion VALUES(10188,'bio12a3-adapt-26',NULL,0,'Vasoconstriction: blood vessels in the skin narrow [1], reducing blood flow to the surface so less heat is lost to the air [1];',1,1);
INSERT INTO rubric_criterion VALUES(10189,'bio12a3-adapt-26',NULL,1,'shivering: rapid, involuntary muscle contractions [1] release heat from the metabolism of the muscles [1].',3,1);
INSERT INTO rubric_criterion VALUES(10190,'bio12a3-adapt-27',NULL,0,'Water evaporates from the skin surface [1], and the energy needed to change it from liquid to vapour (latent heat) is taken from the skin and blood, cooling the body [1].',2,1);
INSERT INTO rubric_criterion VALUES(10191,'bio12a3-adapt-28',NULL,0,'Huddling with other individuals [1], which reduces the surface area exposed to cold air per animal and so reduces heat loss [1];',1,1);
INSERT INTO rubric_criterion VALUES(10192,'bio12a3-adapt-28',NULL,1,'sheltering in a nest or burrow lined with insulating material [1], which traps warm air and reduces exposure to wind and cold [1].',3,1);
INSERT INTO rubric_criterion VALUES(10193,'bio12a3-adapt-29',NULL,0,'Larger leaves provide more surface area for light capture in low light [1];',1,1);
INSERT INTO rubric_criterion VALUES(10194,'bio12a3-adapt-29',NULL,1,'thin leaves shorten the diffusion path for CO₂ to reach the chloroplasts [1];',1,1);
INSERT INTO rubric_criterion VALUES(10195,'bio12a3-adapt-29',NULL,2,'exposed, dry habitats favour smaller, thicker leaves, which reduce the surface area for water loss [1].',1,1);
INSERT INTO rubric_criterion VALUES(10196,'bio12a3-adapt-30',NULL,0,'Chloride cells in the gills actively pump excess salt out of the body [1].',1,1);
INSERT INTO rubric_criterion VALUES(10203,'bio12a3-aus-6',NULL,0,'Structural: a dense network of blood vessels close to the skin of the forearms, which loses heat when licked;',1,1);
INSERT INTO rubric_criterion VALUES(10204,'bio12a3-aus-6',NULL,1,'physiological: produces concentrated urine and can slow or pause embryo development (embryonic diapause) when conditions are poor;',1,1);
INSERT INTO rubric_criterion VALUES(10205,'bio12a3-aus-6',NULL,2,'behavioural: rests in shade during the hottest part of the day and is mostly active at dawn, dusk and night, and licks forearms so evaporation cools the blood.',1,1);
INSERT INTO rubric_criterion VALUES(10206,'bio12a3-aus-7',NULL,0,'Elastic tendons in the hind legs (e.g. the Achilles tendon) store energy on landing and release it in the next hop, so above a certain speed the energy cost of hopping barely rises with speed;',1,1);
INSERT INTO rubric_criterion VALUES(10207,'bio12a3-aus-7',NULL,1,'this lets kangaroos travel long distances between scattered food and water sources with relatively little energy use.',1,1);
INSERT INTO rubric_criterion VALUES(10208,'bio12a3-aus-8',NULL,0,'Vertically hanging leaves present their edge to the midday sun, so less light and heat are absorbed in the hottest part of the day, lowering leaf temperature and transpiration;',1,1);
INSERT INTO rubric_criterion VALUES(10209,'bio12a3-aus-8',NULL,1,'the thick waxy cuticle is waterproof and reduces evaporation of water from the leaf surface.',1,1);
INSERT INTO rubric_criterion VALUES(10222,'bio12a3-aus-21',NULL,0,'Structural: a very long caecum (around 2 m) that houses microbes which ferment cellulose and help break down toxic compounds [1];',1,1);
INSERT INTO rubric_criterion VALUES(10223,'bio12a3-aus-21',NULL,1,'behavioural: sleeps for around 18 hours or more each day, which reduces energy use on a low-energy diet [1].',1,1);
INSERT INTO rubric_criterion VALUES(10224,'bio12a3-aus-22',NULL,0,'(i) behavioural: an action the emu performs to find food and water [1];',1,1);
INSERT INTO rubric_criterion VALUES(10225,'bio12a3-aus-22',NULL,1,'(ii) structural: a physical feature of the body covering [1].',1,1);
INSERT INTO rubric_criterion VALUES(10226,'bio12a3-aus-23',NULL,0,'Gliding lets it cross between widely spaced trees with much less energy than travelling along the ground [1];',1,1);
INSERT INTO rubric_criterion VALUES(10227,'bio12a3-aus-23',NULL,1,'this allows it to reach scattered feeding sites, such as flowering eucalypts and trees with sap or insects, more quickly [1];',1,1);
INSERT INTO rubric_criterion VALUES(10228,'bio12a3-aus-23',NULL,2,'it avoids ground predators during travel, so more time and energy go into finding food [1].',1,1);
INSERT INTO rubric_criterion VALUES(10229,'bio12a3-aus-24',NULL,0,'The mother can bask and move between sunny and shaded sites to keep herself and her developing embryos warmer than the cold surroundings [1];',1,1);
INSERT INTO rubric_criterion VALUES(10230,'bio12a3-aus-24',NULL,1,'the young develop inside the mother, so they are protected from frost and cold, and are born early enough in the season to feed and grow before winter [1].',1,1);
INSERT INTO rubric_criterion VALUES(10231,'bio12a3-aus-25',NULL,0,'An animal whose body temperature depends mainly on external sources of heat, such as the sun, rather than on heat produced by its own metabolism [1].',1,1);
INSERT INTO rubric_criterion VALUES(10232,'bio12a3-aus-26',NULL,0,'Structural: tough, armoured skin of bony plates (scutes) that reduces water loss and protects against injury [1];',1,1);
INSERT INTO rubric_criterion VALUES(10233,'bio12a3-aus-26',NULL,1,'behavioural: basks on riverbanks in the morning to warm up before hunting [1];',1,1);
INSERT INTO rubric_criterion VALUES(10234,'bio12a3-aus-26',NULL,2,'behavioural: builds mound nests from vegetation whose decomposition generates heat for the eggs [1].',1,1);
INSERT INTO rubric_criterion VALUES(10235,'bio12a3-aus-27',NULL,0,'Fleshy leaves store water and have a thick cuticle that reduces water loss [1];',1,1);
INSERT INTO rubric_criterion VALUES(10236,'bio12a3-aus-27',NULL,1,'a low, trailing growth habit reduces exposure to wind and heat [1];',1,1);
INSERT INTO rubric_criterion VALUES(10237,'bio12a3-aus-27',NULL,2,'stems root at the nodes, so the plant anchors itself in shifting sand [1];',1,1);
INSERT INTO rubric_criterion VALUES(10238,'bio12a3-aus-27',NULL,3,'it spreads vegetatively along the ground, allowing it to colonise and hold dune sand after disturbance [1].',1,1);
INSERT INTO rubric_criterion VALUES(10239,'bio12a3-aus-28',NULL,0,'The frog sheds layers of skin that harden into a cocoon around its body while it sits in mud [1];',1,1);
INSERT INTO rubric_criterion VALUES(10240,'bio12a3-aus-28',NULL,1,'the cocoon reduces evaporative water loss from the skin, so the water stored in its body lasts longer [1].',1,1);
INSERT INTO rubric_criterion VALUES(10243,'bio12a3-aus-31',NULL,0,'Torpor lowers the animal''s body temperature and metabolic rate, so it uses much less energy [1];',1,1);
INSERT INTO rubric_criterion VALUES(10244,'bio12a3-aus-31',NULL,1,'this allows it to survive on stored body fat and limited food through the cold winter months when food is scarce [1].',1,1);
INSERT INTO rubric_criterion VALUES(10251,'bio12a3-inter-6',NULL,0,'Intraspecific competition is competition for limited resources between individuals of the same species, e.g. male red kangaroos competing for mates, or eucalypt seedlings of one species competing for light;',1,1);
INSERT INTO rubric_criterion VALUES(10252,'bio12a3-inter-6',NULL,1,'interspecific competition is competition between individuals of different species for the same resource, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10253,'bio12a3-inter-6',NULL,2,'introduced European honeybees and native bees competing for nectar and tree hollows, or rabbits and native herbivores competing for grasses.',1,1);
INSERT INTO rubric_criterion VALUES(10254,'bio12a3-inter-7',NULL,0,'Flying foxes pollinate the flowers of many native trees (e.g. eucalypts) as they feed on nectar;',1,1);
INSERT INTO rubric_criterion VALUES(10255,'bio12a3-inter-7',NULL,1,'they disperse seeds over long distances, often tens of kilometres, which helps regenerate forests and maintain gene flow between fragmented patches;',1,1);
INSERT INTO rubric_criterion VALUES(10256,'bio12a3-inter-7',NULL,2,'because many plant species depend on them and, in turn, many other animals depend on those plants, losing flying foxes would have a disproportionately large effect on forest structure.',1,1);
INSERT INTO rubric_criterion VALUES(10257,'bio12a3-inter-8',NULL,0,'The skink population would decrease;',1,1);
INSERT INTO rubric_criterion VALUES(10258,'bio12a3-inter-8',NULL,1,'grasshoppers are the skinks'' food source, so less food would lead to lower survival and reproduction of skinks (and they may face greater predation pressure as kookaburras have less alternative prey).',1,1);
INSERT INTO rubric_criterion VALUES(10272,'bio12a3-inter-22',NULL,0,'The position an organism occupies in a food chain or food web, based on its feeding relationship and source of energy [1]',1,1);
INSERT INTO rubric_criterion VALUES(10273,'bio12a3-inter-23',NULL,0,'At each trophic level about 90% of the energy is lost, mainly as heat from respiration, and so is not passed on to the next level [1];',1,1);
INSERT INTO rubric_criterion VALUES(10274,'bio12a3-inter-23',NULL,1,'by the top level too little energy remains to support a viable population of consumers [1]',1,1);
INSERT INTO rubric_criterion VALUES(10275,'bio12a3-inter-24',NULL,0,'The fungal hyphae extend the tree''s root system, increasing the absorption of water and mineral nutrients such as phosphorus for the tree [1];',1,1);
INSERT INTO rubric_criterion VALUES(10276,'bio12a3-inter-24',NULL,1,'in return the tree supplies the fungus with sugars produced by photosynthesis [1]',1,1);
INSERT INTO rubric_criterion VALUES(10277,'bio12a3-inter-25',NULL,0,'A keystone species has a disproportionately large effect on community structure relative to its abundance, so a common species is only a keystone if its removal causes major changes to the community [1];',1,1);
INSERT INTO rubric_criterion VALUES(10278,'bio12a3-inter-25',NULL,1,'many abundant species can be replaced by other species, so their loss would have only small effects on other organisms [1]',1,1);
INSERT INTO rubric_criterion VALUES(10279,'bio12a3-inter-26',NULL,0,'In predation, the predator kills and eats its prey, so the prey is harmed immediately [1];',1,1);
INSERT INTO rubric_criterion VALUES(10280,'bio12a3-inter-26',NULL,1,'in parasitism, the parasite lives on or in the host and gains nutrients from it while usually not killing it quickly [1]',1,1);
INSERT INTO rubric_criterion VALUES(10281,'bio12a3-inter-27',NULL,0,'Quolls that eat cane toads are poisoned and die, so the quoll population declines [1];',1,1);
INSERT INTO rubric_criterion VALUES(10282,'bio12a3-inter-27',NULL,1,'with fewer quolls, predation pressure on the quoll''s prey, such as insects and small vertebrates, is reduced, so prey numbers are likely to increase [1];',1,1);
INSERT INTO rubric_criterion VALUES(10283,'bio12a3-inter-27',NULL,2,'changes in the prey population may then affect other species that depend on the prey or compete with it [1]',1,1);
INSERT INTO rubric_criterion VALUES(10284,'bio12a3-inter-28',NULL,0,'Termites physically change the environment by moving soil and building mounds and tunnels, which alters soil structure, drainage and the distribution of nutrients [1];',1,1);
INSERT INTO rubric_criterion VALUES(10285,'bio12a3-inter-28',NULL,1,'these structures create shelter and habitat for other invertebrates and small animals [1];',1,1);
INSERT INTO rubric_criterion VALUES(10286,'bio12a3-inter-28',NULL,2,'if termites were removed, these species would lose their shelter and could decline [1]',1,1);
INSERT INTO rubric_criterion VALUES(10287,'bio12a3-inter-29',NULL,0,'Water fleas receive 10% of 60 000 kJ = 6000 kJ [1];',1,1);
INSERT INTO rubric_criterion VALUES(10288,'bio12a3-inter-29',NULL,1,'small fish receive 10% of 6000 kJ = 600 kJ [1];',1,1);
INSERT INTO rubric_criterion VALUES(10289,'bio12a3-inter-29',NULL,2,'kingfisher receives 10% of 600 kJ = 60 kJ [1]',1,1);
INSERT INTO rubric_criterion VALUES(10290,'bio12a3-inter-30',NULL,0,'Dugongs and green turtles lose their main food source, so their survival and reproduction decline [1];',1,1);
INSERT INTO rubric_criterion VALUES(10291,'bio12a3-inter-30',NULL,1,'juvenile fish and prawns lose their shelter and nursery habitat, so their numbers fall [1];',1,1);
INSERT INTO rubric_criterion VALUES(10292,'bio12a3-inter-30',NULL,2,'larger predators of these fish and prawns lose prey and may also decline [1];',1,1);
INSERT INTO rubric_criterion VALUES(10293,'bio12a3-inter-30',NULL,3,'reduced seagrass means less sediment is trapped and stabilised, increasing turbidity and harming other organisms such as filter feeders and corals [1]',1,1);
INSERT INTO rubric_criterion VALUES(10301,'bio12a3-ik-6',NULL,0,'Cool, low-intensity burns at the right time remove understorey fuel such as dry grass and leaf litter, so later fires have less fuel and are less intense;',1,1);
INSERT INTO rubric_criterion VALUES(10302,'bio12a3-ik-6',NULL,1,'burning in small patches creates a mosaic of different-aged vegetation that acts as firebreaks and gives animals refuges;',1,1);
INSERT INTO rubric_criterion VALUES(10303,'bio12a3-ik-6',NULL,2,'regrowth after burning provides fresh food for herbivores and promotes germination of fire-adapted plants, maintaining a diversity of habitats and species.',1,1);
INSERT INTO rubric_criterion VALUES(10304,'bio12a3-ik-7',NULL,0,'Example: in parts of south-eastern Australia the flowering of certain wattles signals that fish such as mullet are running or that eels are moving (accept other valid examples, e.g. flowering of a plant indicating turtles or dugong are fat and ready to hunt);',1,1);
INSERT INTO rubric_criterion VALUES(10305,'bio12a3-ik-7',NULL,1,'such indicators are reliable because both species respond to the same seasonal environmental cues (e.g. temperature, day length, rainfall), so their life cycle events happen at consistent times relative to each other.',1,1);
INSERT INTO rubric_criterion VALUES(10306,'bio12a3-ik-8',NULL,0,'Knowledge of breeding seasons, feeding grounds and population changes guides when and where hunting occurs, avoiding times when animals are breeding; community-based management plans and cultural rules limit how many animals are taken and which individuals (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10307,'bio12a3-ik-8',NULL,1,'avoiding pregnant females or young), helping keep populations stable.',1,1);
INSERT INTO rubric_criterion VALUES(10322,'bio12a3-ik-23',NULL,0,'The ongoing responsibility of Traditional Owners to look after land, sea, plants, animals and cultural places, using their knowledge, law and practices [1].',1,1);
INSERT INTO rubric_criterion VALUES(10323,'bio12a3-ik-24',NULL,0,'It is based on long-term, direct observation of changes in species, seasons and water that short-term records would miss [1];',1,1);
INSERT INTO rubric_criterion VALUES(10324,'bio12a3-ik-24',NULL,1,'it captures local species interactions and environmental cues, so management can be tailored to that specific area [1].',1,1);
INSERT INTO rubric_criterion VALUES(10325,'bio12a3-ik-25',NULL,0,'Consult the Traditional Owners and use their knowledge of timing, weather and seasonal indicators to choose when to burn [1];',1,1);
INSERT INTO rubric_criterion VALUES(10326,'bio12a3-ik-25',NULL,1,'assess fuel loads, wind and humidity, prepare firebreaks, then burn cool and in small patches [1];',1,1);
INSERT INTO rubric_criterion VALUES(10327,'bio12a3-ik-25',NULL,2,'monitor the results and plan a mosaic of burns of different ages over time to maintain habitat diversity [1].',1,1);
INSERT INTO rubric_criterion VALUES(10328,'bio12a3-ik-26',NULL,0,'Sea Country includes the reefs, waters and animals that are part of people''s culture and identity, so people hold detailed local knowledge of changes [1];',1,1);
INSERT INTO rubric_criterion VALUES(10329,'bio12a3-ik-26',NULL,1,'involving them gives management a basis in their rights, responsibilities and long-term care, which supports compliance and continuity [1].',1,1);
INSERT INTO rubric_criterion VALUES(10330,'bio12a3-ik-27',NULL,0,'Early dry season burns are cooler and patchy, so they reduce the fuel available for later fires [1];',1,1);
INSERT INTO rubric_criterion VALUES(10331,'bio12a3-ik-27',NULL,1,'this reduces the area burnt by late-season wildfires, which are hotter and more extensive and release more greenhouse gases in total [1];',1,1);
INSERT INTO rubric_criterion VALUES(10332,'bio12a3-ik-27',NULL,2,'savanna burning projects led by Traditional Owners can earn Australian Carbon Credit Units under the Emissions Reduction Fund for emissions avoided [1];',1,1);
INSERT INTO rubric_criterion VALUES(10333,'bio12a3-ik-27',NULL,3,'patchy burning also protects large trees and other vegetation that store carbon, so less carbon is lost [1].',1,1);
INSERT INTO rubric_criterion VALUES(10335,'bio12a3-ik-29',NULL,0,'A fire moving into the wind spreads slowly with a low flame height, so it burns at lower intensity and is easier to control [1];',1,1);
INSERT INTO rubric_criterion VALUES(10336,'bio12a3-ik-29',NULL,1,'the cooler fire consumes less of the canopy and understorey, leaving unburnt patches and reducing the risk of large, hot wildfires later [1].',1,1);
INSERT INTO rubric_criterion VALUES(10337,'bio12a3-ik-30',NULL,0,'The stone rows (weirs) funnelled fish into pools and enclosures as water levels fell, so fish could be caught when they were concentrated [1];',1,1);
INSERT INTO rubric_criterion VALUES(10338,'bio12a3-ik-30',NULL,1,'openings in the traps let smaller fish and many others pass upstream, which supports continued breeding and a sustainable catch [1].',1,1);
INSERT INTO rubric_criterion VALUES(10345,'chem34a1-ecs-6',NULL,0,'Blue colour fades and a brown/pink solid (copper) forms; zinc dissolves and the mixture warms;',1,1);
INSERT INTO rubric_criterion VALUES(10346,'chem34a1-ecs-6',NULL,1,'oxidation: Zn(s) → Zn²⁺(aq) + 2e⁻; reduction: Cu²⁺(aq) + 2e⁻ → Cu(s);',1,1);
INSERT INTO rubric_criterion VALUES(10347,'chem34a1-ecs-6',NULL,2,'overall: Zn(s) + Cu²⁺(aq) → Zn²⁺(aq) + Cu(s).',1,1);
INSERT INTO rubric_criterion VALUES(10348,'chem34a1-ecs-7',NULL,0,'Y < X < Z; X reduces Y²⁺ so X is a stronger reducing agent than Y;',1,1);
INSERT INTO rubric_criterion VALUES(10349,'chem34a1-ecs-7',NULL,1,'Z reduces X²⁺ so Z is stronger than X; consistent with Y not reducing Z²⁺.',1,1);
INSERT INTO rubric_criterion VALUES(10350,'chem34a1-ecs-8',NULL,0,'Br₂ is above I⁻ in the series (+1.09 V > +0.54 V), so Br₂ is a stronger oxidising agent than I₂ and reacts: Br₂(aq) + 2I⁻(aq) → 2Br⁻(aq) + I₂(aq);',1,1);
INSERT INTO rubric_criterion VALUES(10351,'chem34a1-ecs-8',NULL,1,'Br₂ is below Cl₂ (+1.09 V < +1.36 V), so it is not strong enough to oxidise Cl⁻.',1,1);
INSERT INTO rubric_criterion VALUES(10358,'chem34a1-gc-6',NULL,0,'Anode: magnesium, negative electrode;',1,1);
INSERT INTO rubric_criterion VALUES(10359,'chem34a1-gc-6',NULL,1,'anode: Mg(s) → Mg²⁺(aq) + 2e⁻;',1,1);
INSERT INTO rubric_criterion VALUES(10360,'chem34a1-gc-6',NULL,2,'cathode (carbon, positive): Fe³⁺(aq) + e⁻ → Fe²⁺(aq);',1,1);
INSERT INTO rubric_criterion VALUES(10361,'chem34a1-gc-6',NULL,3,'E°cell = 0.77 − (−2.37) = 3.14 V.',1,1);
INSERT INTO rubric_criterion VALUES(10362,'chem34a1-gc-7',NULL,0,'If mixed, electrons would transfer directly between the reactants and the chemical energy would be released as heat;',1,1);
INSERT INTO rubric_criterion VALUES(10363,'chem34a1-gc-7',NULL,1,'separating them forces electrons to travel through an external circuit, so chemical energy is converted into electrical energy.',1,1);
INSERT INTO rubric_criterion VALUES(10364,'chem34a1-gc-8',NULL,0,'The zinc anode loses mass because Zn is oxidised to Zn²⁺ which goes into solution;',1,1);
INSERT INTO rubric_criterion VALUES(10365,'chem34a1-gc-8',NULL,1,'the copper cathode gains mass because Cu²⁺ is reduced and deposited as Cu;',1,1);
INSERT INTO rubric_criterion VALUES(10366,'chem34a1-gc-8',NULL,2,'the blue colour of the Cu²⁺ solution fades as Cu²⁺ concentration decreases.',1,1);
INSERT INTO rubric_criterion VALUES(10373,'chem34a1-fc-6',NULL,0,'Advantages: higher energy efficiency because chemical energy converts directly to electrical energy (avoiding heat → mechanical → electrical steps); only product is water, so no CO₂ or other pollutants at point of use;',1,1);
INSERT INTO rubric_criterion VALUES(10374,'chem34a1-fc-6',NULL,1,'quiet with no moving parts;',1,1);
INSERT INTO rubric_criterion VALUES(10375,'chem34a1-fc-6',NULL,2,'disadvantage: hydrogen is expensive and difficult to store/transport, catalysts such as platinum are costly, or most hydrogen is currently made from fossil fuels.',1,1);
INSERT INTO rubric_criterion VALUES(10376,'chem34a1-fc-7',NULL,0,'Anode: CH₄(g) + 2H₂O(l) → CO₂(g) + 8H⁺(aq) + 8e⁻;',1,1);
INSERT INTO rubric_criterion VALUES(10377,'chem34a1-fc-7',NULL,1,'cathode: O₂(g) + 4H⁺(aq) + 4e⁻ → 2H₂O(l) (×2);',1,1);
INSERT INTO rubric_criterion VALUES(10378,'chem34a1-fc-7',NULL,2,'overall: CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(l).',1,1);
INSERT INTO rubric_criterion VALUES(10379,'chem34a1-fc-8',NULL,0,'H⁺ ions are produced at the anode (H₂ → 2H⁺ + 2e⁻) and consumed at the cathode (O₂ + 4H⁺ + 4e⁻ → 2H₂O), so they migrate through the electrolyte from anode to cathode;',1,1);
INSERT INTO rubric_criterion VALUES(10380,'chem34a1-fc-8',NULL,1,'this completes the circuit and maintains charge balance as electrons flow externally.',1,1);
INSERT INTO rubric_criterion VALUES(10387,'chem34a1-ghs-6',NULL,0,'Water is electrolysed using electricity from renewable sources such as solar or wind;',1,1);
INSERT INTO rubric_criterion VALUES(10388,'chem34a1-ghs-6',NULL,1,'2H₂O(l) → 2H₂(g) + O₂(g);',1,1);
INSERT INTO rubric_criterion VALUES(10389,'chem34a1-ghs-6',NULL,2,'the process uses renewable energy and an abundant feedstock (water), produces no CO₂, and using the hydrogen in a fuel cell regenerates water, so the cycle does not deplete resources or add greenhouse gases.',1,1);
INSERT INTO rubric_criterion VALUES(10390,'chem34a1-ghs-7',NULL,0,'An energy source occurs naturally and can be harvested directly, e.g. solar energy from the Sun;',1,1);
INSERT INTO rubric_criterion VALUES(10391,'chem34a1-ghs-7',NULL,1,'an energy carrier stores and transports energy produced from a source, e.g. hydrogen must be manufactured (by electrolysis using solar power) and releases that energy later in a fuel cell.',1,1);
INSERT INTO rubric_criterion VALUES(10392,'chem34a1-ghs-8',NULL,0,'Blue hydrogen lowers CO₂ emissions compared with grey hydrogen because much of the CO₂ is captured and stored underground;',1,1);
INSERT INTO rubric_criterion VALUES(10393,'chem34a1-ghs-8',NULL,1,'however, it still relies on a finite fossil fuel (natural gas), capture is not 100% efficient and methane leaks during extraction add greenhouse gases;',1,1);
INSERT INTO rubric_criterion VALUES(10394,'chem34a1-ghs-8',NULL,2,'therefore it is less sustainable than green hydrogen, though it may be a transitional option while renewable capacity grows.',1,1);
INSERT INTO rubric_criterion VALUES(10401,'chem34a2-phys-6',NULL,0,'The two molecules have similar molar masses, so their dispersion forces are of similar strength;',1,1);
INSERT INTO rubric_criterion VALUES(10402,'chem34a2-phys-6',NULL,1,'ethanol has an –OH group (H bonded to highly electronegative O), so hydrogen bonds form between ethanol molecules;',1,1);
INSERT INTO rubric_criterion VALUES(10403,'chem34a2-phys-6',NULL,2,'propane is non-polar with only dispersion forces, so much less energy is needed to separate its molecules, giving a much lower boiling point.',1,1);
INSERT INTO rubric_criterion VALUES(10404,'chem34a2-phys-7',NULL,0,'Propanoic acid has an O–H group, so it can form hydrogen bonds between its molecules (including dimers);',1,1);
INSERT INTO rubric_criterion VALUES(10405,'chem34a2-phys-7',NULL,1,'methyl ethanoate has no H atom bonded to O, so it cannot form hydrogen bonds between its own molecules and has only weaker dipole–dipole and dispersion forces, which need less energy to overcome.',1,1);
INSERT INTO rubric_criterion VALUES(10406,'chem34a2-phys-8',NULL,0,'Both the amine (N–H) and the alcohol (O–H) can form hydrogen bonds between molecules, whereas butane has only dispersion forces, so they boil higher;',1,1);
INSERT INTO rubric_criterion VALUES(10407,'chem34a2-phys-8',NULL,1,'N is less electronegative than O, so the N–H bond is less polar and the hydrogen bonds in the amine are weaker;',1,1);
INSERT INTO rubric_criterion VALUES(10408,'chem34a2-phys-8',NULL,2,'therefore less energy is needed to separate amine molecules than alcohol molecules.',1,1);
INSERT INTO rubric_criterion VALUES(10415,'psych34a1-div-6',NULL,0,'CNS consists of the brain and spinal cord and processes information and coordinates responses; PNS consists of all the nerves outside the brain and spinal cord (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10416,'psych34a1-div-6',NULL,1,'spinal nerves, cranial nerves) and carries messages between the CNS and the rest of the body; any correct component of each (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10417,'psych34a1-div-6',NULL,2,'brain / somatic nervous system).',1,1);
INSERT INTO rubric_criterion VALUES(10418,'psych34a1-div-7',NULL,0,'The autonomic nervous system controls involuntary functions of internal organs and glands; the sympathetic nervous system arouses the body in response to a threat, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10419,'psych34a1-div-7',NULL,1,'increases heart rate; the parasympathetic nervous system calms the body and returns it to homeostasis, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10420,'psych34a1-div-7',NULL,2,'decreases heart rate back to normal.',1,1);
INSERT INTO rubric_criterion VALUES(10421,'psych34a1-div-8',NULL,0,'(a) Somatic nervous system; motor neurons carried a command to skeletal muscles in his arm to move it voluntarily/consciously (or by reflex via the spinal cord);',1,1);
INSERT INTO rubric_criterion VALUES(10422,'psych34a1-div-8',NULL,1,'sensory neurons carried the pain message to the CNS;',1,1);
INSERT INTO rubric_criterion VALUES(10423,'psych34a1-div-8',NULL,2,'(b) Autonomic nervous system, specifically the sympathetic nervous system;',1,1);
INSERT INTO rubric_criterion VALUES(10424,'psych34a1-div-8',NULL,3,'the involuntary increase in heart rate is an arousal response to a perceived threat.',1,1);
INSERT INTO rubric_criterion VALUES(10431,'psych34a1-con-6',NULL,0,'A spinal reflex is an unconscious, automatic and involuntary response to a stimulus;',1,1);
INSERT INTO rubric_criterion VALUES(10432,'psych34a1-con-6',NULL,1,'the sensory neuron sends the message to the spinal cord where it is passed via an interneuron to a motor neuron that triggers the muscle;',1,1);
INSERT INTO rubric_criterion VALUES(10433,'psych34a1-con-6',NULL,2,'the brain is not required to process the message, so it occurs before awareness of the stimulus is registered.',1,1);
INSERT INTO rubric_criterion VALUES(10434,'psych34a1-con-7',NULL,0,'Conscious responses involve awareness and voluntary control with the brain processing information, so are slower, e.g. deciding to catch a ball;',1,1);
INSERT INTO rubric_criterion VALUES(10435,'psych34a1-con-7',NULL,1,'unconscious responses occur automatically without awareness or brain-based decision making, so are usually faster, e.g. withdrawing a hand from a sharp object via spinal reflex;',1,1);
INSERT INTO rubric_criterion VALUES(10436,'psych34a1-con-7',NULL,2,'correct example of each given;',1,1);
INSERT INTO rubric_criterion VALUES(10437,'psych34a1-con-7',NULL,3,'comparison of both speed and brain involvement.',1,1);
INSERT INTO rubric_criterion VALUES(10438,'psych34a1-con-8',NULL,0,'Unconscious spinal reflex;',1,1);
INSERT INTO rubric_criterion VALUES(10439,'psych34a1-con-8',NULL,1,'sensory neuron detects the stretch and sends a message to the spinal cord, then via an interneuron to a motor neuron that causes the thigh muscle to contract;',1,1);
INSERT INTO rubric_criterion VALUES(10440,'psych34a1-con-8',NULL,2,'the response is processed at the spinal cord without the brain deciding;',1,1);
INSERT INTO rubric_criterion VALUES(10441,'psych34a1-con-8',NULL,3,'it is involuntary and occurs too quickly for conscious control to intervene.',1,1);
INSERT INTO rubric_criterion VALUES(10448,'psych34a1-ntm-6',NULL,0,'Excitatory neurotransmitters increase the likelihood that the postsynaptic neuron will fire an action potential, e.g. glutamate;',1,1);
INSERT INTO rubric_criterion VALUES(10449,'psych34a1-ntm-6',NULL,1,'inhibitory neurotransmitters decrease the likelihood that the postsynaptic neuron will fire, e.g. GABA;',1,1);
INSERT INTO rubric_criterion VALUES(10450,'psych34a1-ntm-6',NULL,2,'both bind to receptor sites on the postsynaptic neuron.',1,1);
INSERT INTO rubric_criterion VALUES(10451,'psych34a1-ntm-7',NULL,0,'An action potential arrives at the axon terminal of the presynaptic neuron;',1,1);
INSERT INTO rubric_criterion VALUES(10452,'psych34a1-ntm-7',NULL,1,'vesicles release neurotransmitter into the synaptic gap;',1,1);
INSERT INTO rubric_criterion VALUES(10453,'psych34a1-ntm-7',NULL,2,'neurotransmitter diffuses across the gap and binds to complementary receptor sites on the postsynaptic neuron;',1,1);
INSERT INTO rubric_criterion VALUES(10454,'psych34a1-ntm-7',NULL,3,'this has an excitatory or inhibitory effect on the postsynaptic neuron, making it more or less likely to fire.',1,1);
INSERT INTO rubric_criterion VALUES(10455,'psych34a1-ntm-8',NULL,0,'Glutamate is a neurotransmitter that directly acts at the synapse to excite the postsynaptic neuron;',1,1);
INSERT INTO rubric_criterion VALUES(10456,'psych34a1-ntm-8',NULL,1,'a neuromodulator such as dopamine does not by itself simply transmit the signal but influences/regulates the effect of neurotransmitters;',1,1);
INSERT INTO rubric_criterion VALUES(10457,'psych34a1-ntm-8',NULL,2,'it can change the sensitivity or responsiveness of neurons, often over many neurons at once, thereby adjusting the strength of neural communication.',1,1);
INSERT INTO rubric_criterion VALUES(10464,'psych34a1-ltp-6',NULL,0,'LTP is a long-lasting increase in the strength of synaptic transmission between neurons following repeated stimulation;',1,1);
INSERT INTO rubric_criterion VALUES(10465,'psych34a1-ltp-6',NULL,1,'it makes it easier for the presynaptic neuron to trigger the postsynaptic neuron;',1,1);
INSERT INTO rubric_criterion VALUES(10466,'psych34a1-ltp-6',NULL,2,'it is a cellular basis of learning and memory because strengthened pathways support retention of new information.',1,1);
INSERT INTO rubric_criterion VALUES(10467,'psych34a1-ltp-7',NULL,0,'Glutamate is released from the presynaptic neuron into the synapse and binds to receptors on the postsynaptic neuron; repeated stimulation leads to more/stronger receptor activity (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10468,'psych34a1-ltp-7',NULL,1,'more receptors on the postsynaptic membrane) so the postsynaptic neuron responds more strongly;',1,1);
INSERT INTO rubric_criterion VALUES(10469,'psych34a1-ltp-7',NULL,2,'this strengthens the synapse, producing LTP.',1,1);
INSERT INTO rubric_criterion VALUES(10470,'psych34a1-ltp-8',NULL,0,'LTP strengthens synaptic connections after high-frequency/repeated activity;',1,1);
INSERT INTO rubric_criterion VALUES(10471,'psych34a1-ltp-8',NULL,1,'LTD weakens synaptic connections after low-frequency/infrequent activity;',1,1);
INSERT INTO rubric_criterion VALUES(10472,'psych34a1-ltp-8',NULL,2,'LTP supports the formation and consolidation of memories;',1,1);
INSERT INTO rubric_criterion VALUES(10473,'psych34a1-ltp-8',NULL,3,'LTD removes or weakens unused or unnecessary connections, which refines neural circuits and allows flexibility in learning.',1,1);
INSERT INTO rubric_criterion VALUES(10480,'psych34a1-gas-6',NULL,0,'Alarm reaction is the initial response to a stressor; shock phase: the body''s resistance temporarily drops (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10481,'psych34a1-gas-6',NULL,1,'decreased heart rate and blood pressure) as it perceives the stressor;',1,1);
INSERT INTO rubric_criterion VALUES(10482,'psych34a1-gas-6',NULL,2,'counter-shock phase: the sympathetic nervous system is activated, adrenaline and cortisol are released, increasing heart rate and mobilising energy for fight-flight-freeze.',1,1);
INSERT INTO rubric_criterion VALUES(10483,'psych34a1-gas-7',NULL,0,'Adrenaline is released rapidly by the adrenal medulla and produces immediate effects such as increased heart rate and blood flow;',1,1);
INSERT INTO rubric_criterion VALUES(10484,'psych34a1-gas-7',NULL,1,'cortisol is released more slowly by the adrenal cortex via the HPA axis and acts over a longer period, releasing glucose and maintaining energy supply;',1,1);
INSERT INTO rubric_criterion VALUES(10485,'psych34a1-gas-7',NULL,2,'prolonged high cortisol is associated with the resistance and exhaustion stages and negative health effects.',1,1);
INSERT INTO rubric_criterion VALUES(10486,'psych34a1-gas-8',NULL,0,'Her prolonged stress corresponds to the resistance stage, where she has been coping with elevated physiological arousal;',1,1);
INSERT INTO rubric_criterion VALUES(10487,'psych34a1-gas-8',NULL,1,'over time her bodily resources were depleted so she has entered the exhaustion stage;',1,1);
INSERT INTO rubric_criterion VALUES(10488,'psych34a1-gas-8',NULL,2,'in exhaustion, resistance to stress falls below normal and the immune system is weakened, explaining the frequent colds;',1,1);
INSERT INTO rubric_criterion VALUES(10489,'psych34a1-gas-8',NULL,3,'feeling drained reflects depleted energy resources from sustained cortisol and arousal.',1,1);
INSERT INTO rubric_criterion VALUES(10496,'psych34a1-tmc-6',NULL,0,'Primary appraisal is the initial evaluation of an event as irrelevant, benign-positive or stressful;',1,1);
INSERT INTO rubric_criterion VALUES(10497,'psych34a1-tmc-6',NULL,1,'secondary appraisal is the evaluation of one''s ability and resources to cope with the event;',1,1);
INSERT INTO rubric_criterion VALUES(10498,'psych34a1-tmc-6',NULL,2,'if resources are judged inadequate the situation is more likely to be experienced as stressful.',1,1);
INSERT INTO rubric_criterion VALUES(10499,'psych34a1-tmc-7',NULL,0,'Primary appraisal: she judges the presentation as stressful (a challenge/threat) because it is relevant to her wellbeing;',1,1);
INSERT INTO rubric_criterion VALUES(10500,'psych34a1-tmc-7',NULL,1,'secondary appraisal: she assesses her coping resources positively (past experience, time to practise);',1,1);
INSERT INTO rubric_criterion VALUES(10501,'psych34a1-tmc-7',NULL,2,'because she believes she can cope, she is likely to experience it as a challenge, leading to lower stress;',1,1);
INSERT INTO rubric_criterion VALUES(10502,'psych34a1-tmc-7',NULL,3,'coping strategies are chosen in response.',1,1);
INSERT INTO rubric_criterion VALUES(10503,'psych34a1-tmc-8',NULL,0,'Strength: it recognises individual differences in appraisal so explains why the same event is stressful for one person but not another (and links to coping choices);',1,1);
INSERT INTO rubric_criterion VALUES(10504,'psych34a1-tmc-8',NULL,1,'limitation: it focuses on cognitive appraisal and may underplay physiological aspects of stress or the role of objective stressor severity;',1,1);
INSERT INTO rubric_criterion VALUES(10505,'psych34a1-tmc-8',NULL,2,'appraisal is difficult to measure objectively and relies on self-report.',1,1);
INSERT INTO rubric_criterion VALUES(10512,'psych34a1-gba-6',NULL,0,'Signals travel from the brain to the gut (e.g. stress altering digestion);',1,1);
INSERT INTO rubric_criterion VALUES(10513,'psych34a1-gba-6',NULL,1,'and signals also travel from the gut to the brain (e.g. gut microbiota and gut-produced chemicals influencing mood and stress response).',1,1);
INSERT INTO rubric_criterion VALUES(10514,'psych34a1-gba-7',NULL,0,'Gut microbiota are the community of microorganisms living in the gut;',1,1);
INSERT INTO rubric_criterion VALUES(10515,'psych34a1-gba-7',NULL,1,'they influence the production of neurotransmitters such as serotonin and other signalling chemicals;',1,1);
INSERT INTO rubric_criterion VALUES(10516,'psych34a1-gba-7',NULL,2,'these signals reach the brain via the vagus nerve, immune and hormonal pathways and so can influence mood, stress responses and behaviour.',1,1);
INSERT INTO rubric_criterion VALUES(10517,'psych34a1-gba-8',NULL,0,'Probiotics may alter the composition of gut microbiota, changing production of neurotransmitters (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10518,'psych34a1-gba-8',NULL,1,'serotonin) and signalling to the brain via the vagus nerve, which could reduce stress and anxiety;',1,1);
INSERT INTO rubric_criterion VALUES(10519,'psych34a1-gba-8',NULL,2,'limitation: stress and anxiety were self-reported so subject to bias (or small sample, other lifestyle variables not controlled, placebo effect);',1,1);
INSERT INTO rubric_criterion VALUES(10520,'psych34a1-gba-8',NULL,3,'a link is not enough to prove the probiotic alone caused the change, and the mechanism was not measured directly.',1,1);
INSERT INTO rubric_criterion VALUES(10527,'psych34a1-cop-6',NULL,0,'Approach coping involves confronting or dealing directly with the stressor, e.g. making a plan or seeking social support;',1,1);
INSERT INTO rubric_criterion VALUES(10528,'psych34a1-cop-6',NULL,1,'avoidance coping involves evading, ignoring or withdrawing from the stressor, e.g. distraction or procrastinating;',1,1);
INSERT INTO rubric_criterion VALUES(10529,'psych34a1-cop-6',NULL,2,'correct example of each.',1,1);
INSERT INTO rubric_criterion VALUES(10530,'psych34a1-cop-7',NULL,0,'A coping strategy''s effectiveness depends on the situation and the stressor; a strategy may be adaptive in one context and maladaptive in another;',1,1);
INSERT INTO rubric_criterion VALUES(10531,'psych34a1-cop-7',NULL,1,'example: avoidance such as distraction may help short-term with an uncontrollable situation (e.g. waiting for medical results) but be ineffective for a controllable one (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10532,'psych34a1-cop-7',NULL,2,'an upcoming assignment) where an approach strategy such as planning is more effective.',1,1);
INSERT INTO rubric_criterion VALUES(10533,'psych34a1-cop-8',NULL,0,'Coping flexibility is the ability to adapt or switch coping strategies according to the changing demands of the stressor/context and whether the current strategy is working; it is beneficial because it allows the person to choose the most appropriate strategy, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10534,'psych34a1-cop-8',NULL,1,'approach when the stressor is controllable and avoidance when it is not;',1,1);
INSERT INTO rubric_criterion VALUES(10535,'psych34a1-cop-8',NULL,2,'this leads to more effective stress management and better psychological wellbeing.',1,1);
INSERT INTO rubric_criterion VALUES(10542,'psych34a1-cc-6',NULL,0,'NS (before conditioning): the school bell;',1,1);
INSERT INTO rubric_criterion VALUES(10543,'psych34a1-cc-6',NULL,1,'UCS: the free lunch/food;',1,1);
INSERT INTO rubric_criterion VALUES(10544,'psych34a1-cc-6',NULL,2,'UCR: salivation in response to the food;',1,1);
INSERT INTO rubric_criterion VALUES(10545,'psych34a1-cc-6',NULL,3,'CS (after conditioning): the school bell;',1,1);
INSERT INTO rubric_criterion VALUES(10546,'psych34a1-cc-6',NULL,4,'CR: salivation in response to the bell alone.',1,1);
INSERT INTO rubric_criterion VALUES(10547,'psych34a1-cc-7',NULL,0,'Acquisition is the stage during which the association between the NS and UCS is formed; the NS is repeatedly paired with the UCS;',1,1);
INSERT INTO rubric_criterion VALUES(10548,'psych34a1-cc-7',NULL,1,'learning is most effective when the NS is presented just before/slightly before the UCS (contiguity);',1,1);
INSERT INTO rubric_criterion VALUES(10549,'psych34a1-cc-7',NULL,2,'once the NS elicits the response alone it becomes the CS and the response becomes the CR.',1,1);
INSERT INTO rubric_criterion VALUES(10550,'psych34a1-cc-8',NULL,0,'Spontaneous recovery;',1,1);
INSERT INTO rubric_criterion VALUES(10551,'psych34a1-cc-8',NULL,1,'the reappearance of a previously extinguished CR after a rest period without further pairing;',1,1);
INSERT INTO rubric_criterion VALUES(10552,'psych34a1-cc-8',NULL,2,'suggests extinction does not completely erase the learned association, it is suppressed, and the CR is usually weaker than at acquisition.',1,1);
INSERT INTO rubric_criterion VALUES(10559,'psych34a1-oc-6',NULL,0,'Antecedent: play time finishes (or being asked to tidy up);',1,1);
INSERT INTO rubric_criterion VALUES(10560,'psych34a1-oc-6',NULL,1,'behaviour: she puts her toys away;',1,1);
INSERT INTO rubric_criterion VALUES(10561,'psych34a1-oc-6',NULL,2,'consequence: she receives a sticker (positive reinforcement);',1,1);
INSERT INTO rubric_criterion VALUES(10562,'psych34a1-oc-6',NULL,3,'effect: the behaviour is more likely to be repeated in the future.',1,1);
INSERT INTO rubric_criterion VALUES(10563,'psych34a1-oc-7',NULL,0,'Positive reinforcement is the addition of a pleasant stimulus after a behaviour, increasing the likelihood of the behaviour, e.g. a dog receives a treat for sitting;',1,1);
INSERT INTO rubric_criterion VALUES(10564,'psych34a1-oc-7',NULL,1,'negative reinforcement is the removal of an unpleasant stimulus after a behaviour, also increasing the likelihood of the behaviour, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10565,'psych34a1-oc-7',NULL,2,'taking painkillers to remove a headache;',1,1);
INSERT INTO rubric_criterion VALUES(10566,'psych34a1-oc-7',NULL,3,'both increase behaviour, differing in whether a stimulus is added or removed.',1,1);
INSERT INTO rubric_criterion VALUES(10567,'psych34a1-oc-8',NULL,0,'Reasons (any two): punishment may not be delivered consistently or immediately after the behaviour; the student may find detention not aversive or may gain attention from it (which could reinforce the behaviour);',1,1);
INSERT INTO rubric_criterion VALUES(10568,'psych34a1-oc-8',NULL,1,'punishment shows what not to do rather than what to do; alternative: use positive reinforcement, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10569,'psych34a1-oc-8',NULL,2,'praise or reward for arriving on time.',1,1);
INSERT INTO rubric_criterion VALUES(10576,'psych34a1-obs-6',NULL,0,'Attention: the observer pays attention to the model''s behaviour;',1,1);
INSERT INTO rubric_criterion VALUES(10577,'psych34a1-obs-6',NULL,1,'retention: the observer stores the behaviour in memory;',1,1);
INSERT INTO rubric_criterion VALUES(10578,'psych34a1-obs-6',NULL,2,'reproduction: the observer is physically able to replicate the behaviour;',1,1);
INSERT INTO rubric_criterion VALUES(10579,'psych34a1-obs-6',NULL,3,'motivation: the observer has a reason or desire to perform the behaviour;',1,1);
INSERT INTO rubric_criterion VALUES(10580,'psych34a1-obs-6',NULL,4,'reinforcement: the observer is reinforced (directly or vicariously) or expects reinforcement, making the behaviour more likely to be repeated.',1,1);
INSERT INTO rubric_criterion VALUES(10581,'psych34a1-obs-7',NULL,0,'Children observed an adult model behaving aggressively toward an inflatable Bobo doll (or non-aggressively in a control condition);',1,1);
INSERT INTO rubric_criterion VALUES(10582,'psych34a1-obs-7',NULL,1,'when later placed in a room with the doll, children who had seen aggression imitated the same aggressive acts;',1,1);
INSERT INTO rubric_criterion VALUES(10583,'psych34a1-obs-7',NULL,2,'this showed behaviour can be learned by observation without direct reinforcement.',1,1);
INSERT INTO rubric_criterion VALUES(10584,'psych34a1-obs-8',NULL,0,'Attention: Lena watched and focused on the baker''s technique;',1,1);
INSERT INTO rubric_criterion VALUES(10585,'psych34a1-obs-8',NULL,1,'reproduction: Lena tries to physically replicate the behaviour from memory;',1,1);
INSERT INTO rubric_criterion VALUES(10586,'psych34a1-obs-8',NULL,2,'reproduction may have failed because she lacks the motor skill or practice, or her retention of the details was incomplete;',1,1);
INSERT INTO rubric_criterion VALUES(10587,'psych34a1-obs-8',NULL,3,'with more practice and feedback her reproduction can improve.',1,1);
INSERT INTO rubric_criterion VALUES(10594,'psych34a2-atsi-6',NULL,0,'1 mark for a feature of Country-based learning (e.g. knowledge, story or law is linked to specific places/landmarks; songlines);',1,1);
INSERT INTO rubric_criterion VALUES(10595,'psych34a2-atsi-6',NULL,1,'1 mark for explaining how it supports memory (e.g. landmarks act as retrieval cues, linking information to place and sequence makes it easier to recall, learning in context).',1,1);
INSERT INTO rubric_criterion VALUES(10596,'psych34a2-atsi-7',NULL,0,'Any two strategies, each with an explanation, 1 mark for strategy and 1 mark for explanation: invite a local Elder or community member to share stories (learning from Elders in a community context, knowledge held in oral stories, relevant and respectful);',1,1);
INSERT INTO rubric_criterion VALUES(10597,'psych34a2-atsi-7',NULL,1,'take learning outdoors onto Country (links knowledge to place, landmarks as retrieval cues, multisensory);',1,1);
INSERT INTO rubric_criterion VALUES(10598,'psych34a2-atsi-7',NULL,2,'use storytelling, art, song or dance to represent events (multisensory, emotional, shared and repeated);',1,1);
INSERT INTO rubric_criterion VALUES(10599,'psych34a2-atsi-7',NULL,3,'learning through observation and practice in small groups (collaborative, social learning).',1,1);
INSERT INTO rubric_criterion VALUES(10600,'psych34a2-atsi-8',NULL,0,'Information is encoded in song, story and rhythm, which gives structure and aids retrieval;',1,1);
INSERT INTO rubric_criterion VALUES(10601,'psych34a2-atsi-8',NULL,1,'the knowledge is linked to physical landmarks on Country, which act as cues and give a sequence;',1,1);
INSERT INTO rubric_criterion VALUES(10602,'psych34a2-atsi-8',NULL,2,'it is repeated, rehearsed and passed on through the community and Elders with shared responsibility, so it is maintained and checked across generations (also acceptable: multisensory and emotional meaning).',1,1);
INSERT INTO rubric_criterion VALUES(10609,'psych34a2-asm-6',NULL,0,'Iconic memory is the sensory memory for visual information; duration is a fraction of a second (about 0.2 to 0.4 seconds);',1,1);
INSERT INTO rubric_criterion VALUES(10610,'psych34a2-asm-6',NULL,1,'echoic memory is the sensory memory for auditory information;',1,1);
INSERT INTO rubric_criterion VALUES(10611,'psych34a2-asm-6',NULL,2,'duration about 3 to 4 seconds.',1,1);
INSERT INTO rubric_criterion VALUES(10612,'psych34a2-asm-7',NULL,0,'She must attend to the number so it moves from sensory memory to short-term memory (1);',1,1);
INSERT INTO rubric_criterion VALUES(10613,'psych34a2-asm-7',NULL,1,'she needs to rehearse it (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10614,'psych34a2-asm-7',NULL,2,'maintenance or elaborative rehearsal) so it is transferred to long-term memory (1 to 2 marks for explaining rehearsal and transfer to LTM);',1,1);
INSERT INTO rubric_criterion VALUES(10615,'psych34a2-asm-7',NULL,3,'if interrupted, the number will not be rehearsed and will be lost from STM within about 12 to 30 seconds through decay or displacement, so it is not transferred to LTM (1).',1,1);
INSERT INTO rubric_criterion VALUES(10616,'psych34a2-asm-8',NULL,0,'Serial position effect: better recall of items at the start (primacy) and end (recency) of a list than the middle; primacy is explained by early items being rehearsed and transferred to LTM;',1,1);
INSERT INTO rubric_criterion VALUES(10617,'psych34a2-asm-8',NULL,1,'recency is explained by the last items still being held in STM;',1,1);
INSERT INTO rubric_criterion VALUES(10618,'psych34a2-asm-8',NULL,2,'the middle items are lost because they are displaced from STM before they are rehearsed enough to enter LTM, which supports the existence of two stores.',1,1);
INSERT INTO rubric_criterion VALUES(10625,'psych34a2-eim-6',NULL,0,'Episodic memory (1) with a suitable example, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10626,'psych34a2-eim-6',NULL,1,'remembering your 10th birthday party or what you did yesterday (1);',1,1);
INSERT INTO rubric_criterion VALUES(10627,'psych34a2-eim-6',NULL,2,'semantic memory (1) with a suitable example, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10628,'psych34a2-eim-6',NULL,3,'knowing that Canberra is the capital of Australia (1).',1,1);
INSERT INTO rubric_criterion VALUES(10629,'psych34a2-eim-7',NULL,0,'Procedural (implicit) memory (1) because he can perform the skill without conscious recall of how (1);',1,1);
INSERT INTO rubric_criterion VALUES(10630,'psych34a2-eim-7',NULL,1,'episodic (explicit) memory failure/absence (1) because he cannot consciously recall the specific time and place of the learning (1).',1,1);
INSERT INTO rubric_criterion VALUES(10631,'psych34a2-eim-7',NULL,2,'(Also acceptable: contrast between implicit retained and explicit lost.)',2,1);
INSERT INTO rubric_criterion VALUES(10632,'psych34a2-eim-8',NULL,0,'Explicit and implicit memories are stored and processed separately, involving different brain regions; the person''s explicit memory system (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10633,'psych34a2-eim-8',NULL,1,'hippocampus) is damaged, preventing formation of new conscious memories; implicit procedural memory (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10634,'psych34a2-eim-8',NULL,2,'involving the cerebellum) remains intact so the skill improves with practice even though they cannot recall the practice sessions.',1,1);
INSERT INTO rubric_criterion VALUES(10641,'psych34a2-brm-6',NULL,0,'Hippocampus: involved in the encoding and consolidation of new explicit (episodic and semantic) memories, which are then stored in the neocortex (1 to 2 marks);',1,1);
INSERT INTO rubric_criterion VALUES(10642,'psych34a2-brm-6',NULL,1,'cerebellum: involved in the formation and storage of implicit memories such as procedural memory (motor skills) and classically conditioned responses (1 mark).',2,1);
INSERT INTO rubric_criterion VALUES(10643,'psych34a2-brm-7',NULL,0,'Childhood memories were already consolidated and are stored in the neocortex, so remain accessible (1);',1,1);
INSERT INTO rubric_criterion VALUES(10644,'psych34a2-brm-7',NULL,1,'damaged hippocampus prevents consolidation of new explicit (episodic) memories, so recent conversations are not recalled (1 to 2);',1,1);
INSERT INTO rubric_criterion VALUES(10645,'psych34a2-brm-7',NULL,2,'learning a sport is implicit procedural memory, involving the cerebellum, which is intact (1).',2,1);
INSERT INTO rubric_criterion VALUES(10646,'psych34a2-brm-8',NULL,0,'The hippocampus encodes and consolidates the explicit details of the event, such as where and when it happened (1);',1,1);
INSERT INTO rubric_criterion VALUES(10647,'psych34a2-brm-8',NULL,1,'the amygdala processes the emotional significance (fear) and enhances the strength of consolidation (1);',1,1);
INSERT INTO rubric_criterion VALUES(10648,'psych34a2-brm-8',NULL,2,'together the memory is stronger and more vivid, with emotional response and factual details linked (1).',1,1);
INSERT INTO rubric_criterion VALUES(10655,'psych34a2-ama-6',NULL,0,'Autobiographical memory is memory of events and information about one''s own life (1);',1,1);
INSERT INTO rubric_criterion VALUES(10656,'psych34a2-ama-6',NULL,1,'it draws on episodic memory (personal events and experiences) (1) and semantic memory (personal facts, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10657,'psych34a2-ama-6',NULL,2,'where you went to school) (1).',1,1);
INSERT INTO rubric_criterion VALUES(10658,'psych34a2-ama-7',NULL,0,'Imagery contributes to the vividness and sensory richness of recalled events (1);',1,1);
INSERT INTO rubric_criterion VALUES(10659,'psych34a2-ama-7',NULL,1,'factual (semantic/episodic) information can be retrieved without imagery (1);',1,1);
INSERT INTO rubric_criterion VALUES(10660,'psych34a2-ama-7',NULL,2,'so imagery is not necessary for the retrieval of autobiographical information, but it influences the quality or detail of recollection (1).',1,1);
INSERT INTO rubric_criterion VALUES(10661,'psych34a2-ama-8',NULL,0,'Limitation (1): imagery is subjective, so people may differ in how they interpret or rate vividness, so responses may be unreliable or biased;',1,1);
INSERT INTO rubric_criterion VALUES(10662,'psych34a2-ama-8',NULL,1,'address (up to 2): use objective measures in addition, such as performance on tasks requiring imagery, physiological responses or comparing with brain imaging, or use standardised scales such as a validated vividness questionnaire and compare across a large sample.',2,1);
INSERT INTO rubric_criterion VALUES(10669,'psych34a2-alz-6',NULL,0,'Any two: formation of amyloid plaques between neurons (1); neurofibrillary tangles of tau protein within neurons (1); loss of neurons and synapses (1);',1,1);
INSERT INTO rubric_criterion VALUES(10670,'psych34a2-alz-6',NULL,1,'shrinkage (atrophy) of regions such as the hippocampus and neocortex (1); reduced levels of neurotransmitters such as acetylcholine (1).',1,1);
INSERT INTO rubric_criterion VALUES(10671,'psych34a2-alz-7',NULL,0,'Damage to the hippocampus affects consolidation of new explicit memories, so recent events and repeated questions are forgotten (1 to 2);',1,1);
INSERT INTO rubric_criterion VALUES(10672,'psych34a2-alz-7',NULL,1,'making tea is a procedural (implicit) memory, which is stored in regions such as the cerebellum that are affected later (1);',1,1);
INSERT INTO rubric_criterion VALUES(10673,'psych34a2-alz-7',NULL,2,'her wedding day is an old, consolidated episodic memory stored in the neocortex, which is initially less affected (1).',2,1);
INSERT INTO rubric_criterion VALUES(10674,'psych34a2-alz-8',NULL,0,'As neurons are lost, memory, language and reasoning decline, leading to difficulty with daily tasks such as managing money, cooking or self-care, and eventually needing full-time care (1 to 2);',1,1);
INSERT INTO rubric_criterion VALUES(10675,'psych34a2-alz-8',NULL,1,'family members may experience emotional, financial and physical strain as carers and may grieve as the person''s personality and ability to recognise them changes (1).',2,1);
INSERT INTO rubric_criterion VALUES(10682,'psych34a2-mne-6',NULL,0,'A mnemonic is a memory aid or technique used to improve encoding and retrieval of information, often by organising it or linking it to something familiar (1);',1,1);
INSERT INTO rubric_criterion VALUES(10683,'psych34a2-mne-6',NULL,1,'example: acronym, acrostic, method of loci or chunking, with a suitable example (1).',1,1);
INSERT INTO rubric_criterion VALUES(10684,'psych34a2-mne-7',NULL,0,'Choose a familiar route or place, e.g. walking through a house (1);',1,1);
INSERT INTO rubric_criterion VALUES(10685,'psych34a2-mne-7',NULL,1,'create a vivid image of each item and place it in a distinct location along the route in order (1 to 2);',1,1);
INSERT INTO rubric_criterion VALUES(10686,'psych34a2-mne-7',NULL,2,'at recall, mentally walk the route and retrieve each item from its location (1);',1,1);
INSERT INTO rubric_criterion VALUES(10687,'psych34a2-mne-7',NULL,3,'helps because locations provide retrieval cues and a sequence, and vivid imagery adds elaboration (1).',1,1);
INSERT INTO rubric_criterion VALUES(10688,'psych34a2-mne-8',NULL,0,'STM has a limited capacity of about 7 ± 2 items (1);',1,1);
INSERT INTO rubric_criterion VALUES(10689,'psych34a2-mne-8',NULL,1,'chunking groups individual items into larger meaningful units (1);',1,1);
INSERT INTO rubric_criterion VALUES(10690,'psych34a2-mne-8',NULL,2,'each chunk counts as one item, so more information can be held in STM and later transferred to LTM (1).',1,1);
INSERT INTO rubric_criterion VALUES(10697,'psych34a2-cms-6',NULL,0,'NWC is a state in which a person is alert and aware of their thoughts, feelings and surroundings and can respond in a coordinated way (1);',1,1);
INSERT INTO rubric_criterion VALUES(10698,'psych34a2-cms-6',NULL,1,'ASC is a state that differs from NWC in level of awareness, perception, attention or control (1);',1,1);
INSERT INTO rubric_criterion VALUES(10699,'psych34a2-cms-6',NULL,2,'example: sleep, daydreaming, meditation, or a drug-induced state (1).',1,1);
INSERT INTO rubric_criterion VALUES(10700,'psych34a2-cms-7',NULL,0,'EEG: records electrical activity of the brain; REM shows fast, low-amplitude, beta-like waves similar to wakefulness (1);',1,1);
INSERT INTO rubric_criterion VALUES(10701,'psych34a2-cms-7',NULL,1,'EOG: records eye movement; REM shows rapid eye movements (1);',1,1);
INSERT INTO rubric_criterion VALUES(10702,'psych34a2-cms-7',NULL,2,'EMG: records muscle activity; REM shows muscle paralysis/very low muscle tone (1);',1,1);
INSERT INTO rubric_criterion VALUES(10703,'psych34a2-cms-7',NULL,3,'one mark for linking at least two measures to the identification of REM (1).',1,1);
INSERT INTO rubric_criterion VALUES(10704,'psych34a2-cms-8',NULL,0,'Advantage (1): self-reports provide direct access to subjective experiences such as dream content and perceived sleep quality, which cannot be measured physiologically;',1,1);
INSERT INTO rubric_criterion VALUES(10705,'psych34a2-cms-8',NULL,1,'limitation (2): people may forget or distort what they experienced, may not accurately judge how long they slept, and responses may be influenced by social desirability, so data may be unreliable or inaccurate.',2,1);
INSERT INTO rubric_criterion VALUES(10712,'psych34a2-nrs-6',NULL,0,'Light sleep, transition between wakefulness and sleep (1);',1,1);
INSERT INTO rubric_criterion VALUES(10713,'psych34a2-nrs-6',NULL,1,'brain waves slow from alpha to theta, with slower heart rate and breathing, reduced muscle tone and possible hypnic jerks, slow rolling eye movements (1).',1,1);
INSERT INTO rubric_criterion VALUES(10714,'psych34a2-nrs-7',NULL,0,'Brain waves: REM is fast, low amplitude, similar to wakefulness; NREM 3 is slow, high amplitude delta waves (1);',1,1);
INSERT INTO rubric_criterion VALUES(10715,'psych34a2-nrs-7',NULL,1,'muscle tone: REM has paralysis (atonia) while NREM 3 has reduced but present muscle tone (1);',1,1);
INSERT INTO rubric_criterion VALUES(10716,'psych34a2-nrs-7',NULL,2,'ease of waking: REM is relatively easy to wake from (brain is active) while NREM 3 is hardest to wake from (1);',1,1);
INSERT INTO rubric_criterion VALUES(10717,'psych34a2-nrs-7',NULL,3,'one mark for correctly using comparative language or noting both stages for each criterion (1).',1,1);
INSERT INTO rubric_criterion VALUES(10718,'psych34a2-nrs-8',NULL,0,'A person does not go straight from stage 1 through to REM; the order is NREM 1, 2, 3 and back through 2 before REM (1);',1,1);
INSERT INTO rubric_criterion VALUES(10719,'psych34a2-nrs-8',NULL,1,'the cycle lasts about 90 minutes and repeats 4 to 5 times per night (1);',1,1);
INSERT INTO rubric_criterion VALUES(10720,'psych34a2-nrs-8',NULL,2,'the proportions change across the night, with more deep sleep early and longer REM later (1).',1,1);
INSERT INTO rubric_criterion VALUES(10727,'psych34a2-cur-6',NULL,0,'Circadian rhythm: a cycle of about 24 hours (1);',1,1);
INSERT INTO rubric_criterion VALUES(10728,'psych34a2-cur-6',NULL,1,'example: the sleep-wake cycle (1);',1,1);
INSERT INTO rubric_criterion VALUES(10729,'psych34a2-cur-6',NULL,2,'ultradian rhythm: a cycle shorter than 24 hours, occurring more than once a day (1);',1,1);
INSERT INTO rubric_criterion VALUES(10730,'psych34a2-cur-6',NULL,3,'example: the approximately 90-minute cycle of sleep stages (NREM and REM) (1).',1,1);
INSERT INTO rubric_criterion VALUES(10731,'psych34a2-cur-7',NULL,0,'The retina detects reduced light and sends signals to the SCN (1);',1,1);
INSERT INTO rubric_criterion VALUES(10732,'psych34a2-cur-7',NULL,1,'the SCN signals the pineal gland to increase melatonin secretion (1);',1,1);
INSERT INTO rubric_criterion VALUES(10733,'psych34a2-cur-7',NULL,2,'rising melatonin promotes sleepiness and lowers alertness, leading to sleep onset (1).',1,1);
INSERT INTO rubric_criterion VALUES(10734,'psych34a2-cur-8',NULL,0,'Her circadian rhythm is aligned to Melbourne time (1);',1,1);
INSERT INTO rubric_criterion VALUES(10735,'psych34a2-cur-8',NULL,1,'in London, the light-dark cycle and local times are different, so melatonin release and the body clock are out of sync with local time (1);',1,1);
INSERT INTO rubric_criterion VALUES(10736,'psych34a2-cur-8',NULL,2,'the SCN takes several days to adjust (resynchronise) to the new light cues, so she is sleepy during the day and alert at night (jet lag) (1).',1,1);
INSERT INTO rubric_criterion VALUES(10743,'psych34a2-sal-6',NULL,0,'Any two: newborns sleep more hours per day (about 14 to 17 hours versus 7 to 9 hours) (1); newborns spend a greater proportion of sleep in REM (about 50% versus 20 to 25%) (1);',1,1);
INSERT INTO rubric_criterion VALUES(10744,'psych34a2-sal-6',NULL,1,'newborns'' sleep is polyphasic (several short sleeps across 24 hours, no consolidated night sleep) and has shorter cycles (1).',1,1);
INSERT INTO rubric_criterion VALUES(10745,'psych34a2-sal-7',NULL,0,'Adolescents experience a delay in melatonin secretion due to a shift in circadian rhythm (1);',1,1);
INSERT INTO rubric_criterion VALUES(10746,'psych34a2-sal-7',NULL,1,'this results in sleep onset later at night and difficulty waking early (1);',1,1);
INSERT INTO rubric_criterion VALUES(10747,'psych34a2-sal-7',NULL,2,'adolescents need about 8 to 10 hours of sleep, so early starts reduce total sleep (1);',1,1);
INSERT INTO rubric_criterion VALUES(10748,'psych34a2-sal-7',NULL,3,'a later start would allow sleep to better match their biological rhythm and improve alertness and learning (1).',1,1);
INSERT INTO rubric_criterion VALUES(10749,'psych34a2-sal-8',NULL,0,'Any two changes (1 mark each): reduced time in deep NREM stage 3 sleep; more frequent awakenings and lighter sleep;',1,1);
INSERT INTO rubric_criterion VALUES(10750,'psych34a2-sal-8',NULL,1,'earlier sleep and wake times due to a shift in circadian rhythm;',1,1);
INSERT INTO rubric_criterion VALUES(10751,'psych34a2-sal-8',NULL,2,'plus 1 mark for an effect: sleep fragmentation can lead to daytime sleepiness, napping and reduced concentration or alertness.',1,1);
INSERT INTO rubric_criterion VALUES(10758,'psych34a3-sd-6',NULL,0,'Total sleep deprivation is no sleep at all for a period of time (e.g. staying awake all night to study / a 24-hour shift);',1,1);
INSERT INTO rubric_criterion VALUES(10759,'psych34a3-sd-6',NULL,1,'partial sleep deprivation is getting less sleep than needed, through restricted or fragmented sleep over one or more nights (e.g. sleeping five hours a night during exams);',1,1);
INSERT INTO rubric_criterion VALUES(10760,'psych34a3-sd-6',NULL,2,'the difference is complete absence of sleep versus reduced/disrupted sleep.',1,1);
INSERT INTO rubric_criterion VALUES(10761,'psych34a3-sd-7',NULL,0,'Behavioural: slowed reaction time, reduced coordination/motor performance, microsleeps leading to loss of control;',1,1);
INSERT INTO rubric_criterion VALUES(10762,'psych34a3-sd-7',NULL,1,'Cognitive: reduced attention/concentration, impaired decision-making and judgement;',1,1);
INSERT INTO rubric_criterion VALUES(10763,'psych34a3-sd-7',NULL,2,'Comparison: about 24 hours awake produces impairment comparable to a BAC of about 0.10%, above the legal driving limit of 0.05%;',1,1);
INSERT INTO rubric_criterion VALUES(10764,'psych34a3-sd-7',NULL,3,'so the driver is at greater risk of a crash.',1,1);
INSERT INTO rubric_criterion VALUES(10765,'psych34a3-sd-8',NULL,0,'Sleep deprivation has immediate effects on functioning, so performance during the day is already impaired (e.g. slowed reaction time, poor concentration, memory difficulty);',1,1);
INSERT INTO rubric_criterion VALUES(10766,'psych34a3-sd-8',NULL,1,'affective effects such as irritability and mood changes also occur before any recovery sleep;',1,1);
INSERT INTO rubric_criterion VALUES(10767,'psych34a3-sd-8',NULL,2,'the claim ignores these immediate costs, so it is not supported even if some recovery sleep occurs later.',1,1);
INSERT INTO rubric_criterion VALUES(10774,'psych34a3-crsd-6',NULL,0,'DSPD: a circadian rhythm sleep disorder where the sleep-wake cycle is delayed so the person cannot fall asleep until very late and wakes late / has difficulty waking at socially required times; effect: e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10775,'psych34a3-crsd-6',NULL,1,'daytime sleepiness at school due to partial sleep deprivation, reduced concentration or poorer performance, or irritability;',1,1);
INSERT INTO rubric_criterion VALUES(10776,'psych34a3-crsd-6',NULL,2,'the cause is a mismatch between the body clock and school schedule.',1,1);
INSERT INTO rubric_criterion VALUES(10777,'psych34a3-crsd-7',NULL,0,'Bright light therapy: exposure to bright light soon after waking suppresses melatonin and shifts the circadian rhythm earlier; so the person feels sleepy earlier at night;',1,1);
INSERT INTO rubric_criterion VALUES(10778,'psych34a3-crsd-7',NULL,1,'Melatonin: synthetic melatonin taken several hours before the desired bedtime (in the evening) acts like the natural darkness signal;',1,1);
INSERT INTO rubric_criterion VALUES(10779,'psych34a3-crsd-7',NULL,2,'promotes sleepiness and advances the sleep-wake cycle;',1,1);
INSERT INTO rubric_criterion VALUES(10780,'psych34a3-crsd-7',NULL,3,'timing is important as wrongly timed light or melatonin could shift the cycle in the wrong direction.',1,1);
INSERT INTO rubric_criterion VALUES(10781,'psych34a3-crsd-8',NULL,0,'Light is the main zeitgeber that entrains the circadian rhythm; daylight exposure signals wakefulness and suppresses melatonin, so during the day her body is cued to be alert;',1,1);
INSERT INTO rubric_criterion VALUES(10782,'psych34a3-crsd-8',NULL,1,'her night work conflicts with her body clock, so she is sleepy at work and has trouble sleeping in daytime (circadian misalignment);',1,1);
INSERT INTO rubric_criterion VALUES(10783,'psych34a3-crsd-8',NULL,2,'noise and social cues (zeitgebers) in daytime may also reduce sleep.',1,1);
INSERT INTO rubric_criterion VALUES(10790,'psych34a3-shz-6',NULL,0,'Sleep hygiene: habits and practices that promote good quality and sufficient sleep; e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10791,'psych34a3-shz-6',NULL,1,'avoid screens / bright light for an hour before bed; no caffeine in the afternoon or evening;',1,1);
INSERT INTO rubric_criterion VALUES(10792,'psych34a3-shz-6',NULL,2,'consistent sleep and wake times; a cool, dark, quiet bedroom.',1,1);
INSERT INTO rubric_criterion VALUES(10793,'psych34a3-shz-7',NULL,0,'Light is detected by the retina and signals the suprachiasmatic nucleus (the body clock) in the hypothalamus;',1,1);
INSERT INTO rubric_criterion VALUES(10794,'psych34a3-shz-7',NULL,1,'the SCN regulates the pineal gland''s secretion of melatonin: darkness increases melatonin and sleepiness, light suppresses it;',1,1);
INSERT INTO rubric_criterion VALUES(10795,'psych34a3-shz-7',NULL,2,'so regular light exposure keeps the circadian rhythm aligned with the 24-hour day.',1,1);
INSERT INTO rubric_criterion VALUES(10796,'psych34a3-shz-8',NULL,0,'His weekend schedule delays his exposure to morning light and other zeitgebers, shifting the circadian rhythm later;',1,1);
INSERT INTO rubric_criterion VALUES(10797,'psych34a3-shz-8',NULL,1,'on Monday his body clock is out of sync with the early school start, so he is sleepy and has difficulty waking;',1,1);
INSERT INTO rubric_criterion VALUES(10798,'psych34a3-shz-8',NULL,2,'solution: keep a consistent wake time and get morning light exposure (or avoid late-night light / screens);',1,1);
INSERT INTO rubric_criterion VALUES(10799,'psych34a3-shz-8',NULL,3,'this re-entrains the cycle and reduces social jet lag.',1,1);
INSERT INTO rubric_criterion VALUES(10806,'psych34a3-mw-6',NULL,0,'The continuum shows mental health ranging from good mental wellbeing/optimal functioning through mental health problems and mental disorder to severe mental illness; position changes with internal factors (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10807,'psych34a3-mw-6',NULL,1,'coping, biological state) and external factors (e.g. stressors, social support, treatment);',1,1);
INSERT INTO rubric_criterion VALUES(10808,'psych34a3-mw-6',NULL,2,'so someone can move toward either end over time.',1,1);
INSERT INTO rubric_criterion VALUES(10809,'psych34a3-mw-7',NULL,0,'Mental wellbeing: a positive state of functioning in which a person can cope, realise abilities and contribute (e.g. a student who copes with exams and maintains friendships);',1,1);
INSERT INTO rubric_criterion VALUES(10810,'psych34a3-mw-7',NULL,1,'mental illness: a diagnosable condition involving significant distress and impairment (e.g. major depressive disorder);',1,1);
INSERT INTO rubric_criterion VALUES(10811,'psych34a3-mw-7',NULL,2,'wellbeing is not just the absence of illness, and illness is more severe and persistent.',1,1);
INSERT INTO rubric_criterion VALUES(10812,'psych34a3-mw-8',NULL,0,'He has moved from the mentally healthy end toward a mental health problem due to external factors (job loss, reduced social support) which strained his coping;',1,1);
INSERT INTO rubric_criterion VALUES(10813,'psych34a3-mw-8',NULL,1,'he is not necessarily a mental disorder unless criteria are met;',1,1);
INSERT INTO rubric_criterion VALUES(10814,'psych34a3-mw-8',NULL,2,'moving back could involve new employment, rebuilding social connections and developing coping strategies/seeking professional help.',1,1);
INSERT INTO rubric_criterion VALUES(10821,'psych34a3-sew-6',NULL,0,'SEWB is a holistic, multidimensional concept of health where an individual''s wellbeing is linked to their connections to others, culture and land; and not just absence of illness; two domains from: body, mind and emotions;',1,1);
INSERT INTO rubric_criterion VALUES(10822,'psych34a3-sew-6',NULL,1,'family and kinship; community; culture;',1,1);
INSERT INTO rubric_criterion VALUES(10823,'psych34a3-sew-6',NULL,2,'Country; spirituality and ancestors.',1,1);
INSERT INTO rubric_criterion VALUES(10824,'psych34a3-sew-7',NULL,0,'Connection to Country and culture is part of identity and belonging in SEWB; its loss (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10825,'psych34a3-sew-7',NULL,1,'through displacement or disconnection from community) may reduce sense of identity, spiritual connection and support; so could lead to lowered self-esteem, isolation and increased risk of a mental health problem;',1,1);
INSERT INTO rubric_criterion VALUES(10826,'psych34a3-sew-7',NULL,2,'the domains are interrelated, so a loss in one affects others.',1,1);
INSERT INTO rubric_criterion VALUES(10827,'psych34a3-sew-8',NULL,0,'Strategy 1: run programs led by elders/community members that include cultural activities (e.g. language, ceremony, art);',1,1);
INSERT INTO rubric_criterion VALUES(10828,'psych34a3-sew-8',NULL,1,'justification: strengthens connection to culture and community; Strategy 2: Country-based programs such as caring for Country or on-Country camps;',1,1);
INSERT INTO rubric_criterion VALUES(10829,'psych34a3-sew-8',NULL,2,'justification: strengthens connection to Country and spirituality/ancestors; other valid: family and kinship support groups;',1,1);
INSERT INTO rubric_criterion VALUES(10830,'psych34a3-sew-8',NULL,3,'services should be culturally safe and community-controlled.',1,1);
INSERT INTO rubric_criterion VALUES(10837,'psych34a3-sp-6',NULL,0,'Biological: dysfunction in GABA reduces inhibition of fear response / LTP strengthens the fear memory pathway;',1,1);
INSERT INTO rubric_criterion VALUES(10838,'psych34a3-sp-6',NULL,1,'Psychological: a frightening experience of turbulence classically conditions fear of flying (flight = CS), or avoidance reinforces fear (negative reinforcement);',1,1);
INSERT INTO rubric_criterion VALUES(10839,'psych34a3-sp-6',NULL,2,'Social: seeing a family member or media coverage showing fear of air travel (observational learning);',1,1);
INSERT INTO rubric_criterion VALUES(10840,'psych34a3-sp-6',NULL,3,'overall these factors interact.',1,1);
INSERT INTO rubric_criterion VALUES(10841,'psych34a3-sp-7',NULL,0,'UCS: the frightening event (e.g. being trapped in a lift when it breaks down);',1,1);
INSERT INTO rubric_criterion VALUES(10842,'psych34a3-sp-7',NULL,1,'UCR: fear/panic; before conditioning the lift is a neutral stimulus;',1,1);
INSERT INTO rubric_criterion VALUES(10843,'psych34a3-sp-7',NULL,2,'after pairing, the lift becomes the CS; CR: fear response to the lift alone;',1,1);
INSERT INTO rubric_criterion VALUES(10844,'psych34a3-sp-7',NULL,3,'generalisation to other enclosed spaces may follow.',1,1);
INSERT INTO rubric_criterion VALUES(10845,'psych34a3-sp-8',NULL,0,'Avoiding the object reduces anxiety, which negatively reinforces the avoidance behaviour (anxiety relief is rewarding);',1,1);
INSERT INTO rubric_criterion VALUES(10846,'psych34a3-sp-8',NULL,1,'the person never learns the feared stimulus is safe, so the conditioned response is not extinguished;',1,1);
INSERT INTO rubric_criterion VALUES(10847,'psych34a3-sp-8',NULL,2,'the fear memory remains and the phobia persists.',1,1);
INSERT INTO rubric_criterion VALUES(10854,'psych34a3-spi-6',NULL,0,'Person learns a relaxation technique (e.g. deep breathing);',1,1);
INSERT INTO rubric_criterion VALUES(10855,'psych34a3-spi-6',NULL,1,'a fear hierarchy is constructed from least feared (e.g. word ''spider'') to most feared (holding one);',1,1);
INSERT INTO rubric_criterion VALUES(10856,'psych34a3-spi-6',NULL,2,'person is gradually exposed at each step while relaxed; progression only occurs when anxiety is controlled;',1,1);
INSERT INTO rubric_criterion VALUES(10857,'psych34a3-spi-6',NULL,3,'by counterconditioning, relaxation replaces fear as the response.',1,1);
INSERT INTO rubric_criterion VALUES(10858,'psych34a3-spi-7',NULL,0,'Benefit: act quickly to reduce anxiety by increasing GABA''s inhibitory effect, useful short-term; limitation: do not address the cause (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10859,'psych34a3-spi-7',NULL,1,'learned fear), so symptoms may return when stopped; risks include drowsiness, tolerance and dependence;',1,1);
INSERT INTO rubric_criterion VALUES(10860,'psych34a3-spi-7',NULL,2,'therefore best combined with psychological interventions such as CBT or exposure.',1,1);
INSERT INTO rubric_criterion VALUES(10861,'psych34a3-spi-8',NULL,0,'Both are exposure-based and rely on the person learning that the stimulus is not dangerous;',1,1);
INSERT INTO rubric_criterion VALUES(10862,'psych34a3-spi-8',NULL,1,'systematic desensitisation is gradual with relaxation, flooding is immediate full-intensity exposure;',1,1);
INSERT INTO rubric_criterion VALUES(10863,'psych34a3-spi-8',NULL,2,'advantage of flooding: often faster results / fewer sessions;',1,1);
INSERT INTO rubric_criterion VALUES(10864,'psych34a3-spi-8',NULL,3,'disadvantage: very distressing, higher drop-out risk, needs careful consent and monitoring.',1,1);
INSERT INTO rubric_criterion VALUES(10871,'psych34a3-pf-6',NULL,0,'Risk factor: increases the likelihood of developing a mental health problem (e.g. chronic stress, social isolation, poverty);',1,1);
INSERT INTO rubric_criterion VALUES(10872,'psych34a3-pf-6',NULL,1,'protective factor: reduces the likelihood or buffers impact (e.g. social support, exercise, self-efficacy);',1,1);
INSERT INTO rubric_criterion VALUES(10873,'psych34a3-pf-6',NULL,2,'they influence mental wellbeing in opposite directions and may interact.',1,1);
INSERT INTO rubric_criterion VALUES(10874,'psych34a3-pf-7',NULL,0,'Biological: e.g. regular sleep or exercise, supports brain function and stress regulation;',1,1);
INSERT INTO rubric_criterion VALUES(10875,'psych34a3-pf-7',NULL,1,'Psychological: e.g. self-efficacy or effective coping, helps person manage challenges;',1,1);
INSERT INTO rubric_criterion VALUES(10876,'psych34a3-pf-7',NULL,2,'Social: e.g. family support or social connectedness, provides emotional/practical help and belonging.',1,1);
INSERT INTO rubric_criterion VALUES(10877,'psych34a3-pf-8',NULL,0,'Social: strong support from family and friends provides emotional and practical help; Psychological: adaptive coping and self-efficacy let him actively search for work and view the situation as challenge;',1,1);
INSERT INTO rubric_criterion VALUES(10878,'psych34a3-pf-8',NULL,1,'Biological: good sleep/exercise habits maintain stress regulation;',1,1);
INSERT INTO rubric_criterion VALUES(10879,'psych34a3-pf-8',NULL,2,'protective factors buffer the effect of the stressor.',1,1);
INSERT INTO rubric_criterion VALUES(10886,'psych34a3-ed-6',NULL,0,'IV: listening to music during study (music versus no music);',1,1);
INSERT INTO rubric_criterion VALUES(10887,'psych34a3-ed-6',NULL,1,'DV: exam scores;',1,1);
INSERT INTO rubric_criterion VALUES(10888,'psych34a3-ed-6',NULL,2,'controlled variables e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10889,'psych34a3-ed-6',NULL,3,'time spent studying, difficulty of material, prior knowledge, noise level, time of day, same exam.',1,1);
INSERT INTO rubric_criterion VALUES(10890,'psych34a3-ed-7',NULL,0,'Random allocation: assigns participants to groups by chance so each has equal likelihood of being in either; spreads participant characteristics evenly, reducing the effect of extraneous variables;',1,1);
INSERT INTO rubric_criterion VALUES(10891,'psych34a3-ed-7',NULL,1,'placebo: an inactive treatment that looks like the real treatment;',1,1);
INSERT INTO rubric_criterion VALUES(10892,'psych34a3-ed-7',NULL,2,'controls for participant expectation / placebo effect so differences can be attributed to the IV.',1,1);
INSERT INTO rubric_criterion VALUES(10893,'psych34a3-ed-8',NULL,0,'Participants self-selected, so groups may differ in other ways (e.g. age, motivation, caffeine use) giving confounding variables;',1,1);
INSERT INTO rubric_criterion VALUES(10894,'psych34a3-ed-8',NULL,1,'this weakens internal validity as the difference in memory may not be due to sleep;',1,1);
INSERT INTO rubric_criterion VALUES(10895,'psych34a3-ed-8',NULL,2,'improvement: random allocation of participants to sleep-deprived or normal-sleep conditions by researcher.',1,1);
INSERT INTO rubric_criterion VALUES(10902,'psych34a3-ds-6',NULL,0,'Mean = 50 ÷ 6 = 8.3 (8.33);',1,1);
INSERT INTO rubric_criterion VALUES(10903,'psych34a3-ds-6',NULL,1,'median = (7 + 8) ÷ 2 = 7.5;',1,1);
INSERT INTO rubric_criterion VALUES(10904,'psych34a3-ds-6',NULL,2,'the median is better as the score of 14 is an outlier that pulls the mean up, but median is not affected by extreme scores.',1,1);
INSERT INTO rubric_criterion VALUES(10905,'psych34a3-ds-7',NULL,0,'Statistical significance means the results are unlikely to be due to chance (p below the chosen level, e.g. 0.05), so the null hypothesis can be rejected;',1,1);
INSERT INTO rubric_criterion VALUES(10906,'psych34a3-ds-7',NULL,1,'it does not give effect size; a very small difference can be significant in a large sample;',1,1);
INSERT INTO rubric_criterion VALUES(10907,'psych34a3-ds-7',NULL,2,'so the result may have little real-world importance.',1,1);
INSERT INTO rubric_criterion VALUES(10908,'psych34a3-ds-8',NULL,0,'Conclusion: higher levels of exercise were associated with lower anxiety scores in the sample (correlation not causation); the results support / do not prove the hypothesis;',1,1);
INSERT INTO rubric_criterion VALUES(10909,'psych34a3-ds-8',NULL,1,'limitation e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10910,'psych34a3-ds-8',NULL,2,'sample not representative (so cannot generalise), self-report bias, or uncontrolled third variables.',1,1);
INSERT INTO rubric_criterion VALUES(10917,'psych34a3-ev-6',NULL,0,'Informed consent: participants agree after being told the nature, risks and procedures (parental consent for minors); confidentiality: personal information and data are protected;',1,1);
INSERT INTO rubric_criterion VALUES(10918,'psych34a3-ev-6',NULL,1,'voluntary participation / right to withdraw: free to leave at any time;',1,1);
INSERT INTO rubric_criterion VALUES(10919,'psych34a3-ev-6',NULL,2,'also valid: debriefing, minimising harm (beneficence), deception only if justified.',1,1);
INSERT INTO rubric_criterion VALUES(10920,'psych34a3-ev-7',NULL,0,'Deception must be justified as necessary and no alternative method is available, with minimal risk of harm and approved by ethics committee;',1,1);
INSERT INTO rubric_criterion VALUES(10921,'psych34a3-ev-7',NULL,1,'full debriefing after the study explaining the true purpose;',1,1);
INSERT INTO rubric_criterion VALUES(10922,'psych34a3-ev-7',NULL,2,'participants must be able to withdraw their data / not be exposed to undue distress.',1,1);
INSERT INTO rubric_criterion VALUES(10923,'psych34a3-ev-8',NULL,0,'Reliability: consistency of results if the study or measure is repeated; validity: whether the study measures what it claims and results are due to the IV (internal) / generalise (external);',1,1);
INSERT INTO rubric_criterion VALUES(10924,'psych34a3-ev-8',NULL,1,'improve reliability e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10925,'psych34a3-ev-8',NULL,2,'standardised instructions, clearer or more questionnaire items, test-retest checks, or training of researchers.',1,1);
INSERT INTO rubric_criterion VALUES(10932,'psych12a1-appr-6',NULL,0,'Similarity: both are non-invasive (do not require surgery) and can be used with healthy participants to study brain activity during tasks (1);',1,1);
INSERT INTO rubric_criterion VALUES(10933,'psych12a1-appr-6',NULL,1,'Difference: fMRI has high spatial resolution because it detects blood oxygen changes in specific regions, whereas EEG has poor spatial resolution (1);',1,1);
INSERT INTO rubric_criterion VALUES(10934,'psych12a1-appr-6',NULL,2,'EEG has high temporal resolution (milliseconds) whereas fMRI has lower temporal resolution because blood flow changes are slower (1).',1,1);
INSERT INTO rubric_criterion VALUES(10935,'psych12a1-appr-7',NULL,0,'(a) The participant would say they saw ''key'' (1);',1,1);
INSERT INTO rubric_criterion VALUES(10936,'psych12a1-appr-7',NULL,1,'(b) The right visual field is processed by the left hemisphere, which controls speech, so the word ''key'' can be named (1);',1,1);
INSERT INTO rubric_criterion VALUES(10937,'psych12a1-appr-7',NULL,2,'the left visual field is processed by the right hemisphere, which lacks language production, and the corpus callosum cannot transfer the information so ''ring'' cannot be verbalised (1).',1,1);
INSERT INTO rubric_criterion VALUES(10938,'psych12a1-appr-8',NULL,0,'Technique: fMRI (or PET) (1); Strength: shows which specific regions have increased blood flow/oxygen use during the task, with good spatial resolution (1);',1,1);
INSERT INTO rubric_criterion VALUES(10939,'psych12a1-appr-8',NULL,1,'Limitation: expensive, participant must lie still in a scanner, and poor temporal resolution so it cannot show rapid changes (1).',1,1);
INSERT INTO rubric_criterion VALUES(10940,'psych12a1-appr-8',NULL,2,'Accept a justified alternative such as EEG if its strength and limitation are correct.',1,1);
INSERT INTO rubric_criterion VALUES(10957,'psych12a1-appr-25',NULL,0,'Case study: an in-depth investigation of one person or a small group with naturally occurring brain damage or a condition, in which the researcher does not manipulate variables [1];',1,1);
INSERT INTO rubric_criterion VALUES(10958,'psych12a1-appr-25',NULL,1,'Experiment: the researcher manipulates an independent variable under controlled conditions, usually with a control group, to establish cause and effect [1].',1,1);
INSERT INTO rubric_criterion VALUES(10959,'psych12a1-appr-26',NULL,0,'Informed consent: participants, or a legally recognised substitute if their capacity is impaired, must understand and agree to take part [1];',1,1);
INSERT INTO rubric_criterion VALUES(10960,'psych12a1-appr-26',NULL,1,'this is important because people with brain injuries may have reduced ability to make decisions, so their rights must be protected [1].',1,1);
INSERT INTO rubric_criterion VALUES(10961,'psych12a1-appr-27',NULL,0,'(a) fMRI [1], as it detects changes in blood oxygenation that indicate which regions are active during the task, with good spatial resolution [1];',1,1);
INSERT INTO rubric_criterion VALUES(10962,'psych12a1-appr-27',NULL,1,'(b) MRI (or CT) [1], as it shows the brain''s structure in detail so abnormalities can be identified, and MRI does not use ionising radiation [1].',3,1);
INSERT INTO rubric_criterion VALUES(10963,'psych12a1-appr-28',NULL,0,'Computed tomography (CT) [1].',1,1);
INSERT INTO rubric_criterion VALUES(10964,'psych12a1-appr-29',NULL,0,'Stimulating a specific area and recording the movement or sensation the patient reported links that area to a function [1];',1,1);
INSERT INTO rubric_criterion VALUES(10965,'psych12a1-appr-29',NULL,1,'limitation: it is only possible in the small number of patients undergoing surgery, so the sample is limited and may not be representative [1].',1,1);
INSERT INTO rubric_criterion VALUES(10966,'psych12a1-appr-30',NULL,0,'The finding is correlational: it shows an association between activity and the task, not cause and effect [1];',1,1);
INSERT INTO rubric_criterion VALUES(10967,'psych12a1-appr-30',NULL,1,'the activity could be incidental or a consequence of the task, so evidence such as lesions or stimulation is needed to show necessity [1].',1,1);
INSERT INTO rubric_criterion VALUES(10968,'psych12a1-appr-31',NULL,0,'fMRI does not use a radioactive tracer, so the participant is not exposed to radiation and can be scanned repeatedly [1].',1,1);
INSERT INTO rubric_criterion VALUES(10969,'psych12a1-appr-32',NULL,0,'After removal of the hippocampus, H.M. could not form new long-term (declarative) memories, suggesting the hippocampus is needed for memory formation [1];',1,1);
INSERT INTO rubric_criterion VALUES(10970,'psych12a1-appr-32',NULL,1,'limitation: this is a single case, and the surgical damage extended beyond the hippocampus, so the conclusion may not generalise [1].',1,1);
INSERT INTO rubric_criterion VALUES(10971,'psych12a1-appr-33',NULL,0,'Structural techniques show the anatomy of the brain, such as CT or MRI [1];',1,1);
INSERT INTO rubric_criterion VALUES(10972,'psych12a1-appr-33',NULL,1,'functional techniques show activity or processes in the brain, such as fMRI or PET [1];',1,1);
INSERT INTO rubric_criterion VALUES(10973,'psych12a1-appr-33',NULL,2,'functional techniques are used to link regions to tasks, whereas structural techniques are used to identify damage or abnormalities [1].',1,1);
INSERT INTO rubric_criterion VALUES(10974,'psych12a1-appr-34',NULL,0,'Strength: case studies provide detailed, in-depth information about the effects of specific injuries, which may be rare and cannot be deliberately produced in humans [1];',1,1);
INSERT INTO rubric_criterion VALUES(10975,'psych12a1-appr-34',NULL,1,'they can suggest hypotheses about the role of particular regions [1];',1,1);
INSERT INTO rubric_criterion VALUES(10976,'psych12a1-appr-34',NULL,2,'limitation: each injury differs in location, extent and the person''s prior functioning, so findings may not generalise [1];',1,1);
INSERT INTO rubric_criterion VALUES(10977,'psych12a1-appr-34',NULL,3,'the researcher cannot control the damage, so cause and effect cannot be firmly established [1].',1,1);
INSERT INTO rubric_criterion VALUES(10981,'psych12a1-appr-38',NULL,0,'CT has good spatial resolution and shows the brain''s structure in detail [1];',1,1);
INSERT INTO rubric_criterion VALUES(10982,'psych12a1-appr-38',NULL,1,'CT produces a static image and has poor temporal resolution, so it cannot track changes over time [1];',1,1);
INSERT INTO rubric_criterion VALUES(10983,'psych12a1-appr-38',NULL,2,'EEG has good temporal resolution, recording changes within milliseconds, but poor spatial resolution [1]',1,1);
INSERT INTO rubric_criterion VALUES(10984,'psych12a1-appr-39',NULL,0,'The control group receives no lesion (or a sham operation) and shows normal performance, providing a baseline for comparison [1];',1,1);
INSERT INTO rubric_criterion VALUES(10985,'psych12a1-appr-39',NULL,1,'any difference between the groups can then be attributed to the lesion rather than to other factors [1]',1,1);
INSERT INTO rubric_criterion VALUES(10992,'psych12a1-stru-6',NULL,0,'Accept two well-justified structures, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(10993,'psych12a1-stru-6',NULL,1,'temporal lobe (involved in recognising faces/auditory and object recognition) (1+1);',1,1);
INSERT INTO rubric_criterion VALUES(10994,'psych12a1-stru-6',NULL,2,'amygdala (processes fear and emotional responses, so reduced fear suggests damage) (1+1).',1,1);
INSERT INTO rubric_criterion VALUES(10995,'psych12a1-stru-6',NULL,3,'Each structure named (1) and linked to its function (1).',1,1);
INSERT INTO rubric_criterion VALUES(10996,'psych12a1-stru-7',NULL,0,'Frontal lobe: involved in voluntary movement (motor cortex), planning, decision-making, reasoning, judgement and personality (1-2);',1,1);
INSERT INTO rubric_criterion VALUES(10997,'psych12a1-stru-7',NULL,1,'Example: damage to the prefrontal cortex may lead to impulsive behaviour, poor judgement or changes in personality/emotional regulation (1).',2,1);
INSERT INTO rubric_criterion VALUES(10998,'psych12a1-stru-8',NULL,0,'Hippocampus: forms new explicit/declarative memories and is involved in spatial memory (1);',1,1);
INSERT INTO rubric_criterion VALUES(10999,'psych12a1-stru-8',NULL,1,'Amygdala: processes emotions, especially fear and aggression, and adds emotional significance to memories (1).',1,1);
INSERT INTO rubric_criterion VALUES(11018,'psych12a1-stru-27',NULL,0,'Body parts requiring fine, precise movement have a larger representation in the motor cortex [1]',1,1);
INSERT INTO rubric_criterion VALUES(11019,'psych12a1-stru-28',NULL,0,'Temporal lobe [1]',1,1);
INSERT INTO rubric_criterion VALUES(11020,'psych12a1-stru-29',NULL,0,'Motor pathways cross over in the lower brainstem, so each hemisphere controls the opposite side of the body [1];',1,1);
INSERT INTO rubric_criterion VALUES(11021,'psych12a1-stru-29',NULL,1,'the right motor cortex therefore controls the left side of the body, so the left side is weakened [1]',1,1);
INSERT INTO rubric_criterion VALUES(11022,'psych12a1-stru-30',NULL,0,'The cerebellum fine-tunes movement, coordinating timing and balance as the skill is practised [1];',1,1);
INSERT INTO rubric_criterion VALUES(11023,'psych12a1-stru-30',NULL,1,'with repetition, movements become smoother and more automatic [1]',1,1);
INSERT INTO rubric_criterion VALUES(11024,'psych12a1-stru-31',NULL,0,'The hypothalamus contains a group of cells (the suprachiasmatic nucleus) that acts as the body''s internal clock [1];',1,1);
INSERT INTO rubric_criterion VALUES(11025,'psych12a1-stru-31',NULL,1,'it uses light signals from the eyes to regulate daily rhythms of sleepiness and alertness [1]',1,1);
INSERT INTO rubric_criterion VALUES(11026,'psych12a1-stru-32',NULL,0,'Auditory pathways are bilateral, so each ear sends signals to both auditory cortices [1];',1,1);
INSERT INTO rubric_criterion VALUES(11027,'psych12a1-stru-32',NULL,1,'the right temporal lobe, which is undamaged, still receives input from both ears [1]',1,1);
INSERT INTO rubric_criterion VALUES(11028,'psych12a1-stru-33',NULL,0,'The left visual field is processed by the right hemisphere [1];',1,1);
INSERT INTO rubric_criterion VALUES(11029,'psych12a1-stru-33',NULL,1,'the right hemisphere controls the left hand, so the patient can point to or pick up a key with the left hand [1];',1,1);
INSERT INTO rubric_criterion VALUES(11030,'psych12a1-stru-33',NULL,2,'the patient cannot say ''key'' aloud because the information cannot cross the severed corpus callosum to the left hemisphere''s language areas [1]',1,1);
INSERT INTO rubric_criterion VALUES(11031,'psych12a1-stru-34',NULL,0,'The hippocampus is involved in spatial memory and navigation [1];',1,1);
INSERT INTO rubric_criterion VALUES(11032,'psych12a1-stru-34',NULL,1,'the larger hippocampus suggests that learning and storing detailed spatial maps is associated with changes in its structure [1];',1,1);
INSERT INTO rubric_criterion VALUES(11033,'psych12a1-stru-34',NULL,2,'the study is correlational, so it cannot prove that the training caused the enlargement [1]',1,1);
INSERT INTO rubric_criterion VALUES(11034,'psych12a1-stru-35',NULL,0,'Myelin is a fatty insulating sheath that wraps around axons [1];',1,1);
INSERT INTO rubric_criterion VALUES(11035,'psych12a1-stru-35',NULL,1,'it allows the electrical impulse to jump between gaps in the sheath, which is faster than travelling along the whole axon [1];',1,1);
INSERT INTO rubric_criterion VALUES(11036,'psych12a1-stru-35',NULL,2,'so messages travel more quickly between brain regions [1]',1,1);
INSERT INTO rubric_criterion VALUES(11037,'psych12a1-stru-36',NULL,0,'Medulla oblongata: controls automatic functions such as breathing and heart rate [1];',1,1);
INSERT INTO rubric_criterion VALUES(11038,'psych12a1-stru-36',NULL,1,'Cerebellum: coordinates balance and smooth voluntary movement [1];',1,1);
INSERT INTO rubric_criterion VALUES(11039,'psych12a1-stru-36',NULL,2,'Damage to the medulla can disrupt breathing and heart rate, which are essential for survival [1];',1,1);
INSERT INTO rubric_criterion VALUES(11040,'psych12a1-stru-36',NULL,3,'Cerebellum damage affects coordination but does not directly control vital functions, so it is less immediately life-threatening [1]',1,1);
INSERT INTO rubric_criterion VALUES(11041,'psych12a1-stru-37',NULL,0,'The amygdala detects the threat and triggers a rapid fear response [1];',1,1);
INSERT INTO rubric_criterion VALUES(11042,'psych12a1-stru-37',NULL,1,'it sends signals that produce physiological arousal and an immediate reaction [1];',1,1);
INSERT INTO rubric_criterion VALUES(11043,'psych12a1-stru-37',NULL,2,'the prefrontal cortex evaluates the situation and sends regulatory signals that can dampen the amygdala''s response [1];',1,1);
INSERT INTO rubric_criterion VALUES(11044,'psych12a1-stru-37',NULL,3,'this allows the person to respond to the threat in a controlled rather than impulsive way [1]',1,1);
INSERT INTO rubric_criterion VALUES(11045,'psych12a1-stru-38',NULL,0,'Frontal lobe: voluntary movement, planning and decision-making [1];',1,1);
INSERT INTO rubric_criterion VALUES(11046,'psych12a1-stru-38',NULL,1,'Parietal lobe: processing touch, pain and temperature [1];',1,1);
INSERT INTO rubric_criterion VALUES(11047,'psych12a1-stru-38',NULL,2,'Temporal lobe: auditory processing and object recognition [1];',1,1);
INSERT INTO rubric_criterion VALUES(11048,'psych12a1-stru-38',NULL,3,'Occipital lobe: visual processing [1]',1,1);
INSERT INTO rubric_criterion VALUES(11056,'psych12a1-neur-6',NULL,0,'Neuroplasticity is the brain''s ability to change its structure and function in response to experience (1);',1,1);
INSERT INTO rubric_criterion VALUES(11057,'psych12a1-neur-6',NULL,1,'repeated practice repeatedly activates the same neural pathways, strengthening synaptic connections through long-term potentiation (1);',1,1);
INSERT INTO rubric_criterion VALUES(11058,'psych12a1-neur-6',NULL,2,'new synaptic connections may form (sprouting) while unused connections weaken or are pruned, making the neural network more efficient so skills improve (1).',1,1);
INSERT INTO rubric_criterion VALUES(11059,'psych12a1-neur-7',NULL,0,'Changes (any two): synaptic pruning of unused connections; myelination increasing the speed of neural transmission;',1,1);
INSERT INTO rubric_criterion VALUES(11060,'psych12a1-neur-7',NULL,1,'ongoing development of the prefrontal cortex; limbic system maturing earlier (1 for two changes identified);',1,1);
INSERT INTO rubric_criterion VALUES(11061,'psych12a1-neur-7',NULL,2,'Link: the prefrontal cortex, responsible for judgement and impulse control, is still developing while the limbic system (reward and emotion) is highly active, so adolescents may be more prone to risk-taking (2).',1,1);
INSERT INTO rubric_criterion VALUES(11062,'psych12a1-neur-8',NULL,0,'LTP: long-lasting strengthening of synapses after frequent/repeated stimulation, making transmission more efficient (1);',1,1);
INSERT INTO rubric_criterion VALUES(11063,'psych12a1-neur-8',NULL,1,'LTD: long-lasting weakening of synaptic connections after infrequent or low stimulation, which can lead to the connection being pruned (1).',1,1);
INSERT INTO rubric_criterion VALUES(11081,'psych12a1-neur-26',NULL,0,'Frequently used synaptic connections can be strengthened, or new connections can form (sprouting) [1]',1,1);
INSERT INTO rubric_criterion VALUES(11082,'psych12a1-neur-27',NULL,0,'The neural pathways for the skill are used less, so their synaptic connections are weakened and some are pruned [1];',1,1);
INSERT INTO rubric_criterion VALUES(11083,'psych12a1-neur-27',NULL,1,'without repeated activation the network becomes less efficient, so movements are slower and less accurate [1]',1,1);
INSERT INTO rubric_criterion VALUES(11084,'psych12a1-neur-28',NULL,0,'Myelin insulates axons, which speeds the transmission of nerve impulses [1];',1,1);
INSERT INTO rubric_criterion VALUES(11085,'psych12a1-neur-28',NULL,1,'faster and more reliable signals between the brain and muscles improve the timing and coordination of the movement [1]',1,1);
INSERT INTO rubric_criterion VALUES(11086,'psych12a1-neur-29',NULL,0,'The study is correlational, so it shows an association rather than proving that navigation experience caused the difference [1];',1,1);
INSERT INTO rubric_criterion VALUES(11087,'psych12a1-neur-29',NULL,1,'people with stronger spatial abilities may have been more likely to choose taxi driving, so pre-existing differences may explain the result [1]',1,1);
INSERT INTO rubric_criterion VALUES(11088,'psych12a1-neur-30',NULL,0,'Adaptive plasticity is change that improves function or helps the brain adjust to experience [1], for example reorganisation that restores a lost ability after injury [1];',1,1);
INSERT INTO rubric_criterion VALUES(11089,'psych12a1-neur-30',NULL,1,'maladaptive plasticity is change associated with harmful or unhelpful outcomes [1], for example cortical reorganisation linked to persistent phantom limb pain [1]',3,1);
INSERT INTO rubric_criterion VALUES(11090,'psych12a1-neur-31',NULL,0,'Early childhood is a critical (sensitive) period when the brain is especially responsive to language input [1];',1,1);
INSERT INTO rubric_criterion VALUES(11091,'psych12a1-neur-31',NULL,1,'children''s greater plasticity allows language networks to form readily and efficiently [1];',1,1);
INSERT INTO rubric_criterion VALUES(11092,'psych12a1-neur-31',NULL,2,'adults have reduced plasticity and build new connections more slowly, so fluency develops more slowly [1]',1,1);
INSERT INTO rubric_criterion VALUES(11093,'psych12a1-neur-32',NULL,0,'Connections that are not stimulated are less likely to be maintained, so they are pruned [1];',1,1);
INSERT INTO rubric_criterion VALUES(11094,'psych12a1-neur-32',NULL,1,'the networks that remain are those that were activated, which may limit the range of skills developed [1];',1,1);
INSERT INTO rubric_criterion VALUES(11095,'psych12a1-neur-32',NULL,2,'later enriched experiences can partly reorganise these networks, so the effects are not always permanent [1]',1,1);
INSERT INTO rubric_criterion VALUES(11096,'psych12a1-neur-33',NULL,0,'Evidence: the prefrontal cortex, which supports planning and impulse control, continues developing into the mid-20s [1];',1,1);
INSERT INTO rubric_criterion VALUES(11097,'psych12a1-neur-33',NULL,1,'the limbic system, involved in reward and emotion, is highly responsive during adolescence, which can increase risk-taking [1];',1,1);
INSERT INTO rubric_criterion VALUES(11098,'psych12a1-neur-33',NULL,2,'evaluation: the claim is overstated, as adolescents can make good decisions and outcomes depend on context, emotional state and peer presence [1];',1,1);
INSERT INTO rubric_criterion VALUES(11099,'psych12a1-neur-33',NULL,3,'neuroplasticity means experience and training can improve decision-making skills, so development is not fixed [1]',1,1);
INSERT INTO rubric_criterion VALUES(11100,'psych12a1-neur-34',NULL,0,'Most neurons are generated before birth, and neurogenesis in the adult brain is limited and restricted to a few regions [1];',1,1);
INSERT INTO rubric_criterion VALUES(11101,'psych12a1-neur-34',NULL,1,'neurons lost to injury are generally not replaced in large numbers [1];',1,1);
INSERT INTO rubric_criterion VALUES(11102,'psych12a1-neur-34',NULL,2,'recovery therefore depends on changes in existing networks, such as sprouting, rerouting and strengthening of surviving synapses [1];',1,1);
INSERT INTO rubric_criterion VALUES(11103,'psych12a1-neur-34',NULL,3,'rehabilitation that repeatedly uses the affected function encourages these changes [1]',1,1);
INSERT INTO rubric_criterion VALUES(11104,'psych12a1-neur-35',NULL,0,'Neuroplasticity continues across the lifespan, so new synaptic connections can form and existing ones can be strengthened with practice [1];',1,1);
INSERT INTO rubric_criterion VALUES(11105,'psych12a1-neur-35',NULL,1,'learning is typically slower than in childhood because plasticity is generally greater earlier in life [1]',1,1);
INSERT INTO rubric_criterion VALUES(11108,'psych12a1-neur-38',NULL,0,'Lasting changes depend on repeated stimulation that strengthens synapses over time, through long-term potentiation [1];',1,1);
INSERT INTO rubric_criterion VALUES(11109,'psych12a1-neur-38',NULL,1,'spacing allows the changes to consolidate between sessions, whereas a single intense session produces only short-lived changes [1]',1,1);
INSERT INTO rubric_criterion VALUES(11110,'psych12a1-neur-39',NULL,0,'The study measures an association between practice and brain structure without manipulating practice [1];',1,1);
INSERT INTO rubric_criterion VALUES(11111,'psych12a1-neur-39',NULL,1,'the groups may already differ, for example in motor ability or motivation, which could explain the difference [1];',1,1);
INSERT INTO rubric_criterion VALUES(11112,'psych12a1-neur-39',NULL,2,'randomly assigning adolescents to a juggling training group or a control group, and scanning both groups before and after training, would test cause and effect [1]',1,1);
INSERT INTO rubric_criterion VALUES(11119,'psych12a1-acqu-6',NULL,0,'Any two with justification: difficulty planning and making decisions; impulsivity or poor judgement; changes in personality or emotional regulation (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11120,'psych12a1-acqu-6',NULL,1,'irritability, aggression); reduced attention or problem solving; difficulty with voluntary movement (1 mark each).',1,1);
INSERT INTO rubric_criterion VALUES(11121,'psych12a1-acqu-7',NULL,0,'Neuroplasticity allows the brain to reorganise after damage (1);',1,1);
INSERT INTO rubric_criterion VALUES(11122,'psych12a1-acqu-7',NULL,1,'undamaged areas can take over function through rerouting and sprouting new synaptic connections (1);',1,1);
INSERT INTO rubric_criterion VALUES(11123,'psych12a1-acqu-7',NULL,2,'rehabilitation such as physiotherapy, speech therapy or repeated practice of lost skills strengthens the new pathways (1).',1,1);
INSERT INTO rubric_criterion VALUES(11124,'psych12a1-acqu-8',NULL,0,'Traumatic: caused by external physical force to the head, e.g. a fall or car accident (1+1 for definition and example);',1,1);
INSERT INTO rubric_criterion VALUES(11125,'psych12a1-acqu-8',NULL,1,'Non-traumatic: caused by internal factors such as a blockage, bleed, infection or lack of oxygen, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11126,'psych12a1-acqu-8',NULL,2,'stroke or tumour (1).',1,1);
INSERT INTO rubric_criterion VALUES(11144,'psych12a1-acqu-26',NULL,0,'Any two, [1] each: inherited, autosomal dominant genetic disorder; involuntary, jerky movements (chorea) caused by degeneration of neurons in the basal ganglia;',1,1);
INSERT INTO rubric_criterion VALUES(11145,'psych12a1-acqu-26',NULL,1,'progressive cognitive decline and changes in mood or personality.',1,1);
INSERT INTO rubric_criterion VALUES(11146,'psych12a1-acqu-27',NULL,0,'Amyloid-β plaques build up between neurons, interfering with synaptic signalling and triggering inflammation [1];',1,1);
INSERT INTO rubric_criterion VALUES(11147,'psych12a1-acqu-27',NULL,1,'tau tangles form inside neurons and disrupt the internal transport of nutrients along axons [1];',1,1);
INSERT INTO rubric_criterion VALUES(11148,'psych12a1-acqu-27',NULL,2,'the resulting neuronal death causes brain atrophy and memory loss [1].',1,1);
INSERT INTO rubric_criterion VALUES(11149,'psych12a1-acqu-28',NULL,0,'Visual agnosia [1]',1,1);
INSERT INTO rubric_criterion VALUES(11150,'psych12a1-acqu-29',NULL,0,'The left hemisphere is usually dominant for language, so a left-sided stroke may cause aphasia, such as difficulty speaking or understanding [1];',1,1);
INSERT INTO rubric_criterion VALUES(11151,'psych12a1-acqu-29',NULL,1,'the right hemisphere is more involved in spatial awareness and attention, so right-sided damage may cause neglect of the left side of space [1];',1,1);
INSERT INTO rubric_criterion VALUES(11152,'psych12a1-acqu-29',NULL,2,'each hemisphere controls the opposite side of the body, so a left stroke causes right-sided weakness and a right stroke causes left-sided weakness [1];',1,1);
INSERT INTO rubric_criterion VALUES(11153,'psych12a1-acqu-29',NULL,3,'the size and location of the damage determine the severity and the specific deficits [1].',1,1);
INSERT INTO rubric_criterion VALUES(11154,'psych12a1-acqu-30',NULL,0,'Their damaged memory system cannot accurately store or retrieve past events [1];',1,1);
INSERT INTO rubric_criterion VALUES(11155,'psych12a1-acqu-30',NULL,1,'the brain fills the gaps with plausible but false information, which the person may believe is true [1].',1,1);
INSERT INTO rubric_criterion VALUES(11156,'psych12a1-acqu-31',NULL,0,'Each concussion can disrupt neuronal function and cause further damage before the brain has recovered from the previous one [1];',1,1);
INSERT INTO rubric_criterion VALUES(11157,'psych12a1-acqu-31',NULL,1,'repeated injury can lead to longer-lasting cognitive, emotional or behavioural problems [1].',1,1);
INSERT INTO rubric_criterion VALUES(11158,'psych12a1-acqu-32',NULL,0,'Levodopa crosses the blood-brain barrier and is converted into dopamine in the brain, which relieves movement symptoms [1];',1,1);
INSERT INTO rubric_criterion VALUES(11159,'psych12a1-acqu-32',NULL,1,'it replaces some of the lost dopamine rather than stopping the degeneration of dopamine neurons [1];',1,1);
INSERT INTO rubric_criterion VALUES(11160,'psych12a1-acqu-32',NULL,2,'the neurons continue to die, so the disease progresses and treatment does not cure it [1].',1,1);
INSERT INTO rubric_criterion VALUES(11161,'psych12a1-acqu-33',NULL,0,'A group of neurons produces sudden, excessive and abnormal electrical discharges [1];',1,1);
INSERT INTO rubric_criterion VALUES(11162,'psych12a1-acqu-33',NULL,1,'the abnormal activity spreads or synchronises across brain regions, disrupting normal function and causing altered consciousness, movement or sensation [1].',1,1);
INSERT INTO rubric_criterion VALUES(11163,'psych12a1-acqu-34',NULL,0,'Neurons need a continuous oxygen supply and begin to die within minutes without it [1];',1,1);
INSERT INTO rubric_criterion VALUES(11164,'psych12a1-acqu-34',NULL,1,'reduced oxygen affects the whole brain rather than a single localised area, so damage is diffuse [1];',1,1);
INSERT INTO rubric_criterion VALUES(11165,'psych12a1-acqu-34',NULL,2,'the hippocampus and cortex are particularly vulnerable, which can cause memory and attention deficits [1].',1,1);
INSERT INTO rubric_criterion VALUES(11166,'psych12a1-acqu-35',NULL,0,'Any two, [1] each: brain tumour; infection such as encephalitis or meningitis;',1,1);
INSERT INTO rubric_criterion VALUES(11167,'psych12a1-acqu-35',NULL,1,'toxic exposure, such as long-term alcohol or drug misuse.',1,1);
INSERT INTO rubric_criterion VALUES(11168,'psych12a1-acqu-36',NULL,0,'Myelin is the fatty insulating sheath around axons that allows impulses to travel quickly by jumping between nodes [1];',1,1);
INSERT INTO rubric_criterion VALUES(11169,'psych12a1-acqu-36',NULL,1,'in MS the immune system attacks and destroys myelin, a process called demyelination [1];',1,1);
INSERT INTO rubric_criterion VALUES(11170,'psych12a1-acqu-36',NULL,2,'without myelin, signals are slowed or blocked, causing symptoms such as weakness, numbness, fatigue or vision problems [1].',1,1);
INSERT INTO rubric_criterion VALUES(11171,'psych12a1-acqu-37',NULL,0,'Repeated structured practice of word-finding or naming tasks [1];',1,1);
INSERT INTO rubric_criterion VALUES(11172,'psych12a1-acqu-37',NULL,1,'melodic intonation therapy, which uses singing and rhythm to engage intact right-hemisphere areas [1];',1,1);
INSERT INTO rubric_criterion VALUES(11173,'psych12a1-acqu-37',NULL,2,'neuroplasticity allows repeated practice to strengthen existing or newly formed connections [1];',1,1);
INSERT INTO rubric_criterion VALUES(11174,'psych12a1-acqu-37',NULL,3,'reorganisation can shift some language function to undamaged regions, including the right hemisphere [1].',1,1);
INSERT INTO rubric_criterion VALUES(11176,'psych12a1-acqu-39',NULL,0,'A stroke is caused by a sudden blockage or bleed that deprives brain cells of oxygen, so neurons die within minutes or hours [1];',1,1);
INSERT INTO rubric_criterion VALUES(11177,'psych12a1-acqu-39',NULL,1,'Alzheimer''s disease involves progressive degeneration of neurons and connections over years, so symptoms emerge slowly [1]',1,1);
INSERT INTO rubric_criterion VALUES(11184,'psych12a1-natu-6',NULL,0,'Nature: genetic and biological factors that influence development, e.g. inherited capacity for language/brain structures (1);',1,1);
INSERT INTO rubric_criterion VALUES(11185,'psych12a1-natu-6',NULL,1,'Nurture: environmental influences, e.g. exposure to language, interaction with caregivers (1);',1,1);
INSERT INTO rubric_criterion VALUES(11186,'psych12a1-natu-6',NULL,2,'both interact, as a child needs both the biological capacity and exposure to language to develop speech (1).',1,1);
INSERT INTO rubric_criterion VALUES(11187,'psych12a1-natu-7',NULL,0,'Biological: genetic predisposition, imbalance of neurotransmitters, or hormonal changes (1);',1,1);
INSERT INTO rubric_criterion VALUES(11188,'psych12a1-natu-7',NULL,1,'Psychological: negative thought patterns, low self-esteem or poor coping skills (1);',1,1);
INSERT INTO rubric_criterion VALUES(11189,'psych12a1-natu-7',NULL,2,'Social: bullying, family conflict, social isolation or lack of support (1).',1,1);
INSERT INTO rubric_criterion VALUES(11190,'psych12a1-natu-8',NULL,0,'Identical twins raised together share both genes and environment, so it is hard to separate the two influences (1); twins raised apart are rare, giving small samples, and they may still share prenatal or similar environments, limiting generalisability (1).',1,1);
INSERT INTO rubric_criterion VALUES(11191,'psych12a1-natu-8',NULL,1,'Accept another valid limitation.',1,1);
INSERT INTO rubric_criterion VALUES(11210,'psych12a1-natu-27',NULL,0,'Socialisation is the process by which people learn the behaviours, values and norms of their culture or community through interaction with others [1]; e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11211,'psych12a1-natu-27',NULL,1,'a child learning to take turns during a game with friends [1].',1,1);
INSERT INTO rubric_criterion VALUES(11212,'psych12a1-natu-28',NULL,0,'A consistent, early-emerging pattern of emotional and behavioural reactivity to the environment [1].',1,1);
INSERT INTO rubric_criterion VALUES(11213,'psych12a1-natu-29',NULL,0,'Socioeconomic status is a social factor reflecting family income, parental education and neighbourhood resources [1];',1,1);
INSERT INTO rubric_criterion VALUES(11214,'psych12a1-natu-29',NULL,1,'lower income can increase family stress and reduce access to enriching activities [1];',1,1);
INSERT INTO rubric_criterion VALUES(11215,'psych12a1-natu-29',NULL,2,'parental stress may reduce responsive parenting, affecting the child''s emotional development [1].',1,1);
INSERT INTO rubric_criterion VALUES(11216,'psych12a1-natu-30',NULL,0,'Biological: disrupted sleep or raised stress hormones such as cortisol [1];',1,1);
INSERT INTO rubric_criterion VALUES(11217,'psych12a1-natu-30',NULL,1,'Psychological: catastrophic thinking about failing, or a fear-of-failure belief [1];',1,1);
INSERT INTO rubric_criterion VALUES(11218,'psych12a1-natu-30',NULL,2,'Social: high pressure from parents or school, or limited support from friends [1];',1,1);
INSERT INTO rubric_criterion VALUES(11219,'psych12a1-natu-30',NULL,3,'Interaction: poor sleep reduces concentration and recall, which increases self-critical thinking, which intensifies anxiety [1].',1,1);
INSERT INTO rubric_criterion VALUES(11220,'psych12a1-natu-31',NULL,0,'Depression usually results from several interacting biological, psychological and social influences [1];',1,1);
INSERT INTO rubric_criterion VALUES(11221,'psych12a1-natu-31',NULL,1,'a single-cause explanation ignores these factors and may lead to incomplete understanding or to treatment that addresses only one of them [1].',1,1);
INSERT INTO rubric_criterion VALUES(11222,'psych12a1-natu-32',NULL,0,'Nurture: an environmental influence on development [1].',1,1);
INSERT INTO rubric_criterion VALUES(11223,'psych12a1-natu-33',NULL,0,'A heritable trait is one whose variation is influenced by genes passed from parents to offspring [1];',1,1);
INSERT INTO rubric_criterion VALUES(11224,'psych12a1-natu-33',NULL,1,'a trait present at birth may instead be caused by the prenatal environment, such as infection during pregnancy, so being present at birth does not mean a trait is heritable [1].',1,1);
INSERT INTO rubric_criterion VALUES(11225,'psych12a1-natu-34',NULL,0,'Effective coping strategies, such as problem-solving or seeking support, reduce the impact of the stressor on mood and wellbeing [1];',1,1);
INSERT INTO rubric_criterion VALUES(11226,'psych12a1-natu-34',NULL,1,'poor coping may increase distress and make the person more vulnerable to a mental health problem [1].',1,1);
INSERT INTO rubric_criterion VALUES(11227,'psych12a1-natu-35',NULL,0,'The biopsychosocial approach considers biological, psychological and social factors together, whereas a purely biological model considers only physical causes [1];',1,1);
INSERT INTO rubric_criterion VALUES(11228,'psych12a1-natu-35',NULL,1,'biological: airway inflammation or an inherited tendency to asthma [1];',1,1);
INSERT INTO rubric_criterion VALUES(11229,'psych12a1-natu-35',NULL,2,'psychological: stress from exam pressure [1];',1,1);
INSERT INTO rubric_criterion VALUES(11230,'psych12a1-natu-35',NULL,3,'social: exposure to smoke in the household [1].',1,1);
INSERT INTO rubric_criterion VALUES(11231,'psych12a1-natu-36',NULL,0,'Children''s genes cannot be randomly assigned or manipulated [1];',1,1);
INSERT INTO rubric_criterion VALUES(11232,'psych12a1-natu-36',NULL,1,'deliberately creating harmful or deprived environments would be unethical [1];',1,1);
INSERT INTO rubric_criterion VALUES(11233,'psych12a1-natu-36',NULL,2,'researchers therefore rely on naturally occurring groups such as twins and adoptees, which contain confounding variables [1].',1,1);
INSERT INTO rubric_criterion VALUES(11234,'psych12a1-natu-37',NULL,0,'Adoption agencies often place children in homes similar in socioeconomic status, which reduces the range of environments studied [1];',1,1);
INSERT INTO rubric_criterion VALUES(11235,'psych12a1-natu-37',NULL,1,'the early environment with the biological mother, including prenatal conditions, is not controlled, so genetic and environmental effects cannot be fully separated [1].',1,1);
INSERT INTO rubric_criterion VALUES(11236,'psych12a1-natu-38',NULL,0,'Nurture: reading to a child is an environmental influence [1];',1,1);
INSERT INTO rubric_criterion VALUES(11237,'psych12a1-natu-38',NULL,1,'correlation does not establish cause, because children who are read to may differ in other ways, such as family income [1];',1,1);
INSERT INTO rubric_criterion VALUES(11238,'psych12a1-natu-38',NULL,2,'another factor the study should consider is the child''s inherited verbal ability [1].',1,1);
INSERT INTO rubric_criterion VALUES(11246,'psych12a1-emot-6',NULL,0,'Infant and caregiver are placed in an unfamiliar room with toys, with a series of episodes in which the caregiver and a stranger enter and leave, separating and reuniting the infant and caregiver (1+1);',1,1);
INSERT INTO rubric_criterion VALUES(11247,'psych12a1-emot-6',NULL,1,'observers record the infant''s exploration, reaction to separation, reaction to the stranger and behaviour on reunion to classify attachment type (1).',2,1);
INSERT INTO rubric_criterion VALUES(11248,'psych12a1-emot-7',NULL,0,'Insecure-avoidant: little distress when the caregiver leaves, avoids or ignores the caregiver on return (1);',1,1);
INSERT INTO rubric_criterion VALUES(11249,'psych12a1-emot-7',NULL,1,'Insecure-resistant: highly distressed on separation, seeks contact on return but also resists or is angry and is not easily comforted (1).',1,1);
INSERT INTO rubric_criterion VALUES(11250,'psych12a1-emot-8',NULL,0,'Secure attachment (1);',1,1);
INSERT INTO rubric_criterion VALUES(11251,'psych12a1-emot-8',NULL,1,'distress at separation, quick comfort on return and exploration using the caregiver as a secure base (1);',1,1);
INSERT INTO rubric_criterion VALUES(11252,'psych12a1-emot-8',NULL,2,'Limitation: a single observation or behaviour in one context may not reflect attachment, and temperament or cultural differences may influence behaviour (1).',1,1);
INSERT INTO rubric_criterion VALUES(11269,'psych12a1-emot-25',NULL,0,'Bowlby proposed that attachment is an innate behaviour that evolved to keep infants close to protective caregivers and so improve survival [1];',1,1);
INSERT INTO rubric_criterion VALUES(11270,'psych12a1-emot-25',NULL,1,'learning theory proposes that attachment is learned through association with feeding and reinforcement [1].',1,1);
INSERT INTO rubric_criterion VALUES(11271,'psych12a1-emot-26',NULL,0,'Infants progress from indiscriminate attachment from about 6 weeks to a specific attachment, usually to a primary caregiver, by around 7 months [1];',1,1);
INSERT INTO rubric_criterion VALUES(11272,'psych12a1-emot-26',NULL,1,'many then form multiple attachments [1];',1,1);
INSERT INTO rubric_criterion VALUES(11273,'psych12a1-emot-26',NULL,2,'attachment strength was linked to the caregiver''s responsiveness rather than to feeding, which challenges the view that attachment is based on feeding [1].',1,1);
INSERT INTO rubric_criterion VALUES(11274,'psych12a1-emot-27',NULL,0,'An internal working model is a mental representation of self and others, built from early caregiving experiences, that sets expectations about how relationships will work [1];',1,1);
INSERT INTO rubric_criterion VALUES(11275,'psych12a1-emot-27',NULL,1,'these expectations guide how a person interprets and behaves in later relationships, such as friendships and romantic partnerships [1];',1,1);
INSERT INTO rubric_criterion VALUES(11276,'psych12a1-emot-27',NULL,2,'one method is the Adult Attachment Interview, which asks adults about their childhood experiences [1];',1,1);
INSERT INTO rubric_criterion VALUES(11277,'psych12a1-emot-27',NULL,3,'Main, Kaplan and Cassidy (1985) found that parents'' Adult Attachment Interview classifications predicted the attachment type of their infants in the Strange Situation [1].',1,1);
INSERT INTO rubric_criterion VALUES(11278,'psych12a1-emot-28',NULL,0,'Stranger anxiety shows the infant can distinguish familiar from unfamiliar people [1];',1,1);
INSERT INTO rubric_criterion VALUES(11279,'psych12a1-emot-28',NULL,1,'distress towards strangers, especially when the familiar caregiver is not present, shows that a specific attachment to that caregiver has formed [1].',1,1);
INSERT INTO rubric_criterion VALUES(11280,'psych12a1-emot-29',NULL,0,'Primary emotions, such as happiness, sadness, fear and anger, appear in infancy [1];',1,1);
INSERT INTO rubric_criterion VALUES(11281,'psych12a1-emot-29',NULL,1,'self-conscious emotions, such as embarrassment, pride and guilt, emerge later, around 18 to 24 months, and depend on a sense of self [1].',1,1);
INSERT INTO rubric_criterion VALUES(11282,'psych12a1-emot-30',NULL,0,'The caregiver helps calm the infant''s distress, so the infant''s emotional arousal is managed through co-regulation [1];',1,1);
INSERT INTO rubric_criterion VALUES(11283,'psych12a1-emot-30',NULL,1,'repeated experiences teach the infant that distress is followed by comfort, building expectations that needs will be met [1];',1,1);
INSERT INTO rubric_criterion VALUES(11284,'psych12a1-emot-30',NULL,2,'over time the infant gradually develops self-regulation and manages emotions independently [1].',1,1);
INSERT INTO rubric_criterion VALUES(11285,'psych12a1-emot-31',NULL,0,'Strength: the standardised, repeatable procedure allows researchers to compare attachment classifications across countries [1];',1,1);
INSERT INTO rubric_criterion VALUES(11286,'psych12a1-emot-31',NULL,1,'a large meta-analysis of studies from many countries (van IJzendoorn and Kroonenberg, 1988) was possible because the same procedure was used [1].',1,1);
INSERT INTO rubric_criterion VALUES(11287,'psych12a1-emot-31',NULL,2,'Limitation: the procedure takes place in an unfamiliar laboratory setting, which may not reflect how infants behave at home [1];',1,1);
INSERT INTO rubric_criterion VALUES(11288,'psych12a1-emot-31',NULL,3,'behaviours labelled insecure in one culture may be normal in another, so classifications may reflect cultural expectations rather than the quality of attachment [1].',1,1);
INSERT INTO rubric_criterion VALUES(11289,'psych12a1-emot-32',NULL,0,'A sensitive period is a time in early childhood when an infant is most ready to form an attachment [1];',1,1);
INSERT INTO rubric_criterion VALUES(11290,'psych12a1-emot-32',NULL,1,'if attachment has not formed by the end of this period, forming one later may be more difficult [1].',1,1);
INSERT INTO rubric_criterion VALUES(11291,'psych12a1-emot-33',NULL,0,'The caregiver acts as a secure base, a safe point from which the toddler can explore the environment [1];',1,1);
INSERT INTO rubric_criterion VALUES(11292,'psych12a1-emot-33',NULL,1,'the toddler ventures away but returns for comfort or reassurance when frightened [1];',1,1);
INSERT INTO rubric_criterion VALUES(11293,'psych12a1-emot-33',NULL,2,'knowing the caregiver is available allows the toddler to explore with confidence, for example playing on a playground and returning to the parent for reassurance after a fall [1].',1,1);
INSERT INTO rubric_criterion VALUES(11294,'psych12a1-emot-34',NULL,0,'The social smile is directed at people and typically appears around 6 to 8 weeks, unlike the reflexive smiles of newborns [1];',1,1);
INSERT INTO rubric_criterion VALUES(11295,'psych12a1-emot-34',NULL,1,'it encourages caregivers to respond and interact, strengthening the bond between infant and caregiver [1].',1,1);
INSERT INTO rubric_criterion VALUES(11296,'psych12a1-emot-35',NULL,0,'Early secure attachment builds an internal working model with positive expectations about relationships [1];',1,1);
INSERT INTO rubric_criterion VALUES(11297,'psych12a1-emot-35',NULL,1,'learning to regulate emotions helps children cope with friendships and social situations [1];',1,1);
INSERT INTO rubric_criterion VALUES(11298,'psych12a1-emot-35',NULL,2,'limitation: later experiences, such as changes in family circumstances, may explain outcomes [1];',1,1);
INSERT INTO rubric_criterion VALUES(11299,'psych12a1-emot-35',NULL,3,'this makes it hard to show that early emotional development caused later relationships, because the link cannot be separated from other influences [1].',1,1);
INSERT INTO rubric_criterion VALUES(11302,'psych12a1-emot-38',NULL,0,'A strategy such as turning away from the frustrating task, seeking comfort from a caregiver or using a toy to distract themselves [1];',1,1);
INSERT INTO rubric_criterion VALUES(11303,'psych12a1-emot-38',NULL,1,'adults can help by naming the feeling, modelling calm responses and offering support so the child gradually manages emotions independently [1]',1,1);
INSERT INTO rubric_criterion VALUES(11304,'psych12a1-emot-39',NULL,0,'Naming emotions helps children label what they feel, so the emotion is understood rather than overwhelming them [1];',1,1);
INSERT INTO rubric_criterion VALUES(11305,'psych12a1-emot-39',NULL,1,'recognising emotions in others allows the child to predict others'' responses and adjust their own behaviour [1];',1,1);
INSERT INTO rubric_criterion VALUES(11306,'psych12a1-emot-39',NULL,2,'this emotional understanding supports the use of regulation strategies, such as calming down or asking for help [1]',1,1);
INSERT INTO rubric_criterion VALUES(11313,'psych12a1-cogn-6',NULL,0,'Egocentrism is the inability to see a situation from another person''s perspective (1);',1,1);
INSERT INTO rubric_criterion VALUES(11314,'psych12a1-cogn-6',NULL,1,'Example: a child holding a picture up so only they can see it while describing it to a parent, or assuming others see the same view they do (1).',1,1);
INSERT INTO rubric_criterion VALUES(11315,'psych12a1-cogn-7',NULL,0,'Assimilation: fitting new information into an existing schema (1);',1,1);
INSERT INTO rubric_criterion VALUES(11316,'psych12a1-cogn-7',NULL,1,'Accommodation: modifying an existing schema or creating a new one when new information doesn''t fit (1);',1,1);
INSERT INTO rubric_criterion VALUES(11317,'psych12a1-cogn-7',NULL,2,'Example: a child with a ''bird'' schema sees a bat, first calls it a bird (assimilation), then adjusts the schema or forms a new one for bat (accommodation) (1).',1,1);
INSERT INTO rubric_criterion VALUES(11318,'psych12a1-cogn-8',NULL,0,'Piaget may have underestimated children''s abilities because tasks were complex or language-heavy, and later research shows younger children can succeed on simplified tasks (1+1).',1,1);
INSERT INTO rubric_criterion VALUES(11319,'psych12a1-cogn-8',NULL,1,'Accept other valid limitations such as the stages being less rigid than proposed or a lack of focus on social and cultural influences.',1,1);
INSERT INTO rubric_criterion VALUES(11337,'psych12a1-cogn-26',NULL,0,'A primary circular reaction repeats an action on the infant''s own body, e.g. repeatedly sucking the thumb [1];',1,1);
INSERT INTO rubric_criterion VALUES(11338,'psych12a1-cogn-26',NULL,1,'a secondary circular reaction repeats an action on an object to produce an effect in the environment, e.g. repeatedly shaking a rattle to hear the sound [1].',1,1);
INSERT INTO rubric_criterion VALUES(11339,'psych12a1-cogn-27',NULL,0,'New information that conflicts with existing schemas creates cognitive disequilibrium [1];',1,1);
INSERT INTO rubric_criterion VALUES(11340,'psych12a1-cogn-27',NULL,1,'the child uses assimilation and accommodation to resolve the conflict [1];',1,1);
INSERT INTO rubric_criterion VALUES(11341,'psych12a1-cogn-27',NULL,2,'this produces a new, more stable state of understanding (equilibrium) that moves development to a higher level [1].',1,1);
INSERT INTO rubric_criterion VALUES(11342,'psych12a1-cogn-28',NULL,0,'Children form and test their own theories about the world, much like scientists [1];',1,1);
INSERT INTO rubric_criterion VALUES(11343,'psych12a1-cogn-28',NULL,1,'they actively explore and revise their schemas when evidence does not fit their current understanding [1].',1,1);
INSERT INTO rubric_criterion VALUES(11344,'psych12a1-cogn-29',NULL,0,'Concrete operational thinking applies logic to concrete, observable objects and events [1], e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11345,'psych12a1-cogn-29',NULL,1,'ordering objects by weight to work out which is heaviest [1];',1,1);
INSERT INTO rubric_criterion VALUES(11346,'psych12a1-cogn-29',NULL,2,'formal operational thinking applies logic to abstract and hypothetical ideas and possibilities [1], e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11347,'psych12a1-cogn-29',NULL,3,'reasoning about how a society would change if a rule were removed, or testing a hypothesis in a science experiment [1].',1,1);
INSERT INTO rubric_criterion VALUES(11348,'psych12a1-cogn-30',NULL,0,'Use hands-on, concrete materials so children can manipulate objects and test ideas [1];',1,1);
INSERT INTO rubric_criterion VALUES(11349,'psych12a1-cogn-30',NULL,1,'include activities involving reversibility and conservation, such as pouring liquids or rearranging counters [1];',1,1);
INSERT INTO rubric_criterion VALUES(11350,'psych12a1-cogn-30',NULL,2,'introduce abstract concepts only after concrete examples, rather than expecting hypothetical reasoning [1].',1,1);
INSERT INTO rubric_criterion VALUES(11351,'psych12a1-cogn-31',NULL,0,'Deductive reasoning [1];',1,1);
INSERT INTO rubric_criterion VALUES(11352,'psych12a1-cogn-31',NULL,1,'it is valid because the conclusion must follow logically from the premises: if every student who passes has studied and Mia did not study, then Mia cannot have passed [1].',1,1);
INSERT INTO rubric_criterion VALUES(11353,'psych12a1-cogn-32',NULL,0,'Each stage involves a different kind of reasoning, not simply more information [1];',1,1);
INSERT INTO rubric_criterion VALUES(11354,'psych12a1-cogn-32',NULL,1,'each stage builds on and reorganises the structures of the previous stage rather than adding to them [1].',1,1);
INSERT INTO rubric_criterion VALUES(11355,'psych12a1-cogn-33',NULL,0,'The child sees a quantity transformed in appearance, and is then asked whether the amount is still the same [1];',1,1);
INSERT INTO rubric_criterion VALUES(11356,'psych12a1-cogn-33',NULL,1,'a child who says it is the same and gives a reason such as ''nothing was added or taken away'' or ''it can be changed back'' shows conservation [1].',1,1);
INSERT INTO rubric_criterion VALUES(11357,'psych12a1-cogn-34',NULL,0,'The theory emphasises that children are active learners and that teaching should match their stage of thinking [1];',1,1);
INSERT INTO rubric_criterion VALUES(11358,'psych12a1-cogn-34',NULL,1,'this helps teachers design hands-on activities suited to the child''s level rather than expecting abstract reasoning too early [1].',1,1);
INSERT INTO rubric_criterion VALUES(11359,'psych12a1-cogn-35',NULL,0,'Sensorimotor thinking is based on physical actions and sensory experience, whereas preoperational thinking involves the use of symbols and mental representations [1].',1,1);
INSERT INTO rubric_criterion VALUES(11360,'psych12a1-cogn-36',NULL,0,'Seriation, the systematic ordering of items along a dimension such as length, is not yet developed in preoperational children [1];',1,1);
INSERT INTO rubric_criterion VALUES(11361,'psych12a1-cogn-36',NULL,1,'the child cannot yet mentally compare and organise all the sticks, so the arrangement is random [1].',1,1);
INSERT INTO rubric_criterion VALUES(11364,'psych12a1-cogn-39',NULL,0,'A 12-year-old is in the formal operational stage, so can reason abstractly and systematically test combinations of variables [1];',1,1);
INSERT INTO rubric_criterion VALUES(11365,'psych12a1-cogn-39',NULL,1,'a 7-year-old is in the concrete operational stage, so reasoning is tied to concrete, observable objects and does not yet extend to systematic testing of many variables [1]',1,1);
INSERT INTO rubric_criterion VALUES(11372,'psych12a1-psyc-6',NULL,0,'A psychosocial crisis is a conflict between the individual''s psychological needs and the demands of society at each stage (1); successful resolution leads to a psychological strength or virtue (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11373,'psych12a1-psyc-6',NULL,1,'hope, will) (1);',1,1);
INSERT INTO rubric_criterion VALUES(11374,'psych12a1-psyc-6',NULL,2,'unsuccessful resolution may make later crises harder to resolve, though earlier crises can be revisited (1).',1,1);
INSERT INTO rubric_criterion VALUES(11375,'psych12a1-psyc-7',NULL,0,'The teenager is in the identity versus role confusion stage (1);',1,1);
INSERT INTO rubric_criterion VALUES(11376,'psych12a1-psyc-7',NULL,1,'exploring different roles, values and peer groups helps form a sense of self (1);',1,1);
INSERT INTO rubric_criterion VALUES(11377,'psych12a1-psyc-7',NULL,2,'if this goes well, a stable identity develops, otherwise they may experience role confusion and uncertainty about who they are (1).',1,1);
INSERT INTO rubric_criterion VALUES(11378,'psych12a1-psyc-8',NULL,0,'Piaget focuses on cognitive development (how thinking and reasoning develop through stages) (1);',1,1);
INSERT INTO rubric_criterion VALUES(11379,'psych12a1-psyc-8',NULL,1,'Erikson focuses on psychosocial development, the development of identity and social relationships through crises across the lifespan (1).',1,1);
INSERT INTO rubric_criterion VALUES(11396,'psych12a1-psyc-25',NULL,0,'Intimacy versus isolation is the young adult crisis of forming close, committed relationships with others [1];',1,1);
INSERT INTO rubric_criterion VALUES(11397,'psych12a1-psyc-25',NULL,1,'an unsuccessful resolution leads to loneliness, social withdrawal and difficulty trusting others in close relationships [1].',1,1);
INSERT INTO rubric_criterion VALUES(11398,'psych12a1-psyc-26',NULL,0,'Fidelity, the ability to commit to shared values, beliefs and relationships [1];',1,1);
INSERT INTO rubric_criterion VALUES(11399,'psych12a1-psyc-26',NULL,1,'this helps adults stay loyal to partners, friends and roles such as work and family [1].',1,1);
INSERT INTO rubric_criterion VALUES(11400,'psych12a1-psyc-27',NULL,0,'Eight stages [1];',1,1);
INSERT INTO rubric_criterion VALUES(11401,'psych12a1-psyc-27',NULL,1,'the first crisis is trust versus mistrust and the last is integrity versus despair [1].',1,1);
INSERT INTO rubric_criterion VALUES(11402,'psych12a1-psyc-28',NULL,0,'Initiative versus guilt occurs in the preschool years, about 3 to 5 years, and concerns planning and starting activities such as games [1];',1,1);
INSERT INTO rubric_criterion VALUES(11403,'psych12a1-psyc-28',NULL,1,'industry versus inferiority occurs in middle childhood, about 6 to 12 years, and concerns mastering skills, especially at school [1];',1,1);
INSERT INTO rubric_criterion VALUES(11404,'psych12a1-psyc-28',NULL,2,'successful initiative gives a sense of purpose, while successful industry gives a sense of competence [1].',1,1);
INSERT INTO rubric_criterion VALUES(11405,'psych12a1-psyc-29',NULL,0,'The theory was developed mainly from observations of individuals in Western societies [1];',1,1);
INSERT INTO rubric_criterion VALUES(11406,'psych12a1-psyc-29',NULL,1,'its emphasis on independence and an identity separate from family may not fit collectivist cultures, where identity is closely tied to family and community [1].',1,1);
INSERT INTO rubric_criterion VALUES(11407,'psych12a1-psyc-30',NULL,0,'Integrity versus despair is the final crisis, in late adulthood, when people review their lives [1];',1,1);
INSERT INTO rubric_criterion VALUES(11408,'psych12a1-psyc-30',NULL,1,'a sense of integrity results when people accept their life as meaningful and worthwhile [1];',1,1);
INSERT INTO rubric_criterion VALUES(11409,'psych12a1-psyc-30',NULL,2,'despair results when people regret missed opportunities and feel that life cannot be lived again [1].',1,1);
INSERT INTO rubric_criterion VALUES(11410,'psych12a1-psyc-31',NULL,0,'Autonomy versus shame and doubt occurs in toddlerhood, when children learn to do things for themselves and make choices [1];',1,1);
INSERT INTO rubric_criterion VALUES(11411,'psych12a1-psyc-31',NULL,1,'successful resolution produces will, the determination to exercise free choice [1].',1,1);
INSERT INTO rubric_criterion VALUES(11412,'psych12a1-psyc-32',NULL,0,'Identity development continues across the lifespan, so the adult can re-examine their values, beliefs and roles [1];',1,1);
INSERT INTO rubric_criterion VALUES(11413,'psych12a1-psyc-32',NULL,1,'changes such as a new job, a relationship or parenthood can prompt exploration and commitment to a clearer sense of self [1];',1,1);
INSERT INTO rubric_criterion VALUES(11414,'psych12a1-psyc-32',NULL,2,'a secure identity formed in adulthood can then strengthen commitments in relationships and career [1].',1,1);
INSERT INTO rubric_criterion VALUES(11415,'psych12a1-psyc-33',NULL,0,'Competence and skills gained through successful industry build confidence and self-esteem [1];',1,1);
INSERT INTO rubric_criterion VALUES(11416,'psych12a1-psyc-33',NULL,1,'this confidence allows adolescents to explore different roles and commit to a sense of who they are [1].',1,1);
INSERT INTO rubric_criterion VALUES(11417,'psych12a1-psyc-34',NULL,0,'Identity versus role confusion occurs in adolescence and intimacy versus isolation in young adulthood [1];',1,1);
INSERT INTO rubric_criterion VALUES(11418,'psych12a1-psyc-34',NULL,1,'identity asks ''Who am I?'' while intimacy asks ''Can I form close, committed relationships?'' [1];',1,1);
INSERT INTO rubric_criterion VALUES(11419,'psych12a1-psyc-34',NULL,2,'successful identity produces fidelity, while successful intimacy produces love [1];',1,1);
INSERT INTO rubric_criterion VALUES(11420,'psych12a1-psyc-34',NULL,3,'a secure identity provides the foundation for successful intimacy [1].',1,1);
INSERT INTO rubric_criterion VALUES(11424,'psych12a1-psyc-38',NULL,0,'A child who develops trust has learned that caregivers are reliable, so feels secure enough to explore and take risks [1];',1,1);
INSERT INTO rubric_criterion VALUES(11425,'psych12a1-psyc-38',NULL,1,'a child who has developed mistrust may be wary of new situations and less willing to try new experiences [1]',1,1);
INSERT INTO rubric_criterion VALUES(11426,'psych12a1-psyc-39',NULL,0,'The crisis is industry versus inferiority [1];',1,1);
INSERT INTO rubric_criterion VALUES(11427,'psych12a1-psyc-39',NULL,1,'because her successes depend on help, she may not develop a sense of competence and may feel inferior to her peers [1];',1,1);
INSERT INTO rubric_criterion VALUES(11428,'psych12a1-psyc-39',NULL,2,'a likely outcome is reduced confidence and reluctance to attempt tasks independently [1]',1,1);
INSERT INTO rubric_criterion VALUES(11435,'psych12a1-typi-6',NULL,0,'Atypical behaviour is behaviour that is uncommon or differs from the norm, but it may not harm the person or interfere with functioning (1);',1,1);
INSERT INTO rubric_criterion VALUES(11436,'psych12a1-typi-6',NULL,1,'it can be adaptive or beneficial (1);',1,1);
INSERT INTO rubric_criterion VALUES(11437,'psych12a1-typi-6',NULL,2,'Example: a person with exceptional musical talent or someone who lives a very different lifestyle but functions well and is content (1).',1,1);
INSERT INTO rubric_criterion VALUES(11438,'psych12a1-typi-7',NULL,0,'Typical and atypical behaviour is judged relative to cultural norms (1);',1,1);
INSERT INTO rubric_criterion VALUES(11439,'psych12a1-typi-7',NULL,1,'the same behaviour may be considered typical in one culture and atypical in another (1);',1,1);
INSERT INTO rubric_criterion VALUES(11440,'psych12a1-typi-7',NULL,2,'so behaviour should be assessed in the cultural and social context, and not by one culture''s standards (1).',1,1);
INSERT INTO rubric_criterion VALUES(11441,'psych12a1-typi-8',NULL,0,'Any two: the behaviour is atypical for the person''s age, culture and context (1); it causes distress to the person or others (1); it is maladaptive or interferes with daily functioning (1);',1,1);
INSERT INTO rubric_criterion VALUES(11442,'psych12a1-typi-8',NULL,1,'it persists over time or is severe in intensity (1). Maximum 2 marks.',1,1);
INSERT INTO rubric_criterion VALUES(11458,'psych12a1-typi-24',NULL,0,'Ethnocentrism [1]',1,1);
INSERT INTO rubric_criterion VALUES(11459,'psych12a1-typi-25',NULL,0,'15 ÷ 500 × 100 = 3% [1];',1,1);
INSERT INTO rubric_criterion VALUES(11460,'psych12a1-typi-25',NULL,1,'the behaviour is statistically uncommon (infrequent) in this group [1]',1,1);
INSERT INTO rubric_criterion VALUES(11461,'psych12a1-typi-26',NULL,0,'A brief response to a stressful event is usually expected, whereas a behaviour that continues for a long time is more likely to indicate an ongoing problem [1];',1,1);
INSERT INTO rubric_criterion VALUES(11462,'psych12a1-typi-26',NULL,1,'persistence suggests the behaviour may be affecting functioning beyond the situation that triggered it [1]',1,1);
INSERT INTO rubric_criterion VALUES(11463,'psych12a1-typi-27',NULL,0,'Typical behaviour is judged against age-based developmental expectations, so the same ability is expected at different ages [1];',1,1);
INSERT INTO rubric_criterion VALUES(11464,'psych12a1-typi-27',NULL,1,'a sixteen-year-old is expected to read fluently, so the difficulty is unusual for their age [1]',1,1);
INSERT INTO rubric_criterion VALUES(11465,'psych12a1-typi-28',NULL,0,'A single atypical behaviour does not show distress, impaired functioning or persistence, so the label may not be accurate [1];',1,1);
INSERT INTO rubric_criterion VALUES(11466,'psych12a1-typi-28',NULL,1,'labels can lead to stigma and discrimination from others [1];',1,1);
INSERT INTO rubric_criterion VALUES(11467,'psych12a1-typi-28',NULL,2,'a label may change how the person sees themselves and affect their relationships, self-esteem or opportunities [1]',1,1);
INSERT INTO rubric_criterion VALUES(11468,'psych12a1-typi-29',NULL,0,'The continuum shows a range of states rather than a simple healthy or unhealthy split [1];',1,1);
INSERT INTO rubric_criterion VALUES(11469,'psych12a1-typi-29',NULL,1,'a person can move along it over time, for example from flourishing to a mental health problem after a stressful event [1];',1,1);
INSERT INTO rubric_criterion VALUES(11470,'psych12a1-typi-29',NULL,2,'with support they can move back towards wellbeing [1]',1,1);
INSERT INTO rubric_criterion VALUES(11471,'psych12a1-typi-30',NULL,0,'Whether a behaviour is adaptive depends on the person''s circumstances, goals and context [1];',1,1);
INSERT INTO rubric_criterion VALUES(11472,'psych12a1-typi-30',NULL,1,'e.g., working long hours may be adaptive for a person whose job requires it and who has time for rest, but maladaptive for a person who is exhausted and neglecting their health [1];',1,1);
INSERT INTO rubric_criterion VALUES(11473,'psych12a1-typi-30',NULL,2,'judgements should focus on the effect on the person''s functioning and wellbeing [1]',1,1);
INSERT INTO rubric_criterion VALUES(11474,'psych12a1-typi-31',NULL,0,'Distress can be a typical response to events such as loss, illness or exam stress [1];',1,1);
INSERT INTO rubric_criterion VALUES(11475,'psych12a1-typi-31',NULL,1,'a behaviour is a concern when distress is combined with other criteria such as impaired functioning, persistence or severity [1];',1,1);
INSERT INTO rubric_criterion VALUES(11476,'psych12a1-typi-31',NULL,2,'whether it is atypical also depends on the person''s age, culture and context [1]',1,1);
INSERT INTO rubric_criterion VALUES(11477,'psych12a1-typi-32',NULL,0,'Her behaviour is a marked change from her usual pattern and atypical for her age [1];',1,1);
INSERT INTO rubric_criterion VALUES(11478,'psych12a1-typi-32',NULL,1,'she reports distress, feeling sad and tired most days [1];',1,1);
INSERT INTO rubric_criterion VALUES(11479,'psych12a1-typi-32',NULL,2,'it interferes with her functioning at school and in sport [1];',1,1);
INSERT INTO rubric_criterion VALUES(11480,'psych12a1-typi-32',NULL,3,'it has persisted for three months, so it is a cause for concern and warrants support from a professional [1]',1,1);
INSERT INTO rubric_criterion VALUES(11484,'psych12a1-typi-36',NULL,0,'A criterion such as harm, dysfunction or distress [1];',1,1);
INSERT INTO rubric_criterion VALUES(11485,'psych12a1-typi-36',NULL,1,'it considers the impact on the person and others, rather than only how rare the behaviour is, so harmless rare behaviours are not labelled as problems [1]',1,1);
INSERT INTO rubric_criterion VALUES(11486,'psych12a1-typi-37',NULL,0,'The clinician should consider whether the behaviour is typical within the client''s cultural group rather than judging it by the clinician''s own norms [1];',1,1);
INSERT INTO rubric_criterion VALUES(11487,'psych12a1-typi-37',NULL,1,'the behaviour may be adaptive and expected within her family norms, so it should not be labelled atypical without further context [1];',1,1);
INSERT INTO rubric_criterion VALUES(11488,'psych12a1-typi-37',NULL,2,'the clinician should still assess whether it causes distress or impairment in her daily life [1]',1,1);
INSERT INTO rubric_criterion VALUES(11489,'psych12a1-typi-38',NULL,0,'Duration: the behaviour has lasted five weeks, which is longer than a temporary reaction [1];',1,1);
INSERT INTO rubric_criterion VALUES(11490,'psych12a1-typi-38',NULL,1,'dysfunction: it prevents the child from attending school and taking part in family life [1]',1,1);
INSERT INTO rubric_criterion VALUES(11497,'psych12a2-mw-6',NULL,0,'Categorical approach: a disorder is diagnosed as present or absent when a person meets a set of specified criteria (e.g. DSM-5-TR);',1,1);
INSERT INTO rubric_criterion VALUES(11498,'psych12a2-mw-6',NULL,1,'dimensional approach: symptoms are rated along a continuum of severity, so people differ in degree rather than kind; one valid difference in use, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11499,'psych12a2-mw-6',NULL,2,'categorical gives a clear diagnosis that guides treatment, while dimensional captures severity and sub-threshold cases.',1,1);
INSERT INTO rubric_criterion VALUES(11500,'psych12a2-mw-7',NULL,0,'Mia is likely flourishing; she shows positive emotional, social and psychological functioning (social connection, coping, personal growth);',1,1);
INSERT INTO rubric_criterion VALUES(11501,'psych12a2-mw-7',NULL,1,'Jo is likely languishing;',1,1);
INSERT INTO rubric_criterion VALUES(11502,'psych12a2-mw-7',NULL,2,'low emotional and social wellbeing even without a diagnosed disorder shows that mental health is not just the absence of disorder.',1,1);
INSERT INTO rubric_criterion VALUES(11503,'psych12a2-mw-8',NULL,0,'Mental health is a continuum and wellbeing varies over time and across emotional, social and cognitive domains;',1,1);
INSERT INTO rubric_criterion VALUES(11504,'psych12a2-mw-8',NULL,1,'with effective treatment, supports and coping strategies, a person with a disorder can function well and report positive wellbeing, so disorder and wellbeing are not opposites.',1,1);
INSERT INTO rubric_criterion VALUES(11524,'psych12a2-mw-28',NULL,0,'The co-occurrence of two or more mental disorders in the same person at the same time [1]',1,1);
INSERT INTO rubric_criterion VALUES(11525,'psych12a2-mw-29',NULL,0,'A provisional diagnosis is recorded when a disorder is strongly suspected but there is insufficient information to confirm all criteria [1];',1,1);
INSERT INTO rubric_criterion VALUES(11526,'psych12a2-mw-29',NULL,1,'for example, symptoms are present but their duration cannot yet be established [1]',1,1);
INSERT INTO rubric_criterion VALUES(11527,'psych12a2-mw-30',NULL,0,'Self-acceptance, e.g. holding a positive view of oneself and one''s past [1];',1,1);
INSERT INTO rubric_criterion VALUES(11528,'psych12a2-mw-30',NULL,1,'purpose in life, e.g. having goals that give one''s life direction and meaning [1]',1,1);
INSERT INTO rubric_criterion VALUES(11529,'psych12a2-mw-31',NULL,0,'Reliability means different clinicians reach the same diagnosis for the same person [1];',1,1);
INSERT INTO rubric_criterion VALUES(11530,'psych12a2-mw-31',NULL,1,'validity means the classification accurately describes the disorder it names [1];',1,1);
INSERT INTO rubric_criterion VALUES(11531,'psych12a2-mw-31',NULL,2,'without both, people may receive inconsistent or inaccurate diagnoses and inappropriate treatment [1]',1,1);
INSERT INTO rubric_criterion VALUES(11532,'psych12a2-mw-32',NULL,0,'Advantage: clear criteria give a diagnosis that supports consistent communication between clinicians [1];',1,1);
INSERT INTO rubric_criterion VALUES(11533,'psych12a2-mw-32',NULL,1,'advantage: a clear diagnosis can guide treatment decisions and eligibility for services [1];',1,1);
INSERT INTO rubric_criterion VALUES(11534,'psych12a2-mw-32',NULL,2,'limitation: people just below the threshold may be excluded, so their severity is ignored [1];',1,1);
INSERT INTO rubric_criterion VALUES(11535,'psych12a2-mw-32',NULL,3,'limitation: labels can oversimplify a complex experience and may create stigma [1]',1,1);
INSERT INTO rubric_criterion VALUES(11536,'psych12a2-mw-33',NULL,0,'The degree or severity of symptoms along a continuum [1];',1,1);
INSERT INTO rubric_criterion VALUES(11537,'psych12a2-mw-33',NULL,1,'changes over time, such as improvement or worsening, including people below a diagnostic cut-off who still have significant difficulties [1]',1,1);
INSERT INTO rubric_criterion VALUES(11538,'psych12a2-mw-34',NULL,0,'A categorical approach would not diagnose major depressive disorder, because Jade has four symptoms and five are required [1];',1,1);
INSERT INTO rubric_criterion VALUES(11539,'psych12a2-mw-34',NULL,1,'a dimensional approach would rate the severity of her symptoms, for example as mild to moderate [1];',1,1);
INSERT INTO rubric_criterion VALUES(11540,'psych12a2-mw-34',NULL,2,'this captures her real difficulties and allows her progress to be tracked over time [1]',1,1);
INSERT INTO rubric_criterion VALUES(11541,'psych12a2-mw-35',NULL,0,'Symptoms and distress may be expressed differently across cultures [1];',1,1);
INSERT INTO rubric_criterion VALUES(11542,'psych12a2-mw-35',NULL,1,'some beliefs or idioms of distress are culturally normal, so a clinician may mistake them for a disorder or miss a disorder [1]',1,1);
INSERT INTO rubric_criterion VALUES(11543,'psych12a2-mw-36',NULL,0,'Emotional wellbeing [1]',1,1);
INSERT INTO rubric_criterion VALUES(11544,'psych12a2-mw-37',NULL,0,'Social wellbeing is most affected [1];',1,1);
INSERT INTO rubric_criterion VALUES(11545,'psych12a2-mw-37',NULL,1,'he lacks social integration, as he does not feel he belongs to any community [1];',1,1);
INSERT INTO rubric_criterion VALUES(11546,'psych12a2-mw-37',NULL,2,'his social contribution is low, as he believes he has nothing useful to offer others [1]',1,1);
INSERT INTO rubric_criterion VALUES(11547,'psych12a2-mw-38',NULL,0,'A categorical diagnosis gives a clear classification for communication, service access and treatment guidelines [1];',1,1);
INSERT INTO rubric_criterion VALUES(11548,'psych12a2-mw-38',NULL,1,'a dimensional rating captures the severity of symptoms and how they change over time [1];',1,1);
INSERT INTO rubric_criterion VALUES(11549,'psych12a2-mw-38',NULL,2,'used together, the clinician can diagnose and also track severity for the same client [1];',1,1);
INSERT INTO rubric_criterion VALUES(11550,'psych12a2-mw-38',NULL,3,'benefit: a fuller picture guides treatment choices and allows progress to be monitored [1]',1,1);
INSERT INTO rubric_criterion VALUES(11558,'psych12a2-pp-6',NULL,0,'Dispositional attribution: behaviour explained by internal characteristics such as personality, ability or attitudes; situational attribution: behaviour explained by external factors such as circumstances, other people or the environment;',1,1);
INSERT INTO rubric_criterion VALUES(11559,'psych12a2-pp-6',NULL,1,'two appropriate examples, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11560,'psych12a2-pp-6',NULL,2,'''he is rude'' (dispositional) vs ''he was stressed by a deadline'' (situational).',1,1);
INSERT INTO rubric_criterion VALUES(11561,'psych12a2-pp-7',NULL,0,'Actor-observer bias (a form of the fundamental attribution error when judging others); we explain others'' behaviour dispositionally (unpleasant person);',1,1);
INSERT INTO rubric_criterion VALUES(11562,'psych12a2-pp-7',NULL,1,'we explain our own behaviour situationally (being exhausted);',1,1);
INSERT INTO rubric_criterion VALUES(11563,'psych12a2-pp-7',NULL,2,'we have more access to our own situational context than to others''.',1,1);
INSERT INTO rubric_criterion VALUES(11564,'psych12a2-pp-8',NULL,0,'An interviewer''s unfavourable first impression of one trait (e.g. appearance, nervousness or accent) can generalise to unrelated traits;',1,1);
INSERT INTO rubric_criterion VALUES(11565,'psych12a2-pp-8',NULL,1,'the applicant may be rated as less competent or reliable than their actual skills warrant, so they are unfairly judged.',1,1);
INSERT INTO rubric_criterion VALUES(11584,'psych12a2-pp-27',NULL,0,'Vivid, widely reported accidents come to mind easily, so the driver overestimates how common such accidents are among the brand''s drivers [1];',1,1);
INSERT INTO rubric_criterion VALUES(11585,'psych12a2-pp-27',NULL,1,'the judgement ignores base rates, so it is biased and inaccurate [1].',1,1);
INSERT INTO rubric_criterion VALUES(11586,'psych12a2-pp-28',NULL,0,'The teacher''s expectation shapes how they treat the student, reducing opportunities and feedback [1];',1,1);
INSERT INTO rubric_criterion VALUES(11587,'psych12a2-pp-28',NULL,1,'the student responds to these cues with lower confidence and effort, so their results decline [1];',1,1);
INSERT INTO rubric_criterion VALUES(11588,'psych12a2-pp-28',NULL,2,'the decline appears to confirm the original expectation, creating a self-reinforcing cycle [1];',1,1);
INSERT INTO rubric_criterion VALUES(11589,'psych12a2-pp-28',NULL,3,'the cycle could be broken by the teacher giving the student challenging tasks and feedback, or by the student being shown evidence that contradicts the expectation [1].',1,1);
INSERT INTO rubric_criterion VALUES(11590,'psych12a2-pp-29',NULL,0,'The strong opening is early information, which is given more weight in forming the overall impression [1];',1,1);
INSERT INTO rubric_criterion VALUES(11591,'psych12a2-pp-29',NULL,1,'the marker interprets the later, weaker paragraphs in light of that favourable first impression, so their weaknesses are underweighted [1];',1,1);
INSERT INTO rubric_criterion VALUES(11592,'psych12a2-pp-29',NULL,2,'the mark therefore does not accurately reflect the whole essay [1].',1,1);
INSERT INTO rubric_criterion VALUES(11593,'psych12a2-pp-30',NULL,0,'The student worries that poor performance will confirm the stereotype, which creates anxiety and pressure [1];',1,1);
INSERT INTO rubric_criterion VALUES(11594,'psych12a2-pp-30',NULL,1,'this anxiety uses up attention and working memory, lowering performance on the test [1].',1,1);
INSERT INTO rubric_criterion VALUES(11595,'psych12a2-pp-31',NULL,0,'The observer believes people get what they deserve, so the victim must have done something to bring the robbery on [1];',1,1);
INSERT INTO rubric_criterion VALUES(11596,'psych12a2-pp-31',NULL,1,'blaming the victim protects the observer''s belief that the world is fair and that similar misfortune can be avoided [1].',1,1);
INSERT INTO rubric_criterion VALUES(11597,'psych12a2-pp-32',NULL,0,'A non-verbal cue such as eye contact or tone of voice [1];',1,1);
INSERT INTO rubric_criterion VALUES(11598,'psych12a2-pp-32',NULL,1,'steady eye contact may lead the interviewer to judge the applicant as confident and honest, making the impression more favourable [1].',1,1);
INSERT INTO rubric_criterion VALUES(11599,'psych12a2-pp-33',NULL,0,'The coach notices and remembers the player''s mistakes because they fit the belief [1];',1,1);
INSERT INTO rubric_criterion VALUES(11600,'psych12a2-pp-33',NULL,1,'the coach overlooks or discounts good plays that contradict it [1];',1,1);
INSERT INTO rubric_criterion VALUES(11601,'psych12a2-pp-33',NULL,2,'the belief is therefore maintained despite balanced evidence, so the evaluation is biased [1].',1,1);
INSERT INTO rubric_criterion VALUES(11602,'psych12a2-pp-34',NULL,0,'Outgroup homogeneity: members of the outgroup are seen as all alike, so one negative example is generalised to the whole group [1];',1,1);
INSERT INTO rubric_criterion VALUES(11603,'psych12a2-pp-34',NULL,1,'ultimate attribution error: negative behaviour by outgroup members is attributed to their dispositions, while the same behaviour by ingroup members is excused as situational [1];',1,1);
INSERT INTO rubric_criterion VALUES(11604,'psych12a2-pp-34',NULL,2,'negative outgroup behaviour is therefore seen as typical and inherent, while ingroup failings are explained away [1];',1,1);
INSERT INTO rubric_criterion VALUES(11605,'psych12a2-pp-34',NULL,3,'individual counter-examples are dismissed as exceptions, so the prejudice resists contrary evidence [1].',1,1);
INSERT INTO rubric_criterion VALUES(11606,'psych12a2-pp-35',NULL,0,'A positive mood can lead the person to interpret the stranger''s ambiguous behaviour more favourably [1];',1,1);
INSERT INTO rubric_criterion VALUES(11607,'psych12a2-pp-35',NULL,1,'a negative mood can lead to more unfavourable judgements, so the impression reflects the perceiver''s state as well as the stranger''s behaviour [1].',1,1);
INSERT INTO rubric_criterion VALUES(11609,'psych12a2-pp-37',NULL,0,'The tendency to attribute successes to internal, dispositional factors and failures to external, situational factors, which protects self-esteem [1];',1,1);
INSERT INTO rubric_criterion VALUES(11610,'psych12a2-pp-37',NULL,1,'for example, a student who does well credits her ability, but blames an unfair test when she does poorly [1]',1,1);
INSERT INTO rubric_criterion VALUES(11611,'psych12a2-pp-38',NULL,0,'The representativeness heuristic, in which a person is judged by how closely they match a stereotype or prototype of a group [1];',1,1);
INSERT INTO rubric_criterion VALUES(11612,'psych12a2-pp-38',NULL,1,'the owner ignores the applicant''s qualifications and work history, which are better evidence of ability [1];',1,1);
INSERT INTO rubric_criterion VALUES(11613,'psych12a2-pp-38',NULL,2,'this could lead to rejecting a capable applicant for irrelevant reasons [1]',1,1);
INSERT INTO rubric_criterion VALUES(11620,'psych12a2-ad-6',NULL,0,'Cognitive: beliefs or thoughts about the object (e.g. recycling reduces landfill);',1,1);
INSERT INTO rubric_criterion VALUES(11621,'psych12a2-ad-6',NULL,1,'affective: feelings about it (e.g. feeling proud or good about recycling);',1,1);
INSERT INTO rubric_criterion VALUES(11622,'psych12a2-ad-6',NULL,2,'behavioural: how the person acts or intends to act (e.g. sorting rubbish into the recycling bin).',1,1);
INSERT INTO rubric_criterion VALUES(11623,'psych12a2-ad-7',NULL,0,'She experiences dissonance (psychological discomfort) because her behaviour conflicts with her attitude about honesty; reduction by changing the attitude (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11624,'psych12a2-ad-7',NULL,1,'''white lies are kind''), adding a new cognition (it avoided hurting her friend) or changing behaviour (telling the friend the truth);',1,1);
INSERT INTO rubric_criterion VALUES(11625,'psych12a2-ad-7',NULL,2,'one strategy clearly linked to the scenario.',1,1);
INSERT INTO rubric_criterion VALUES(11626,'psych12a2-ad-8',NULL,0,'Behaviour can be shaped by situational factors such as social pressure, cost or convenience;',1,1);
INSERT INTO rubric_criterion VALUES(11627,'psych12a2-ad-8',NULL,1,'attitudes may be weak or conflicting across components, or the person may not have the opportunity or ability to act on them.',1,1);
INSERT INTO rubric_criterion VALUES(11646,'psych12a2-ad-27',NULL,0,'A message that only presents facts engages only the cognitive component, which may be insufficient because attitudes are also driven by emotion [1];',1,1);
INSERT INTO rubric_criterion VALUES(11647,'psych12a2-ad-27',NULL,1,'an appeal to feelings such as guilt or fear engages the affective component and can motivate action [1];',1,1);
INSERT INTO rubric_criterion VALUES(11648,'psych12a2-ad-27',NULL,2,'a stronger affective response makes it more likely that the behavioural component (intention to act) will change [1].',1,1);
INSERT INTO rubric_criterion VALUES(11649,'psych12a2-ad-28',NULL,0,'Her behaviour (helping) conflicts with her belief that hunting is cruel, creating cognitive dissonance [1]; the family request provides external justification, which may ease the tension somewhat [1];',1,1);
INSERT INTO rubric_criterion VALUES(11650,'psych12a2-ad-28',NULL,1,'she could change her attitude, e.g. by deciding that hunting is a tradition that is not truly cruel [1];',1,1);
INSERT INTO rubric_criterion VALUES(11651,'psych12a2-ad-28',NULL,2,'or she could change her behaviour or add a new cognition, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11652,'psych12a2-ad-28',NULL,3,'by telling herself she helped only to support her family and declining future events [1].',1,1);
INSERT INTO rubric_criterion VALUES(11653,'psych12a2-ad-29',NULL,0,'A reason outside the person, such as a reward or pressure from others, that explains why they acted against their attitude, so less dissonance is felt [1].',1,1);
INSERT INTO rubric_criterion VALUES(11654,'psych12a2-ad-30',NULL,0,'She feels tension because the new information conflicts with her decision to buy the phone [1];',1,1);
INSERT INTO rubric_criterion VALUES(11655,'psych12a2-ad-30',NULL,1,'she could reduce it by focusing on the strengths of her phone and devaluing the competitor''s model [1].',1,1);
INSERT INTO rubric_criterion VALUES(11656,'psych12a2-ad-31',NULL,0,'The person may hold beliefs that public transport is cheap and efficient (cognitive) [1];',1,1);
INSERT INTO rubric_criterion VALUES(11657,'psych12a2-ad-31',NULL,1,'while also feeling anxious or annoyed about crowded trains (affective), so the two components do not match [1].',1,1);
INSERT INTO rubric_criterion VALUES(11658,'psych12a2-ad-32',NULL,0,'Acting in a way that conflicts with a belief creates dissonance, so the person may change the belief to match the action [1]; e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11659,'psych12a2-ad-32',NULL,1,'someone who spends heavily on a brand comes to believe its products are superior to those of other brands [1].',1,1);
INSERT INTO rubric_criterion VALUES(11660,'psych12a2-ad-33',NULL,0,'The child watches and imitates models, such as parents or teachers, who read enthusiastically [1]; the child sees reading valued or enjoyed and so adopts the attitude (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11661,'psych12a2-ad-33',NULL,1,'wanting to read because a parent visibly enjoys books) [1].',1,1);
INSERT INTO rubric_criterion VALUES(11662,'psych12a2-ad-34',NULL,0,'Behavioural component [1].',1,1);
INSERT INTO rubric_criterion VALUES(11669,'psych12a2-sp-6',NULL,0,'Prejudice: an unjustified, usually negative, attitude or feeling towards people because of their group membership; discrimination: unfair behaviour or treatment of people because of their group membership;',1,1);
INSERT INTO rubric_criterion VALUES(11670,'psych12a2-sp-6',NULL,1,'examples, e.g. disliking colleagues who wear a hijab (prejudice) vs.',1,1);
INSERT INTO rubric_criterion VALUES(11671,'psych12a2-sp-6',NULL,2,'not promoting them because of it (discrimination).',1,1);
INSERT INTO rubric_criterion VALUES(11672,'psych12a2-sp-7',NULL,0,'Stereotypes and prejudice can lead to discriminatory behaviour even when applicants'' qualifications are identical; the employers'' beliefs affected who was selected;',1,1);
INSERT INTO rubric_criterion VALUES(11673,'psych12a2-sp-7',NULL,1,'strategy, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11674,'psych12a2-sp-7',NULL,2,'blind CV screening, cooperative contact, or diversity training that challenges stereotypes.',1,1);
INSERT INTO rubric_criterion VALUES(11675,'psych12a2-sp-8',NULL,0,'People notice and remember information that supports the stereotype (confirmation of belief) while ignoring exceptions;',1,1);
INSERT INTO rubric_criterion VALUES(11676,'psych12a2-sp-8',NULL,1,'this reinforces the belief and may shape behaviour towards the group in ways that elicit stereotype-consistent responses.',1,1);
INSERT INTO rubric_criterion VALUES(11695,'psych12a2-sp-27',NULL,0,'A social group that a person does not belong to, which is often perceived as different from, and less favourably than, their own in-group. [1]',1,1);
INSERT INTO rubric_criterion VALUES(11696,'psych12a2-sp-28',NULL,0,'People overestimate the link between rare, distinctive behaviours and a minority group, because such pairings stand out in memory. [1] This leads people to believe the group is associated with that behaviour, which becomes a stereotype.',1,1);
INSERT INTO rubric_criterion VALUES(11697,'psych12a2-sp-28',NULL,1,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(11698,'psych12a2-sp-29',NULL,0,'Members of an out-group are seen as more alike than members of the in-group, so individual differences are overlooked. [1] This makes it easier to apply one negative belief to all out-group members, supporting prejudice.',1,1);
INSERT INTO rubric_criterion VALUES(11699,'psych12a2-sp-29',NULL,1,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(11700,'psych12a2-sp-30',NULL,0,'Direct discrimination: a person or organisation deliberately treats someone less favourably because of their group membership, e.g. refusing to hire someone because of their religion. [1] Institutional discrimination: a policy or practice that appears neutral disadvantages a group regardless of intent, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11701,'psych12a2-sp-30',NULL,1,'a roster that excludes people with caring responsibilities. [1] Both produce unfair outcomes based on group membership;',1,1);
INSERT INTO rubric_criterion VALUES(11702,'psych12a2-sp-30',NULL,2,'the key difference is intent. [1]',1,1);
INSERT INTO rubric_criterion VALUES(11703,'psych12a2-sp-31',NULL,0,'Individuating information gives specific personal details that the stereotype does not describe. [1] Because a stereotype is a generalisation, this makes it less likely to be applied to the person.',1,1);
INSERT INTO rubric_criterion VALUES(11704,'psych12a2-sp-31',NULL,1,'[1] Judgements then rely on the person''s own characteristics rather than their group membership.',1,1);
INSERT INTO rubric_criterion VALUES(11705,'psych12a2-sp-31',NULL,2,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(11706,'psych12a2-sp-32',NULL,0,'Recategorisation places members of both groups within a shared, superordinate category, so they are seen as one in-group. [1] Former out-group members are then evaluated more favourably as part of the shared group.',1,1);
INSERT INTO rubric_criterion VALUES(11707,'psych12a2-sp-32',NULL,1,'[1] This weakens the us-versus-them boundary, reducing prejudice and in-group bias.',1,1);
INSERT INTO rubric_criterion VALUES(11708,'psych12a2-sp-32',NULL,2,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(11709,'psych12a2-sp-33',NULL,0,'Categorisation: people sort themselves and others into groups, creating in-groups and out-groups. [1] Identification: people adopt their group''s identity, which becomes part of their self-concept.',1,1);
INSERT INTO rubric_criterion VALUES(11710,'psych12a2-sp-33',NULL,1,'[1] Comparison: people compare their in-group with out-groups and evaluate their own group more positively to protect self-esteem, leading to favouritism.',1,1);
INSERT INTO rubric_criterion VALUES(11711,'psych12a2-sp-33',NULL,2,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(11712,'psych12a2-sp-34',NULL,0,'Laws target the behavioural component by making discriminatory actions illegal. [1] Prejudice also has affective (feelings) and cognitive (stereotype) components, which laws do not directly change.',1,1);
INSERT INTO rubric_criterion VALUES(11713,'psych12a2-sp-34',NULL,1,'[1] A person may stop discriminating while still holding negative feelings and stereotypes, so prejudice can persist.',1,1);
INSERT INTO rubric_criterion VALUES(11714,'psych12a2-sp-34',NULL,2,'[1] Interventions that change beliefs and feelings, such as education and positive contact, are needed to address these components.',1,1);
INSERT INTO rubric_criterion VALUES(11715,'psych12a2-sp-34',NULL,3,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(11716,'psych12a2-sp-35',NULL,0,'Competition for scarce resources creates real conflicts of interest between the groups. [1] Groups come to see each other as rivals, increasing hostility and negative stereotypes of the out-group.',1,1);
INSERT INTO rubric_criterion VALUES(11717,'psych12a2-sp-35',NULL,1,'[1] Realistic group conflict theory predicts that prejudice increases as competition intensifies.',1,1);
INSERT INTO rubric_criterion VALUES(11718,'psych12a2-sp-35',NULL,2,'[1] A strategy such as introducing superordinate goals that require both groups to cooperate can reduce the conflict.',1,1);
INSERT INTO rubric_criterion VALUES(11719,'psych12a2-sp-35',NULL,3,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(11720,'psych12a2-sp-36',NULL,0,'Believing that people get what they deserve leads people to see members of a disadvantaged group as responsible for their own misfortune. [1] This justifies unfair treatment or indifference towards the group, supporting prejudice and discrimination.',1,1);
INSERT INTO rubric_criterion VALUES(11721,'psych12a2-sp-36',NULL,1,'[1]',1,1);
INSERT INTO rubric_criterion VALUES(11728,'psych12a2-hc-6',NULL,0,'Cognitive bias: a systematic error in thinking or judgement that can affect decisions; heuristic: a mental shortcut or rule of thumb used to make quick decisions;',1,1);
INSERT INTO rubric_criterion VALUES(11729,'psych12a2-hc-6',NULL,1,'heuristics are the strategies and biases are the systematic errors that can result, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11730,'psych12a2-hc-6',NULL,2,'availability heuristic causing overestimation of vivid events.',1,1);
INSERT INTO rubric_criterion VALUES(11731,'psych12a2-hc-7',NULL,0,'Availability heuristic;',1,1);
INSERT INTO rubric_criterion VALUES(11732,'psych12a2-hc-7',NULL,1,'the vivid crash coverage makes plane crashes easy to recall, so he overestimates their probability;',1,1);
INSERT INTO rubric_criterion VALUES(11733,'psych12a2-hc-7',NULL,2,'statistically driving is riskier per distance travelled, so the decision relies on a biased estimate rather than actual risk.',1,1);
INSERT INTO rubric_criterion VALUES(11734,'psych12a2-hc-8',NULL,0,'Advantage: fast and efficient, saving time and cognitive effort when information is limited; disadvantage: can lead to errors or biased judgements, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11735,'psych12a2-hc-8',NULL,1,'ignoring base rates or overestimating vivid events.',1,1);
INSERT INTO rubric_criterion VALUES(11753,'psych12a2-hc-26',NULL,0,'The first salary figure offered acts as an anchor or reference point [1];',1,1);
INSERT INTO rubric_criterion VALUES(11754,'psych12a2-hc-26',NULL,1,'later offers and the final agreement are adjusted insufficiently away from that figure, so the outcome is pulled towards it [1].',1,1);
INSERT INTO rubric_criterion VALUES(11755,'psych12a2-hc-27',NULL,0,'Hindsight bias [1].',1,1);
INSERT INTO rubric_criterion VALUES(11756,'psych12a2-hc-28',NULL,0,'Representativeness heuristic: the diagnosis is judged by how closely the symptoms resemble the doctor''s prototype of the virus [1];',1,1);
INSERT INTO rubric_criterion VALUES(11757,'psych12a2-hc-28',NULL,1,'base rate (prevalence) information is ignored, so the likelihood of this rare virus is overestimated [1];',1,1);
INSERT INTO rubric_criterion VALUES(11758,'psych12a2-hc-28',NULL,2,'the judgement relies on resemblance rather than the statistical probability of the illness [1].',1,1);
INSERT INTO rubric_criterion VALUES(11759,'psych12a2-hc-29',NULL,0,'Sunk cost fallacy [1];',1,1);
INSERT INTO rubric_criterion VALUES(11760,'psych12a2-hc-29',NULL,1,'her decision is driven by past, unrecoverable costs rather than the expected future costs and benefits [1];',1,1);
INSERT INTO rubric_criterion VALUES(11761,'psych12a2-hc-29',NULL,2,'past investment should be irrelevant to whether further investment is worthwhile [1];',1,1);
INSERT INTO rubric_criterion VALUES(11762,'psych12a2-hc-29',NULL,3,'a strategy such as evaluating only future prospects or seeking an independent, objective review [1].',1,1);
INSERT INTO rubric_criterion VALUES(11763,'psych12a2-hc-30',NULL,0,'When only one option is recognised, that option is chosen [1];',1,1);
INSERT INTO rubric_criterion VALUES(11764,'psych12a2-hc-30',NULL,1,'this can be accurate because recognition often correlates with the quantity being judged, such as a city''s population [1];',1,1);
INSERT INTO rubric_criterion VALUES(11765,'psych12a2-hc-30',NULL,2,'it fails when recognition reflects factors unrelated to the judged criterion, such as a small town being well known because of a famous sporting team [1].',1,1);
INSERT INTO rubric_criterion VALUES(11766,'psych12a2-hc-31',NULL,0,'The overall frequency or proportion of a condition or event in a population, which should inform judgements about an individual case [1].',1,1);
INSERT INTO rubric_criterion VALUES(11767,'psych12a2-hc-32',NULL,0,'The tendency to overestimate how many other people share one''s own beliefs, attitudes or behaviours [1];',1,1);
INSERT INTO rubric_criterion VALUES(11768,'psych12a2-hc-32',NULL,1,'the person treats their own views as typical of the majority [1];',1,1);
INSERT INTO rubric_criterion VALUES(11769,'psych12a2-hc-32',NULL,2,'this can lead to misperceiving social norms, such as believing most people support a policy simply because the person does [1];',1,1);
INSERT INTO rubric_criterion VALUES(11770,'psych12a2-hc-32',NULL,3,'it can also lead to inaccurate predictions of others'' behaviour and a reduced understanding of differing views [1].',1,1);
INSERT INTO rubric_criterion VALUES(11771,'psych12a2-hc-33',NULL,0,'The belief that one can influence outcomes that are actually determined by chance [1]; e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11772,'psych12a2-hc-33',NULL,1,'a player who believes that choosing ''lucky'' numbers improves their chance of winning a lottery [1].',1,1);
INSERT INTO rubric_criterion VALUES(11773,'psych12a2-hc-34',NULL,0,'Availability heuristic: likelihood is judged by how easily examples come to mind [1]; e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11774,'psych12a2-hc-34',NULL,1,'a resident who recalls several recent local burglaries overestimates the crime rate in their suburb [1]; representativeness heuristic: likelihood is judged by how closely something matches a prototype or category [1];',1,1);
INSERT INTO rubric_criterion VALUES(11775,'psych12a2-hc-34',NULL,2,'e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11776,'psych12a2-hc-34',NULL,3,'judging an unfamiliar man who is neatly dressed and punctual to be an accountant because he matches that stereotype [1].',1,1);
INSERT INTO rubric_criterion VALUES(11783,'psych12a2-ob-6',NULL,0,'Authority figure physically present/close to the participant; prestigious or legitimate setting (e.g. Yale), lab coat;',1,1);
INSERT INTO rubric_criterion VALUES(11784,'psych12a2-ob-6',NULL,1,'learner at a distance from the participant; gradual escalation of shocks (any two, each described).',1,1);
INSERT INTO rubric_criterion VALUES(11785,'psych12a2-ob-7',NULL,0,'Perceived legitimacy and expertise of the authority figure (doctor in a hospital setting); diffusion of responsibility, believing the doctor is responsible for the outcome;',1,1);
INSERT INTO rubric_criterion VALUES(11786,'psych12a2-ob-7',NULL,1,'a third factor such as the pressure of hierarchy or gradual escalation;',1,1);
INSERT INTO rubric_criterion VALUES(11787,'psych12a2-ob-7',NULL,2,'at least two reasons linked to the scenario.',1,1);
INSERT INTO rubric_criterion VALUES(11788,'psych12a2-ob-8',NULL,0,'Breach identified, e.g. informed consent (participants were deceived), or protection from harm/withdrawal rights (participants were pressed to continue);',1,1);
INSERT INTO rubric_criterion VALUES(11789,'psych12a2-ob-8',NULL,1,'explanation of how it is breached; modern approach, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11790,'psych12a2-ob-8',NULL,2,'full debriefing, ethics committee approval, risk assessment, stopping at lower shock levels, or allowing withdrawal without pressure.',1,1);
INSERT INTO rubric_criterion VALUES(11805,'psych12a2-ob-23',NULL,0,'Teachers experienced conflict between their own values (not harming another person) and the experimenter''s instructions [1];',1,1);
INSERT INTO rubric_criterion VALUES(11806,'psych12a2-ob-23',NULL,1,'continuing despite this shows that the authority''s demands can override personal conscience, a key finding of the study [1].',1,1);
INSERT INTO rubric_criterion VALUES(11807,'psych12a2-ob-24',NULL,0,'Obedience is following a direct order or command from an authority figure [1]; conformity is changing behaviour to match a group or majority without a direct order [1];',1,1);
INSERT INTO rubric_criterion VALUES(11808,'psych12a2-ob-24',NULL,1,'valid examples of each, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11809,'psych12a2-ob-24',NULL,2,'a soldier following a commander''s order (obedience) and a teenager adopting the clothing style of friends (conformity) [1].',1,1);
INSERT INTO rubric_criterion VALUES(11810,'psych12a2-ob-25',NULL,0,'Strength: the standardised procedure (set shock levels, scripted prods and a confederate learner) allowed the study to be replicated [1];',1,1);
INSERT INTO rubric_criterion VALUES(11811,'psych12a2-ob-25',NULL,1,'strength: later replications have supported the general finding that ordinary people obey strongly, adding reliability [1];',1,1);
INSERT INTO rubric_criterion VALUES(11812,'psych12a2-ob-25',NULL,2,'limitation: the original sample was small and all male, limiting generalisability [1];',1,1);
INSERT INTO rubric_criterion VALUES(11813,'psych12a2-ob-25',NULL,3,'limitation: deception and psychological distress raise serious ethical concerns [1].',1,1);
INSERT INTO rubric_criterion VALUES(11814,'psych12a2-ob-26',NULL,0,'The prods were scripted instructions to continue (e.g. ''The experiment requires that you continue'') [1];',1,1);
INSERT INTO rubric_criterion VALUES(11815,'psych12a2-ob-26',NULL,1,'they standardised the pressure so every participant received the same instructions, allowing fair comparison [1].',1,1);
INSERT INTO rubric_criterion VALUES(11816,'psych12a2-ob-27',NULL,0,'The study was stopped for ethical reasons, to reduce the risk of psychological harm to participants [1];',1,1);
INSERT INTO rubric_criterion VALUES(11817,'psych12a2-ob-27',NULL,1,'150 volts is where the learner first protests and asks to be released, so the most distressing shocks were avoided [1];',1,1);
INSERT INTO rubric_criterion VALUES(11818,'psych12a2-ob-27',NULL,2,'obedience up to that point was similar to Milgram''s original results, supporting the replicability of the findings [1].',1,1);
INSERT INTO rubric_criterion VALUES(11819,'psych12a2-ob-28',NULL,0,'An authority figure whose power is seen as rightful or accepted, for example because of their position, expertise or the institution they represent [1].',1,1);
INSERT INTO rubric_criterion VALUES(11820,'psych12a2-ob-29',NULL,0,'Each step was only slightly higher than the last, so refusing at any point felt inconsistent with having already complied [1];',1,1);
INSERT INTO rubric_criterion VALUES(11821,'psych12a2-ob-29',NULL,1,'once teachers had continued through earlier levels they were committed to going on, a foot-in-the-door effect [1].',1,1);
INSERT INTO rubric_criterion VALUES(11822,'psych12a2-ob-30',NULL,0,'Advantage: variables such as shock levels and prods can be controlled, so cause-and-effect conclusions and replication are possible [1];',1,1);
INSERT INTO rubric_criterion VALUES(11823,'psych12a2-ob-30',NULL,1,'limitation: the artificial setting may reduce ecological validity, so results may not generalise to everyday situations [1].',1,1);
INSERT INTO rubric_criterion VALUES(11824,'psych12a2-ob-31',NULL,0,'Participants were ordinary people from varied occupations, and most obeyed to the maximum, suggesting obedience is common rather than limited to unusual personalities [1];',1,1);
INSERT INTO rubric_criterion VALUES(11825,'psych12a2-ob-31',NULL,1,'obedience changed substantially when situational features changed, such as the authority figure''s presence or the learner''s proximity, which fixed traits cannot explain [1];',1,1);
INSERT INTO rubric_criterion VALUES(11826,'psych12a2-ob-31',NULL,2,'so the situation is a key determinant of obedience [1].',1,1);
INSERT INTO rubric_criterion VALUES(11833,'psych12a2-cg-6',NULL,0,'Group size (conformity increases up to a point, e.g. 3 or 4 members);',1,1);
INSERT INTO rubric_criterion VALUES(11834,'psych12a2-cg-6',NULL,1,'unanimity (a dissenter reduces conformity); also task ambiguity, group status or whether responses are public/private (any two, each described).',1,1);
INSERT INTO rubric_criterion VALUES(11835,'psych12a2-cg-7',NULL,0,'Social loafing; make individual contributions identifiable or assess them individually;',1,1);
INSERT INTO rubric_criterion VALUES(11836,'psych12a2-cg-7',NULL,1,'use smaller groups or give each member a defined role;',1,1);
INSERT INTO rubric_criterion VALUES(11837,'psych12a2-cg-7',NULL,2,'(any two strategies, linked to the concept).',1,1);
INSERT INTO rubric_criterion VALUES(11838,'psych12a2-cg-8',NULL,0,'Normative influence: conforming to be accepted or avoid rejection by the group (e.g. wearing a brand because friends do);',1,1);
INSERT INTO rubric_criterion VALUES(11839,'psych12a2-cg-8',NULL,1,'informational influence: conforming because the group is seen as having correct information in an ambiguous situation (e.g. copying others'' choice of exit in an unfamiliar building);',1,1);
INSERT INTO rubric_criterion VALUES(11840,'psych12a2-cg-8',NULL,2,'clear difference in motivation (belonging vs accuracy).',1,1);
INSERT INTO rubric_criterion VALUES(11858,'psych12a2-cg-26',NULL,0,'A naive participant was seated among confederates who had been instructed in advance to give answers [1];',1,1);
INSERT INTO rubric_criterion VALUES(11859,'psych12a2-cg-26',NULL,1,'the group judged which of three comparison lines matched a standard line over 18 trials [1];',1,1);
INSERT INTO rubric_criterion VALUES(11860,'psych12a2-cg-26',NULL,2,'on the 12 critical trials the confederates unanimously gave the same incorrect answer, and the participant usually answered last [1].',1,1);
INSERT INTO rubric_criterion VALUES(11861,'psych12a2-cg-27',NULL,0,'Compliance: changing behaviour to gain a reward or avoid punishment, without private acceptance [1];',1,1);
INSERT INTO rubric_criterion VALUES(11862,'psych12a2-cg-27',NULL,1,'identification: adopting behaviour to maintain a satisfying relationship with a respected person or group, with private beliefs possibly unchanged [1];',1,1);
INSERT INTO rubric_criterion VALUES(11863,'psych12a2-cg-27',NULL,2,'internalisation: genuinely accepting the belief or behaviour, so it is maintained even when no one is watching [1];',1,1);
INSERT INTO rubric_criterion VALUES(11864,'psych12a2-cg-27',NULL,3,'the key difference is motivation and permanence, as compliance and identification depend on the social context while internalisation depends on the person''s own values [1].',1,1);
INSERT INTO rubric_criterion VALUES(11865,'psych12a2-cg-28',NULL,0,'Diffusion of responsibility: each bystander feels less personally responsible for acting, so responsibility is shared among those present [1];',1,1);
INSERT INTO rubric_criterion VALUES(11866,'psych12a2-cg-28',NULL,1,'informational influence: bystanders look to one another, see no one acting, and conclude that help is not needed [1].',1,1);
INSERT INTO rubric_criterion VALUES(11867,'psych12a2-cg-29',NULL,0,'Anonymity in a crowd reduces a person''s sense of individual identity and accountability [1];',1,1);
INSERT INTO rubric_criterion VALUES(11868,'psych12a2-cg-29',NULL,1,'lower self-awareness weakens normal self-restraint and personal moral standards [1];',1,1);
INSERT INTO rubric_criterion VALUES(11869,'psych12a2-cg-29',NULL,2,'the crowd''s emotional arousal and norms can then encourage behaviour, such as vandalism, that the person would not normally perform [1].',1,1);
INSERT INTO rubric_criterion VALUES(11870,'psych12a2-cg-30',NULL,0,'Self-censorship: the directors with doubts keep quiet [1];',1,1);
INSERT INTO rubric_criterion VALUES(11871,'psych12a2-cg-30',NULL,1,'pressure on dissenters: the chair labels critics as disloyal [1];',1,1);
INSERT INTO rubric_criterion VALUES(11872,'psych12a2-cg-30',NULL,2,'illusion of unanimity: the board treats silence as agreement [1].',1,1);
INSERT INTO rubric_criterion VALUES(11873,'psych12a2-cg-31',NULL,0,'Conformity: changing behaviour or beliefs to match a group or social norm, without a direct order [1];',1,1);
INSERT INTO rubric_criterion VALUES(11874,'psych12a2-cg-31',NULL,1,'obedience: following a direct order from an authority figure [1];',1,1);
INSERT INTO rubric_criterion VALUES(11875,'psych12a2-cg-31',NULL,2,'example of conformity: a student wears the same style of clothing as her friends to fit in [1];',1,1);
INSERT INTO rubric_criterion VALUES(11876,'psych12a2-cg-31',NULL,3,'example of obedience: a nurse gives a patient a medication dose because a doctor instructs it [1].',1,1);
INSERT INTO rubric_criterion VALUES(11877,'psych12a2-cg-32',NULL,0,'An estimate formed through group interaction continued to be used by participants when they were later tested alone [1];',1,1);
INSERT INTO rubric_criterion VALUES(11878,'psych12a2-cg-32',NULL,1,'this showed the norm had been accepted privately, not just displayed for others [1];',1,1);
INSERT INTO rubric_criterion VALUES(11879,'psych12a2-cg-32',NULL,2,'participants relied on the group''s estimate as a guide to accuracy because the task was ambiguous [1].',1,1);
INSERT INTO rubric_criterion VALUES(11880,'psych12a2-cg-33',NULL,0,'An actor who secretly works with the researcher and gives pre-arranged answers [1].',1,1);
INSERT INTO rubric_criterion VALUES(11881,'psych12a2-cg-34',NULL,0,'Average output = 28 ÷ 4 = 7 units per student [1];',1,1);
INSERT INTO rubric_criterion VALUES(11882,'psych12a2-cg-34',NULL,1,'this is less than the 10 units each student produced alone [1];',1,1);
INSERT INTO rubric_criterion VALUES(11883,'psych12a2-cg-34',NULL,2,'the reduction in individual effort in a group is consistent with social loafing [1].',1,1);
INSERT INTO rubric_criterion VALUES(11884,'psych12a2-cg-35',NULL,0,'Limitation: the task was artificial and low-stakes, so it has low ecological validity [1];',1,1);
INSERT INTO rubric_criterion VALUES(11885,'psych12a2-cg-35',NULL,1,'limitation: the sample was an all-male group of American college students, so the findings may not generalise to women or other cultures [1];',1,1);
INSERT INTO rubric_criterion VALUES(11886,'psych12a2-cg-35',NULL,2,'strength: the controlled procedure and clear measure of incorrect answers allowed reliable comparison across conditions [1];',1,1);
INSERT INTO rubric_criterion VALUES(11887,'psych12a2-cg-35',NULL,3,'limitation: participants were deceived by confederates and may have experienced stress, raising ethical concerns [1].',1,1);
INSERT INTO rubric_criterion VALUES(11888,'psych12a2-cg-36',NULL,0,'Appointing a devil''s advocate to challenge the proposal [1], which encourages critical discussion and reduces the pressure to agree [1];',1,1);
INSERT INTO rubric_criterion VALUES(11889,'psych12a2-cg-36',NULL,1,'asking members to form and record independent views before the group discusses the issue [1], so that doubts are voiced rather than suppressed [1].',3,1);
INSERT INTO rubric_criterion VALUES(11896,'psych12a2-sv-6',NULL,0,'Light enters through the cornea and passes through the pupil and lens (focused by accommodation);',1,1);
INSERT INTO rubric_criterion VALUES(11897,'psych12a2-sv-6',NULL,1,'falls on the retina where rods and cones detect it (transduction into neural signals);',1,1);
INSERT INTO rubric_criterion VALUES(11898,'psych12a2-sv-6',NULL,2,'signals travel via bipolar and ganglion cells through the optic nerve;',1,1);
INSERT INTO rubric_criterion VALUES(11899,'psych12a2-sv-6',NULL,3,'to the thalamus and then the visual cortex in the occipital lobe.',1,1);
INSERT INTO rubric_criterion VALUES(11900,'psych12a2-sv-7',NULL,0,'The fovea contains a high density of cones, which provide sharp detail and colour vision, so reading is impaired;',1,1);
INSERT INTO rubric_criterion VALUES(11901,'psych12a2-sv-7',NULL,1,'the periphery of the retina has mostly rods, which remain intact;',1,1);
INSERT INTO rubric_criterion VALUES(11902,'psych12a2-sv-7',NULL,2,'rods detect motion and low-light stimuli in the periphery.',1,1);
INSERT INTO rubric_criterion VALUES(11903,'psych12a2-sv-8',NULL,0,'Sensation: detection of light by photoreceptors and conversion into neural signals; perception: the brain''s organisation and interpretation of these signals, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11904,'psych12a2-sv-8',NULL,1,'recognising a face.',1,1);
INSERT INTO rubric_criterion VALUES(11924,'psych12a2-sv-28',NULL,0,'The iris contracts or relaxes its muscles to change the size of the pupil [1];',1,1);
INSERT INTO rubric_criterion VALUES(11925,'psych12a2-sv-28',NULL,1,'the pupil constricts in bright light to limit the light entering, and dilates in dim light to admit more [1].',1,1);
INSERT INTO rubric_criterion VALUES(11926,'psych12a2-sv-29',NULL,0,'The cornea bends incoming light and provides most of the eye''s focusing power [1];',1,1);
INSERT INTO rubric_criterion VALUES(11927,'psych12a2-sv-29',NULL,1,'the lens makes fine adjustments to the focus [1];',1,1);
INSERT INTO rubric_criterion VALUES(11928,'psych12a2-sv-29',NULL,2,'the ciliary muscles change the shape of the lens so that light from objects at different distances is focused on the retina [1].',1,1);
INSERT INTO rubric_criterion VALUES(11929,'psych12a2-sv-30',NULL,0,'The blind spot in each eye falls in a different part of the visual field, so the other eye detects that region [1];',1,1);
INSERT INTO rubric_criterion VALUES(11930,'psych12a2-sv-30',NULL,1,'the brain also fills in the gap using information from the surrounding visual field [1].',1,1);
INSERT INTO rubric_criterion VALUES(11931,'psych12a2-sv-31',NULL,0,'Faint light is detected mainly by rods [1];',1,1);
INSERT INTO rubric_criterion VALUES(11932,'psych12a2-sv-31',NULL,1,'rods are concentrated in the periphery of the retina and are largely absent from the fovea [1];',1,1);
INSERT INTO rubric_criterion VALUES(11933,'psych12a2-sv-31',NULL,2,'looking to the side places the image of the star on the rod-rich periphery, increasing sensitivity [1].',1,1);
INSERT INTO rubric_criterion VALUES(11934,'psych12a2-sv-32',NULL,0,'The right visual cortex receives information from the left visual field of both eyes [1];',1,1);
INSERT INTO rubric_criterion VALUES(11935,'psych12a2-sv-32',NULL,1,'at the optic chiasm, fibres from the nasal half of each retina cross to the opposite hemisphere, sending left visual field signals to the right hemisphere [1];',1,1);
INSERT INTO rubric_criterion VALUES(11936,'psych12a2-sv-32',NULL,2,'damage therefore causes loss of vision in the left visual field of both eyes [1].',1,1);
INSERT INTO rubric_criterion VALUES(11937,'psych12a2-sv-33',NULL,0,'Transduction is the conversion of light energy into neural signals by photoreceptors in the retina [1];',1,1);
INSERT INTO rubric_criterion VALUES(11938,'psych12a2-sv-33',NULL,1,'accommodation is the change in lens shape that allows light from objects at different distances to be focused on the retina [1].',1,1);
INSERT INTO rubric_criterion VALUES(11939,'psych12a2-sv-34',NULL,0,'The area of the external world that can be seen at one moment when the eyes are fixed on a single point [1].',1,1);
INSERT INTO rubric_criterion VALUES(11940,'psych12a2-sv-35',NULL,0,'Loss of colour vision, because cones are required to detect colour [1];',1,1);
INSERT INTO rubric_criterion VALUES(11941,'psych12a2-sv-35',NULL,1,'reduced visual acuity and detail, because cones are concentrated in the fovea and are needed for sharp vision [1].',1,1);
INSERT INTO rubric_criterion VALUES(11942,'psych12a2-sv-36',NULL,0,'The claim is incorrect [1];',1,1);
INSERT INTO rubric_criterion VALUES(11943,'psych12a2-sv-36',NULL,1,'rods do not detect colour, as colour vision requires cones [1];',1,1);
INSERT INTO rubric_criterion VALUES(11944,'psych12a2-sv-36',NULL,2,'in low light cones are much less active, so colours appear faded and the scene is seen mainly in shades of grey [1].',1,1);
INSERT INTO rubric_criterion VALUES(11945,'psych12a2-sv-37',NULL,0,'The iris muscles dilate the pupil within seconds, letting more light reach the retina [1];',1,1);
INSERT INTO rubric_criterion VALUES(11946,'psych12a2-sv-37',NULL,1,'this is a fast reflex that changes the amount of light entering the eye [1];',1,1);
INSERT INTO rubric_criterion VALUES(11947,'psych12a2-sv-37',NULL,2,'rods and cones increase their sensitivity through regeneration of photopigment, which takes minutes to around 30 minutes [1];',1,1);
INSERT INTO rubric_criterion VALUES(11948,'psych12a2-sv-37',NULL,3,'so overall sensitivity adjusts much more slowly than the pupil does [1].',1,1);
INSERT INTO rubric_criterion VALUES(11955,'psych12a2-td-6',NULL,0,'Bottom-up: perception built from the sensory features of the stimulus upward to recognition; example, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11956,'psych12a2-td-6',NULL,1,'noticing the shapes, edges and colours of an unfamiliar object; top-down: perception guided by prior knowledge, context and expectation;',1,1);
INSERT INTO rubric_criterion VALUES(11957,'psych12a2-td-6',NULL,2,'example, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11958,'psych12a2-td-6',NULL,3,'reading messy handwriting by using context.',1,1);
INSERT INTO rubric_criterion VALUES(11959,'psych12a2-td-7',NULL,0,'Their perception is influenced by expectations, prior experience or context (e.g. recent priming or interests) rather than only the stimulus;',1,1);
INSERT INTO rubric_criterion VALUES(11960,'psych12a2-td-7',NULL,1,'this leads to different interpretations of the same sensory input.',1,1);
INSERT INTO rubric_criterion VALUES(11961,'psych12a2-td-8',NULL,0,'Bottom-up processing registers the visual features of the object (shape, colour, edges); top-down processing uses knowledge and context (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(11962,'psych12a2-td-8',NULL,1,'a kitchen setting) to interpret the features and recognise it quickly;',1,1);
INSERT INTO rubric_criterion VALUES(11963,'psych12a2-td-8',NULL,2,'together they allow efficient, accurate perception, especially when input is incomplete.',1,1);
INSERT INTO rubric_criterion VALUES(11981,'psych12a2-td-26',NULL,0,'Stored knowledge of the brand and its logo fills in the hidden part of the image [1];',1,1);
INSERT INTO rubric_criterion VALUES(11982,'psych12a2-td-26',NULL,1,'the shopper''s expectation of finding that product guides how the visible features are interpreted [1].',1,1);
INSERT INTO rubric_criterion VALUES(11983,'psych12a2-td-27',NULL,0,'The sensory input is ambiguous, so the bottom-up features alone do not form a recognised face [1];',1,1);
INSERT INTO rubric_criterion VALUES(11984,'psych12a2-td-27',NULL,1,'being told there is a face creates an expectation that is used to organise the blotches [1];',1,1);
INSERT INTO rubric_criterion VALUES(11985,'psych12a2-td-27',NULL,2,'the same input is now interpreted differently, so the perception changes [1].',1,1);
INSERT INTO rubric_criterion VALUES(11986,'psych12a2-td-28',NULL,0,'An unfamiliar stimulus with no relevant prior knowledge, such as encountering a new object or species [1];',1,1);
INSERT INTO rubric_criterion VALUES(11987,'psych12a2-td-28',NULL,1,'perception must then be built from the sensory features themselves [1];',1,1);
INSERT INTO rubric_criterion VALUES(11988,'psych12a2-td-28',NULL,2,'relying on expectations could lead to a misperception because the wrong expectations would be applied [1].',1,1);
INSERT INTO rubric_criterion VALUES(11989,'psych12a2-td-29',NULL,0,'Early reading relies mainly on bottom-up processing, decoding each letter and sound from its sensory features [1];',1,1);
INSERT INTO rubric_criterion VALUES(11990,'psych12a2-td-29',NULL,1,'as skill develops, stored knowledge of words and spelling patterns allows top-down processing [1];',1,1);
INSERT INTO rubric_criterion VALUES(11991,'psych12a2-td-29',NULL,2,'the skilled reader uses context and expectation to recognise words quickly [1];',1,1);
INSERT INTO rubric_criterion VALUES(11992,'psych12a2-td-29',NULL,3,'bottom-up features are still used for unfamiliar or misspelt words [1].',1,1);
INSERT INTO rubric_criterion VALUES(11993,'psych12a2-td-30',NULL,0,'Top-down processing, because the tourist''s expectation shapes the interpretation of the sign [1];',1,1);
INSERT INTO rubric_criterion VALUES(11994,'psych12a2-td-30',NULL,1,'the expectation overrides the sensory detail, so the misreading occurs [1];',1,1);
INSERT INTO rubric_criterion VALUES(11995,'psych12a2-td-30',NULL,2,'the error could be reduced by attending more closely to the sensory features of the sign, such as reading each word carefully [1].',1,1);
INSERT INTO rubric_criterion VALUES(11996,'psych12a2-td-31',NULL,0,'Perception also depends on expectations, prior experience and context, which can influence the interpretation of clear input [1];',1,1);
INSERT INTO rubric_criterion VALUES(11997,'psych12a2-td-31',NULL,1,'so the brain may interpret the input in a way that does not match what is actually present, for example by seeing what is expected [1].',1,1);
INSERT INTO rubric_criterion VALUES(11998,'psych12a2-td-32',NULL,0,'Context provides extra information about the likely meaning of an ambiguous stimulus [1]; it narrows the range of possible interpretations, so the most likely one is perceived [1];',1,1);
INSERT INTO rubric_criterion VALUES(11999,'psych12a2-td-32',NULL,1,'e.g.',1,1);
INSERT INTO rubric_criterion VALUES(12000,'psych12a2-td-32',NULL,2,'reading the word ''bank'' as a river bank when it appears beside a picture of water [1].',1,1);
INSERT INTO rubric_criterion VALUES(12001,'psych12a2-td-33',NULL,0,'Bottom-up: the faint lights and edges are registered from the sensory input [1];',1,1);
INSERT INTO rubric_criterion VALUES(12002,'psych12a2-td-33',NULL,1,'top-down: the pilot''s expectation of a landing strip guides the interpretation of those features [1];',1,1);
INSERT INTO rubric_criterion VALUES(12003,'psych12a2-td-33',NULL,2,'both combine to form the perception [1];',1,1);
INSERT INTO rubric_criterion VALUES(12004,'psych12a2-td-33',NULL,3,'an error could arise if the expectation leads the pilot to perceive a runway where the lights do not show one [1].',1,1);
INSERT INTO rubric_criterion VALUES(12005,'psych12a2-td-34',NULL,0,'Perception built up from the raw sensory features of a stimulus, without relying on prior knowledge or expectation [1].',1,1);
INSERT INTO rubric_criterion VALUES(12012,'psych12a3-dcg-6',NULL,0,'Monocular cues require input from only one eye (1); binocular cues require input from both eyes and depend on their different positions (1);',1,1);
INSERT INTO rubric_criterion VALUES(12013,'psych12a3-dcg-6',NULL,1,'example of monocular: relative size, interposition, linear perspective, texture gradient;',1,1);
INSERT INTO rubric_criterion VALUES(12014,'psych12a3-dcg-6',NULL,2,'example of binocular: retinal disparity or convergence (1 for both examples correct).',1,1);
INSERT INTO rubric_criterion VALUES(12015,'psych12a3-dcg-7',NULL,0,'Figure-ground is the tendency to organise a visual scene into a distinct object (the figure) that stands out against its background (1);',1,1);
INSERT INTO rubric_criterion VALUES(12016,'psych12a3-dcg-7',NULL,1,'we perceive the figure as having a defined form and the ground as extending behind it (1);',1,1);
INSERT INTO rubric_criterion VALUES(12017,'psych12a3-dcg-7',NULL,2,'a logo could use contrasting colours so that the shape or lettering clearly stands out as the figure, or deliberately use ambiguity so that the negative space forms a second image (1).',1,1);
INSERT INTO rubric_criterion VALUES(12018,'psych12a3-dcg-8',NULL,0,'Interposition (overlap) (1);',1,1);
INSERT INTO rubric_criterion VALUES(12019,'psych12a3-dcg-8',NULL,1,'the object that partially blocks the view of another is perceived as closer, and the partly hidden object as further away (1).',1,1);
INSERT INTO rubric_criterion VALUES(12034,'psych12a3-dcg-23',NULL,0,'Convergence is the inward turning of the two eyes to focus on a near object, with the muscle effort used as a distance signal [1];',1,1);
INSERT INTO rubric_criterion VALUES(12035,'psych12a3-dcg-23',NULL,1,'it is a binocular cue because it requires both eyes [1].',1,1);
INSERT INTO rubric_criterion VALUES(12036,'psych12a3-dcg-24',NULL,0,'Accommodation [1].',1,1);
INSERT INTO rubric_criterion VALUES(12037,'psych12a3-dcg-25',NULL,0,'The eyes are set apart horizontally, so each eye views the object from a slightly different position [1];',1,1);
INSERT INTO rubric_criterion VALUES(12038,'psych12a3-dcg-25',NULL,1,'the difference is larger for nearby objects, which the brain uses as a depth cue [1].',1,1);
INSERT INTO rubric_criterion VALUES(12039,'psych12a3-dcg-26',NULL,0,'Texture gradient is the change in the size and density of surface detail as distance increases [1];',1,1);
INSERT INTO rubric_criterion VALUES(12040,'psych12a3-dcg-26',NULL,1,'near blades of grass are large and widely spaced, while distant ones are small and tightly packed [1];',1,1);
INSERT INTO rubric_criterion VALUES(12041,'psych12a3-dcg-26',NULL,2,'the smooth change in detail signals a surface that extends away from the viewer, so the far end is judged to be further away [1].',1,1);
INSERT INTO rubric_criterion VALUES(12042,'psych12a3-dcg-27',NULL,0,'Partly valid: relative size suggests the smaller bird is further away if both birds are assumed to be the same size [1];',1,1);
INSERT INTO rubric_criterion VALUES(12043,'psych12a3-dcg-27',NULL,1,'however, the birds may differ in actual size, so relative size alone is unreliable [1];',1,1);
INSERT INTO rubric_criterion VALUES(12044,'psych12a3-dcg-27',NULL,2,'a second cue, such as interposition if one bird partly blocks the other, or aerial perspective, would support or refute the judgement [1];',1,1);
INSERT INTO rubric_criterion VALUES(12045,'psych12a3-dcg-27',NULL,3,'the claim is therefore reasonable only when other cues confirm it [1].',1,1);
INSERT INTO rubric_criterion VALUES(12046,'psych12a3-dcg-28',NULL,0,'Similarity groups elements that share a visual feature such as colour [1];',1,1);
INSERT INTO rubric_criterion VALUES(12047,'psych12a3-dcg-28',NULL,1,'all red lines are perceived as one type of service and all blue lines as another [1];',1,1);
INSERT INTO rubric_criterion VALUES(12048,'psych12a3-dcg-28',NULL,2,'the commuter can therefore identify the train network quickly without reading every label [1].',1,1);
INSERT INTO rubric_criterion VALUES(12049,'psych12a3-dcg-29',NULL,0,'The friend''s outline or clothing is organised as the figure that stands out against the crowd as background [1];',1,1);
INSERT INTO rubric_criterion VALUES(12050,'psych12a3-dcg-29',NULL,1,'because the figure is perceived as a distinct object, the person can locate it quickly [1].',1,1);
INSERT INTO rubric_criterion VALUES(12057,'psych12a3-gp-6',NULL,0,'Chemicals from the food dissolve in saliva and contact taste receptor cells in taste buds within papillae on the tongue (1);',1,1);
INSERT INTO rubric_criterion VALUES(12058,'psych12a3-gp-6',NULL,1,'the receptors transduce the chemical stimulus into neural impulses that travel along sensory neurons (1);',1,1);
INSERT INTO rubric_criterion VALUES(12059,'psych12a3-gp-6',NULL,2,'the information reaches the gustatory cortex where it is interpreted as sweet taste (1).',1,1);
INSERT INTO rubric_criterion VALUES(12060,'psych12a3-gp-7',NULL,0,'Flavour is the combined perception of taste and smell (1);',1,1);
INSERT INTO rubric_criterion VALUES(12061,'psych12a3-gp-7',NULL,1,'odour molecules from food travel to the olfactory receptors at the back of the nasal cavity while chewing/swallowing, and the brain integrates this with gustatory input (1).',1,1);
INSERT INTO rubric_criterion VALUES(12062,'psych12a3-gp-8',NULL,0,'Supertasters have more taste buds/papillae (1);',1,1);
INSERT INTO rubric_criterion VALUES(12063,'psych12a3-gp-8',NULL,1,'so they would rate the drink as much more intensely bitter (or find it unpleasant) than non-tasters, who would rate it as mild (1).',1,1);
INSERT INTO rubric_criterion VALUES(12081,'psych12a3-gp-26',NULL,0,'Soft palate, pharynx or epiglottis (1).',1,1);
INSERT INTO rubric_criterion VALUES(12082,'psych12a3-gp-27',NULL,0,'Mushroom-shaped papillae found mainly on the front and sides of the tongue (1).',1,1);
INSERT INTO rubric_criterion VALUES(12083,'psych12a3-gp-28',NULL,0,'The thalamus receives taste information from the brainstem (1), and relays it onward to the primary gustatory cortex in the cerebral cortex (1).',2,1);
INSERT INTO rubric_criterion VALUES(12084,'psych12a3-gp-29',NULL,0,'Both senses respond to chemical molecules from food or the environment (1);',1,1);
INSERT INTO rubric_criterion VALUES(12085,'psych12a3-gp-29',NULL,1,'their receptors are activated when molecules bind to them, producing neural signals (1).',1,1);
INSERT INTO rubric_criterion VALUES(12086,'psych12a3-gp-30',NULL,0,'Sourness signals acidity, which can indicate unripe or spoiled food (1);',1,1);
INSERT INTO rubric_criterion VALUES(12087,'psych12a3-gp-30',NULL,1,'avoiding such food reduces the risk of ingesting harmful bacteria or toxins (1).',1,1);
INSERT INTO rubric_criterion VALUES(12088,'psych12a3-gp-31',NULL,0,'Taste receptors are in taste buds on the tongue, soft palate, pharynx and epiglottis (1);',1,1);
INSERT INTO rubric_criterion VALUES(12089,'psych12a3-gp-31',NULL,1,'olfactory receptors are in the olfactory epithelium at the roof of the nasal cavity (1).',1,1);
INSERT INTO rubric_criterion VALUES(12090,'psych12a3-gp-32',NULL,0,'Less sodium is available to stimulate the salt-sensitive receptor cells (1);',1,1);
INSERT INTO rubric_criterion VALUES(12091,'psych12a3-gp-32',NULL,1,'fewer neural impulses are generated, so the signal reaching the gustatory cortex is weaker (1);',1,1);
INSERT INTO rubric_criterion VALUES(12092,'psych12a3-gp-32',NULL,2,'flavour also depends on smell, texture or aroma, and reduced aroma or crunch can increase the perceived blandness (1).',1,1);
INSERT INTO rubric_criterion VALUES(12093,'psych12a3-gp-33',NULL,0,'A chemical from food binds to or enters a receptor on the taste receptor cell (1);',1,1);
INSERT INTO rubric_criterion VALUES(12094,'psych12a3-gp-33',NULL,1,'this changes the cell''s electrical activity, producing a receptor potential (1);',1,1);
INSERT INTO rubric_criterion VALUES(12095,'psych12a3-gp-33',NULL,2,'the cell releases a neurotransmitter onto a sensory neuron, which generates neural impulses sent to the brain (1).',1,1);
INSERT INTO rubric_criterion VALUES(12102,'psych12a3-dpi-6',NULL,0,'The moon’s retinal image is the same size in both positions (1); near the horizon, objects such as trees and buildings provide depth cues (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(12103,'psych12a3-dpi-6',NULL,1,'relative size/texture gradient) making the moon seem further away (1);',1,1);
INSERT INTO rubric_criterion VALUES(12104,'psych12a3-dpi-6',NULL,2,'the brain therefore perceives it as larger, whereas in the empty sky there are no cues, so it appears smaller (1).',1,1);
INSERT INTO rubric_criterion VALUES(12105,'psych12a3-dpi-7',NULL,0,'Two lines of equal length appear different in length (1);',1,1);
INSERT INTO rubric_criterion VALUES(12106,'psych12a3-dpi-7',NULL,1,'the line with outward-pointing fins (like an arrowhead pointing inwards) looks shorter than the line with inward-pointing fins (1);',1,1);
INSERT INTO rubric_criterion VALUES(12107,'psych12a3-dpi-7',NULL,2,'explanation: the fins are interpreted as depth cues, like the corners of a room, making one line appear further away and hence longer (1).',1,1);
INSERT INTO rubric_criterion VALUES(12108,'psych12a3-dpi-8',NULL,0,'A perception in which the observer’s experience differs from the physical properties of the stimulus (1);',1,1);
INSERT INTO rubric_criterion VALUES(12109,'psych12a3-dpi-8',NULL,1,'example: Ponzo illusion, Ames room, moon illusion, Rubin’s vase (1).',1,1);
INSERT INTO rubric_criterion VALUES(12123,'psych12a3-dpi-22',NULL,0,'After prolonged viewing of downward motion, a stationary scene such as the rocks beside a waterfall appears to move upward [1];',1,1);
INSERT INTO rubric_criterion VALUES(12124,'psych12a3-dpi-22',NULL,1,'motion-detecting neurons tuned to downward movement become fatigued, so neurons responding to upward movement dominate when the still scene is viewed [1].',1,1);
INSERT INTO rubric_criterion VALUES(12125,'psych12a3-dpi-23',NULL,0,'A hollow mask viewed from the inside is perceived as a normal convex face [1];',1,1);
INSERT INTO rubric_criterion VALUES(12126,'psych12a3-dpi-23',NULL,1,'the viewer’s stored knowledge that faces are convex is applied to the sensory input [1];',1,1);
INSERT INTO rubric_criterion VALUES(12127,'psych12a3-dpi-23',NULL,2,'this prior expectation (top-down processing) overrides depth cues such as shading and perspective that indicate a concave surface [1];',1,1);
INSERT INTO rubric_criterion VALUES(12128,'psych12a3-dpi-23',NULL,3,'the percept is therefore constructed from sensory data and experience, not a direct copy of the stimulus [1].',1,1);
INSERT INTO rubric_criterion VALUES(12129,'psych12a3-dpi-24',NULL,0,'Three black circles with wedges removed are arranged so that a triangle with clear edges appears to lie over them, although no triangle outline is drawn [1];',1,1);
INSERT INTO rubric_criterion VALUES(12130,'psych12a3-dpi-24',NULL,1,'the brain completes the missing contours from the arrangement of the shapes, which is a form of perceptual organisation (closure) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12131,'psych12a3-dpi-25',NULL,0,'Two tabletops that are identical in shape and size are drawn in perspective and appear to differ [1];',1,1);
INSERT INTO rubric_criterion VALUES(12132,'psych12a3-dpi-25',NULL,1,'the brain interprets the drawing as a three-dimensional scene and applies perspective and size-distance scaling to the tabletops [1];',1,1);
INSERT INTO rubric_criterion VALUES(12133,'psych12a3-dpi-25',NULL,2,'the apparent depth makes one tabletop look longer and narrower than the other [1].',1,1);
INSERT INTO rubric_criterion VALUES(12134,'psych12a3-dpi-26',NULL,0,'People from environments without many right-angled, rectangular buildings (non-carpentered environments) were less susceptible to the Müller-Lyer illusion than people from carpentered urban environments [1];',1,1);
INSERT INTO rubric_criterion VALUES(12135,'psych12a3-dpi-26',NULL,1,'this suggests that experience with the surroundings shapes the depth cues and assumptions used to perceive illusions [1].',1,1);
INSERT INTO rubric_criterion VALUES(12136,'psych12a3-dpi-27',NULL,0,'Figure-ground organisation is the perceptual separation of a scene into an object (the figure) and its background, which can reverse in images such as Rubin’s vase, where either the vase or two faces can be seen as the figure [1].',1,1);
INSERT INTO rubric_criterion VALUES(12137,'psych12a3-dpi-28',NULL,0,'Two identical central circles look different in size when one is surrounded by larger circles and the other by smaller circles [1];',1,1);
INSERT INTO rubric_criterion VALUES(12138,'psych12a3-dpi-28',NULL,1,'the central circle surrounded by larger circles looks smaller, and the one surrounded by smaller circles looks larger [1];',1,1);
INSERT INTO rubric_criterion VALUES(12139,'psych12a3-dpi-28',NULL,2,'this is size contrast, in which perceived size is judged relative to the size of nearby objects [1].',1,1);
INSERT INTO rubric_criterion VALUES(12140,'psych12a3-dpi-29',NULL,0,'Perceptual set is a readiness to perceive a stimulus in a particular way, based on expectations, experience or context [1];',1,1);
INSERT INTO rubric_criterion VALUES(12141,'psych12a3-dpi-29',NULL,1,'the same ambiguous image is interpreted according to what each viewer expects, so each may see a different object [1];',1,1);
INSERT INTO rubric_criterion VALUES(12142,'psych12a3-dpi-29',NULL,2,'for example, a viewer told the image shows an animal may see an animal, while a viewer told it shows a plant may see a plant [1];',1,1);
INSERT INTO rubric_criterion VALUES(12143,'psych12a3-dpi-29',NULL,3,'the resulting perception is shaped by top-down processing rather than determined by the stimulus alone [1].',1,1);
INSERT INTO rubric_criterion VALUES(12150,'psych12a3-smv-6',NULL,0,'IV: whether participants listen to classical music (or the type of music/no music) while studying (1); DV: number of words recalled correctly (1);',1,1);
INSERT INTO rubric_criterion VALUES(12151,'psych12a3-smv-6',NULL,1,'extraneous variable e.g.',1,1);
INSERT INTO rubric_criterion VALUES(12152,'psych12a3-smv-6',NULL,2,'length of word list, time of day, prior knowledge/age, noise in room, study time (1).',1,1);
INSERT INTO rubric_criterion VALUES(12153,'psych12a3-smv-7',NULL,0,'A case study is an in-depth investigation of a single individual, group or event (1);',1,1);
INSERT INTO rubric_criterion VALUES(12154,'psych12a3-smv-7',NULL,1,'it typically collects detailed qualitative data without manipulating variables (1);',1,1);
INSERT INTO rubric_criterion VALUES(12155,'psych12a3-smv-7',NULL,2,'a controlled experiment manipulates an IV and measures its effect on a DV while controlling other variables, so it can establish cause and effect (1).',1,1);
INSERT INTO rubric_criterion VALUES(12156,'psych12a3-smv-8',NULL,0,'An aim states the purpose of the investigation (what is being investigated), e.g. to investigate the effect of caffeine on reaction time (1);',1,1);
INSERT INTO rubric_criterion VALUES(12157,'psych12a3-smv-8',NULL,1,'a hypothesis is a testable prediction of the outcome, stating the relationship between the IV and DV, e.g. participants given caffeine will have faster reaction times than those given none (1).',1,1);
INSERT INTO rubric_criterion VALUES(12175,'psych12a3-smv-26',NULL,0,'The consistency of a measure, so that it produces similar results when the same test is repeated under the same conditions [1].',1,1);
INSERT INTO rubric_criterion VALUES(12176,'psych12a3-smv-27',NULL,0,'Social desirability bias: students may answer in ways that make them look favourable rather than honestly [1];',1,1);
INSERT INTO rubric_criterion VALUES(12177,'psych12a3-smv-27',NULL,1,'this means the questionnaire measures self-presentation rather than true anxiety, reducing validity [1];',1,1);
INSERT INTO rubric_criterion VALUES(12178,'psych12a3-smv-27',NULL,2,'it could be reduced by ensuring anonymity, reassuring students that responses are confidential, or supporting results with another measure such as a physiological indicator [1].',1,1);
INSERT INTO rubric_criterion VALUES(12179,'psych12a3-smv-28',NULL,0,'Observation of a problem, such as students'' low maths scores, leading to a question about whether the app helps [1]; a testable hypothesis, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(12180,'psych12a3-smv-28',NULL,1,'students who use the app will score higher than students who do not [1];',1,1);
INSERT INTO rubric_criterion VALUES(12181,'psych12a3-smv-28',NULL,2,'a controlled experiment with app use as the IV and test score as the DV, using a control group and collecting data [1];',1,1);
INSERT INTO rubric_criterion VALUES(12182,'psych12a3-smv-28',NULL,3,'analysis of the results to decide whether the hypothesis is supported, followed by a conclusion that can be reported and replicated [1].',1,1);
INSERT INTO rubric_criterion VALUES(12183,'psych12a3-smv-29',NULL,0,'The sample is not representative of the target population, because university students differ from adolescents in general in age, independence and lifestyle [1];',1,1);
INSERT INTO rubric_criterion VALUES(12184,'psych12a3-smv-29',NULL,1,'so the findings may not apply to adolescents more broadly [1].',1,1);
INSERT INTO rubric_criterion VALUES(12185,'psych12a3-smv-30',NULL,0,'Keep the noise level constant across all participants and sessions, e.g. by testing everyone in a sound-proofed room [1];',1,1);
INSERT INTO rubric_criterion VALUES(12186,'psych12a3-smv-30',NULL,1,'this stops noise varying systematically with the IV, so differences in recall can be attributed to the IV [1].',1,1);
INSERT INTO rubric_criterion VALUES(12187,'psych12a3-smv-31',NULL,0,'Advantage: fewer participants are needed, and individual differences are controlled because each person serves as their own control [1];',1,1);
INSERT INTO rubric_criterion VALUES(12188,'psych12a3-smv-31',NULL,1,'disadvantage: order effects, such as practice or fatigue, may influence performance in the second condition [1];',1,1);
INSERT INTO rubric_criterion VALUES(12189,'psych12a3-smv-31',NULL,2,'reduce by counterbalancing the order in which participants complete the conditions [1].',1,1);
INSERT INTO rubric_criterion VALUES(12190,'psych12a3-smv-32',NULL,0,'Teacher differences: volunteer teachers may be more motivated or skilled, so gains could reflect the teacher rather than the program [1];',1,1);
INSERT INTO rubric_criterion VALUES(12191,'psych12a3-smv-32',NULL,1,'school differences: the schools may differ in resources or student background, so outcome differences could reflect the school [1];',1,1);
INSERT INTO rubric_criterion VALUES(12192,'psych12a3-smv-32',NULL,2,'because these variables are not controlled, the effect of the program cannot be isolated [1];',1,1);
INSERT INTO rubric_criterion VALUES(12193,'psych12a3-smv-32',NULL,3,'reduce by randomly allocating students or classes from the same school to the program and control groups, which balances these variables across groups [1].',1,1);
INSERT INTO rubric_criterion VALUES(12194,'psych12a3-smv-33',NULL,0,'To test the procedures, materials and measures so that problems can be identified and fixed before the main study [1];',1,1);
INSERT INTO rubric_criterion VALUES(12195,'psych12a3-smv-33',NULL,1,'to check whether the manipulation of the IV works and the study is feasible, saving time and resources [1].',1,1);
INSERT INTO rubric_criterion VALUES(12196,'psych12a3-smv-34',NULL,0,'Method: case study [1];',1,1);
INSERT INTO rubric_criterion VALUES(12197,'psych12a3-smv-34',NULL,1,'strength: provides rich, detailed in-depth data about an individual, including rare cases [1];',1,1);
INSERT INTO rubric_criterion VALUES(12198,'psych12a3-smv-34',NULL,2,'limitation: findings cannot be generalised to other people, and cause and effect cannot be established because no variables are manipulated [1].',1,1);
INSERT INTO rubric_criterion VALUES(12199,'psych12a3-smv-35',NULL,0,'The extent to which a measure or study measures what it is intended to measure [1].',1,1);
INSERT INTO rubric_criterion VALUES(12206,'psych12a3-sed-6',NULL,0,'Convenience sampling (1);',1,1);
INSERT INTO rubric_criterion VALUES(12207,'psych12a3-sed-6',NULL,1,'the sample may not be representative of the population, limiting generalisability, or may be biased (1).',1,1);
INSERT INTO rubric_criterion VALUES(12208,'psych12a3-sed-7',NULL,0,'Random sampling is the selection of participants from the population so that each member has an equal chance of being chosen (1);',1,1);
INSERT INTO rubric_criterion VALUES(12209,'psych12a3-sed-7',NULL,1,'random allocation is the assignment of the sample’s participants to experimental or control groups by chance (1);',1,1);
INSERT INTO rubric_criterion VALUES(12210,'psych12a3-sed-7',NULL,2,'sampling aims to produce a representative sample, whereas allocation aims to distribute participant characteristics evenly across groups to control participant variables (1).',1,1);
INSERT INTO rubric_criterion VALUES(12211,'psych12a3-sed-8',NULL,0,'Two separate groups are formed, one taught with the new method and one with the usual method, and their test scores are compared (1, with random allocation as an acceptable addition);',1,1);
INSERT INTO rubric_criterion VALUES(12212,'psych12a3-sed-8',NULL,1,'each participant experiences only one condition (1);',1,1);
INSERT INTO rubric_criterion VALUES(12213,'psych12a3-sed-8',NULL,2,'strength: no order effects/practice effects, since participants do not repeat the task (1).',1,1);
INSERT INTO rubric_criterion VALUES(12225,'psych12a3-sed-20',NULL,0,'Systematic error in the way participants are selected, so that the sample is not representative of the population [1].',1,1);
INSERT INTO rubric_criterion VALUES(12226,'psych12a3-sed-21',NULL,0,'In a within-subjects design the same participants experience every condition of the independent variable [1];',1,1);
INSERT INTO rubric_criterion VALUES(12227,'psych12a3-sed-21',NULL,1,'in a between-subjects design different participants are allocated to each condition [1].',1,1);
INSERT INTO rubric_criterion VALUES(12228,'psych12a3-sed-22',NULL,0,'To control order effects such as practice or fatigue [1], by varying the order of conditions across participants so that order effects are spread evenly between conditions [1].',2,1);
INSERT INTO rubric_criterion VALUES(12229,'psych12a3-sed-23',NULL,0,'Between-subjects: participants are randomly allocated to a walking group or a sitting group, and each person completes the concentration task in one condition only [1];',1,1);
INSERT INTO rubric_criterion VALUES(12230,'psych12a3-sed-23',NULL,1,'within-subjects: the same participants complete the task after walking and after sitting [1];',1,1);
INSERT INTO rubric_criterion VALUES(12231,'psych12a3-sed-23',NULL,2,'advantage of within-subjects: fewer participants are needed because each person contributes data to both conditions [1];',1,1);
INSERT INTO rubric_criterion VALUES(12232,'psych12a3-sed-23',NULL,3,'disadvantage of between-subjects: individual differences may affect the groups unevenly, since each person completes only one condition [1].',1,1);
INSERT INTO rubric_criterion VALUES(12239,'psych12a3-dac-6',NULL,0,'Mean = (210 + 220 + 230 + 240 + 250 + 250 + 260) ÷ 7 = 1660 ÷ 7 ≈ 237.1 ms (1);',1,1);
INSERT INTO rubric_criterion VALUES(12240,'psych12a3-dac-6',NULL,1,'mode = 250 ms (1).',1,1);
INSERT INTO rubric_criterion VALUES(12241,'psych12a3-dac-7',NULL,0,'Qualitative data are descriptive, non-numerical information about qualities or experiences (1); quantitative data are numerical measurements that can be statistically analysed (1);',1,1);
INSERT INTO rubric_criterion VALUES(12242,'psych12a3-dac-7',NULL,1,'examples: interview responses or observation notes (qualitative);',1,1);
INSERT INTO rubric_criterion VALUES(12243,'psych12a3-dac-7',NULL,2,'scores on a questionnaire, time taken or number correct (quantitative) (1 for both examples).',1,1);
INSERT INTO rubric_criterion VALUES(12244,'psych12a3-dac-8',NULL,0,'The conclusion may not be justified (1); without random allocation, participant variables (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(12245,'psych12a3-dac-8',NULL,1,'age, ability, motivation) may differ between groups and act as confounding variables (1);',1,1);
INSERT INTO rubric_criterion VALUES(12246,'psych12a3-dac-8',NULL,2,'so the difference may not be due only to sleep deprivation and a causal conclusion cannot be confidently drawn (1).',1,1);
INSERT INTO rubric_criterion VALUES(12264,'psych12a3-dac-26',NULL,0,'The extent to which the findings of a study, based on its sample, can be applied to the wider population or other settings [1].',1,1);
INSERT INTO rubric_criterion VALUES(12265,'psych12a3-dac-27',NULL,0,'45 ÷ 60 × 100 = 75% [1];',1,1);
INSERT INTO rubric_criterion VALUES(12266,'psych12a3-dac-27',NULL,1,'the number of participants who improved is numerical, so it is quantitative data [1].',1,1);
INSERT INTO rubric_criterion VALUES(12267,'psych12a3-dac-28',NULL,0,'Median = 9, the middle value of the ordered scores [1];',1,1);
INSERT INTO rubric_criterion VALUES(12268,'psych12a3-dac-28',NULL,1,'range = 12 − 4 = 8 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12269,'psych12a3-dac-29',NULL,0,'Limitations, such as a small or non-random sample or reliance on self-report, affect how confidently the results can be interpreted [1];',1,1);
INSERT INTO rubric_criterion VALUES(12270,'psych12a3-dac-29',NULL,1,'stating them shows the extent to which the findings can be generalised [1];',1,1);
INSERT INTO rubric_criterion VALUES(12271,'psych12a3-dac-29',NULL,2,'this avoids overstating the findings or implying causation that the design cannot support [1].',1,1);
INSERT INTO rubric_criterion VALUES(12272,'psych12a3-dac-30',NULL,0,'The sample is small and specific (15 first-year university students), so the finding cannot be generalised to all adults [1];',1,1);
INSERT INTO rubric_criterion VALUES(12273,'psych12a3-dac-30',NULL,1,'with no control group, practice effects or other factors could explain the improvement, so caffeine cannot be confirmed as the cause [1];',1,1);
INSERT INTO rubric_criterion VALUES(12274,'psych12a3-dac-30',NULL,2,'a better conclusion would state that reaction times improved after caffeine in this sample of 15 students, and that further research is needed [1].',1,1);
INSERT INTO rubric_criterion VALUES(12275,'psych12a3-dac-31',NULL,0,'Difference = 18.4 − 15.1 = 3.3 [1];',1,1);
INSERT INTO rubric_criterion VALUES(12276,'psych12a3-dac-31',NULL,1,'the experimental group had the higher mean score [1];',1,1);
INSERT INTO rubric_criterion VALUES(12277,'psych12a3-dac-31',NULL,2,'suggested conclusion: the intervention was associated with higher scores in this sample of 40 students [1];',1,1);
INSERT INTO rubric_criterion VALUES(12278,'psych12a3-dac-31',NULL,3,'the result may not generalise beyond this one school, a limitation that should be acknowledged [1].',1,1);
INSERT INTO rubric_criterion VALUES(12279,'psych12a3-dac-32',NULL,0,'‘Support’ means the data are consistent with the hypothesis [1];',1,1);
INSERT INTO rubric_criterion VALUES(12280,'psych12a3-dac-32',NULL,1,'‘prove’ overstates certainty, as a single study with a limited sample cannot establish a claim beyond doubt [1].',1,1);
INSERT INTO rubric_criterion VALUES(12281,'psych12a3-dac-33',NULL,0,'Mean = 1860 ÷ 6 = 310 ms [1];',1,1);
INSERT INTO rubric_criterion VALUES(12282,'psych12a3-dac-33',NULL,1,'median = (305 + 310) ÷ 2 = 307.5 ms [1];',1,1);
INSERT INTO rubric_criterion VALUES(12283,'psych12a3-dac-33',NULL,2,'range = 330 − 295 = 35 ms [1].',1,1);
INSERT INTO rubric_criterion VALUES(12284,'psych12a3-dac-34',NULL,0,'Excluding participants because of their results, rather than a pre-stated criterion, biases the data and reduces validity [1];',1,1);
INSERT INTO rubric_criterion VALUES(12285,'psych12a3-dac-34',NULL,1,'the conclusion ignores the three excluded participants, so the findings do not reflect the whole group tested [1];',1,1);
INSERT INTO rubric_criterion VALUES(12286,'psych12a3-dac-34',NULL,2,'the claim that the intervention ‘works for everyone’ overgeneralises beyond the sample studied [1];',1,1);
INSERT INTO rubric_criterion VALUES(12287,'psych12a3-dac-34',NULL,3,'a justified conclusion would report the exclusions and limit its claims to the participants tested [1].',1,1);
INSERT INTO rubric_criterion VALUES(12294,'psych12a3-eth-6',NULL,0,'Informed consent must be obtained from the students and from their parents/guardians as they are under 18 (1); confidentiality and privacy of responses must be maintained, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(12295,'psych12a3-eth-6',NULL,1,'de-identified data stored securely (1);',1,1);
INSERT INTO rubric_criterion VALUES(12296,'psych12a3-eth-6',NULL,2,'other acceptable: right to withdraw, voluntary participation, minimising distress with support available (1 for explaining how each is addressed).',1,1);
INSERT INTO rubric_criterion VALUES(12297,'psych12a3-eth-7',NULL,0,'Debriefing occurs at the end of the study to ensure participants leave in the same state in which they entered (1);',1,1);
INSERT INTO rubric_criterion VALUES(12298,'psych12a3-eth-7',NULL,1,'it explains the true aim and any deception used and answers questions (1);',1,1);
INSERT INTO rubric_criterion VALUES(12299,'psych12a3-eth-7',NULL,2,'it checks for distress/offers support and gives participants the opportunity to withdraw their data (1).',1,1);
INSERT INTO rubric_criterion VALUES(12300,'psych12a3-eth-8',NULL,0,'Deception may be necessary because knowing the true aim could alter participants’ behaviour and invalidate the results (1);',1,1);
INSERT INTO rubric_criterion VALUES(12301,'psych12a3-eth-8',NULL,1,'it is acceptable only if the potential benefits outweigh the risks, there is no suitable alternative, it causes no more than minimal harm, and participants are fully debriefed (1).',1,1);
INSERT INTO rubric_criterion VALUES(12317,'psych12a3-eth-24',NULL,0,'Anonymity means that no one, including the researcher, can link a participant to their data [1];',1,1);
INSERT INTO rubric_criterion VALUES(12318,'psych12a3-eth-24',NULL,1,'confidentiality means the researcher knows who the participant is but does not disclose or publish identifying information [1].',1,1);
INSERT INTO rubric_criterion VALUES(12319,'psych12a3-eth-25',NULL,0,'Informed consent requires participants to understand what the study involves, so the statement must be clear [1];',1,1);
INSERT INTO rubric_criterion VALUES(12320,'psych12a3-eth-25',NULL,1,'jargon may cause misunderstanding, meaning participants could agree without fully understanding the risks and procedures [1].',1,1);
INSERT INTO rubric_criterion VALUES(12321,'psych12a3-eth-26',NULL,0,'Tell participants that they can skip any question and withdraw at any time without penalty [1];',1,1);
INSERT INTO rubric_criterion VALUES(12322,'psych12a3-eth-26',NULL,1,'provide a debriefing at the end of the study that checks participants’ wellbeing [1];',1,1);
INSERT INTO rubric_criterion VALUES(12323,'psych12a3-eth-26',NULL,2,'give participants a list of support services, such as a counselling line [1].',1,1);
INSERT INTO rubric_criterion VALUES(12324,'psych12a3-eth-27',NULL,0,'Concern: the children cannot give informed consent and were not told they were being observed [1];',1,1);
INSERT INTO rubric_criterion VALUES(12325,'psych12a3-eth-27',NULL,1,'concern: their privacy is invaded because their behaviour is recorded without permission [1];',1,1);
INSERT INTO rubric_criterion VALUES(12326,'psych12a3-eth-27',NULL,2,'address the first by seeking ethics approval and consent from parents or guardians and the school, with the children’s assent where possible [1];',1,1);
INSERT INTO rubric_criterion VALUES(12327,'psych12a3-eth-27',NULL,3,'address the second by recording behaviour without identifying individuals and storing data securely [1].',1,1);
INSERT INTO rubric_criterion VALUES(12328,'psych12a3-eth-28',NULL,0,'A large payment may pressure people, particularly those experiencing financial hardship, to take part even though they would otherwise decline [1];',1,1);
INSERT INTO rubric_criterion VALUES(12329,'psych12a3-eth-28',NULL,1,'their participation is then not free, and they may accept risks they would normally avoid [1].',1,1);
INSERT INTO rubric_criterion VALUES(12330,'psych12a3-eth-29',NULL,0,'Replacement: use cell cultures or computer models where possible instead of live mice [1];',1,1);
INSERT INTO rubric_criterion VALUES(12331,'psych12a3-eth-29',NULL,1,'reduction: collect multiple measurements from each mouse where scientifically appropriate, so fewer mice are needed [1];',1,1);
INSERT INTO rubric_criterion VALUES(12332,'psych12a3-eth-29',NULL,2,'refinement: use humane anaesthetic and appropriate housing to reduce pain and distress [1].',1,1);
INSERT INTO rubric_criterion VALUES(12333,'psych12a3-eth-30',NULL,0,'Reviewing research proposals to assess their risks, benefits and ethical acceptability [1];',1,1);
INSERT INTO rubric_criterion VALUES(12334,'psych12a3-eth-30',NULL,1,'approving a study, or requiring changes, before data collection begins [1];',1,1);
INSERT INTO rubric_criterion VALUES(12335,'psych12a3-eth-30',NULL,2,'monitoring approved research, including adverse events and any changes to procedures [1].',1,1);
INSERT INTO rubric_criterion VALUES(12336,'psych12a3-eth-31',NULL,0,'Informed consent: participants must understand the study and their right to withdraw, and agree without pressure [1];',1,1);
INSERT INTO rubric_criterion VALUES(12337,'psych12a3-eth-31',NULL,1,'minimising harm: questions about mood may cause distress, so the researcher should monitor wellbeing and stop if needed [1];',1,1);
INSERT INTO rubric_criterion VALUES(12338,'psych12a3-eth-31',NULL,2,'confidentiality: sensitive health information must be stored securely and not identifiable in reports [1];',1,1);
INSERT INTO rubric_criterion VALUES(12339,'psych12a3-eth-31',NULL,3,'duty of care: participants at risk should be given information about support services and referral procedures [1].',1,1);
INSERT INTO rubric_criterion VALUES(12340,'psych12a3-eth-32',NULL,0,'Other researchers, practitioners and the public rely on accurate reports to build knowledge and make decisions [1];',1,1);
INSERT INTO rubric_criterion VALUES(12341,'psych12a3-eth-32',NULL,1,'withholding unsupported results would distort the evidence base and waste participants’ contributions [1].',1,1);
INSERT INTO rubric_criterion VALUES(12342,'psych12a3-eth-33',NULL,0,'Duty of care [1]',1,1);
INSERT INTO rubric_criterion VALUES(12349,'psych12a3-vre-6',NULL,0,'Internal validity is the extent to which the results are due to the manipulation of the IV and not other factors such as confounding variables (1);',1,1);
INSERT INTO rubric_criterion VALUES(12350,'psych12a3-vre-6',NULL,1,'external validity is the extent to which the results can be generalised to other people, settings and times (1).',1,1);
INSERT INTO rubric_criterion VALUES(12351,'psych12a3-vre-7',NULL,0,'Random errors are unpredictable variations in measurement that vary in size and direction and affect precision (1);',1,1);
INSERT INTO rubric_criterion VALUES(12352,'psych12a3-vre-7',NULL,1,'systematic errors are consistent biases in the same direction that affect accuracy (1);',1,1);
INSERT INTO rubric_criterion VALUES(12353,'psych12a3-vre-7',NULL,2,'random errors reduced by taking repeated measurements and averaging, or using a larger sample (1);',1,1);
INSERT INTO rubric_criterion VALUES(12354,'psych12a3-vre-7',NULL,3,'systematic errors reduced by calibrating equipment, standardising procedures, or using a control group/blinding (1).',1,1);
INSERT INTO rubric_criterion VALUES(12355,'psych12a3-vre-8',NULL,0,'Threat: participant expectations/demand characteristics or placebo effect, or investigator effect (1);',1,1);
INSERT INTO rubric_criterion VALUES(12356,'psych12a3-vre-8',NULL,1,'in a double-blind procedure neither participants nor the researcher(s) collecting data know who is in the experimental or control group (1);',1,1);
INSERT INTO rubric_criterion VALUES(12357,'psych12a3-vre-8',NULL,2,'this reduces the influence of expectations on responses and measurement, improving validity (1).',1,1);
INSERT INTO rubric_criterion VALUES(12376,'psych12a3-vre-27',NULL,0,'Reliability is the extent to which a test gives consistent results [1];',1,1);
INSERT INTO rubric_criterion VALUES(12377,'psych12a3-vre-27',NULL,1,'a reliable test produces similar scores when the same participants are tested again under the same conditions [1].',1,1);
INSERT INTO rubric_criterion VALUES(12378,'psych12a3-vre-28',NULL,0,'A variable other than the independent variable that changes systematically with it and may affect the dependent variable, so it provides an alternative explanation for the results [1].',1,1);
INSERT INTO rubric_criterion VALUES(12379,'psych12a3-vre-29',NULL,0,'External validity (generalisability) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12380,'psych12a3-vre-30',NULL,0,'A pilot study tests the procedures, instructions and equipment with a small group before the main study [1];',1,1);
INSERT INTO rubric_criterion VALUES(12381,'psych12a3-vre-30',NULL,1,'problems such as unclear instructions or inconsistent timing are identified and corrected [1];',1,1);
INSERT INTO rubric_criterion VALUES(12382,'psych12a3-vre-30',NULL,2,'this leads to standardised procedures that produce more consistent results across all participants [1].',1,1);
INSERT INTO rubric_criterion VALUES(12383,'psych12a3-vre-31',NULL,0,'Standardised procedures mean all participants experience the same conditions, reducing variation caused by differences in instructions or handling [1];',1,1);
INSERT INTO rubric_criterion VALUES(12384,'psych12a3-vre-31',NULL,1,'this produces more consistent results that can be repeated [1].',1,1);
INSERT INTO rubric_criterion VALUES(12385,'psych12a3-vre-32',NULL,0,'Mean reading = 150.6 ÷ 4 = 37.65 °C [1];',1,1);
INSERT INTO rubric_criterion VALUES(12386,'psych12a3-vre-32',NULL,1,'mean error = 37.65 − 37.0 = +0.65 °C, so the thermometer reads too high [1];',1,1);
INSERT INTO rubric_criterion VALUES(12387,'psych12a3-vre-32',NULL,2,'this consistent offset in one direction is systematic error, which affects accuracy [1];',1,1);
INSERT INTO rubric_criterion VALUES(12388,'psych12a3-vre-32',NULL,3,'the small spread of readings (37.5–37.8 °C) shows low random error, so the thermometer is precise [1].',1,1);
INSERT INTO rubric_criterion VALUES(12389,'psych12a3-vre-33',NULL,0,'Confusing wording means participants may interpret questions differently, producing inconsistent answers [1];',1,1);
INSERT INTO rubric_criterion VALUES(12390,'psych12a3-vre-33',NULL,1,'this lowers the reliability of the questionnaire [1];',1,1);
INSERT INTO rubric_criterion VALUES(12391,'psych12a3-vre-33',NULL,2,'responses may reflect confusion about the wording rather than stress, which lowers validity [1].',1,1);
INSERT INTO rubric_criterion VALUES(12392,'psych12a3-vre-34',NULL,0,'Accuracy is how close a measurement is to the true value [1];',1,1);
INSERT INTO rubric_criterion VALUES(12393,'psych12a3-vre-34',NULL,1,'precision is how close repeated measurements are to each other, showing consistency [1].',1,1);
INSERT INTO rubric_criterion VALUES(12400,'methods12a1-lin-6',NULL,0,'Midpoint of AB = (2, 4) [1]; gradient of AB = 4/6 = 2/3, so perpendicular gradient = −3/2 [1];',1,1);
INSERT INTO rubric_criterion VALUES(12401,'methods12a1-lin-6',NULL,1,'y − 4 = −(3/2)(x − 2), giving y = −3x/2 + 7, or 3x + 2y = 14 [1].',1,1);
