INSERT INTO rubric_criterion VALUES(12403,'methods12a1-lin-7',NULL,0,'From the second equation y = 5x − 7 [1]; substitute: 3x + 10x − 14 = 12, so 13x = 26, x = 2 and y = 3 [1];',1,1);
