INSERT INTO rubric_criterion VALUES(12405,'methods12a1-lin-7',NULL,2,'Check: 3(2) + 2(3) = 12 and 5(2) − 3 = 7.',1,1);
INSERT INTO rubric_criterion VALUES(12406,'methods12a1-lin-8',NULL,0,'(a) Gradient 2.2: the cost increases by $2.20 for each extra kilometre; vertical intercept 4.5: the fixed charge of $4.50 at the start of the trip (d = 0) [1 for both].',1,1);
INSERT INTO rubric_criterion VALUES(12407,'methods12a1-lin-8',NULL,1,'(b) 26.5 = 4.5 + 2.2d [1];',1,1);
INSERT INTO rubric_criterion VALUES(12408,'methods12a1-lin-8',NULL,2,'2.2d = 22, so d = 10 km [1].',1,1);
INSERT INTO rubric_criterion VALUES(12427,'methods12a1-lin-27',NULL,0,'Gradient = (8 − (−1))/(5 − 2) = 9/3 = 3 [1];',1,1);
INSERT INTO rubric_criterion VALUES(12428,'methods12a1-lin-27',NULL,1,'y + 1 = 3(x − 2), so y = 3x − 7 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12429,'methods12a1-lin-28',NULL,0,'(a) AB = √((5 − (−4))² + (−9 − 3)²) = √(81 + 144) [1] = √225 = 15 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12430,'methods12a1-lin-28',NULL,1,'(b) Midpoint = ((−4 + 5)/2, (3 + (−9))/2) = (1/2, −3) [1].',2,1);
INSERT INTO rubric_criterion VALUES(12431,'methods12a1-lin-29',NULL,0,'Gradient of AB = 2/4 = 1/2 [1];',1,1);
INSERT INTO rubric_criterion VALUES(12432,'methods12a1-lin-29',NULL,1,'gradient of AC = 2/(−1) = −2 [1];',1,1);
INSERT INTO rubric_criterion VALUES(12433,'methods12a1-lin-29',NULL,2,'the product is −1, so AB ⊥ AC and the angle at A is 90° [1].',1,1);
INSERT INTO rubric_criterion VALUES(12434,'methods12a1-lin-29',NULL,3,'AB = √20, AC = √5, so area = ½ × √20 × √5 = ½ × 10 = 5 square units [1].',1,1);
INSERT INTO rubric_criterion VALUES(12435,'methods12a1-lin-30',NULL,0,'Substitute y = 2x − 1: 3x + 2(2x − 1) = 12 [1];',1,1);
INSERT INTO rubric_criterion VALUES(12436,'methods12a1-lin-30',NULL,1,'7x − 2 = 12, so x = 2 [1];',1,1);
INSERT INTO rubric_criterion VALUES(12437,'methods12a1-lin-30',NULL,2,'y = 2(2) − 1 = 3, so the intersection is (2, 3) [1].',1,1);
