INSERT INTO rubric_criterion VALUES(12439,'methods12a1-lin-31',NULL,1,'10 − k = 9, so k = 1 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12440,'methods12a1-lin-32',NULL,0,'Rearrange: y = 2x − 5/2, so the gradient is 2 [1];',1,1);
INSERT INTO rubric_criterion VALUES(12441,'methods12a1-lin-32',NULL,1,'parallel line has gradient 2, so y + 2 = 2(x − 3) [1];',1,1);
INSERT INTO rubric_criterion VALUES(12442,'methods12a1-lin-32',NULL,2,'y = 2x − 8 [1].',1,1);
