INSERT INTO rubric_criterion VALUES(12444,'methods12a1-lin-33',NULL,1,'(b) C = 40 + 8(5) = $80 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12445,'methods12a1-lin-33',NULL,2,'(c) At t = 3: X = $64, Y = $54, so Company Y is cheaper [1].',2,1);
INSERT INTO rubric_criterion VALUES(12446,'methods12a1-lin-34',NULL,0,'Put y = 0: 3x = 30, so the x-intercept is (10, 0) [1];',1,1);
INSERT INTO rubric_criterion VALUES(12447,'methods12a1-lin-34',NULL,1,'put x = 0: −5y = 30, so the y-intercept is (0, −6) [1];',1,1);
