INSERT INTO rubric_criterion VALUES(12449,'methods12a1-lin-35',NULL,0,'Let the point be (a, 0): (a − 1)² + 9 = (a − 5)² + 1 [1]; a² − 2a + 10 = a² − 10a + 26, so 8a = 16 [1];',1,1);
