INSERT INTO rubric_criterion VALUES(12452,'methods12a1-lin-36',NULL,0,'Gradient of AB = (4 − (−2))/(2 − (−1)) = 6/3 = 2 [1]; gradient of BC = (8 − 4)/(4 − 2) = 2;',1,1);
INSERT INTO rubric_criterion VALUES(12453,'methods12a1-lin-36',NULL,1,'equal gradients with the common point B, so the points are collinear [1].',1,1);
