INSERT INTO rubric_criterion VALUES(12466,'methods12a1-fdr-6',NULL,0,'(a) f(−2) = 2(4) + 6 = 14 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12467,'methods12a1-fdr-6',NULL,1,'(b) f(a + 1) = 2(a² + 2a + 1) − 3a − 3 = 2a² + a − 1 [1].',1,1);
