INSERT INTO rubric_criterion VALUES(12469,'methods12a1-fdr-7',NULL,0,'(a) Need 9 − x² ≥ 0, so domain = [−3, 3] [1]; the output is a square root so is ≥ 0, with maximum √9 = 3 at x = 0, so range = [0, 3] [1].',1,1);
