INSERT INTO rubric_criterion VALUES(12471,'methods12a1-fdr-7',NULL,2,'for example x = 0 gives y = 3 and y = −3 [1], so one input has two outputs and it fails the vertical line test [1].',1,1);
INSERT INTO rubric_criterion VALUES(12472,'methods12a1-fdr-7',NULL,3,'f is only the upper semicircle.',1,1);
