INSERT INTO rubric_criterion VALUES(12501,'methods12a1-fdr-29',NULL,0,'(a) f(x) = (x + 1)² − 9, so the minimum is −9 and range = [−9, ∞) [1][1].',1,1);
INSERT INTO rubric_criterion VALUES(12502,'methods12a1-fdr-29',NULL,1,'(b) The vertex x = −1 is outside [0, 3], so f is increasing on the domain [1];',1,1);
