INSERT INTO rubric_criterion VALUES(12504,'methods12a1-fdr-30',NULL,0,'(a) When x = 5, y² = 4 so y = 2 or y = −2 [1];',1,1);
INSERT INTO rubric_criterion VALUES(12505,'methods12a1-fdr-30',NULL,1,'one input gives two outputs, so a vertical line cuts the graph twice and it is not a function [1].',1,1);
INSERT INTO rubric_criterion VALUES(12506,'methods12a1-fdr-30',NULL,2,'(b) Domain = [1, ∞) and range = [0, ∞) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12507,'methods12a1-fdr-31',NULL,0,'(a) Length = 20 − w, so A(w) = w(20 − w) = 20w − w² [1].',1,1);
