INSERT INTO rubric_criterion VALUES(12509,'methods12a1-fdr-31',NULL,2,'The maximum is A(10) = 100 and A approaches 0 at the ends, so range = (0, 100] [1].',1,1);
INSERT INTO rubric_criterion VALUES(12510,'methods12a1-fdr-32',NULL,0,'(a) f(x) = 2x − 4 for x ≥ 2 and f(x) = 4 − 2x for x < 2 [1].',1,1);
