INSERT INTO rubric_criterion VALUES(12528,'methods12a1-quad-6',NULL,0,'Quadratic formula: x = (−2 ± √(4 + 48))/6 [1] = (−2 ± √52)/6 = (−2 ± 2√13)/6 = (−1 ± √13)/3 [1].',2,1);
INSERT INTO rubric_criterion VALUES(12529,'methods12a1-quad-7',NULL,0,'y-intercept: (0, −5) [1].',1,1);
