INSERT INTO rubric_criterion VALUES(12533,'methods12a1-quad-8',NULL,0,'Set x² + 1 = 2x + k, so x² − 2x + (1 − k) = 0 [1]. Discriminant Δ = 4 − 4(1 − k) = 4k.',1,1);
