INSERT INTO rubric_criterion VALUES(12583,'methods12a1-quad-37',NULL,1,'Since Δ < 0 there are no real roots, so no x-intercepts [1].',1,1);
INSERT INTO rubric_criterion VALUES(12584,'methods12a1-quad-37',NULL,2,'Minimum at x = 3/4: y = 2(9/16) − 9/4 + 4 = 23/8 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12585,'methods12a1-quad-38',NULL,0,'The axis passes midway between the x-intercepts 4 and −10, so x = −3 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12592,'methods12a1-cq-6',NULL,0,'f(x) = x(x² − x − 6) = x(x − 3)(x + 2) [1]. x-intercepts at −2, 0 and 3;',1,1);
INSERT INTO rubric_criterion VALUES(12593,'methods12a1-cq-6',NULL,1,'y-intercept (0, 0) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12594,'methods12a1-cq-6',NULL,2,'Positive leading coefficient, so y → −∞ as x → −∞ and y → ∞ as x → ∞ [1].',1,1);
INSERT INTO rubric_criterion VALUES(12595,'methods12a1-cq-6',NULL,3,'Graph crosses the axis at each intercept (three single factors), positive between −2 and 0 and negative between 0 and 3 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12596,'methods12a1-cq-7',NULL,0,'Form: y = a(x + 3)²(x − 2) [1]. At x = 0: a(9)(−2) = −18a = 18, so a = −1 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12597,'methods12a1-cq-7',NULL,1,'y = −(x + 3)²(x − 2).',1,1);
INSERT INTO rubric_criterion VALUES(12598,'methods12a1-cq-7',NULL,2,'Leading coefficient negative, so y → −∞ as x → ∞ [1].',1,1);
INSERT INTO rubric_criterion VALUES(12599,'methods12a1-cq-8',NULL,0,'(a) x-intercepts at −3, 0, 2. At x = 0 the factor is squared so the graph touches the axis and turns (flat);',1,1);
INSERT INTO rubric_criterion VALUES(12600,'methods12a1-cq-8',NULL,1,'crosses at −3 and 2 [1]. Leading coefficient −1 (degree 4), so y → −∞ at both ends [1].',1,1);
INSERT INTO rubric_criterion VALUES(12601,'methods12a1-cq-8',NULL,2,'(b) Test: f(1) = −1(−1)(4) = 4 > 0, f(−1) = −1(−3)(2) = 6 > 0, f(3) < 0, f(−4) < 0 [1]. So f(x) > 0 for −3 < x < 2, x ≠ 0, i.e.',1,1);
INSERT INTO rubric_criterion VALUES(12602,'methods12a1-cq-8',NULL,3,'(−3, 0) ∪ (0, 2) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12616,'methods12a1-cq-22',NULL,0,'x-intercepts at x = −1 and x = 2 [1]. y-intercept: (1)²(2) = 2, so (0, 2) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12617,'methods12a1-cq-22',NULL,1,'The factor (x + 1) is squared, so the graph touches the x-axis and turns at x = −1;',1,1);
INSERT INTO rubric_criterion VALUES(12618,'methods12a1-cq-22',NULL,2,'it crosses at x = 2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12619,'methods12a1-cq-22',NULL,3,'The leading term is −x³ (negative), so y → ∞ as x → −∞ and y → −∞ as x → ∞ [1].',1,1);
INSERT INTO rubric_criterion VALUES(12620,'methods12a1-cq-23',NULL,0,'Let u = x², so u² − 3u − 4 = 0 and (u − 4)(u + 1) = 0, giving (x² − 4)(x² + 1) = 0 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12621,'methods12a1-cq-23',NULL,1,'x² = 4 gives x = ±2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12622,'methods12a1-cq-23',NULL,2,'x² = −1 has no real solutions, so the only x-intercepts are (−2, 0) and (2, 0) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12623,'methods12a1-cq-24',NULL,0,'Form: y = a(x − 2)²(x + 1)(x − 4) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12624,'methods12a1-cq-24',NULL,1,'At x = 0: a(4)(1)(−4) = −16a = 16, so a = −1 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12625,'methods12a1-cq-24',NULL,2,'y = −(x − 2)²(x + 1)(x − 4) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12626,'methods12a1-cq-25',NULL,0,'f has even degree and negative leading coefficient, so f(x) → −∞ as x → −∞ and as x → ∞ [1].',1,1);
INSERT INTO rubric_criterion VALUES(12627,'methods12a1-cq-25',NULL,1,'g has odd degree and positive leading coefficient, so g(x) → −∞ as x → −∞ and g(x) → ∞ as x → ∞ [1].',1,1);
INSERT INTO rubric_criterion VALUES(12628,'methods12a1-cq-26',NULL,0,'(a) y = −(x − 3)³ + 2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12629,'methods12a1-cq-26',NULL,1,'(b) The inflection point moves from (0, 0) to (3, 2) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12630,'methods12a1-cq-26',NULL,2,'(c) y-intercept: −(−3)³ + 2 = 27 + 2 = 29, so (0, 29) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12631,'methods12a1-cq-26',NULL,3,'x-intercept: (x − 3)³ = 2, so x = 3 + ∛2 ≈ 4.26 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12632,'methods12a1-cq-27',NULL,0,'x³ − 9x = x(x − 3)(x + 3), with roots −3, 0 and 3 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12633,'methods12a1-cq-27',NULL,1,'Positive leading coefficient: the graph is below the axis for x < −3 and for 0 < x < 3, and above for −3 < x < 0 and x > 3 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12634,'methods12a1-cq-27',NULL,2,'So x³ − 9x ≤ 0 for x ≤ −3 or 0 ≤ x ≤ 3 (roots included) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12635,'methods12a1-cq-28',NULL,0,'The ends of a cubic go in opposite directions (one up, one down), so the continuous graph must cross the x-axis at least once [1].',1,1);
INSERT INTO rubric_criterion VALUES(12636,'methods12a1-cq-28',NULL,1,'The ends of a quartic go in the same direction, so with a positive leading coefficient the graph can stay entirely above the axis [1].',1,1);
INSERT INTO rubric_criterion VALUES(12637,'methods12a1-cq-28',NULL,2,'Example: y = x⁴ + 1 (any quartic whose minimum is above the axis) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12638,'methods12a1-cq-29',NULL,0,'Form: y = a(x + 2)(x − 1)(x − 3) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12639,'methods12a1-cq-29',NULL,1,'At x = 2: a(4)(1)(−1) = −4a = 8 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12640,'methods12a1-cq-29',NULL,2,'So a = −2 and y = −2(x + 2)(x − 1)(x − 3) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12641,'methods12a1-cq-29',NULL,3,'At x = 0: −2(2)(−1)(−3) = −12, so the y-intercept is (0, −12) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12642,'methods12a1-cq-30',NULL,0,'(a) The base is (12 − 2x) by (8 − 2x) and the height is x, so V = x(12 − 2x)(8 − 2x) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12643,'methods12a1-cq-30',NULL,1,'(b) x-intercepts at x = 0, 4 and 6 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12644,'methods12a1-cq-30',NULL,2,'The cut must be positive and less than half the shorter side, so 0 < x < 4 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12650,'methods12a1-cq-36',NULL,0,'f(1) = 0 gives a + b = −7 and f(2) = 0 gives 4a + 2b = −14 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12651,'methods12a1-cq-36',NULL,1,'Solving gives a = 0 and b = −7 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12652,'methods12a1-cq-36',NULL,2,'f(x) = x³ − 7x + 6 = (x − 1)(x − 2)(x + 3), so the third intercept is x = −3 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12653,'methods12a1-cq-37',NULL,0,'y = (x² − 4)² = (x − 2)²(x + 2)² [1].',1,1);
INSERT INTO rubric_criterion VALUES(12654,'methods12a1-cq-37',NULL,1,'x-intercepts at x = ±2, where the graph touches the axis (repeated factors) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12655,'methods12a1-cq-37',NULL,2,'y-intercept (0, 16), which is a local maximum [1].',1,1);
INSERT INTO rubric_criterion VALUES(12656,'methods12a1-cq-37',NULL,3,'Positive leading coefficient so y → ∞ as x → ±∞, giving a W-shape [1].',1,1);
INSERT INTO rubric_criterion VALUES(12663,'methods12a1-frt-6',NULL,0,'P(2) = 8 − 12 − 8 + 12 = 0, so (x − 2) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12664,'methods12a1-frt-6',NULL,1,'Division gives P(x) = (x − 2)(x² − x − 6) [1] = (x − 2)(x − 3)(x + 2) [1].',2,1);
INSERT INTO rubric_criterion VALUES(12665,'methods12a1-frt-7',NULL,0,'P(1) = 0: 1 + a + b − 6 = 0, so a + b = 5 [1]. P(−1) = 2: −1 + a − b − 6 = 2, so a − b = 9 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12666,'methods12a1-frt-7',NULL,1,'Adding: 2a = 14, a = 7 and b = −2 [1]. Check: P(x) = x³ + 7x² − 2x − 6;',1,1);
INSERT INTO rubric_criterion VALUES(12667,'methods12a1-frt-7',NULL,2,'P(1) = 0 and P(−1) = 2.',1,1);
INSERT INTO rubric_criterion VALUES(12668,'methods12a1-frt-8',NULL,0,'Q(x) = x² + 4x + 3 [1]; remainder R = P(2) = 8 + 8 − 10 + 1 = 7 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12669,'methods12a1-frt-8',NULL,1,'P(x) = (x − 2)(x² + 4x + 3) + 7 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12670,'methods12a1-frt-8',NULL,2,'Check: (x − 2)(x² + 4x + 3) = x³ + 2x² − 5x − 6, and adding 7 gives P(x).',1,1);
INSERT INTO rubric_criterion VALUES(12689,'methods12a1-frt-27',NULL,0,'By the remainder theorem the remainder is P(−1) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12690,'methods12a1-frt-27',NULL,1,'P(−1) = −2 − 1 − 3 − 4 = −10 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12691,'methods12a1-frt-28',NULL,0,'P(−3) = −27 + 18 + 15 − 6 = 0, so (x + 3) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12692,'methods12a1-frt-28',NULL,1,'Division gives P(x) = (x + 3)(x² − x − 2) [1] = (x + 3)(x − 2)(x + 1) [1].',2,1);
INSERT INTO rubric_criterion VALUES(12693,'methods12a1-frt-29',NULL,0,'P(3) = 27 + 9k − 21 + 6 = 12 + 9k = −6 [1], so k = −2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12694,'methods12a1-frt-29',NULL,1,'Then P(x) = x³ − 2x² − 7x + 6 and P(−1) = −1 − 2 + 7 + 6 = 10, so the remainder is 10 [1].',2,1);
INSERT INTO rubric_criterion VALUES(12695,'methods12a1-frt-30',NULL,0,'Let P(x) = x³ − 3x² − 6x + 8.',1,1);
INSERT INTO rubric_criterion VALUES(12696,'methods12a1-frt-30',NULL,1,'P(1) = 1 − 3 − 6 + 8 = 0, so (x − 1) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12697,'methods12a1-frt-30',NULL,2,'Division gives P(x) = (x − 1)(x² − 2x − 8) [1] = (x − 1)(x − 4)(x + 2) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12698,'methods12a1-frt-30',NULL,3,'So x = 1, x = 4 or x = −2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12699,'methods12a1-frt-31',NULL,0,'P(1) = 1 + 1 − 7 − 1 + 6 = 0 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12700,'methods12a1-frt-31',NULL,1,'P(−1) = 1 − 1 − 7 + 1 + 6 = 0 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12701,'methods12a1-frt-31',NULL,2,'So (x − 1)(x + 1) = x² − 1 is a factor, and dividing gives P(x) = (x² − 1)(x² + x − 6) [1] = (x − 1)(x + 1)(x − 2)(x + 3) [1].',2,1);
INSERT INTO rubric_criterion VALUES(12702,'methods12a1-frt-32',NULL,0,'The remainder is P(1/2) since 2x − 1 = 0 when x = 1/2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12703,'methods12a1-frt-32',NULL,1,'P(1/2) = 6/8 − 1/4 + 2 − 1 = 3/2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12704,'methods12a1-frt-33',NULL,0,'P(−1/2) = −1/4 + 7/4 − k/2 − 3 = 0 [1], so −3/2 − k/2 = 0 and k = −3 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12705,'methods12a1-frt-33',NULL,1,'Division gives P(x) = (2x + 1)(x² + 3x − 3), so the quotient is x² + 3x − 3 [1].',2,1);
INSERT INTO rubric_criterion VALUES(12706,'methods12a1-frt-34',NULL,0,'P(−2) = −8 + 16 + 2 − 6 = 4 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12707,'methods12a1-frt-34',NULL,1,'Since P(−2) ≠ 0, (x + 2) is not a factor of P(x) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12708,'methods12a1-frt-35',NULL,0,'V(−3) = −27 + 27 + 12 − 12 = 0, so (x + 3) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12709,'methods12a1-frt-35',NULL,1,'Division gives V(x) = (x + 3)(x² − 4) [1] = (x + 3)(x − 2)(x + 2), so the dimensions are (x + 3), (x − 2) and (x + 2) cm [1].',1,1);
INSERT INTO rubric_criterion VALUES(12710,'methods12a1-frt-35',NULL,2,'When x = 5: 8 × 3 × 7 = 168 cm³ [1].',2,1);
INSERT INTO rubric_criterion VALUES(12711,'methods12a1-frt-36',NULL,0,'Let P(x) = 2x³ − 3x² − 11x + 6. P(3) = 54 − 27 − 33 + 6 = 0, so (x − 3) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12712,'methods12a1-frt-36',NULL,1,'Division gives P(x) = (x − 3)(2x² + 3x − 2) = (x − 3)(2x − 1)(x + 2) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12713,'methods12a1-frt-36',NULL,2,'So x = 3, x = 1/2 or x = −2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12714,'methods12a1-frt-37',NULL,0,'P(1) = 1 − 5 + 7 − 3 = 0, so (x − 1) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12715,'methods12a1-frt-37',NULL,1,'Division gives P(x) = (x − 1)(x² − 4x + 3) [1] = (x − 1)²(x − 3), so (x − 1) is the repeated factor [1].',2,1);
INSERT INTO rubric_criterion VALUES(12716,'methods12a1-frt-38',NULL,0,'P(x) = (x − 3)(x² + 2x − 1) + 4 [1] = x³ − x² − 7x + 3 + 4, which gives P(x) = x³ − x² − 7x + 7 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12717,'methods12a1-frt-38',NULL,1,'P(3) = 27 − 9 − 21 + 7 = 4, as required [1].',2,1);
INSERT INTO rubric_criterion VALUES(12719,'vce-methods12-fr-c1',NULL,0,'a = −1;',1,1);
INSERT INTO rubric_criterion VALUES(12720,'vce-methods12-fr-c1',NULL,1,'remainder 6',1,1);
INSERT INTO rubric_criterion VALUES(12726,'methods12a1-spe-6',NULL,0,'Try x = 2: 8 − 12 − 20 + 24 = 0, so (x − 2) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12727,'methods12a1-spe-6',NULL,1,'Dividing: (x − 2)(x² − x − 12) [1] = (x − 2)(x − 4)(x + 3), so x = 2, 4 or −3 [1].',2,1);
INSERT INTO rubric_criterion VALUES(12728,'methods12a1-spe-7',NULL,0,'(a) Let u = x²: u² − 10u + 9 = (u − 1)(u − 9) = 0, so x² = 1 or 9, x = ±1 or ±3 [2].',1,1);
INSERT INTO rubric_criterion VALUES(12729,'methods12a1-spe-7',NULL,1,'(b) u² + u − 6 = (u + 3)(u − 2) = 0;',1,1);
INSERT INTO rubric_criterion VALUES(12730,'methods12a1-spe-7',NULL,2,'x² = −3 has no real solution, x² = 2 gives x = ±√2 [2].',2,1);
INSERT INTO rubric_criterion VALUES(12731,'methods12a1-spe-8',NULL,0,'x(x + 2)(x + 5) = 120, so x³ + 7x² + 10x − 120 = 0 [1]. Try x = 3: 27 + 63 + 30 − 120 = 0, so (x − 3) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12732,'methods12a1-spe-8',NULL,1,'Dividing: (x − 3)(x² + 10x + 40) = 0;',1,1);
INSERT INTO rubric_criterion VALUES(12733,'methods12a1-spe-8',NULL,2,'the quadratic has discriminant 100 − 160 < 0 so no further real roots [1].',1,1);
INSERT INTO rubric_criterion VALUES(12734,'methods12a1-spe-8',NULL,3,'x = 3, so the dimensions are 3 cm, 5 cm, 8 cm (3 × 5 × 8 = 120) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12752,'methods12a1-spe-26',NULL,0,'x(x² − 9) = x(x − 3)(x + 3) = 0 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12753,'methods12a1-spe-26',NULL,1,'x = 0, x = 3 or x = −3 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12754,'methods12a1-spe-27',NULL,0,'Try x = 2: 8 + 8 − 10 − 6 = 0, so (x − 2) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12755,'methods12a1-spe-27',NULL,1,'Dividing gives (x − 2)(x² + 4x + 3) [1] = (x − 2)(x + 1)(x + 3), so x = 2, −1 or −3 [1].',2,1);
INSERT INTO rubric_criterion VALUES(12756,'methods12a1-spe-28',NULL,0,'Group: x²(2x − 1) − 4(2x − 1) [1] = (2x − 1)(x² − 4) = (2x − 1)(x − 2)(x + 2) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12757,'methods12a1-spe-28',NULL,1,'So x = 1/2, x = 2 or x = −2 [1].',2,1);
INSERT INTO rubric_criterion VALUES(12758,'methods12a1-spe-29',NULL,0,'Let u = x²: 2u² − 11u + 5 = 0 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12759,'methods12a1-spe-29',NULL,1,'(2u − 1)(u − 5) = 0, so u = 1/2 or u = 5 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12760,'methods12a1-spe-29',NULL,2,'x² = 1/2 gives x = ±√2/2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12761,'methods12a1-spe-29',NULL,3,'x² = 5 gives x = ±√5 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12762,'methods12a1-spe-30',NULL,0,'Substitute x = −1: −1 + k + 4 − 6 = 0 [1], so k = 3 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12763,'methods12a1-spe-30',NULL,1,'Dividing x³ + 3x² − 4x − 6 by (x + 1) gives (x + 1)(x² + 2x − 6) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12764,'methods12a1-spe-30',NULL,2,'The quadratic gives x = −1 ± √7, so the solutions are x = −1, −1 + √7 and −1 − √7 [1].',2,1);
INSERT INTO rubric_criterion VALUES(12765,'methods12a1-spe-31',NULL,0,'The box has base (12 − 2x) by (12 − 2x) and height x, so x(12 − 2x)² = 128, giving 4x³ − 48x² + 144x − 128 = 0 and x³ − 12x² + 36x − 32 = 0 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12766,'methods12a1-spe-31',NULL,1,'Try x = 2: 8 − 48 + 72 − 32 = 0, so (x − 2) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12767,'methods12a1-spe-31',NULL,2,'Dividing: (x − 2)(x² − 10x + 16) = (x − 2)(x − 2)(x − 8), so x = 2 or x = 8 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12768,'methods12a1-spe-31',NULL,3,'Since 12 − 2x > 0 requires x < 6, x = 8 is rejected and x = 2 cm [1].',1,1);
INSERT INTO rubric_criterion VALUES(12769,'methods12a1-spe-32',NULL,0,'Let u = x² − 3x: u² − 2u − 8 = 0 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12770,'methods12a1-spe-32',NULL,1,'(u − 4)(u + 2) = 0, so u = 4 or u = −2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12771,'methods12a1-spe-32',NULL,2,'x² − 3x − 4 = 0 gives (x − 4)(x + 1) = 0, so x = 4 or x = −1 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12772,'methods12a1-spe-32',NULL,3,'x² − 3x + 2 = 0 gives (x − 1)(x − 2) = 0, so x = 1 or x = 2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12773,'methods12a1-spe-33',NULL,0,'Try x = 1: 1 − 7 + 14 − 8 = 0, so (x − 1) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12774,'methods12a1-spe-33',NULL,1,'Dividing gives (x − 1)(x² − 6x + 8) [1] = (x − 1)(x − 2)(x − 4), so x = 1, 2 or 4 [1].',2,1);
INSERT INTO rubric_criterion VALUES(12775,'methods12a1-spe-34',NULL,0,'Dividing by x² assumes x ≠ 0, so the solution x = 0 is lost [1].',1,1);
INSERT INTO rubric_criterion VALUES(12776,'methods12a1-spe-34',NULL,1,'Correctly, x³ − 4x² = x²(x − 4) = 0, so x = 0 or x = 4 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12779,'methods12a1-spe-37',NULL,0,'Test x = 3: 27 + 36 − 33 − 30 = 0, so (x − 3) is a factor [1].',1,1);
INSERT INTO rubric_criterion VALUES(12780,'methods12a1-spe-37',NULL,1,'x³ + 4x² − 11x − 30 = (x − 3)(x² + 7x + 10) = (x − 3)(x + 2)(x + 5) [1].',1,1);
INSERT INTO rubric_criterion VALUES(12781,'methods12a1-spe-37',NULL,2,'Solutions x = 3, x = −2, x = −5 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12782,'methods12a1-spe-38',NULL,0,'x²(x + 2) = 45, so x³ + 2x² − 45 = 0 [1].',1,1);
INSERT INTO rubric_criterion VALUES(12783,'methods12a1-spe-38',NULL,1,'27 + 18 − 45 = 0, so x = 3 is a solution [1].',1,1);
INSERT INTO rubric_criterion VALUES(12784,'methods12a1-spe-38',NULL,2,'x³ + 2x² − 45 = (x − 3)(x² + 5x + 15) and the discriminant 25 − 60 < 0, so no other real solutions [1].',1,1);
INSERT INTO rubric_criterion VALUES(12785,'methods12a1-spe-38',NULL,3,'The base has side 3 cm [1].',1,1);
INSERT INTO rubric_criterion VALUES(12786,'vce-methods12-sp-c1',NULL,0,'x = −2, 1, 3',2,1);
INSERT INTO rubric_criterion VALUES(12792,'methods12a1-pwr-6',NULL,0,'Asymptotes: x = 1 and y = 2 [1].',1,1);
