INSERT INTO rubric_criterion VALUES(13747,'methods12a3-rc-25',NULL,0,'f(5) = 25 + 15 = 40 and f(1) = 1 + 3 = 4 [1];',1,1);
INSERT INTO rubric_criterion VALUES(13748,'methods12a3-rc-25',NULL,1,'average rate = (40 − 4)/(5 − 1) = 36/4 = 9 [1].',1,1);
INSERT INTO rubric_criterion VALUES(13749,'methods12a3-rc-26',NULL,0,'(a) s(2 + h) − s(2) = (4 + 4h + h²) − 4 = 4h + h² [1];',1,1);
