INSERT INTO rubric_criterion VALUES(13751,'methods12a3-rc-26',NULL,2,'(b) as h → 0, 4 + h → 4, so the instantaneous velocity is 4 m s⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(13752,'methods12a3-rc-27',NULL,0,'(a) 50/2 = 25 km h⁻¹ and (b) (140 − 50)/3 = 30 km h⁻¹ [1];',1,1);
