INSERT INTO rubric_criterion VALUES(13754,'methods12a3-rc-27',NULL,2,'the mean of 25 and 30 is 27.5, which differs because the two intervals have different lengths (2 h and 3 h), so the average must be weighted by time [1].',1,1);
INSERT INTO rubric_criterion VALUES(13755,'methods12a3-rc-28',NULL,0,'(a) f(3) = −3 and f(1) = −3, so the average rate is 0/2 = 0 [1];',1,1);
