INSERT INTO rubric_criterion VALUES(13758,'methods12a3-rc-28',NULL,3,'(c) f′(x) = 2x − 4 = 0 gives x = 2 [1].',1,1);
INSERT INTO rubric_criterion VALUES(13759,'methods12a3-rc-29',NULL,0,'Change in population = 15 600 − 12 000 = 3600 over 10 years [1];',1,1);
INSERT INTO rubric_criterion VALUES(13760,'methods12a3-rc-29',NULL,1,'average rate = 3600/10 = 360 people per year [1].',1,1);
INSERT INTO rubric_criterion VALUES(13761,'methods12a3-rc-30',NULL,0,'(a) s(3) = 51 and s(1) = 1 [1];',1,1);
