INSERT INTO rubric_criterion VALUES(13765,'methods12a3-rc-31',NULL,0,'The average rate is the change in position divided by the change in time over an interval, shown as the gradient of a secant (chord) [1];',1,1);
INSERT INTO rubric_criterion VALUES(13766,'methods12a3-rc-31',NULL,1,'the instantaneous rate is the rate at a single moment, like a speedometer reading, found as the limit as the interval shrinks to zero and shown as the gradient of the tangent [1].',1,1);
INSERT INTO rubric_criterion VALUES(13767,'methods12a3-rc-32',NULL,0,'(a) C(20) = 2100 and C(10) = 900 [1];',1,1);
