INSERT INTO rubric_criterion VALUES(13776,'methods12a3-rc-36',NULL,0,'f(1) = 1 and f(1 + h) = 3(1 + h)² − 2(1 + h) = 1 + 4h + 3h². [1] Secant gradient = (4h + 3h²)/h = 4 + 3h.',1,1);
