INSERT INTO rubric_criterion VALUES(13779,'methods12a3-rc-37',NULL,0,'(a) h(0) = 0 and h(2) = 60, so the average velocity is 60/2 = 30 m/s. [1]',1,1);
INSERT INTO rubric_criterion VALUES(13780,'methods12a3-rc-37',NULL,1,'(b) h(4) = 80, so the average velocity is (80 − 60)/2 = 10 m/s. [1]',1,1);
INSERT INTO rubric_criterion VALUES(13781,'methods12a3-rc-37',NULL,2,'(c) The average velocity is smaller later, so the rocket is slowing down. [1]',1,1);
INSERT INTO rubric_criterion VALUES(13788,'methods12a3-fp-6',NULL,0,'[f(x + h) − f(x)]/h = [(x + h)² + 3(x + h) − x² − 3x]/h (1 mark) = (2xh + h² + 3h)/h = 2x + 3 + h (1 mark);',1,1);
INSERT INTO rubric_criterion VALUES(13789,'methods12a3-fp-6',NULL,1,'as h → 0, f′(x) = 2x + 3 (1 mark).',2,1);
INSERT INTO rubric_criterion VALUES(13790,'methods12a3-fp-7',NULL,0,'f(3) = 18 − 3 = 15 (1 mark); f(3 + h) = 2(9 + 6h + h²) − 3 − h = 15 + 11h + 2h² (1 mark);',1,1);
INSERT INTO rubric_criterion VALUES(13791,'methods12a3-fp-7',NULL,1,'[f(3 + h) − f(3)]/h = 11 + 2h → 11 as h → 0, so f′(3) = 11 (1 mark).',1,1);
INSERT INTO rubric_criterion VALUES(13792,'methods12a3-fp-7',NULL,2,'Check: f′(x) = 4x − 1 gives 11.',1,1);
INSERT INTO rubric_criterion VALUES(13793,'methods12a3-fp-8',NULL,0,'f(x + h) − f(x) = (x + h)³ − (x + h) − x³ + x = 3x²h + 3xh² + h³ − h (1 mark);',1,1);
INSERT INTO rubric_criterion VALUES(13794,'methods12a3-fp-8',NULL,1,'dividing by h: 3x² + 3xh + h² − 1 (1 mark);',1,1);
INSERT INTO rubric_criterion VALUES(13795,'methods12a3-fp-8',NULL,2,'as h → 0 this tends to 3x² − 1 (1 mark).',1,1);
INSERT INTO rubric_criterion VALUES(13810,'methods12a3-fp-23',NULL,0,'[f(x + h) − f(x)]/h = [4(x + h)² + 5 − 4x² − 5]/h [1] = (8xh + 4h²)/h = 8x + 4h [1];',1,1);
