INSERT INTO rubric_criterion VALUES(13812,'methods12a3-fp-24',NULL,0,'[f(x + h) − f(x)]/h = [1/(x + h) − 1/x]/h [1];',1,1);
INSERT INTO rubric_criterion VALUES(13813,'methods12a3-fp-24',NULL,1,'combine over a common denominator: [x − (x + h)]/[x(x + h)] = −h/[x(x + h)] [1];',1,1);
