INSERT INTO rubric_criterion VALUES(13815,'methods12a3-fp-24',NULL,3,'as h → 0, f′(x) = −1/x² [1].',1,1);
INSERT INTO rubric_criterion VALUES(13816,'methods12a3-fp-25',NULL,0,'f(−2) = 4 + 10 = 14 and f(−2 + h) = 4 − 4h + h² + 10 − 5h = 14 − 9h + h² [1];',1,1);
INSERT INTO rubric_criterion VALUES(13817,'methods12a3-fp-25',NULL,1,'[f(−2 + h) − f(−2)]/h = (−9h + h²)/h = −9 + h [1];',1,1);
INSERT INTO rubric_criterion VALUES(13818,'methods12a3-fp-25',NULL,2,'as h → 0, f′(−2) = −9 [1].',1,1);
INSERT INTO rubric_criterion VALUES(13819,'methods12a3-fp-26',NULL,0,'[2(x + h)³ − 2x³]/h = 2(3x²h + 3xh² + h³)/h [1] = 6x² + 6xh + 2h² [1];',1,1);
INSERT INTO rubric_criterion VALUES(13820,'methods12a3-fp-26',NULL,1,'as h → 0, f′(x) = 6x² [1].',2,1);
INSERT INTO rubric_criterion VALUES(13821,'methods12a3-fp-27',NULL,0,'The quotient at x = 0 is [f(h) − f(0)]/h = |h|/h [1]; for h > 0 this equals 1, so the limit from the right is 1 [1];',1,1);
INSERT INTO rubric_criterion VALUES(13822,'methods12a3-fp-27',NULL,1,'for h < 0 it equals −1, so the limit from the left is −1;',1,1);
INSERT INTO rubric_criterion VALUES(13823,'methods12a3-fp-27',NULL,2,'the two limits differ, so f′(0) does not exist [1].',1,1);
INSERT INTO rubric_criterion VALUES(13824,'methods12a3-fp-28',NULL,0,'f(2) = 2 and f(2 + h) = 4 + 4h + h² − 2 − h = 2 + 3h + h² [1];',1,1);
