INSERT INTO rubric_criterion VALUES(14135,'vce-methods12-an-c1',NULL,0,'f(x) = x³ − 2x² + x + 5',2,1);
INSERT INTO rubric_criterion VALUES(14141,'physics12a1-tkp-6',NULL,0,'(a) 77 − 273 = −196 °C;',1,1);
INSERT INTO rubric_criterion VALUES(14142,'physics12a1-tkp-6',NULL,1,'(b) 20 + 273 = 293 K;',1,1);
INSERT INTO rubric_criterion VALUES(14143,'physics12a1-tkp-6',NULL,2,'(c) 293 − 77 = 216 K (a difference of 216 K is the same as 216 °C).',1,1);
INSERT INTO rubric_criterion VALUES(14144,'physics12a1-tkp-7',NULL,0,'Temperature is a measure of the average random kinetic energy of the particles;',1,1);
INSERT INTO rubric_criterion VALUES(14145,'physics12a1-tkp-7',NULL,1,'internal energy is the total of the kinetic and potential energies of all the particles;',1,1);
INSERT INTO rubric_criterion VALUES(14146,'physics12a1-tkp-7',NULL,2,'example: a bathtub of water and a cup of water at the same temperature have the same average particle KE but the bathtub has far greater internal energy because it has many more particles.',1,1);
INSERT INTO rubric_criterion VALUES(14147,'physics12a1-tkp-8',NULL,0,'Heating increases the average kinetic energy (and speed) of the air particles; particles collide with the can walls more frequently;',1,1);
INSERT INTO rubric_criterion VALUES(14148,'physics12a1-tkp-8',NULL,1,'each collision exerts a greater force (greater change in momentum);',1,1);
INSERT INTO rubric_criterion VALUES(14149,'physics12a1-tkp-8',NULL,2,'the volume and number of particles are constant so the pressure increases.',1,1);
INSERT INTO rubric_criterion VALUES(14167,'physics12a1-tkp-26',NULL,0,'(a) 25 + 273 = 298 K [1];',1,1);
INSERT INTO rubric_criterion VALUES(14168,'physics12a1-tkp-26',NULL,1,'(b) 350 − 273 = 77 °C [1].',1,1);
INSERT INTO rubric_criterion VALUES(14169,'physics12a1-tkp-27',NULL,0,'Air molecules are in constant random motion [1];',1,1);
INSERT INTO rubric_criterion VALUES(14170,'physics12a1-tkp-27',NULL,1,'they collide with the smoke particles from all directions [1];',1,1);
INSERT INTO rubric_criterion VALUES(14171,'physics12a1-tkp-27',NULL,2,'at any instant the collisions on different sides do not balance, so there is a net force and the smoke particle moves in a random, jerky way [1].',1,1);
INSERT INTO rubric_criterion VALUES(14172,'physics12a1-tkp-28',NULL,0,'At the same temperature the average translational kinetic energies are equal [1];',1,1);
INSERT INTO rubric_criterion VALUES(14173,'physics12a1-tkp-28',NULL,1,'since ½mv² is equal, v is proportional to 1/√m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14174,'physics12a1-tkp-28',NULL,2,'ratio of speeds = √(16/4) = 2, so helium particles are on average twice as fast [1].',1,1);
INSERT INTO rubric_criterion VALUES(14175,'physics12a1-tkp-29',NULL,0,'When the objects are in contact, particles at the interface collide and transfer kinetic energy from the particles with greater average kinetic energy to those with less [1];',1,1);
INSERT INTO rubric_criterion VALUES(14176,'physics12a1-tkp-29',NULL,1,'there is a net transfer from the hotter to the colder object until the average random kinetic energy per particle is the same in both [1];',1,1);
INSERT INTO rubric_criterion VALUES(14177,'physics12a1-tkp-29',NULL,2,'at this point the temperatures are equal and there is no net energy transfer [1].',1,1);
INSERT INTO rubric_criterion VALUES(14178,'physics12a1-tkp-30',NULL,0,'Solid: particles are closely packed in fixed positions and vibrate about them [1];',1,1);
INSERT INTO rubric_criterion VALUES(14179,'physics12a1-tkp-30',NULL,1,'liquid: particles are close together but not in fixed positions, and they move past one another [1];',1,1);
INSERT INTO rubric_criterion VALUES(14180,'physics12a1-tkp-30',NULL,2,'gas: particles are far apart and move rapidly and randomly, with negligible forces between them except in collisions [1].',1,1);
INSERT INTO rubric_criterion VALUES(14181,'physics12a1-tkp-31',NULL,0,'(a) 120 + 273 = 393 K [1];',1,1);
INSERT INTO rubric_criterion VALUES(14182,'physics12a1-tkp-31',NULL,1,'−153 + 273 = 120 K [1];',1,1);
INSERT INTO rubric_criterion VALUES(14183,'physics12a1-tkp-31',NULL,2,'(b) change = 393 − 120 = 273 K (a decrease of 273 K) [1].',1,1);
INSERT INTO rubric_criterion VALUES(14184,'physics12a1-tkp-32',NULL,0,'The particles in the liquid have a range of kinetic energies, and the fastest, most energetic particles near the surface escape as vapour [1];',1,1);
INSERT INTO rubric_criterion VALUES(14185,'physics12a1-tkp-32',NULL,1,'the particles that escape take away more than the average kinetic energy [1];',1,1);
INSERT INTO rubric_criterion VALUES(14186,'physics12a1-tkp-32',NULL,2,'the average kinetic energy of the remaining particles therefore falls, so the temperature decreases [1].',1,1);
INSERT INTO rubric_criterion VALUES(14187,'physics12a1-tkp-33',NULL,0,'Average kinetic energy is proportional to the temperature in kelvin, not degrees Celsius [1];',1,1);
INSERT INTO rubric_criterion VALUES(14188,'physics12a1-tkp-33',NULL,1,'10 °C = 283 K and 20 °C = 293 K [1];',1,1);
INSERT INTO rubric_criterion VALUES(14189,'physics12a1-tkp-33',NULL,2,'the ratio is 293/283 ≈ 1.04, so the kinetic energy increases by only about 4% and the claim is incorrect [1].',1,1);
INSERT INTO rubric_criterion VALUES(14196,'physics12a1-shc-6',NULL,0,'Energy lost by Al = energy gained by water; 0.250 × 900 × (100.0 − T) = 0.400 × 4180 × (T − 20.0);',1,1);
INSERT INTO rubric_criterion VALUES(14197,'physics12a1-shc-6',NULL,1,'225(100 − T) = 1672(T − 20);',1,1);
INSERT INTO rubric_criterion VALUES(14198,'physics12a1-shc-6',NULL,2,'22 500 + 33 440 = 1897T so 55 940 = 1897T;',1,1);
INSERT INTO rubric_criterion VALUES(14199,'physics12a1-shc-6',NULL,3,'T = 29.5 °C.',1,1);
INSERT INTO rubric_criterion VALUES(14200,'physics12a1-shc-7',NULL,0,'(a) Q = mcΔT = 1.50 × 4180 × 82.0 = 5.14 × 10⁵ J;',1,1);
INSERT INTO rubric_criterion VALUES(14201,'physics12a1-shc-7',NULL,1,'(b) t = Q/P = 514 140/2000 = 257 s;',1,1);
INSERT INTO rubric_criterion VALUES(14202,'physics12a1-shc-7',NULL,2,'(c) energy input = 514 140/0.85 = 6.05 × 10⁵ J;',1,1);
INSERT INTO rubric_criterion VALUES(14203,'physics12a1-shc-7',NULL,3,'t = 604 871/2000 = 302 s.',1,1);
INSERT INTO rubric_criterion VALUES(14204,'physics12a1-shc-8',NULL,0,'(a) Q = Pt = 50 × 300 = 15 000 J; c = Q/(mΔT) = 15 000/(1.0 × 17) = 882 J kg⁻¹ K⁻¹ (≈ 880);',1,1);
INSERT INTO rubric_criterion VALUES(14205,'physics12a1-shc-8',NULL,1,'(b) some energy is lost to the surroundings so the block gains less energy than Pt, yet the student used the full Pt, giving too large a value; improvement: insulate the block (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(14206,'physics12a1-shc-8',NULL,2,'lag it with foam).',1,1);
INSERT INTO rubric_criterion VALUES(14224,'physics12a1-shc-26',NULL,0,'Specific heat capacity is the energy required to raise the temperature of 1 kg of a substance by 1 K [1];',1,1);
INSERT INTO rubric_criterion VALUES(14225,'physics12a1-shc-26',NULL,1,'its SI unit is J kg⁻¹ K⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(14226,'physics12a1-shc-27',NULL,0,'Q = Pt = 2400 × 240 = 5.76 × 10⁵ J [1];',1,1);
INSERT INTO rubric_criterion VALUES(14227,'physics12a1-shc-27',NULL,1,'ΔT = Q/(mc) = 576 000/(5.0 × 4180) = 27.6 K [1];',1,1);
INSERT INTO rubric_criterion VALUES(14228,'physics12a1-shc-27',NULL,2,'final temperature = 15 + 27.6 = 42.6 °C [1].',1,1);
INSERT INTO rubric_criterion VALUES(14229,'physics12a1-shc-28',NULL,0,'Measure the mass of the block with a balance [1];',1,1);
INSERT INTO rubric_criterion VALUES(14230,'physics12a1-shc-28',NULL,1,'heat it with an electric heater of known power (or measured voltage and current) for a measured time, recording the initial and final temperatures with a thermometer, with the block insulated to reduce losses [1];',1,1);
INSERT INTO rubric_criterion VALUES(14231,'physics12a1-shc-28',NULL,2,'calculate the energy supplied using Q = Pt (or VIt) and the temperature rise ΔT [1];',1,1);
INSERT INTO rubric_criterion VALUES(14232,'physics12a1-shc-28',NULL,3,'calculate c = Q/(mΔT) [1].',1,1);
INSERT INTO rubric_criterion VALUES(14233,'physics12a1-shc-29',NULL,0,'Energy gained by water = 0.200 × 4180 × 6.0 = 5016 J [1];',1,1);
INSERT INTO rubric_criterion VALUES(14234,'physics12a1-shc-29',NULL,1,'energy lost by metal = 0.300 × c × 74.0 [1];',1,1);
INSERT INTO rubric_criterion VALUES(14235,'physics12a1-shc-29',NULL,2,'equate: 0.300 × c × 74.0 = 5016 [1];',1,1);
INSERT INTO rubric_criterion VALUES(14236,'physics12a1-shc-29',NULL,3,'c = 5016/22.2 = 226 J kg⁻¹ K⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(14237,'physics12a1-shc-30',NULL,0,'Q = mcΔT = 0.80 × 900 × 45 = 3.24 × 10⁴ J [1];',1,1);
INSERT INTO rubric_criterion VALUES(14238,'physics12a1-shc-30',NULL,1,'t = Q/P [1] = 32 400/500 = 64.8 s ≈ 65 s [1].',2,1);
INSERT INTO rubric_criterion VALUES(14245,'physics12a1-lat-6',NULL,0,'Warm ice: 0.300 × 2100 × 10.0 = 6300 J; melt: 0.300 × 3.34 × 10⁵ = 100 200 J;',1,1);
INSERT INTO rubric_criterion VALUES(14246,'physics12a1-lat-6',NULL,1,'warm water: 0.300 × 4180 × 100 = 125 400 J;',1,1);
INSERT INTO rubric_criterion VALUES(14247,'physics12a1-lat-6',NULL,2,'vaporise: 0.300 × 2.26 × 10⁶ = 678 000 J;',1,1);
INSERT INTO rubric_criterion VALUES(14248,'physics12a1-lat-6',NULL,3,'total = 909 900 J ≈ 9.10 × 10⁵ J.',1,1);
INSERT INTO rubric_criterion VALUES(14249,'physics12a1-lat-7',NULL,0,'Energy to melt ice = 0.0500 × 3.34 × 10⁵ = 16 700 J; melted ice then warms: 0.0500 × 4180 × T = 209T;',1,1);
INSERT INTO rubric_criterion VALUES(14250,'physics12a1-lat-7',NULL,1,'warm water cools: 0.300 × 4180 × (25.0 − T) = 1254(25.0 − T); 16 700 + 209T = 31 350 − 1254T;',1,1);
INSERT INTO rubric_criterion VALUES(14251,'physics12a1-lat-7',NULL,2,'1463T = 14 650;',1,1);
INSERT INTO rubric_criterion VALUES(14252,'physics12a1-lat-7',NULL,3,'T = 10.0 °C.',1,1);
INSERT INTO rubric_criterion VALUES(14253,'physics12a1-lat-8',NULL,0,'Temperature depends on average kinetic energy of the particles;',1,1);
INSERT INTO rubric_criterion VALUES(14254,'physics12a1-lat-8',NULL,1,'during melting the supplied energy is used to break the bonds holding particles in a fixed lattice, increasing their potential energy;',1,1);
INSERT INTO rubric_criterion VALUES(14255,'physics12a1-lat-8',NULL,2,'the kinetic energy (and so temperature) does not change until all the ice has melted.',1,1);
INSERT INTO rubric_criterion VALUES(14272,'physics12a1-lat-25',NULL,0,'Specific latent heat of vaporisation is the energy required to change 1 kg of a liquid to a gas at its boiling point without a change in temperature [1];',1,1);
INSERT INTO rubric_criterion VALUES(14273,'physics12a1-lat-25',NULL,1,'unit J kg⁻¹ [1].',1,1);
INSERT INTO rubric_criterion VALUES(14274,'physics12a1-lat-26',NULL,0,'Energy released by condensing = 0.0400 × 2.26 × 10⁶ = 90 400 J [1];',1,1);
INSERT INTO rubric_criterion VALUES(14275,'physics12a1-lat-26',NULL,1,'energy released by condensed water cooling = 0.0400 × 4180 × (100 − T) [1];',1,1);
INSERT INTO rubric_criterion VALUES(14276,'physics12a1-lat-26',NULL,2,'energy gained by cool water = 0.500 × 4180 × (T − 20.0) [1];',1,1);
INSERT INTO rubric_criterion VALUES(14277,'physics12a1-lat-26',NULL,3,'equate: 90 400 + 167.2(100 − T) = 2090(T − 20.0), giving T = 66.0 °C [1].',1,1);
INSERT INTO rubric_criterion VALUES(14278,'physics12a1-lat-27',NULL,0,'Temperature rises steadily as ice warms to 0 °C [1];',1,1);
INSERT INTO rubric_criterion VALUES(14279,'physics12a1-lat-27',NULL,1,'a horizontal section at 0 °C while the ice melts [1];',1,1);
INSERT INTO rubric_criterion VALUES(14280,'physics12a1-lat-27',NULL,2,'a rise to 100 °C that is less steep than the ice section, as water has a higher specific heat capacity [1];',1,1);
INSERT INTO rubric_criterion VALUES(14281,'physics12a1-lat-27',NULL,3,'a longer horizontal section at 100 °C during boiling because L vaporisation is much greater than L fusion, then a steady rise as steam is heated [1].',1,1);
INSERT INTO rubric_criterion VALUES(14282,'physics12a1-lat-28',NULL,0,'Energy released by water cooling = 0.250 × 4180 × 30.0 = 31 350 J [1];',1,1);
INSERT INTO rubric_criterion VALUES(14283,'physics12a1-lat-28',NULL,1,'energy absorbed by melting ice = mL, so 31 350 = m × 3.34 × 10⁵ [1];',1,1);
INSERT INTO rubric_criterion VALUES(14284,'physics12a1-lat-28',NULL,2,'m = 0.0939 kg [1].',1,1);
INSERT INTO rubric_criterion VALUES(14285,'physics12a1-lat-29',NULL,0,'Energy to cool water = 0.400 × 4180 × 20.0 = 33 440 J; energy to freeze = 0.400 × 3.34 × 10⁵ = 133 600 J;',1,1);
INSERT INTO rubric_criterion VALUES(14286,'physics12a1-lat-29',NULL,1,'total = 167 040 J [1]; t = E/P [1];',1,1);
INSERT INTO rubric_criterion VALUES(14287,'physics12a1-lat-29',NULL,2,'t = 167 040 ÷ 150 = 1.11 × 10³ s (about 18.6 minutes) [1].',1,1);
INSERT INTO rubric_criterion VALUES(14288,'physics12a1-lat-30',NULL,0,'Energy to warm ice to 0 °C = 0.100 × 2100 × 20.0 = 4200 J; energy to melt = 0.100 × 3.34 × 10⁵ = 33 400 J;',1,1);
INSERT INTO rubric_criterion VALUES(14289,'physics12a1-lat-30',NULL,1,'total 37 600 J, less than the 66 880 J available from cooling the water to 0 °C so all the ice melts [1]; energy to warm melted ice: 0.100 × 4180 × T = 418T [1];',1,1);
INSERT INTO rubric_criterion VALUES(14290,'physics12a1-lat-30',NULL,2,'energy released by warm water: 0.400 × 4180 × (40.0 − T) = 1672(40.0 − T) [1];',1,1);
INSERT INTO rubric_criterion VALUES(14291,'physics12a1-lat-30',NULL,3,'37 600 + 418T = 66 880 − 1672T, giving T = 14.0 °C [1].',1,1);
INSERT INTO rubric_criterion VALUES(14292,'vce-physics12-lh-c1',NULL,0,'About 2.2 × 10⁵ J',3,1);
INSERT INTO rubric_criterion VALUES(14298,'physics12a1-ccr-6',NULL,0,'The tile is a better thermal conductor than the carpet;',1,1);
INSERT INTO rubric_criterion VALUES(14299,'physics12a1-ccr-6',NULL,1,'energy is conducted from the warmer foot to the tile at a faster rate;',1,1);
INSERT INTO rubric_criterion VALUES(14300,'physics12a1-ccr-6',NULL,2,'skin temperature drops more quickly (and the carpet, a poor conductor, stays warm at the surface), so the tile feels colder even though both are at the same temperature.',1,1);
INSERT INTO rubric_criterion VALUES(14301,'physics12a1-ccr-7',NULL,0,'Energy is conducted from the element through the base of the pot to the water at the bottom;',1,1);
INSERT INTO rubric_criterion VALUES(14302,'physics12a1-ccr-7',NULL,1,'the heated water expands, becomes less dense and rises while cooler, denser water sinks, forming convection currents;',1,1);
INSERT INTO rubric_criterion VALUES(14303,'physics12a1-ccr-7',NULL,2,'this circulation transports energy throughout the water to the top.',1,1);
INSERT INTO rubric_criterion VALUES(14304,'physics12a1-ccr-8',NULL,0,'Evacuated space between the walls reduces conduction and convection (no particles to transfer energy);',1,1);
INSERT INTO rubric_criterion VALUES(14305,'physics12a1-ccr-8',NULL,1,'silvered surfaces reduce radiation (low emissivity, reflecting infrared);',1,1);
INSERT INTO rubric_criterion VALUES(14306,'physics12a1-ccr-8',NULL,2,'insulating stopper reduces conduction and convection at the opening (poor conductor and traps air).',1,1);
INSERT INTO rubric_criterion VALUES(14326,'physics12a1-ccr-28',NULL,0,'Air next to the radiator is heated, expands and becomes less dense, so it rises [1];',1,1);
INSERT INTO rubric_criterion VALUES(14327,'physics12a1-ccr-28',NULL,1,'cooler, denser air moves in to replace it, producing a convection current that circulates warm air around the room [1].',1,1);
INSERT INTO rubric_criterion VALUES(14328,'physics12a1-ccr-29',NULL,0,'Substitute into P = kAΔT/L [1];',1,1);
INSERT INTO rubric_criterion VALUES(14329,'physics12a1-ccr-29',NULL,1,'P = 0.040 × 12 × 15 ÷ 0.10 [1];',1,1);
INSERT INTO rubric_criterion VALUES(14330,'physics12a1-ccr-29',NULL,2,'P = 72 W [1].',1,1);
INSERT INTO rubric_criterion VALUES(14331,'physics12a1-ccr-30',NULL,0,'The matt black surface is a good absorber of radiation, so it absorbs most of the radiation from the Sun [1];',1,1);
INSERT INTO rubric_criterion VALUES(14332,'physics12a1-ccr-30',NULL,1,'the white surface reflects much of the incident radiation, so less energy is absorbed and the white car warms less [1].',1,1);
INSERT INTO rubric_criterion VALUES(14333,'physics12a1-ccr-31',NULL,0,'The feathers trap many small pockets of air [1];',1,1);
INSERT INTO rubric_criterion VALUES(14334,'physics12a1-ccr-31',NULL,1,'air is a poor conductor, so conduction of energy away from the body is reduced [1];',1,1);
INSERT INTO rubric_criterion VALUES(14335,'physics12a1-ccr-31',NULL,2,'the pockets are too small for convection currents to form, so the trapped air stays still and convection loss is also reduced [1].',1,1);
INSERT INTO rubric_criterion VALUES(14336,'physics12a1-ccr-32',NULL,0,'Conduction transfers energy through a material by collisions or vibrations between neighbouring particles, with no overall movement of the material [1];',1,1);
INSERT INTO rubric_criterion VALUES(14337,'physics12a1-ccr-32',NULL,1,'convection transfers energy by the bulk movement of a fluid, with heated, less dense fluid rising and cooler fluid sinking [1].',1,1);
INSERT INTO rubric_criterion VALUES(14338,'physics12a1-ccr-33',NULL,0,'Convert thickness to metres: L = 4.0 × 10⁻³ m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14339,'physics12a1-ccr-33',NULL,1,'P = 0.84 × 1.5 × 6.0 ÷ (4.0 × 10⁻³) [1];',1,1);
INSERT INTO rubric_criterion VALUES(14340,'physics12a1-ccr-33',NULL,2,'P = 1.9 × 10³ W (1890 W) [1].',1,1);
INSERT INTO rubric_criterion VALUES(14341,'physics12a1-ccr-34',NULL,0,'Convection currents carry heated air upwards, away from a person standing to the side, and air is a poor conductor [1];',1,1);
INSERT INTO rubric_criterion VALUES(14342,'physics12a1-ccr-34',NULL,1,'the fire emits infrared radiation in all directions, which travels through the air and is absorbed by the person''s skin [1].',1,1);
INSERT INTO rubric_criterion VALUES(14343,'physics12a1-ccr-35',NULL,0,'A large surface area increases the area in contact with the air, so more energy is transferred by conduction to the air and convection [1];',1,1);
INSERT INTO rubric_criterion VALUES(14344,'physics12a1-ccr-35',NULL,1,'matt black surfaces are good emitters of radiation, so more energy is radiated away [1];',1,1);
INSERT INTO rubric_criterion VALUES(14345,'physics12a1-ccr-35',NULL,2,'warmed air near the fins rises and is replaced by cooler air, which maintains a convection current [1].',1,1);
INSERT INTO rubric_criterion VALUES(14346,'physics12a1-ccr-36',NULL,0,'Metal is a good thermal conductor, so energy is rapidly conducted along the spoon (by free electrons and vibrations) to the handle [1];',1,1);
INSERT INTO rubric_criterion VALUES(14347,'physics12a1-ccr-36',NULL,1,'wood is a poor conductor, so energy travels along it very slowly and the handle stays cool [1].',1,1);
INSERT INTO rubric_criterion VALUES(14354,'physics12a1-wien-6',NULL,0,'(a) T = 2.898 × 10⁻³ / 1.45 × 10⁻⁶ = 2.00 × 10³ K;',1,1);
INSERT INTO rubric_criterion VALUES(14355,'physics12a1-wien-6',NULL,1,'(b) peak lies in the infrared;',1,1);
INSERT INTO rubric_criterion VALUES(14356,'physics12a1-wien-6',NULL,2,'most energy emitted is infrared, not visible, so the lamp is inefficient as a light source.',1,1);
INSERT INTO rubric_criterion VALUES(14357,'physics12a1-wien-7',NULL,0,'λmax = 2.898 × 10⁻³ / 288 (1);',1,1);
INSERT INTO rubric_criterion VALUES(14358,'physics12a1-wien-7',NULL,1,'= 1.01 × 10⁻⁵ m, or about 10 µm (1);',1,1);
INSERT INTO rubric_criterion VALUES(14359,'physics12a1-wien-7',NULL,2,'this is in the infrared region (1).',1,1);
INSERT INTO rubric_criterion VALUES(14360,'physics12a1-wien-8',NULL,0,'The graph is a continuous curve with a single peak;',1,1);
INSERT INTO rubric_criterion VALUES(14361,'physics12a1-wien-8',NULL,1,'as temperature increases the peak moves to a shorter wavelength;',1,1);
INSERT INTO rubric_criterion VALUES(14362,'physics12a1-wien-8',NULL,2,'the intensity is greater at all wavelengths so the area under the curve (total power emitted) increases.',1,1);
INSERT INTO rubric_criterion VALUES(14381,'physics12a1-wien-27',NULL,0,'T = 2.898 × 10⁻³ / 4.50 × 10⁻⁷ [1];',1,1);
INSERT INTO rubric_criterion VALUES(14382,'physics12a1-wien-27',NULL,1,'T = 6.44 × 10³ K [1].',1,1);
INSERT INTO rubric_criterion VALUES(14383,'physics12a1-wien-28',NULL,0,'The peak wavelength halves because it is inversely proportional to the absolute temperature [1];',1,1);
INSERT INTO rubric_criterion VALUES(14384,'physics12a1-wien-28',NULL,1,'the peak moves towards the visible region so a greater proportion of the emitted radiation is visible and the sphere glows brighter [1].',1,1);
INSERT INTO rubric_criterion VALUES(14385,'physics12a1-wien-29',NULL,0,'Furnace: λmax = 2.898 × 10⁻³ / 1500 = 1.93 × 10⁻⁶ m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14386,'physics12a1-wien-29',NULL,1,'bench: λmax = 2.898 × 10⁻³ / 300 = 9.66 × 10⁻⁶ m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14387,'physics12a1-wien-29',NULL,2,'the hotter furnace has a peak wavelength five times shorter than the bench [1].',1,1);
INSERT INTO rubric_criterion VALUES(14388,'physics12a1-wien-30',NULL,0,'Conduction and convection require a medium (particles) to carry the energy, and space between the Sun and Earth is almost a vacuum [1];',1,1);
INSERT INTO rubric_criterion VALUES(14389,'physics12a1-wien-30',NULL,1,'radiation is electromagnetic waves, which can travel through a vacuum without a medium [1].',1,1);
INSERT INTO rubric_criterion VALUES(14390,'physics12a1-wien-31',NULL,0,'A dark surface is a good absorber so it absorbs more of the Sun''s incident radiation than the white surface [1];',1,1);
INSERT INTO rubric_criterion VALUES(14391,'physics12a1-wien-31',NULL,1,'good absorbers are also good emitters, so the dark surface has a higher emissivity [1];',1,1);
INSERT INTO rubric_criterion VALUES(14392,'physics12a1-wien-31',NULL,2,'therefore at night the dark car radiates more energy per second and cools faster [1].',1,1);
INSERT INTO rubric_criterion VALUES(14393,'physics12a1-wien-32',NULL,0,'The vacuum between the walls prevents conduction and convection across the gap [1];',1,1);
INSERT INTO rubric_criterion VALUES(14394,'physics12a1-wien-32',NULL,1,'the silvered surfaces are poor emitters of thermal radiation [1];',1,1);
INSERT INTO rubric_criterion VALUES(14395,'physics12a1-wien-32',NULL,2,'they also reflect radiation back towards the hot contents, so little energy is lost by radiation [1].',1,1);
INSERT INTO rubric_criterion VALUES(14396,'physics12a1-wien-33',NULL,0,'Betelgeuse: λmax = 2.898 × 10⁻³ / 3500 = 8.28 × 10⁻⁷ m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14397,'physics12a1-wien-33',NULL,1,'Rigel: λmax = 2.898 × 10⁻³ / 12 000 = 2.42 × 10⁻⁷ m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14398,'physics12a1-wien-33',NULL,2,'Betelgeuse''s peak is in the infrared with its visible output strongest at the red end, so it appears red [1];',1,1);
INSERT INTO rubric_criterion VALUES(14399,'physics12a1-wien-33',NULL,3,'Rigel''s peak is in the ultraviolet with strong output at the blue end of the visible, so it appears blue-white [1].',1,1);
INSERT INTO rubric_criterion VALUES(14400,'physics12a1-wien-34',NULL,0,'(a) T = 2.898 × 10⁻³ / 1.2 × 10⁻⁶ = 2.42 × 10³ K [1];',1,1);
INSERT INTO rubric_criterion VALUES(14401,'physics12a1-wien-34',NULL,1,'(b) new temperature = 3.42 × 10³ K [1];',1,1);
INSERT INTO rubric_criterion VALUES(14402,'physics12a1-wien-34',NULL,2,'λmax = 2.898 × 10⁻³ / 3415 = 8.5 × 10⁻⁷ m [1].',1,1);
INSERT INTO rubric_criterion VALUES(14403,'physics12a1-wien-35',NULL,0,'T = 100 + 273 = 373 K [1];',1,1);
INSERT INTO rubric_criterion VALUES(14404,'physics12a1-wien-35',NULL,1,'λmax = 2.898 × 10⁻³ / 373 = 7.77 × 10⁻⁶ m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14405,'physics12a1-wien-35',NULL,2,'this is in the infrared region [1].',1,1);
INSERT INTO rubric_criterion VALUES(14406,'physics12a1-wien-36',NULL,0,'A blackbody is an ideal object that absorbs all radiation incident on it and emits the maximum possible thermal radiation at its temperature [1];',1,1);
INSERT INTO rubric_criterion VALUES(14407,'physics12a1-wien-36',NULL,1,'radiation entering the small hole is reflected many times inside the cavity and is almost completely absorbed, so almost none escapes [1];',1,1);
INSERT INTO rubric_criterion VALUES(14408,'physics12a1-wien-36',NULL,2,'the radiation leaving the hole has a spectrum that depends only on the cavity temperature [1].',1,1);
INSERT INTO rubric_criterion VALUES(14409,'physics12a1-wien-37',NULL,0,'T = 80 + 273 = 353 K [1];',1,1);
INSERT INTO rubric_criterion VALUES(14410,'physics12a1-wien-37',NULL,1,'λmax = 2.898 × 10⁻³ / 353 = 8.21 × 10⁻⁶ m, in the infrared [1];',1,1);
INSERT INTO rubric_criterion VALUES(14411,'physics12a1-wien-37',NULL,2,'the hotter tea emits more infrared radiation per second than its surroundings [1];',1,1);
INSERT INTO rubric_criterion VALUES(14412,'physics12a1-wien-37',NULL,3,'the camera detects this greater intensity so the cup appears brighter [1].',1,1);
INSERT INTO rubric_criterion VALUES(14419,'physics12a1-gh-6',NULL,0,'Natural greenhouse effect: warming from greenhouse gases that occur naturally in the atmosphere (e.g. H₂O, CO₂, CH₄);',1,1);
INSERT INTO rubric_criterion VALUES(14420,'physics12a1-gh-6',NULL,1,'enhanced: additional warming due to increased greenhouse gas concentrations from human activity such as fossil fuel combustion;',1,1);
INSERT INTO rubric_criterion VALUES(14421,'physics12a1-gh-6',NULL,2,'the natural effect keeps the Earth''s average surface temperature at about 288 K (15 °C) rather than about 255 K (−18 °C), allowing liquid water.',1,1);
INSERT INTO rubric_criterion VALUES(14422,'physics12a1-gh-7',NULL,0,'Thermal expansion: as the oceans warm, the water expands, increasing its volume; melting of land-based ice (glaciers and ice sheets, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(14423,'physics12a1-gh-7',NULL,1,'Greenland and Antarctica) adds water to the oceans;',1,1);
INSERT INTO rubric_criterion VALUES(14424,'physics12a1-gh-7',NULL,2,'floating sea ice contributes little because it already displaces its own mass of water (any two, with explanation).',1,1);
INSERT INTO rubric_criterion VALUES(14425,'physics12a1-gh-8',NULL,0,'Sunlight is mostly visible and passes through the atmosphere largely unabsorbed to heat the surface;',1,1);
INSERT INTO rubric_criterion VALUES(14426,'physics12a1-gh-8',NULL,1,'the Earth, at a much lower temperature, emits at longer wavelengths (infrared, by Wien''s law);',1,1);
INSERT INTO rubric_criterion VALUES(14427,'physics12a1-gh-8',NULL,2,'greenhouse gases absorb infrared strongly, trapping energy and re-emitting some back to the surface.',1,1);
INSERT INTO rubric_criterion VALUES(14447,'physics12a1-gh-28',NULL,0,'Burning fossil fuels releases carbon dioxide (a greenhouse gas) into the atmosphere, increasing its concentration [1];',1,1);
INSERT INTO rubric_criterion VALUES(14448,'physics12a1-gh-28',NULL,1,'the extra greenhouse gas absorbs and re-emits more of the infrared radiation emitted by the Earth, returning more energy to the surface and raising the average temperature [1].',1,1);
INSERT INTO rubric_criterion VALUES(14449,'physics12a1-gh-29',NULL,0,'λ_max = 2.898 × 10⁻³ ÷ 330 = 8.8 × 10⁻⁶ m (8.8 µm) [1];',1,1);
INSERT INTO rubric_criterion VALUES(14450,'physics12a1-gh-29',NULL,1,'this is in the infrared region [1].',1,1);
INSERT INTO rubric_criterion VALUES(14451,'physics12a1-gh-30',NULL,0,'Snow compacts into ice and traps small bubbles of air from the time it fell [1]; analysing the gas in the bubbles at different depths gives past CO₂ concentrations, with deeper ice being older [1];',1,1);
INSERT INTO rubric_criterion VALUES(14452,'physics12a1-gh-30',NULL,1,'the ratios of isotopes (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(14453,'physics12a1-gh-30',NULL,2,'oxygen or hydrogen) in the ice depend on the temperature at the time, giving past temperatures [1].',1,1);
INSERT INTO rubric_criterion VALUES(14454,'physics12a1-gh-31',NULL,0,'A positive feedback is a process in which an initial change causes a further change in the same direction, amplifying the original effect [1];',1,1);
INSERT INTO rubric_criterion VALUES(14455,'physics12a1-gh-31',NULL,1,'warming thaws permafrost, releasing trapped methane and CO₂ [1];',1,1);
INSERT INTO rubric_criterion VALUES(14456,'physics12a1-gh-31',NULL,2,'these greenhouse gases enhance warming, causing more thawing [1].',1,1);
INSERT INTO rubric_criterion VALUES(14457,'physics12a1-gh-32',NULL,0,'At equilibrium, the rate at which the Earth absorbs solar energy equals the rate at which it radiates energy to space [1];',1,1);
INSERT INTO rubric_criterion VALUES(14458,'physics12a1-gh-32',NULL,1,'extra CO₂ absorbs more of the infrared emitted by the surface and re-emits some back downward, so less energy escapes to space [1];',1,1);
INSERT INTO rubric_criterion VALUES(14459,'physics12a1-gh-32',NULL,2,'absorbed energy now exceeds energy radiated, so the Earth gains energy and its temperature rises [1];',1,1);
INSERT INTO rubric_criterion VALUES(14460,'physics12a1-gh-32',NULL,3,'as it warms, it emits more radiation until emitted and absorbed rates are equal again at a higher temperature [1].',1,1);
INSERT INTO rubric_criterion VALUES(14461,'physics12a1-gh-33',NULL,0,'Fractional increase in volume = 2.1 × 10⁻⁴ × 0.80 = 1.68 × 10⁻⁴ [1];',1,1);
INSERT INTO rubric_criterion VALUES(14462,'physics12a1-gh-33',NULL,1,'for a fixed area, the fractional change in depth equals the fractional change in volume [1];',1,1);
INSERT INTO rubric_criterion VALUES(14463,'physics12a1-gh-33',NULL,2,'rise = 800 × 1.68 × 10⁻⁴ = 0.13 m [1].',1,1);
INSERT INTO rubric_criterion VALUES(14464,'physics12a1-gh-34',NULL,0,'Net power = 0.60 × 5.1 × 10¹⁴ = 3.1 × 10¹⁴ W [1];',1,1);
INSERT INTO rubric_criterion VALUES(14465,'physics12a1-gh-34',NULL,1,'energy = power × time [1];',1,1);
INSERT INTO rubric_criterion VALUES(14466,'physics12a1-gh-34',NULL,2,'E = 3.06 × 10¹⁴ × 3.15 × 10⁷ = 9.6 × 10²¹ J [1].',1,1);
INSERT INTO rubric_criterion VALUES(14467,'physics12a1-gh-35',NULL,0,'CO₂ dissolves in seawater to form carbonic acid, lowering the pH of the oceans (ocean acidification) [1];',1,1);
INSERT INTO rubric_criterion VALUES(14468,'physics12a1-gh-35',NULL,1,'this makes it harder for organisms such as corals and shellfish to build calcium carbonate shells and skeletons, threatening marine ecosystems [1].',1,1);
INSERT INTO rubric_criterion VALUES(14469,'physics12a1-gh-36',NULL,0,'A large eruption injects sulfate aerosols into the upper atmosphere that reflect incoming sunlight, increasing albedo and cooling the Earth [1];',1,1);
INSERT INTO rubric_criterion VALUES(14470,'physics12a1-gh-36',NULL,1,'this effect is short lived (a year or two) as the aerosols settle out [1];',1,1);
INSERT INTO rubric_criterion VALUES(14471,'physics12a1-gh-36',NULL,2,'increased CO₂ absorbs infrared emitted by the Earth, trapping more energy and causing long-lasting warming [1].',1,1);
INSERT INTO rubric_criterion VALUES(14472,'physics12a1-gh-37',NULL,0,'A cold week is a short-term weather event, the state of the atmosphere over a short time [1];',1,1);
INSERT INTO rubric_criterion VALUES(14473,'physics12a1-gh-37',NULL,1,'climate is the average of weather over long periods (decades), so global warming is assessed from long-term trends in average temperature [1];',1,1);
INSERT INTO rubric_criterion VALUES(14474,'physics12a1-gh-37',NULL,2,'a single cold week is consistent with warming because short-term variation occurs about a rising average, so the claim is not valid [1].',1,1);
INSERT INTO rubric_criterion VALUES(14481,'physics12a1-wave-6',NULL,0,'(a) f = c/λ = 3.00 × 10⁸ / 650 × 10⁻⁹ = 4.62 × 10¹⁴ Hz;',1,1);
INSERT INTO rubric_criterion VALUES(14482,'physics12a1-wave-6',NULL,1,'(b) v = c/n = 3.00 × 10⁸ / 1.50 = 2.00 × 10⁸ m s⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(14483,'physics12a1-wave-6',NULL,2,'(c) λ = v/f = 2.00 × 10⁸ / 4.62 × 10¹⁴ = 4.33 × 10⁻⁷ m (433 nm).',1,1);
INSERT INTO rubric_criterion VALUES(14484,'physics12a1-wave-7',NULL,0,'Intensity is a maximum when axes are parallel and decreases to (almost) zero when the filters are at 90° (crossed);',1,1);
INSERT INTO rubric_criterion VALUES(14485,'physics12a1-wave-7',NULL,1,'this occurs because only the component of the light''s oscillation along the transmission axis passes through;',1,1);
INSERT INTO rubric_criterion VALUES(14486,'physics12a1-wave-7',NULL,2,'sound is a longitudinal wave, whose oscillations are along the direction of travel, so there is no transverse direction to filter.',1,1);
INSERT INTO rubric_criterion VALUES(14487,'physics12a1-wave-8',NULL,0,'Diffraction is significant when the opening is comparable to the wavelength;',1,1);
INSERT INTO rubric_criterion VALUES(14488,'physics12a1-wave-8',NULL,1,'visible light has a wavelength of about 5 × 10⁻⁷ m, far smaller than a doorway (about 1 m), so there is negligible spreading;',1,1);
INSERT INTO rubric_criterion VALUES(14489,'physics12a1-wave-8',NULL,2,'audible sound has wavelengths of about 0.1 m to several metres, comparable to the doorway, so it diffracts noticeably.',1,1);
INSERT INTO rubric_criterion VALUES(14509,'physics12a1-wave-28',NULL,0,'Coherent sources emit waves of the same frequency with a constant phase difference [1];',1,1);
INSERT INTO rubric_criterion VALUES(14510,'physics12a1-wave-28',NULL,1,'both slits are illuminated by the same wavefront from one source, so they keep a fixed phase relationship and produce a stable interference pattern [1].',1,1);
INSERT INTO rubric_criterion VALUES(14511,'physics12a1-wave-29',NULL,0,'Use Δx = λL/d [1];',1,1);
INSERT INTO rubric_criterion VALUES(14512,'physics12a1-wave-29',NULL,1,'Δx = (550 × 10⁻⁹ × 2.0) / (0.25 × 10⁻³) [1];',1,1);
INSERT INTO rubric_criterion VALUES(14513,'physics12a1-wave-29',NULL,2,'Δx = 4.4 × 10⁻³ m (4.4 mm) [1].',1,1);
INSERT INTO rubric_criterion VALUES(14514,'physics12a1-wave-30',NULL,0,'Light diffracts at each slit so that waves spread out and overlap [1];',1,1);
INSERT INTO rubric_criterion VALUES(14515,'physics12a1-wave-30',NULL,1,'where the path difference is a whole number of wavelengths the waves arrive in phase and interfere constructively, giving a bright fringe [1];',1,1);
INSERT INTO rubric_criterion VALUES(14516,'physics12a1-wave-30',NULL,2,'where the path difference is an odd number of half wavelengths they arrive out of phase and interfere destructively, giving a dark fringe [1].',1,1);
INSERT INTO rubric_criterion VALUES(14517,'physics12a1-wave-31',NULL,0,'Path difference in wavelengths = 2.4 × 10⁻⁶ / 6.00 × 10⁻⁷ = 4.0 [1];',1,1);
INSERT INTO rubric_criterion VALUES(14518,'physics12a1-wave-31',NULL,1,'a whole number of wavelengths means constructive interference, so P is a bright fringe [1].',1,1);
INSERT INTO rubric_criterion VALUES(14519,'physics12a1-wave-32',NULL,0,'λ = c/f = 3.00 × 10⁸ / 1.00 × 10⁸ = 3.0 m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14520,'physics12a1-wave-32',NULL,1,'diffraction is significant when the obstacle or opening is comparable in size to the wavelength [1];',1,1);
INSERT INTO rubric_criterion VALUES(14521,'physics12a1-wave-32',NULL,2,'radio wavelengths (metres) are comparable to buildings, whereas visible light (about 5 × 10⁻⁷ m) is far smaller, so it shows negligible diffraction [1].',1,1);
INSERT INTO rubric_criterion VALUES(14522,'physics12a1-wave-33',NULL,0,'The fringe spacing decreases [1];',1,1);
INSERT INTO rubric_criterion VALUES(14523,'physics12a1-wave-33',NULL,1,'the frequency stays the same but the speed of light is lower in water, so the wavelength decreases [1];',1,1);
INSERT INTO rubric_criterion VALUES(14524,'physics12a1-wave-33',NULL,2,'since Δx = λL/d, a smaller λ gives a smaller fringe spacing [1].',1,1);
INSERT INTO rubric_criterion VALUES(14525,'physics12a1-wave-34',NULL,0,'Rearrange Δx = λL/d to λ = Δx d / L [1];',1,1);
INSERT INTO rubric_criterion VALUES(14526,'physics12a1-wave-34',NULL,1,'λ = (3.6 × 10⁻³ × 3.0 × 10⁻⁴) / 1.8 [1];',1,1);
INSERT INTO rubric_criterion VALUES(14527,'physics12a1-wave-34',NULL,2,'λ = 6.0 × 10⁻⁷ m (600 nm) [1].',1,1);
INSERT INTO rubric_criterion VALUES(14534,'physics12a1-em-6',NULL,0,'(a) radio, microwave, infrared, visible, ultraviolet, X-ray, gamma (all in correct order for 2 marks);',1,1);
INSERT INTO rubric_criterion VALUES(14535,'physics12a1-em-6',NULL,1,'(b) c = fλ, so frequency is inversely proportional to wavelength (constant speed in a vacuum).',2,1);
INSERT INTO rubric_criterion VALUES(14536,'physics12a1-em-7',NULL,0,'(a) f = c/λ = 3.00 × 10⁸ / 1.00 × 10⁻¹⁰ = 3.00 × 10¹⁸ Hz;',1,1);
INSERT INTO rubric_criterion VALUES(14537,'physics12a1-em-7',NULL,1,'(b) t = d/c = 1.50 × 10¹¹ / 3.00 × 10⁸ = 500 s (about 8.3 minutes).',2,1);
INSERT INTO rubric_criterion VALUES(14538,'physics12a1-em-8',NULL,0,'Ultraviolet has a higher frequency (shorter wavelength) so each photon carries more energy; this energy can damage DNA and cells (e.g.',1,1);
INSERT INTO rubric_criterion VALUES(14539,'physics12a1-em-8',NULL,1,'sunburn, skin cancer) whereas visible light photons do not;',1,1);
INSERT INTO rubric_criterion VALUES(14540,'physics12a1-em-8',NULL,2,'protection: the ozone layer absorbs UV, or sunscreen, clothing and sunglasses absorb or block it.',1,1);
INSERT INTO rubric_criterion VALUES(14557,'physics12a1-em-25',NULL,0,'They all travel at the same speed, c = 3.00 × 10⁸ m s⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(14558,'physics12a1-em-25',NULL,1,'they are all transverse waves of oscillating electric and magnetic fields (and can travel through a vacuum) [1];',1,1);
INSERT INTO rubric_criterion VALUES(14559,'physics12a1-em-25',NULL,2,'frequency (or wavelength, or photon energy) differs between regions [1].',1,1);
INSERT INTO rubric_criterion VALUES(14560,'physics12a1-em-26',NULL,0,'All objects above absolute zero emit infrared radiation, with warmer objects emitting more, due to the thermal motion of their particles [1]; application, e.g.',1,1);
INSERT INTO rubric_criterion VALUES(14561,'physics12a1-em-26',NULL,1,'thermal imaging cameras, remote controls or infrared heaters [1].',1,1);
INSERT INTO rubric_criterion VALUES(14562,'physics12a1-em-27',NULL,0,'Ionising radiation has photons with enough energy to remove electrons from atoms or molecules [1]; non-ionising radiation does not have enough energy to do so [1];',1,1);
INSERT INTO rubric_criterion VALUES(14563,'physics12a1-em-27',NULL,1,'examples: ionising: ultraviolet (high end), X-rays or gamma rays;',1,1);
INSERT INTO rubric_criterion VALUES(14564,'physics12a1-em-27',NULL,2,'non-ionising: radio, microwave, infrared or visible [1].',1,1);
INSERT INTO rubric_criterion VALUES(14565,'physics12a1-em-28',NULL,0,'X-rays are directed through the arm onto a detector or film [1];',1,1);
INSERT INTO rubric_criterion VALUES(14566,'physics12a1-em-28',NULL,1,'bone absorbs more X-rays than soft tissue, so fewer X-rays reach the detector behind the bone [1];',1,1);
INSERT INTO rubric_criterion VALUES(14567,'physics12a1-em-28',NULL,2,'this produces contrast, with the bone appearing as a different brightness from the surrounding tissue, so the fracture is visible [1].',1,1);
INSERT INTO rubric_criterion VALUES(14568,'physics12a1-em-29',NULL,0,'Total distance travelled = ct = 3.00 × 10⁸ × 4.0 × 10⁻⁴ = 1.2 × 10⁵ m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14569,'physics12a1-em-29',NULL,1,'this is a round trip, so divide by 2 [1];',1,1);
INSERT INTO rubric_criterion VALUES(14570,'physics12a1-em-29',NULL,2,'distance = 6.0 × 10⁴ m (60 km) [1].',1,1);
INSERT INTO rubric_criterion VALUES(14571,'physics12a1-em-30',NULL,0,'Gamma rays have a much higher frequency than radio waves [1];',1,1);
INSERT INTO rubric_criterion VALUES(14572,'physics12a1-em-30',NULL,1,'gamma rays have a much shorter wavelength than radio waves [1];',1,1);
INSERT INTO rubric_criterion VALUES(14573,'physics12a1-em-30',NULL,2,'gamma-ray photons carry much more energy than radio-wave photons [1].',1,1);
INSERT INTO rubric_criterion VALUES(14574,'physics12a1-em-31',NULL,0,'Sterilising water or equipment, because ultraviolet photons have enough energy to damage the DNA of microbes [1];',1,1);
INSERT INTO rubric_criterion VALUES(14575,'physics12a1-em-31',NULL,1,'detecting forged banknotes (or fluorescence), because certain materials absorb ultraviolet and re-emit visible light [1].',1,1);
INSERT INTO rubric_criterion VALUES(14576,'physics12a1-em-32',NULL,0,'f = c/λ [1];',1,1);
INSERT INTO rubric_criterion VALUES(14577,'physics12a1-em-32',NULL,1,'violet: 3.00 × 10⁸ / 4.00 × 10⁻⁷ = 7.50 × 10¹⁴ Hz [1];',1,1);
INSERT INTO rubric_criterion VALUES(14578,'physics12a1-em-32',NULL,2,'red: 3.00 × 10⁸ / 7.00 × 10⁻⁷ = 4.29 × 10¹⁴ Hz [1];',1,1);
INSERT INTO rubric_criterion VALUES(14579,'physics12a1-em-32',NULL,3,'violet has the higher frequency (shorter wavelength) [1].',1,1);
INSERT INTO rubric_criterion VALUES(14580,'physics12a1-em-33',NULL,0,'The claim is incorrect: all electromagnetic waves, including radio and visible light, travel at the same speed c = 3.00 × 10⁸ m s⁻¹ in a vacuum [1];',1,1);
INSERT INTO rubric_criterion VALUES(14581,'physics12a1-em-33',NULL,1,'radio waves are used for communication because of their long wavelengths and how they interact with the atmosphere, not because they are faster [1].',1,1);
INSERT INTO rubric_criterion VALUES(14582,'physics12a1-em-34',NULL,0,'λ = c/f [1];',1,1);
INSERT INTO rubric_criterion VALUES(14583,'physics12a1-em-34',NULL,1,'5G: 3.00 × 10⁸ / 2.80 × 10¹⁰ = 1.07 × 10⁻² m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14584,'physics12a1-em-34',NULL,2,'older: 3.00 × 10⁸ / 7.00 × 10⁸ = 0.429 m [1].',1,1);
INSERT INTO rubric_criterion VALUES(14591,'physics12a1-ref-6',NULL,0,'(a) sin θ₂ = sin 30.0° / 1.33 = 0.3759, θ₂ = 22.1°;',1,1);
INSERT INTO rubric_criterion VALUES(14592,'physics12a1-ref-6',NULL,1,'(b) v = c/n = 3.00 × 10⁸ / 1.33 = 2.26 × 10⁸ m s⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(14593,'physics12a1-ref-6',NULL,2,'(c) towards the normal, as light slows in the higher-index medium.',2,1);
INSERT INTO rubric_criterion VALUES(14594,'physics12a1-ref-7',NULL,0,'(a) sin θc = 1/2.42 = 0.413, so θc = 24.4°;',1,1);
INSERT INTO rubric_criterion VALUES(14595,'physics12a1-ref-7',NULL,1,'(b) the critical angle is small so light entering the diamond strikes internal surfaces at angles larger than θc and is totally internally reflected many times before exiting through certain faces, producing intense sparkle.',2,1);
INSERT INTO rubric_criterion VALUES(14596,'physics12a1-ref-8',NULL,0,'Rays from a point on the bottom bend away from the normal as they pass from water into air (lower n);',1,1);
INSERT INTO rubric_criterion VALUES(14597,'physics12a1-ref-8',NULL,1,'the eye traces the rays back in straight lines to an apparent source position;',1,1);
INSERT INTO rubric_criterion VALUES(14598,'physics12a1-ref-8',NULL,2,'this apparent position is higher than the real position, so the pool looks shallower.',1,1);
INSERT INTO rubric_criterion VALUES(14616,'physics12a1-ref-26',NULL,0,'sin θ₂ = (1.00 × sin 35.0°)/1.52 = 0.5736/1.52 = 0.3774 [1];',1,1);
INSERT INTO rubric_criterion VALUES(14617,'physics12a1-ref-26',NULL,1,'θ₂ = 22.2° [1]',1,1);
INSERT INTO rubric_criterion VALUES(14618,'physics12a1-ref-27',NULL,0,'(a) v = c/n = 3.00 × 10⁸ / 1.52 = 1.97 × 10⁸ m s⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(14619,'physics12a1-ref-27',NULL,1,'(b) frequency is unchanged, so λ = λ₀/n = 589/1.52 [1] = 388 nm [1]',2,1);
INSERT INTO rubric_criterion VALUES(14620,'physics12a1-ref-28',NULL,0,'Light travels more slowly in glass than in air (higher refractive index) [1];',1,1);
INSERT INTO rubric_criterion VALUES(14621,'physics12a1-ref-28',NULL,1,'the part of the wavefront that enters the glass first slows down first, so the wavefront swings and the ray bends towards the normal [1]',1,1);
INSERT INTO rubric_criterion VALUES(14622,'physics12a1-ref-29',NULL,0,'(a) sin θc = 1.00/1.60 = 0.625 [1], θc = 38.7° [1];',1,1);
INSERT INTO rubric_criterion VALUES(14623,'physics12a1-ref-29',NULL,1,'(b) light must travel from the higher-index glass towards air, and the angle of incidence must exceed the critical angle [1]',2,1);
INSERT INTO rubric_criterion VALUES(14624,'physics12a1-ref-30',NULL,0,'sin θ₂ = 1.33 × sin 40.0° / 1.50 = 1.33 × 0.6428/1.50 = 0.5700 [1];',1,1);
INSERT INTO rubric_criterion VALUES(14625,'physics12a1-ref-30',NULL,1,'θ₂ = 34.7° [1]',1,1);
INSERT INTO rubric_criterion VALUES(14626,'physics12a1-ref-31',NULL,0,'Shine a narrow ray from the ray box into the block at several different angles of incidence, tracing the incident and emergent rays and the block outline on paper [1];',1,1);
INSERT INTO rubric_criterion VALUES(14627,'physics12a1-ref-31',NULL,1,'draw the normal and join the entry and exit points to find the refracted ray inside the block [1];',1,1);
INSERT INTO rubric_criterion VALUES(14628,'physics12a1-ref-31',NULL,2,'measure the angles of incidence and refraction with a protractor for each trial [1];',1,1);
INSERT INTO rubric_criterion VALUES(14629,'physics12a1-ref-31',NULL,3,'plot sin θ₁ against sin θ₂ (or calculate sin θ₁/sin θ₂ for each trial) and the gradient (average) gives the refractive index of the glass [1]',1,1);
INSERT INTO rubric_criterion VALUES(14630,'physics12a1-ref-32',NULL,0,'The fibre has a core of higher refractive index surrounded by cladding of lower refractive index [1];',1,1);
INSERT INTO rubric_criterion VALUES(14631,'physics12a1-ref-32',NULL,1,'light enters the core and strikes the core–cladding boundary at an angle of incidence greater than the critical angle [1];',1,1);
INSERT INTO rubric_criterion VALUES(14632,'physics12a1-ref-32',NULL,2,'it is totally internally reflected repeatedly, so none escapes and it travels along the fibre [1]',1,1);
INSERT INTO rubric_criterion VALUES(14633,'physics12a1-ref-33',NULL,0,'Light from the submerged part of the straw bends away from the normal as it passes from water into air [1];',1,1);
INSERT INTO rubric_criterion VALUES(14634,'physics12a1-ref-33',NULL,1,'the eye traces these rays back in straight lines, so the submerged part appears at a different (shallower) position from the part in air, making the straw look bent [1]',1,1);
INSERT INTO rubric_criterion VALUES(14635,'physics12a1-ref-34',NULL,0,'(a) sin θ₂ = 1.50 × sin 55.0° / 1.33 = 1.50 × 0.8192/1.33 = 0.9238 [1], θ₂ = 67.5° [1];',1,1);
INSERT INTO rubric_criterion VALUES(14636,'physics12a1-ref-34',NULL,1,'(b) no, because the angle of incidence (55.0°) is less than the critical angle sin⁻¹(1.33/1.50) = 62.5° [1]',2,1);
INSERT INTO rubric_criterion VALUES(14637,'physics12a1-ref-35',NULL,0,'Trial 1: n = sin 20.0°/sin 13.0° = 0.3420/0.2250 = 1.52 [1];',1,1);
INSERT INTO rubric_criterion VALUES(14638,'physics12a1-ref-35',NULL,1,'Trial 2: n = sin 40.0°/sin 25.0° = 0.6428/0.4226 = 1.52 [1];',1,1);
INSERT INTO rubric_criterion VALUES(14639,'physics12a1-ref-35',NULL,2,'average refractive index = 1.52 [1]',1,1);
INSERT INTO rubric_criterion VALUES(14640,'physics12a1-ref-36',NULL,0,'(a) λ = c/f = 3.00 × 10⁸ / 5.00 × 10¹⁴ = 6.00 × 10⁻⁷ m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14641,'physics12a1-ref-36',NULL,1,'(b) v = c/n = 3.00 × 10⁸ / 1.33 = 2.26 × 10⁸ m s⁻¹ [1];',1,1);
INSERT INTO rubric_criterion VALUES(14642,'physics12a1-ref-36',NULL,2,'(c) λ = v/f = 2.26 × 10⁸ / 5.00 × 10¹⁴ = 4.51 × 10⁻⁷ m [1];',1,1);
INSERT INTO rubric_criterion VALUES(14643,'physics12a1-ref-36',NULL,3,'(d) frequency is unchanged, 5.00 × 10¹⁴ Hz [1]',1,1);
INSERT INTO rubric_criterion VALUES(14644,'physics12a1-ref-37',NULL,0,'The refractive index of glass is slightly different for different wavelengths, being larger for violet/blue light than for red light [1];',1,1);
INSERT INTO rubric_criterion VALUES(14645,'physics12a1-ref-37',NULL,1,'so on entering the prism each colour is refracted through a different angle (violet bends most, red least) [1];',1,1);
INSERT INTO rubric_criterion VALUES(14646,'physics12a1-ref-37',NULL,2,'the separation increases at the second face, producing a spectrum [1]',1,1);
INSERT INTO rubric_criterion VALUES(14647,'vce-physics12-rs-c1',NULL,0,'About 25°',2,1);
INSERT INTO rubric_criterion VALUES(14653,'physics12a2-tir-6',NULL,0,'(a) sin θc = 1/2.42 = 0.413, so θc ≈ 24.4°;',1,1);
INSERT INTO rubric_criterion VALUES(14654,'physics12a2-tir-6',NULL,1,'(b) the critical angle is small, so most rays inside the diamond strike internal faces at angles greater than θc;',1,1);
INSERT INTO rubric_criterion VALUES(14655,'physics12a2-tir-6',NULL,2,'they undergo total internal reflection several times before leaving through the top, giving bright sparkle (and dispersion adds colour).',1,1);
INSERT INTO rubric_criterion VALUES(14656,'physics12a2-tir-7',NULL,0,'(a) sin θc = 1.33/1.52 = 0.875, so θc ≈ 61°;',1,1);
INSERT INTO rubric_criterion VALUES(14657,'physics12a2-tir-7',NULL,1,'(b) at 55° (< θc) the ray is partly refracted into the water, bending away from the normal, with a weak partial reflection;',1,1);
INSERT INTO rubric_criterion VALUES(14658,'physics12a2-tir-7',NULL,2,'at 65° (> θc) there is total internal reflection, so no light enters the water.',1,1);
INSERT INTO rubric_criterion VALUES(14659,'physics12a2-tir-8',NULL,0,'White light is a mixture of wavelengths; the refractive index of the glass or water depends on wavelength, being greater for shorter wavelengths;',1,1);
INSERT INTO rubric_criterion VALUES(14660,'physics12a2-tir-8',NULL,1,'so each colour refracts by a different amount and separates (violet bends most, red least);',1,1);
INSERT INTO rubric_criterion VALUES(14661,'physics12a2-tir-8',NULL,2,'in a raindrop the red light is deviated least, so it reaches the observer from the higher, outer part of the bow.',1,1);
INSERT INTO rubric_criterion VALUES(14668,'physics12a2-nsi-6',NULL,0,'(a) E = 0.0304 × 931.5 ≈ 28.3 MeV;',1,1);
INSERT INTO rubric_criterion VALUES(14669,'physics12a2-nsi-6',NULL,1,'(b) 4 nucleons, so 28.3 / 4 ≈ 7.08 MeV per nucleon (≈ 7.1 MeV).',2,1);
INSERT INTO rubric_criterion VALUES(14670,'physics12a2-nsi-7',NULL,0,'(a) each has 6 protons; neutrons 6, 7 and 8 respectively;',1,1);
INSERT INTO rubric_criterion VALUES(14671,'physics12a2-nsi-7',NULL,1,'(b) ¹⁴C has too many neutrons for its number of protons (N/Z above the stable band), so the nucleus is unstable;',1,1);
INSERT INTO rubric_criterion VALUES(14672,'physics12a2-nsi-7',NULL,2,'it changes by decay (beta-minus) to reach a more stable ratio.',1,1);
INSERT INTO rubric_criterion VALUES(14673,'physics12a2-nsi-8',NULL,0,'The strong force is attractive but very short range, so each nucleon only attracts its near neighbours; the electrostatic repulsion between protons has a long range and acts between all proton pairs, so it grows faster with size;',1,1);
INSERT INTO rubric_criterion VALUES(14674,'physics12a2-nsi-8',NULL,1,'extra neutrons add strong-force attraction and spread the protons apart without adding repulsion;',1,1);
INSERT INTO rubric_criterion VALUES(14675,'physics12a2-nsi-8',NULL,2,'so heavy nuclei need N > Z to be stable.',1,1);
INSERT INTO rubric_criterion VALUES(14682,'physics12a2-abg-6',NULL,0,'(a) ²⁴¹₉₅Am → ²³⁷₉₃Np + ⁴₂He;',1,1);
INSERT INTO rubric_criterion VALUES(14683,'physics12a2-abg-6',NULL,1,'(b) ¹⁴₆C → ¹⁴₇N + ⁰₋₁e + antineutrino (ν̄);',1,1);
INSERT INTO rubric_criterion VALUES(14684,'physics12a2-abg-6',NULL,2,'mass numbers and atomic numbers balance on both sides in each equation.',1,1);
INSERT INTO rubric_criterion VALUES(14685,'physics12a2-abg-7',NULL,0,'Alpha: greatest ionising ability (large mass and +2 charge), least penetrating (stopped by paper or a few cm of air); beta: moderate ionising ability, moderate penetration (stopped by a few mm of aluminium);',1,1);
INSERT INTO rubric_criterion VALUES(14686,'physics12a2-abg-7',NULL,1,'gamma: weakest ionising ability (no charge), most penetrating (needs thick lead or concrete);',1,1);
INSERT INTO rubric_criterion VALUES(14687,'physics12a2-abg-7',NULL,2,'ionising ability and penetrating power are inversely related.',1,1);
INSERT INTO rubric_criterion VALUES(14688,'physics12a2-abg-8',NULL,0,'Alpha particles strongly ionise the air in the chamber, producing a steady current between the plates; smoke particles absorb or attach to the ions and reduce the current, triggering the alarm;',1,1);
INSERT INTO rubric_criterion VALUES(14689,'physics12a2-abg-8',NULL,1,'alpha radiation is stopped by the detector casing and a few cm of air, so little escapes;',1,1);
INSERT INTO rubric_criterion VALUES(14690,'physics12a2-abg-8',NULL,2,'the source is only dangerous if ingested or inhaled.',1,1);
INSERT INTO rubric_criterion VALUES(14709,'physics12a2-abg-27',NULL,0,'Measure the count rate with no absorber and subtract background radiation [1] place each absorber in turn between source and detector;',1,1);
INSERT INTO rubric_criterion VALUES(14710,'physics12a2-abg-27',NULL,1,'a drop with paper indicates alpha, a drop with aluminium indicates beta [1] a count that remains until thick lead is added indicates gamma [1]',2,1);
INSERT INTO rubric_criterion VALUES(14711,'physics12a2-abg-28',NULL,0,'Alpha particles are massive, slow and carry a +2 charge, so they interact strongly with atoms and strip electrons from them [1] this means they lose their energy in a very short distance and are stopped by paper or a few cm of air [1] gamma photons are uncharged and interact rarely with matter, so they ionise little per unit distance but travel far through dense materials [1]',3,1);
INSERT INTO rubric_criterion VALUES(14712,'physics12a2-abg-29',NULL,0,'²²²₈₆Rn → ²¹⁸₈₄Po + ⁴₂He with mass numbers and atomic numbers balanced [1]',1,1);
INSERT INTO rubric_criterion VALUES(14713,'physics12a2-abg-30',NULL,0,'Alpha particles are positively charged and are deflected in one direction along a curved path [1] beta-minus particles are negatively charged and are deflected in the opposite direction, with a tighter curve because of their much smaller mass [1] gamma rays have no charge so they are not deflected [1]',3,1);
INSERT INTO rubric_criterion VALUES(14714,'physics12a2-abg-31',NULL,0,'²¹⁴₈₃Bi → ²¹⁴₈₄Po + ⁰₋₁e + antineutrino (ν̄) [1] polonium-214 with Z = 84 identified as the daughter [1] ²¹⁴₈₄Po → ²¹⁰₈₂Pb + ⁴₂He [1] lead-210 with Z = 82 identified, with A and Z balanced in both equations [1]',4,1);
INSERT INTO rubric_criterion VALUES(14721,'physics12a2-hla-6',NULL,0,'(a) 24 days is 3 half-lives: 64 → 32 → 16 → 8.0 MBq;',1,1);
INSERT INTO rubric_criterion VALUES(14722,'physics12a2-hla-6',NULL,1,'(b) 64 to 2.0 MBq is a factor of 32 = 2⁵, so 5 half-lives;',1,1);
INSERT INTO rubric_criterion VALUES(14723,'physics12a2-hla-6',NULL,2,'5 × 8.0 = 40 days.',1,1);
INSERT INTO rubric_criterion VALUES(14724,'physics12a2-hla-7',NULL,0,'25% is two halvings (100 → 50 → 25), so 2 half-lives;',1,1);
INSERT INTO rubric_criterion VALUES(14725,'physics12a2-hla-7',NULL,1,'age ≈ 2 × 5730 = 11 460 years (about 1.1 × 10⁴ years);',1,1);
INSERT INTO rubric_criterion VALUES(14726,'physics12a2-hla-7',NULL,2,'assumption: the ratio of carbon-14 in living organisms (atmosphere) was constant over time, so the original activity equals that of living wood.',1,1);
INSERT INTO rubric_criterion VALUES(14727,'physics12a2-hla-8',NULL,0,'(a) 24 h is 4 half-lives, (1/2)⁴ = 1/16 ≈ 6.25%;',1,1);
INSERT INTO rubric_criterion VALUES(14728,'physics12a2-hla-8',NULL,1,'(b) long enough for the imaging to be carried out after preparation and delivery;',1,1);
INSERT INTO rubric_criterion VALUES(14729,'physics12a2-hla-8',NULL,2,'short enough that the activity (and the patient''s dose) falls quickly so it does not stay in the body for long.',1,1);
INSERT INTO rubric_criterion VALUES(14736,'physics12a2-nff-6',NULL,0,'(a) E = 0.20 × 931.5 = 186 MeV (186.3);',1,1);
INSERT INTO rubric_criterion VALUES(14737,'physics12a2-nff-6',NULL,1,'(b) 186.3 × 10⁶ eV × 1.60 × 10⁻¹⁹ J eV⁻¹ ≈ 2.98 × 10⁻¹¹ J (about 3.0 × 10⁻¹¹ J).',2,1);
INSERT INTO rubric_criterion VALUES(14738,'physics12a2-nff-7',NULL,0,'Fission: heavy nuclei (e.g. U-235) split, started by neutron absorption, at moderate temperatures, producing radioactive fission products that need long-term storage;',1,1);
INSERT INTO rubric_criterion VALUES(14739,'physics12a2-nff-7',NULL,1,'fusion: light nuclei (e.g. H-2 and H-3) join, requiring extremely high temperature and pressure, producing helium and neutrons with much less long-lived waste;',1,1);
INSERT INTO rubric_criterion VALUES(14740,'physics12a2-nff-7',NULL,2,'both release energy because binding energy per nucleon increases.',1,1);
INSERT INTO rubric_criterion VALUES(14741,'physics12a2-nff-8',NULL,0,'A neutron is absorbed by a U-235 nucleus, which splits and releases two or three more neutrons; these can cause further fissions (a chain reaction);',1,1);
INSERT INTO rubric_criterion VALUES(14742,'physics12a2-nff-8',NULL,1,'a moderator slows the neutrons so they are more likely to be absorbed;',1,1);
INSERT INTO rubric_criterion VALUES(14743,'physics12a2-nff-8',NULL,2,'control rods absorb excess neutrons so that, on average, one neutron per fission causes another fission and the power stays steady.',1,1);
INSERT INTO rubric_criterion VALUES(14744,'vce-physics12-nf-c1',NULL,0,'About 2.8 × 10⁻¹¹ J',2,1);
INSERT INTO rubric_criterion VALUES(14750,'physics12a2-rdb-6',NULL,0,'(a) D = E/m = 2.5 × 10⁻³ / 50 = 5.0 × 10⁻⁵ Gy;',1,1);
INSERT INTO rubric_criterion VALUES(14751,'physics12a2-rdb-6',NULL,1,'(b) H = wR × D = 20 × 5.0 × 10⁻⁵ = 1.0 × 10⁻³ Sv (1.0 mSv).',2,1);
INSERT INTO rubric_criterion VALUES(14752,'physics12a2-rdb-7',NULL,0,'(a) reduce the time of exposure, increase the distance, use shielding (e.g. lead);',1,1);
INSERT INTO rubric_criterion VALUES(14753,'physics12a2-rdb-7',NULL,1,'(b) at 2.0 m the dose rate is 80 / 2² = 20 µSv h⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(14754,'physics12a2-rdb-7',NULL,2,'dose = 20 × 3.0 = 60 µSv.',1,1);
INSERT INTO rubric_criterion VALUES(14755,'physics12a2-rdb-8',NULL,0,'Ionising radiation removes electrons from atoms and molecules in cells, producing ions and free radicals that can break DNA strands or alter bases; damaged cells may die, mutate or become cancerous if the damage is not repaired;',1,1);
INSERT INTO rubric_criterion VALUES(14756,'physics12a2-rdb-8',NULL,1,'rapidly dividing cells (such as tumour cells) are more sensitive;',1,1);
INSERT INTO rubric_criterion VALUES(14757,'physics12a2-rdb-8',NULL,2,'radiotherapy aims a high dose at the tumour from several directions to kill cancer cells while limiting the dose to surrounding healthy tissue.',1,1);
INSERT INTO rubric_criterion VALUES(14764,'physics12a2-cpd-6',NULL,0,'(a) Q = I t = 0.25 × 120 = 30 C;',1,1);
INSERT INTO rubric_criterion VALUES(14765,'physics12a2-cpd-6',NULL,1,'(b) n = 30 / 1.60 × 10⁻¹⁹ ≈ 1.9 × 10²⁰ electrons;',1,1);
INSERT INTO rubric_criterion VALUES(14766,'physics12a2-cpd-6',NULL,2,'(c) W = qV = 30 × 6.0 = 180 J.',1,1);
INSERT INTO rubric_criterion VALUES(14767,'physics12a2-cpd-7',NULL,0,'Current is the rate of flow of charge past a point (I = Q/t), measured in amperes and measured in series with a component;',1,1);
INSERT INTO rubric_criterion VALUES(14768,'physics12a2-cpd-7',NULL,1,'potential difference is the energy transferred per unit charge between two points (V = W/q), measured in volts and measured in parallel across a component;',1,1);
INSERT INTO rubric_criterion VALUES(14769,'physics12a2-cpd-7',NULL,2,'current is a flow through the component while potential difference is across it (the supply provides the energy, charge carriers do not get used up).',1,1);
INSERT INTO rubric_criterion VALUES(14770,'physics12a2-cpd-8',NULL,0,'(a) I = Q/t = 90 / 300 = 0.30 A;',1,1);
INSERT INTO rubric_criterion VALUES(14771,'physics12a2-cpd-8',NULL,1,'(b) V = W/q = 540 / 90 = 6.0 V;',1,1);
INSERT INTO rubric_criterion VALUES(14772,'physics12a2-cpd-8',NULL,2,'(c) P = VI = 6.0 × 0.30 = 1.8 W (also 540 / 300 = 1.8 W).',1,1);
INSERT INTO rubric_criterion VALUES(14773,'vce-physics12-cp-c1',NULL,0,'360 C;',1,1);
INSERT INTO rubric_criterion VALUES(14774,'vce-physics12-cp-c1',NULL,1,'about 2.3 × 10²¹ electrons',1,1);
INSERT INTO rubric_criterion VALUES(14780,'physics12a2-rol-6',NULL,0,'(a) length ×3 gives ×3; half the diameter gives one quarter the area, so resistance ×4;',1,1);
INSERT INTO rubric_criterion VALUES(14781,'physics12a2-rol-6',NULL,1,'R = 6.0 × 3 × 4 = 72 Ω;',1,1);
INSERT INTO rubric_criterion VALUES(14782,'physics12a2-rol-6',NULL,2,'(b) R is directly proportional to length and inversely proportional to cross-sectional area (area proportional to diameter squared) for the same material.',1,1);
INSERT INTO rubric_criterion VALUES(14783,'physics12a2-rol-7',NULL,0,'(a) R = V/I gives 10 Ω, 11 Ω (11.1), 12.5 Ω; (b) the component is non-ohmic because its resistance is not constant (I is not proportional to V;',1,1);
INSERT INTO rubric_criterion VALUES(14784,'physics12a2-rol-7',NULL,1,'the I–V graph curves rather than being a straight line through the origin);',1,1);
INSERT INTO rubric_criterion VALUES(14785,'physics12a2-rol-7',NULL,2,'resistance increases as current increases, consistent with heating.',1,1);
INSERT INTO rubric_criterion VALUES(14786,'physics12a2-rol-8',NULL,0,'(a) R = V/I = 230 / 8.0 ≈ 29 Ω (28.75);',1,1);
INSERT INTO rubric_criterion VALUES(14787,'physics12a2-rol-8',NULL,1,'(b) P = VI = 230 × 8.0 = 1840 W;',1,1);
INSERT INTO rubric_criterion VALUES(14788,'physics12a2-rol-8',NULL,2,'(c) E = Pt = 1840 × 1800 ≈ 3.3 × 10⁶ J.',1,1);
INSERT INTO rubric_criterion VALUES(14795,'physics12a2-spc-6',NULL,0,'(a) parallel part: 1/R = 1/6 + 1/3 = 1/2, so 2.0 Ω; total = 4.0 + 2.0 = 6.0 Ω;',1,1);
INSERT INTO rubric_criterion VALUES(14796,'physics12a2-spc-6',NULL,1,'(b) I = 12 / 6.0 = 2.0 A;',1,1);
INSERT INTO rubric_criterion VALUES(14797,'physics12a2-spc-6',NULL,2,'(c) V = 2.0 × 4.0 = 8.0 V;',1,1);
INSERT INTO rubric_criterion VALUES(14798,'physics12a2-spc-6',NULL,3,'(d) pd across the parallel part = 12 − 8.0 = 4.0 V, so I = 4.0 / 6.0 ≈ 0.67 A.',1,1);
INSERT INTO rubric_criterion VALUES(14799,'physics12a2-spc-7',NULL,0,'Total R = 300 Ω; I = 9.0 / 300 = 0.030 A (30 mA);',1,1);
INSERT INTO rubric_criterion VALUES(14800,'physics12a2-spc-7',NULL,1,'V₁ = 0.030 × 100 = 3.0 V; V₂ = 0.030 × 200 = 6.0 V;',1,1);
INSERT INTO rubric_criterion VALUES(14801,'physics12a2-spc-7',NULL,2,'the voltages add to 9.0 V.',1,1);
INSERT INTO rubric_criterion VALUES(14802,'physics12a2-spc-8',NULL,0,'In parallel each appliance is connected across the full supply voltage so it operates at its rated voltage;',1,1);
INSERT INTO rubric_criterion VALUES(14803,'physics12a2-spc-8',NULL,1,'each appliance can be switched on or off independently without affecting the others;',1,1);
INSERT INTO rubric_criterion VALUES(14804,'physics12a2-spc-8',NULL,2,'if one appliance fails (open circuit) the others continue to work, whereas in series the voltage would be shared and one failure would stop all of them.',1,1);
INSERT INTO rubric_criterion VALUES(14805,'vce-physics12-sp-c1',NULL,0,'2.0 A;',1,1);
INSERT INTO rubric_criterion VALUES(14806,'vce-physics12-sp-c1',NULL,1,'about 1.3 A',2,1);
INSERT INTO rubric_criterion VALUES(14812,'physics12a3-epe-6',NULL,0,'(a) R total = 4.0 + 8.0 = 12 Ω, so I = V/R = 12/12 = 1.0 A;',1,1);
INSERT INTO rubric_criterion VALUES(14813,'physics12a3-epe-6',NULL,1,'(b) V = IR = 1.0 × 8.0 = 8.0 V;',1,1);
INSERT INTO rubric_criterion VALUES(14814,'physics12a3-epe-6',NULL,2,'(c) P = VI = 8.0 × 1.0 = 8.0 W (equivalently I²R = 1.0² × 8.0 = 8.0 W).',1,1);
INSERT INTO rubric_criterion VALUES(14815,'physics12a3-epe-7',NULL,0,'(a) I₁ = 240/60 = 4.0 A and I₂ = 240/120 = 2.0 A (same voltage across each branch);',1,1);
INSERT INTO rubric_criterion VALUES(14816,'physics12a3-epe-7',NULL,1,'(b) total current = 4.0 + 2.0 = 6.0 A (equivalent resistance 40 Ω, 240/40 = 6.0 A);',1,1);
INSERT INTO rubric_criterion VALUES(14817,'physics12a3-epe-7',NULL,2,'(c) P = VI = 240 × 6.0 = 1440 W (960 W + 480 W).',2,1);
INSERT INTO rubric_criterion VALUES(14818,'physics12a3-epe-8',NULL,0,'(a) Efficiency = useful output / input = 350/500 = 0.70 = 70%;',1,1);
INSERT INTO rubric_criterion VALUES(14819,'physics12a3-epe-8',NULL,1,'(b) waste power = 500 − 350 = 150 W;',1,1);
INSERT INTO rubric_criterion VALUES(14820,'physics12a3-epe-8',NULL,2,'energy = Pt = 150 × (10 × 60) = 150 × 600 = 9.0 × 10⁴ J.',1,1);
INSERT INTO rubric_criterion VALUES(14827,'physics12a3-es-6',NULL,0,'The fuse contains a thin wire that heats (I²R) and melts when the current exceeds its rating, breaking the circuit;',1,1);
INSERT INTO rubric_criterion VALUES(14828,'physics12a3-es-6',NULL,1,'this stops excessive current that could overheat wiring or start a fire;',1,1);
INSERT INTO rubric_criterion VALUES(14829,'physics12a3-es-6',NULL,2,'it is placed in the live wire so that when it blows the appliance is disconnected from the live (high potential) side, so the appliance does not remain at a dangerous potential.',1,1);
INSERT INTO rubric_criterion VALUES(14830,'physics12a3-es-7',NULL,0,'(a) Earthed: a large current flows through the low-resistance earth wire, which blows the fuse or trips the circuit breaker/RCD, disconnecting the supply so the casing is no longer live;',1,1);
INSERT INTO rubric_criterion VALUES(14831,'physics12a3-es-7',NULL,1,'(b) not earthed: the casing becomes live at about 230 V but no large current flows, so the fuse does not blow;',1,1);
INSERT INTO rubric_criterion VALUES(14832,'physics12a3-es-7',NULL,2,'a person touching the casing then provides a path to earth and receives a (possibly lethal) shock.',1,1);
INSERT INTO rubric_criterion VALUES(14833,'physics12a3-es-8',NULL,0,'(a) I = V/R = 230/1500 = 0.15 A (153 mA);',1,1);
INSERT INTO rubric_criterion VALUES(14834,'physics12a3-es-8',NULL,1,'(b) this leakage current (about 150 mA) is well above 30 mA, so the RCD detects the live-neutral imbalance and cuts the supply within milliseconds, before serious harm;',1,1);
INSERT INTO rubric_criterion VALUES(14835,'physics12a3-es-8',NULL,2,'the 15 A breaker only trips on current above 15 A, and 0.15 A is far below this, so it would not trip even though 0.15 A is dangerous to a person.',1,1);
INSERT INTO rubric_criterion VALUES(14842,'physics12a3-mg-6',NULL,0,'(a) Section 1: a = 12/4.0 = +3.0 m s⁻²; section 2: a = 0;',1,1);
INSERT INTO rubric_criterion VALUES(14843,'physics12a3-mg-6',NULL,1,'section 3: a = (0 − 12)/4.0 = −3.0 m s⁻²;',1,1);
INSERT INTO rubric_criterion VALUES(14844,'physics12a3-mg-6',NULL,2,'(b) displacement = area = ½ × 4.0 × 12 + 6.0 × 12 + ½ × 4.0 × 12 = 24 + 72 + 24 = 120 m;',1,1);
INSERT INTO rubric_criterion VALUES(14845,'physics12a3-mg-6',NULL,3,'average velocity = 120/14 = 8.6 m s⁻¹ (8.57).',1,1);
INSERT INTO rubric_criterion VALUES(14846,'physics12a3-mg-7',NULL,0,'(a) 0–8 s: v = 40/8.0 = +5.0 m s⁻¹; 8–12 s: v = 0;',1,1);
INSERT INTO rubric_criterion VALUES(14847,'physics12a3-mg-7',NULL,1,'12–20 s: v = −40/8.0 = −5.0 m s⁻¹; (b) displacement = 0 m (returns to the start);',1,1);
INSERT INTO rubric_criterion VALUES(14848,'physics12a3-mg-7',NULL,2,'distance = 40 + 40 = 80 m.',1,1);
INSERT INTO rubric_criterion VALUES(14849,'physics12a3-mg-8',NULL,0,'The graph is a single straight line with a negative gradient (−9.8 m s⁻²) starting at a positive initial velocity; gradient = acceleration, which is constant and equal to −g throughout (including at the top);',1,1);
INSERT INTO rubric_criterion VALUES(14850,'physics12a3-mg-8',NULL,1,'the intercept on the time axis is the instant at the top of the flight where v = 0;',1,1);
INSERT INTO rubric_criterion VALUES(14851,'physics12a3-mg-8',NULL,2,'the area above the axis (upward displacement) equals the area below (downward displacement) because the ball returns to its launch height, so net displacement is zero.',1,1);
INSERT INTO rubric_criterion VALUES(14858,'physics12a3-eca-6',NULL,0,'(a) s = ut + ½at²: 400 = 12 × 20 + ½ × a × 20², so 400 = 240 + 200a and a = 0.80 m s⁻²;',1,1);
INSERT INTO rubric_criterion VALUES(14859,'physics12a3-eca-6',NULL,1,'(b) v = u + at = 12 + 0.80 × 20 = 28 m s⁻¹ (check: average speed ½(12 + 28) = 20 m s⁻¹, 20 × 20 = 400 m).',2,1);
INSERT INTO rubric_criterion VALUES(14860,'physics12a3-eca-7',NULL,0,'Reaction distance = 20 × 0.60 = 12 m;',1,1);
INSERT INTO rubric_criterion VALUES(14861,'physics12a3-eca-7',NULL,1,'braking distance from v² = u² + 2as: 0 = 400 − 2(8.0)s, so s = 400/16 = 25 m;',1,1);
INSERT INTO rubric_criterion VALUES(14862,'physics12a3-eca-7',NULL,2,'total stopping distance = 12 + 25 = 37 m.',2,1);
INSERT INTO rubric_criterion VALUES(14863,'physics12a3-eca-8',NULL,0,'(a) s = ½gt² = ½ × 9.8 × 3.0² = 44.1 m ≈ 44 m;',1,1);
INSERT INTO rubric_criterion VALUES(14864,'physics12a3-eca-8',NULL,1,'(b) v = gt = 9.8 × 3.0 = 29.4 m s⁻¹ ≈ 29 m s⁻¹ (check: v² = 2gs = 2 × 9.8 × 44.1 = 864, v = 29.4).',2,1);
INSERT INTO rubric_criterion VALUES(14865,'vce-physics12-ca-c1',NULL,0,'82.5 m',2,1);
INSERT INTO rubric_criterion VALUES(14871,'physics12a3-nlm-6',NULL,0,'(a) Treat as one system: a = F/m total = 10/(2.0 + 3.0) = 2.0 m s⁻²;',1,1);
INSERT INTO rubric_criterion VALUES(14872,'physics12a3-nlm-6',NULL,1,'(b) the net force on the 3.0 kg block is the contact force: F = ma = 3.0 × 2.0 = 6.0 N.',2,1);
INSERT INTO rubric_criterion VALUES(14873,'physics12a3-nlm-7',NULL,0,'(a) F_net = 3000 − 1000 = 2000 N, a = 2000/1200 = 1.67 m s⁻²;',1,1);
INSERT INTO rubric_criterion VALUES(14874,'physics12a3-nlm-7',NULL,1,'(b) v = u + at = 0 + 1.67 × 10 = 16.7 m s⁻¹;',1,1);
INSERT INTO rubric_criterion VALUES(14875,'physics12a3-nlm-7',NULL,2,'(c) s = ½at² = ½ × 1.67 × 10² = 83 m.',2,1);
INSERT INTO rubric_criterion VALUES(14876,'physics12a3-nlm-8',NULL,0,'Newton''s first law: with no net force acting on it, the passenger keeps moving at the car''s original velocity while the car slows down, so appears to lurch forward;',1,1);
INSERT INTO rubric_criterion VALUES(14877,'physics12a3-nlm-8',NULL,1,'a seatbelt exerts a backward force on the passenger, so the passenger decelerates with the car (F = ma) and does not hit the dashboard or windscreen;',1,1);
INSERT INTO rubric_criterion VALUES(14878,'physics12a3-nlm-8',NULL,2,'the belt also spreads the force over a larger area/time, reducing injury.',1,1);
INSERT INTO rubric_criterion VALUES(14885,'physics12a3-mi-6',NULL,0,'(a) Taking the final direction as positive: Δp = 0.16 × (40 − (−30)) = 0.16 × 70 = 11.2 N s;',1,1);
INSERT INTO rubric_criterion VALUES(14886,'physics12a3-mi-6',NULL,1,'(b) F = Δp/Δt = 11.2/(5.0 × 10⁻³) = 2.2 × 10³ N (2240 N).',2,1);
INSERT INTO rubric_criterion VALUES(14887,'physics12a3-mi-7',NULL,0,'(a) 1000 × 15 = 3000 v, so v = 5.0 m s⁻¹; (b) KE before = ½ × 1000 × 15² = 1.125 × 10⁵ J;',1,1);
INSERT INTO rubric_criterion VALUES(14888,'physics12a3-mi-7',NULL,1,'KE after = ½ × 3000 × 5.0² = 3.75 × 10⁴ J;',1,1);
INSERT INTO rubric_criterion VALUES(14889,'physics12a3-mi-7',NULL,2,'loss = 7.5 × 10⁴ J;',1,1);
INSERT INTO rubric_criterion VALUES(14890,'physics12a3-mi-7',NULL,3,'(c) inelastic, because kinetic energy is not conserved (momentum is conserved).',1,1);
INSERT INTO rubric_criterion VALUES(14891,'physics12a3-mi-8',NULL,0,'(a) Total momentum is zero: 60v + 40 × 3.0 = 0, so v = −2.0 m s⁻¹ (2.0 m s⁻¹ in the opposite direction);',1,1);
INSERT INTO rubric_criterion VALUES(14892,'physics12a3-mi-8',NULL,1,'(b) KE = ½ × 40 × 3.0² + ½ × 60 × 2.0² = 180 + 120 = 300 J;',1,1);
INSERT INTO rubric_criterion VALUES(14893,'physics12a3-mi-8',NULL,2,'this came from chemical energy stored in the skaters'' muscles (momentum is conserved but kinetic energy increases).',1,1);
INSERT INTO rubric_criterion VALUES(14894,'vce-physics12-mi-c1',NULL,0,'7.5 N s;',1,1);
INSERT INTO rubric_criterion VALUES(14895,'vce-physics12-mi-c1',NULL,1,'750 N',2,1);
INSERT INTO rubric_criterion VALUES(14901,'physics12a3-wep-6',NULL,0,'(a) E = ½kx² = ½ × 200 × 0.10² = 1.0 J;',1,1);
INSERT INTO rubric_criterion VALUES(14902,'physics12a3-wep-6',NULL,1,'(b) all the elastic energy becomes kinetic: ½mv² = 1.0, so v = √(2 × 1.0/0.050) = √40 = 6.3 m s⁻¹.',2,1);
INSERT INTO rubric_criterion VALUES(14903,'physics12a3-wep-7',NULL,0,'(a) Loss of gravitational PE = mgh = 2.0 × 9.8 × 3.0 = 58.8 J;',1,1);
INSERT INTO rubric_criterion VALUES(14904,'physics12a3-wep-7',NULL,1,'KE at bottom = ½ × 2.0 × 6.0² = 36 J;',1,1);
INSERT INTO rubric_criterion VALUES(14905,'physics12a3-wep-7',NULL,2,'energy lost = 58.8 − 36 = 22.8 J ≈ 23 J;',1,1);
INSERT INTO rubric_criterion VALUES(14906,'physics12a3-wep-7',NULL,3,'(b) work done by friction = Fs, so F = 22.8/5.0 = 4.6 N.',1,1);
INSERT INTO rubric_criterion VALUES(14907,'physics12a3-wep-8',NULL,0,'(a) ΔE = mgh = 70 × 9.8 × 12 = 8232 J ≈ 8.2 × 10³ J;',1,1);
INSERT INTO rubric_criterion VALUES(14908,'physics12a3-wep-8',NULL,1,'(b) P = E/t = 8232/30 = 274 W ≈ 2.7 × 10² W;',1,1);
INSERT INTO rubric_criterion VALUES(14909,'physics12a3-wep-8',NULL,2,'(c) chemical energy = useful energy/efficiency = 8232/0.25 = 32 928 J ≈ 3.3 × 10⁴ J.',2,1);
INSERT INTO rubric_criterion VALUES(14916,'physics12a3-te-6',NULL,0,'Take torques about A: B × 4.0 = (30 × 9.8) × 1.0 + (20 × 9.8) × 2.0 = 294 + 392 = 686 N m, so B = 171.5 N ≈ 1.7 × 10² N;',1,1);
INSERT INTO rubric_criterion VALUES(14917,'physics12a3-te-6',NULL,1,'vertical forces balance: A + B = (30 + 20) × 9.8 = 490 N, so A = 490 − 171.5 = 318.5 N ≈ 3.2 × 10² N.',3,1);
INSERT INTO rubric_criterion VALUES(14918,'physics12a3-te-7',NULL,0,'(a) Torques about the hinge: T × 2.0 = (10 × 9.8) × 1.0 + (4.0 × 9.8) × 2.0 = 98 + 78.4 = 176.4, so T = 88.2 N ≈ 88 N;',1,1);
INSERT INTO rubric_criterion VALUES(14919,'physics12a3-te-7',NULL,1,'(b) vertical forces: hinge force + T = total weight = 14 × 9.8 = 137.2 N, so hinge force = 137.2 − 88.2 = 49 N upward.',3,1);
INSERT INTO rubric_criterion VALUES(14920,'physics12a3-te-8',NULL,0,'While tilting, the weight acts at the centre of mass and produces a torque about the pivot edge; the cupboard returns to its original position while the vertical line through the centre of mass still falls inside the base (restoring torque);',1,1);
INSERT INTO rubric_criterion VALUES(14921,'physics12a3-te-8',NULL,1,'it topples when this line passes beyond the pivot edge;',1,1);
INSERT INTO rubric_criterion VALUES(14922,'physics12a3-te-8',NULL,2,'a tall, narrow cupboard has a high centre of mass and a narrow base, so this happens at a smaller tilt angle than for a short, wide one.',1,1);
INSERT INTO rubric_criterion VALUES(14924,'methods-challenge-1',NULL,0,'\(k = e\);',1,1);
INSERT INTO rubric_criterion VALUES(14925,'methods-challenge-1',NULL,1,'point \((1, e)\)',1,1);
INSERT INTO rubric_criterion VALUES(14927,'methods-challenge-3',NULL,0,'\(x = 0\) or \(x = \log_e 2\)',2,1);
INSERT INTO rubric_criterion VALUES(14930,'methods-challenge-6',NULL,0,'\(k = 1\);',1,1);
INSERT INTO rubric_criterion VALUES(14931,'methods-challenge-6',NULL,1,'\(\text{E}(X) = e - 1\)',1,1);
INSERT INTO rubric_criterion VALUES(14932,'methods-challenge-7',NULL,0,'\(c = \dfrac{a}{\sqrt{3}}\)',2,1);
INSERT INTO rubric_criterion VALUES(14934,'methods-challenge-9',NULL,0,'29',3,1);
INSERT INTO rubric_criterion VALUES(14939,'general-challenge-4',NULL,0,'About 20.9 years (251 withdrawals, the last smaller)',1,1);
INSERT INTO rubric_criterion VALUES(14940,'general-challenge-5',NULL,0,'$1125.89 (flat rate $10 000; reducing balance $8874.11)',1,1);
INSERT INTO rubric_criterion VALUES(14944,'general-challenge-9',NULL,0,'r measures overall linear association;',1,1);
INSERT INTO rubric_criterion VALUES(14945,'general-challenge-9',NULL,1,'one point can still lie far from the line (an outlier) while the rest fit closely.',1,1);
INSERT INTO rubric_criterion VALUES(14947,'specialist-challenge-1',NULL,0,'\(z = 0\), \(z = 1\), \(z = -\frac{1}{2} \pm \frac{\sqrt{3}}{2}i\)',3,1);
INSERT INTO rubric_criterion VALUES(14950,'specialist-challenge-4',NULL,0,'Skew',2,1);
INSERT INTO rubric_criterion VALUES(14952,'specialist-challenge-6',NULL,0,'\(y = \dfrac{1}{1 - x}\), defined for \(x < 1\)',3,1);
INSERT INTO rubric_criterion VALUES(14955,'specialist-challenge-9',NULL,0,'Contrapositive: if \(n\) is even, \(n = 2k\), then \(n^2 + 2n = 4k^2 + 4k = 2(2k^2 + 2k)\), which is even.',1,1);
INSERT INTO rubric_criterion VALUES(14956,'specialist-challenge-9',NULL,1,'So if \(n^2 + 2n\) is odd, \(n\) must be odd.',2,1);
INSERT INTO rubric_criterion VALUES(14958,'chem-challenge-1',NULL,0,'Calibration factor 800 J/°C;',1,1);
INSERT INTO rubric_criterion VALUES(14959,'chem-challenge-1',NULL,1,'energy released 2240 J (2.24 kJ)',1,1);
INSERT INTO rubric_criterion VALUES(14962,'chem-challenge-4',NULL,0,'0.318 g',1,1);
INSERT INTO rubric_criterion VALUES(14966,'chem-challenge-8',NULL,0,'Atom economy is theoretical: all reactant atoms could end up in the product.',1,1);
INSERT INTO rubric_criterion VALUES(14967,'chem-challenge-8',NULL,1,'The 40% yield means most reactant is not converted in practice, so material and energy are wasted unless it is recycled.',1,1);
INSERT INTO rubric_criterion VALUES(14969,'chem-challenge-10',NULL,0,'The enzyme is denatured: heat disrupts the hydrogen bonds, ionic interactions and dispersion forces of its tertiary structure, changing the active site so the substrate no longer fits.',1,1);
INSERT INTO rubric_criterion VALUES(14970,'chem-challenge-10',NULL,1,'Peptide bonds (primary structure) are not broken, but the original shape is not restored.',2,1);
INSERT INTO rubric_criterion VALUES(14973,'physics-challenge-3',NULL,0,'About 15 m/s',2,1);
INSERT INTO rubric_criterion VALUES(14974,'physics-challenge-4',NULL,0,'About 6.3 m/s',2,1);
INSERT INTO rubric_criterion VALUES(14977,'physics-challenge-7',NULL,0,'About 1.7 × 10⁻¹⁰ m;',1,1);
INSERT INTO rubric_criterion VALUES(14978,'physics-challenge-7',NULL,1,'it is similar to the atomic spacing, so diffraction is noticeable',2,1);
INSERT INTO rubric_criterion VALUES(14980,'physics-challenge-9',NULL,0,'The falling magnet changes the flux through the copper, inducing eddy currents. By Lenz''s law their fields oppose the motion, slowing the magnet.',1,1);
INSERT INTO rubric_criterion VALUES(14981,'physics-challenge-9',NULL,1,'Gravitational potential energy becomes heat in the copper, not just kinetic energy.',1,1);
INSERT INTO rubric_criterion VALUES(14982,'physics-challenge-10',NULL,0,'About 3.1 × 10¹⁰ J;',1,1);
INSERT INTO rubric_criterion VALUES(14983,'physics-challenge-10',NULL,1,'g is not constant over this distance (it falls to g/4 at 2R)',2,1);
INSERT INTO rubric_criterion VALUES(14985,'vce-bio34-challenge-2',NULL,0,'STR regions are amplified by PCR and separated by size on a gel.',1,1);
INSERT INTO rubric_criterion VALUES(14986,'vce-bio34-challenge-2',NULL,1,'A child inherits one allele at each STR locus from each parent, so every band in the child not from the mother must match a band of the biological father.',1,1);
INSERT INTO rubric_criterion VALUES(14987,'vce-bio34-challenge-2',NULL,2,'One mismatch at several loci excludes him.',1,1);
INSERT INTO rubric_criterion VALUES(14994,'vce-bio34-challenge-9',NULL,0,'No effect: a silent mutation, because the genetic code is degenerate.',1,1);
INSERT INTO rubric_criterion VALUES(14995,'vce-bio34-challenge-9',NULL,1,'Small effect: a missense mutation swaps one amino acid for a similar one or one away from the active site.',1,1);
INSERT INTO rubric_criterion VALUES(14996,'vce-bio34-challenge-9',NULL,2,'Large effect: a nonsense mutation creates an early stop codon, or a missense change alters the active site.',1,1);
INSERT INTO rubric_criterion VALUES(14997,'vce-bio34-challenge-10',NULL,0,'IV: temperature (for example 10, 20, 30, 40, 50 °C, using water baths). DV: rate of O₂ production (volume of gas or foam height per minute).',1,1);
INSERT INTO rubric_criterion VALUES(14998,'vce-bio34-challenge-10',NULL,1,'Controlled: catalase concentration and volume, H₂O₂ concentration and volume, pH.',1,1);
INSERT INTO rubric_criterion VALUES(14999,'vce-bio34-challenge-10',NULL,2,'Repeat each trial at least three times.',1,1);
INSERT INTO rubric_criterion VALUES(15000,'vce-psych34-challenge-1',NULL,0,'Precipitation: a dog (NS) is paired with a frightening bite (UCS → fear as UCR), so dogs become a CS producing fear (CR).',1,1);
INSERT INTO rubric_criterion VALUES(15001,'vce-psych34-challenge-1',NULL,1,'Perpetuation: avoiding dogs removes the anxiety, which negatively reinforces avoidance, so the fear is never extinguished.',1,1);
INSERT INTO rubric_criterion VALUES(15005,'vce-psych34-challenge-5',NULL,0,'Affective: more irritability, mood swings and stronger negative emotional reactions; poorer emotional regulation.',1,1);
INSERT INTO rubric_criterion VALUES(15006,'vce-psych34-challenge-5',NULL,1,'Cognitive: slower reaction time, poorer attention, concentration and decision-making.',1,1);
INSERT INTO rubric_criterion VALUES(15009,'vce-psych34-challenge-8',NULL,0,'A stressor is the event or situation; stress is the psychological and physiological response.',1,1);
INSERT INTO rubric_criterion VALUES(15010,'vce-psych34-challenge-8',NULL,1,'In the transactional model, people appraise the stressor differently (primary appraisal) and judge their resources differently (secondary appraisal), so their stress responses differ.',1,1);
INSERT INTO rubric_criterion VALUES(15014,'vce-chem12-challenge-2',NULL,0,'MgO',2,1);
INSERT INTO rubric_criterion VALUES(15016,'vce-chem12-challenge-4',NULL,0,'1.43 g',1,1);
INSERT INTO rubric_criterion VALUES(15017,'vce-chem12-challenge-5',NULL,0,'pH = 2.00',2,1);
INSERT INTO rubric_criterion VALUES(15022,'vce-chem12-challenge-10',NULL,0,'Both have similar dispersion forces because their molar masses are similar, but butan-1-ol also forms hydrogen bonds between its O–H groups, which need more energy to overcome.',2,1);
INSERT INTO rubric_criterion VALUES(15023,'vce-bio12-challenge-1',NULL,0,'10 µm: 600 ÷ 1000 = 0.6 µm⁻¹. 20 µm: 2400 ÷ 8000 = 0.3 µm⁻¹.',1,1);
INSERT INTO rubric_criterion VALUES(15024,'vce-bio12-challenge-1',NULL,1,'The larger cell has half the surface per unit of volume, so it exchanges materials (O₂, nutrients, wastes) relatively more slowly.',1,1);
INSERT INTO rubric_criterion VALUES(15026,'vce-bio12-challenge-3',NULL,0,'Mitosis: one division, two daughter cells, diploid, genetically identical, for growth and repair.',1,1);
INSERT INTO rubric_criterion VALUES(15027,'vce-bio12-challenge-3',NULL,1,'Meiosis: two divisions, four cells, haploid, genetically different (crossing over and independent assortment), producing gametes.',2,1);
INSERT INTO rubric_criterion VALUES(15030,'vce-bio12-challenge-6',NULL,0,'Nervous: electrical impulses along neurons and neurotransmitters at synapses; very fast, short-lived and precisely targeted.',1,1);
INSERT INTO rubric_criterion VALUES(15031,'vce-bio12-challenge-6',NULL,1,'Endocrine: hormones carried in the blood to cells with receptors; slower, longer-lasting and often widespread.',1,1);
INSERT INTO rubric_criterion VALUES(15035,'vce-bio12-challenge-10',NULL,0,'Negative feedback reverses a change to restore a set point (for example, insulin lowering high blood glucose).',1,1);
INSERT INTO rubric_criterion VALUES(15036,'vce-bio12-challenge-10',NULL,1,'Positive feedback amplifies a change (for example, oxytocin increasing contractions in childbirth).',1,1);
INSERT INTO rubric_criterion VALUES(15037,'vce-psych12-challenge-1',NULL,0,'Pre-operational (about 2–7): thinking is egocentric and focused on appearance, so a child thinks a tall thin glass holds more juice.',1,1);
INSERT INTO rubric_criterion VALUES(15038,'vce-psych12-challenge-1',NULL,1,'Concrete operational (about 7–11): children can conserve, understanding that quantity stays the same, and can think logically about concrete situations.',2,1);
INSERT INTO rubric_criterion VALUES(15041,'vce-psych12-challenge-4',NULL,0,'The conflict between the belief and the behaviour causes discomfort. Because the behaviour cannot be undone, the student may change the belief (for example, ''everyone cheats;',1,1);
INSERT INTO rubric_criterion VALUES(15042,'vce-psych12-challenge-4',NULL,1,'it isn''t a big deal'') to reduce the dissonance.',1,1);
INSERT INTO rubric_criterion VALUES(15046,'vce-psych12-challenge-8',NULL,0,'Biological: the prefrontal cortex is still developing, while reward systems are highly active. Psychological: optimism bias (''it won''t happen to me'') and sensation-seeking.',1,1);
INSERT INTO rubric_criterion VALUES(15047,'vce-psych12-challenge-8',NULL,1,'Social: peer pressure and wanting approval from friends in the car.',1,1);
INSERT INTO rubric_criterion VALUES(15051,'vce-methods12-challenge-2',NULL,0,'x = 0 or x = 2',2,1);
INSERT INTO rubric_criterion VALUES(15056,'vce-methods12-challenge-7',NULL,0,'P(3, 2)',2,1);
INSERT INTO rubric_criterion VALUES(15057,'vce-methods12-challenge-8',NULL,0,'a = 2, b = −1',3,1);
INSERT INTO rubric_criterion VALUES(15059,'vce-methods12-challenge-10',NULL,0,'t = 1 s at x = 4 m; t = 3 s at x = 0 m',1,1);
INSERT INTO rubric_criterion VALUES(15066,'vce-physics12-challenge-7',NULL,0,'15 m/s;',1,1);
INSERT INTO rubric_criterion VALUES(15067,'vce-physics12-challenge-7',NULL,1,'37.5 m',1,1);
INSERT INTO rubric_criterion VALUES(15069,'vce-physics12-challenge-9',NULL,0,'About 6.5 × 10³ J',2,1);
INSERT INTO rubric_criterion VALUES(15071,'gcse-bio-challenge-1',NULL,0,'30 µm',1,1);
INSERT INTO rubric_criterion VALUES(15076,'gcse-bio-challenge-6',NULL,0,'Water enters both cells by osmosis. The plant cell swells until its membrane presses against the strong cellulose cell wall, which stops it bursting (it becomes turgid).',1,1);
INSERT INTO rubric_criterion VALUES(15077,'gcse-bio-challenge-6',NULL,1,'The animal cell has no cell wall, so it swells and bursts.',1,1);
INSERT INTO rubric_criterion VALUES(15080,'gcse-bio-challenge-9',NULL,0,'Another factor, such as carbon dioxide concentration or temperature, becomes the limiting factor, so extra light makes no difference to the rate.',2,1);
INSERT INTO rubric_criterion VALUES(15081,'gcse-bio-challenge-10',NULL,0,'Random mutations made some bacteria resistant. Antibiotics killed non-resistant bacteria, so resistant ones survived, reproduced and passed on the resistance allele.',1,1);
INSERT INTO rubric_criterion VALUES(15082,'gcse-bio-challenge-10',NULL,1,'With repeated antibiotic use, resistant strains such as MRSA became common.',1,1);
INSERT INTO rubric_criterion VALUES(15169,'vce-chinese-sl34-gc1',NULL,0,'Assessed as part of the whole conversation: 我家有四口人：爸爸、妈妈、哥哥和我。爸爸是工程师，妈妈是护士。我哥哥今年二十岁，在墨尔本大学学医。周末我们一家人常常一起去海边散步，有时候也一起做饭。',0,1);
INSERT INTO rubric_criterion VALUES(15170,'vce-chinese-sl34-gc2',NULL,0,'Assessed as part of the whole conversation: 我跟家人的关系很好。我最喜欢跟妈妈聊天，因为她很会听我说话。我跟哥哥小时候常常吵架，可是现在他上大学了，我们反而更亲近了。他常常帮我复习数学。',0,1);
INSERT INTO rubric_criterion VALUES(15171,'vce-chinese-sl34-gc3',NULL,0,'Assessed as part of the whole conversation: 我最好的朋友叫莎拉，我们从七年级就认识了。她很幽默，也很热心，每次我不开心的时候，她都会想办法让我笑。我们都喜欢打网球，所以每个星期六下午一起去打球。',0,1);
INSERT INTO rubric_criterion VALUES(15172,'vce-chinese-sl34-gc4',NULL,0,'Assessed as part of the whole conversation: 我的爱好是画画和听音乐。我从小就喜欢画画，现在我每个星期都会画一两幅画。画画让我觉得很放松，特别是学习压力大的时候。我也喜欢听流行音乐，最近在听一些中文歌。',0,1);
INSERT INTO rubric_criterion VALUES(15173,'vce-chinese-sl34-gc5',NULL,0,'Assessed as part of the whole conversation: 周末我一般先睡个懒觉，然后去超市打工。星期六下午我常常跟朋友一起去打网球。星期天我会在家复习功课，晚上跟家人一起吃饭、看电视。',0,1);
INSERT INTO rubric_criterion VALUES(15174,'vce-chinese-sl34-gc6',NULL,0,'Assessed as part of the whole conversation: 我很喜欢运动，特别是游泳和篮球。我每个星期去游泳两次，每次游一个小时。我觉得运动不但对身体好，而且可以减轻学习压力。',0,1);
INSERT INTO rubric_criterion VALUES(15175,'vce-chinese-sl34-gc7',NULL,0,'Assessed as part of the whole conversation: 我最喜欢的节日是春节。每年春节，我们全家都会去奶奶家吃团圆饭，一起包饺子。长辈会给我们红包，红包里有压岁钱。我们还会去唐人街看舞狮表演，非常热闹。',0,1);
INSERT INTO rubric_criterion VALUES(15176,'vce-chinese-sl34-gc8',NULL,0,'Assessed as part of the whole conversation: 前年夏天，我跟父母去了上海和北京。在北京，我们爬了长城，我觉得长城又长又壮观。在上海，我们晚上去外滩看夜景，非常漂亮。这次旅行让我更想把中文学好，因为我希望下次能自己跟当地人聊天。',0,1);
INSERT INTO rubric_criterion VALUES(15177,'vce-chinese-sl34-gc9',NULL,0,'Assessed as part of the whole conversation: 我每天大概花两个小时上网，主要是查资料和跟朋友聊天。上网的好处是很方便，可以很快找到需要的信息。坏处是很容易浪费时间，而且看屏幕太久对眼睛不好，所以我考试前会少用手机。',0,1);
INSERT INTO rubric_criterion VALUES(15178,'vce-chinese-sl34-gc10',NULL,0,'Assessed as part of the whole conversation: 我在一家面包店打过工，每个星期六工作六个小时。打工让我学会了怎么跟顾客沟通，也让我知道了挣钱不容易。现在我花钱的时候会更小心。',0,1);
INSERT INTO rubric_criterion VALUES(15179,'vce-chinese-sl34-gc-c1',NULL,0,'Assessed as part of the whole conversation: 我觉得两方面都有。一方面，网络让我们跟住在国外的亲戚联系更方便了。比如，我常常跟在北京的外婆视频聊天，她可以看到我长高了。另一方面，有时候我们一家人坐在一起吃饭，每个人却都在看手机，谁也不说话。所以我觉得，网络本身没有好坏，关键在于我们怎么用。我们家现在有一个规定：吃饭的时候不看手机。',0,1);
INSERT INTO rubric_criterion VALUES(15180,'vce-chinese-sl34-gc11',NULL,0,'Assessed as part of the whole conversation: 我今年学英语、数学、化学、心理学和中文。我最喜欢的科目是心理学，因为它让我了解人的想法和行为，而且老师上课很有意思。不过化学对我来说比较难，我需要多花时间复习。',0,1);
INSERT INTO rubric_criterion VALUES(15181,'vce-chinese-sl34-gc12',NULL,0,'Assessed as part of the whole conversation: 我学中文有几个原因。第一，我小时候去过中国，对中国文化很感兴趣。第二，我觉得中文很有用，将来可能对我的工作有帮助。第三，我有很多会说中文的朋友，我希望能跟他们用中文聊天。',0,1);
INSERT INTO rubric_criterion VALUES(15182,'vce-chinese-sl34-gc13',NULL,0,'Assessed as part of the whole conversation: 我觉得汉字最难，因为很多字看起来差不多，很容易写错。为了解决这个问题，我每天都会用手机应用程序练习写字，还会把容易写错的字写在小卡片上，有空的时候就复习。',0,1);
INSERT INTO rubric_criterion VALUES(15183,'vce-chinese-sl34-gc14',NULL,0,'Assessed as part of the whole conversation: 我的学校在墨尔本东区，是一所男女同校的公立学校，有一千多个学生。我们学校的设备很好，有很大的图书馆和体育馆。我最喜欢学校的音乐活动，每年都有很精彩的音乐会。',0,1);
INSERT INTO rubric_criterion VALUES(15184,'vce-chinese-sl34-gc15',NULL,0,'Assessed as part of the whole conversation: 十二年级的压力确实很大，因为作业多，考试也多。为了减轻压力，我每天都会做一些运动，比如跑步或者游泳。我也会安排好时间，早点儿睡觉。遇到困难的时候，我会跟家人或者老师聊一聊。',0,1);
INSERT INTO rubric_criterion VALUES(15185,'vce-chinese-sl34-gc16',NULL,0,'Assessed as part of the whole conversation: 我参加了学校的辩论队和篮球队。辩论让我变得更自信，说话也更有条理。打篮球让我学会了团队合作。虽然课外活动占用了一些时间，但是我觉得很值得。',0,1);
INSERT INTO rubric_criterion VALUES(15186,'vce-chinese-sl34-gc17',NULL,0,'Assessed as part of the whole conversation: 我毕业以后打算先休息一年，去打工和旅行，然后上大学学商业。我希望能在大学继续学中文，因为将来我想在跟中国有关系的公司工作。',0,1);
INSERT INTO rubric_criterion VALUES(15187,'vce-chinese-sl34-gc18',NULL,0,'Assessed as part of the whole conversation: 我将来想当老师，因为我很喜欢跟小孩子在一起，而且我觉得教育非常重要。我的妈妈也是老师，她常常告诉我，看到学生进步是最快乐的事情。',0,1);
INSERT INTO rubric_criterion VALUES(15188,'vce-chinese-sl34-gc19',NULL,0,'Assessed as part of the whole conversation: 我觉得学中文对我的将来有很大的帮助。现在中国和澳大利亚的关系很密切，很多公司需要会说中文的员工。另外，会说中文也能让我去中国旅行或者工作的时候更方便，更容易了解当地的文化。',0,1);
INSERT INTO rubric_criterion VALUES(15189,'vce-chinese-sl34-gc20',NULL,0,'Assessed as part of the whole conversation: 如果有机会去中国，我最想去西安看兵马俑，因为我对中国历史很感兴趣。我也想尝一尝各地的小吃，比如四川的火锅。最重要的是，我想多跟当地人用中文聊天，提高我的口语。',0,1);
INSERT INTO rubric_criterion VALUES(15190,'vce-chinese-sl34-gc-c2',NULL,0,'Assessed as part of the whole conversation: 如果我可以改变一件事，我会让学校早上晚一点儿开始上课。听说青少年需要更多睡眠，可是我们每天八点半就要上课，很多同学第一节课都很累，没办法集中精神。如果九点半上课，大家会更有精神，学习效果也会更好。当然，这样放学也会晚一点儿，可是我觉得这是值得的。',0,1);
INSERT INTO rubric_criterion VALUES(15191,'vce-english34-jane-eyre-q1',NULL,0,'John Reed says it to Jane in Chapter 1 at Gateshead, before he throws a book at her.',1,1);
INSERT INTO rubric_criterion VALUES(15192,'vce-english34-jane-eyre-q1',NULL,1,'It shows that the Reeds treat Jane as a dependent outsider with no rights in the household, and it introduces the novel''s concern with class, power and belonging.',2,1);
INSERT INTO rubric_criterion VALUES(15193,'vce-english34-jane-eyre-q2',NULL,0,'In Chapter 2, when she is locked in the red-room as punishment after fighting John Reed.',1,1);
INSERT INTO rubric_criterion VALUES(15194,'vce-english34-jane-eyre-q2',NULL,1,'It is the first time Jane names the injustice done to her, the beginning of her lifelong refusal to accept unfair treatment.',1,1);
INSERT INTO rubric_criterion VALUES(15195,'vce-english34-jane-eyre-q3',NULL,0,'In Chapter 12, restless at Thornfield, the narrator Jane argues that women need action, purpose and fields for their talents just as men do, and that it is narrow to confine them to domestic tasks.',2,1);
INSERT INTO rubric_criterion VALUES(15196,'vce-english34-jane-eyre-q4',NULL,0,'Jane says it to Rochester in the orchard in Chapter 23, when she thinks he is about to marry Blanche Ingram.',1,1);
INSERT INTO rubric_criterion VALUES(15197,'vce-english34-jane-eyre-q4',NULL,1,'She insists that, despite her low social position and plainness, she has as much soul and feeling as he does.',2,1);
INSERT INTO rubric_criterion VALUES(15198,'vce-english34-jane-eyre-q5',NULL,0,'In the same Chapter 23 scene with Rochester, Jane asserts that she is a free person who chooses for herself and cannot be caught or owned.',2,1);
INSERT INTO rubric_criterion VALUES(15199,'vce-english34-jane-eyre-q6',NULL,0,'In Chapter 27, after the wedding is stopped and she learns Rochester already has a wife, Bertha Mason. Rochester begs her to stay as his companion;',1,1);
INSERT INTO rubric_criterion VALUES(15200,'vce-english34-jane-eyre-q6',NULL,1,'Jane decides she must leave to keep her self-respect.',1,1);
INSERT INTO rubric_criterion VALUES(15201,'vce-english34-jane-eyre-q7',NULL,0,'St John Rivers, in Chapter 34, proposing that Jane marry him and go with him as a missionary to India. Jane refuses because he does not love her;',1,1);
INSERT INTO rubric_criterion VALUES(15202,'vce-english34-jane-eyre-q7',NULL,1,'she would have to suppress her nature for a marriage of duty.',1,1);
INSERT INTO rubric_criterion VALUES(15203,'vce-english34-jane-eyre-q8',NULL,0,'At the start of Chapter 38, the final chapter, when Jane tells the reader she has married Rochester at Ferndean.',2,1);
INSERT INTO rubric_criterion VALUES(15204,'vce-english34-jane-eyre-qc1',NULL,0,'In Chapter 23, freedom is a declaration: Jane claims an independent will and equality with Rochester while confessing her love.',1,1);
INSERT INTO rubric_criterion VALUES(15205,'vce-english34-jane-eyre-qc1',NULL,1,'In Chapter 27, freedom becomes a costly choice: she leaves the man she loves rather than become his mistress, because her self-respect and principles matter more than her happiness.',1,1);
INSERT INTO rubric_criterion VALUES(15206,'vce-english34-jane-eyre-qc1',NULL,2,'Freedom moves from words to sacrifice.',1,1);
INSERT INTO rubric_criterion VALUES(15211,'vce-english34-jane-eyre-i5',NULL,0,'Bertha is the hidden first wife confined in Thornfield''s attic. In plot terms she is the obstacle to Jane''s marriage;',1,1);
INSERT INTO rubric_criterion VALUES(15212,'vce-english34-jane-eyre-i5',NULL,1,'in Gothic terms she is the source of the mysterious laughter and the fire.',1,1);
INSERT INTO rubric_criterion VALUES(15213,'vce-english34-jane-eyre-i5',NULL,2,'Many readers see her as a dark double of Jane, showing what rage and confinement can do to a woman, and as a figure who exposes Rochester''s past and the way women could be shut away.',1,1);
INSERT INTO rubric_criterion VALUES(15214,'vce-english34-jane-eyre-i6',NULL,0,'Mr Brocklehurst preaches humility and self-denial to the girls while his own family live in luxury, so Lowood exposes religious hypocrisy and cruelty towards poor children.',1,1);
INSERT INTO rubric_criterion VALUES(15215,'vce-english34-jane-eyre-i6',NULL,1,'Helen Burns and Miss Temple show genuine faith and kindness instead, so Brontë separates true Christianity from the institution''s abuse of it.',2,1);
INSERT INTO rubric_criterion VALUES(15216,'vce-english34-jane-eyre-i7',NULL,0,'Rochester offers passionate love but tries to bind Jane in a marriage that would be illegal and immoral, which would make her his mistress.',1,1);
INSERT INTO rubric_criterion VALUES(15217,'vce-english34-jane-eyre-i7',NULL,1,'St John offers a lawful marriage of duty but without love, demanding that Jane suppress her feelings.',1,1);
INSERT INTO rubric_criterion VALUES(15218,'vce-english34-jane-eyre-i7',NULL,2,'Jane rejects both because each would require her to give up part of herself.',1,1);
INSERT INTO rubric_criterion VALUES(15219,'vce-english34-jane-eyre-ic1',NULL,0,'The reading: Bertha embodies the rage and passion Jane learns to contain.',1,1);
INSERT INTO rubric_criterion VALUES(15220,'vce-english34-jane-eyre-ic1',NULL,1,'Young Jane''s fury at John Reed and her imprisonment in the red-room echo Bertha''s confinement in the attic, and Bertha tearing Jane''s wedding veil acts out Jane''s unspoken fears about the marriage.',1,1);
INSERT INTO rubric_criterion VALUES(15221,'vce-english34-jane-eyre-ic1',NULL,2,'Limitation: it turns Bertha into a symbol of Jane''s mind and ignores her as a Creole woman from Jamaica whose own story is never told, a gap postcolonial critics and Jean Rhys''s Wide Sargasso Sea address.',2,1);
INSERT INTO rubric_criterion VALUES(15225,'vce-english34-jane-eyre-c4',NULL,0,'They create intimacy and make the reader a confidant, so we share Jane''s judgements.',1,1);
INSERT INTO rubric_criterion VALUES(15226,'vce-english34-jane-eyre-c4',NULL,1,'They also remind us that Jane is the author of her own story, which reinforces her control and independence.',1,1);
INSERT INTO rubric_criterion VALUES(15227,'vce-english34-jane-eyre-c5',NULL,0,'The red-room, where Mr Reed died, is cold, silent and blood-coloured.',1,1);
INSERT INTO rubric_criterion VALUES(15228,'vce-english34-jane-eyre-c5',NULL,1,'Jane''s imprisonment there represents her powerlessness and the injustice of her life at Gateshead, and its Gothic terror introduces the novel''s pattern of confinement that Jane must escape (later echoed by Bertha''s attic).',2,1);
INSERT INTO rubric_criterion VALUES(15229,'vce-english34-jane-eyre-cc1',NULL,0,'The older narrator can judge her younger self, combining intense feeling with reflection, so we trust her account.',1,1);
INSERT INTO rubric_criterion VALUES(15230,'vce-english34-jane-eyre-cc1',NULL,1,'Direct address makes the reader a confidant, drawing us into her moral choices and on to her side.',1,1);
INSERT INTO rubric_criterion VALUES(15231,'vce-english34-jane-eyre-cc1',NULL,2,'It also shows Jane controlling her own story, fitting the subtitle ‘An Autobiography’ and the novel''s concern with a woman''s voice.',1,1);
INSERT INTO rubric_criterion VALUES(15240,'vce-english34-jane-eyre-ec1',NULL,0,'Contention: Rochester''s injuries and Jane''s inheritance do rebalance power, but Brontë presents the ending as a union of equals that Jane has earned through her own choices, not a triumph over a weakened man.',1,1);
INSERT INTO rubric_criterion VALUES(15241,'vce-english34-jane-eyre-ec1',NULL,1,'(1) Rochester''s blindness and lost hand reverse their earlier inequality, so the topic has some force.',1,1);
INSERT INTO rubric_criterion VALUES(15242,'vce-english34-jane-eyre-ec1',NULL,2,'(2) Yet Jane''s independence comes first from her inheritance, her new family and her refusal of St John, before she returns.',1,1);
INSERT INTO rubric_criterion VALUES(15243,'vce-english34-jane-eyre-ec1',NULL,3,'(3) Brontë frames their marriage as mutual dependence and companionship, which complicates any reading of Jane''s happiness as a victory.',1,1);
INSERT INTO rubric_criterion VALUES(15244,'vce-english34-twelfth-night-q1',NULL,0,'Orsino, in the opening line of the play (Act 1, Scene 1).',1,1);
INSERT INTO rubric_criterion VALUES(15245,'vce-english34-twelfth-night-q1',NULL,1,'He asks for ''excess'' of music so that, ''surfeiting, / The appetite may sicken and so die'', which shows that he is in love with the idea of love and enjoys his own melancholy.',2,1);
INSERT INTO rubric_criterion VALUES(15246,'vce-english34-twelfth-night-q2',NULL,0,'Viola, in Act 1, Scene 2, after the shipwreck.',1,1);
INSERT INTO rubric_criterion VALUES(15247,'vce-english34-twelfth-night-q2',NULL,1,'Alone in Illyria and believing her brother drowned, she asks the Captain to help disguise her so that she can serve Orsino.',1,1);
INSERT INTO rubric_criterion VALUES(15248,'vce-english34-twelfth-night-q3',NULL,0,'In Act 1, Scene 5, Viola (as Cesario) describes how she would woo Olivia if she were Orsino.',1,1);
INSERT INTO rubric_criterion VALUES(15249,'vce-english34-twelfth-night-q3',NULL,1,'The speech is so passionate that Olivia falls in love with Cesario.',1,1);
INSERT INTO rubric_criterion VALUES(15250,'vce-english34-twelfth-night-q4',NULL,0,'Olivia, in Act 1, Scene 5, after Malvolio sneers at Feste.',1,1);
INSERT INTO rubric_criterion VALUES(15251,'vce-english34-twelfth-night-q4',NULL,1,'It identifies Malvolio''s flaw, his vanity and self-importance, which Maria later exploits with the forged letter.',1,1);
INSERT INTO rubric_criterion VALUES(15252,'vce-english34-twelfth-night-q5',NULL,0,'In Act 2, Scene 2, Viola realises that Olivia loves Cesario, while Viola loves Orsino, who loves Olivia.',1,1);
INSERT INTO rubric_criterion VALUES(15253,'vce-english34-twelfth-night-q5',NULL,1,'She cannot fix the love triangle while she is in disguise, so she leaves it to time.',1,1);
INSERT INTO rubric_criterion VALUES(15254,'vce-english34-twelfth-night-q6',NULL,0,'Sir Toby Belch says it to Malvolio in Act 2, Scene 3, when Malvolio tries to stop the late-night revelry. It sets festivity and pleasure against Malvolio''s puritanical disapproval.',1,1);
INSERT INTO rubric_criterion VALUES(15255,'vce-english34-twelfth-night-q7',NULL,0,'It is part of the letter Maria forges in Olivia''s handwriting, which Malvolio reads in Act 2, Scene 5 while the others watch from hiding.',1,1);
INSERT INTO rubric_criterion VALUES(15256,'vce-english34-twelfth-night-q7',NULL,1,'It flatters his ambition and convinces him that Olivia loves him.',1,1);
INSERT INTO rubric_criterion VALUES(15257,'vce-english34-twelfth-night-q8',NULL,0,'Malvolio, as he storms out in the final scene (Act 5, Scene 1), after learning he was tricked and humiliated.',1,1);
INSERT INTO rubric_criterion VALUES(15258,'vce-english34-twelfth-night-q8',NULL,1,'It is a discordant note in the happy ending.',1,1);
INSERT INTO rubric_criterion VALUES(15259,'vce-english34-twelfth-night-qc1',NULL,0,'In 1.2 the disguise is Viola''s choice and gives her safety and freedom to act in Illyria.',1,1);
INSERT INTO rubric_criterion VALUES(15260,'vce-english34-twelfth-night-qc1',NULL,1,'By 2.2 the same disguise traps her: she loves Orsino, Olivia loves ‘Cesario’, and she cannot reveal herself.',1,1);
INSERT INTO rubric_criterion VALUES(15261,'vce-english34-twelfth-night-qc1',NULL,2,'She moves from taking control to handing her fate to time, showing how disguise both empowers and constrains.',1,1);
INSERT INTO rubric_criterion VALUES(15266,'vce-english34-twelfth-night-i5',NULL,0,'Almost every lover is deluded: Orsino loves an idea of Olivia, Olivia falls for a woman in disguise, Malvolio believes a forged letter, and Sir Andrew hopes for Olivia with no chance.',1,1);
INSERT INTO rubric_criterion VALUES(15267,'vce-english34-twelfth-night-i5',NULL,1,'Love makes characters act against reason, which is both comic and, for Viola, painful.',2,1);
INSERT INTO rubric_criterion VALUES(15268,'vce-english34-twelfth-night-i6',NULL,0,'At first he is a pompous killjoy and his gulling seems deserved and funny.',1,1);
INSERT INTO rubric_criterion VALUES(15269,'vce-english34-twelfth-night-i6',NULL,1,'But when he is locked in a dark room and told he is mad (Act 4, Scene 2), the joke becomes cruel, and his final threat of revenge leaves the audience uneasy about how he has been treated.',2,1);
INSERT INTO rubric_criterion VALUES(15270,'vce-english34-twelfth-night-i7',NULL,0,'Both plots are about deception and self-deception. The main plot''s disguise is innocent and leads to love;',1,1);
INSERT INTO rubric_criterion VALUES(15271,'vce-english34-twelfth-night-i7',NULL,1,'the subplot''s trick is deliberate and leads to humiliation.',1,1);
INSERT INTO rubric_criterion VALUES(15272,'vce-english34-twelfth-night-i7',NULL,2,'The subplot also brings festivity and disorder, contrasting with the romantic melancholy of Orsino''s court.',1,1);
INSERT INTO rubric_criterion VALUES(15273,'vce-english34-twelfth-night-ic1',NULL,0,'The letter scene is comic: Malvolio''s vanity and ambition make his gulling feel deserved.',1,1);
INSERT INTO rubric_criterion VALUES(15274,'vce-english34-twelfth-night-ic1',NULL,1,'The dark-room scene, where Feste as Sir Topas torments him while he insists he is sane, moves towards cruelty.',1,1);
INSERT INTO rubric_criterion VALUES(15275,'vce-english34-twelfth-night-ic1',NULL,2,'In the final scene Olivia acknowledges he has been badly wronged, and his exit vowing revenge leaves a discordant note, so many audiences end with sympathy as well as laughter.',1,1);
INSERT INTO rubric_criterion VALUES(15279,'vce-english34-twelfth-night-c4',NULL,0,'Spoken to Olivia, it is literally true (Viola is not a man) and the audience hears both meanings, creating dramatic irony.',1,1);
INSERT INTO rubric_criterion VALUES(15280,'vce-english34-twelfth-night-c4',NULL,1,'It also sums up the play''s interest in identity: characters are not what they seem, and disguise reveals hidden desires.',2,1);
INSERT INTO rubric_criterion VALUES(15281,'vce-english34-twelfth-night-c5',NULL,0,'Feste''s reference to ''the whirligig of time'' bringing ''his revenges'' and his closing song bring a note of melancholy and realism after the weddings.',1,1);
INSERT INTO rubric_criterion VALUES(15282,'vce-english34-twelfth-night-c5',NULL,1,'They remind the audience that festivity ends and time moves on, which keeps the comedy from feeling simply happy.',2,1);
INSERT INTO rubric_criterion VALUES(15292,'vce-english34-twelfth-night-ec1',NULL,0,'Contention: the comic ending pairs the lovers, but Shakespeare undercuts its harmony, suggesting that desire is rarely fulfilled cleanly.',1,1);
INSERT INTO rubric_criterion VALUES(15293,'vce-english34-twelfth-night-ec1',NULL,1,'(1) The marriages rest on mistaken identity and sudden shifts of feeling: Olivia marries Sebastian believing him Cesario, and Orsino turns quickly to Viola.',1,1);
INSERT INTO rubric_criterion VALUES(15294,'vce-english34-twelfth-night-ec1',NULL,2,'(2) Several characters are left outside the celebration: Malvolio humiliated, Antonio unresolved and Sir Andrew rejected.',1,1);
INSERT INTO rubric_criterion VALUES(15295,'vce-english34-twelfth-night-ec1',NULL,3,'(3) Feste''s melancholy closing song reminds the audience that the festive world gives way to ordinary life.',1,1);
INSERT INTO rubric_criterion VALUES(15296,'vce-english34-my-brilliant-career-q1',NULL,0,'In the Introduction, which Sybylla addresses to ''My dear fellow Australians''.',1,1);
INSERT INTO rubric_criterion VALUES(15297,'vce-english34-my-brilliant-career-q1',NULL,1,'She declares that her story is a real ''yarn'' about hardship, not a romantic novel.',1,1);
INSERT INTO rubric_criterion VALUES(15298,'vce-english34-my-brilliant-career-q2',NULL,0,'In Chapter 5, during the drought at Possum Gully, as she faces endless drudgery on the dairy farm at fifteen.',1,1);
INSERT INTO rubric_criterion VALUES(15299,'vce-english34-my-brilliant-career-q2',NULL,1,'''Brilliant career'' is bitterly ironic: her future looks like nothing but weariness.',1,1);
INSERT INTO rubric_criterion VALUES(15300,'vce-english34-my-brilliant-career-q3',NULL,0,'In Chapter 7, Sybylla explains why her grandmother wants to bring her to Caddagat: to find her a husband.',1,1);
INSERT INTO rubric_criterion VALUES(15301,'vce-english34-my-brilliant-career-q3',NULL,1,'It shows the expectation that marriage is a woman''s only destiny.',1,1);
INSERT INTO rubric_criterion VALUES(15302,'vce-english34-my-brilliant-career-q4',NULL,0,'Sarcastic. In Chapter 7 she notes that, because she is considered plain, she will be given more time to find a husband.',1,1);
INSERT INTO rubric_criterion VALUES(15303,'vce-english34-my-brilliant-career-q4',NULL,1,'She mocks the way women are treated as goods to be traded.',1,1);
INSERT INTO rubric_criterion VALUES(15304,'vce-english34-my-brilliant-career-q5',NULL,0,'Sybylla states, in Chapter 7, her deep aversion to marriage as a trap that is unfair to women.',1,1);
INSERT INTO rubric_criterion VALUES(15305,'vce-english34-my-brilliant-career-q5',NULL,1,'It explains why, despite her feelings for Harold Beecham, she ultimately refuses to marry him.',1,1);
INSERT INTO rubric_criterion VALUES(15306,'vce-english34-my-brilliant-career-q6',NULL,0,'In Chapter 25, after Harold has lost his fortune.',1,1);
INSERT INTO rubric_criterion VALUES(15307,'vce-english34-my-brilliant-career-q6',NULL,1,'She agrees to marry him when she turns twenty-one, showing loyalty and compassion: she offers herself when he is poor, not when he was rich.',1,1);
INSERT INTO rubric_criterion VALUES(15308,'vce-english34-my-brilliant-career-q7',NULL,0,'In Chapter 38, the final chapter.',1,1);
INSERT INTO rubric_criterion VALUES(15309,'vce-english34-my-brilliant-career-q7',NULL,1,'Sybylla celebrates her Australian identity and her bond with the bush and its working people.',1,1);
INSERT INTO rubric_criterion VALUES(15310,'vce-english34-my-brilliant-career-q8',NULL,0,'In the final chapter, Sybylla identifies with ordinary bush people while protesting her limited place as a woman.',1,1);
INSERT INTO rubric_criterion VALUES(15311,'vce-english34-my-brilliant-career-q8',NULL,1,'The repeated ''I am only'' and the dash before ''woman'' show both humility and bitterness.',1,1);
INSERT INTO rubric_criterion VALUES(15312,'vce-english34-my-brilliant-career-qc1',NULL,0,'In Chapter 5 ‘brilliant career’ is bitter irony: her ambitions are crushed by drudgery and drought.',1,1);
INSERT INTO rubric_criterion VALUES(15313,'vce-english34-my-brilliant-career-qc1',NULL,1,'At the end she still has no career in the usual sense, but she claims a voice and an identity with ordinary bush people.',1,1);
INSERT INTO rubric_criterion VALUES(15314,'vce-english34-my-brilliant-career-qc1',NULL,2,'The novel itself, her outspoken account, becomes the ‘career’ that society denied her.',1,1);
INSERT INTO rubric_criterion VALUES(15319,'vce-english34-my-brilliant-career-i5',NULL,0,'She fears marriage would trap her and end her ambitions; she feels she is not suited to be a conventional wife;',1,1);
INSERT INTO rubric_criterion VALUES(15320,'vce-english34-my-brilliant-career-i5',NULL,1,'and she believes she would make Harold unhappy.',1,1);
INSERT INTO rubric_criterion VALUES(15321,'vce-english34-my-brilliant-career-i5',NULL,2,'Her refusal is an assertion of independence, even though it leaves her future uncertain.',1,1);
INSERT INTO rubric_criterion VALUES(15322,'vce-english34-my-brilliant-career-i6',NULL,0,'Ambivalently.',1,1);
INSERT INTO rubric_criterion VALUES(15323,'vce-english34-my-brilliant-career-i6',NULL,1,'The bush is a source of beauty, pride and national identity (as in the final chapter), but it is also a place of drought, poverty and endless labour that crushes ambition, especially for women.',1,1);
INSERT INTO rubric_criterion VALUES(15324,'vce-english34-my-brilliant-career-i7',NULL,0,'She believes she is ugly, which makes her insecure and defensive.',1,1);
INSERT INTO rubric_criterion VALUES(15325,'vce-english34-my-brilliant-career-i7',NULL,1,'Her family treat beauty as a woman''s main asset in the marriage market, so her plainness makes her feel worthless and fuels her bitterness about women''s value being judged by appearance.',2,1);
INSERT INTO rubric_criterion VALUES(15326,'vce-english34-my-brilliant-career-ic1',NULL,0,'She sees marriage as a trap that is unfair to women, doubts she could make him happy, and wants freedom and a life of her own mind.',1,1);
INSERT INTO rubric_criterion VALUES(15327,'vce-english34-my-brilliant-career-ic1',NULL,1,'It is both: she keeps her independence and integrity, but she returns to hardship and loneliness, and the novel lets readers feel the cost of that choice in a society that offers women few alternatives.',2,1);
INSERT INTO rubric_criterion VALUES(15331,'vce-english34-my-brilliant-career-c4',NULL,0,'Sybylla''s sarcasm (''sweet thought!'') and self-mockery make her lively and rebellious, and they expose the absurdity of the expectations placed on her.',1,1);
INSERT INTO rubric_criterion VALUES(15332,'vce-english34-my-brilliant-career-c4',NULL,1,'The humour also hides pain: her jokes about being ugly or unmarriageable reveal insecurity.',1,1);
INSERT INTO rubric_criterion VALUES(15333,'vce-english34-my-brilliant-career-c5',NULL,0,'They create an urgent, spoken voice full of emotion, as if Sybylla is talking directly to us.',1,1);
INSERT INTO rubric_criterion VALUES(15334,'vce-english34-my-brilliant-career-c5',NULL,1,'They convey frustration, despair and passion, and make the novel feel like a confession rather than a polished story.',1,1);
INSERT INTO rubric_criterion VALUES(15344,'vce-english34-my-brilliant-career-ec1',NULL,0,'Contention: Sybylla''s self-doubt and restlessness shape her choices, but Franklin shows that her inner conflict grows from the narrow roles her society allows women.',1,1);
INSERT INTO rubric_criterion VALUES(15345,'vce-english34-my-brilliant-career-ec1',NULL,1,'(1) Her contempt for her own looks and moods leads her to push away those who care for her.',1,1);
INSERT INTO rubric_criterion VALUES(15346,'vce-english34-my-brilliant-career-ec1',NULL,2,'(2) Yet poverty, drought and class trap her at Possum Gully and Barney''s Gap, not her personality.',1,1);
INSERT INTO rubric_criterion VALUES(15347,'vce-english34-my-brilliant-career-ec1',NULL,3,'(3) Her refusal of marriage is presented as resistance to a social system rather than self-sabotage.',1,1);
INSERT INTO rubric_criterion VALUES(15348,'vce-english34-memory-police-q1',NULL,0,'In Chapter 1, as the narrator recalls things that once existed on the island.',1,1);
INSERT INTO rubric_criterion VALUES(15349,'vce-english34-memory-police-q1',NULL,1,'The plain list of ordinary objects shows how many small things have been lost, and how each loss is treated as simply a fact.',1,1);
INSERT INTO rubric_criterion VALUES(15350,'vce-english34-memory-police-q2',NULL,0,'From Chapter 1: as a child, the narrator heard stories from her mother about things that had disappeared.',1,1);
INSERT INTO rubric_criterion VALUES(15351,'vce-english34-memory-police-q2',NULL,1,'Perfume survives only as a story, and the narrator has to imagine what it was.',1,1);
INSERT INTO rubric_criterion VALUES(15352,'vce-english34-memory-police-q3',NULL,0,'That memory is resilient: even when objects are taken away, something of them may survive in people''s hearts.',1,1);
INSERT INTO rubric_criterion VALUES(15353,'vce-english34-memory-police-q3',NULL,1,'It offers hope against the regime''s attempt to erase the past.',1,1);
INSERT INTO rubric_criterion VALUES(15354,'vce-english34-memory-police-q4',NULL,0,'The narrator suggests that as the island loses things, the people lose part of themselves: their inner lives become thinner and emptier along with their world.',2,1);
INSERT INTO rubric_criterion VALUES(15355,'vce-english34-memory-police-q5',NULL,0,'The narrator accepts her own emptiness.',1,1);
INSERT INTO rubric_criterion VALUES(15356,'vce-english34-memory-police-q5',NULL,1,'The disappearances have hollowed out her inner life, and she resigns herself to it rather than resisting.',1,1);
INSERT INTO rubric_criterion VALUES(15357,'vce-english34-memory-police-q6',NULL,0,'The narrator''s own novel is about a typist who loses her voice.',1,1);
INSERT INTO rubric_criterion VALUES(15358,'vce-english34-memory-police-q6',NULL,1,'The idea that losing your voice means losing your sense of self mirrors the islanders, who lose words, objects and memories and with them their identities.',1,1);
INSERT INTO rubric_criterion VALUES(15359,'vce-english34-memory-police-qc1',NULL,0,'The first offers hope: memory survives in the heart even when objects vanish.',1,1);
INSERT INTO rubric_criterion VALUES(15360,'vce-english34-memory-police-qc1',NULL,1,'The second shows the narrator''s resignation as disappearances empty her.',1,1);
INSERT INTO rubric_criterion VALUES(15361,'vce-english34-memory-police-qc1',NULL,2,'Together they set up the novel''s central tension between resilience and erosion, leaving the reader to ask whether memory can survive when the people who hold it give up.',1,1);
INSERT INTO rubric_criterion VALUES(15366,'vce-english34-memory-police-i5',NULL,0,'They enforce the disappearances, searching houses and taking away anyone who remembers.',1,1);
INSERT INTO rubric_criterion VALUES(15367,'vce-english34-memory-police-i5',NULL,1,'Their power works through fear and through people''s willingness to accept losses, so control comes as much from compliance as from force.',1,1);
INSERT INTO rubric_criterion VALUES(15368,'vce-english34-memory-police-i6',NULL,0,'The old man is a steady, gentle companion who helps her hide R.',1,1);
INSERT INTO rubric_criterion VALUES(15369,'vce-english34-memory-police-i6',NULL,1,'Their friendship shows kindness and care surviving under oppression, and it gives the novel much of its emotional warmth.',1,1);
INSERT INTO rubric_criterion VALUES(15370,'vce-english34-memory-police-i7',NULL,0,'As the disappearances spread to parts of people''s bodies, the narrator gradually fades away completely, while R, who remembers, leaves his hiding place.',1,1);
INSERT INTO rubric_criterion VALUES(15371,'vce-english34-memory-police-i7',NULL,1,'The ending suggests that without memory a person cannot survive, but that memory itself, held by someone, endures.',2,1);
INSERT INTO rubric_criterion VALUES(15372,'vce-english34-memory-police-ic1',NULL,0,'Unlike R, she loses the memories themselves, so she cannot miss what has gone.',1,1);
INSERT INTO rubric_criterion VALUES(15373,'vce-english34-memory-police-ic1',NULL,1,'The regime makes each loss feel normal, and she adapts to survive.',1,1);
INSERT INTO rubric_criterion VALUES(15374,'vce-english34-memory-police-ic1',NULL,2,'Ogawa seems more interested in quiet complicity and adaptation under authoritarian control than in heroic rebellion, yet the narrator''s hiding of R and her writing are small, real acts of resistance.',1,1);
INSERT INTO rubric_criterion VALUES(15378,'vce-english34-memory-police-c4',NULL,0,'The island is isolated and unnamed, so it feels both specific and universal.',1,1);
INSERT INTO rubric_criterion VALUES(15379,'vce-english34-memory-police-c4',NULL,1,'Its isolation means there is no escape and no outside help, which intensifies the sense of control, and its vagueness lets readers apply the story to many societies.',2,1);
INSERT INTO rubric_criterion VALUES(15380,'vce-english34-memory-police-c5',NULL,0,'Leaving the cause unexplained makes the regime feel arbitrary and absolute, like a natural law the characters cannot question.',1,1);
INSERT INTO rubric_criterion VALUES(15381,'vce-english34-memory-police-c5',NULL,1,'It shifts the focus from politics to the experience of loss, and invites readers to bring their own interpretations.',1,1);
INSERT INTO rubric_criterion VALUES(15391,'vce-english34-memory-police-ec1',NULL,0,'Contention: the narrator''s fate is bleak, but Ogawa suggests that quiet resistance matters even when it cannot defeat the regime.',1,1);
INSERT INTO rubric_criterion VALUES(15392,'vce-english34-memory-police-ec1',NULL,1,'(1) The disappearances seem unstoppable, and the narrator herself finally vanishes.',1,1);
INSERT INTO rubric_criterion VALUES(15393,'vce-english34-memory-police-ec1',NULL,2,'(2) Yet R survives, and objects and memories hidden in the secret room keep the past alive.',1,1);
INSERT INTO rubric_criterion VALUES(15394,'vce-english34-memory-police-ec1',NULL,3,'(3) The novel-within-the-novel shows writing as a way of preserving a self, so the act of telling is a form of resistance.',1,1);
INSERT INTO rubric_criterion VALUES(15395,'vce-english34-educated-q1',NULL,0,'The family''s preparation for the end of the world at the new millennium (Y2K), which her father was certain would bring disaster.',1,1);
INSERT INTO rubric_criterion VALUES(15396,'vce-english34-educated-q1',NULL,1,'When nothing happens, the short, flat sentence deflates his prophecy.',1,1);
INSERT INTO rubric_criterion VALUES(15397,'vce-english34-educated-q2',NULL,0,'Tara''s father, in Chapter 10, while driving dangerously through the night.',1,1);
INSERT INTO rubric_criterion VALUES(15398,'vce-english34-educated-q2',NULL,1,'He trusts that faith will protect the family, which reveals his reckless certainty and the danger it puts his children in.',1,1);
INSERT INTO rubric_criterion VALUES(15399,'vce-english34-educated-q3',NULL,0,'As she teaches herself at home, Tara realises that persevering with difficult texts, even before she understands them, is the key skill behind learning.',2,1);
INSERT INTO rubric_criterion VALUES(15400,'vce-english34-educated-q4',NULL,0,'That poverty limits learning: when you are struggling to survive, you cannot afford to wonder and explore.',1,1);
INSERT INTO rubric_criterion VALUES(15401,'vce-english34-educated-q4',NULL,1,'It reflects her early years at university, when money worries crowded out everything else.',1,1);
INSERT INTO rubric_criterion VALUES(15402,'vce-english34-educated-q5',NULL,0,'Once she has some financial support at university, she is no longer consumed by worry about money and can focus on learning.',2,1);
INSERT INTO rubric_criterion VALUES(15403,'vce-english34-educated-q6',NULL,0,'Tara realises that others, especially her father, had defined her story and her identity, and that she has the right to interpret her own life.',2,1);
INSERT INTO rubric_criterion VALUES(15404,'vce-english34-educated-q7',NULL,0,'She has changed so much that she is no longer the child her father shaped, yet she cannot deny that he raised that child.',1,1);
INSERT INTO rubric_criterion VALUES(15405,'vce-english34-educated-q7',NULL,1,'It expresses both separation from her family and an inescapable connection to it.',1,1);
INSERT INTO rubric_criterion VALUES(15406,'vce-english34-educated-q8',NULL,0,'In the memoir''s final lines.',1,1);
INSERT INTO rubric_criterion VALUES(15407,'vce-english34-educated-q8',NULL,1,'Tara acknowledges that her family might see her change as betrayal, but she names it education: the making of a new self.',1,1);
INSERT INTO rubric_criterion VALUES(15408,'vce-english34-educated-qc1',NULL,0,'At first others, especially her father, define her identity with forceful, absolute voices.',1,1);
INSERT INTO rubric_criterion VALUES(15409,'vce-english34-educated-qc1',NULL,1,'By the end she names her own transformation, choosing ‘education’ over the family''s words such as ‘betrayal’.',1,1);
INSERT INTO rubric_criterion VALUES(15410,'vce-english34-educated-qc1',NULL,2,'She moves from being narrated to narrating, and the memoir itself is the proof.',1,1);
INSERT INTO rubric_criterion VALUES(15415,'vce-english34-educated-i5',NULL,0,'As a painful conflict. Education teaches Tara to question her father''s beliefs and to trust her own memories, but doing so is seen by her family as betrayal.',1,1);
INSERT INTO rubric_criterion VALUES(15416,'vce-english34-educated-i5',NULL,1,'She gains a new self but loses much of her family.',1,1);
INSERT INTO rubric_criterion VALUES(15417,'vce-english34-educated-i6',NULL,0,'Westover repeatedly questions her own memories and compares them with her siblings'' accounts, sometimes in footnotes.',1,1);
INSERT INTO rubric_criterion VALUES(15418,'vce-english34-educated-i6',NULL,1,'She shows that memory is unreliable and that owning your memories is part of owning your identity, especially when your family insists on a different story.',2,1);
INSERT INTO rubric_criterion VALUES(15419,'vce-english34-educated-i7',NULL,0,'With complexity. He is dangerous, controlling and possibly unwell, putting his children in harm''s way through his beliefs;',1,1);
INSERT INTO rubric_criterion VALUES(15420,'vce-english34-educated-i7',NULL,1,'yet he is also charismatic and loving in his way. Westover tries to understand him rather than simply condemn him.',1,1);
INSERT INTO rubric_criterion VALUES(15421,'vce-english34-educated-ic1',NULL,0,'She shows his fear, his beliefs and his skill, and she comes to consider whether mental illness shaped his behaviour, so he is complex rather than evil.',1,1);
INSERT INTO rubric_criterion VALUES(15422,'vce-english34-educated-ic1',NULL,1,'Her line that he is ‘the father who raised her’ keeps the bond alive.',1,1);
INSERT INTO rubric_criterion VALUES(15423,'vce-english34-educated-ic1',NULL,2,'This complexity makes her break from her family more painful and more convincing.',1,1);
INSERT INTO rubric_criterion VALUES(15427,'vce-english34-educated-c4',NULL,0,'The mountain is described with beauty and power, and it stands for home, her father''s world and the strength of her roots.',1,1);
INSERT INTO rubric_criterion VALUES(15428,'vce-english34-educated-c4',NULL,1,'Its presence across the memoir shows how deeply her identity is tied to the place even as she leaves it.',2,1);
INSERT INTO rubric_criterion VALUES(15429,'vce-english34-educated-c5',NULL,0,'The restraint makes the events more disturbing and credible, as she reports rather than dramatises.',1,1);
INSERT INTO rubric_criterion VALUES(15430,'vce-english34-educated-c5',NULL,1,'It also shows the adult narrator''s distance and reflection, contrasting with the child who lived through them.',1,1);
INSERT INTO rubric_criterion VALUES(15440,'vce-english34-educated-ec1',NULL,0,'Contention: Westover shows that education costs her family, home and certainty, but she presents that cost as the price of becoming herself, imposed by her family''s demand for loyalty rather than by learning.',1,1);
INSERT INTO rubric_criterion VALUES(15441,'vce-english34-educated-ec1',NULL,1,'(1) Her education leads to estrangement and grief, so the cost is real.',1,1);
INSERT INTO rubric_criterion VALUES(15442,'vce-english34-educated-ec1',NULL,2,'(2) The cost comes from a family that treats independent thought as betrayal.',1,1);
INSERT INTO rubric_criterion VALUES(15443,'vce-english34-educated-ec1',NULL,3,'(3) Westover frames education as self-making, and by the end she accepts the loss as part of who she has become.',1,1);
INSERT INTO rubric_criterion VALUES(15450,'vce-english34-arg-t7',NULL,0,'Because Section C rewards analysis of how language is intended to persuade a particular audience.',1,1);
INSERT INTO rubric_criterion VALUES(15451,'vce-english34-arg-t7',NULL,1,'You need to explain the effect: what the technique is likely to make readers think or feel, and how that supports the writer''s contention.',1,1);
INSERT INTO rubric_criterion VALUES(15452,'vce-english34-arg-t8',NULL,0,'The context (the issue and what prompted the piece), the writer and form (for example, a letter to the editor), the intended audience, the writer''s contention, and the overall tone.',1,1);
INSERT INTO rubric_criterion VALUES(15453,'vce-english34-arg-t8',NULL,1,'It does not give your own opinion on the issue.',1,1);
INSERT INTO rubric_criterion VALUES(15468,'vce-english34-arg-pc1',NULL,0,'Identifying only names the technique.',1,1);
INSERT INTO rubric_criterion VALUES(15469,'vce-english34-arg-pc1',NULL,1,'Analysis explains how specific words work on a particular audience and support the contention.',1,1);
INSERT INTO rubric_criterion VALUES(15470,'vce-english34-arg-pc1',NULL,2,'Example: by comparing delay to a ‘tap left running’, the writer makes the cost seem constant and wasteful, positioning taxpayers to see inaction as irresponsible and to support urgent funding.',1,1);
INSERT INTO rubric_criterion VALUES(15471,'vce-chinese-sl34-challenge-1',NULL,0,'Assessed as part of the whole conversation: 我认为学习中文对我的将来帮助很大。第一，我以后想当律师，墨尔本有很多说中文的客户，会说中文的话，我可以更好地帮助他们。第二，我打算大学的时候去中国做交换生，如果中文好，我就能更快地适应那里的生活。另外，学中文也让我交了很多新朋友。',0,1);
INSERT INTO rubric_criterion VALUES(15472,'vce-chinese-sl34-challenge-2',NULL,0,'Assessed as part of the whole conversation: 我从一个中国交换生那里听说，中国的高中生每天上课的时间比我们长，晚上还要上晚自习，考试的压力也很大。我们这里的学生一般下午三点半就放学了，有更多时间参加体育和音乐活动。不过，我觉得每个学生都不一样，不能说哪种方式一定更好。两种方式都有优点，比如中国学生很努力，我们的学生比较会独立思考。',0,1);
INSERT INTO rubric_criterion VALUES(15473,'vce-chinese-sl34-challenge-3',NULL,0,'Assessed as part of the whole conversation: 我基本同意。书上的知识很重要，可是去别的地方亲眼看一看，感受会更深。比如，我在书上读过很多关于长城的介绍，可是去年真的爬上长城的时候，才知道它有多么雄伟。不过，我觉得读书和旅行应该结合起来：先读书了解历史，旅行的时候才能看懂更多。',0,1);
INSERT INTO rubric_criterion VALUES(15474,'vce-chinese-sl34-challenge-4',NULL,0,'Assessed as part of the whole conversation: 我最难忘的经历是去年在一家养老院做志愿者。每个星期六我都去陪老人聊天、下棋。一开始我很紧张，不知道说什么，可是后来一位张奶奶教我包饺子，我们成了好朋友。这次经历让我学会了耐心，也让我明白，有时候陪伴比礼物更重要。',0,1);
INSERT INTO rubric_criterion VALUES(15479,'vce-chinese-sl34-challenge-9',NULL,0,'学中文不但很有用，而且很有意思。',1,1);
INSERT INTO rubric_criterion VALUES(15480,'vce-chinese-sl34-challenge-10',NULL,0,'尊敬的校长：您好！我想向您反映一件事。',1,1);
INSERT INTO rubric_criterion VALUES(15483,'vce-english34-challenge-3',NULL,0,'For example: ‘Brontë uses the orchard proposal to show that Jane will accept love only as Rochester''s equal, never as his possession.’',2,1);
INSERT INTO rubric_criterion VALUES(15486,'vce-english34-challenge-6',NULL,0,'An image can reinforce the contention emotionally or make an abstract issue concrete.',1,1);
INSERT INTO rubric_criterion VALUES(15487,'vce-english34-challenge-6',NULL,1,'For example, a photo of a fenced-off, empty playground beside an article calling for park funding makes the loss visible and invites parents'' sympathy.',1,1);
INSERT INTO rubric_criterion VALUES(15488,'vce-english34-challenge-7',NULL,0,'Helen embodies patient endurance and Christian forgiveness, in contrast with young Jane''s rebellion against injustice.',1,1);
INSERT INTO rubric_criterion VALUES(15489,'vce-english34-challenge-7',NULL,1,'Her death at Lowood exposes the cruelty of Brocklehurst''s regime.',1,1);
INSERT INTO rubric_criterion VALUES(15490,'vce-english34-challenge-7',NULL,2,'Jane learns from her but does not copy her: Brontë suggests faith and self-respect can coexist with resistance.',1,1);
INSERT INTO rubric_criterion VALUES(15492,'vce-english34-challenge-9',NULL,0,'Malvolio''s self-deception about Olivia''s love mirrors the self-deception of Orsino and Olivia.',1,1);
INSERT INTO rubric_criterion VALUES(15493,'vce-english34-challenge-9',NULL,1,'The forged letter is another form of disguise and misreading.',1,1);
INSERT INTO rubric_criterion VALUES(15494,'vce-english34-challenge-9',NULL,2,'The subplot exaggerates the main plot''s follies, and its harsher ending exposes what the romantic plot glosses over.',1,1);
INSERT INTO rubric_criterion VALUES(15495,'vce-english34-challenge-10',NULL,0,'The writer might use emotive anecdotes and inclusive language (‘our children’) to stir parents'' concern, while using statistics, cost arguments and appeals to responsibility to pressure the council to act.',2,1);
