INSERT INTO rubric_criterion VALUES(17538,'methods-6-3-m1',725,0,'Solve \(4x - x^2 = x\): \(x^2 - 3x = 0\), so \(x(x - 3) = 0\), giving \(x = 0\) or \(x = 3\).',0,0);
INSERT INTO rubric_criterion VALUES(17539,'methods-6-3-m1',725,1,'Use \(g(x) = x\) for the \(y\)-coordinates: the points are \((0, 0)\) and \((3, 3)\).',1,0);
INSERT INTO rubric_criterion VALUES(17540,'methods-6-3-m1',726,0,'On \([0, 3]\) the parabola is above the line (for example \(f(1) = 3 > g(1) = 1\)), so the area is \(\displaystyle\int_0^3 \big(f(x) - g(x)\big)\,dx = \int_0^3 (3x - x^2)\,dx\).',1,0);
INSERT INTO rubric_criterion VALUES(17541,'methods-6-3-m1',727,0,'Antidifferentiate: \(\displaystyle\int_0^3 (3x - x^2)\,dx = \left[\frac{3x^2}{2} - \frac{x^3}{3}\right]_0^3\).',1,0);
INSERT INTO rubric_criterion VALUES(17542,'methods-6-3-m1',727,1,'Evaluate: \(\left(\frac{27}{2} - 9\right) - 0 = \frac{9}{2}\) square units.',1,0);
INSERT INTO rubric_criterion VALUES(17543,'methods-6-3-m1',728,0,'The vertical height of the region at \(x\) is \(h(x) = f(x) - g(x) = 3x - x^2 = x(3 - x)\), a parabola with zeros at \(0\) and \(3\), so its axis of symmetry is \(x = \frac{3}{2}\).',0,0);
INSERT INTO rubric_criterion VALUES(17544,'methods-6-3-m1',728,1,'Since \(h(3 - x) = (3 - x)x = h(x)\), the height at \(\frac{3}{2} - t\) equals the height at \(\frac{3}{2} + t\). So \(\displaystyle\int_0^{3/2} h(x)\,dx = \int_{3/2}^{3} h(x)\,dx = \frac{9}{4}\), which is half of \(\frac{9}{2}\).',1,0);
