INSERT INTO rubric_criterion VALUES(17619,'methods-7-3-m1',730,0,'\(X \sim \text{Bi}(12, 0.2)\), so \(\Pr(X = 3) = \binom{12}{3}(0.2)^3(0.8)^9 = 220 \times 0.008 \times 0.8^9 \approx 0.2362\).',1,0);
INSERT INTO rubric_criterion VALUES(17620,'methods-7-3-m1',731,0,'Use the complement: \(\Pr(X \ge 2) = 1 - \Pr(X = 0) - \Pr(X = 1)\).',1,0);
INSERT INTO rubric_criterion VALUES(17621,'methods-7-3-m1',731,1,'\(= 1 - 0.8^{12} - 12(0.2)(0.8)^{11} \approx 1 - 0.06872 - 0.20616 \approx 0.7251\).',1,0);
INSERT INTO rubric_criterion VALUES(17622,'methods-7-3-m1',732,0,'\(\Pr(X \ge 2 \mid X \le 4) = \dfrac{\Pr(2 \le X \le 4)}{\Pr(X \le 4)}\).',1,0);
INSERT INTO rubric_criterion VALUES(17623,'methods-7-3-m1',732,1,'With CAS, \(\Pr(2 \le X \le 4) \approx 0.65257\) and \(\Pr(X \le 4) \approx 0.92744\), so the probability is \(\dfrac{0.65257}{0.92744} \approx 0.7036\).',1,0);
INSERT INTO rubric_criterion VALUES(17624,'methods-7-3-m1',733,0,'\(\Pr(\text{at least one}) = 1 - 0.8^n > 0.99\), so \(0.8^n < 0.01\).',1,0);
INSERT INTO rubric_criterion VALUES(17625,'methods-7-3-m1',733,1,'\(n > \dfrac{\log_e 0.01}{\log_e 0.8} \approx 20.64\), so the smallest sample size is \(n = 21\).',1,0);
