INSERT INTO rubric_criterion VALUES(21650,'psych34a1-con-3',NULL,0,'Chooses A: sensory neuron, interneuron in spinal cord, motor neuron, effector',1,0);
INSERT INTO rubric_criterion VALUES(21651,'psych34a1-con-4',NULL,0,'Chooses D: It produces a response faster than one routed through the brain, reducing potential harm',1,0);
INSERT INTO rubric_criterion VALUES(21652,'psych34a1-con-5',NULL,0,'Chooses B: a conscious response because it involved awareness and voluntary control',1,0);
INSERT INTO rubric_criterion VALUES(21653,'vce-psych34-cu-c1',NULL,0,'Chooses C: Interneurons in the spinal cord link sensory and motor neurons, so the response starts before the pain message reaches the brain',1,0);
INSERT INTO rubric_criterion VALUES(21654,'psych34a1-ntm-1',NULL,0,'Chooses C: It increases the likelihood that the postsynaptic neuron will fire',1,0);
INSERT INTO rubric_criterion VALUES(21655,'psych34a1-ntm-2',NULL,0,'Chooses A: GABA',1,0);
INSERT INTO rubric_criterion VALUES(21656,'psych34a1-ntm-3',NULL,0,'Chooses C: alter the effect of neurotransmitters on the postsynaptic neuron, often across many neurons',1,0);
INSERT INTO rubric_criterion VALUES(21657,'psych34a1-ntm-4',NULL,0,'Chooses A: crosses the synaptic gap and binds to receptor sites on the postsynaptic neuron',1,0);
INSERT INTO rubric_criterion VALUES(21658,'psych34a1-ntm-5',NULL,0,'Chooses C: increased likelihood that the neurons will fire',1,0);
INSERT INTO rubric_criterion VALUES(21659,'vce-psych34-nt-c1',NULL,0,'Chooses D: More neural excitation, such as anxiety or even seizures',1,0);
INSERT INTO rubric_criterion VALUES(21660,'psych34a1-ltp-1',NULL,0,'Chooses B: the ability of synapses to change in strength in response to activity',1,0);
INSERT INTO rubric_criterion VALUES(21661,'psych34a1-ltp-2',NULL,0,'Chooses D: a long-lasting strengthening of synaptic connections following repeated stimulation',1,0);
INSERT INTO rubric_criterion VALUES(21662,'psych34a1-ltp-3',NULL,0,'Chooses B: Glutamate',1,0);
INSERT INTO rubric_criterion VALUES(21663,'psych34a1-ltp-4',NULL,0,'Chooses C: a weaker synaptic connection due to infrequent or low-level stimulation',1,0);
INSERT INTO rubric_criterion VALUES(21664,'psych34a1-ltp-5',NULL,0,'Chooses A: Long-term potentiation of the relevant synapses',1,0);
INSERT INTO rubric_criterion VALUES(21665,'vce-psych34-sp-c1',NULL,0,'Chooses D: Long-term potentiation while practising, then long-term depression after stopping',1,0);
INSERT INTO rubric_criterion VALUES(21666,'psych34a1-gas-1',NULL,0,'Chooses D: a state of threat or challenge that causes a physiological and psychological response',1,0);
INSERT INTO rubric_criterion VALUES(21667,'psych34a1-gas-2',NULL,0,'Chooses C: is a positive form of stress that can motivate and enhance performance',1,0);
INSERT INTO rubric_criterion VALUES(21668,'psych34a1-gas-3',NULL,0,'Chooses A: Adrenaline',1,0);
INSERT INTO rubric_criterion VALUES(21669,'psych34a1-gas-4',NULL,0,'Chooses B: Exhaustion',1,0);
INSERT INTO rubric_criterion VALUES(21670,'psych34a1-gas-5',NULL,0,'Chooses B: maintains elevated cortisol levels while attempting to cope with the stressor',1,0);
INSERT INTO rubric_criterion VALUES(21671,'vce-psych34-gas-c1',NULL,0,'Chooses B: High cortisol levels over a long period suppress the immune system',1,0);
INSERT INTO rubric_criterion VALUES(21672,'psych34a1-tmc-1',NULL,0,'Chooses C: Lazarus and Folkman',1,0);
INSERT INTO rubric_criterion VALUES(21673,'psych34a1-tmc-2',NULL,0,'Chooses A: a transaction between the individual and the environment, depending on appraisal',1,0);
INSERT INTO rubric_criterion VALUES(21674,'psych34a1-tmc-3',NULL,0,'Chooses C: irrelevant, benign-positive or stressful',1,0);
INSERT INTO rubric_criterion VALUES(21675,'psych34a1-tmc-4',NULL,0,'Chooses B: evaluating whether one has the resources and abilities to cope with the event',1,0);
INSERT INTO rubric_criterion VALUES(21676,'psych34a1-tmc-5',NULL,0,'Chooses A: different primary and secondary appraisals',1,0);
INSERT INTO rubric_criterion VALUES(21677,'vce-psych34-tm-c1',NULL,0,'Chooses D: Primary appraisal: stressful (challenge); secondary appraisal: evaluating her coping resources',1,0);
INSERT INTO rubric_criterion VALUES(21678,'psych34a1-gba-1',NULL,0,'Chooses A: the bidirectional communication between the gastrointestinal tract and the central nervous system',1,0);
INSERT INTO rubric_criterion VALUES(21679,'psych34a1-gba-2',NULL,0,'Chooses B: a network of neurons embedded in the walls of the gastrointestinal tract',1,0);
INSERT INTO rubric_criterion VALUES(21680,'psych34a1-gba-3',NULL,0,'Chooses A: carrying signals between the gut and the brain in both directions',1,0);
INSERT INTO rubric_criterion VALUES(21681,'psych34a1-gba-4',NULL,0,'Chooses D: Gut microbiota can influence the production of neurotransmitters such as serotonin, which may affect mood and stress responses',1,0);
INSERT INTO rubric_criterion VALUES(21682,'psych34a1-gba-5',NULL,0,'Chooses A: signals from the brain affecting gut function via the gut-brain axis',1,0);
INSERT INTO rubric_criterion VALUES(21683,'vce-psych34-gb-c1',NULL,0,'Chooses B: Bidirectional: the brain affects the gut and the gut affects the brain',1,0);
INSERT INTO rubric_criterion VALUES(21684,'psych34a1-cop-1',NULL,0,'Chooses C: strategies that aim to confront and deal directly with the stressor',1,0);
INSERT INTO rubric_criterion VALUES(21685,'psych34a1-cop-2',NULL,0,'Chooses B: Spending hours playing video games to avoid thinking about an upcoming exam',1,0);
INSERT INTO rubric_criterion VALUES(21686,'psych34a1-cop-3',NULL,0,'Chooses C: the ability to adapt coping strategies to suit the demands of different stressful situations',1,0);
INSERT INTO rubric_criterion VALUES(21687,'psych34a1-cop-4',NULL,0,'Chooses B: its effectiveness depends on the nature of the stressor and the situation',1,0);
INSERT INTO rubric_criterion VALUES(21688,'psych34a1-cop-5',NULL,0,'Chooses D: coping flexibility',1,0);
INSERT INTO rubric_criterion VALUES(21689,'vce-psych34-cf-c1',NULL,0,'Chooses D: A student who finds re-reading notes isn''t working switches to practice exams and asking a teacher',1,0);
INSERT INTO rubric_criterion VALUES(21690,'psych34a1-cc-1',NULL,0,'Chooses B: Pavlov',1,0);
INSERT INTO rubric_criterion VALUES(21691,'psych34a1-cc-2',NULL,0,'Chooses C: an automatic response to the unconditioned stimulus that does not need to be learned',1,0);
INSERT INTO rubric_criterion VALUES(21692,'psych34a1-cc-3',NULL,0,'Chooses B: the smell of the chips',1,0);
INSERT INTO rubric_criterion VALUES(21693,'psych34a1-cc-4',NULL,0,'Chooses C: the CS is repeatedly presented without the UCS, so the CR gradually weakens and disappears',1,0);
INSERT INTO rubric_criterion VALUES(21694,'psych34a1-cc-5',NULL,0,'Chooses D: stimulus generalisation',1,0);
INSERT INTO rubric_criterion VALUES(21695,'vce-psych34-cc-c1',NULL,0,'Chooses D: The bacteria that made him ill',1,0);
INSERT INTO rubric_criterion VALUES(21696,'psych34a1-oc-1',NULL,0,'Chooses B: behaviour is shaped by its consequences',1,0);
INSERT INTO rubric_criterion VALUES(21697,'psych34a1-oc-2',NULL,0,'Chooses C: antecedent, behaviour, consequence',1,0);
INSERT INTO rubric_criterion VALUES(21698,'psych34a1-oc-3',NULL,0,'Chooses A: negative reinforcement',1,0);
INSERT INTO rubric_criterion VALUES(21699,'psych34a1-oc-4',NULL,0,'Chooses B: negative punishment',1,0);
INSERT INTO rubric_criterion VALUES(21700,'psych34a1-oc-5',NULL,0,'Chooses C: The swimming race or training session in which the swimmer attempts a personal best',1,0);
