INSERT INTO rubric_criterion VALUES(21702,'psych34a1-obs-1',NULL,0,'Chooses A: Bandura',1,0);
INSERT INTO rubric_criterion VALUES(21703,'psych34a1-obs-2',NULL,0,'Chooses A: Attention, retention, reproduction, motivation, reinforcement',1,0);
INSERT INTO rubric_criterion VALUES(21704,'psych34a1-obs-3',NULL,0,'Chooses C: the person who is observed and whose behaviour is imitated',1,0);
INSERT INTO rubric_criterion VALUES(21705,'psych34a1-obs-4',NULL,0,'Chooses D: vicarious reinforcement',1,0);
INSERT INTO rubric_criterion VALUES(21706,'psych34a1-obs-5',NULL,0,'Chooses B: A trainee remembers the chef''s technique when practising later that evening',1,0);
INSERT INTO rubric_criterion VALUES(21707,'vce-psych34-ol-c1',NULL,0,'Chooses A: Reproduction',1,0);
INSERT INTO rubric_criterion VALUES(21708,'psych34a2-atsi-1',NULL,0,'Chooses D: Knowledge is closely tied to place, so features of the land act as cues that hold and help recall cultural knowledge',1,0);
INSERT INTO rubric_criterion VALUES(21709,'psych34a2-atsi-2',NULL,0,'Chooses A: songlines',1,0);
INSERT INTO rubric_criterion VALUES(21710,'psych34a2-atsi-3',NULL,0,'Chooses C: Learning is community-based, often through observation, practice and storytelling with kin and Elders',1,0);
INSERT INTO rubric_criterion VALUES(21711,'psych34a2-atsi-4',NULL,0,'Chooses A: They link information to meaningful, emotional, multisensory experiences that are shared and repeated, which supports memory',1,0);
INSERT INTO rubric_criterion VALUES(21712,'psych34a2-atsi-5',NULL,0,'Chooses C: define relationships and responsibilities, including who teaches particular knowledge and to whom',1,0);
