INSERT INTO rubric_criterion VALUES(21714,'psych34a2-asm-1',NULL,0,'Chooses D: Sensory memory, short-term memory, long-term memory',1,0);
INSERT INTO rubric_criterion VALUES(21715,'psych34a2-asm-2',NULL,0,'Chooses B: About 7 ± 2 items and about 12 to 30 seconds without rehearsal',1,0);
INSERT INTO rubric_criterion VALUES(21716,'psych34a2-asm-3',NULL,0,'Chooses D: information in sensory memory decaying because it was not attended to',1,0);
INSERT INTO rubric_criterion VALUES(21717,'psych34a2-asm-4',NULL,0,'Chooses A: more rehearsal, so these words are more likely to be transferred to long-term memory',1,0);
INSERT INTO rubric_criterion VALUES(21718,'psych34a2-asm-5',NULL,0,'Chooses C: It treats short-term memory as a single store and does not explain how different types of long-term memory work or the role of processing beyond rehearsal',1,0);
INSERT INTO rubric_criterion VALUES(21719,'vce-psych34-as-c1',NULL,0,'Chooses C: Echoic sensory memory, which holds sounds for about 3–4 seconds',1,0);
INSERT INTO rubric_criterion VALUES(21720,'psych34a2-eim-1',NULL,0,'Chooses C: Riding a bike without consciously thinking about each movement',1,0);
INSERT INTO rubric_criterion VALUES(21721,'psych34a2-eim-2',NULL,0,'Chooses B: memory of general facts and knowledge about the world',1,0);
INSERT INTO rubric_criterion VALUES(21722,'psych34a2-eim-3',NULL,0,'Chooses A: implicit memory, because past experience influenced performance without conscious recollection',1,0);
INSERT INTO rubric_criterion VALUES(21723,'psych34a2-eim-4',NULL,0,'Chooses A: Classically conditioned response: feeling anxious when you hear a dentist''s drill',1,0);
INSERT INTO rubric_criterion VALUES(21724,'psych34a2-eim-5',NULL,0,'Chooses B: Explicit memory requires conscious recall and can be declared; implicit memory influences behaviour without conscious awareness',1,0);
INSERT INTO rubric_criterion VALUES(21725,'vce-psych34-ei-c1',NULL,0,'Chooses D: Implicit memory (classically conditioned)',1,0);
INSERT INTO rubric_criterion VALUES(21726,'psych34a2-brm-1',NULL,0,'Chooses C: Hippocampus',1,0);
INSERT INTO rubric_criterion VALUES(21727,'psych34a2-brm-2',NULL,0,'Chooses B: attaching emotional significance to memories, especially fear-related, and enhancing their consolidation',1,0);
INSERT INTO rubric_criterion VALUES(21728,'psych34a2-brm-3',NULL,0,'Chooses C: Explicit memory formation depends on the hippocampus, while procedural learning does not',1,0);
INSERT INTO rubric_criterion VALUES(21729,'psych34a2-brm-4',NULL,0,'Chooses A: Neocortex: long-term storage of explicit memories',1,0);
INSERT INTO rubric_criterion VALUES(21730,'psych34a2-brm-5',NULL,0,'Chooses D: Amygdala',1,0);
INSERT INTO rubric_criterion VALUES(21731,'vce-psych34-br-c1',NULL,0,'Chooses A: The hippocampus is needed to consolidate explicit memories, while procedural skills rely on other regions',1,0);
INSERT INTO rubric_criterion VALUES(21732,'psych34a2-ama-1',NULL,0,'Chooses B: memory of personal life experiences and personal knowledge about oneself',1,0);
INSERT INTO rubric_criterion VALUES(21733,'psych34a2-ama-2',NULL,0,'Chooses B: a condition in which a person cannot voluntarily form mental images',1,0);
INSERT INTO rubric_criterion VALUES(21734,'psych34a2-ama-3',NULL,0,'Chooses D: contain fewer sensory and visual details, although they may still recall facts about the events',1,0);
INSERT INTO rubric_criterion VALUES(21735,'psych34a2-ama-4',NULL,0,'Chooses A: aphantasia',1,0);
INSERT INTO rubric_criterion VALUES(21736,'psych34a2-ama-5',NULL,0,'Chooses C: Visual imagery may enrich the vividness of recalled episodes but is not required to remember what happened',1,0);
INSERT INTO rubric_criterion VALUES(21737,'vce-psych34-am-c1',NULL,0,'Chooses B: They cannot voluntarily form mental images, which help people re-experience past events',1,0);
INSERT INTO rubric_criterion VALUES(21738,'psych34a2-alz-1',NULL,0,'Chooses D: a progressive neurodegenerative disease resulting in loss of neurons and increasing memory and cognitive impairment',1,0);
INSERT INTO rubric_criterion VALUES(21739,'psych34a2-alz-2',NULL,0,'Chooses B: Build-up of amyloid plaques and neurofibrillary tangles, with neuron loss',1,0);
INSERT INTO rubric_criterion VALUES(21740,'psych34a2-alz-3',NULL,0,'Chooses D: Difficulty forming new episodic memories, such as forgetting recent conversations',1,0);
INSERT INTO rubric_criterion VALUES(21741,'psych34a2-alz-4',NULL,0,'Chooses A: Procedural memory depends on regions such as the cerebellum that are affected later than the hippocampus and neocortex',1,0);
INSERT INTO rubric_criterion VALUES(21742,'psych34a2-alz-5',NULL,0,'Chooses C: decline in language, reasoning and stored explicit memories',1,0);
INSERT INTO rubric_criterion VALUES(21743,'vce-psych34-ad-c1',NULL,0,'Chooses C: Amyloid plaques form between neurons; neurofibrillary tangles of tau form inside neurons',1,0);
INSERT INTO rubric_criterion VALUES(21744,'psych34a2-mne-1',NULL,0,'Chooses A: an acrostic',1,0);
INSERT INTO rubric_criterion VALUES(21745,'psych34a2-mne-2',NULL,0,'Chooses C: Imagining placing each item on a shopping list at a distinct location along a familiar route through your house',1,0);
