INSERT INTO rubric_criterion VALUES(21750,'psych34a2-cms-1',NULL,0,'Chooses B: the level of awareness a person has of their internal states and external environment',1,0);
INSERT INTO rubric_criterion VALUES(21751,'psych34a2-cms-2',NULL,0,'Chooses D: Electroencephalograph (EEG)',1,0);
