INSERT INTO rubric_criterion VALUES(21753,'psych34a2-cms-4',NULL,0,'Chooses D: A participant''s description of their dreams or sleepiness after waking',1,0);
INSERT INTO rubric_criterion VALUES(21754,'psych34a2-cms-5',NULL,0,'Chooses A: It allows observation of behaviours such as body movements and sleep talking without the need for the participant''s report',1,0);
