INSERT INTO rubric_criterion VALUES(21756,'psych34a2-nrs-1',NULL,0,'Chooses B: Fast, low-amplitude brain waves, rapid eye movements and temporary muscle paralysis',1,0);
INSERT INTO rubric_criterion VALUES(21757,'psych34a2-nrs-2',NULL,0,'Chooses C: Large amplitude, low frequency delta waves',1,0);
