INSERT INTO rubric_criterion VALUES(21759,'psych34a2-nrs-4',NULL,0,'Chooses D: It increases, with REM periods becoming longer toward morning',1,0);
INSERT INTO rubric_criterion VALUES(21760,'psych34a2-nrs-5',NULL,0,'Chooses D: report that they have been dreaming vividly',1,0);
