INSERT INTO rubric_criterion VALUES(21762,'psych34a2-cur-1',NULL,0,'Chooses C: lasts about 24 hours',1,0);
INSERT INTO rubric_criterion VALUES(21763,'psych34a2-cur-2',NULL,0,'Chooses A: The suprachiasmatic nucleus (SCN)',1,0);
INSERT INTO rubric_criterion VALUES(21764,'psych34a2-cur-3',NULL,0,'Chooses B: a hormone secreted by the pineal gland that promotes sleepiness, with levels rising in darkness',1,0);
INSERT INTO rubric_criterion VALUES(21765,'psych34a2-cur-4',NULL,0,'Chooses A: The 90-minute cycle through stages of sleep',1,0);
INSERT INTO rubric_criterion VALUES(21766,'psych34a2-cur-5',NULL,0,'Chooses D: Their internal clock is mismatched with external light-dark cues, causing reduced sleep quality and alertness at work',1,0);
INSERT INTO rubric_criterion VALUES(21767,'vce-psych34-cr-c1',NULL,0,'Chooses A: Sleep cycles (about 90 minutes) are ultradian; about 5 occur within the circadian sleep–wake cycle',1,0);
INSERT INTO rubric_criterion VALUES(21768,'psych34a2-sal-1',NULL,0,'Chooses C: sleep for more hours and spend a greater proportion of sleep in REM sleep',1,0);
