INSERT INTO rubric_criterion VALUES(21770,'psych34a2-sal-3',NULL,0,'Chooses C: A delay in the release of melatonin shifts their circadian rhythm later',1,0);
INSERT INTO rubric_criterion VALUES(21771,'psych34a2-sal-4',NULL,0,'Chooses B: 7 to 9 hours',1,0);
INSERT INTO rubric_criterion VALUES(21772,'psych34a2-sal-5',NULL,0,'Chooses D: The proportion of sleep spent in REM is highest in infancy and declines to about 20 to 25% in adulthood',1,0);
INSERT INTO rubric_criterion VALUES(21773,'vce-psych34-sl-c1',NULL,0,'Chooses A: Melatonin is released later in the evening, delaying their sleep–wake cycle',1,0);
INSERT INTO rubric_criterion VALUES(21774,'psych34a3-sd-1',NULL,0,'Chooses B: A brief, involuntary episode of sleep lasting a few seconds, during which the person may appear awake',1,0);
INSERT INTO rubric_criterion VALUES(21775,'psych34a3-sd-2',NULL,0,'Chooses A: slower, similar to the impairment seen with a blood alcohol concentration of about 0.10%',1,0);
INSERT INTO rubric_criterion VALUES(21776,'psych34a3-sd-3',NULL,0,'Chooses B: Increased irritability and mood swings',1,0);
INSERT INTO rubric_criterion VALUES(21777,'psych34a3-sd-4',NULL,0,'Chooses C: Total sleep deprivation involves no sleep for a period of time, while partial involves reduced sleep or sleep that is restricted or fragmented',1,0);
INSERT INTO rubric_criterion VALUES(21778,'psych34a3-sd-5',NULL,0,'Chooses D: cognitive functioning',1,0);
INSERT INTO rubric_criterion VALUES(21779,'vce-psych34-sd-c1',NULL,0,'Chooses A: 0.05%',1,0);
INSERT INTO rubric_criterion VALUES(21780,'psych34a3-crsd-1',NULL,0,'Chooses B: a persistent inability to fall asleep until very late at night and difficulty waking at socially required times, because the sleep-wake cycle is shifted later',1,0);
INSERT INTO rubric_criterion VALUES(21781,'psych34a3-crsd-2',NULL,0,'Chooses D: Bright light therapy',1,0);
INSERT INTO rubric_criterion VALUES(21782,'psych34a3-crsd-3',NULL,0,'Chooses A: Her work schedule conflicts with her circadian rhythm, which is synchronised by light and other zeitgebers',1,0);
INSERT INTO rubric_criterion VALUES(21783,'psych34a3-crsd-4',NULL,0,'Chooses C: it is a hormone secreted by the pineal gland that signals darkness and promotes sleepiness, so timed doses can shift the sleep-wake cycle',1,0);
INSERT INTO rubric_criterion VALUES(21784,'psych34a3-crsd-5',NULL,0,'Chooses D: It is caused by a mismatch between her internal body clock and the new local time, so her zeitgebers are out of step with her circadian rhythm',1,0);
