INSERT INTO rubric_criterion VALUES(21787,'psych34a3-shz-2',NULL,0,'Chooses A: Keeping a consistent bedtime and wake time, including on weekends',1,0);
INSERT INTO rubric_criterion VALUES(21788,'psych34a3-shz-3',NULL,0,'Chooses C: Light',1,0);
