INSERT INTO rubric_criterion VALUES(21790,'psych34a3-shz-5',NULL,0,'Chooses C: A decrease in the mean sleep onset latency',1,0);
INSERT INTO rubric_criterion VALUES(21791,'vce-psych34-sh-c1',NULL,0,'Chooses C: Blue light acts as a zeitgeber, signalling the SCN to suppress melatonin release',1,0);
INSERT INTO rubric_criterion VALUES(21792,'psych34a3-mw-1',NULL,0,'Chooses A: A state in which a person can realise their abilities, cope with normal stressors, work productively and contribute to their community',1,0);
INSERT INTO rubric_criterion VALUES(21793,'psych34a3-mw-2',NULL,0,'Chooses B: at the mentally healthy / good mental wellbeing end',1,0);
INSERT INTO rubric_criterion VALUES(21794,'psych34a3-mw-3',NULL,0,'Chooses A: A mental health problem interferes with a person''s thoughts, feelings or behaviour but is generally less severe and shorter lasting than a mental disorder, which meets diagnostic criteria and persists over time',1,0);
INSERT INTO rubric_criterion VALUES(21795,'psych34a3-mw-4',NULL,0,'Chooses C: a mental health problem',1,0);
INSERT INTO rubric_criterion VALUES(21796,'psych34a3-mw-5',NULL,0,'Chooses A: People''s mental health can vary in degree and shift position over time in response to internal and external factors',1,0);
INSERT INTO rubric_criterion VALUES(21797,'vce-psych34-mw-c1',NULL,0,'Chooses B: A person''s position can move over time, and someone with a disorder can still have high wellbeing',1,0);
INSERT INTO rubric_criterion VALUES(21798,'psych34a3-sew-1',NULL,0,'Chooses A: A holistic concept that includes connection to body, mind and emotions, family and kinship, community, culture, Country, and spirituality and ancestors',1,0);
INSERT INTO rubric_criterion VALUES(21799,'psych34a3-sew-2',NULL,0,'Chooses C: Taking part in cultural ceremonies and caring for land that holds ancestral and spiritual significance',1,0);
INSERT INTO rubric_criterion VALUES(21800,'psych34a3-sew-3',NULL,0,'Chooses A: views wellbeing as shaped by the person''s connections to family, community, culture and Country, as well as individual factors',1,0);
INSERT INTO rubric_criterion VALUES(21801,'psych34a3-sew-4',NULL,0,'Chooses C: Racism and discrimination',1,0);
INSERT INTO rubric_criterion VALUES(21802,'psych34a3-sew-5',NULL,0,'Chooses A: Spending time with extended family and fulfilling kinship obligations',1,0);
INSERT INTO rubric_criterion VALUES(21803,'vce-psych34-se-c1',NULL,0,'Chooses C: Connection to personal wealth',1,0);
INSERT INTO rubric_criterion VALUES(21804,'psych34a3-sp-1',NULL,0,'Chooses A: Excessive, persistent fear of a specific object or situation that is out of proportion to the actual danger and leads to avoidance',1,0);
INSERT INTO rubric_criterion VALUES(21805,'psych34a3-sp-2',NULL,0,'Chooses C: Dysfunction in GABA, an inhibitory neurotransmitter, can reduce its ability to calm the fear response, so anxiety is less regulated',1,0);
INSERT INTO rubric_criterion VALUES(21806,'psych34a3-sp-3',NULL,0,'Chooses B: conditioned stimulus',1,0);
INSERT INTO rubric_criterion VALUES(21807,'psych34a3-sp-4',NULL,0,'Chooses B: Observing a parent react with extreme fear to spiders',1,0);
INSERT INTO rubric_criterion VALUES(21808,'psych34a3-sp-5',NULL,0,'Chooses A: It strengthens synaptic connections associated with the feared stimulus and fear response, making the fear memory more easily triggered',1,0);
INSERT INTO rubric_criterion VALUES(21809,'vce-psych34-pf-c1',NULL,0,'Chooses A: Operant conditioning: avoidance is negatively reinforced by the removal of anxiety',1,0);
INSERT INTO rubric_criterion VALUES(21810,'psych34a3-spi-1',NULL,0,'Chooses D: a gradual exposure to feared stimuli in a hierarchy from least to most feared while using relaxation to replace the fear response',1,0);
